(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("strabo-geography-4-e", [{"sp": "HDR", "t": "Γεωγραφικά (ΙΑʹ–ΙΔʹ)"}, {"sp": "HDR", "t": "Βιβλίον ΙΑʹ", "st": "11"}, {"sp": "N", "t": "τῇ δ’ Εὐρώπῃ συνεχής ἐστιν ἡ Ἀσία κατὰ τὸν Τάναϊν συνάπτουσα αὐτῇ· περὶ ταύτης οὖν ἐφεξῆς ῥητέον διελόντας φυσικοῖς τισιν ὅροις τοῦ σαφοῦς χάριν. ὅπερ οὖν Ἐρατοσθένης ἐφ’ ὅλης τῆς οἰκουμένης ἐποίησε, τοῦθ’ ἡμῖν ἐπὶ τῆς Ἀσίας ποιητέον.", "st": "11.1.1"}, {"sp": "N", "t": "ὁ γὰρ Ταῦρος μέσην πως διέζωκε ταύτην τὴν ἤπειρον ἀπὸ τῆς ἑσπέρας ἐπὶ τὴν ἕω τεταμένος, τὸ μὲν αὐτῆς ἀπολείπων πρὸς βορρᾶν τὸ δὲ μεσημβρινόν. καλοῦσι δὲ αὐτῶν οἱ Ἕλληνες τὸ μὲν ἐντὸς τοῦ Ταύρου τὸ δὲ ἐκτός. εἴρηται δὲ ταῦθ’ ἡμῖν καὶ πρότερον, ἀλλ’ εἰρήσθω καὶ νῦν ὑπομνήσεως χάριν.", "st": "11.1.2"}, {"sp": "N", "t": "πλάτος μὲν οὖν ἔχει τὸ ὄρος πολλαχοῦ καὶ τρισχιλίων σταδίων, μῆκος δ’ ὅσον καὶ τὸ τῆς Ἀσίας, τεττάρων που μυριάδων καὶ πεντακισχιλίων, ἀπὸ τῆς Ῥοδίων περαίας ἐπὶ τὰ ἄκρα τῆς Ἰνδικῆς καὶ Σκυθίας πρὸς τὰς ἀνατολάς.", "st": "11.1.3"}, {"sp": "N", "t": "διῄρηται δ’ εἰς μέρη πολλὰ καὶ ὀνόματα περιγραφαῖς καὶ μείζοσι καὶ ἐλάττοσιν ἀφωρισμένα. ἐπεὶ δ’ ἐν τῷ τοσούτῳ πλάτει τοῦ ὄρους ἀπολαμβάνεταί τινα ἔθνη, τὰ μὲν ἀσημότερα τὰ δὲ καὶ παντελῶς γνώριμα (καθάπερ ἡ Παρθυαία καὶ Μηδία καὶ Ἀρμενία καὶ Καππαδοκῶν τινες καὶ Κίλικες καὶ Πισίδαι), τὰ μὲν πλεονάζοντα ἐν τοῖς προσβόρροις μέρεσιν ἐνταῦθα τακτέον, τὰ δ’ ἐν τοῖς νοτίοις εἰς τὰ νότια, καὶ τὰ ἐν μέσῳ δὲ τῶν ὀρῶν κείμενα διὰ τὰς τῶν ἀέρων ὁμοιότητας πρὸς βορρᾶν πως θετέον· ψυχροὶ γάρ εἰσιν, οἱ δὲ νότιοι θερμοί. καὶ τῶν ποταμῶν δὲ αἱ ῥύσεις ἐνθένδε ἰοῦσαι πᾶσαι σχεδόν τι εἰς τἀναντία αἱ μὲν εἰς τὰ βόρεια αἱ δ’ εἰς τὰ νότια μέρη (τά γε πρῶτα, κἂν ὕστερόν τινες ἐπιστρέφωσι πρὸς ἀνατολὰς ἢ δύσεις), ἔχουσί τι εὐφυὲς πρὸς τὸ τοῖς ὄρεσιν ὁρίοις χρῆσθαι κατὰ τὴν εἰς δύο μέρη διαίρεσιν τῆς Ἀσίας· καθάπερ καὶ ἡ θάλαττα ἡ ἐντὸς στηλῶν, ἐπ’ εὐθείας πως οὖσα ἡ πλείστη τοῖς ὄρεσι τούτοις, ἐπιτηδεία γεγένηται πρὸς τὸ δύο ποιεῖν ἠπείρους, τήν τε Εὐρώπην καὶ τὴν Λιβύην, ὅριον ἀμφοῖν οὖσα ἀξιόλογον.", "st": "11.1.4"}, {"sp": "N", "t": "τοῖς δὲ μεταβαίνουσιν ἀπὸ τῆς Εὐρώπης ἐπὶ τὴν Ἀσίαν ἐν τῇ γεωγραφίᾳ τὰ πρὸς βορρᾶν ἐστι πρῶτα τῆς εἰς δύο διαιρέσεως, ὥστε ἀπὸ τούτων ἀρκτέον. αὐτῶν δὲ τούτων πρῶτά ἐστι τὰ περὶ τὸν Τάναϊν, ὅνπερ τῆς Εὐρώπης καὶ τῆς Ἀσίας ὅριον ὑπεθέμεθα. ἔστι δὲ ταῦτα τρόπον τινὰ χερρονησίζοντα· περιέχεται γὰρ ἐκ μὲν τῆς ἑσπέρας τῷ ποταμῷ τῷ Τανάιδι καὶ τῇ Μαιώτιδι μέχρι τοῦ Βοσπόρου καὶ τῆς τοῦ Εὐξείνου παραλίας τῆς τελευτώσης εἰς τὴν Κολχίδα· ἐκ δὲ τῶν ἄρκτων τῷ Ὠκεανῷ μέχρι τοῦ στόματος τῆς Κασπίας θαλάττης· ἕωθεν δὲ αὐτῇ ταύτῃ τῇ θαλάττῃ μέχρι τῶν μεθορίων τῆς τε Ἀλβανίας καὶ τῆς Ἀρμενίας, καθ’ ἃ ὁ Κῦρος καὶ ὁ Ἀράξης ἐκδιδοῦσι ποταμοί, ῥέοντες ὁ μὲν διὰ τῆς Ἀρμενίας Κῦρος δὲ διὰ τῆς Ἰβηρίας καὶ τῆς Ἀλβανίας· ἐκ νότου δὲ τῇ ἀπὸ τῆς ἐκβολῆς τοῦ Κύρου μέχρι τῆς Κολχίδος, ὅσον τρισχιλίων οὔσῃ σταδίων ἀπὸ θαλάττης ἐπὶ θάλατταν, δι’ Ἀλβανῶν καὶ Ἰβήρων, ὥστε ἰσθμοῦ λόγον ἔχειν. οἱ δ’ ἐπὶ τοσοῦτον συναγαγόντες τὸν ἰσθμὸν ἐφ’ ὅσον Κλείταρχος, ἐπίκλυστον φήσας ἐξ ἑκατέρου τοῦ πελάγους, οὐδ’ ἂν λόγου ἀξιοῖντο. Ποσειδώνιος δὲ χιλίων καὶ πεντακοσίων εἴρηκε τὸν ἰσθμόν, ὅσον καὶ τὸν ἀπὸ Πηλουσίου ἰσθμὸν εἰς τὴν Ἐρυθράν. “δοκῶ δέ” φησί “μὴ πολὺ διαφέρειν μηδὲ τὸν ἀπὸ τῆς Μαιώτιδος εἰς τὸν Ὠκεανόν.”", "st": "11.1.5"}, {"sp": "N", "t": "οὐκ οἶδα δὲ πῶς ἄν τις περὶ τῶν ἀδήλων αὐτῷ πιστεύσειε μηδὲν εἰκὸς ἔχοντι εἰπεῖν περὶ αὐτῶν, ὅταν περὶ τῶν φανερῶν οὕτω παραλόγως λέγῃ, καὶ ταῦτα φίλος Πομπηίῳ γεγονὼς τῷ στρατεύσαντι ἐπὶ τοὺς Ἴβηρας καὶ τοὺς Ἀλβανοὺς μέχρι τῆς ἐφ’ ἑκάτερα θαλάττης τῆς τε Κασπίας καὶ τῆς Κολχικῆς. φασὶ γοῦν ἐν Ῥόδῳ γενόμενον τὸν Πομπήιον, ἡνίκα ἐπὶ τὸν λῃστρικὸν πόλεμον ἐξῆλθεν (εὐθὺς δ’ ἔμελλε καὶ ἐπὶ Μιθριδάτην ὁρμήσειν καὶ τὰ μέχρι τῆς Κασπίας ἔθνη), παρατυχεῖν διαλεγομένῳ τῷ Ποσειδωνίῳ, ἀπιόντα δ’ ἐρέσθαι εἴ τι προστάττει, τὸν δ’ εἰπεῖν<br>αἰὲν ἀριστεύειν καὶ ὑπείροχον ἔμμεναι ἄλλων.<br>προστίθει δὲ τούτοις ὅτι καὶ τὴν ἱστορίαν συνέγραψε τὴν περὶ αὐτόν. διὰ δὴ ταῦτα ἐχρῆν φροντίσαι τἀληθοῦς πλέον τι.", "st": "11.1.6"}, {"sp": "N", "t": "δεύτερον δ’ ἂν εἴη μέρος τὸ ὑπὲρ τῆς Ὑρκανίας θαλάττης, ἣν [καὶ] Κασπίαν καλοῦμεν, μέχρι τῶν κατ’ Ἰνδοὺς Σκυθῶν. τρίτον δὲ μέρος τὸ συνεχὲς τῷ λεχθέντι ἰσθμῷ καὶ τὰ ἑξῆς τούτῳ καὶ ταῖς Κασπίαις πύλαις, τῶν ἐντὸς τοῦ Ταύρου καὶ τῆς Εὐρώπης ἐγγυτάτω· ταῦτα δ’ ἐστὶ Μηδία καὶ Ἀρμενία καὶ Καππαδοκία καὶ τὰ μεταξύ. τέταρτον δ’ ἡ ἐντὸς Ἅλυος γῆ καὶ τὰ ἐν αὐτῷ τῷ Ταύρῳ καὶ ἐκτὸς ὅσα εἰς τὴν χερρόνησον ἐμπίπτει, ἣν ποιεῖ ὁ διείργων ἰσθμὸς τήν τε Ποντικὴν καὶ τὴν Κιλικίαν θάλατταν. τῶν δὲ ἄλλων τῶν ἔξω τοῦ Ταύρου τήν τε Ἰνδικὴν τίθεμεν καὶ τὴν Ἀριανὴν μέχρι τῶν ἐθνῶν τῶν καθηκόντων πρός τε τὴν κατὰ Πέρσας θάλατταν καὶ τὸν Ἀράβιον κόλπον καὶ τὸν Νεῖλον καὶ πρὸς τὸ Αἰγύπτιον πέλαγος καὶ τὸ Ἰσσικόν.", "st": "11.1.7"}, {"sp": "N", "t": "οὕτω δὲ διακειμένων τὸ πρῶτον μέρος οἰκοῦσιν ἐκ μὲν τῶν πρὸς ἄρκτον μερῶν καὶ τὸν Ὠκεανὸν Σκυθῶν τινὲς νομάδες καὶ ἁμάξοικοι, ἐνδοτέρω δὲ τούτων Σαρμάται, καὶ οὗτοι Σκύθαι, Ἄορσοι καὶ Σιρακοὶ μέχρι τῶν Καυκασίων ὀρῶν ἐπὶ μεσημβρίαν τείνοντες, οἱ μὲν νομάδες οἱ δὲ καὶ σκηνῖται καὶ γεωργοί, περὶ δὲ τὴν λίμνην Μαιῶται· πρὸς δὲ τῇ θαλάττῃ τοῦ Βοσπόρου τὰ κατὰ τὴν Ἀσίαν ἐστὶ καὶ ἡ Σινδική· μετὰ δὲ ταύτην Ἀχαιοὶ καὶ Ζυγοὶ καὶ Ἡνίοχοι Κερκέται τε καὶ Μακροπώγωνες. ὑπέρκειται δὲ τούτων καὶ τὰ τῶν Φθειροφάγων στενά· μετὰ δὲ τοὺς Ἡνιόχους ἡ Κολχὶς ὑπὸ τοῖς Καυκασίοις ὄρεσι κειμένη καὶ τοῖς Μοσχικοῖς. ἐπεὶ δ’ ὅριον ὑπόκειται τῆς Εὐρώπης καὶ τῆς Ἀσίας ὁ Τάναϊς ποταμός, ἐντεῦθεν ἀρξάμενοι τὰ καθ’ ἕκαστα ὑπογράψομεν.", "st": "11.2.1"}, {"sp": "N", "t": "φέρεται μὲν οὖν ἀπὸ τῶν ἀρκτικῶν μερῶν, οὐ μὴν ὡς ἂν κατὰ διάμετρον ἀντίρρους τῷ Νείλῳ, καθάπερ νομίζουσιν οἱ πολλοί, ἀλλὰ ἑωθινώτερος ἐκείνου, παραπλησίως ἐκείνῳ τὰς ἀρχὰς ἀδήλους ἔχων· ἀλλὰ τοῦ μὲν πολὺ τὸ φανερὸν χώραν διεξιόντος πᾶσαν εὐεπίμικτον καὶ μακροὺς ἀνάπλους ἔχοντος, τοῦ δὲ Τανάιδος τὰς μὲν ἐκβολὰς ἴσμεν (δύο δ’ εἰσὶν εἰς τὰ ἀρκτικώτατα μέρη τῆς Μαιώτιδος ἑξήκοντα σταδίους ἀλλήλων διέχουσαι), τοῦ δ’ ὑπὲρ τῶν ἐκβολῶν ὀλίγον τὸ γνώριμόν ἐστι διὰ τὰ ψύχη καὶ τὰς ἀπορίας τῆς χώρας, ἃς οἱ μὲν αὐτόχθονες δύνανται φέρειν σαρξὶ καὶ γάλακτι τρεφόμενοι νομαδικῶς, οἱ δ’ ἀλλοεθνεῖς οὐχ ὑπομένουσιν. ἄλλως τε οἱ νομάδες δυσεπίμικτοι τοῖς ἄλλοις ὄντες καὶ πλήθει καὶ βίᾳ διαφέροντες ἀποκεκλείκασιν εἰ καί τι πορεύσιμον τῆς χώρας ἐστὶν ἢ εἴ τινας τετύχηκεν ἀνάπλους ἔχων ὁ ποταμός. ἀπὸ δὲ τῆς αἰτίας ταύτης οἱ μὲν ὑπέλαβον τὰς πηγὰς ἔχειν αὐτὸν ἐν τοῖς Καυκασίοις ὄρεσι, πολὺν δ’ ἐνεχθέντα ἐπὶ τὰς ἄρκτους εἶτ’ ἀναστρέψαντα ἐκβάλλειν εἰς τὴν Μαιῶτιν (τούτοις δὲ ὁμοδοξεῖ καὶ Θεοφάνης ὁ Μιτυληναῖος), οἱ δ’ ἀπὸ τῶν ἄνω μερῶν τοῦ Ἴστρου φέρεσθαι· σημεῖον δὲ φέρουσιν οὐδὲν τῆς πόρρωθεν οὕτω ῥύσεως καὶ ἀπ’ ἄλλων κλιμάτων, ὥσπερ οὐ δυνατὸν ὂν καὶ ἐγγύθεν καὶ ἀπὸ τῶν ἄρκτων.", "st": "11.2.2"}, {"sp": "N", "t": "ἐπὶ δὲ τῷ ποταμῷ καὶ τῇ λίμνῃ πόλις ὁμώνυμος οἰκεῖται Τάναϊς, κτίσμα τῶν τὸν Βόσπορον ἐχόντων Ἑλλήνων. νεωστὶ μὲν οὖν ἐξεπόρθησεν αὐτὴν Πολέμων ὁ βασιλεὺς ἀπειθοῦσαν, ἦν δ’ ἐμπόριον κοινὸν τῶν τε Ἀσιανῶν καὶ τῶν Εὐρωπαίων νομάδων καὶ τῶν ἐκ τοῦ Βοσπόρου τὴν λίμνην πλεόντων, τῶν μὲν ἀνδράποδα ἀγόντων καὶ δέρματα καὶ εἴ τι ἄλλο τῶν νομαδικῶν, τῶν δ’ ἐσθῆτα καὶ οἶνον καὶ τἆλλα ὅσα τῆς ἡμέρου διαίτης οἰκεῖα ἀντιφορτιζομένων. πρόκειται δ’ ἐν ἑκατὸν σταδίοις τοῦ ἐμπορίου νῆσος Ἀλωπεκία, κατοικία μιγάδων ἀνθρώπων· ἔστι δὲ καὶ ἄλλα νησίδια πλησίον ἐν τῇ λίμνῃ. διέχει δὲ τοῦ στόματος τῆς Μαιώτιδος εὐθυπλοοῦσιν ἐπὶ τὰ βόρεια δισχιλίους καὶ διακοσίους σταδίους ὁ Τάναϊς, οὐ πολὺ δὲ πλείους εἰσὶ παραλεγομένῳ τὴν γῆν.", "st": "11.2.3"}, {"sp": "N", "t": "ἐν δὲ τῷ παράπλῳ τῷ παρὰ γῆν πρῶτον μέν ἐστιν ἀπὸ τοῦ Τανάιδος προϊοῦσιν ἐν ὀκτακοσίοις σταδίοις ὁ μέγας καλούμενος Ῥομβίτης, ἐν ᾧ τὰ πλεῖστα ἁλιεύματα τῶν εἰς ταριχείας ἰχθύων· ἔπειτα ἐν ἄλλοις ὀκτακοσίοις ὁ ἐλάττων Ῥομβίτης [καὶ] ἄκρα ἔχουσα καὶ αὐτὴ ἁλιείας ἐλάττους· ἔχουσι δὲ οἱ μὲν … πρότερον νησία ὁρμητήρια, οἱ δ’ ἐν τῷ μικρῷ Ῥομβίτῃ αὐτοί εἰσιν οἱ Μαιῶται ἐργαζόμενοι· οἰκοῦσι γὰρ ἐν τῷ παράπλῳ τούτω παντὶ οἱ Μαιῶται, γεωργοὶ μὲν οὐχ ἧττον δὲ τῶν νομάδων πολεμισταί. διῄρηνται δὲ εἰς ἔθνη πλείω τὰ μὲν πλησίον τοῦ Τανάιδος ἀγριώτερα, τὰ δὲ συνάπτοντα τῷ Βοσπόρῳ χειροήθη μᾶλλον. ἀπὸ δὲ τοῦ μικροῦ Ῥομβίτου στάδιοί εἰσιν ἑξακόσιοι ἐπὶ Τυράμβην καὶ τὸν Ἀντικείτην ποταμόν· εἶθ’ ἑκατὸν καὶ εἴκοσιν ἐπὶ τὴν κώμην τὴν Κιμμερικήν, ἥτις ἐστὶν ἀφετήριον τοῖς τὴν λίμνην πλέουσιν· ἐν δὲ τῷ παράπλῳ τούτῳ καὶ σκοπαί τινες λέγονται Κλαζομενίων.", "st": "11.2.4"}, {"sp": "N", "t": "τὸ δὲ Κιμμερικὸν πόλις ἦν πρότερον ἐπὶ χερρονήσου ἱδρυμένη, τὸν ἰσθμὸν τάφρῳ καὶ χώματι κλείουσα· ἐκέκτηντο δ’ οἱ Κιμμέριοι μεγάλην ποτὲ ἐν τῷ Βοσπόρῳ δύναμιν, διόπερ καὶ Κιμμερικὸς Βόσπορος ὠνομάσθη. οὗτοι δ’ εἰσὶν οἱ τοὺς τὴν μεσόγαιαν οἰκοῦντας ἐν τοῖς δεξιοῖς μέρεσι τοῦ Πόντου μέχρι Ἰωνίας ἐπιδραμόντες. τούτους μὲν οὖν ἐξήλασαν ἐκ τῶν τόπων Σκύθαι, τοὺς δὲ Σκύθας Ἕλληνες οἱ Παντικάπαιον καὶ τὰς ἄλλας οἰκίσαντες πόλεις τὰς ἐν Βοσπόρῳ.", "st": "11.2.5"}, {"sp": "N", "t": "εἶτ’ ἐπὶ τὴν Ἀχίλλειον κώμην εἴκοσιν, ἐν ᾗ τὸ Ἀχιλλέως ἱερόν· ἐνταῦθα δ’ ἐστὶν ὁ στενώτατος πορθμὸς τοῦ στόματος τῆς Μαιώτιδος ὅσον εἴκοσι σταδίων ἢ πλειόνων, ἔχων ἐν τῇ περαίᾳ κώμην τὸ Μυρμήκιον (πλησίον δ’ ἐστὶ τοῦ Ἡρακλείου) καὶ τὸ Παρθένιον.", "st": "11.2.6"}, {"sp": "N", "t": "ἐντεῦθεν δ’ ἐπὶ τὸ Σατύρου μνῆμα ἐνενήκοντα στάδιοι· τοῦτο δ’ ἐστὶν ἐπ’ ἄκρας τινὸς χωστὸν ἀνδρὸς τῶν ἐπιφανῶς δυναστευσάντων τοῦ Βοσπόρου.", "st": "11.2.7"}, {"sp": "N", "t": "πλησίον δὲ κώμη Πατραεύς, ἀφ’ ἧς ἐπὶ κώμην Κοροκονδάμην ἑκατὸν τριάκοντα· αὕτη δ’ ἐστὶ τοῦ Κιμμερικοῦ καλουμένου Βοσπόρου πέρας. καλεῖται δὲ οὕτως ὁ στενωπὸς ἐπὶ τοῦ στόματος τῆς Μαιώτιδος ἀπὸ τῶν κατὰ τὸ Ἀχίλλειον καὶ τὸ Μυρμήκιον στενῶν διατείνων μέχρι πρὸς τὴν Κοροκονδάμην καὶ τὸ ἀντικείμενον αὐτῇ κώμιον τῆς Παντικαπαίων γῆς ὄνομα Ἄκραν ἑβδομήκοντα σταδίων διειργόμενον πορθμῷ· μέχρι γὰρ δεῦρο καὶ ὁ κρύσταλλος διατείνει, πηττομένης τῆς Μαιώτιδος κατὰ τοὺς κρυμοὺς ὥστε πεζεύεσθαι. ἅπας δ’ ἐστὶν εὐλίμενος ὁ στενωπὸς οὗτος.", "st": "11.2.8"}, {"sp": "N", "t": "ὑπέρκειται δὲ τῆς Κοροκονδάμης εὐμεγέθης λίμνη, ἣν καλοῦσιν ἀπ’ αὐτῆς Κοροκονδαμῖτιν· ἐκδίδωσι δ’ ἀπὸ δέκα σταδίων τῆς κώμης εἰς τὴν θάλατταν· ἐμβάλλει δὲ εἰς τὴν λίμνην ἀπορρώξ τις τοῦ Ἀντικείτου ποταμοῦ, καὶ ποιεῖ νῆσον περίκλυστόν τινα ταύτῃ τε τῇ λίμνῃ καὶ τῇ Μαιώτιδι καὶ τῷ ποταμῷ. τινὲς δὲ καὶ τοῦτον τὸν ποταμὸν Ὕπανιν προσαγορεύουσι, καθάπερ καὶ τὸν πρὸς τῷ Βορυσθένει.", "st": "11.2.9"}, {"sp": "N", "t": "εἰσπλεύσαντι δ’ εἰς τὴν Κοροκονδαμῖτιν ἥ τε Φαναγόρειά ἐστι πόλις ἀξιόλογος καὶ Κῆποι καὶ Ἑρμώνασσα καὶ τὸ Ἀπάτουρον τὸ τῆς Ἀφροδίτης ἱερόν· ὧν ἡ Φαναγόρεια καὶ οἱ Κῆποι κατὰ τὴν λεχθεῖσαν νῆσον ἵδρυνται εἰσπλέοντι ἐν ἀριστερᾷ, αἱ δὲ λοιπαὶ πόλεις ἐν δεξιᾷ πέραν Ὑπάνιος ἐν τῇ Σινδικῇ. ἔστι δὲ καὶ Γοργιπία ἐν τῇ Σινδικῇ, τὸ βασίλειον τῶν Σινδῶν πλησίον θαλάττης, καὶ Ἀβοράκη. τοῖς δὲ τοῦ Βοσπόρου δυνάσταις ὑπήκοοι ὄντες ἅπαντες Βοσπορανοὶ καλοῦνται· καὶ ἔστι τῶν μὲν Εὐρωπαίων Βοσπορανῶν μητρόπολις τὸ Παντικάπαιον, τῶν δ’ Ἀσιανῶν τὸ Φαναγόρειον (καλεῖται γὰρ καὶ οὕτως ἡ πόλις), καὶ δοκεῖ τῶν μὲν ἐκ τῆς Μαιώτιδος καὶ τῆς ὑπερκειμένης βαρβάρου κατακομιζομένων ἐμπόριον εἶναι τὰ Φαναγόρεια, τῶν δ’ ἐκ τῆς θαλάττης ἀναφερομένων ἐκεῖσε τὸ Παντικάπαιον. ἔστι δὲ καὶ ἐν τῇ Φαναγορείᾳ τῆς Ἀφροδίτης ἱερὸν ἐπίσημον τῆς Ἀπατούρου· ἐτυμολογοῦσι δὲ τὸ ἐπίθετον τῆς θεοῦ μῦθόν τινα προστησάμενοι, ὡς ἐπιθεμένων ἐνταῦθα τῇ θεῷ τῶν γιγάντων ἐπικαλεσαμένη τὸν Ἡρακλέα κρύψειεν ἐν κευθμῶνί τινι, εἶτα τῶν γιγάντων ἕκαστον δεχομένη καθ’ ἕνα τῷ Ἡρακλεῖ παραδιδοίη δολοφονεῖν ἐξ ἀπάτης.", "st": "11.2.10"}, {"sp": "N", "t": "τῶν Μαιωτῶν δ’ εἰσὶν αὐτοί τε οἱ Σινδοὶ καὶ Δανδάριοι καὶ Τορέται καὶ Ἄγροι καὶ Ἀρρηχοί, ἔτι δὲ Τάρπητες Ὀβιδιακηνοὶ Σιττακηνοὶ Δόσκοι, ἄλλοι πλείους· τούτων δ’ εἰσὶ καὶ οἱ Ἀσπουργιανοὶ μεταξὺ Φαναγορείας οἰκοῦντες καὶ Γοργιπίας ἐν πεντακοσίοις σταδίοις, οἷς ἐπιθέμενος Πολέμων ὁ βασιλεὺς ἐπὶ προσποιήσει φιλίας οὐ λαθὼν ἀντεστρατηγήθη καὶ ζωγρίᾳ ληφθεὶς ἀπέθανε. τῶν τε συμπάντων Μαιωτῶν τῶν Ἀσιανῶν οἱ μὲν ὑπήκουον τῶν τὸ ἐμπόριον ἐχόντων τὸ ἐν τῷ Τανάιδι οἱ δὲ τῶν Βοσπορανῶν· τοτὲ δ’ ἀφίσταντο ἄλλοτ’ ἄλλοι. πολλάκις δ’ οἱ τῶν Βοσπορανῶν ἡγεμόνες καὶ τὰ μέχρι τοῦ Τανάιδος κατεῖχον καὶ μάλιστα οἱ ὕστατοι, Φαρνάκης καὶ Ἄσανδρος καὶ Πολέμων. Φαρνάκης δέ ποτε καὶ τὸν Ὕπανιν τοῖς Δανδαρίοις ἐπαγαγεῖν λέγεται διά τινος παλαιᾶς διώρυγος ἀνακαθάρας αὐτὴν [καὶ] κατακλύσαι τὴν χώραν.", "st": "11.2.11"}, {"sp": "N", "t": "μετὰ δὲ τὴν Σινδικὴν καὶ τὴν Γοργιπίαν ἐπὶ τῇ θαλάττῃ ἡ τῶν Ἀχαιῶν καὶ Ζυγῶν καὶ Ἡνιόχων παραλία τὸ πλέον ἀλίμενος καὶ ὀρεινή, τοῦ Καυκάσου μέρος οὖσα. ζῶσι δὲ ἀπὸ τῶν κατὰ θάλατταν λῃστηρίων, ἀκάτια ἔχοντες λεπτὰ στενὰ καὶ κοῦφα, ὅσον ἀνθρώπους πέντε καὶ εἴκοσι δεχόμενα, σπάνιον δὲ τριάκοντα δέξασθαι τοὺς πάντας δυνάμενα· καλοῦσι δ’ αὐτὰ οἱ Ἕλληνες καμάρας. φασὶ δ’ ἀπὸ τῆς Ἰάσονος στρατιᾶς τοὺς μὲν Φθιώτας Ἀχαιοὺς τὴν ἐνθάδε Ἀχαΐαν οἰκίσαι, Λάκωνας δὲ τὴν Ἡνιοχίαν, ὧν ἦρχον Κρέκας καὶ Ἀμφίστρατος οἱ τῶν Διοσκούρων ἡνίοχοι, καὶ τοὺς Ἡνιόχους ἀπὸ τούτων εἰκὸς ὠνομάσθαι. τῶν δ’ οὖν καμαρῶν στόλους κατασκευαζόμενοι καὶ ἐπιπλέοντες τοτὲ μὲν ταῖς ὁλκάσι τοτὲ δὲ χώρᾳ τινὶ ἢ καὶ πόλει θαλαττοκρατοῦσι. προσλαμβάνουσι δ’ ἔσθ’ ὅτε καὶ οἱ τὸν Βόσπορον ἔχοντες ὑφόρμους χορηγοῦντες καὶ ἀγορὰν καὶ διάθεσιν τῶν ἁρπαζομένων· ἐπανιόντες δὲ εἰς τὰ οἰκεῖα χωρία, ναυλοχεῖν οὐκ ἔχοντες, ἀναθέμενοι τοῖς ὤμοις τὰς καμάρας ἀναφέρουσιν ἐπὶ τοὺς δρυμοὺς ἐν οἷσπερ καὶ οἰκοῦσι, λυπρὰν ἀροῦντες γῆν· καταφέρουσι δὲ πάλιν ὅταν ᾖ καιρὸς τοῦ πλεῖν. τὸ δ’ αὐτὸ ποιοῦσι καὶ ἐν τῇ ἀλλοτρίᾳ γνώριμα ἔχοντες ὑλώδη χωρία, ἐν οἷς ἀποκρύψαντες τὰς καμάρας αὐτοὶ πλανῶνται πεζῇ νύκτωρ καὶ μεθ’ ἡμέραν ἀνδραποδισμοῦ χάριν. ἃ δ’ ἂν λάβωσιν ἐπίλυτρα ποιοῦσι ῥᾳδίως μετὰ τοὺς ἀνάπλους μηνύοντες τοῖς ἀπολέσασιν. ἐν μὲν οὖν τοῖς δυναστευομένοις τόποις ἐστί τις βοήθεια ἐκ τῶν ἡγεμόνων τοῖς ἀδικουμένοις· ἀντεπιτίθενται γὰρ πολλάκις καὶ κατάγουσιν αὐτάνδρους τὰς καμάρας· ἡ δ’ ὑπὸ Ῥωμαίοις ἀβοηθητοτέρα ἐστὶ διὰ τὴν ὀλιγωρίαν τῶν πεμπομένων.", "st": "11.2.12"}, {"sp": "N", "t": "τοιοῦτος μὲν ὁ τούτων βίος· δυναστεύονται δὲ καὶ οὗτοι ὑπὸ τῶν καλουμένων Σκηπτούχων; καὶ αὐτοὶ δὲ οὗτοι ὑπὸ τυράννοις ἢ βασιλεῦσίν εἰσιν. οἱ γοῦν Ἡνίοχοι τέτταρας εἶχον βασιλέας, ἡνίκα Μιθριδάτης ὁ Εὐπάτωρ φεύγων ἐκ τῆς προγονικῆς εἰς Βόσπορον διῄει τὴν χώραν αὐτῶν· καὶ αὕτη μὲν ἦν πορεύσιμος αὐτῷ, τῆς δὲ τῶν Ζυγῶν ἀπογνοὺς διά τε δυσχερείας καὶ ἀγριότητας τῇ παραλίᾳ χαλεπῶς ᾔει, τὰ πολλὰ ἐμβαίνων ἐπὶ τὴν θάλατταν, ἕως ἐπὶ τὴν τῶν Ἀχαιῶν ἧκε· καὶ προσλαβόντων τούτων ἐξετέλεσε τὴν ὁδὸν τὴν ἐκ Φάσιδος οὐ πολὺ τῶν τετρακισχιλίων λείπουσαν σταδίων.", "st": "11.2.13"}, {"sp": "N", "t": "εὐθὺς δ’ οὖν ἀπὸ τῆς Κοροκονδάμης πρὸς ἕω μὲν ὁ πλοῦς ἐστιν. ἐν δὲ σταδίοις ἑκατὸν ὀγδοήκοντα ὁ Σινδικός ἐστι λιμὴν καὶ πόλις, εἶτα ἐν τετρακοσίοις τὰ καλούμενα Βατὰ κώμη καὶ λιμήν, καθ’ ὃ μάλιστα ἀντικεῖσθαι δοκεῖ πρὸς νότον ἡ Σινώπη ταύτῃ τῇ παραλίᾳ, καθάπερ ἡ Κάραμβις εἴρηται τοῦ Κριοῦ μετώπῳ· ἀπὸ δὲ τῶν Βατῶν ὁ μὲν Ἀρτεμίδωρος τὴν Κερκετῶν λέγει παραλίαν ὑφόρμους ἔχουσαν καὶ κώμας ὅσον ἐπὶ σταδίους ὀκτακοσίους καὶ πεντήκοντα, εἶτα τὴν τῶν Ἀχαιῶν σταδίων πεντακοσίων, εἶτα τὴν τῶν Ἡνιόχων χιλίων, εἶτα τὸν Πιτυοῦντα τὸν μέγαν τριακοσίων ἑξήκοντα μέχρι Διοσκουριάδος· οἱ δὲ τὰ Μιθριδατικὰ συγγράψαντες, οἷς μᾶλλον προσεκτέον, Ἀχαιοὺς λέγουσι πρώτους, εἶτα Ζυγούς, εἶτα Ἡνιόχους, εἶτα Κερκέτας καὶ Μόσχους καὶ Κόλχους καὶ τοὺς ὑπὲρ τούτων Φθειροφάγους καὶ Σοάνας καὶ ἄλλα μικρὰ ἔθνη τὰ περὶ τὸν Καύκασον. κατ’ ἀρχὰς μὲν οὖν ἡ παραλία, καθάπερ εἶπον, ἐπὶ τὴν ἕω τείνει καὶ βλέπει πρὸς νότον, ἀπὸ δὲ τῶν Βατῶν ἐπιστροφὴν λαμβάνει κατὰ μικρόν, εἶτ’ ἀντιπρόσωπος γίνεται τῇ δύσει καὶ τελευτᾷ πρὸς τὸν Πιτυοῦντα καὶ τὴν Διοσκουριάδα· ταῦτα γὰρ τὰ χωρία τῆς Κολχίδος συνάπτει τῇ λεχθείσῃ παραλίᾳ. μετὰ δὲ τὴν Διοσκουριάδα ἡ λοιπὴ τῆς Κολχίδος ἐστὶ παραλία καὶ ἡ συνεχὴς Τραπεζοῦς καμπὴν ἀξιόλογον ποιήσασα, εἶτα εἰς εὐθεῖαν ταθεῖσά πως πλευρὰν τὴν τὰ δεξιὰ τοῦ Πόντου ποιοῦσαν τὰ βλέποντα πρὸς ἄρκτον. ἅπασα δ’ ἡ τῶν Ἀχαιῶν καὶ τῶν ἄλλων παραλία μέχρι Διοσκουριάδος καὶ τῶν ἐπ’ εὐθείας πρὸς νότον ἐν τῇ μεσογαίᾳ τόπων ὑποπέπτωκε τῷ Καυκάσῳ.", "st": "11.2.14"}, {"sp": "N", "t": "ἔστι δ’ ὄρος τοῦτο ὑπερκείμενον τοῦ πελάγους ἑκατέρου τοῦ τε Ποντικοῦ καὶ τοῦ Κασπίου, διατειχίζον τὸν ἰσθμὸν τὸν διείργοντα αὐτά. ἀφορίζει δὲ πρὸς νότον μὲν τήν τε Ἀλβανίαν καὶ τὴν Ἰβηρίαν, πρὸς ἄρκτον δὲ τὰ τῶν Σαρματῶν πεδία· εὔδενδρον δ’ ἐστὶν ὕλῃ παντοδαπῇ τῇ τε ἄλλῃ καὶ τῇ ναυπηγησίμῳ. φησὶ δ’ Ἐρατοσθένης ὑπὸ τῶν ἐπιχωρίων καλεῖσθαι Κάσπιον τὸν Καύκασον, ἴσως ἀπὸ τῶν Κασπίων παρονομασθέντα. ἀγκῶνες δέ τινες αὐτοῦ προπίπτουσιν ἐπὶ τὴν μεσημβρίαν, οἳ τήν τε Ἰβηρίαν περιλαμβάνουσι μέσην καὶ τοῖς Ἀρμενίων ὄρεσι συνάπτουσι καὶ τοῖς Μοσχικοῖς καλουμένοις, ἔτι δὲ τῷ Σκυδίσῃ καὶ τῷ Παρυάδρῃ· ταῦτα δ’ ἐστὶ μέρη τοῦ Ταύρου πάντα τοῦ ποιοῦντος τὸ νότιον τῆς Ἀρμενίας πλευρόν, ἀπερρωγότα πως ἐκεῖθεν πρὸς ἄρκτον καὶ προσπίπτοντα μέχρι τοῦ Καυκάσου καὶ τῆς τοῦ Εὐξείνου παραλίας τῆς ἐπὶ Θεμίσκυραν διατεινούσης ἀπὸ τῆς Κολχίδος.", "st": "11.2.15"}, {"sp": "N", "t": "ἡ δ’ οὖν Διοσκουριὰς ἐν κόλπῳ τοιούτῳ κειμένη καὶ τὸ ἑωθινώτατον σημεῖον ἐπέχουσα τοῦ σύμπαντος πελάγους, μυχός τε τοῦ Εὐξείνου λέγεται καὶ ἔσχατος πλοῦς· τό τε παροιμιακῶς λεχθὲν οὕτω δεῖ δέξασθαι<br>εἰς Φᾶσιν ἔνθα ναυσὶν ἔσχατος δρόμος,<br>οὐχ ὡς τὸν ποταμὸν λέγοντος τοῦ ποιήσαντος τὸ ἰαμβεῖον, οὐδὲ δὴ ὡς τὴν ὁμώνυμον αὐτῷ πόλιν κειμένην ἐπὶ τῷ ποταμῷ, ἀλλ’ ὡς τὴν Κολχίδα ἀπὸ μέρους, ἐπεὶ ἀπό γε τοῦ ποταμοῦ καὶ τῆς πόλεως οὐκ ἐλάττων ἑξακοσίων σταδίων λείπεται πλοῦς ἐπ’ εὐθείας εἰς τὸν μυχόν. ἡ δ’ αὐτὴ Διοσκουριάς ἐστι καὶ ἀρχὴ τοῦ ἰσθμοῦ τοῦ μεταξὺ τῆς Κασπίας καὶ τοῦ Πόντου καὶ ἐμπόριον τῶν ὑπερκειμένων καὶ σύνεγγυς ἐθνῶν κοινόν· συνέρχεσθαι γοῦν εἰς αὐτὴν ἑβδομήκοντα, οἱ δὲ καὶ τριακόσια ἔθνη φασίν, οἷς οὐδὲν τῶν ὄντων μέλει, πάντα δὲ ἑτερόγλωττα διὰ τὸ σποράδην καὶ ἀμίκτως οἰκεῖν ὑπὸ αὐθαδείας καὶ ἀγριότητος· Σαρμάται δ’ εἰσὶν οἱ πλείους, πάντες δὲ Καυκάσιοι. ταῦτα μὲν δὴ τὰ περὶ τὴν Διοσκουριάδα.", "st": "11.2.16"}, {"sp": "N", "t": "καὶ ἡ λοιπὴ δὲ Κολχὶς ἐπὶ τῇ θαλάττῃ ἡ πλείων ἐστί· διαρρεῖ δ’ αὐτὴν ὁ Φᾶσις, μέγας ποταμὸς ἐξ Ἀρμενίας τὰς ἀρχὰς ἔχων, δεχόμενος τόν τε Γλαῦκον καὶ τὸν Ἵππον ἐκ τῶν πλησίον ὀρῶν ἐκπίπτοντας· ἀναπλεῖται δὲ μέχρι Σαραπανῶν ἐρύματος δυναμένου δέξασθαι καὶ πόλεως συνοικισμόν, ὅθεν πεζεύουσιν ἐπὶ τὸν Κῦρον ἡμέραις τέτταρσι δι’ ἁμαξιτοῦ. ἐπίκειται δὲ τῷ Φάσιδι ὁμώνυμος πόλις, ἐμπόριον τῶν Κόλχων, τῇ μὲν προβεβλημένη τὸν ποταμὸν τῇ δὲ λίμνην τῇ δὲ τὴν θάλατταν. ἐντεῦθεν δὲ πλοῦς ἐπ’ Ἀμισοῦ καὶ Σινώπης τριῶν ἡμερῶν ἢ δύο διὰ τὸ τοὺς αἰγιαλοὺς μαλακοὺς εἶναι καὶ τὰς τῶν ποταμῶν ἐκβολάς. ἀγαθὴ δ’ ἐστὶν ἡ χώρα καὶ καρποῖς πλὴν τοῦ μέλιτος (πικρίζει γὰρ τὸ πλέον) καὶ τοῖς πρὸς ναυπηγίαν πᾶσιν· ὕλην τε γὰρ καὶ φύει καὶ ποταμοῖς κατακομίζει, λίνον τε ποιεῖ πολὺ καὶ κάνναβιν καὶ κηρὸν καὶ πίτταν. ἡ δὲ λινουργία καὶ τεθρύληται· καὶ γὰρ εἰς τοὺς ἔξω τόπους ἐξεκόμιζον, καί τινες βουλόμενοι συγγένειάν τινα τοῖς Κόλχοις πρὸς τοὺς Αἰγυπτίους ἐμφανίζειν ἀπὸ τούτων πιστοῦνται. ὑπέρκειται δὲ τῶν λεχθέντων ποταμῶν ἐν τῇ Μοσχικῇ τὸ τῆς Λευκοθέας ἱερὸν Φρίξου ἵδρυμα, καὶ μαντεῖον ἐκείνου, ὅπου κριὸς οὐ θύεται, πλούσιόν ποτε ὑπάρξαν, συληθὲν δὲ ὑπὸ Φαρνάκου καθ’ ἡμᾶς καὶ μικρὸν ὕστερον ὑπὸ Μιθριδάτου τοῦ Περγαμηνοῦ. κακωθείσης γὰρ χώρας<br>νοσεῖ τὰ τῶν θεῶν οὐδὲ τιμᾶσθαι θέλει,<br>φησὶν Εὐριπίδης.", "st": "11.2.17"}, {"sp": "N", "t": "τὸ μὲν γὰρ παλαιὸν ὅσην ἐπιφάνειαν ἔσχεν ἡ χώρα αὕτη δηλοῦσιν οἱ μῦθοι, τὴν Ἰάσονος στρατείαν αἰνιττόμενοι προελθόντος μέχρι καὶ Μηδίας, ἔτι δὲ πρότερον τὴν Φρίξου. μετὰ δὲ ταῦτα διαδεξάμενοι βασιλεῖς εἰς σκηπτουχίας διῃρημένην ἔχοντες τὴν χώραν μέσως ἔπραττον· αὐξηθέντος δὲ ἐπὶ πολὺ Μιθριδάτου τοῦ Εὐπάτορος, εἰς ἐκεῖνον ἡ χώρα περιέστη· ἐπέμπετο δ’ ἀεί τις τῶν φίλων ὕπαρχος καὶ διοικητὴς τῆς χώρας. τούτων δὲ ἦν καὶ Μοαφέρνης, ὁ τῆς μητρὸς ἡμῶν θεῖος πρὸς πατρός· ἦν δ’ ἔνθεν ἡ πλείστη τῷ βασιλεῖ πρὸς τὰς ναυτικὰς δυνάμεις ὑπουργία. καταλυθέντος δὲ Μιθριδάτου συγκατελύθη καὶ ἡ ὑπ’ αὐτῷ πᾶσα καὶ διενεμήθη πολλοῖς· ὕστατα δὲ Πολέμων ἔσχε τὴν Κολχίδα, κἀκείνου τελευτήσαντος ἡ γυνὴ Πυθοδωρὶς κρατεῖ, βασιλεύουσα καὶ Κόλχων καὶ Τραπεζοῦντος καὶ Φαρνακίας καὶ τῶν ὑπερκειμένων βαρβάρων, περὶ ὧν ἐροῦμεν ἐν τοῖς ὕστερον. ἡ δ’ οὖν Μοσχική, ἐν ᾗ τὸ ἱερόν, τριμερής ἐστι· τὸ μὲν γὰρ ἔχουσιν αὐτῆς Κόλχοι τὸ δὲ Ἴβηρες τὸ δὲ Ἀρμένιοι. ἔστι δὲ καὶ πολίχνιον ἐν τῇ Ἰβηρίᾳ Φρίξου πόλις ἡ νῦν Ἰδήεσσα, εὐερκὲς χωρίον ἐν μεθορίοις τῆς Κολχίδος.", "st": "11.2.18"}, {"sp": "N", "t": "τῶν δὲ συνερχομένων ἐθνῶν εἰς τὴν Διοσκουριάδα καὶ οἱ Φθειροφάγοι εἰσίν, ἀπὸ τοῦ αὐχμοῦ καὶ τοῦ πίνου λαβόντες τοὔνομα. πλησίον δὲ καὶ οἱ Σοάνες, οὐδὲν βελτίους τούτων τῷ πίνῳ δυνάμει δὲ βελτίους, σχεδὸν δέ τι καὶ κράτιστοι κατὰ ἀλκὴν καὶ δύναμιν· δυναστεύουσι γοῦν τῶν κύκλῳ τὰ ἄκρα τοῦ Καυκάσου κατέχοντες τὰ ὑπὲρ τῆς Διοσκουριάδος· βασιλέα δ’ ἔχουσι καὶ συνέδριον ἀνδρῶν τριακοσίων, συνάγουσι δ’ ὥς φασι στρατιὰν καὶ εἴκοσι μυριάδων· ἅπαν γάρ ἐστι τὸ πλῆθος μάχιμον, οὐ συντεταγμένον [δέ]. παρὰ τούτοις δὲ λέγεται καὶ χρυσὸν καταφέρειν τοὺς χειμάρρους, ὑποδέχεσθαι δ’ αὐτὸν τοὺς βαρβάρους φάτναις κατατετρημέναις καὶ μαλλωταῖς δοραῖς· ἀφ’ οὗ δὴ μεμυθεῦσθαι καὶ τὸ χρυσόμαλλον δέρος· εἰ μὴ καὶ Ἴβηρας ὁμωνύμως τοῖς ἑσπερίοις καλοῦσιν ἀπὸ τῶν ἑκατέρωθι χρυσείων. χρῶνται δ’ οἱ Σοάνες φαρμάκοις πρὸς τὰς ἀκίδας θαυμαστοῖς καὶ τοὺς ἀφαρμάκτοις τετρωμένους βέλεσι λυπεῖ κατὰ τὴν ὀσμήν. τὰ μὲν οὖν ἄλλα ἔθνη τὰ πλησίον τὰ περὶ τὸν Καύκασον λυπρὰ καὶ μικρόχωρα, τὸ δὲ τῶν Ἀλβανῶν ἔθνος καὶ τὸ τῶν Ἰβήρων, ἃ δὴ πληροῖ μάλιστα τὸν λεχθέντα ἰσθμόν, Καυκάσια [μὲν] καὶ αὐτὰ λέγοιτ’ ἄν, εὐδαίμονα δὲ χώραν ἔχει καὶ σφόδρα καλῶς οἰκεῖσθαι δυναμένην.", "st": "11.2.19"}, {"sp": "N", "t": "καὶ δὴ ἥ γε Ἰβηρία κατοικεῖται καλῶς τὸ πλέον πόλεσί τε καὶ ἐποικίοις, ὥστε καὶ κεραμωτὰς εἶναι στέγας καὶ ἀρχιτεκτονικὴν τὴν τῶν οἰκήσεων κατασκευὴν καὶ ἀγορὰς καὶ τἆλλα κοινά.", "st": "11.3.1"}, {"sp": "N", "t": "τῆς δὲ χώρας τὰ μὲν κύκλῳ τοῖς Καυκασίοις ὄρεσι περιέχεται· προπεπτώκασι γάρ, ὡς εἶπον, ἀγκῶνες ἐπὶ τὴν μεσημβρίαν εὔκαρποι, περιλαμβάνοντες τὴν σύμπασαν Ἰβηρίαν καὶ συνάπτοντες πρός τε τὴν Ἀρμενίαν καὶ τὴν Κολχίδα· ἐν μέσῳ δ’ ἐστὶ πεδίον ποταμοῖς διάρρυτον, μεγίστῳ δὲ τῷ Κύρῳ, ὃς τὴν ἀρχὴν ἔχων ἀπὸ τῆς Ἀρμενίας, εἰσβαλὼν εὐθὺς εἰς τὸ πεδίον τὸ λεχθέν, παραλαβὼν καὶ τὸν Ἄραγον ἐκ τοῦ Καυκάσου ῥέοντα καὶ ἄλλα ὕδατα διὰ στενῆς ποταμίας εἰς τὴν Ἀλβανίαν ἐκπίπτει· μεταξὺ δὲ ταύτης τε καὶ τῆς Ἀρμενίας ἐνεχθεὶς πολὺς διὰ πεδίων εὐβοτουμένων σφόδρα, δεξάμενος καὶ [ἄλλους] πλείους ποταμούς, ὧν ἐστιν ὅ τε Ἀλαζόνιος καὶ ὁ Σανδοβάνης καὶ ὁ Ῥοιτάκης καὶ Χάνης πλωτοὶ πάντες εἰς τὴν Κασπίαν ἐμβάλλει θάλατταν. ἐκαλεῖτο δὲ πρότερον Κόρος.", "st": "11.3.2"}, {"sp": "N", "t": "τὸ μὲν οὖν πεδίον τῶν Ἰβήρων οἱ γεωργικώτεροι καὶ πρὸς εἰρήνην νενευκότες οἰκοῦσιν ἀρμενιστί τε καὶ μηδιστὶ ἐσκευασμένοι, τὴν δ’ ὀρεινὴν οἱ πλείους καὶ μάχιμοι κατέχουσι Σκυθῶν δίκην ζῶντες καὶ Σαρματῶν, ὧνπερ καὶ ὅμοροι καὶ συγγενεῖς εἰσιν· ἅπτονται δ’ ὅμως καὶ γεωργίας, πολλάς τε μυριάδας συνάγουσιν καὶ ἐξ ἑαυτῶν καὶ ἐξ ἐκείνων, ἐπειδάν τι συμπέσῃ θορυβῶδες.", "st": "11.3.3"}, {"sp": "N", "t": "τέτταρες δ’ εἰσὶν εἰς τὴν χώραν εἰσβολαί· μία μὲν διὰ Σαραπανῶν φρουρίου Κολχικοῦ καὶ τῶν κατ’ αὐτὸ στενῶν, δι’ ὧν ὁ Φᾶσις γεφύραις ἑκατὸν καὶ εἴκοσι περατὸς γινόμενος διὰ τὴν σκολιότητα καταρρεῖ τραχὺς καὶ βίαιος εἰς τὴν Κολχίδα, πολλοῖς χειμάρροις κατὰ τὰς ἐπομβρίας ἐκχαραδρουμένων τῶν τόπων. γεννᾶται δ’ ἐκ τῶν ὑπερκειμένων ὀρῶν πολλαῖς συμπληρούμενος πηγαῖς, ἐν δὲ τοῖς πεδίοις καὶ ἄλλους προσλαμβάνει ποταμούς, ὧν ἐστιν ὅ τε Γλαῦκος καὶ ὁ Ἵππος· πληρωθεὶς δὲ καὶ γενόμενος πλωτὸς ἐξίησιν εἰς τὸν Πόντον καὶ ἔχει πόλιν ὁμώνυμον ἐφ’ αὑτῷ καὶ λίμνην πλησίον. ἡ μὲν οὖν ἐκ τῆς Κολχίδος εἰς τὴν Ἰβηρίαν ἐμβολὴ τοιαύτη, πέτραις καὶ ἐρύμασι καὶ ποταμοῖς χαραδρώδεσι διακεκλεισμένη.", "st": "11.3.4"}, {"sp": "N", "t": "ἐκ δὲ τῶν πρὸς ἄρκτον νομάδων ἐπὶ τρεῖς ἡμέρας ἀνάβασις χαλεπή, καὶ μετὰ ταύτην ποταμία στενὴ ἐπὶ τοῦ Ἀράγου ποταμοῦ τεττάρων ἡμερῶν ὁδὸν ἔχουσα ἐφ’ ἕνα, φρουρεῖ δὲ τὸ πέρας τῆς ὁδοῦ τεῖχος δύσμαχον· ἀπὸ δὲ τῆς Ἀλβανίας διὰ πέτρας πρῶτον λατομητὴ εἴσοδος, εἶτα διὰ τέλματος ὃ ποιεῖ ὁ ποταμὸς [Ἀλαζόνιος] ἐκ τοῦ Καυκάσου καταπίπτων. ἀπὸ δὲ τῆς Ἀρμενίας τὰ ἐπὶ τῷ Κύρῳ στενὰ καὶ τὰ ἐπὶ τῷ Ἀράγῳ· πρὶν γὰρ εἰς ἀλλήλους συμπεσεῖν, ἔχουσιν ἐπικειμένας πόλεις ἐρυμνὰς ἐπὶ πέτραις διεχούσαις ἀλλήλων ὅσον ἑκκαίδεκα σταδίους, ἐπὶ μὲν τῷ Κύρῳ τὴν Ἁρμοζικὴν ἐπὶ δὲ θατέρῳ Σευσάμορα. ταύταις δὲ ἐχρήσατο ταῖς εἰσβολαῖς πρότερον Πομπήιος ἐκ τῶν Ἀρμενίων ὁρμηθείς, καὶ μετὰ ταῦτα Κανίδιος.", "st": "11.3.5"}, {"sp": "N", "t": "τέτταρα δὲ καὶ γένη τῶν ἀνθρώπων οἰκεῖ τὴν χώραν· ἓν μὲν καὶ πρῶτον ἐξ οὗ τοὺς βασιλέας καθιστᾶσι κατ’ ἀγχιστείαν τε καὶ ἡλικίαν τὸν πρεσβύτατον, ὁ δὲ δεύτερος δικαιοδοτεῖ καὶ στρατηλατεῖ. δεύτερον δὲ τὸ τῶν ἱερέων οἳ ἐπιμελοῦνται καὶ τῶν πρὸς τοὺς ὁμόρους δικαίων. τρίτον δὲ τὸ τῶν στρατευομένων καὶ γεωργούντων. τέταρτον δὲ τὸ τῶν λαῶν, οἳ βασιλικοὶ δοῦλοί εἰσι καὶ πάντα διακονοῦνται τὰ πρὸς τὸν βίον. κοιναὶ δ’ εἰσὶν αὐτοῖς αἱ κτήσεις κατὰ συγγένειαν, ἄρχει δὲ καὶ ταμιεύει ἑκάστην ὁ πρεσβύτατος. τοιοῦτοι μὲν οἱ Ἴβηρες καὶ ἡ χώρα αὐτῶν.", "st": "11.3.6"}, {"sp": "N", "t": "Ἀλβανοὶ δὲ ποιμενικώτεροι καὶ τοῦ νομαδικοῦ γένους ἐγγυτέρω, πλὴν ἀλλ’ οὐκ ἄγριοι· ταύτῃ δὲ καὶ πολεμικοὶ μετρίως. οἰκοῦσι δὲ μεταξὺ τῶν Ἰβήρων καὶ τῆς Κασπίας θαλάττης, πρὸς ἕω μὲν ἁπτόμενοι τῆς θαλάττης, πρὸς δύσιν δὲ ὁμοροῦντες τοῖς Ἴβηρσι· τῶν δὲ λοιπῶν πλευρῶν τὸ μὲν βόρειον φρουρεῖται τοῖς Καυκασίοις ὄρεσι (ταῦτα γὰρ ὑπέρκειται τῶν πεδίων, καλεῖται δὲ τὰ πρὸς τῇ θαλάττῃ μάλιστα Κεραύνια), τὸ δὲ νότιον ποιεῖ ἡ Ἀρμενία παρήκουσα, πολλὴ μὲν πεδιὰς πολλὴ δὲ καὶ ὀρεινή, καθάπερ ἡ Καμβυσηνή, καθ’ ἣν ἅμα καὶ τοῖς Ἴβηρσι καὶ τοῖς Ἀλβανοῖς οἱ Ἀρμένιοι συνάπτουσιν.", "st": "11.4.1"}, {"sp": "N", "t": "ὁ δὲ Κῦρος ὁ διαρρέων τὴν Ἀλβανίαν καὶ οἱ ἄλλοι ποταμοὶ οἱ πληροῦντες ἐκεῖνον ταῖς μὲν τῆς γῆς ἀρεταῖς προσλαμβάνουσι, τὴν δὲ θάλατταν ἀλλοτριοῦσιν. ἡ γὰρ χοῦς προσπίπτουσα πολλὴ πληροῖ τὸν πόρον, ὥστε καὶ τὰς ἐπικειμένας νησῖδας ἐξηπειροῦσθαι καὶ τενάγη ποιεῖν ἀνώμαλα καὶ δυσφύλακτα· τὴν δ’ ἀνωμαλίαν ἐπιτείνουσιν αἱ ἐκ τῶν πλημμυρίδων ἀνακοπαί. καὶ δὴ καὶ εἰς στόματα δώδεκά φασι μεμερίσθαι τὰς ἐκβολάς, τὰ μὲν τυφλὰ τὰ δὲ παντελῶς ἐπίπεδα ὄντα καὶ μηδὲ ὕφορμον ἀπολείποντα· ἐπὶ πλείους γοῦν ἢ ἑξήκοντα σταδίους ἀμφικλύστου τῆς ᾐόνος οὔσης τῇ θαλάττῃ καὶ τοῖς ποταμοῖς, ἅπαν εἶναι μέρος αὐτῆς ἀπροσπέλαστον, τὴν δὲ χοῦν καὶ μέχρι πεντακοσίων παρήκειν σταδίων θινώδη ποιοῦσαν τὸν αἰγιαλόν. πλησίον δὲ καὶ ὁ Ἀράξης ἐμβάλλει τραχὺς ἐκ τῆς Ἀρμενίας ἐκπίπτων· ἣν δὲ ἐκεῖνος προωθεῖ χοῦν πορευτὸν ποιῶν τὸ ῥεῖθρον, ταύτην ὁ Κῦρος ἀναπληροῖ.", "st": "11.4.2"}, {"sp": "N", "t": "τάχα μὲν οὖν τῷ τοιούτῳ γένει τῶν ἀνθρώπων οὐδὲν δεῖ θαλάττης· οὐδὲ γὰρ τῇ γῇ χρῶνται κατ’ ἀξίαν, πάντα μὲν ἐκφερούσῃ καρπὸν καὶ τὸν ἡμερώτατον, πᾶν δὲ φυτόν· καὶ γὰρ τὰ ἀειθαλῆ φέρει· τυγχάνει δ’ ἐπιμελείας οὐδὲ μικρᾶς<br>ἀλλὰ τάγ’ ἄσπαρτα καὶ ἀνήροτα πάντα φύονται,<br>καθάπερ οἱ στρατεύσαντές φασι, Κυκλώπειόν τινα διηγούμενοι βίον· πολλαχοῦ γὰρ σπαρεῖσαν ἅπαξ δὶς ἐκφέρειν καρπὸν ἢ καὶ τρίς, τὸν δὲ πρῶτον καὶ πεντηκοντάχουν, ἀνέαστον καὶ ταῦτα οὐδὲ σιδήρῳ τμηθεῖσαν ἀλλ’ αὐτοξύλῳ ἀρότρῳ. ποτίζεται δὲ πᾶν τὸ πεδίον τοῦ Βαβυλωνίου καὶ τοῦ Αἰγυπτίου μᾶλλον τοῖς ποταμοῖς καὶ τοῖς ἄλλοις ὕδασιν ὥστ’ ἀεὶ ποώδη φυλάττειν τὴν ὄψιν· διὰ δὲ τοῦτο καὶ εὔβοτόν ἐστι· πρόσεστι δὲ καὶ τὸ εὐάερον ἐκείνων μᾶλλον. ἄσκαφοι δ’ αἱ ἄμπελοι μένουσαι διὰ τέλους, τεμνόμεναι δὲ διὰ πενταετηρίδος, νέαι μὲν διετεῖς ἐκφέρουσιν ἤδη καρπόν, τέλειαι δ’ ἀποδιδόασι τοσοῦτον ὥστ’ ἀφιᾶσιν ἐν τοῖς κλήμασι πολὺ μέρος. εὐερνῆ δ’ ἐστὶ καὶ τὰ βοσκήματα παρ’ αὐτοῖς τά τε ἥμερα καὶ τὰ ἄγρια.", "st": "11.4.3"}, {"sp": "N", "t": "καὶ οἱ ἄνθρωποι κάλλει καὶ μεγέθει διαφέροντες, ἁπλοῖ δὲ καὶ οὐ καπηλικοί· οὐδὲ γὰρ νομίσματι τὰ πολλὰ χρῶνται, οὐδὲ ἀριθμὸν ἴσασι μείζω τῶν ἑκατόν, ἀλλὰ φορτίοις τὰς ἀμοιβὰς ποιοῦνται· καὶ πρὸς τἆλλα δὲ τὰ τοῦ βίου ῥᾳθύμως ἔχουσιν. ἄπειροι δ’ εἰσὶ καὶ μέτρων τῶν ἐπ’ ἀκριβὲς καὶ σταθμῶν, καὶ πολέμου δὲ καὶ πολιτείας καὶ γεωργίας ἀπρονοήτως ἔχουσιν· ὅμως δὲ καὶ πεζοὶ καὶ ἀφ’ ἵππων ἀγωνίζονται, ψιλοί τε καὶ κατάφρακτοι, καθάπερ Ἀρμένιοι.", "st": "11.4.4"}, {"sp": "N", "t": "στέλλουσι δὲ μείζω τῆς Ἰβήρων στρατιάν. ὁπλίζουσι γὰρ καὶ ἓξ μυριάδας πεζῶν, ἱππέας δὲ μυρίους καὶ δισχιλίους, ὅσοις πρὸς Πομπήιον διεκινδύνευσαν. καὶ τούτοις δὲ συμπολεμοῦσιν οἱ νομάδες πρὸς τοὺς ἔξωθεν, ὥσπερ τοῖς Ἴβηρσι, κατὰ τὰς αὐτὰς αἰτίας. ἄλλως δ’ ἐπιχειροῦσι τοῖς ἀνθρώποις πολλάκις ὥστε καὶ γεωργεῖν κωλύουσιν. ἀκοντισταὶ δέ εἰσι καὶ τοξόται, θώρακας ἔχοντες καὶ θυρεούς, περίκρανα δὲ θήρεια παραπλησίως τοῖς Ἴβηρσιν. ἔστι δὲ τῆς Ἀλβανῶν χώρας καὶ ἡ Κασπιανή, τοῦ Κασπίου ἔθνους ἐπώνυμος, οὗπερ καὶ ἡ θάλαττα, ἀφανοῦς ὄντος νυνί. ἡ δ’ ἐκ τῆς Ἰβηρίας εἰς τὴν Ἀλβανίαν εἰσβολὴ διὰ τῆς Καμβυσηνῆς ἀνύδρου τε καὶ τραχείας ἐπὶ τὸν Ἀλαζόνιον ποταμόν. θηρευτικοὶ δὲ καὶ αὐτοὶ καὶ οἱ κύνες αὐτῶν εἰς ὑπερβολήν, οὐ τέχνῃ μᾶλλον ἢ σπουδῇ τῇ περὶ τοῦτο.", "st": "11.4.5"}, {"sp": "N", "t": "διαφέρουσι δὲ καὶ οἱ βασιλεῖς· νυνὶ μὲν οὖν εἷς ἁπάντων ἄρχει, πρότερον δὲ καὶ καθ’ ἑκάστην γλῶτταν ἰδίᾳ ἐβασιλεύοντο ἕκαστοι. γλῶτται δ’ εἰσὶν ἓξ καὶ εἴκοσιν αὐτοῖς διὰ τὸ μὴ εὐεπίμικτον πρὸς ἀλλήλους. φέρει δ’ ἡ γῆ καὶ τῶν ἑρπετῶν ἔνια τῶν θανασίμων καὶ σκορπίους καὶ φαλάγγια· τῶν δὲ φαλαγγίων τὰ μὲν ποιεῖ γελῶντας ἀποθνήσκειν, τὰ δὲ κλαίοντας πόθῳ τῶν οἰκείων.", "st": "11.4.6"}, {"sp": "N", "t": "θεοὺς δὲ τιμῶσιν ἥλιον καὶ δία καὶ σελήνην, διαφερόντως δὲ τὴν σελήνην. ἔστι δ’ αὐτῆς τὸ ἱερὸν τῆς Ἰβηρίας πλησίον· ἱερᾶται δ’ ἀνὴρ ἐντιμότατος μετά γε τὸν βασιλέα, προεστὼς τῆς ἱερᾶς χώρας, πολλῆς καὶ εὐάνδρου, καὶ αὐτῆς καὶ τῶν ἱεροδούλων, ὧν ἐνθουσιῶσι πολλοὶ καὶ προφητεύουσιν· ὃς δ’ ἂν αὐτῶν ἐπὶ πλέον κατάσχετος γενόμενος πλανᾶται κατὰ τὰς ὕλας μόνος, τοῦτον συλλαβὼν ὁ ἱερεὺς ἁλύσει δήσας ἱερᾷ τρέφει πολυτελῶς τὸν ἐνιαυτὸν ἐκεῖνον, ἔπειτα προαχθεὶς εἰς τὴν θυσίαν τῆς θεοῦ, σὺν ἄλλοις ἱερείοις θύεται μυρισθείς. τῆς δὲ θυσίας ὁ τρόπος οὗτος· ἔχων τις ἱερὰν λόγχην ᾗπέρ ἐστι νόμος ἀνθρωποθυτεῖν, παρελθὼν ἐκ τοῦ πλήθους παίει διὰ τῆς πλευρᾶς εἰς τὴν καρδίαν, οὐκ ἄπειρος τοιούτου· πεσόντος δὲ σημειοῦνται μαντεῖά τινα ἐκ τοῦ πτώματος καὶ εἰς τὸ κοινὸν ἀποφαίνουσι, κομισθέντος δὲ τοῦ σώματος εἴς τι χωρίον ἐπιβαίνουσιν ἅπαντες καθαρσίῳ χρώμενοι.", "st": "11.4.7"}, {"sp": "N", "t": "ὑπερβαλλόντως δὲ τὸ γῆρας τιμῶσιν Ἀλβανοὶ καὶ τὸ τῶν ἄλλων, οὐ τῶν γονέων μόνον· τεθνηκότων δὲ οὐχ ὅσιον φροντίζειν οὐδὲ μεμνῆσθαι. συγκατορύττουσι μέντοι τὰ χρήματα αὐτοῖς, καὶ διὰ τοῦτο πένητες ζῶσιν οὐδὲν πατρῷον ἔχοντες. ταῦτα μὲν περὶ Ἀλβανῶν. λέγεται δ’ Ἰάσονα μετὰ Ἀρμένου τοῦ Θετταλοῦ κατὰ τὸν πλοῦν τὸν ἐπὶ τοὺς Κόλχους ὁρμῆσαι μέχρι τῆς Κασπίας θαλάττης, καὶ τήν τε Ἰβηρίαν καὶ τὴν Ἀλβανίαν ἐπελθεῖν καὶ πολλὰ τῆς Ἀρμενίας καὶ τῆς Μηδίας, ὡς μαρτυρεῖ τά τε Ἰασόνια καὶ ἄλλα ὑπομνήματα πλείω. τὸν δὲ Ἄρμενον εἶναι ἐξ Ἀρμενίου πόλεως τῶν περὶ τὴν Βοιβηίδα λίμνην μεταξὺ Φερῶν καὶ Λαρίσης, τοὺς σὺν αὐτῷ τε οἰκίσαι τήν τε Ἀκιλισηνὴν καὶ τὴν Συσπιρῖτιν ἕως Καλαχανῆς καὶ Ἀδιαβηνῆς, καὶ δὴ καὶ τὴν Ἀρμενίαν ἐπώνυμον καταλιπεῖν.", "st": "11.4.8"}, {"sp": "N", "t": "ἐν δὲ τοῖς ὑπὲρ τῆς Ἀλβανίας ὄρεσι καὶ τὰς Ἀμαζόνας οἰκεῖν φασι. Θεοφάνης μὲν οὖν ὁ συστρατεύσας τῷ Πομπηίῳ καὶ γενόμενος ἐν τοῖς Ἀλβανοῖς, μεταξὺ τῶν Ἀμαζόνων καὶ τῶν Ἀλβανῶν φησι Γήλας οἰκεῖν καὶ Λήγας Σκύθας, καὶ ῥεῖν ἐνταῦθα τὸν Μερμάδαλιν ποταμὸν τούτων τε καὶ τῶν Ἀμαζόνων ἀνὰ μέσον. ἄλλοι δέ, ὧν καὶ ὁ Σκήψιος Μητρόδωρος καὶ Ὑψικράτης, οὐδὲ αὐτοὶ ἄπειροι τῶν τόπων γεγονότες, Γαργαρεῦσιν ὁμόρους αὐτὰς οἰκεῖν φασιν ἐν ταῖς ὑπωρείαις ταῖς πρὸς ἄρκτον τῶν Καυκασίων ὀρῶν ἃ καλεῖται Κεραύνια, τὸν μὲν ἄλλον χρόνον καθ’ αὑτάς, αὐτουργούσας ἕκαστα τά τε πρὸς ἄροτον καὶ φυτουργίαν καὶ τὰ πρὸς τὰς νομὰς καὶ μάλιστα τῶν ἵππων, τὰς δ’ ἀλκιμωτάτας κυνηγεσίαις πλεονάζειν καὶ τὰ πολέμια ἀσκεῖν· ἁπάσας δ’ ἐπικεκαῦσθαι τὸν δεξιὸν μαστὸν ἐκ νηπίων, ὥστε εὐπετῶς χρῆσθαι τῷ βραχίονι πρὸς ἑκάστην χρείαν, ἐν δὲ τοῖς πρώτοις πρὸς ἀκοντισμόν· χρῆσθαι δὲ καὶ τόξῳ καὶ σαγάρει καὶ πέλτῃ, δορὰς δὲ θηρίων ποιεῖσθαι περίκρανά τε καὶ σκεπάσματα καὶ διαζώματα· δύο δὲ μῆνας ἐξαιρέτους ἔχειν τοῦ ἔαρος, καθ’ οὓς ἀναβαίνουσιν εἰς τὸ πλησίον ὄρος τὸ διορίζον αὐτάς τε καὶ τοὺς Γαργαρέας. ἀναβαίνουσι δὲ κἀκεῖνοι κατὰ ἔθος τι παλαιόν, συνθύσοντές τε καὶ συνεσόμενοι ταῖς γυναιξὶ τεκνοποιίας χάριν ἀφανῶς τε καὶ ἐν σκότει, ὁ τυχὼν τῇ τυχούσῃ, ἐγκύμονας δὲ ποιήσαντες ἀποπέμπουσιν· αἱ δ’ ὅ τι μὲν ἂν θῆλυ τέκωσι κατέχουσιν αὐταί, τὰ δ’ ἄρρενα κομίζουσιν ἐκείνοις ἐκτρέφειν· ᾠκείωται δ’ ἕκαστος πρὸς ἕκαστον νομίζων υἱὸν διὰ τὴν ἄγνοιαν.", "st": "11.5.1"}, {"sp": "N", "t": "ὁ δὲ Μερμόδας καταράττων ἀπὸ τῶν ὀρῶν διὰ τῆς τῶν Ἀμαζόνων καὶ τῆς Σιρακηνῆς καὶ ὅση μεταξὺ ἔρημος, εἰς τὴν Μαιῶτιν ἐκδίδωσι. τοὺς δὲ Γαργαρέας συναναβῆναι μὲν ἐκ Θεμισκύρας φασὶ ταῖς Ἀμαζόσιν εἰς τούσδε τοὺς τόπους, εἶτ’ ἀποστάντας αὐτῶν πολεμεῖν μετὰ Θρᾳκῶν καὶ Εὐβοέων τινῶν πλανηθέντων μέχρι δεῦρο πρὸς αὐτάς, ὕστερον δὲ καταλυσαμένους τὸν πρὸς αὐτὰς πόλεμον ἐπὶ τοῖς λεχθεῖσι ποιήσασθαι συμβάσεις, ὥστε τέκνων συγκοινωνεῖν μόνον, ζῆν δὲ καθ’ αὑτοὺς ἑκατέρους.", "st": "11.5.2"}, {"sp": "N", "t": "ἴδιον δέ τι συμβέβηκε τῷ λόγῳ [τῷ] περὶ τῶν Ἀμαζόνων· οἱ μὲν γὰρ ἄλλοι τὸ μυθῶδες καὶ τὸ ἱστορικὸν διωρισμένον ἔχουσι· τὰ γὰρ παλαιὰ καὶ ψευδῆ καὶ τερατώδη μῦθοι καλοῦνται, ἡ δ’ ἱστορία βούλεται τἀληθές, ἄν τε παλαιὸν ἄν τε νέον, καὶ τὸ τερατῶδες ἢ οὐκ ἔχει ἢ σπάνιον· περὶ δὲ τῶν Ἀμαζόνων τὰ αὐτὰ λέγεται καὶ νῦν καὶ πάλαι, τερατώδη τε ὄντα καὶ πίστεως πόρρω. τίς γὰρ ἂν πιστεύσειεν, ὡς γυναικῶν στρατὸς ἢ πόλις ἢ ἔθνος συσταίη ἄν ποτε χωρὶς ἀνδρῶν; καὶ οὐ μόνον γε συσταίη, ἀλλὰ καὶ ἐφόδους ποιήσαιτο ἐπὶ τὴν ἀλλοτρίαν καὶ κρατήσειεν οὐ τῶν ἐγγὺς μόνον ὥστε καὶ μέχρι τῆς νῦν Ἰωνίας προελθεῖν, ἀλλὰ καὶ διαπόντιον στείλαιτο στρατείαν μέχρι τῆς Ἀττικῆς; τοῦτο γὰρ ὅμοιον ὡς ἂν εἴ τις λέγοι, τοὺς μὲν ἄνδρας γυναῖκας γεγονέναι τοὺς τότε τὰς δὲ γυναῖκας ἄνδρας. ἀλλὰ μὴν ταῦτά γε αὐτὰ καὶ νῦν λέγεται περὶ αὐτῶν. ἐπιτείνει δὲ τὴν ἰδιότητα καὶ τὸ πιστεύεσθαι τὰ παλαιὰ μᾶλλον ἢ τὰ νῦν·", "st": "11.5.3"}, {"sp": "N", "t": "κτίσεις γοῦν πόλεων καὶ ἐπωνυμίαι λέγονται, καθάπερ Ἐφέσου καὶ Σμύρνης καὶ Κύμης καὶ Μυρίνης, καὶ τάφοι καὶ ἄλλα ὑπομνήματα· τὴν δὲ Θεμίσκυραν καὶ τὰ περὶ τὸν Θερμώδοντα πεδία καὶ τὰ ὑπερκείμενα ὄρη ἅπαντες Ἀμαζόνων καλοῦσι, καί φασιν ἐξελαθῆναι αὐτὰς ἐνθένδε. ὅπου δὲ νῦν εἰσίν, ὀλίγοι τε καὶ ἀναποδείκτως καὶ ἀπίστως ἀποφαίνονται· καθάπερ καὶ περὶ Θαληστρίας, ἣν Ἀλεξάνδρῳ συμμῖξαί φασιν ἐν τῇ Ὑρκανίᾳ καὶ συγγενέσθαι τεκνοποιίας χάριν, δυναστεύουσαν τῶν Ἀμαζόνων· οὐ γὰρ ὁμολογεῖται τοῦτο· ἀλλὰ τῶν συγγραφέων τοσούτων ὄντων οἱ μάλιστα τῆς ἀληθείας φροντίσαντες οὐκ εἰρήκασιν, οὐδ’ οἱ πιστευόμενοι μάλιστα οὐδενὸς μέμνηνται τοιούτου, οὐδ’ οἱ εἰπόντες τὰ αὐτὰ εἰρήκασι· Κλείταρχος δέ φησι τὴν Θαληστρίαν ἀπὸ Κασπίων πυλῶν καὶ Θερμώδοντος ὁρμηθεῖσαν ἐλθεῖν πρὸς Ἀλέξανδρον· εἰσὶ δ’ ἀπὸ Κασπίας εἰς Θερμώδοντα στάδιοι πλείους ἑξακισχιλίων.", "st": "11.5.4"}, {"sp": "N", "t": "καὶ τὰ πρὸς τὸ ἔνδοξον θρυληθέντα οὐκ ἀνωμολόγηται παρὰ πάντων, οἱ δὲ πλάσαντες ἦσαν οἱ κολακείας μᾶλλον ἢ ἀληθείας φροντίζοντες· οἷον τὸ τὸν Καύκασον μετενεγκεῖν εἰς τὰ Ἰνδικὰ ὄρη καὶ τὴν πλησιάζουσαν ἐκείνοις ἑῴαν θάλατταν ἀπὸ τῶν ὑπερκειμένων τῆς Κολχίδος καὶ τοῦ Εὐξείνου ὀρῶν· ταῦτα γὰρ οἱ Ἕλληνες καὶ Καύκασον ὠνόμαζον, διέχοντα τῆς Ἰνδικῆς πλείους ἢ τρισμυρίους σταδίους, καὶ ἐνταῦθα ἐμύθευσαν τὰ περὶ Προμηθέα καὶ τὸν δεσμὸν αὐτοῦ· ταῦτα γὰρ τὰ ὕστατα πρὸς ἕω ἐγνώριζον οἱ τότε. ἡ δὲ ἐπὶ Ἰνδοὺς στρατεία Διονύσου καὶ Ἡρακλέους ὑστερογενῆ τὴν μυθοποιίαν ἐμφαίνει, ἅτε τοῦ Ἡρακλέους καὶ τὸν Προμηθέα λῦσαι λεγομένου χιλιάσιν ἐτῶν ὕστερον. καὶ ἦν μὲν ἐνδοξότερον τὸ τὸν Ἀλέξανδρον μέχρι τῶν Ἰνδικῶν ὀρῶν καταστρέψασθαι τὴν Ἀσίαν ἢ μέχρι τοῦ μυχοῦ τοῦ Εὐξείνου καὶ τοῦ Καυκάσου· ἀλλ’ ἡ δόξα τοῦ ὄρους καὶ τοὔνομα καὶ τὸ τοὺς περὶ Ἰάσονα δοκεῖν μακροτάτην στρατείαν τελέσαι τὴν μέχρι τῶν πλησίον Καυκάσου καὶ τὸ τὸν Προμηθέα παραδεδόσθαι δεδεμένον ἐπὶ τοῖς ἐσχάτοις τῆς γῆς ἐν τῷ Καυκάσῳ … χαριεῖσθαί τι τῷ βασιλεῖ ὑπέλαβον τοὔνομα τοῦ ὄρους μετενέγκαντες εἰς τὴν Ἰνδικήν.", "st": "11.5.5"}, {"sp": "N", "t": "τὰ μὲν οὖν ὑψηλότατα τοῦ ὄντως Καυκάσου τὰ νοτιώτατά ἐστι τὰ πρὸς Ἀλβανίᾳ καὶ Ἰβηρίᾳ καὶ Κόλχοις καὶ Ἡνιόχοις· οἰκοῦσι δὲ οὓς εἶπον τοὺς συνερχομένους εἰς τὴν Διοσκουριάδα· συνέρχονται δὲ τὸ πλεῖστον ἁλῶν χάριν. τούτων δ’ οἱ μὲν τὰς ἀκρωρείας κατέχουσιν, οἱ δὲ ἐν νάπαις αὐλίζονται καὶ ζῶσιν ἀπὸ θηρείων σαρκῶν τὸ πλέον καὶ καρπῶν ἀγρίων καὶ γάλακτος. αἱ δὲ κορυφαὶ χειμῶνος μὲν ἄβατοι, θέρους δὲ προσβαίνουσιν ὑποδούμενοι κεντρωτὰ ὠμοβόινα δίκην τυμπάνων πλατεῖα διὰ τὰς χιόνας καὶ τοὺς κρυστάλλους. καταβαίνουσι δ’ ἐπὶ δορᾶς κείμενοι σὺν τοῖς φορτίοις καὶ κατολισθαίνοντες, ὅπερ καὶ κατὰ τὴν Ἀτροπατίαν Μηδίαν καὶ κατὰ τὸ Μάσιον ὄρος τὸ ἐν Ἀρμενίᾳ συμβαίνει· ἐνταῦθα δὲ καὶ τροχίσκοι ξύλινοι κεντρωτοὶ τοῖς πέλμασιν ὑποτίθενται. τοῦ γοῦν Καυκάσου τὰ μὲν ἄκρα τοιαῦτα.", "st": "11.5.6"}, {"sp": "N", "t": "καταβαίνοντι δ’ εἰς τὰς ὑπωρείας ἀρκτικώτερα μέν ἐστι τὰ κλίματα, ἡμερώτερα δέ· ἤδη γὰρ συνάπτει τοῖς πεδίοις τῶν Σιράκων. εἰσὶ δὲ καὶ τρωγλοδύται τινὲς ἐν φωλεοῖς οἰκοῦντες διὰ τὰ ψύχη, παρ’ οἷς ἤδη καὶ ἀλφίτων ἐστὶν εὐπορία· μετὰ δὲ τοὺς τρωγλοδύτας καὶ χαμαικοῖται καὶ πολυφάγοι τινὲς καλούμενοι καὶ αἱ τῶν Εἰσαδίκων κῶμαι, δυναμένων γεωργεῖν διὰ τὸ μὴ παντελῶς ὑποπεπτωκέναι ταῖς ἄρκτοις.", "st": "11.5.7"}, {"sp": "N", "t": "οἱ δ’ ἐφεξῆς ἤδη νομάδες οἱ μεταξὺ τῆς Μαιώτιδος καὶ τῆς Κασπίας Ναβιανοὶ καὶ Πανξανοὶ καὶ ἤδη τὰ τῶν Σιράκων καὶ Ἀόρσων φῦλα. δοκοῦσι δ’ οἱ Ἄορσοι καὶ οἱ Σίρακες φυγάδες εἶναι τῶν ἀνωτέρω … καὶ προσάρκτιοι μᾶλλον Ἀόρσων. Ἀβέακος μὲν οὖν ὁ τῶν Σιράκων βασιλεύς, ἡνίκα Φαρνάκης τὸν Βόσπορον εἶχε, δύο μυριάδας ἱππέων ἔστελλε, Σπαδίνης δ’ ὁ τῶν Ἀόρσων καὶ εἴκοσιν, οἱ δὲ ἄνω Ἄορσοι καὶ πλείονας· καὶ γὰρ ἐπεκράτουν πλείονος γῆς καὶ σχεδόν τι τῆς Κασπίων παραλίας τῆς πλείστης ἦρχον, ὥστε καὶ ἐνεπορεύοντο καμήλοις τὸν Ἰνδικὸν φόρτον καὶ τὸν Βαβυλώνιον παρά τε Ἀρμενίων καὶ Μήδων διαδεχόμενοι· ἐχρυσοφόρουν δὲ διὰ τὴν εὐπορίαν. οἱ μὲν οὖν Ἄορσοι τὸν Τάναϊν παροικοῦσιν, οἱ Σίρακες δὲ τὸν Ἀχαρδέον, ὃς ἐκ τοῦ Καυκάσου ῥέων ἐκδίδωσιν εἰς τὴν Μαιῶτιν.", "st": "11.5.8"}, {"sp": "N", "t": "ἡ δὲ δευτέρα μερὶς ἄρχεται μὲν ἀπὸ τῆς Κασπίας θαλάττης, εἰς ἣν κατέπαυεν ἡ προτέρα· καλεῖται δ’ ἡ αὐτὴ θάλαττα καὶ Ὑρκανία. δεῖ δὲ περὶ τῆς θαλάττης εἰπεῖν πρότερον ταύτης καὶ τῶν προσοίκων ἐθνῶν. ἔστι δ’ ὁ κόλπος ἀνέχων ἐκ τοῦ ὠκεανοῦ πρὸς μεσημβρίαν κατ’ ἀρχὰς μὲν ἱκανῶς στενός, ἐνδοτέρω δὲ πλατύνεται προϊών, καὶ μάλιστα κατὰ τὸν μυχὸν ἐπὶ σταδίους που καὶ πεντακισχιλίους· ὁ δ’ εἴσπλους μέχρι τοῦ μυχοῦ μικρῷ πλειόνων ἂν εἴη συνάπτων πως ἤδη τῇ ἀοικήτῳ. φησὶ δ’ Ἐρατοσθένης τὸν ὑπὸ τῶν Ἑλλήνων γνωριζόμενον περίπλουν τῆς θαλάττης ταύτης τὸν μὲν παρὰ τοὺς Ἀλβανοὺς καὶ τοὺς Καδουσίους εἶναι πεντακισχιλίων καὶ τετρακοσίων, τὸν δὲ παρὰ τὴν Ἀναριακῶν καὶ Μάρδων καὶ Ὑρκανῶν μέχρι τοῦ στόματος τοῦ Ὤξου ποταμοῦ τετρακισχιλίων καὶ ὀκτακοσίων· ἔνθεν δ’ ἐπὶ τοῦ Ἰαξάρτου δισχιλίων τετρακοσίων. δεῖ δὲ περὶ τῶν ἐν τῇ μερίδι ταύτῃ καὶ τοῖς ἐπὶ τοσοῦτον ἐκτετοπισμένοις ἁπλούστερον ἀκούειν, καὶ μάλιστα περὶ τῶν διαστημάτων.", "st": "11.6.1"}, {"sp": "N", "t": "εἰσπλέοντι δ’ ἐν δεξιᾷ μὲν τοῖς Εὐρωπαίοις οἱ συνεχεῖς Σκύθαι νέμονται καὶ Σαρμάται οἱ μεταξὺ τοῦ Τανάιδος καὶ τῆς θαλάττης ταύτης, νομάδες οἱ πλείους, περὶ ὧν εἰρήκαμεν· ἐν ἀριστερᾷ δ’ οἱ πρὸς ἕω Σκύθαι, νομάδες καὶ οὗτοι, μέχρι τῆς ἑῴας θαλάττης καὶ τῆς Ἰνδικῆς παρατείνοντες. ἅπαντας μὲν δὴ τοὺς προσβόρρους κοινῶς οἱ παλαιοὶ τῶν Ἑλλήνων συγγραφεῖς Σκύθας καὶ Κελτοσκύθας ἐκάλουν· οἱ δ’ ἔτι πρότερον διελόντες τοὺς μὲν ὑπὲρ τοῦ Εὐξείνου καὶ Ἴστρου καὶ τοῦ Ἀδρίου κατοικοῦντας Ὑπερβορέους ἔλεγον καὶ Σαυρομάτας καὶ Ἀριμασπούς, τοὺς δὲ πέραν τῆς Κασπίας θαλάττης τοὺς μὲν Σάκας τοὺς δὲ Μασσαγέτας ἐκάλουν, οὐκ ἔχοντες ἀκριβὲς λέγειν περὶ αὐτῶν οὐδέν, καίπερ πρὸς Μασσαγέτας τοῦ Κύρου πόλεμον ἱστοροῦντες. ἀλλ’ οὔτε περὶ τούτων οὐδὲν ἠκρίβωτο πρὸς ἀλήθειαν, οὔτε τὰ παλαιὰ τῶν Περσικῶν οὔτε τῶν Μηδικῶν ἢ Συριακῶν ἐς πίστιν ἀφικνεῖτο μεγάλην διὰ τὴν τῶν συγγραφέων ἁπλότητα καὶ τὴν φιλομυθίαν.", "st": "11.6.2"}, {"sp": "N", "t": "ὁρῶντες γὰρ τοὺς φανερῶς μυθογράφους εὐδοκιμοῦντας ᾠήθησαν καὶ αὐτοὶ παρέξεσθαι τὴν γραφὴν ἡδεῖαν, ἐὰν ἐν ἱστορίας σχήματι λέγωσιν ἃ μηδέποτε [μήτε] εἶδον μήτε ἤκουσαν ἢ οὐ παρά γε ἰδόντων, σκοποῦντες δὲ αὐτὸ μόνον τοῦτο ὅ τι ἀκρόασιν ἡδεῖαν ἔχει καὶ θαυμαστήν. ῥᾷον δ’ ἄν τις Ἡσιόδῳ καὶ Ὁμήρῳ πιστεύσειεν ἡρωολογοῦσι καὶ τοῖς τραγικοῖς ποιηταῖς ἢ Κτησίᾳ τε καὶ Ἡροδότῳ καὶ Ἑλλανίκῳ καὶ ἄλλοις τοιούτοις.", "st": "11.6.3"}, {"sp": "N", "t": "οὐδὲ τοῖς περὶ Ἀλεξάνδρου δὲ συγγράψασιν ῥᾴδιον πιστεύειν τοῖς πολλοῖς· καὶ γὰρ οὗτοι ῥᾳδιουργοῦσι διά τε τὴν δόξαν τὴν Ἀλεξάνδρου καὶ διὰ τὸ τὴν στρατείαν πρὸς τὰς ἐσχατιὰς γεγονέναι τῆς Ἀσίας πόρρω ἀφ’ ἡμῶν· τὸ δὲ πόρρω δυσέλεγκτον. ἡ δὲ τῶν Ῥωμαίων ἐπικράτεια καὶ ἡ τῶν Παρθυαίων πλεῖόν τι προσεκκαλύπτει τῶν παραδεδομένων πρότερον· οἱ γὰρ περὶ ἐκείνων συγγράφοντες καὶ τὰ χωρία καὶ τὰ ἔθνη, ἐν οἷς αἱ πράξεις, πιστότερον λέγουσιν ἢ οἱ πρὸ αὐτῶν· μᾶλλον γὰρ κατωπτεύκασι.", "st": "11.6.4"}, {"sp": "N", "t": "τοὺς δ’ οὖν ἐν ἀριστερᾷ εἰσπλέοντι τὸ Κάσπιον πέλαγος παροικοῦντας νομάδας Δάας οἱ νῦν προσαγορεύουσι τοὺς ἐπονομαζομένους Πάρνους· εἶτ’ ἔρημος πρόκειται μεταξύ, καὶ ἐφεξῆς ἡ Ὑρκανία, καθ’ ἣν ἤδη πελαγίζει μέχρι τοῦ συνάψαι τοῖς Μηδικοῖς ὄρεσι καὶ τοῖς Ἀρμενίων. τούτων δ’ ἐστὶ μηνοειδὲς τὸ σχῆμα κατὰ τὰς ὑπωρείας, αἳ τελευτῶσαι πρὸς θάλατταν ποιοῦσι τὸν μυχὸν τοῦ κόλπου. οἰκεῖ δὲ τὴν παρώρειαν ταύτην μέχρι τῶν ἄκρων ἀπὸ θαλάττης ἀρξαμένοις ἐπὶ μικρὸν μὲν τῶν Ἀλβανῶν τι μέρος καὶ τῶν Ἀρμενίων, τὸ δὲ πλέον Γῆλαι καὶ Καδούσιοι καὶ Ἄμαρδοι καὶ Οὐίτιοι καὶ Ἀναριάκαι. φασὶ δὲ Παρρασίων τινὰς συνοικῆσαι τοῖς Ἀναριάκαις, οὓς καλεῖσθαι νῦν Παρσίους· Αἰνιᾶνας δ’ ἐν τῇ Οὐιτίᾳ τειχίσαι πόλιν ἣν Αἰνιάνα καλεῖσθαι, καὶ δείκνυσθαι ὅπλα τε Ἑλληνικὰ ἐνταῦθα καὶ σκεύη χαλκᾶ καὶ ταφάς· ἐνταῦθα δὲ καὶ πόλιν Ἀναριάκην, ἐν ᾗ, φασί, δείκνυται μαντεῖον ἐγκοιμωμένων … καὶ ἄλλα τινὰ ἔθνη λῃστρικὰ καὶ μάχιμα μᾶλλον ἢ γεωργικά· ποιεῖ δὲ τοῦτο ἡ τραχύτης τῶν τόπων. τὸ μέντοι πλέον τῆς περὶ τὴν ὀρεινὴν παραλίας Καδούσιοι νέμονται, σχεδὸν δέ τι ἐπὶ πεντακισχιλίους σταδίους, ὥς φησι Πατροκλῆς, ὃς καὶ πάρισον ἡγεῖται τὸ πέλαγος τοῦτο τῷ Ποντικῷ. ταῦτα μὲν οὖν τὰ χωρία λυπρά.", "st": "11.7.1"}, {"sp": "N", "t": "ἡ δ’ Ὑρκανία σφόδρα εὐδαίμων καὶ πολλὴ καὶ τὸ πλέον πεδιὰς πόλεσί τε ἀξιολόγοις διειλημμένη, ὧν ἐστι Ταλαβρόκη καὶ Σαμαριανὴ καὶ Κάρτα καὶ τὸ βασίλειον Τάπη, ὅ φασι μικρὸν ὑπὲρ τῆς θαλάττης ἱδρυμένον διέχειν τῶν Κασπίων πυλῶν σταδίους χιλίους τετρακοσίους. σημεῖα δὲ τῆς εὐδαιμονίας· ἡ μὲν γὰρ ἄμπελος μετρητὴν οἴνου φέρει, ἡ δὲ συκῆ μεδίμνους ἑξήκοντα, ὁ δὲ σῖτος ἐκ τοῦ ἐκπεσόντος καρποῦ τῆς καλάμης φύεται, ἐν δὲ τοῖς δένδρεσι σμηνουργεῖται καὶ τῶν φύλλων ἀπορρεῖ μέλι· τοῦτο δὲ γίνεται καὶ τῆς Μηδίας ἐν τῇ Ματιανῇ καὶ τῆς Ἀρμενίας ἐν τῇ Σακασηνῇ καὶ τῇ Ἀραξηνῇ. τῆς μέντοι προσηκούσης ἐπιμελείας οὐκ ἔτυχεν οὔτε αὐτὴ οὔτε ἡ ἐπώνυμος αὐτῇ θάλαττα ἄπλους τε οὖσα καὶ ἀργός· νῆσοί τέ εἰσιν οἰκεῖσθαι δυνάμεναι, ὡς δ’ εἰρήκασί τινες καὶ χρυσῖτιν ἔχουσαι γῆν. αἴτιον δ’ ὅτι καὶ οἱ ἡγεμόνες οἵ τ’ ἐξ ἀρχῆς ἐτύγχανον βάρβαροι ὄντες οἱ τῶν Ὑρκανῶν, Μῆδοί τε καὶ Πέρσαι καὶ οἱ ὕστατοι Παρθυαῖοι, χείρους ἐκείνων ὄντες, καὶ ἡ γείτων ἅπασα χώρα λῃστῶν καὶ νομάδων μεστὴ καὶ ἐρημίας. Μακεδόνες δ’ ὀλίγον μὲν χρόνον ἐπῆρξαν, ἀλλ’ ἐν πολέμοις ὄντες καὶ τὰ πόρρω σκοπεῖν οὐ δυνάμενοι. φησὶ δ’ Ἀριστόβουλος ὑλώδη οὖσαν τὴν Ὑρκανίαν δρῦν ἔχειν, πεύκην δὲ καὶ ἐλάτην καὶ πίτυν μὴ φύειν, τὴν δ’ Ἰνδικὴν πληθύειν τούτοις. τῆς δὲ Ὑρκανίας ἐστὶ καὶ ἡ Νησαία· τινὲς δὲ καὶ καθ’ αὑτὴν τιθέασι τὴν Νησαίαν.", "st": "11.7.2"}, {"sp": "N", "t": "διαρρεῖται δὲ καὶ ποταμοῖς ἡ Ὑρκανία τῷ τε Ὤχῳ καὶ Ὤξῳ μέχρι τῆς εἰς θάλατταν ἐκβολῆς, ὧν ὁ Ὦχος καὶ διὰ τῆς Νησαίας ῥεῖ· ἔνιοι δὲ τὸν Ὦχον εἰς τὸν Ὦξον ἐμβάλλειν φασίν. Ἀριστόβουλος δὲ καὶ μέγιστον ἀποφαίνει τὸν Ὦξον τῶν ἑωραμένων ὑφ’ ἑαυτοῦ κατὰ τὴν Ἀσίαν πλὴν τῶν Ἰνδικῶν· φησὶ δὲ καὶ εὔπλουν εἶναι καὶ οὗτος καὶ Ἐρατοσθένης παρὰ Πατροκλέους λαβών, καὶ πολλὰ τῶν Ἰνδικῶν φορτίων κατάγειν εἰς τὴν Ὑρκανίαν θάλατταν, ἐντεῦθεν δ’ εἰς τὴν Ἀλβανίαν περαιοῦσθαι καὶ διὰ τοῦ Κύρου καὶ τῶν ἑξῆς τόπων εἰς τὸν Εὔξεινον καταφέρεσθαι. οὐ πάνυ δὲ ὑπὸ τῶν παλαιῶν ὁ Ὦχος ὀνομάζεται· Ἀπολλόδωρος μέντοι ὁ τὰ Παρθικὰ γράψας συνεχῶς αὐτὸν ὀνομάζει ὡς ἐγγυτάτω τοῖς Παρθυαίοις ῥέοντα.", "st": "11.7.3"}, {"sp": "N", "t": "προσεδοξάσθη δὲ καὶ περὶ τῆς θαλάττης ταύτης πολλὰ ψευδῆ διὰ τὴν Ἀλεξάνδρου φιλοτιμίαν· ἐπειδὴ γὰρ ὡμολόγητο ἐκ πάντων ὅτι διείργει τὴν Ἀσίαν ἀπὸ τῆς Εὐρώπης ὁ Τάναϊς ποταμός, τὸ δὲ μεταξὺ τῆς θαλάττης καὶ τοῦ Τανάιδος πολὺ μέρος τῆς Ἀσίας ὂν οὐχ ὑπέπιπτε τοῖς Μακεδόσι, στρατηγεῖν δ’ ἔγνωστο ὥστε τῇ φήμῃ γε κἀκείνων δόξαι τῶν μερῶν κρατεῖν τὸν Ἀλέξανδρον, εἰς ἓν συνῆγον τήν τε Μαιῶτιν λίμνην τὴν δεχομένην τὸν Τάναϊν καὶ τὴν Κασπίαν θάλατταν, λίμνην καὶ ταύτην καλοῦντες καὶ συντετρῆσθαι φάσκοντες πρὸς ἀλλήλας ἀμφοτέρας, ἑκατέραν δὲ εἶναι μέρος τῆς ἑτέρας. Πολύκλειτος δὲ καὶ πίστεις προφέρεται περὶ τοῦ λίμνην εἶναι τὴν θάλατταν ταύτην, ὄφεις τε γὰρ ἐκτρέφειν καὶ ὑπόγλυκυ εἶναι τὸ ὕδωρ· ὅτι δὲ καὶ οὐχ ἑτέρα τῆς Μαιώτιδός ἐστι, τεκμαιρόμενος ἐκ τοῦ τὸν Τάναϊν εἰς αὐτὴν ἐμβάλλειν· ἐκ γὰρ τῶν αὐτῶν ὀρῶν τῶν Ἰνδικῶν ἐξ ὧν ὅ τε Ὦχος καὶ ὁ Ὦξος καὶ ἄλλοι πλείους φέρεται καὶ ὁ Ἰαξάρτης ἐκδίδωσί τε ὁμοίως ἐκείνοις εἰς τὸ Κάσπιον πέλαγος πάντων ἀρκτικώτατος. τοῦτον οὖν ὠνόμασαν Τάναϊν, καὶ προσέθεσάν γε τούτῳ πίστιν, ὡς εἴη Τάναϊς ὃν εἴρηκεν ὁ Πολύκλειτος· τὴν γὰρ περαίαν τοῦ ποταμοῦ τούτου φέρειν ἐλάτην καὶ οἰστοῖς ἐλατίνοις χρῆσθαι τοὺς ταύτῃ Σκύθας· τοῦτο δὲ καὶ τεκμήριον τοῦ τὴν χώραν τὴν πέραν τῆς Εὐρώπης εἶναι, μὴ τῆς Ἀσίας· τὴν γὰρ Ἀσίαν τὴν ἄνω καὶ τὴν πρὸς ἕω μὴ φύειν ἐλάτην. Ἐρατοσθένης δέ φησι καὶ ἐν τῇ Ἰνδικῇ φύεσθαι ἐλάτην καὶ ἐντεῦθεν ναυπηγήσασθαι τὸν στόλον Ἀλέξανδρον· πολλὰ δὲ καὶ ἄλλα τοιαῦτα συγκρούειν Ἐρατοσθένης πειρᾶται, ἡμῖν δ’ ἀποχρώντως εἰρήσθω περὶ αὐτῶν.", "st": "11.7.4"}, {"sp": "N", "t": "καὶ τοῦτο δ’ ἐκ τῶν κατὰ τὴν Ὑρκανίαν ἱστορουμένων παραδόξων ἐστὶν ὑπὸ Εὐδόξου καὶ ἄλλων, ὅτι πρόκεινταί τινες ἀκταὶ τῆς θαλάττης ὕπαντροι, τούτων δὲ μεταξὺ καὶ τῆς θαλάττης ὑπόκειται ταπεινὸς αἰγιαλός, ἐκ δὲ τῶν ὕπερθεν κρημνῶν ποταμοὶ ῥέοντες τοσαύτῃ προφέρονται βίᾳ ὥστε ταῖς ἀκταῖς συνάψαντες ἐξακοντίζουσι τὸ ὕδωρ εἰς τὴν θάλατταν, ἄρραντον φυλάττοντες τὸν αἰγιαλὸν ὥστε καὶ στρατοπέδοις ὁδεύσιμον εἶναι σκεπαζομένοις τῷ ῥεύματι, οἱ δ’ ἐπιχώριοι κατάγονται πολλάκις εὐωχίας καὶ θυσίας χάριν εἰς τὸν τόπον, καὶ ποτὲ μὲν ὑπὸ τοῖς ἄντροις κατακλίνονται, ποτὲ δ’ ὑπ’ αὐτῷ τῷ ῥεύματι ἡλιαζόμενοι ἄλλως ἄλλοι τέρπονται, παραφαινομένης ἅμα καὶ τῆς θαλάττης ἑκατέρωθεν καὶ τῆς ᾐόνος ποώδους καὶ ἀνθηρᾶς οὔσης διὰ τὴν ἰκμάδα.", "st": "11.7.5"}, {"sp": "N", "t": "ἀπὸ δὲ τῆς Ὑρκανίας θαλάττης προϊόντι ἐπὶ τὴν ἕω δεξιὰ μέν ἐστι τὰ ὄρη μέχρι τῆς Ἰνδικῆς θαλάττης παρατείνοντα, ἅπερ οἱ Ἕλληνες ὀνομάζουσι Ταῦρον, ἀρξάμενα ἀπὸ τῆς Παμφυλίας καὶ τῆς Κιλικίας καὶ μέχρι δεῦρο προϊόντα ἀπὸ τῆς ἑσπέρας συνεχῆ καὶ τυγχάνοντα ἄλλων καὶ ἄλλων ὀνομάτων. προσοικοῦσι δ’ αὐτοῦ τὰ προσάρκτια μέρη πρῶτοι μὲν οἱ Γῆλαι καὶ Καδούσιοι καὶ Ἄμαρδοι, καθάπερ εἴρηται, καὶ τῶν Ὑρκανίων τινές, ἔπειτα τὸ τῶν Παρθυαίων ἔθνος καὶ τὸ τῶν Μαργιανῶν καὶ τῶν Ἀρίων καὶ ἡ ἔρημος, ἣν ἀπὸ τῆς Ὑρκανίας ὁρίζει ὁ Σάρνιος ποταμὸς πρὸς ἕω βαδίζουσι καὶ ἐπὶ τὸν Ὦχον. καλεῖται δὲ τὸ μέχρι δεῦρο ἀπὸ τῆς Ἀρμενίας διατεῖνον ἢ μικρὸν ἀπολεῖπον Παραχοάθρας. ἔστι δὲ ἀπὸ τῆς Ὑρκανίας θαλάττης εἰς τοὺς Ἀρίους περὶ ἑξακισχιλίους σταδίους· εἶθ’ ἡ Βακτριανή ἐστι καὶ ἡ Σογδιανή, τελευταῖοι δὲ Σκύθαι νομάδες. τὰ δ’ ὄρη Μακεδόνες μὲν ἅπαντα τὰ ἐφεξῆς ἀπὸ Ἀρίων Καύκασον ἐκάλεσαν, παρὰ δὲ τοῖς βαρβάροις τά τε ἄκρα κατὰ μέρος ὠνομάζετο ὁ Παροπάμισος τὰ προσβόρεια καὶ τὰ Ἠμωδὰ καὶ τὸ Ἴμαον καὶ ἄλλα τοιαῦτα ὀνόματα ἑκάστοις μέρεσιν ἐπέκειτο.", "st": "11.8.1"}, {"sp": "N", "t": "ἐν ἀριστερᾷ δὲ τούτοις ἀντιπαράκειται [τὰ] Σκυθικὰ ἔθνη καὶ τὰ νομαδικὰ ἅπασαν ἐκπληροῦντα τὴν βόρειον πλευράν. οἱ μὲν δὴ πλείους τῶν Σκυθῶν ἀπὸ τῆς Κασπίας θαλάττης ἀρξάμενοι Δᾶαι προσαγορεύονται, τοὺς δὲ προσεῴους τούτων μᾶλλον Μασσαγέτας καὶ Σάκας ὀνομάζουσι, τοὺς δ’ ἄλλους κοινῶς μὲν Σκύθας ὀνομάζουσιν ἰδίᾳ δ’ ὡς ἑκάστους· ἅπαντες δ’ ὡς ἐπὶ τὸ πολὺ νομάδες. μάλιστα δὲ γνώριμοι γεγόνασι τῶν νομάδων οἱ τοὺς Ἕλληνας ἀφελόμενοι τὴν Βακτριανήν, Ἄσιοι καὶ Πασιανοὶ καὶ Τόχαροι καὶ Σακάραυλοι, ὁρμηθέντες ἀπὸ τῆς περαίας τοῦ Ἰαξάρτου τῆς κατὰ Σάκας καὶ Σογδιανούς, ἣν κατεῖχον Σάκαι. καὶ τῶν Δαῶν οἱ μὲν προσαγορεύονται Ἄπαρνοι οἱ δὲ Ξάνθιοι οἱ δὲ Πίσσουροι. οἱ μὲν οὖν Ἄπαρνοι πλησιαίτατα τῇ Ὑρκανίᾳ παράκεινται καὶ τῇ κατ’ αὐτὴν θαλάττῃ, οἱ δὲ λοιποὶ διατείνουσι καὶ μέχρι τῆς ἀντιπαρηκούσης τῇ Ἀρίᾳ.", "st": "11.8.2"}, {"sp": "N", "t": "μεταξὺ δ’ αὐτῶν καὶ τῆς Ὑρκανίας καὶ τῆς Παρθυαίας μέχρι Ἀρίων ἔρημος πρόκειται πολλὴ καὶ ἄνυδρος, ἣν διεξιόντες μακραῖς ὁδοῖς κατέτρεχον τήν τε Ὑρκανίαν καὶ τὴν Νησαίαν καὶ τὰ τῶν Παρθυαίων πεδία· οἱ δὲ συνέθεντο φόρους· φόρος δ’ ἦν τὸ ἐπιτρέπειν τακτοῖς τισι χρόνοις τὴν χώραν κατατρέχειν καὶ φέρεσθαι λείαν. ἐπιπολαζόντων δ’ αὐτῶν παρὰ τὰ συγκείμενα ἐπολεμεῖτο, καὶ πάλιν διαλύσεις καὶ ἀναπολεμήσεις ὑπῆρχον. τοιοῦτος δὲ καὶ ὁ τῶν ἄλλων νομάδων βίος, ἀεὶ τοῖς πλησίον ἐπιτιθεμένων τοτὲ δ’ αὖ διαλλαττομένων.", "st": "11.8.3"}, {"sp": "N", "t": "Σάκαι μέντοι παραπλησίας ἐφόδους ἐποιήσαντο τοῖς Κιμμερίοις καὶ Τρήρεσι, τὰς μὲν μακροτέρας τὰς δὲ καὶ ἐγγύθεν· καὶ γὰρ τὴν Βακτριανὴν κατέσχον καὶ τῆς Ἀρμενίας κατεκτήσαντο τὴν ἀρίστην γῆν, ἣν καὶ ἐπώνυμον ἑαυτῶν κατέλιπον τὴν Σακασηνήν, καὶ μέχρι Καππαδόκων καὶ μάλιστα τῶν πρὸς Εὐξείνῳ οὓς Ποντικοὺς νῦν καλοῦσι, προῆλθον. ἐπιθέμενοι δ’ αὐτοῖς πανηγυρίζουσιν ἀπὸ τῶν λαφύρων οἱ ταύτῃ τότε τῶν Περσῶν στρατηγοὶ νύκτωρ ἄρδην αὐτοὺς ἠφάνισαν. ἐν δὲ τῷ πεδίῳ πέτραν τινὰ προσχώματι συμπληρώσαντες εἰς βουνοειδὲς σχῆμα ἐπέθηκαν τεῖχος καὶ τὸ τῆς Ἀναΐτιδος καὶ τῶν συμβώμων θεῶν ἱερὸν ἱδρύσαντο, Ὠμανοῦ καὶ Ἀναδάτου Περσικῶν δαιμόνων, ἀπέδειξάν τε πανήγυριν κατ’ ἔτος ἱεράν, τὰ Σάκαια, ἣν μέχρι νῦν ἐπιτελοῦσιν οἱ τὰ Ζῆλα ἔχοντες· οὕτω γὰρ καλοῦσι τὸν τόπον· ἔστι δὲ ἱεροδούλων πόλισμα τὸ πλέον· Πομπήιος δὲ προσθεὶς χώραν ἀξιόλογον καὶ τοὺς ἐν αὐτῇ συνοικίσας εἰς τὸ τεῖχος μίαν τῶν πόλεων ἀπέφηνεν ὧν διέταξε μετὰ τὴν Μιθριδάτου κατάλυσιν.", "st": "11.8.4"}, {"sp": "N", "t": "οἱ μὲν [οὖν] οὕτω λέγουσι περὶ τῶν Σακῶν, οἱ δ’ ὅτι Κῦρος ἐπιστρατεύσας τοῖς Σάκαις ἡττηθεὶς τῇ μάχῃ φεύγει, στρατοπεδευσάμενος δ’ ἐν ᾧ χωρίῳ τὰς παρασκευὰς ἀπολελοίπει πλήρεις ἀφθονίας ἁπάσης καὶ μάλιστα οἴνου, διαναπαύσας μικρὰ τὴν στρατιάν, ἤλαυνεν ἀφ’ ἑσπέρας ὡς φεύγων, πλήρεις ἀφεὶς τὰς σκηνάς· προελθὼν δ’ ὅσον ἐδόκει συμφέρειν ἱδρύθη· ἐπιόντες δ’ ἐκεῖνοι καὶ καταλαβόντες ἔρημον ἀνδρῶν τὸ στρατόπεδον τῶν δὲ πρὸς ἀπόλαυσιν μεστόν, ἀνέδην ἐνεπίμπλαντο· ὁ δ’ ὑποστρέψας ἐξοίνους κατέλαβε καὶ παραπλῆγας, ὥσθ’ οἱ μὲν ἐν κάρῳ κείμενοι καὶ ὕπνῳ κατεκόπτοντο, οἱ δ’ ὀρχούμενοι καὶ βακχεύοντες γυμνοὶ περιέπιπτον τοῖς τῶν πολεμίων ὅπλοις, ὀλίγου δ’ ἀπώλοντο ἅπαντες. ὁ δὲ θεῖον νομίσας τὸ εὐτύχημα, τὴν ἡμέραν ἐκείνην ἀνιερώσας τῇ πατρίῳ θεῷ προσηγόρευσε Σάκαια· ὅπου δ’ ἂν ᾖ τῆς θεοῦ ταύτης ἱερόν, ἐνταῦθα νομίζεται καὶ ἡ τῶν Σακαίων ἑορτὴ βακχεία τις μεθ’ ἡμέραν καὶ νύκτωρ, διεσκευασμένων σκυθιστί, πινόντων ἅμα καὶ πληκτιζομένων πρὸς ἀλλήλους ἅμα τε καὶ τὰς συμπινούσας γυναῖκας.", "st": "11.8.5"}, {"sp": "N", "t": "Μασσαγέται δ’ ἐδήλωσαν τὴν σφετέραν ἀρετὴν ἐν τῷ πρὸς Κῦρον πολέμῳ, περὶ οὗ θρυλοῦσι πολλοί, καὶ δεῖ πυνθάνεσθαι παρ’ ἐκείνων. λέγεται δὲ καὶ τοιαῦτα περὶ τῶν Μασσαγετῶν, ὅτι κατοικοῦσιν οἱ μὲν ὄρη τινὲς δ’ αὐτῶν πεδία οἱ δὲ ἕλη ἃ ποιοῦσιν οἱ ποταμοί, οἱ δὲ τὰς ἐν τοῖς ἕλεσι νήσους. μάλιστα δέ φασι τὸν Ἀράξην ποταμὸν κατακλύζειν τὴν χώραν πολλαχῆ σχιζόμενον, ἐκπίπτοντα δὲ τοῖς μὲν ἄλλοις στόμασιν εἰς τὴν ἄλλην τὴν πρὸς ἄρκτοις θάλατταν, ἑνὶ δὲ μόνῳ πρὸς τὸν κόλπον τὸν Ὑρκάνιον. θεὸν δὲ ἥλιον μόνον ἡγοῦνται, τούτῳ δὲ ἱπποθυτοῦσι· γαμεῖ δ’ ἕκαστος μίαν, χρῶνται δὲ καὶ ταῖς ἀλλήλων οὐκ ἀφανῶς, ὁ δὲ μιγνύμενος τῇ ἀλλοτρίᾳ τὴν φαρέτραν ἐξαρτήσας ἐκ τῆς ἁμάξης φανερῶς μίγνυται· θάνατος δὲ νομίζεται παρ’ αὐτοῖς ἄριστος, ὅταν γηράσαντες κατακοπῶσι μετὰ προβατείων κρεῶν καὶ ἀναμὶξ βρωθῶσι· τοὺς δὲ νόσῳ θανόντας ῥίπτουσιν ὡς ἀσεβεῖς καὶ ἀξίους ὑπὸ θηρίων βεβρῶσθαι. ἀγαθοὶ δὲ ἱππόται καὶ πεζοί, τόξοις δὲ χρῶνται καὶ μαχαίραις καὶ θώραξι καὶ σαγάρεσι χαλκαῖς, ζῶναι δὲ αὐτοῖς εἰσι χρυσαῖ καὶ διαδήματα ἐν ταῖς μάχαις· οἵ τε ἵπποι χρυσοχάλινοι, καὶ μασχαλιστῆρες δὲ χρυσοῖ· ἄργυρος δ’ οὐ γίνεται παρ’ αὐτοῖς, σίδηρος δ’ ὀλίγος, χαλκὸς δὲ καὶ χρυσὸς ἄφθονος.", "st": "11.8.6"}, {"sp": "N", "t": "οἱ μὲν οὖν ἐν ταῖς νήσοις οὐκ ἔχοντες σπόριμα ῥιζοφαγοῦσι καὶ ἀγρίοις χρῶνται καρποῖς, ἀμπέχονται δὲ τοὺς τῶν δένδρων φλοιούς (οὐδὲ γὰρ βοσκήματα ἔχουσι), πίνουσι δὲ τὸν ἐκ τῶν δένδρων καρπὸν ἐκθλίβοντες· οἱ δ’ ἐν τοῖς ἕλεσιν ἰχθυοφαγοῦσιν, ἀμπέχονται δὲ τὰ τῶν φωκῶν δέρματα τῶν ἐκ θαλάττης ἀνατρεχουσῶν· οἱ δ’ ὄρειοι τοῖς ἀγρίοις τρέφονται καὶ αὐτοὶ καρποῖς· ἔχουσι δὲ καὶ πρόβατα ὀλίγα ὥστ’ οὐδὲ κατακόπτουσι φειδόμενοι τῶν ἐρίων χάριν καὶ τοῦ γάλακτος· τὴν δ’ ἐσθῆτα ποικίλλουσιν ἐπιχρίστοις φαρμάκοις δυσεξίτηλον ἔχουσι τὸ ἄνθος. οἱ δὲ πεδινοὶ καίπερ ἔχοντες χώραν οὐ γεωργοῦσιν, ἀλλὰ ἀπὸ προβάτων καὶ ἰχθύων ζῶσι νομαδικῶς καὶ Σκυθικῶς. ἔστι γάρ τις καὶ κοινὴ δίαιτα πάντων τῶν τοιούτων ἣν πολλάκις λέγω, καὶ ταφαὶ δ’ εἰσὶ παραπλήσιαι καὶ ἤθη καὶ ὁ σύμπας βίος, αὐθέκαστος μὲν σκαιός τε καὶ ἄγριος καὶ πολεμικός, πρὸς δὲ τὰ συμβόλαια ἁπλοῦς καὶ ἀκάπηλος.", "st": "11.8.7"}, {"sp": "N", "t": "τοῦ δὲ τῶν Μασσαγετῶν καὶ τῶν Σακῶν ἔθνους καὶ οἱ Ἀττάσιοι καὶ οἱ Χωράσμιοι, εἰς οὓς ἀπὸ τῶν Βακτριανῶν καὶ τῶν Σογδιανῶν ἔφυγε Σπιταμένης, εἷς ἐκ τῶν ἀποδράντων Περσῶν τὸν Ἀλέξανδρον, καθάπερ καὶ Βῆσσος· καὶ ὕστερον δὲ Ἀρσάκης τὸν Καλλίνικον φεύγων Σέλευκον εἰς τοὺς Ἀπασιάκας ἐχώρησε. φησὶ δ’ Ἐρατοσθένης τοὺς Ἀραχωτοὺς καὶ Μασσαγέτας τοῖς Βακτρίοις παρακεῖσθαι πρὸς δύσιν παρὰ τὸν Ὦξον, καὶ Σάκας μὲν καὶ Σογδιανοὺς τοῖς ὅλοις ἐδάφεσιν ἀντικεῖσθαι τῇ Ἰνδικῇ, Βακτρίους δ’ ἐπ’ ὀλίγον· τὸ γὰρ πλέον τῷ Παροπαμισῷ παρακεῖσθαι· διείργειν δὲ Σάκας μὲν καὶ Σογδιανοὺς τὸν Ἰαξάρτην, καὶ Σογδιανοὺς δὲ καὶ Βακτριανοὺς τὸν Ὦξον, μεταξὺ δὲ Ὑρκανῶν καὶ Ἀρίων Ταπύρους οἰκεῖν· κύκλῳ δὲ περὶ τὴν θάλατταν μετὰ τοὺς Ὑρκανοὺς Ἀμάρδους τε καὶ Ἀναριάκας καὶ Καδουσίους καὶ Ἀλβανοὺς καὶ Κασπίους καὶ Οὐιτίους, τάχα δὲ καὶ ἑτέρους μέχρι Σκυθῶν, ἐπὶ θάτερα δὲ μέρη τῶν Ὑρκανῶν Δέρβικας, τοὺς δὲ Καδουσίους συμψαύειν Μήδων καὶ Ματιανῶν ὑπὸ τὸν Παραχοάθραν.", "st": "11.8.8"}, {"sp": "N", "t": "τὰ δὲ διαστήματα οὕτω λέγει· ἀπὸ μὲν τοῦ Κασπίου ἐπὶ τὸν Κῦρον ὡς χιλίους ὀκτακοσίους σταδίους, ἔνθεν δ’ ἐπὶ Κασπίας πύλας πεντακισχιλίους ἑξακοσίους, εἶτ’ εἰς Ἀλεξάνδρειαν τὴν ἐν Ἀρίοις ἑξακισχιλίους τετρακοσίους, εἶτ’ εἰς Βάκτραν τὴν πόλιν, ἣ καὶ Ζαριάσπα καλεῖται, τρισχιλίους ὀκτακοσίους ἑβδομήκοντα, εἶτ’ ἐπὶ τὸν Ἰαξάρτην ποταμόν, ἐφ’ ὃν Ἀλέξανδρος ἧκεν, ὡς πεντακισχιλίους· ὁμοῦ δισμύριοι δισχίλιοι ἑξακόσιοι ἑβδομήκοντα. λέγει δὲ καὶ οὕτω τὰ διαστήματα ἀπὸ Κασπίων πυλῶν εἰς Ἰνδούς· εἰς μὲν Ἑκατόμπυλον χιλίους ἐνακοσίους ἑξήκοντά φασιν, εἰς δ’ Ἀλεξάνδρειαν τὴν ἐν Ἀρίοις τετρακισχιλίους πεντακοσίους τριάκοντα, εἶτ’ εἰς Προφθασίαν τὴν ἐν Δραγγῇ χιλίους ἑξακοσίους, οἱ δὲ πεντακοσίους, εἶτ’ εἰς Ἀραχωτοὺς τὴν πόλιν τετρακισχιλίους ἑκατὸν εἴκοσιν, εἶτ’ εἰς Ὀρτόσπανα ἐπὶ τὴν ἐκ Βάκτρων τρίοδον δισχιλίους, εἶτ’ εἰς τὰ ὅρια τῆς Ἰνδικῆς χιλίους· ὁμοῦ μύριοι πεντακισχίλιοι τριακόσιοι. ἐπ’ εὐθείας δὲ τῷ διαστήματι τούτῳ τὸ συνεχὲς δεῖ νοεῖν, τὸ ἀπὸ τοῦ Ἰνδοῦ μέχρι τῆς ἑῴας θαλάττης μῆκος τῆς Ἰνδικῆς. ταῦτα μὲν τὰ περὶ τοὺς Σάκας.", "st": "11.8.9"}, {"sp": "N", "t": "ἡ δὲ Παρθυαία πολλὴ μὲν οὐκ ἔστι· συνετέλει γοῦν μετὰ τῶν Ὑρκανῶν [κατὰ] τὰ Περσικὰ καὶ μετὰ ταῦτα τῶν Μακεδόνων κρατούντων ἐπὶ χρόνον πολύν. πρὸς δὲ τῇ σμικρότητι δασεῖα καὶ ὀρεινή ἐστι καὶ ἄπορος, ὥστε διὰ τοῦτο δρόμῳ διεξιᾶσι τὸν ἑαυτῶν οἱ βασιλεῖς ὄχλον, οὐ δυναμένης τρέφειν τῆς χώρας οὐδ’ ἐπὶ μικρόν· ἀλλὰ νῦν ηὔξηται. μέρη δ’ ἐστὶ τῆς Παρθυηνῆς ἥ τε Κωμισηνὴ καὶ ἡ Χωρήνη, σχεδὸν δέ τι καὶ τὰ μέχρι πυλῶν Κασπίων καὶ Ῥαγῶν καὶ Ταπύρων ὄντα τῆς Μηδίας πρότερον. ἔστι δ’ Ἀπάμεια καὶ Ἡράκλεια, πόλεις περὶ τὰς Ῥάγας. εἰσὶ δ’ ἀπὸ Κασπίων πυλῶν εἰς μὲν Ῥάγας στάδιοι πεντακόσιοι, ὥς φησιν Ἀπολλόδωρος, εἰς δ’ Ἑκατόμπυλον τὸ τῶν Παρθυαίων βασίλειον χίλιοι διακόσιοι ἑξήκοντα· τοὔνομα δὲ ταῖς Ῥάγαις ἀπὸ τῶν γενομένων σεισμῶν γενέσθαι φασίν, ὑφ’ ὧν πόλεις τε συχναὶ καὶ κῶμαι δισχίλιαι, ὡς Ποσειδώνιός φησι, ἀνετράπησαν. τοὺς δὲ Ταπύρους οἰκεῖν φασι μεταξὺ Δερβίκων τε καὶ Ὑρκανῶν. ἱστοροῦσι δὲ περὶ τῶν Ταπύρων ὅτι αὐτοῖς εἴη νόμιμον τὰς γυναῖκας ἐκδιδόναι τὰς γαμετὰς ἑτέροις ἀνδράσιν, ἐπειδὰν ἐξ αὐτῶν ἀνέλωνται δύο ἢ τρία τέκνα, καθάπερ καὶ Κάτων Ὁρτησίῳ δεηθέντι ἐξέδωκε τὴν Μαρκίαν ἐφ’ ἡμῶν κατὰ παλαιὸν Ῥωμαίων ἔθος.", "st": "11.9.1"}, {"sp": "N", "t": "νεωτερισθέντων δὲ τῶν ἔξω τοῦ Ταύρου διὰ τὸ πρὸς ἄλλοις εἶναι τοὺς τῆς Συρίας καὶ τῆς Μηδίας βασιλέας τοὺς ἔχοντας καὶ ταῦτα, πρῶτον μὲν τὴν Βακτριανὴν ἀπέστησαν οἱ πεπιστευμένοι καὶ τὴν ἐγγὺς αὐτῆς πᾶσαν, οἱ περὶ Εὐθύδημον. ἔπειτ’ Ἀρσάκης ἀνὴρ Σκύθης τῶν Δαῶν τινας ἔχων τοὺς Πάρνους καλουμένους νομάδας παροικοῦντας τὸν Ὦχον, ἐπῆλθεν ἐπὶ τὴν Παρθυαίαν καὶ ἐκράτησεν αὐτῆς. κατ’ ἀρχὰς μὲν οὖν ἀσθενὴς ἦν διαπολεμῶν πρὸς τοὺς ἀφαιρεθέντας τὴν χώραν καὶ αὐτὸς καὶ οἱ διαδεξάμενοι ἐκεῖνον, ἔπειθ’ οὕτως ἴσχυσαν ἀφαιρούμενοι τὴν πλησίον ἀεὶ διὰ τὰς ἐν τοῖς πολέμοις κατορθώσεις ὥστε τελευτῶντες ἁπάσης τῆς ἐντὸς Εὐφράτου κύριοι κατέστησαν. ἀφείλοντο δὲ καὶ τῆς Βακτριανῆς μέρος βιασάμενοι τοὺς Σκύθας καὶ ἔτι πρότερον τοὺς περὶ Εὐκρατίδαν, καὶ νῦν ἐπάρχουσι τοσαύτης γῆς καὶ τοσούτων ἐθνῶν ὥστε ἀντίπαλοι τοῖς Ῥωμαίοις τρόπον τινὰ γεγόνασι κατὰ μέγεθος τῆς ἀρχῆς. αἴτιος δ’ ὁ βίος αὐτῶν καὶ τὰ ἔθη τὰ ἔχοντα πολὺ μὲν τὸ βάρβαρον καὶ τὸ Σκυθικόν, πλέον μέντοι τὸ χρήσιμον πρὸς ἡγεμονίαν καὶ τὴν ἐν τοῖς πολέμοις κατόρθωσιν.", "st": "11.9.2"}, {"sp": "N", "t": "φασὶ δὲ τοὺς Πάρνους Δάας μετανάστας εἶναι ἐκ τῶν ὑπὲρ τῆς Μαιώτιδος Δαῶν, οὓς Ξανδίους ἢ Παρίους καλοῦσιν· οὐ πάνυ δ’ ὡμολόγηται Δάας εἶναί τινας τῶν ὑπὲρ τῆς Μαιώτιδος Σκυθῶν· ἀπὸ τούτων δ’ οὖν ἕλκειν φασὶ τὸ γένος τὸν Ἀρσάκην, οἱ δὲ Βακτριανὸν λέγουσιν αὐτόν, φεύγοντα δὲ τὴν αὔξησιν τῶν περὶ Διόδοτον ἀποστῆσαι τὴν Παρθυαίαν. εἰρηκότες δὲ πολλὰ περὶ τῶν Παρθικῶν νομίμων ἐν τῇ ἕκτῃ τῶν ἱστορικῶν ὑπομνημάτων βίβλῳ, δευτέρᾳ δὲ τῶν μετὰ Πολύβιον, παραλείψομεν ἐνταῦθα μὴ ταυτολογεῖν δόξωμεν, τοσοῦτον εἰπόντες μόνον ὅτι τῶν Παρθυαίων συνέδριόν φησιν εἶναι Ποσειδώνιος διττόν, τὸ μὲν συγγενῶν τὸ δὲ σοφῶν καὶ μάγων, ἐξ ὧν ἀμφοῖν τοὺς βασιλεῖς καθίστασθαι.", "st": "11.9.3"}, {"sp": "N", "t": "ἡ δ’ Ἀρία καὶ ἡ Μαργιανὴ κράτιστα χωρία ἐστὶ ταύτῃ, τῇ μὲν ὑπὸ τῶν ὀρῶν ἐγκλειόμενα τῇ δ’ ἐν πεδίοις τὰς οἰκήσεις ἔχοντα. τὰ μὲν οὖν ὄρη νέμονται σκηνῖταί τινες, τὰ δὲ πεδία ποταμοῖς διαρρεῖται ποτίζουσιν αὐτὰ τὰ μὲν τῷ Ἀρίῳ τὰ δὲ Μάργῳ. ὁμορεῖ δὲ ἡ Ἀρία τῇ Βακτριανῇ καὶ τὴν ὑποστᾶσαν ὄρει τῷ ἔχοντι τὴν Βακτριανήν· διέχει δὲ τῆς Ὑρκανίας περὶ ἑξακισχιλίους σταδίους. συντελὴς δ’ ἦν αὐτῇ καὶ ἡ Δραγγιανὴ μέχρι Καρμανίας, τὸ μὲν πλέον τοῖς νοτίοις μέρεσι τῶν ὀρῶν ὑποπεπτωκυῖα, ἔχουσα μέντοι τινὰ τῶν μερῶν καὶ τοῖς ἀρκτικοῖς πλησιάζοντα τοῖς κατὰ τὴν Ἀρίαν· καὶ ἡ Ἀραχωσία δὲ οὐ πολὺ ἄπωθέν ἐστι, καὶ αὕτη τοῖς νοτίοις μέρεσι τῶν ὀρῶν ὑποπεπτωκυῖα καὶ μέχρι τοῦ Ἰνδοῦ ποταμοῦ τεταμένη, μέρος οὖσα τῆς Ἀριανῆς. μῆκος δὲ τῆς Ἀρίας ὅσον δισχίλιοι στάδιοι, πλάτος δὲ τριακόσιοι τοῦ πεδίου· πόλεις δὲ Ἀρτακάηνα καὶ Ἀλεξάνδρεια καὶ Ἀχαΐα, ἐπώνυμοι τῶν κτισάντων. εὐοινεῖ δὲ σφόδρα ἡ γῆ· καὶ γὰρ εἰς τριγονίαν παραμένει ἐν ἀπιττώτοις ἄγγεσι.", "st": "11.10.1"}, {"sp": "N", "t": "παραπλησία δ’ ἐστὶ καὶ ἡ Μαργιανή, ἐρημίαις δὲ περιέχεται τὸ πεδίον. θαυμάσας δὲ τὴν εὐφυΐαν ὁ Σωτὴρ Ἀντίοχος τείχει περιέβαλε κύκλον ἔχοντι χιλίων καὶ πεντακοσίων σταδίων, πόλιν δὲ ἔκτισεν Ἀντιόχειαν. εὐάμπελος δὲ καὶ αὕτη ἡ γῆ· φασὶ γοῦν τὸν πυθμένα εὑρίσκεσθαι πολλάκις δυσὶν ἀνδράσι περιληπτόν, τὸν δὲ βότρυν δίπηχυν.", "st": "11.10.2"}, {"sp": "N", "t": "τῆς δὲ Βακτρίας μέρη μέν τινα τῇ Ἀρίᾳ παραβέβληται πρὸς ἄρκτον, τὰ πολλὰ δ’ ὑπέρκειται πρὸς ἕω· πολλὴ δ’ ἐστὶ καὶ πάμφορος πλὴν ἐλαίου. τοσοῦτον δὲ ἴσχυσαν οἱ ἀποστήσαντες Ἕλληνες αὐτὴν διὰ τὴν ἀρετὴν τῆς χώρας ὥστε τῆς τε Ἀριανῆς ἐπεκράτουν καὶ τῶν Ἰνδῶν, ὥς φησιν Ἀπολλόδωρος ὁ Ἀρταμιτηνός, καὶ πλείω ἔθνη κατεστρέψαντο ἢ Ἀλέξανδρος, καὶ μάλιστα Μένανδρος (εἴ γε καὶ τὸν Ὕπανιν διέβη πρὸς ἔω καὶ μέχρι τοῦ Ἰμάου προῆλθε) τὰ μὲν αὐτὸς τὰ δὲ Δημήτριος ὁ Εὐθυδήμου υἱὸς τοῦ Βακτρίων βασιλέως· οὐ μόνον δὲ τὴν Παταληνὴν κατέσχον ἀλλὰ καὶ τῆς ἄλλης παραλίας τήν τε Σαραόστου καλουμένην καὶ τὴν Σιγέρδιδος βασιλείαν. καθ’ ὅλου δέ φησιν ἐκεῖνος τῆς συμπάσης Ἀριανῆς πρόσχημα εἶναι τὴν Βακτριανήν· καὶ δὴ καὶ μέχρι Σηρῶν καὶ Φρυνῶν ἐξέτεινον τὴν ἀρχήν.", "st": "11.11.1"}, {"sp": "N", "t": "πόλεις δ’ εἶχον τά τε Βάκτρα ἥνπερ καὶ Ζαριάσπαν καλοῦσιν, ἣν διαρρεῖ ὁμώνυμος ποταμὸς ἐκβάλλων εἰς τὸν Ὦξον, καὶ Ἄδραψα καὶ ἄλλας πλείους· τούτων δ’ ἦν καὶ ἡ Εὐκρατίδεια τοῦ ἄρξαντος ἐπώνυμος. οἱ δὲ κατασχόντες αὐτὴν Ἕλληνες καὶ εἰς σατραπείας διῃρήκασιν, ὧν τήν τε Ἀσπιώνου καὶ τὴν Ταπυρίαν ἀφῄρηντο Εὐκρατίδην οἱ Παρθυαῖοι. ἔσχον δὲ καὶ τὴν Σογδιανὴν ὑπερκειμένην πρὸς ἕω τῆς Βακτριανῆς μεταξὺ τοῦ τε Ὤξου ποταμοῦ, ὃς ὁρίζει τήν τε τῶν Βακτρίων καὶ τὴν τῶν Σογδίων, καὶ τοῦ Ἰαξάρτου· οὗτος δὲ καὶ τοὺς Σογδίους ὁρίζει καὶ τοὺς νομάδας.", "st": "11.11.2"}, {"sp": "N", "t": "τὸ μὲν οὖν παλαιὸν οὐ πολὺ διέφερον τοῖς βίοις καὶ τοῖς ἔθεσι τῶν νομάδων οἵ τε Σογδιανοὶ καὶ οἱ Βακτριανοί, μικρὸν δ’ ὅμως ἡμερώτερα ἦν τὰ τῶν Βακτριανῶν, ἀλλὰ καὶ περὶ τούτων οὐ τὰ βέλτιστα λέγουσιν οἱ περὶ Ὀνησίκριτον· τοὺς γὰρ ἀπειρηκότας διὰ γῆρας ἢ νόσον ζῶντας παραβάλλεσθαι τρεφομένοις κυσὶν ἐπίτηδες πρὸς τοῦτο, οὓς ἐνταφιαστὰς καλεῖσθαι τῇ πατρῴᾳ γλώττῃ, καὶ ὁρᾶσθαι τὰ μὲν ἔξω τείχους τῆς μητροπόλεως τῶν Βάκτρων καθαρά, τῶν δ’ ἐντὸς τὸ πλέον ὀστέων πλῆρες ἀνθρωπίνων· καταλῦσαι δὲ τὸν νόμον Ἀλέξανδρον. τοιαῦτα δέ πως καὶ τὰ περὶ τοὺς Κασπίους ἱστοροῦσι· τοὺς γὰρ γονέας, ἐπειδὰν ὑπὲρ ἑβδομήκοντα ἔτη γεγονότες τυγχάνωσιν, ἐγκλεισθέντας λιμοκτονεῖσθαι. τοῦτο μὲν οὖν ἀνεκτότερον καὶ τῷ Κείων νόμῳ παραπλήσιον καίπερ ὂν σκυθικόν, πολὺ μέντοι σκυθικώτερον τὸ τῶν Βακτριανῶν. καὶ δὴ διαπορεῖν ἄξιον ἦν, ἡνίκα Ἀλέξανδρος τοιαῦτα κατελάμβανε τἀνταῦθα, τί χρὴ εἰπεῖν τὰ ἐπὶ τῶν πρώτων Περσῶν καὶ τῶν ἔτι πρότερον ἡγεμόνων ὁποῖα εἰκὸς ἦν παρ’ αὐτοῖς νενομίσθαι.", "st": "11.11.3"}, {"sp": "N", "t": "φασὶ δ’ οὖν ὀκτὼ πόλεις τὸν Ἀλέξανδρον ἔν τε τῇ Βακτριανῇ καὶ τῇ Σογδιανῇ κτίσαι, τινὰς δὲ κατασκάψαι, ὧν Καριάτας μὲν τῆς Βακτριανῆς, ἐν ᾗ Καλλισθένης συνελήφθη καὶ παρεδόθη φυλακῆ, Μαράκανδα δὲ τῆς Σογδιανῆς καὶ τὰ Κῦρα, ἔσχατον ὂν Κύρου κτίσμα ἐπὶ τῷ Ἰαξάρτῃ ποταμῷ κείμενον, ὅπερ ἦν ὅριον τῆς Περσῶν ἀρχῆς· κατασκάψαι δὲ τὸ κτίσμα τοῦτο καίπερ ὄντα φιλόκυρον διὰ τὰς πυκνὰς ἀποστάσεις· ἑλεῖν δὲ καὶ πέτρας ἐρυμνὰς σφόδρα ἐκ προδοσίας τήν τε ἐν τῇ Βακτριανῇ τὴν Σισιμίθρου ἐν ᾗ εἶχεν Ὀξυάρτης τὴν θυγατέρα Ῥωξάνην, καὶ τὴν ἐν τῇ Σογδιανῇ τὴν τοῦ Ὤξου, οἱ δ’ Ἀριαμάζου φασί. τὴν μὲν οὖν Σισιμίθρου πεντεκαίδεκα σταδίων ἱστοροῦσι τὸ ὕψος, ὀγδοήκοντα δὲ τὸν κύκλον, ἄνω δ’ ἐπίπεδον καὶ εὔγεων ὅσον πεντακοσίους ἄνδρας τρέφειν δυναμένην, ἐν ᾗ καὶ ξενίας τυχεῖν πολυτελοῦς καὶ γάμους ἀγαγεῖν Ῥωξάνης τῆς Ὀξυάρτου θυγατρὸς τὸν Ἀλέξανδρον· τὴν δὲ τῆς Σογδιανῆς διπλασίαν τὸ ὕψος φασί. περὶ τούτους δὲ τοὺς τόπους καὶ τὸ τῶν Βραγχιδῶν ἄστυ ἀνελεῖν, οὓς Ξέρξην μὲν ἱδρῦσαι αὐτόθι συναπάραντας αὐτῷ ἑκόντας ἐκ τῆς οἰκείας διὰ τὸ παραδοῦναι τὰ χρήματα τοῦ θεοῦ τὰ ἐν Διδύμοις καὶ τοὺς θησαυρούς, ἐκεῖνον δ’ ἀνελεῖν μυσαττόμενον τὴν ἱεροσυλίαν καὶ τὴν προδοσίαν.", "st": "11.11.4"}, {"sp": "N", "t": "τὸν δὲ διὰ τῆς Σογδιανῆς ῥέοντα ποταμὸν καλεῖ Πολυτίμητον Ἀριστόβουλος, τῶν Μακεδόνων [τοὔνομα] θεμένων, καθάπερ καὶ ἄλλα πολλὰ τὰ μὲν καινὰ ἔθεσαν τὰ δὲ παρωνόμασαν· ἄρδοντα δὲ τὴν χώραν ἐκπίπτειν εἰς ἔρημον καὶ ἀμμώδη γῆν καταπίνεσθαί τε εἰς τὴν ἄμμον, ὡς καὶ τὸν Ἄριον τὸν δι’ Ἀρίων ῥέοντα. τοῦ δὲ Ὤχου ποταμοῦ πλησίον ὀρύττοντας εὑρεῖν ἐλαίου πηγὴν λέγουσιν· εἰκὸς δέ, ὥσπερ νιτρώδη τινὰ καὶ στύφοντα ὑγρὰ καὶ ἀσφαλτώδη καὶ θειώδη διαρρεῖ τὴν γῆν, οὕτω καὶ λιπαρὰ εὑρίσκεσθαι, τὸ δὲ σπάνιον ποιεῖ τὴν παραδοξίαν. ῥεῖν δὲ τὸν Ὦχον οἱ μὲν διὰ τῆς Βακτριανῆς φασιν οἱ δὲ παρ’ αὐτήν, καὶ οἱ μὲν ἕτερον τοῦ Ὤξου μέχρι τῶν ἐκβολῶν νοτιώτερον ἐκείνου, ἀμφοτέρων δ’ ἐν τῇ Ὑρκανίᾳ τὰς εἰς τὴν θάλατταν ὑπάρχειν ἐκρύσεις, οἱ δὲ κατ’ ἀρχὰς μὲν ἕτερον συμβάλλειν δ’ εἰς ἓν τὸ τοῦ Ὤξου ῥεῖθρον, πολλαχοῦ καὶ ἓξ καὶ ἑπτὰ σταδίων ἔχοντα τὸ πλάτος. ὁ μέντοι Ἰαξάρτης ἀπ’ ἀρχῆς μέχρι τέλους ἕτερός ἐστι τοῦ Ὤξου, καὶ εἰς μὲν τὴν αὐτὴν τελευτῶν θάλατταν, αἱ δ’ ἐμβολαὶ διέχουσιν ἀλλήλων, ὥς φησι Πατροκλῆς, παρασάγγας ὡς ὀγδοήκοντα· τὸν δὲ παρασάγγην τὸν περσικὸν οἱ μὲν ἑξήκοντα σταδίων φασίν, οἱ δὲ τριάκοντα ἢ τετταράκοντα. ἀναπλεόντων δ’ ἡμῶν τὸν Νεῖλον ἄλλοτ’ ἄλλοις μέτροις χρώμενοι τὰς σχοίνους ὠνόμαζον ἀπὸ πόλεως ἐπὶ πόλιν, ὥστε τὸν αὐτὸν τῶν σχοίνων ἀριθμὸν ἀλλαχοῦ μὲν μείζω παρέχειν πλοῦν ἀλλαχοῦ δὲ βραχύτερον· οὕτως ἐξ ἀρχῆς παραδεδομένον καὶ φυλαττόμενον μέχρι νῦν.", "st": "11.11.5"}, {"sp": "N", "t": "μέχρι μὲν δὴ τῆς Σογδιανῆς πρὸς ἀνίσχοντα ἥλιον ἰόντι ἀπὸ τῆς Ὑρκανίας γνώριμα ὑπῆρξε τὰ ἔθνη καὶ τοῖς Πέρσαις πρότερον τὰ εἴσω τοῦ Ταύρου καὶ τοῖς Μακεδόσι μετὰ ταῦτα καὶ τοῖς Παρθυαίοις. τὰ δ’ ἐπέκεινα ἐπ’ εὐθείας ὅτι μὲν Σκυθικά ἐστιν, ἐκ τῆς ὁμοειδείας εἰκάζεται, στρατεῖαι δ’ οὐ γεγόνασιν ἐπ’ αὐτοὺς ἡμῖν γνώριμοι, καθάπερ οὐδὲ ἐπὶ τοὺς βορειοτάτους τῶν νομάδων, ἐφ’ οὓς ἐπεχείρησε μὲν ὁ Ἀλέξανδρος ἄγειν στρατείαν, ὅτε τὸν Βῆσσον μετῄει καὶ τὸν Σπιταμένην, ζωγρίᾳ δ’ ἀναχθέντος τοῦ Βήσσου, τοῦ δὲ Σπιταμένους ὑπὸ τῶν βαρβάρων διαφθαρέντος, ἐπαύσατο τῆς ἐπιχειρήσεως. οὐχ ὁμολογοῦσι δ’ ὅτι περιέπλευσάν τινες ἀπὸ τῆς Ἰνδικῆς ἐπὶ τὴν Ὑρκανίαν· ὅτι δὲ δυνατόν, Πατροκλῆς εἴρηκε.", "st": "11.11.6"}, {"sp": "N", "t": "λέγεται δὲ διότι τοῦ Ταύρου τὸ τελευταῖον, ὃ καλοῦσιν Ἴμαιον, τῇ Ἰνδικῇ θαλάττῃ ξυνάπτον, οὐδὲν οὔτε προὔχει πρὸς ἕω τῆς Ἰνδικῆς μᾶλλον οὔτ’ εἰσέχει· παριόντι δ’ εἰς τὸ βόρειον πλευρὸν ἀεί τι τοῦ μήκους ὑφαιρεῖ καὶ τοῦ πλάτους ἡ θάλαττα, ὥστ’ ἀποφαίνειν μύουρον πρὸς ἕω τὴν νῦν ὑπογραφομένην μερίδα τῆς Ἀσίας, ἣν ὁ Ταῦρος ἀπολαμβάνει πρὸς τὸν ὠκεανὸν τὸν πληροῦντα τὸ Κάσπιον πέλαγος. μῆκος δ’ ἐστὶ ταύτης τῆς μερίδος τὸ μέγιστον ἀπὸ τῆς Ὑρκανίας θαλάττης ἐπὶ τὸν ὠκεανὸν τὸν κατὰ τὸ Ἴμαιον τρισμυρίων που σταδίων, παρὰ τὴν ὀρεινὴν τοῦ Ταύρου τῆς πορείας οὔσης, πλάτος δ’ ἔλαττον τῶν μυρίων. εἴρηται γὰρ ὅτι περὶ τετρακισμυρίους σταδίους ἐστὶ τὸ ἀπὸ τοῦ Ἰσσικοῦ κόλπου μέχρι τῆς ἑῴας θαλάττης τῆς κατὰ Ἰνδούς, ἐπὶ δ’ Ἰσσὸν ἀπὸ τῶν ἑσπερίων ἄκρων τῶν κατὰ στήλας ἄλλοι τρισμύριοι· ἔστι δὲ ὁ μυχὸς τοῦ Ἰσσικοῦ κόλπου μικρὸν ἢ οὐδὲν Ἀμισοῦ ἑωθινώτερος, τὸ δὲ ἀπὸ Ἀμισοῦ ἐπὶ τὴν Ὑρκανίαν γῆν περὶ μυρίους ἐστὶ σταδίους, παράλληλον ὂν τῷ ἀπὸ τοῦ Ἰσσοῦ λεχθέντι ἐπὶ τοὺς Ἰνδούς. λείπεται δὴ τὸ λεχθὲν μῆκος ἐπὶ τὴν ἕω τῆς περιωδευμένης νυνὶ μερίδος οἱ τρισμύριοι στάδιοι. πάλιν δὲ τοῦ πλάτους τοῦ μεγίστου τῆς οἰκουμένης ὄντος περὶ τρισμυρίους σταδίους, χλαμυδοειδοῦς οὔσης, τὸ διάστημα τοῦτο ἐγγὺς ἂν εἴη τοῦ μεσημβρινοῦ τοῦ διὰ τῆς Ὑρκανίας θαλάττης γραφομένου καὶ τῆς Περσικῆς, εἴπερ ἐστὶ τὸ μῆκος τῆς οἰκουμένης ἑπτὰ μυριάδες· εἰ οὖν ἀπὸ τῆς Ὑρκανίας ἐπὶ Ἀρτεμίταν τὴν ἐν τῇ Βαβυλωνίᾳ στάδιοί εἰσιν ὀκτακισχίλιοι, καθάπερ εἴρηκεν Ἀπολλόδωρος ὁ ἐκ τῆς Ἀρτεμίτας, ἐκεῖθεν δ’ ἐπὶ τὸ στόμα τῆς κατὰ Πέρσας θαλάττης ἄλλο τοσοῦτόν ἐστι, καὶ πάλιν τοσοῦτον ἢ μικρὸν ἀπολεῖπον εἰς τὰ ἀνταίροντα τοῖς ἄκροις τῆς Αἰθιοπίας, λοιπὸν ἂν εἴη τοῦ πλάτους τῆς οἰκουμένης τοῦ λεχθέντος ἀπὸ τοῦ μυχοῦ τῆς Ὑρκανίας θαλάττης ἐπὶ τοῦ στόματος αὐτῆς ὅσον εἰρήκαμεν. μυούρου δ’ ὄντος τοῦ τμήματος τούτου τῆς γῆς ἐπὶ τὰ πρὸς ἕω μέρη, γίνοιτ’ ἂν τὸ σχῆμα προσόμοιον μαγειρικῇ κοπίδι, τοῦ μὲν ὄρους ἐπ’ εὐθείας ὄντος καὶ νοουμένου κατὰ τὴν ἀκμὴν τῆς κοπίδος, τῆς δ’ ἀπὸ τοῦ στόματος τοῦ Ὑρκανίου παραλίας ἐπὶ Τάμαρον κατὰ θάτερον πλευρὸν εἰς περιφερῆ καὶ μύουρον γραμμὴν ἀπολῆγον.", "st": "11.11.7"}, {"sp": "N", "t": "ἐπιμνηστέον δὲ καὶ τῶν παραδόξων ἐνίων ἃ θρυλοῦσι περὶ τῶν τελέως βαρβάρων, οἷον τῶν περὶ τὸν Καύκασον καὶ τὴν ἄλλην ὀρεινήν. τοῖς μὲν γὰρ νόμιμον εἶναί φασι τὸ τοῦ Εὐριπίδου<br>τὸν φύντα θρηνεῖν εἰς ὅσ’ ἔρχεται κακά,<br>τὸν δ’ αὖ θανόντα καὶ πόνων πεπαυμένον<br>χαίροντας εὐφημοῦντας ἐκπέμπειν δόμων.<br>ἑτέροις δὲ μηδένα ἀποκτείνειν τῶν ἐξαμαρτόντων τὰ μέγιστα, ἀλλ’ ἐξορίζειν μόνον μετὰ τῶν τέκνων, ὑπεναντίως τοῖς Δέρβιξι· καὶ γὰρ ἐπὶ μικροῖς οὗτοι σφάττουσι. σέβονται δὲ γῆν οἱ Δέρβικες· θύουσι δ’ οὐδὲν θῆλυ οὐδὲ ἐσθίουσι· τοὺς δὲ ὑπὲρ ἑβδομήκοντα ἔτη γεγονότας σφάττουσιν, ἀναλίσκουσι δὲ τὰς σάρκας οἱ ἄγχιστα γένους· τὰς δὲ γραίας ἀπάγχουσιν, εἶτα θάπτουσι· τοὺς δὲ ἐντὸς ἑβδομήκοντα ἐτῶν ἀποθανόντας οὐκ ἐσθίουσιν ἀλλὰ θάπτουσι. Σίγιννοι δὲ τἆλλα μὲν περσίζουσιν, ἱππαρίοις δὲ χρῶνται μικροῖς δασέσιν, ἅπερ ἱππότην ὀχεῖν μὲν οὐ δύναται, τέθριππα δὲ ζευγνύουσιν· ἡνιοχοῦσι δὲ γυναῖκες ἐκ παίδων ἠσκημέναι, ἡ δ’ ἄριστα ἡνιοχοῦσα συνοικεῖ ᾧ βούλεται· τινὰς δ’ ἐπιτηδεύειν φασὶν ὅπως ὡς μακροκεφαλώτατοι φανοῦνται καὶ προπεπτωκότες τοῖς μετώποις ὥσθ’ ὑπερκύπτειν τῶν γενείων. Ταπύρων δ’ ἔστι καὶ τὸ τοὺς μὲν ἄνδρας μελανειμονεῖν καὶ μακροκομεῖν, τὰς δὲ γυναῖκας λευχειμονεῖν καὶ βραχυκομεῖν. καὶ ὁ ἀνδρειότατος κριθεὶς γαμεῖ ἣν βούλεται. Κάσπιοι δὲ τοὺς ὑπὲρ ἑβδομήκοντα ἔτη λιμοκτονήσαντες εἰς τὴν ἐρημίαν ἐκτιθέασιν, ἄπωθεν δὲ σκοπεύοντες ἐὰν μὲν ὑπ’ ὀρνίθων κατασπωμένους ἀπὸ τῆς κλίνης ἴδωσιν, εὐδαιμονίζουσιν, ἐὰν δὲ ὑπὸ θηρίων ἢ κυνῶν, ἧττον, ἐὰν δ’ ὑπὸ μηδενός, κακοδαιμονίζουσι.", "st": "11.11.8"}, {"sp": "N", "t": "ἐπεὶ δὲ τὰ βόρεια μέρη τῆς Ἀσίας ποιεῖ ὁ Ταῦρος, ἃ δὴ καὶ ἐντὸς τοῦ Ταύρου καλοῦσιν, εἰπεῖν προειλόμεθα πρῶτον [περὶ τούτων]· τούτων δ’ ἐστὶ καὶ τὰ ἐν τοῖς ὄρεσιν αὐτοῖς ἢ ὅλα ἢ τὰ πλεῖστα. ὅσα μὲν [οὖν] τῶν Κασπίων πυλῶν ἑωθινώτερά ἐστιν, ἁπλουστέραν ἔχει τὴν περιήγησιν διὰ τὴν ἀγριότητα, οὐ πολύ τε ἂν διαφέροι τοῦδε ἢ τοῦδε τοῦ κλίματος συγκαταλεχθέντα· τὰ δ’ ἑσπέρια πάντα δίδωσιν εὐπορίαν τοῦ λέγειν περὶ αὐτῶν, ὥστε δεῖ προάγειν ἐπὶ τὰ παρακείμενα ταῖς Κασπίαις πύλαις. παράκειται δὲ ἡ Μηδία πρὸς δύσιν, χώρα καὶ πολλὴ καὶ δυναστεύσασά ποτε καὶ ἐν μέσῳ τῷ Ταύρῳ κειμένη, πολυσχιδεῖ κατὰ ταῦτα ὑπάρχοντι τὰ μέρη καὶ αὐλῶνας ἐμπεριλαμβάνοντι μεγάλους, καθάπερ καὶ τῇ Ἀρμενίᾳ τοῦτο συμβέβηκε.", "st": "11.12.1"}, {"sp": "N", "t": "τὸ γὰρ ὄρος τοῦτο ἄρχεται μὲν ἀπὸ τῆς Καρίας καὶ Λυκίας, ἀλλ’ ἐνταῦθα μὲν οὔτε πλάτος οὔτε ὕψος ἀξιόλογον δείκνυσιν· ἐξαίρεται δὲ πολὺ πρῶτον κατὰ τὰς Χελιδονίας (αὗται δ’ εἰσὶ νῆσοι κατὰ τὴν ἀρχὴν τῆς Παμφύλων παραλίας), ἐπὶ δὲ τὰς ἀνατολὰς ἐκτεινόμενον αὐλῶνας μακροὺς ἀπολαμβάνει τοὺς τῶν Κιλίκων· εἶτα τῇ μὲν τὸ Ἀμανὸν ἀπ’ αὐτοῦ σχίζεται τῇ δὲ ὁ Ἀντίταυρος, ἐν ᾧ τὰ Κόμανα ἵδρυται τὰ ἐν τοῖς ἄνω λεγομένοις Καππάδοξιν. οὗτος μὲν οὖν ἐν τῇ Καταονίᾳ τελευτᾷ, τὸ δὲ Ἀμανὸν ὄρος μέχρι τοῦ Εὐφράτου καὶ τῆς Μελιτηνῆς πρόεισι, καθ’ ἣν ἡ Κομμαγηνὴ τῇ Καππαδοκίᾳ παράκειται· ἐκδέχεται δὲ τὰ πέραν τοῦ Εὐφράτου ὄρη, συνεχῆ μὲν τοῖς προειρημένοις πλὴν ὅσον διακόπτει ῥέων διὰ μέσων ὁ ποταμός, πολλὴν δ’ ἐπίδοσιν λαμβάνει εἰς τὸ ὕψος καὶ τὸ πλάτος καὶ τὸ πολυσχιδές. τὸ δ’ οὖν νοτιώτατον μάλιστά ἐστιν ὁ Ταῦρος ὁρίζων τὴν Ἀρμενίαν ἀπὸ τῆς Μεσοποταμίας.", "st": "11.12.2"}, {"sp": "N", "t": "ἐντεῦθεν δὲ ἀμφότεροι ῥέουσιν οἱ τὴν Μεσοποταμίαν ἐγκυκλούμενοι ποταμοὶ καὶ συνάπτοντες ἀλλήλοις ἐγγὺς κατὰ τὴν Βαβυλωνίαν, εἶτα ἐκδιδόντες εἰς τὴν κατὰ Πέρσας θάλατταν, ὅ τε Εὐφράτης καὶ Τίγρις. ἔστι δὲ καὶ μείζων ὁ Εὐφράτης καὶ πλείω διέξεισι χώραν σκολιῷ τῷ ῥείθρῳ, τὰς πηγὰς ἔχων ἐν τῷ προσβορείῳ μέρει τοῦ Ταύρου, ῥέων δ’ ἐπὶ δύσιν διὰ τῆς Ἀρμενίας τῆς μεγάλης καλουμένης μέχρι τῆς μικρᾶς, ἐν δεξιᾷ ἔχων ταύτην ἐν ἀριστερᾷ δὲ τὴν Ἀκιλισηνήν· εἶτ’ ἐπιστρέφει πρὸς νότον, συνάπτει δὲ κατὰ τὴν ἐπιστροφὴν τοῖς Καππαδόκων ὁρίοις· δεξιᾷ δὲ ταῦτα ἀφεὶς καὶ τὰ τῶν Κομμαγηνῶν, ἀριστερᾷ δὲ τὴν Ἀκιλισηνὴν καὶ Σωφηνὴν τῆς μεγάλης Ἀρμενίας πρόεισιν ἐπὶ τὴν Συρίαν καὶ λαμβάνει πάλιν ἄλλην ἐπιστροφὴν εἰς τὴν Βαβυλωνίαν καὶ τὸν Περσικὸν κόλπον. ὁ δὲ Τίγρις ἐκ τοῦ νοτίου μέρους τοῦ αὐτοῦ ὄρους ἐνεχθεὶς ἐπὶ τὴν Σελεύκειαν συνάπτει τῷ Εὐφράτῃ πλησίον καὶ ποιεῖ τὴν Μεσοποταμίαν πρὸς αὐτόν, εἶτ’ ἐκδίδωσι καὶ αὐτὸς εἰς τὸν αὐτὸν κόλπον. διέχουσι δὲ ἀλλήλων αἱ πηγαὶ τοῦ τε Εὐφράτου καὶ τοῦ Τίγριος περὶ δισχιλίους καὶ πεντακοσίους σταδίους.", "st": "11.12.3"}, {"sp": "N", "t": "ἀπὸ δ’ οὖν τοῦ Ταύρου πρὸς ἄρκτον ἀποσχίδες πολλαὶ γεγόνασι, μία μὲν ἡ τοῦ καλουμένου Ἀντιταύρου· καὶ γὰρ ἐνταῦθα οὕτως ὠνομάζετο ὁ τὴν Σωφηνὴν ἀπολαμβάνων ἐν αὐλῶνι μεταξὺ κειμένῳ αὐτοῦ τε καὶ τοῦ Ταύρου. πέραν δὲ τοῦ Εὐφράτου κατὰ τὴν μικρὰν Ἀρμενίαν ἐφεξῆς τῷ Ἀντιταύρῳ πρὸς ἄρκτον ἐπεκτείνεται μέγα ὄρος καὶ πολυσχιδές· καλοῦσι δὲ τὸ μὲν αὐτοῦ Παρυάδρην τὸ δὲ Μοσχικὰ ὄρη τὸ δ’ ἄλλοις ὀνόμασι· ταῦτα δ’ ἀπολαμβάνει τὴν Ἀρμενίαν ὅλην μέχρι Ἰβήρων καὶ Ἀλβανῶν. εἶτ’ ἄλλ’ ἐπανίσταται πρὸς ἕω, τὰ ὑπερκείμενα τῆς Κασπίας θαλάττης μέχρι Μηδίας τῆς τε Ἀτροπατίου καὶ τῆς μεγάλης· καλοῦσι δὲ καὶ ταῦτα τὰ μέρη πάντα τῶν ὀρῶν Παραχοάθραν καὶ τὰ μέχρι τῶν Κασπίων πυλῶν καὶ ἐπέκεινα ἔτι πρὸς ταῖς ἀνατολαῖς τὰ συνάπτοντα τῇ Ἀρίᾳ. τὰ μὲν δὴ πρόσβορρα ὄρη οὕτω καλοῦσι, τὰ δὲ νότια τὰ πέραν τοῦ Εὐφράτου τῆς Καππαδοκίας καὶ τῆς Κομμαγηνῆς πρὸς ἕω τείνοντα κατ’ ἀρχὰς μὲν αὐτὸ τοῦτο καλεῖται Ταῦρος, διορίζων τὴν Σωφηνὴν καὶ τὴν ἄλλην Ἀρμενίαν ἀπὸ τῆς Μεσοποταμίας· τινὲς δὲ Γορδυαῖα ὄρη καλοῦσιν. ἐν δὲ τούτοις ἐστὶ καὶ τὸ Μάσιον, τὸ ὑπερκείμενον τῆς Νισίβιος ὄρος καὶ τῶν Τιγρανοκέρτων. ἔπειτα ἐξαίρεται πλέον καὶ καλεῖται Νιφάτης· ἐνταῦθα δέ που καὶ τοῦ Τίγριος πηγαὶ κατὰ τὸ νότιον τῆς ὀρεινῆς πλευρόν· εἶτ’ ἀπὸ τοῦ Νιφάτου μᾶλλον ἔτι καὶ μᾶλλον ἡ ῥάχις ἐκτεινομένη τὸ Ζάγριον ὄρος ποιεῖ τὸ διορίζον τὴν Μηδίαν καὶ τὴν Βαβυλωνίαν· μετὰ δὲ τὸ Ζάγριον ἐκδέχεται ὑπὲρ μὲν τῆς Βαβυλωνίας ἥ τε τῶν Ἐλυμαίων ὀρεινὴ καὶ ἡ τῶν Παραιτακηνῶν, ὑπὲρ δὲ τῆς Μηδίας ἡ τῶν Κοσσαίων· ἐν μέσῳ δ’ ἐστὶν ἡ Μηδία καὶ ἡ Ἀρμενία, πολλὰ μὲν ὄρη περιλαμβάνουσα πολλὰ δὲ ὀροπέδια, ὡσαύτως δὲ πεδία καὶ αὐλῶνας μεγάλους, συχνὰ δὲ καὶ ἔθνη τὰ περιοικοῦντα, μικρὰ ὀρεινὰ καὶ λῃστρικὰ τὰ πλείω. οὕτω μὲν τοίνυν τίθεμεν ἐντὸς τοῦ Ταύρου τήν τε Μηδίαν, ἧς εἰσι καὶ αἱ Κάσπιοι πύλαι, καὶ τὴν Ἀρμενίαν.", "st": "11.12.4"}, {"sp": "N", "t": "καθ’ ἡμᾶς μὲν τοίνυν προσάρκτια ἂν εἴη τὰ ἔθνη ταῦτα, ἐπειδὴ καὶ ἐντὸς τοῦ Ταύρου, Ἐρατοσθένης δὲ πεποιημένος τὴν διαίρεσιν εἰς τὰ νότια μέρη καὶ τὰ προσάρκτια καὶ τὰς ὑπ’ αὐτοῦ λεγομένας σφραγῖδας, τὰς μὲν βορείους καλῶν τὰς δὲ νοτίους, ὅρια ἀποφαίνει τῶν κλιμάτων ἀμφοῖν τὰς Κασπίους πύλας· εἰκότως οὖν τὰ νοτιώτερα τῶν Κασπίων πυλῶν νότια ἂν ἀποφαίνοι, ὧν ἐστι καὶ ἡ Μηδία καὶ ἡ Ἀρμενία, τὰ δὲ βορειότερα πρόσβορρα, κατ’ ἄλλην καὶ ἄλλην διάταξιν τούτου συμβαίνοντος. τάχα δὲ οὐκ ἐπέβαλε τούτῳ, διότι ἔξω τοῦ Ταύρου πρὸς νότον οὐδέν ἐστιν οὔτε τῆς Ἀρμενίας μέρος οὔτε τῆς Μηδίας.", "st": "11.12.5"}, {"sp": "N", "t": "ἡ δὲ Μηδία δίχα διῄρηται· καλοῦσι δὲ τὴν μὲν μεγάλην, ἧς μητρόπολις τὰ Ἐκβάτανα, μεγάλη πόλις καὶ τὸ βασίλειον ἔχουσα τῆς Μήδων ἀρχῆς· διατελοῦσι δὲ καὶ νῦν οἱ Παρθυαῖοι τούτῳ χρώμενοι βασιλείῳ, καὶ θερίζουσί γε ἐνταῦθα οἱ βασιλεῖς· ψυχρὰ γὰρ ἡ Μηδία· τὸ δὲ χειμάδιόν ἐστιν αὐτοῖς ἐν Σελευκείᾳ τῇ ἐπὶ τῷ Τίγριδι πλησίον Βαβυλῶνος. ἡ δ’ ἑτέρα μερίς ἐστιν ἡ Ἀτροπάτιος Μηδία· τοὔνομα δ’ ἔσχεν ἀπὸ τοῦ ἡγεμόνος Ἀτροπάτου, ὃς ἐκώλυσεν ὑπὸ τοῖς Μακεδόσι γίνεσθαι καὶ ταύτην μέρος οὖσαν μεγάλης Μηδίας· καὶ δὴ καὶ βασιλεὺς ἀναγορευθεὶς ἰδίᾳ συνέταξε καθ’ αὑτὴν τὴν χώραν ταύτην, καὶ ἡ διαδοχὴ σώζεται μέχρι νῦν ἐξ ἐκείνου, πρός τε τοὺς Ἀρμενίων βασιλέας ποιησαμένων ἐπιγαμίας τῶν ὕστερον καὶ Σύρων καὶ μετὰ ταῦτα Παρθυαίων.", "st": "11.13.1"}, {"sp": "N", "t": "κεῖται δὲ ἡ χώρα τῇ μὲν Ἀρμενίᾳ πρὸς ἕω τῇ δὲ μεγάλῃ Μηδίᾳ πρὸς δύσιν, πρὸς ἄρκτον δ’ ἀμφοτέραις· τοῖς δὲ περὶ τὸν μυχὸν τῆς Ὑρκανίας θαλάττης καὶ τῇ Ματιανῇ ἀπὸ νότου παράκειται. ἔστι δ’ οὐ μικρὰ κατὰ τὴν δύναμιν, ὥς φησιν Ἀπολλωνίδης, ἥ γε καὶ μυρίους ἱππέας δύναται παρέχεσθαι, πεζῶν δὲ τέτταρας μυριάδας. λίμνην δ’ ἔχει τὴν Καπαῦτα, ἐν ᾗ ἅλες ἐπανθοῦντες πήττονται· εἰσὶ δὲ κνησμώδεις καὶ ἐπαλγεῖς· ἔλαιον δὲ τοῦ πάθους ἄκος, ὕδωρ δὲ γλυκὺ τοῖς καπυρωθεῖσιν ἱματίοις, εἴ τις κατ’ ἄγνοιαν βάψειεν εἰς αὐτὴν πλύσεως χάριν. ἔχουσι δ’ ἰσχυροὺς γείτονας τοὺς Ἀρμενίους καὶ τοὺς Παρθυαίους, ὑφ’ ὧν περικόπτονται πολλάκις· ἀντέχουσι δ’ ὅμως καὶ ἀπολαμβάνουσι τὰ ἀφαιρεθέντα, καθάπερ τὴν Συμβάκην ἀπέλαβον παρὰ τῶν Ἀρμενίων ὑπὸ Ῥωμαίοις γεγονότων, καὶ αὐτοὶ προσεληλύθασι τῇ φιλίᾳ τῇ πρὸς Καίσαρα· θεραπεύουσι δ’ ἅμα καὶ τοὺς Παρθυαίους.", "st": "11.13.2"}, {"sp": "N", "t": "βασίλειον δ’ αὐτῶν θερινὸν μὲν ἐν πεδίῳ ἱδρυμένον Γάζακα, [χειμερινὸν δὲ] ἐν φρουρίῳ ἐρυμνῷ Ὀυέρα, ὅπερ Ἀντώνιος ἐπολιόρκησε κατὰ τὴν ἐπὶ Παρθυαίους στρατείαν. διέχει δὲ τοῦτο τοῦ Ἀράξου ποταμοῦ τοῦ ὁρίζοντος τήν τε Ἀρμενίαν καὶ τὴν Ἀτροπατηνὴν σταδίους δισχιλίους καὶ τετρακοσίους, ὥς φησιν ὁ Δέλλιος ὁ τοῦ Ἀντωνίου φίλος, συγγράψας τὴν ἐπὶ Παρθυαίους αὐτοῦ στρατείαν ἐν ᾗ παρῆν καὶ αὐτὸς ἡγεμονίαν ἔχων. ἔστι δὲ τῆς χώρας ταύτης τὰ μὲν ἄλλα εὐδαίμονα χωρία, ἡ δὲ προσάρκτιος ὀρεινὴ καὶ τραχεῖα καὶ ψυχρά, Καδουσίων κατοικία τῶν ὀρεινῶν καὶ Ἀμάρδων καὶ Ταπύρων καὶ Κυρτίων καὶ ἄλλων τοιούτων, οἳ μετανάσται εἰσὶ καὶ λῃστρικοί. καὶ γὰρ ὁ Ζάγρος καὶ ὁ Νιφάτης κατεσπαρμένα ἔχουσι τὰ ἔθνη ταῦτα, καὶ οἱ ἐν τῇ Περσίδι Κύρτιοι καὶ Μάρδοι (καὶ γὰρ οὕτω λέγονται οἱ Ἄμαρδοι) καὶ οἱ ἐν τῇ Ἀρμενίᾳ μέχρι νῦν ὁμωνύμως προσαγορευόμενοι τῆς αὐτῆς εἰσὶν ἰδέας.", "st": "11.13.3"}, {"sp": "N", "t": "οἱ δ’ οὖν Καδούσιοι πλήθει τῷ πεζῷ μικρὸν ἀπολείπονται τῶν Ἀριανῶν, ἀκοντισταὶ δ’ εἰσὶν ἄριστοι, ἐν δὲ τοῖς τραχέσιν ἀνθ’ ἱππέων πεζοὶ διαμάχονται. Ἀντωνίῳ δὲ χαλεπὴν τὴν στρατείαν ἐποίησεν οὐχ ἡ τῆς χώρας φύσις, ἀλλ’ ὁ τῶν ὁδῶν ἡγεμών, ὁ τῶν Ἀρμενίων βασιλεὺς Ἀρταουάσδης, ὃν εἰκῆ ἐκεῖνος ἐπιβουλεύοντα αὐτῷ σύμβουλον ἐποιεῖτο καὶ κύριον τῆς περὶ τοῦ πολέμου γνώμης· ἐτιμωρήσατο μὲν οὖν αὐτόν, ἀλλ’ ὀψέ, ἡνίκα πολλῶν αἴτιος κατέστη κακῶν Ῥωμαίοις καὶ αὐτὸς καὶ ἐκεῖνος, ὅστις τὴν ἀπὸ τοῦ Ζεύγματος ὁδὸν τοῦ κατὰ τὸν Εὐφράτην μέχρι τοῦ ἅψασθαι τῆς Ἀτροπατηνῆς ὀκτακισχιλίων σταδίων ἐποίησε, πλέον ἢ διπλασίαν τῆς εὐθείας, διὰ ὀρῶν καὶ ἀνοδιῶν καὶ κυκλοπορίας.", "st": "11.13.4"}, {"sp": "N", "t": "ἡ δὲ μεγάλη Μηδία τὸ μὲν παλαιὸν τῆς Ἀσίας ἡγήσατο πάσης καταλύσασα τὴν τῶν Σύρων ἀρχήν· ὕστερον δ’ ὑπὸ Κύρου καὶ Περσῶν ἀφαιρεθεῖσα τὴν τοσαύτην ἐξουσίαν ἐπὶ Ἀστυάγου διεφύλαττεν ὅμως πολὺ τοῦ πατρίου ἀξιώματος, καὶ ἦν τὰ Ἐκβάτανα χειμάδιον τοῖς Πέρσαις· ὁμοίως δὲ καὶ τοῖς ἐκείνους καταλύσασι Μακεδόσι τοῖς τὴν Συρίαν ἔχουσι, καὶ νῦν ἔτι τοῖς Παρθυαίων βασιλεῦσι τὴν αὐτὴν παρέχεται χρείαν τε καὶ ἀσφάλειαν.", "st": "11.13.5"}, {"sp": "N", "t": "ὁρίζεται δ’ ἀπὸ μὲν τῆς ἕω τῇ τε Παρθυαίᾳ καὶ τοῖς Κοσσαίων ὄρεσι λῃστρικῶν ἀνθρώπων, οἳ τοξότας μυρίους καὶ τρισχιλίους παρέσχοντό ποτε Ἐλυμαίοις συμμαχοῦντες ἐπὶ Σουσίους καὶ Βαβυλωνίους. Νέαρχος δέ φησι τεττάρων ὄντων λῃστρικῶν ἐθνῶν, ὧν Μάρδοι μὲν Πέρσαις προσεχεῖς ἦσαν, Οὔξιοι δὲ καὶ Ἐλυμαῖοι τούτοις τε καὶ Σουσίοις, Κοσσαῖοι δὲ Μήδοις, πάντας μὲν φόρους πράττεσθαι τοὺς βασιλέας, Κοσσαίους δὲ καὶ δῶρα λαμβάνειν, ἡνίκα ὁ βασιλεὺς θερίσας ἐν Ἐκβατάνοις εἰς τὴν Βαβυλωνίαν καταβαίνοι· καταλῦσαι δ’ αὐτῶν τὴν πολλὴν τόλμαν Ἀλέξανδρον ἐπιθέμενον χειμῶνος. τούτοις τε δὴ ἀφορίζεται πρὸς ἕω καὶ ἔτι τοῖς Παραιτακηνοῖς, οἳ συνάπτουσι Πέρσαις ὀρεινοὶ καὶ αὐτοὶ καὶ λῃστρικοί· ἀπὸ δὲ τῶν ἄρκτων τοῖς ὑπεροικοῦσι τῆς Ὑρκανίας θαλάττης Καδουσίοις καὶ τοῖς ἄλλοις, οὓς ἄρτι διήλθομεν· πρὸς νότον δὲ τῇ Ἀπολλωνιάτιδι, ἣν Σιτακηνὴν ἐκάλουν οἱ παλαιοί, καὶ τῷ Ζάγρῳ, καθ’ ὃ ἡ Μασσαβατικὴ κεῖται τῆς Μηδίας οὖσα, οἱ δὲ τῆς Ἐλυμαίας φασί· πρὸς δύσιν δὲ τοῖς Ἀτροπατίοις καὶ τῶν Ἀρμενίων τισίν. εἰσὶ δὲ καὶ Ἑλληνίδες πόλεις κτίσματα τῶν Μακεδόνων ἐν τῇ Μηδίᾳ, ὧν Λαοδίκειά τε καὶ Ἀπάμεια καὶ ἡ πρὸς Ῥάγαις [Ἡράκλεια] καὶ αὐτὴ Ῥάγα, τὸ τοῦ Νικάτορος κτίσμα, ὃ ἐκεῖνος μὲν Εὐρωπὸν ὠνόμασε, Πάρθοι δὲ Ἀρσακίαν, νοτιωτέραν οὖσαν τῶν Κασπίων πυλῶν πεντακοσίοις που σταδίοις, ὥς φησιν Ἀπολλόδωρος Ἀρτεμιτηνός.", "st": "11.13.6"}, {"sp": "N", "t": "ἡ πολλὴ μὲν οὖν ὑψηλή ἐστι καὶ ψυχρά· τοιαῦτα δὲ καὶ τὰ ὑπερκείμενα τῶν Ἐκβατάνων ὄρη καὶ τὰ περὶ τὰς Ῥάγας καὶ τὰς Κασπίους πύλας καὶ καθόλου τὰ προσάρκτια μέρη τὰ ἐντεῦθεν μέχρι πρὸς τὴν Ματιανὴν καὶ τὴν Ἀρμενίαν. ἡ δ’ ὑπὸ ταῖς Κασπίοις πύλαις ἐν ταπεινοῖς ἐδάφεσι καὶ κοίλοις οὖσα εὐδαίμων σφόδρα ἐστὶ καὶ πάμφορος πλὴν ἐλαίας· εἰ δὲ καὶ φύεταί που, ἀλιπής τέ ἐστι καὶ ξηρά· ἱππόβοτος δὲ καὶ αὕτη ἐστὶ διαφερόντως καὶ ἡ Ἀρμενία· καλεῖται δέ τις καὶ λειμὼν ἱππόβοτος, ὃν καὶ διεξίασιν οἱ ἐκ τῆς Περσίδος καὶ Βαβυλῶνος εἰς Κασπίους πύλας ὁδεύοντες, ἐν ᾧ πέντε μυριάδας ἵππων θηλείων νέμεσθαί φασιν ἐπὶ τῶν Περσῶν, εἶναι δὲ τὰς ἀγέλας ταύτας βασιλικάς. τοὺς δὲ Νησαίους ἵππους, οἷς ἐχρῶντο οἱ βασιλεῖς ἀρίστοις οὖσι καὶ μεγίστοις, οἱ μὲν ἐνθένδε λέγουσι τὸ γένος, οἱ δ’ ἐξ Ἀρμενίας· ἰδιόμορφοι δέ εἰσιν, ὥσπερ καὶ οἱ Παρθικοὶ λεγόμενοι νῦν, παρὰ τοὺς Ἑλλαδικοὺς καὶ τοὺς ἄλλους τοὺς παρ’ ἡμῖν. καὶ τὴν βοτάνην δὲ τὴν μάλιστα τρέφουσαν τοὺς ἵππους ἀπὸ τοῦ πλεονάζειν ἐνταῦθα ἰδίως μηδίκην καλοῦμεν. φέρει δὲ καὶ σίλφιον ἡ χώρα, ἀφ’ οὗ ὁ Μηδικὸς καλούμενος ὀπός, πολὺ λειπόμενος τοῦ Κυρηναϊκοῦ· ἔστι δ’ ὅτε καὶ διαφέρων ἐκείνου, εἴτε παρὰ τὰς τῶν τόπων διαφορὰς εἴτε τοῦ φυτοῦ κατ’ εἶδος ἐξαλλάττοντος, εἴτε καὶ παρὰ τοὺς ὀπίζοντας καὶ σκευάζοντας ὥστε συμμένειν πρὸς τὴν ἀπόθεσιν καὶ τὴν χρείαν.", "st": "11.13.7"}, {"sp": "N", "t": "τοιαύτη μέν τις ἡ χώρα· τὸ δὲ μέγεθος πάρισός πώς ἐστιν εἰς πλάτος καὶ μῆκος· δοκεῖ δὲ μέγιστον εἶναι μῆκος τῆς Μηδίας τὸ ἀπὸ τῆς τοῦ Ζάγρου ὑπερθέσεως, ἥπερ καλεῖται Μηδικὴ πύλη, εἰς Κασπίους πύλας διὰ τῆς Σιγριανῆς σταδίων τετρακισχιλίων ἑκατόν. τῷ δὲ μεγέθει καὶ τῇ δυνάμει τῆς χώρας ὁμολογεῖ καὶ ἡ περὶ τῶν φόρων ἱστορία· τῆς γὰρ Καππαδοκίας παρεχούσης τοῖς Πέρσαις κατ’ ἐνιαυτὸν πρὸς τῷ ἀργυρικῷ τέλει ἵππους χιλίους καὶ πεντακοσίους, ἡμιόνους δὲ δισχιλίους, προβάτων δὲ πέντε μυριάδας, διπλάσια σχεδόν τι τούτων ἐτέλουν οἱ Μῆδοι.", "st": "11.13.8"}, {"sp": "N", "t": "ἔθη δὲ τὰ πολλὰ μὲν τὰ αὐτὰ τούτοις τε καὶ τοῖς Ἀρμενίοις διὰ τὸ καὶ τὴν χώραν παραπλησίαν εἶναι. τοὺς μέντοι Μήδους ἀρχηγέτας εἶναί φασι καὶ τούτοις καὶ ἔτι πρότερον Πέρσαις τοῖς ἔχουσιν αὐτοὺς καὶ διαδεξαμένοις τὴν τῆς Ἀσίας ἐξουσίαν. ἡ γὰρ νῦν λεγομένη Περσικὴ στολὴ καὶ ὁ τῆς τοξικῆς καὶ ἱππικῆς ζῆλος καὶ ἡ περὶ τοὺς βασιλέας θεραπεία καὶ κόσμος καὶ σεβασμὸς θεοπρεπὴς παρὰ τῶν ἀρχομένων εἰς τοὺς Πέρσας παρὰ Μήδων ἀφῖκται. καὶ ὅτι τοῦτ’ ἀληθὲς ἐκ τῆς ἐσθῆτος μάλιστα δῆλον· τιάρα γάρ τις καὶ κίταρις καὶ πῖλος καὶ χειριδωτοὶ χιτῶνες καὶ ἀναξυρίδες ἐν μὲν τοῖς ψυχροῖς τόποις καὶ προσβόρροις ἐπιτήδειά ἐστι φορήματα, οἷοί εἰσιν οἱ Μηδικοί, ἐν δὲ τοῖς νοτίοις ἥκιστα· οἱ δὲ Πέρσαι τὴν πλείστην οἴκησιν ἐπὶ τῇ Ἐρυθρᾷ θαλάττῃ κέκτηνται, μεσημβρινώτεροι καὶ Βαβυλωνίων ὄντες καὶ Σουσίων· μετὰ δὲ τὴν κατάλυσιν τὴν τῶν Μήδων προσεκτήσαντό τινα καὶ τῶν προσαπτομένων Μηδίᾳ. ἀλλ’ οὕτως ἐφάνη σεμνὰ καὶ τοῦ βασιλικοῦ προσχήματος οἰκεῖα τὰ ἔθη τοῖς νικήσασι τὰ τῶν νικηθέντων, ὥστ’ ἀντὶ γυμνητῶν καὶ ψιλῶν θηλυστολεῖν ὑπέμειναν, καὶ κατηρεφεῖς εἶναι τοῖς σκεπάσμασι.", "st": "11.13.9"}, {"sp": "N", "t": "τινὲς δὲ Μήδειαν καταδεῖξαι τὴν ἐσθῆτα ταύτην φασὶ δυναστεύσασαν ἐν τοῖς τόποις, καθάπερ καὶ Ἰάσονα, καὶ ἐπικρυπτομένην τὴν ὄψιν ὅτε ἀντὶ τοῦ βασιλέως ἐξίοι· τοῦ μὲν [οὖν] Ἰάσονος ὑπομνήματα εἶναι τὰ Ἰασόνια ἡρῷα τιμώμενα σφόδρα ὑπὸ τῶν βαρβάρων (ἔστι δὲ καὶ ὄρος μέγα ὑπὲρ τῶν Κασπίων πυλῶν ἐν ἀριστερᾷ καλούμενον Ἰασόνιον), τῆς δὲ Μηδείας τὴν ἐσθῆτα καὶ τοὔνομα τῆς χώρας. λέγεται δὲ καὶ Μῆδος υἱὸς αὐτῆς διαδέξασθαι τὴν ἀρχὴν καὶ τὴν χώραν ἐπώνυμον αὑτοῦ καταλιπεῖν. ὁμολογεῖ δὲ τούτοις καὶ τὰ κατὰ τὴν Ἀρμενίαν Ἰασόνια καὶ τὸ τῆς χώρας ὄνομα καὶ ἄλλα πλείω περὶ ὧν ἐροῦμεν.", "st": "11.13.10"}, {"sp": "N", "t": "καὶ τοῦτο δὲ Μηδικὸν τὸ βασιλέα αἱρεῖσθαι τὸν ἀνδρειότατον, ἀλλ’ οὐ πᾶσιν ἀλλὰ τοῖς ὀρείοις· μᾶλλον δὲ τὸ τοῖς βασιλεῦσιν πολλὰς εἶναι γυναῖκας· τοῖς δ’ ὀρείοις τῶν Μήδων καὶ πᾶσιν ἔθος τοῦτο, ἐλάττους δὲ τῶν πέντε οὐκ ἔξεστιν· ὡς δ’ αὕτως τὰς γυναῖκάς φασιν ἐν καλῷ τίθεσθαι ὅτι πλείστους νέμειν ἄνδρας, τῶν πέντε δὲ ἐλάττους συμφορὰν ἡγεῖσθαι. τῆς δ’ ἄλλης Μηδίας εὐδαιμονούσης τελέως λυπρά ἐστιν ἡ προσάρκτιος ὀρεινή· σιτοῦνται γοῦν ἀπὸ ἀκροδρύων, ἔκ τε μήλων ξηρῶν κοπέντων ποιοῦνται μάζας, ἀπὸ δ’ ἀμυγδάλων φωχθέντων ἄρτους, ἐκ δὲ ῥιζῶν τινων οἶνον ἐκθλίβουσι, κρέασι δὲ χρῶνται θηρείοις, ἥμερα δὲ οὐ τρέφουσι θρέμματα. τοσαῦτα καὶ περὶ Μήδων φαμέν· περὶ δὲ τῶν νομίμων κοινῇ τῆς συμπάσης Μηδίας, ἐπειδὴ ταὐτὰ τοῖς Περσικοῖς γεγένηται διὰ τὴν τῶν Περσῶν ἐπικράτειαν, ἐν τῷ περὶ ἐκείνων λόγῳ φήσομεν.", "st": "11.13.11"}, {"sp": "N", "t": "τῆς δ’ Ἀρμενίας τὰ μὲν νότια προβέβληται τὸν Ταῦρον, διείργοντα αὐτὴν ἀφ’ ὅλης τῆς μεταξὺ Εὐφράτου καὶ τοῦ Τίγριος, ἣν Μεσοποταμίαν καλοῦσι, τὰ δὲ ἑωθινὰ τῇ Μηδίᾳ συνάπτει τῇ μεγάλῃ καὶ τῇ Ἀτροπατηνῇ· προσάρκτια δέ ἐστι τὰ ὑπερκείμενα τῆς Κασπίας θαλάττης ὄρη τὰ τοῦ Παραχοάθρα καὶ Ἀλβανοὶ καὶ Ἴβηρες καὶ ὁ Καύκασος ἐγκυκλούμενος τὰ ἔθνη ταῦτα καὶ συνάπτων τοῖς Ἀρμενίοις, συνάπτων δὲ καὶ τοῖς Μοσχικοῖς ὄρεσι καὶ Κολχικοῖς μέχρι τῶν καλουμένων Τιβαρανῶν· ἀπὸ δὲ τῆς ἑσπέρας ταῦτά ἐστι τὰ ἔθνη καὶ ὁ Παρυάδρης καὶ ὁ Σκυδίσης μέχρι τῆς μικρᾶς Ἀρμενίας καὶ τῆς τοῦ Εὐφράτου ποταμίας, ἣ διείργει τὴν Ἀρμενίαν ἀπὸ τῆς Καππαδοκίας καὶ τῆς Κομμαγηνῆς.", "st": "11.14.1"}, {"sp": "N", "t": "ὁ γὰρ Εὐφράτης ἀπὸ τῆς βορείου πλευρᾶς τοῦ Ταύρου τὰς ἀρχὰς ἔχων τὸ μὲν πρῶτον ῥεῖ πρὸς δύσιν διὰ τῆς Ἀρμενίας, εἶτ’ ἐπιστρέφει πρὸς νότον καὶ διακόπτει τὸν Ταῦρον μεταξὺ τῶν Ἀρμενίων τε καὶ Καππαδόκων καὶ Κομμαγηνῶν, ἐκπεσὼν δ’ ἔξω καὶ γενόμενος κατὰ τὴν Συρίαν ἐπιστρέφει πρὸς χειμερινὰς ἀνατολὰς μέχρι Βαβυλῶνος καὶ ποιεῖ τὴν Μεσοποταμίαν πρὸς τὸν Τίγριν· ἀμφότεροι δὲ τελευτῶσιν εἰς τὸν Περσικὸν κόλπον. τὰ μὲν δὴ κύκλῳ τοιαῦτα, ὀρεινὰ σχεδόν τι πάντα καὶ τραχέα πλὴν τῶν πρὸς τὴν Μηδίαν κεκλιμένων ὀλίγων. πάλιν δὲ τοῦ λεχθέντος Ταύρου τὴν ἀρχὴν λαμβάνοντος ἀπὸ τῆς περαίας τῶν Κομμαγηνῶν καὶ τῶν Μελιτηνῶν ἣν ὁ Εὐφράτης ποιεῖ, Μάσιον μέν ἐστι τὸ ὑπερκείμενον ὄρος τῶν ἐν τῇ Μεσοποταμίᾳ Μυγδόνων ἐκ νότου, ἐν οἷς ἡ Νίσιβίς ἐστιν· ἐκ δὲ τῶν πρὸς ἄρκτον μερῶν ἡ Σωφηνὴ κεῖται μεταξὺ τοῦ τε Μασίου καὶ τοῦ Ἀντιταύρου. οὗτος δ’ ἀπὸ τοῦ Εὐφράτου καὶ τοῦ Ταύρου τὴν ἀρχὴν λαβὼν τελευτᾷ πρὸς τὰ ἑῷα τῆς Ἀρμενίας ἀπολαμβάνων μέσην τὴν Σωφηνήν, ἐκ θατέρου δὲ μέρους ἔχων τὴν Ἀκιλισηνὴν μεταξὺ ἱδρυμένην τοῦ Ταύρου τε καὶ τῆς τοῦ Εὐφράτου ποταμίας πρὶν ἢ κάμπτειν αὐτὴν ἐπὶ νότον. βασίλειον δὲ τῆς Σωφηνῆς Καρκαθιόκερτα. τοῦ δὲ Μασίου ὑπέρκειται πρὸς ἕω πολὺ κατὰ τὴν Γορδυηνὴν ὁ Νιφάτης, εἶθ’ ὁ Ἄβος, ἀφ’ οὗ καὶ ὁ Εὐφράτης ῥεῖ καὶ ὁ Ἀράξης, ὁ μὲν πρὸς δύσιν ὁ δὲ πρὸς ἀνατολάς· εἶθ’ ὁ Νίβαρος μέχρι τῆς Μηδίας παρατείνει.", "st": "11.14.2"}, {"sp": "N", "t": "ὁ μὲν οὖν Εὐφράτης εἴρηται ὃν τρόπον ῥεῖ· ὁ δὲ Ἀράξης πρὸς τὰς ἀνατολὰς ἐνεχθεὶς μέχρι τῆς Ἀτροπατηνῆς κάμπτει πρὸς δύσιν καὶ πρὸς ἄρκτους καὶ παραρρεῖ τὰ Ἄζαρα πρῶτον, εἶτ’ Ἀρτάξατα, πόλεις Ἀρμενίων· ἔπειτα διὰ τοῦ Ἀραξηνοῦ πεδίου πρὸς τὸ Κάσπιον ἐκδίδωσι πέλαγος.", "st": "11.14.3"}, {"sp": "N", "t": "ἐν αὐτῇ δὲ τῇ Ἀρμενίᾳ πολλὰ μὲν ὄρη πολλὰ δὲ ὀροπέδια, ἐν οἷς οὐδ’ ἄμπελος φύεται ῥᾳδίως, πολλοὶ δ’ αὐλῶνες οἱ μὲν μέσως οἱ δὲ καὶ σφόδρα εὐδαίμονες καθάπερ τὸ Ἀραξηνὸν πεδίον, δι’ οὗ ὁ Ἀράξης ποταμὸς ῥέων εἰς τὰ ἄκρα τῆς Ἀλβανίας καὶ τὴν Κασπίαν ἐκπίπτει θάλατταν, καὶ μετὰ ταῦτα ἡ Σακασηνὴ καὶ αὐτὴ τῇ Ἀλβανίᾳ πρόσχωρος καὶ τῷ Κύρῳ ποταμῷ, εἶθ’ ἡ Γωγαρηνή· πᾶσα γὰρ ἡ χώρα αὕτη καρποῖς τε καὶ τοῖς ἡμέροις δένδρεσι καὶ τοῖς ἀειθαλέσι πληθύει, φέρει δὲ καὶ ἐλαίαν. ἔστι δὲ καὶ ἡ Φαυηνὴ τῆς Ἀρμενίας ἐπαρχία καὶ ἡ Κωμισηνὴ καὶ Ὀρχιστηνὴ πλείστην ἱππείαν παρέχουσα· ἡ δὲ Χορζηνὴ καὶ Καμβυσηνὴ προσβορρόταταί εἰσι καὶ νιφόβολοι μάλιστα, συνάπτουσαι τοῖς Καυκασίοις ὄρεσι καὶ τῇ Ἰβηρίᾳ καὶ τῇ Κολχίδι· ὅπου φασὶ κατὰ τὰς ὑπερβολὰς τῶν ὀρῶν πολλάκις καὶ συνοδίας ὅλας ἐν τῇ χιόνι καταπίνεσθαι νιφετῶν γινομένων ἐπὶ πλέον· ἔχειν δὲ καὶ βακτηρίας πρὸς τοὺς τοιούτους κινδύνους, [ἃς] παρεξαίροντας εἰς τὴν ἐπιφάνειαν ἀναπνοῆς τε χάριν καὶ τοῦ διαμηνύειν τοῖς ἐπιοῦσιν ὥστε βοηθείας τυγχάνειν, ἀνορύττεσθαι καὶ σώζεσθαι. ἐν δὲ τῇ χιόνι βώλους πήγνυσθαί φασι κοίλας περιεχούσας χρηστὸν ὕδωρ ὡς ἐν χιτῶνι, καὶ ζῷα δὲ ἐν αὐτῇ γεννᾶσθαι· καλεῖ δὲ σκώληκας Ἀπολλωνίδης, Θεοφάνης δὲ θρῖπας· κἀν τούτοις ἀπολαμβάνεσθαι χρηστὸν ὕδωρ, περισχισθέντων δὲ τῶν χιτώνων πίνεσθαι· τὴν δὲ γένεσιν τῶν ζῴων τοιαύτην εἰκάζουσιν οἵαν τὴν τῶν κωνώπων ἐκ τῆς ἐν τοῖς μετάλλοις φλογὸς καὶ τοῦ φεψάλου.", "st": "11.14.4"}, {"sp": "N", "t": "ἱστοροῦσι δὲ τὴν Ἀρμενίαν μικρὰν πρότερον οὖσαν αὐξηθῆναι διὰ τῶν περὶ Ἀρταξίαν καὶ Ζαρίαδριν, οἳ πρότερον μὲν ἦσαν Ἀντιόχου τοῦ μεγάλου στρατηγοί, βασιλεύσαντες δ’ ὕστερον μετὰ τὴν ἐκείνου ἧτταν ὁ μὲν τῆς Σωφηνῆς καὶ τῆς Ἀκισηνῆς καὶ Ὀδομαντίδος καὶ ἄλλων τινῶν ὁ δὲ τῆς περὶ Ἀρτάξατα, συνηύξησαν ἐκ τῶν περικειμένων ἐθνῶν ἀποτεμόμενοι μέρη, ἐκ Μήδων μὲν τήν τε Κασπιανὴν καὶ Φαυνῖτιν καὶ Βασοροπέδαν, Ἰβήρων δὲ τήν τε παρώρειαν τοῦ Παρυάδρου καὶ τὴν Χορζηνὴν καὶ Γωγαρηνήν, πέραν οὖσαν τοῦ Κύρου, Χαλύβων δὲ καὶ Μοσυνοίκων Καρηνῖτιν καὶ Ξερξήνην, ἃ τῇ μικρᾷ Ἀρμενίᾳ ἐστὶν ὅμορα ἢ καὶ μέρη αὐτῆς ἐστι, Καταόνων δὲ Ἀκιλισηνὴν καὶ τὴν περὶ τὸν Ἀντίταυρον, Σύρων δὲ Ταρωνῖτιν, ὥστε πάντας ὁμογλώττους εἶναι.", "st": "11.14.5"}, {"sp": "N", "t": "πόλεις δ’ εἰσὶν τῆς Ἀρμενίας Ἀρτάξατά τε (ἣν καὶ Ἀρταξιάσατα καλοῦσιν, Ἀννίβα κτίσαντος Ἀρταξίᾳ τῷ βασιλεῖ) καὶ Ἄρξατα, ἀμφότεραι ἐπὶ τῷ Ἀράξῃ, ἡ μὲν Ἄρξατα πρὸς τοῖς ὅροις τῆς Ἀτροπατίας, ἡ δὲ Ἀρτάξατα πρὸς τῷ Ἀραξηνῷ πεδίῳ συνῳκισμένη καλῶς καὶ βασίλειον οὖσα τῆς χώρας. κεῖται δ’ ἐπὶ χερρονησιάζοντος ἀγκῶνος τὸ τεῖχος [ἔχουσα] κύκλῳ προβεβλημένον τὸν ποταμὸν πλὴν τοῦ ἰσθμοῦ, τὸν ἰσθμὸν δ’ ἔχει τάφρῳ καὶ χάρακι κεκλεισμένον. οὐ πολὺ δ’ ἄπωθεν τῆς πόλεώς ἐστι τὰ Τιγράνου καὶ Ἀρταουάσδου γαζοφυλάκια, φρούρια ἐρυμνά, Βάβυρσά τε καὶ Ὀλανή· ἦν δὲ καὶ ἄλλα ἐπὶ τῷ Εὐφράτῃ. Ἀρτάγειρα δὲ ἀπέστησε μὲν Ἄδων ὁ φρούραρχος, ἐξεῖλον δ’ οἱ Καίσαρος στρατηγοὶ πολιορκήσαντες πολὺν χρόνον, καὶ τὰ τείχη περιεῖλον.", "st": "11.14.6"}, {"sp": "N", "t": "ποταμοὶ δὲ πλείους μέν εἰσιν ἐν τῇ χώρᾳ, γνωριμώτατοι δὲ Φᾶσις μὲν καὶ Λύκος εἰς τὴν Ποντικὴν ἐκπίπτοντες θάλατταν (Ἐρατοσθένης δ’ ἀντὶ τοῦ Λύκου τίθησι Θερμώδοντα οὐκ εὖ), εἰς δὲ τὴν Κασπίαν Κῦρος καὶ Ἀράξης, εἰς δὲ τὴν Ἐρυθρὰν ὅ τε Εὐφράτης καὶ ὁ Τίγρις.", "st": "11.14.7"}, {"sp": "N", "t": "εἰσὶ δὲ καὶ λίμναι κατὰ τὴν Ἀρμενίαν μεγάλαι, μία μὲν ἡ Μαντιανή, Κυανῆ ἑρμηνευθεῖσα, μεγίστη, ὥς φασι, μετὰ τὴν Μαιῶτιν, ἁλμυροῦ ὕδατος, διήκουσα μέχρι τῆς Ἀτροπατίας, ἔχουσα καὶ ἁλοπήγια· ἡ δὲ Ἀρσηνή, ἣν καὶ Θωπῖτιν καλοῦσιν· ἔστι δὲ νιτρῖτις, τὰς δ’ ἐσθῆτας ῥήττει καὶ διαξαίνει· διὰ δὲ τοῦτο καὶ ἄποτόν ἐστι τὸ ὕδωρ. φέρεται δὲ δι’ αὐτῆς ὁ Τίγρις ἀπὸ τῆς κατὰ τὸν Νιφάτην ὀρεινῆς ὁρμηθείς, ἄμικτον φυλάττων τὸ ῥεῦμα διὰ τὴν ὀξύτητα, ἀφ’ οὗ καὶ τοὔνομα, Μήδων τίγριν καλούντων τὸ τόξευμα· καὶ οὗτος μὲν ἔχει πολυειδεῖς ἰχθῦς, οἱ δὲ λιμναῖοι ἑνὸς εἴδους εἰσί· κατὰ δὲ τὸν μυχὸν τῆς λίμνης εἰς βάραθρον ἐμπεσὼν ὁ ποταμὸς καὶ πολὺν τόπον ἐνεχθεὶς ὑπὸ γῆς ἀνατέλλει κατὰ τὴν Χαλωνῖτιν· ἐκεῖθεν δ’ ἤδη πρὸς τὴν Ὦπιν καὶ τὸ τῆς Σεμιράμιδος καλούμενον διατείχισμα ἐκεῖνός τε καταφέρεται τοὺς Γορδυαίους ἐν δεξιᾷ ἀφεὶς καὶ τὴν Μεσοποταμίαν ὅλην, καὶ ὁ Εὐφράτης τοὐναντίον ἐν ἀριστερᾷ ἔχων τὴν αὐτὴν χώραν· πλησιάσαντες δὲ ἀλλήλοις καὶ ποιήσαντες τὴν Μεσοποταμίαν ὁ μὲν διὰ Σελευκείας φέρεται πρὸς τὸν Περσικὸν κόλπον, ὁ δὲ διὰ Βαβυλῶνος, καθάπερ εἴρηταί που ἐν τοῖς πρὸς Ἐρατοσθένην καὶ Ἵππαρχον λόγοις.", "st": "11.14.8"}, {"sp": "N", "t": "μέταλλα δ’ ἐν μὲν τῇ Συσπιρίτιδί ἐστι χρυσοῦ κατὰ τὰ Κάβαλλα, ἐφ’ ἃ Μένωνα ἔπεμψεν Ἀλέξανδρος μετὰ στρατιωτῶν, ἀνήχθη δ’ ὑπὸ τῶν ἐγχωρίων· καὶ ἄλλα δ’ ἐστὶ μέταλλα, καὶ δὴ τῆς σάνδικος καλουμένης, ἣν δὴ καὶ Ἀρμένιον καλοῦσι χρῶμα, ὅμοιον κάλχῃ. οὕτω δ’ ἐστὶν ἱπποβότος σφόδρα ἡ χώρα καὶ οὐχ ἧττον τῆς Μηδίας, ὥστε οἱ Νησαῖοι ἵπποι καὶ ἐνταῦθα γίνονται, οἷσπερ οἱ Περσῶν βασιλεῖς ἐχρῶντο, καὶ ὁ σατράπης τῆς Ἀρμενίας τῷ Πέρσῃ κατ’ ἔτος δισμυρίους πώλους τοῖς Μιθρακίνοις ἔπεμπεν. Ἀρταουάσδης δὲ Ἀντωνίῳ χωρὶς τῆς ἄλλης ἱππείας αὐτὴν τὴν κατάφρακτον ἑξακισχιλίαν ἵππον ἐκτάξας ἐπέδειξεν, ἡνίκα εἰς τὴν Μηδίαν ἐνέβαλε σὺν αὐτῷ. ταύτης δὲ τῆς ἱππείας οὐ Μῆδοι μόνοι καὶ Ἀρμένιοι ζηλωταὶ γεγόνασιν, ἀλλὰ καὶ Ἀλβανοί· καὶ γὰρ ἐκεῖνοι καταφράκτοις χρῶνται.", "st": "11.14.9"}, {"sp": "N", "t": "τοῦ δὲ πλούτου καὶ τῆς δυνάμεως τῆς χώρας σημεῖον οὐ μικρὸν ὅτι Πομπηίου Τιγράνῃ τῷ πατρὶ τῷ Ἀρταουάσδου τάλαντα ἐπιγράψαντος ἑξακισχίλια ἀργυρίου, διένειμεν αὐτίκα ταῖς δυνάμεσι τῶν Ῥωμαίων, στρατιώτῃ μὲν κατ’ ἄνδρα πεντήκοντα δραχμὰς ἑκατοντάρχῃ δὲ χιλίας ἱππάρχῳ δὲ καὶ χιλιάρχῳ τάλαντον.", "st": "11.14.10"}, {"sp": "N", "t": "μέγεθος δὲ τῆς χώρας Θεοφάνης ἀποδίδωσιν εὖρος μὲν σχοίνων ἑκατὸν μῆκος δὲ διπλάσιον, τιθεὶς τὴν σχοῖνον τετταράκοντα σταδίων· πρὸς ὑπερβολὴν δ’ εἴρηκεν· ἐγγυτέρω δ’ ἐστὶ τῆς ἀληθείας μῆκος μὲν θέσθαι τὸ ὑπ’ ἐκείνου λεχθὲν [εὖρος], εὖρος δὲ τὸ ἥμισυ ἢ μικρῷ πλεῖον. ἡ μὲν δὴ φύσις τῆς Ἀρμενίας καὶ δύναμις τοιαύτη.", "st": "11.14.11"}, {"sp": "N", "t": "ἀρχαιολογία δέ τίς ἐστι περὶ τοῦ ἔθνους τοῦδε τοιαύτη· ἄρμενος ἐξ Ἀρμενίου πόλεως Θετταλικῆς, ἣ κεῖται μεταξὺ Φερῶν καὶ Λαρίσης ἐπὶ τῇ Βοίβῃ, καθάπερ εἴρηται, συνεστράτευσεν Ἰάσονι εἰς τὴν Ἀρμενίαν· τούτου φασὶν ἐπώνυμον τὴν Ἀρμενίαν οἱ περὶ Κυρσίλον τὸν Φαρσάλιον καὶ Μήδιον τὸν Λαρισαῖον, ἄνδρες συνεστρατευκότες Ἀλεξάνδρῳ· τῶν δὲ μετὰ τοῦ Ἀρμένου τοὺς μὲν τὴν Ἀκιλισηνὴν οἰκῆσαι τὴν ὑπὸ τοῖς Σωφηνοῖς πρότερον οὖσαν, τοὺς δὲ ἐν τῇ Συσπιρίτιδι ἕως τῆς Καλαχηνῆς καὶ τῆς Ἀδιαβηνῆς ἔξω τῶν Ἀρμενιακῶν ὅρων. καὶ τὴν ἐσθῆτα δὲ τὴν Ἀρμενιακὴν Θετταλικήν φασιν, οἷον τοὺς βαθεῖς χιτῶνας οὓς καλοῦσιν Θετταλικοὺς ἐν ταῖς τραγῳδίαις, καὶ ζωννύουσι περὶ τὰ στήθη καὶ ἐφαπτίδας, ὡς καὶ τῶν τραγῳδῶν μιμησαμένων τοὺς Θετταλούς· ἔδει μὲν γὰρ αὐτοῖς ἐπιθέτου κόσμου τοιούτου τινός, οἱ δὲ Θετταλοὶ μάλιστα βαθυστολοῦντες, ὡς εἰκός, διὰ τὸ πάντων εἶναι Ἑλλήνων βορειοτάτους καὶ ψυχροτάτους νέμεσθαι τόπους ἐπιτηδειοτάτην παρέσχοντο μίμησιν τῇ τῶν ὑποκριτῶν διασκευῇ ἐν τοῖς ἀναπλάσμασιν· καὶ τὸν τῆς ἱππικῆς ζῆλόν φασιν εἶναι Θετταλικὸν καὶ τούτοις ὁμοίως καὶ Μήδοις. τὴν δὲ Ἰάσονος στρατείαν καὶ τὰ Ἰασόνια μαρτυρεῖ, ὧν τινα οἱ δυνάσται κατεσκεύασαν παραπλησίως ὥσπερ τὸν ἐν Ἀβδήροις νεὼν τοῦ Ἰάσονος Παρμενίων.", "st": "11.14.12"}, {"sp": "N", "t": "τὸν δὲ Ἀράξην κληθῆναι νομίζουσι κατὰ τὴν ὁμοιότητα τὴν πρὸς τὸν Πηνειὸν ὑπὸ τῶν περὶ τὸν Ἄρμενον ὁμωνύμως ἐκείνῳ· καλεῖσθαι γὰρ Ἀράξην κἀκεῖνον διὰ τὸ ἀπαράξαι τὴν Ὄσσαν ἀπὸ τοῦ Ὀλύμπου ῥήξαντα τὰ Τέμπη· καὶ τὸν ἐν Ἀρμενίᾳ δὲ ἀπὸ τῶν ὀρῶν καταβάντα πλατύνεσθαί φασι τὸ παλαιόν, καὶ πελαγίζειν ἐν τοῖς ὑποκειμένοις πεδίοις οὐκ ἔχοντα διέξοδον, Ἰάσονα δὲ μιμησάμενον τὰ Τέμπη ποιῆσαι τὴν διασφάγα, δι’ ἧς καταράττει νυνὶ τὸ ὕδωρ εἰς τὴν Κασπίαν θάλατταν· ἐκ δὲ τούτου γυμνωθῆναι τὸ Ἀραξηνὸν πεδίον, δι’ οὗ τυγχάνει ῥέων ἐπὶ τὸν καταράκτην ὁ ποταμός. οὗτος μὲν οὖν ὁ λόγος περὶ τοῦ Ἀράξου ποταμοῦ λεγόμενος ἔχει τι πιθανόν, ὁ δὲ Ἡροδότειος οὐ πάνυ· φησὶ γὰρ ἐκ Ματιηνῶν αὐτὸν ῥέοντα εἰς τετταράκοντα ποταμοὺς σχίζεσθαι, μερίζειν δὲ Σκύθας καὶ Βακτριανούς· καὶ Καλλισθένης δὲ ἠκολούθησεν αὐτῷ.", "st": "11.14.13"}, {"sp": "N", "t": "λέγονται δὲ καὶ τῶν Αἰνιάνων τινὲς οἱ μὲν τὴν Οὐιτίαν οἰκῆσαι οἱ δ’ ὕπερθε τῶν Ἀρμενίων ὑπὲρ τὸν Ἄβον καὶ τὸν Νίβαρον (μέρη δ’ ἐστὶ τοῦ Ταύρου ταῦτα), ὧν ὁ Ἄβος ἐγγύς ἐστι τῆς ὁδοῦ τῆς εἰς Ἐκβάτανα φερούσης παρὰ τὸν τῆς Βάριδος νεών. φασὶ δὲ καὶ Θρᾳκῶν τινας, τοὺς προσαγορευομένους Σαραπάρας οἷον κεφαλοτόμους, οἰκῆσαι ὑπὲρ τῆς Ἀρμενίας πλησίον Γουρανίων καὶ Μήδων, θηριώδεις ἀνθρώπους καὶ ἀπειθεῖς ὀρεινοὺς περισκυθιστάς τε καὶ ἀποκεφαλιστάς· τοῦτο γὰρ δηλοῦσιν οἱ Σαραπάραι. εἴρηται δὲ καὶ τὰ περὶ τῆς Μηδείας ἐν τοῖς Μηδικοῖς· ὥστ’ ἐκ πάντων τούτων εἰκάζουσι καὶ τοὺς Μήδους καὶ Ἀρμενίους συγγενεῖς πως τοῖς Θετταλοῖς εἶναι καὶ τοῖς ἀπὸ Ἰάσονος καὶ Μηδείας.", "st": "11.14.14"}, {"sp": "N", "t": "ὁ μὲν δὴ παλαιὸς λόγος οὗτος, ὁ δὲ τούτου νεώτερος καὶ κατὰ Πέρσας εἰς τὸ ἐφεξῆς μέχρι εἰς ἡμᾶς ὡς ἐν κεφαλαίῳ πρέποι ἂν μέχρι τοσούτου λεχθείς, ὅτι κατεῖχον τὴν Ἀρμενίαν Πέρσαι καὶ Μακεδόνες, μετὰ ταῦτα οἱ τὴν Συρίαν ἔχοντες καὶ τὴν Μηδίαν· τελευταῖος δ’ ὑπῆρξεν Ὀρόντης ἀπόγονος Ὑδάρνου τῶν ἑπτὰ Περσῶν ἑνός· εἶθ’ ὑπὸ τῶν Ἀντιόχου τοῦ μεγάλου στρατηγῶν τοῦ πρὸς Ῥωμαίους πολεμήσαντος διῃρέθη δίχα, Ἀρταξίου τε καὶ Ζαριάδριος· καὶ ἦρχον οὗτοι τοῦ βασιλέως ἐπιτρέψαντος· ἡττηθέντος δ’ ἐκείνου προσθέμενοι Ῥωμαίοις καθ’ αὑτοὺς ἐτάττοντο βασιλεῖς προσαγορευθέντες. τοῦ μὲν οὖν Ἀρταξίου Τιγράνης ἦν ἀπόγονος καὶ εἶχε τὴν ἰδίως λεγομένην Ἀρμενίαν (αὕτη δ’ ἦν προσεχὴς τῇ τε Μηδίᾳ καὶ Ἀλβανοῖς καὶ Ἴβηρσι μέχρι Κολχίδος καὶ τῆς ἐπὶ τῷ Εὐξείνῳ Καππαδοκίας), τοῦ δὲ Ζαριάδριος ὁ Σωφηνὸς Ἀρτάνης ἔχων τὰ νότια μέρη καὶ τούτων τὰ πρὸς δύσιν μᾶλλον. κατελύθη δ’ οὗτος ὑπὸ τοῦ Τιγράνου, καὶ πάντων κατέστη κύριος ἐκεῖνος. τύχαις δ’ ἐχρήσατο ποικίλαις· κατ’ ἀρχὰς μὲν γὰρ ὡμήρευσε παρὰ Πάρθοις, ἔπειτα δι’ ἐκείνων ἔτυχε καθόδου, λαβόντων μισθὸν ἑβδομήκοντα αὐλῶνας τῆς Ἀρμενίας· αὐξηθεὶς δὲ καὶ ταῦτα ἀπέλαβε τὰ χωρία καὶ τὴν ἐκείνων ἐπόρθησε τήν τε περὶ Νίνον καὶ τὴν περὶ Ἄρβηλα· ὑπηκόους δ’ ἔσχε καὶ τὸν Ἀτροπατηνὸν καὶ τὸν Γορδυαῖον, μεθ’ ὧν καὶ τὴν λοιπὴν Μεσοποταμίαν, ἔτι δὲ τὴν Συρίαν αὐτὴν καὶ Φοινίκην διαβὰς τὸν Εὐφράτην ἀνὰ κράτος εἷλεν. ἐπὶ τοσοῦτον δ’ ἐξαρθεὶς καὶ πόλιν ἔκτισε πλησίον τῆς Ἰβηρίας μεταξὺ ταύτης τε καὶ τοῦ κατὰ τὸν Εὐφράτην Ζεύγματος, ἣν ὠνόμασε Τιγρανόκερτα, ἐκ δώδεκα ἐρημωθεισῶν ὑπ’ αὐτοῦ πόλεων Ἑλληνίδων ἀνθρώπους συναγαγών. ἔφθη δ’ ἐπελθὼν Λεύκολλος ὁ τῷ Μιθριδάτῃ πολεμήσας καὶ τοὺς μὲν οἰκήτορας εἰς τὴν οἰκείαν ἑκάστου ἀπέλυσε, τὸ δὲ κτίσμα ἡμιτελὲς ἔτι ὂν κατέσπασε προσβαλὼν καὶ μικρὰν κώμην κατέλιπεν, ἐξήλασε δὲ καὶ τῆς Συρίας αὐτὸν καὶ τῆς Φοινίκης. διαδεξάμενος δ’ Ἀρταουάσδης ἐκεῖνον τέως μὲν ηὐτύχει φίλος ὢν Ῥωμαίοις, Ἀντώνιον δὲ προδιδοὺς Παρθυαίοις ἐν τῷ πρὸς αὐτοὺς πολέμῳ δίκας ἔτισεν· ἀναχθεὶς γὰρ εἰς Ἀλεξάνδρειαν ὑπ’ αὐτοῦ, δέσμιος πομπευθεὶς διὰ τῆς πόλεως τέως μὲν ἐφρουρεῖτο, ἔπειτ’ ἀνῃρέθη συνάπτοντος τοῦ Ἀκτιακοῦ πολέμου. μετ’ ἐκεῖνον δὲ πλείους ἐβασίλευσαν ὑπὸ Καίσαρι καὶ Ῥωμαίοις ὄντες· καὶ νῦν ἔτι συνέχεται τὸν αὐτὸν τρόπον.", "st": "11.14.15"}, {"sp": "N", "t": "ἅπαντα μὲν οὖν τὰ τῶν Περσῶν ἱερὰ καὶ Μῆδοι καὶ Ἀρμένιοι τετιμήκασι, τὰ δὲ τῆς Ἀναΐτιδος διαφερόντως Ἀρμένιοι, ἔν τε ἄλλοις ἱδρυσάμενοι τόποις καὶ δὴ καὶ ἐν τῇ Ἀκιλισηνῇ. ἀνατιθέασι δ’ ἐνταῦθα δούλους καὶ δούλας· καὶ τοῦτο μὲν οὐ θαυμαστόν, ἀλλὰ καὶ θυγατέρας οἱ ἐπιφανέστατοι τοῦ ἔθνους ἀνιεροῦσι παρθένους, αἷς νόμος ἐστὶ καταπορνευθείσαις πολὺν χρόνον παρὰ τῇ θεῷ μετὰ ταῦτα δίδοσθαι πρὸς γάμον, οὐκ ἀπαξιοῦντος τῇ τοιαύτῃ συνοικεῖν οὐδενός. τοιοῦτον δέ τι καὶ Ἡρόδοτος λέγει τὸ περὶ τὰς Λυδάς· πορνεύειν γὰρ ἁπάσας. οὕτω δὲ φιλοφρόνως χρῶνται τοῖς ἐρασταῖς ὥστε καὶ ξενίαν παρέχουσι καὶ δῶρα ἀντιδιδόασι πλείω πολλάκις ἢ λαμβάνουσιν, ἅτ’ ἐξ εὐπόρων οἴκων ἐπιχορηγούμεναι· δέχονται δὲ οὐ τοὺς τυχόντας τῶν ξένων, ἀλλὰ μάλιστα τοὺς ἀπὸ ἴσου ἀξιώματος.", "st": "11.14.16"}, {"sp": "HDR", "t": "Βιβλίον ΙΒʹ", "st": "12"}, {"sp": "N", "t": "… καὶ ἡ Καππαδοκία δ’ ἐστὶ πολυμερής τε καὶ συχνὰς δεδεγμένη μεταβολάς. οἱ δ’ οὖν ὁμόγλωττοι μάλιστά εἰσιν οἱ ἀφοριζόμενοι πρὸς νότον μὲν τῷ Κιλικίῳ λεγομένῳ Ταύρῳ, πρὸς ἕω δὲ τῇ Ἀρμενίᾳ καὶ τῇ Κολχίδι καὶ τοῖς μεταξὺ ἑτερογλώττοις ἔθνεσι, πρὸς ἄρκτον δὲ τῷ Εὐξείνῳ μέχρι τῶν ἐκβολῶν τοῦ Ἅλυος, πρὸς δύσιν δὲ τῷ τε τῶν Παφλαγόνων ἔθνει καὶ Γαλατῶν τῶν τὴν Φρυγίαν ἐποικησάντων μέχρι Λυκαόνων καὶ Κιλίκων τῶν τὴν τραχεῖαν Κιλικίαν νεμομένων.", "st": "12.1.1"}, {"sp": "N", "t": "καὶ αὐτῶν δὲ τῶν ὁμογλώττων οἱ παλαιοὶ τοὺς Κατάονας καθ’ αὑτοὺς ἔταττον, ἀντιδιαιροῦντες τοῖς Καππάδοξιν ὡς ἑτεροεθνέσι, καὶ ἐν τῇ διαριθμήσει τῶν ἐθνῶν μετὰ τὴν Καππαδοκίαν ἐτίθεσαν τὴν Καταονίαν, εἶτα τὸν Εὐφράτην καὶ τὰ πέραν ἔθνη, ὥστε καὶ τὴν Μελιτηνὴν ὑπὸ τῇ Καταονίᾳ τάττειν, ἣ μεταξὺ κεῖται ταύτης τε καὶ τοῦ Εὐφράτου συνάπτουσα τῇ Κομμαγηνῇ, μέρος τε τῆς Καππαδοκίας ἐστὶ δέκατον κατὰ τὴν εἰς δέκα στρατηγίας διαίρεσιν τῆς χώρας. οὕτω γὰρ δὴ οἱ καθ’ ἡμᾶς βασιλεῖς οἱ πρὸ Ἀρχελάου διατεταγμένην εἶχον τὴν ἡγεμονίαν τῆς Καππαδοκίας· δέκατον δ’ ἐστὶ μέρος καὶ ἡ Καταονία. καθ’ ἡμᾶς δὲ εἶχε στρατηγὸν ἑκατέρα ἴδιον· οὔτε δ’ ἐκ τῆς διαλέκτου διαφορᾶς τινος ἐν τούτοις πρὸς τοὺς ἄλλους Καππάδοκας ἐμφαινομένης οὔτε ἐκ τῶν ἄλλων ἐθῶν, θαυμαστὸν πῶς ἠφάνισται τελέως τὰ σημεῖα τῆς ἀλλοεθνίας. ἦσαν δ’ οὖν διωρισμένοι, προσεκτήσατο δ’ αὐτοὺς Ἀριαράθης ὁ πρῶτος προσαγορευθεὶς Καππαδόκων βασιλεύς.", "st": "12.1.2"}, {"sp": "N", "t": "ἔστι δ’ ὥσπερ χερρονήσου μεγάλης ἰσθμὸς οὗτος, σφιγγόμενος θαλάτταις δυσὶ τῇ τε τοῦ Ἰσσικοῦ κόλπου μέχρι τῆς τραχείας Κιλικίας καὶ τῇ τοῦ Εὐξείνου μεταξὺ Σινώπης τε καὶ τῆς τῶν Τιβαρηνῶν παραλίας· ἐντὸς δὲ τοῦ ἰσθμοῦ λέγομεν χερρόνησον τὴν προσεσπέριον τοῖς Καππάδοξιν ἅπασαν, ἣν Ἡρόδοτος μὲν ἐντὸς Ἅλυος καλεῖ· αὕτη γὰρ ἔστιν ἧς ἦρξεν ἁπάσης Κροῖσος· λέγει δ’ αὐτὸν ἐκεῖνος τύραννον ἐθνέων τῶν ἐντὸς Ἅλυος ποταμοῦ. οἱ δὲ νῦν τὴν ἐντὸς τοῦ Ταύρου καλοῦσιν Ἀσίαν, ὁμωνύμως τῇ ὅλῃ ἠπείρῳ ταύτην Ἀσίαν προσαγορεύοντες. περιέχεται δ’ ἐν αὐτῇ πρῶτα μὲν ἔθνη τὰ ἀπὸ τῆς ἀνατολῆς Παφλαγόνες τε καὶ Φρύγες καὶ Λυκάονες, ἔπειτα Βιθυνοὶ καὶ Μυσοὶ καὶ ἡ Ἐπίκτητος, ἔτι δὲ Τρῳὰς καὶ Ἑλλησποντία, μετὰ δὲ τούτους ἐπὶ θαλάττῃ μὲν Ἑλλήνων οἵ τε Αἰολεῖς καὶ Ἴωνες τῶν δ’ ἄλλων Κᾶρές τε καὶ Λύκιοι, ἐν δὲ τῇ μεσογαίᾳ Λυδοί.", "st": "12.1.3"}, {"sp": "N", "t": "περὶ μὲν οὖν τῶν ἄλλων ἐροῦμεν ὕστερον. τὴν δὲ Καππαδοκίαν εἰς δύο σατραπείας μερισθεῖσαν ὑπὸ τῶν Περσῶν παραλαβόντες Μακεδόνες περιεῖδον τὰ μὲν ἑκόντες τὰ δ’ ἄκοντες εἰς βασιλείας ἀντὶ σατραπειῶν περιστᾶσαν· ὧν τὴν μὲν ἰδίως Καππαδοκίαν ὠνόμασαν καὶ πρὸς τῷ Ταύρῳ καὶ νὴ Δία μεγάλην Καππαδοκίαν, τὴν δὲ Πόντον, οἱ δὲ τὴν πρὸς τῷ Πόντῳ Καππαδοκίαν. τῆς δὲ μεγάλης Καππαδοκίας νῦν μὲν οὐκ ἴσμεν πω τὴν διάταξιν· τελευτήσαντος γὰρ τὸν βίον Ἀρχελάου τοῦ βασιλεύσαντος, ἔγνω Καῖσάρ τε καὶ ἡ σύγκλητος ἐπαρχίαν εἶναι Ῥωμαίων αὐτήν. ἐπ’ ἐκείνου δὲ καὶ τῶν πρὸ αὐτοῦ βασιλέων εἰς δέκα στρατηγίας διῃρημένης τῆς χώρας, πέντε μὲν ἐξητάζοντο αἱ πρὸς τῷ Ταύρῳ, Μελιτηνὴ Καταονία Κιλικία Τυανῖτις Γαρσαυρῖτις, πέντε δὲ λοιπαὶ Λαουιανσηνὴ Σαργαραυσηνὴ Σαραουηνὴ Χαμανηνὴ Μοριμηνή. προσεγένετο δ’ ὕστερον παρὰ Ῥωμαίων ἐκ τῆς Κιλικίας τοῖς πρὸ Ἀρχελάου καὶ ἑνδεκάτη στρατηγία, ἡ περὶ Καστάβαλά τε καὶ Κύβιστρα μέχρι τῆς Ἀντιπάτρου τοῦ λῃστοῦ Δέρβης, τῷ δὲ Ἀρχελάῳ καὶ ἡ τραχεῖα περὶ Ἐλαιοῦσσαν Κιλικία καὶ πᾶσα ἡ τὰ πειρατήρια συστησαμένη.", "st": "12.1.4"}, {"sp": "N", "t": "ἔστι δ’ ἡ μὲν Μελιτηνὴ παραπλησία τῇ Κομμαγηνῇ· πᾶσα γάρ ἐστι τοῖς ἡμέροις δένδροις κατάφυτος, μόνη τῆς ἄλλης Καππαδοκίας, ὥστε καὶ ἔλαιον φέρειν καὶ τὸν Μοναρίτην οἶνον τοῖς Ἑλληνικοῖς ἐνάμιλλον· ἀντίκειται δὲ τῇ Σωφηνῇ, μέσον ἔχουσα τὸν Εὐφράτην ποταμὸν καὶ αὐτὴ [καὶ] ἡ Κομμαγηνὴ ὅμορος οὖσα. ἔστι δὲ φρούριον ἀξιόλογον τῶν Καππαδόκων ἐν τῇ περαίᾳ Τόμισα· τοῦτο δ’ ἐπράθη μὲν τῷ Σωφηνῷ ταλάντων ἑκατόν, ὕστερον δὲ ἐδωρήσατο Λεύκολλος τῷ Καππάδοκι συστρατεύσαντι ἀριστεῖον κατὰ τὸν πρὸς Μιθριδάτην πόλεμον.", "st": "12.2.1"}, {"sp": "N", "t": "ἡ δὲ Καταονία πλατὺ καὶ κοῖλόν ἐστι πεδίον πάμφορον πλὴν τῶν ἀειθαλῶν. περίκειται δ’ ὄρη ἄλλα τε καὶ Ἀμανὸς ἐκ τοῦ πρὸς νότον μέρους ἀπόσπασμα ὂν τοῦ Κιλικίου Ταύρου, καὶ ὁ Ἀντίταυρος εἰς τἀναντία ἀπερρωγώς. ὁ μὲν γὰρ Ἀμανὸς ἐπὶ τὴν Κιλικίαν καὶ τὴν Συριακὴν ἐκτείνεται θάλατταν πρὸς τὴν ἑσπέραν ἀπὸ τῆς Καταονίας καὶ τὸν νότον· τῇ δὲ τοιαύτῃ διαστάσει περικλείει τὸν Ἰσσικὸν κόλπον ἅπαντα καὶ τὰ μεταξὺ τῶν Κιλίκων πεδία πρὸς τὸν Ταῦρον· ὁ δ’ Ἀντίταυρος ἐπὶ τὰς ἄρκτους ἐγκέκλιται καὶ μικρὸν ἐπιλαμβάνει τῶν ἀνατολῶν, εἶτ’ εἰς τὴν μεσόγαιαν τελευτᾷ.", "st": "12.2.2"}, {"sp": "N", "t": "ἐν δὲ τῷ Ἀντιταύρῳ τούτῳ βαθεῖς καὶ στενοί εἰσιν αὐλῶνες, ἐν οἷς ἵδρυται τὰ Κόμανα καὶ τὸ τῆς Ἐνυοῦς ἱερὸν ἣν ἐκεῖνοι Μᾶ ὀνομάζουσι· πόλις δ’ ἐστὶν ἀξιόλογος, πλεῖστον μέντοι τὸ τῶν θεοφορήτων πλῆθος καὶ τὸ τῶν ἱεροδούλων ἐν αὐτῇ. Κατάονες δέ εἰσιν οἱ ἐνοικοῦντες, ἄλλως μὲν ὑπὸ τῷ βασιλεῖ τεταγμένοι, τοῦ δὲ ἱερέως ὑπακούοντες τὸ πλέον· ὁ δὲ τοῦ θ’ ἱεροῦ κύριός ἐστι καὶ τῶν ἱεροδούλων, οἳ κατὰ τὴν ἡμετέραν ἐπιδημίαν πλείους ἦσαν τῶν ἑξακισχιλίων, ἄνδρες ὁμοῦ γυναιξί. πρόσκειται δὲ τῷ ἱερῷ καὶ χώρα πολλή, καρποῦται δ’ ὁ ἱερεὺς τὴν πρόσοδον, καὶ ἔστιν οὗτος δεύτερος κατὰ τιμὴν [ἐν] τῇ Καππαδοκίᾳ μετὰ τὸν βασιλέα· ὡς δ’ ἐπὶ τὸ πολὺ τοῦ αὐτοῦ γένους ἦσαν οἱ ἱερεῖς τοῖς βασιλεῦσι. τὰ δὲ ἱερὰ ταῦτα δοκεῖ Ὀρέστης μετὰ τῆς ἀδελφῆς Ἰφιγενείας κομίσαι δεῦρο ἀπὸ τῆς Ταυρικῆς Σκυθίας, τὰ τῆς Ταυροπόλου Ἀρτέμιδος, ἐνταῦθα δὲ καὶ τὴν πένθιμον κόμην ἀποθέσθαι, ἀφ’ ἧς καὶ τοὔνομα τῇ πόλει. διὰ μὲν οὖν τῆς πόλεως ταύτης ὁ Σάρος ῥεῖ ποταμός, καὶ διὰ τῶν συναγκειῶν τοῦ Ταύρου διεκπεραιοῦται πρὸς τὰ τῶν Κιλίκων πεδία καὶ τὸ ὑποκείμενον πέλαγος.", "st": "12.2.3"}, {"sp": "N", "t": "διὰ δὲ τῆς Καταονίας ὁ Πύραμος, πλωτός, ἐκ μέσου τοῦ πεδίου τὰς πηγὰς ἔχων· ἔστι δὲ βόθρος ἀξιόλογος, δι’ οὗ καθορᾶν ἔστι τὸ ὕδωρ ὑποφερόμενον κρυπτῶς μέχρι πολλοῦ διαστήματος ὑπὸ γῆς, εἶτ’ ἀνατέλλον εἰς τὴν ἐπιφάνειαν· τῷ δὲ καθιέντι ἀκόντιον ἄνωθεν εἰς τὸν βόθρον ἡ βία τοῦ ὕδατος ἀντιπράττει τοσοῦτον ὥστε μόλις βαπτίζεσθαι· ἀπλέτῳ δὲ βάθει καὶ πλάτει πολὺς ἐνεχθεὶς ἐπειδὰν συνάψῃ τῷ Ταύρῳ, παράδοξον λαμβάνει τὴν συναγωγήν· παράδοξος δὲ καὶ ἡ διακοπὴ τοῦ ὄρους ἐστὶ δι’ ἧς ἄγεται τὸ ῥεῖθρον· καθάπερ γὰρ ἐν ταῖς ῥῆγμα λαβούσαις πέτραις καὶ σχισθείσαις δίχα τὰς κατὰ τὴν ἑτέραν ἐξοχὰς ὁμολόγους εἶναι συμβαίνει ταῖς κατὰ τὴν ἑτέραν εἰσοχαῖς ὥστε κἂν συναρμοσθῆναι δύνασθαι, οὕτως εἴδομεν καὶ τὰς ὑπερκειμένας τοῦ ποταμοῦ πέτρας ἑκατέρωθεν σχεδόν τι μέχρι τῶν ἀκρωρειῶν ἀνατεινούσας ἐν διαστάσει δυεῖν ἢ τριῶν πλέθρων ἀντικείμενα ἐχούσας τὰ κοῖλα ταῖς ἐξοχαῖς· τὸ δὲ ἔδαφος τὸ μεταξὺ πᾶν πέτρινον, βαθύ τι καὶ στενὸν τελέως, ἔχον διὰ μέσου ῥῆγμα ὥστε καὶ κύνα καὶ λαγὼ διάλλεσθαι. τοῦτο δ’ ἐστὶ τὸ ῥεῖθρον τοῦ ποταμοῦ ἄχρι χείλους πλῆρες, ὀχετῷ πλατεῖ προσεοικός, διὰ δὲ τὴν σκολιότητα καὶ τὴν ἐκ τοσούτου συναγωγὴν καὶ τὸ τῆς φάραγγος βάθος εὐθὺς τοῖς πόρρωθεν προσιοῦσιν ὁ ψόφος βροντῇ προσπίπτει παραπλήσιος· διεκβαίνων δὲ τὰ ὄρη τοσαύτην κατάγει χοῦν ἐπὶ θάλατταν, τὴν μὲν ἐκ τῆς Καταονίας τὴν δὲ ἐκ τῶν Κιλίκων πεδίων, ὥστε ἐπ’ αὐτῷ καὶ χρησμὸς ἐκπεπτωκὼς φέρεται τοιοῦτος<br>ἔσσεται ἐσσομένοις, ὅτε Πύραμος ἀργυροδίνης<br>ἠιόνα προχέων ἱερὴν ἐς Κύπρον ἵκηται<br>παραπλήσιον γάρ τι κἀκεῖ συμβαίνει καὶ ἐν Αἰγύπτῳ, τοῦ Νείλου προσεξηπειροῦντος ἀεὶ τὴν θάλατταν τῇ προσχώσει· καθὸ καὶ Ἡρόδοτος μὲν δῶρον τοῦ ποταμοῦ τὴν Αἴγυπτον εἶπεν, ὁ ποιητὴς δὲ τὴν Φάρον πελαγίαν ὑπάρξαι πρότερον οὐχ ὡς νυνὶ πρόσγειον οὖσαν τῇ Αἰγύπτῳ.", "st": "12.2.4"}, {"sp": "N", "t": "τρίτη δ’ ἐστὶν ἱερωσύνη Διὸς Ἀσβαμαίου λειπομένη ταύτης, ἀξιόλογος δ’ ὅμως. ἐνταῦθα δ’ ἐστὶ λάκκος ἁλμυροῦ ὕδατος, ἀξιολόγου λίμνης ἔχων περίμετρον, ὀφρύσι κλειόμενος ὑψηλαῖς τε καὶ ὀρθίαις ὥστ’ ἔχειν κατάβασιν κλιμακώδη· τὸ δ’ ὕδωρ οὔτ’ αὔξεσθαί φασιν οὔτ’ ἀπόρρυσιν ἔχειν οὐδαμοῦ φανεράν.", "st": "12.2.5"}, {"sp": "N", "t": "πόλιν δ’ οὔτε τὸ τῶν Καταόνων ἔχει πεδίον οὔθ’ ἡ Μελιτηνή, φρούρια δ’ ἐρυμνὰ ἐπὶ τῶν ὀρῶν τά τε Ἀζάμορα καὶ τὸ Δάσταρκον, ὃ περιρρεῖται τῷ Καρμάλᾳ ποταμῷ. ἔχει δὲ καὶ ἱερὸν τὸ τοῦ Κατάονος Ἀπόλλωνος καθ’ ὅλην τιμώμενον τὴν Καππαδοκίαν, ποιησαμένων ἀφιδρύματα ἀπ’ αὐτοῦ. οὐδὲ αἱ ἄλλαι στρατηγίαι πόλεις ἔχουσι πλὴν δυεῖν· τῶν δὲ λοιπῶν στρατηγιῶν ἐν μὲν τῇ Σαργαραυσηνῇ πολίχνιόν ἐστιν Ἧρπα καὶ ποταμὸς Καρμάλας, ὃς καὶ αὐτὸς εἰς τὴν Κιλικίαν ἐκδίδωσιν· ἐν δὲ ταῖς ἄλλαις ὅ τε Ἄργος ἔρυμα ὑψηλὸν πρὸς τῷ Ταύρῳ, καὶ τὰ Νῶρα ὃ νῦν καλεῖται Νηροασσός, ἐν ᾧ Εὐμένης πολιορκούμενος ἀντέσχε πολὺν χρόνον· καθ’ ἡμᾶς δὲ Σισίνου ὑπῆρξε χρηματοφυλάκιον τοῦ ἐπιθεμένου τῇ Καππαδόκων ἀρχῇ. τούτου δ’ ἦν καὶ τὰ Κάδηνα, βασίλειον καὶ πόλεως κατασκευὴν ἔχον· ἔστι δὲ καὶ ἐπὶ τῶν ὅρων τῶν Λυκαονικῶν τὰ Γαρσαύιρα κωμόπολις· λέγεται δ’ ὑπάρξαι ποτὲ καὶ αὕτη μητρόπολις τῆς χώρας. ἐν δὲ τῇ Μοριμηνῇ τὸ ἱερὸν τοῦ ἐν Ὀυηνάσοις Διός, ἱεροδούλων κατοικίαν ἔχον τρισχιλίων σχεδόν τι καὶ χώραν ἱερὰν εὔκαρπον, παρέχουσαν πρόσοδον ἐνιαύσιον ταλάντων πεντεκαίδεκα τῷ ἱερεῖ· καὶ οὗτος δ’ ἐστὶ διὰ βίου, καθάπερ καὶ ὁ ἐν Κομάνοις, καὶ δευτερεύει κατὰ τιμὴν μετ’ ἐκεῖνον.", "st": "12.2.6"}, {"sp": "N", "t": "δύο δὲ μόναι στρατηγίαι πόλεις ἔχουσιν, ἡ μὲν Τυανῖτις τὰ Τύανα ὑποπεπτωκυῖαν τῷ Ταύρῳ τῷ κατὰ τὰς Κιλικίας πύλας, καθ’ ἃς εὐπετέσταται καὶ κοινόταται πᾶσίν εἰσιν αἱ εἰς τὴν Κιλικίαν καὶ τὴν Συρίαν ὑπερβολαί· καλεῖται δὲ Εὐσέβεια ἡ πρὸς τῷ Ταύρῳ … ἀγαθὴ δὲ καὶ πεδιὰς ἡ πλείστη. τὰ δὲ Τύανα ἐπίκειται χώματι Σεμιράμιδος τετειχισμένῳ καλῶς. οὐ πολὺ δ’ ἄπωθεν ταύτης ἐστὶ τά τε Καστάβαλα καὶ τὰ Κύβιστρα, ἔτι μᾶλλον τῷ ὄρει πλησιάζοντα πολίσματα· ὧν ἐν τοῖς Κασταβάλοις ἐστὶ τὸ τῆς Περασίας Ἀρτέμιδος ἱερόν, ὅπου φασὶ τὰς ἱερείας γυμνοῖς τοῖς ποσὶ δι’ ἀνθρακιᾶς βαδίζειν ἀπαθεῖς· κἀνταῦθα δέ τινες τὴν αὐτὴν θρυλοῦσιν ἱστορίαν τὴν περὶ τοῦ Ὀρέστου καὶ τῆς Ταυροπόλου, Περασίαν κεκλῆσθαι φάσκοντες διὰ τὸ πέραθεν κομισθῆναι. ἐν μὲν δὴ τῇ Τυανίτιδι στρατηγίᾳ τῶν λεχθεισῶν δέκα ἔστι πόλισμα τὰ Τύανα (τὰς δ’ ἐπικτήτους οὐ συναριθμῶ ταύταις, τὰ Καστάβαλα καὶ τὰ Κύβιστρα καὶ τὰ ἐν τῇ τραχείᾳ Κιλικίᾳ, ἐν ᾗ τὴν Ἐλαιοῦσσαν νησίον εὔκαρπον συνέκτισεν Ἀρχέλαος ἀξιολόγως, καὶ τὸ πλέον ἐνταῦθα διέτριβεν), ἐν δὲ τῇ Κιλικίᾳ καλουμένῃ τὰ Μάζακα ἡ μητρόπολις τοῦ ἔθνους· καλεῖται δ’ Εὐσέβεια καὶ αὕτη ἐπίκλησιν ἡ πρὸς τῷ Ἀργαίῳ· κεῖται γὰρ ὑπὸ τῷ Ἀργαίῳ ὄρει πάντων ὑψηλοτάτῳ καὶ ἀνέκλειπτον χιόνι τὴν ἀκρώρειαν ἔχοντι, ἀφ’ ἧς φασιν οἱ ἀναβαίνοντες (οὗτοι δ’ εἰσὶν ὀλίγοι) κατοπτεύεσθαι ταῖς αἰθρίαις ἄμφω τὰ πελάγη τό τε Ποντικὸν καὶ τὸ Ἰσσικόν. τὰ μὲν οὖν ἄλλα ἀφυῆ πρὸς συνοικισμὸν ἔχει πόλεως· ἄνυδρός τε γάρ ἐστι καὶ ἀνώχυρος διὰ τὴν ὀλιγωρίαν τῶν ἡγεμόνων καὶ ἀτείχιστος, τάχα δὲ καὶ ἐπίτηδες, ἵνα μὴ ὡς ἐρύματι πεποιθότες τῷ τείχει σφόδρα λῃστεύοιεν πεδίον οἰκοῦντες λόφους ὑπερδεξίους ἔχοντες καὶ ἀνεμβαλεῖς. καὶ τὰ κύκλῳ δὲ χωρία ἔχει τελέως ἄφορα καὶ ἀγεώργητα καίπερ ὄντα πεδινά, ἀλλ’ ἔστιν ἀμμώδη καὶ ὑπόπετρα. μικρὸν δ’ ἔτι προϊοῦσι καὶ πυρίληπτα πεδία καὶ μεστὰ βόθρων πυρὸς ἐπὶ σταδίους πολλοὺς ὥστε πόρρωθεν ἡ κομιδὴ τῶν ἐπιτηδείων, καὶ τὸ δοκοῦν δὲ πλεονέκτημα παρακείμενον ἔχει κίνδυνον· ἀξύλου γὰρ ὑπαρχούσης σχεδόν τι τῆς συμπάσης Καππαδοκίας ὁ Ἀργαῖος ἔχει περικείμενον δρυμὸν ὥστε ἐγγύθεν ὁ ξυλισμὸς πάρεστιν, ἀλλ’ οἱ ὑποκείμενοι τῷ δρυμῷ τόποι καὶ αὐτοὶ πολλαχοῦ πυρὰ ἔχουσιν, ἅμα δὲ καὶ ὕφυδροί εἰσι ψυχρῷ ὕδατι, οὔτε τοῦ πυρὸς οὔτε τοῦ ὕδατος εἰς τὴν ἐπιφάνειαν ἐκκύπτοντος, ὥστε καὶ ποάζειν τὴν πλείστην· ἔστι δ’ ὅπου καὶ ἑλῶδές ἐστι τὸ ἔδαφος καὶ νύκτωρ ἐξάπτονται φλόγες ἀπ’ αὐτοῦ. οἱ μὲν οὖν ἔμπειροι φυλαττόμενοι τὸν ξυλισμὸν ποιοῦνται, τοῖς δὲ πολλοῖς κίνδυνός ἐστι, καὶ μάλιστα τοῖς κτήνεσιν ἐμπίπτουσιν εἰς ἀδήλους βόθρους πυρός.", "st": "12.2.7"}, {"sp": "N", "t": "ἔστι δὲ καὶ ποταμὸς ἐν τῷ πεδίῳ τῷ πρὸ τῆς πόλεως Μέλας καλούμενος, ὅσον τετταράκοντα σταδίους διέχων τῆς πόλεως, ἐν ταπεινοτέρῳ τῆς πόλεως χωρίῳ τὰς πηγὰς ἔχων. ταύτῃ μὲν οὖν ἄχρηστος αὐτοῖς ἐστιν οὐχ ὑπερδέξιον ἔχων τὸ ῥεῦμα, εἰς ἕλη δὲ καὶ λίμνας διαχεόμενος κακοῖ τὸν ἀέρα τοῦ θέρους τὸν περὶ τὴν πόλιν, καὶ τὸ λατομεῖον δὲ ποιεῖ δύσχρηστον καίπερ εὔχρηστον ὄν· πλαταμῶνες γὰρ εἰσίν, ἀφ’ ὧν τὴν λιθείαν ἔχειν ἄφθονον συμβαίνει τοῖς Μαζακηνοῖς πρὸς τὰς οἰκοδομίας, καλυπτόμεναι δ’ ὑπὸ τῶν ὑδάτων αἱ πλάκες ἀντιπράττουσι. καὶ ταῦτα δ’ ἐστὶ τὰ ἕλη πανταχοῦ πυρίληπτα. Ἀριαράθης δ’ ὁ βασιλεὺς τοῦ Μέλανος κατά τινα στενὰ ἔχοντος τὴν εἰς τὸν Ἅλυν διέξοδον ἐμφράξας ταῦτα λίμνην πελαγίαν ἀπέδειξε τὸ πλησίον πεδίον, ἐνταῦθα δὲ νησῖδάς τινας ὡς τὰς Κυκλάδας ἀπολαβόμενος διατριβὰς ἐν αὐταῖς ἐποιεῖτο μειρακιώδεις· ἐκραγὲν δ’ ἀθρόως τὸ ἔμφραγμα ἐξέκλυσε πάλιν τὸ ὕδωρ, πληρωθεὶς δ’ ὁ Ἅλυς τῆς τε τῶν Καππαδόκων πολλὴν παρέσυρε καὶ κατοικίας καὶ φυτείας ἠφάνισε πολλὰς τῆς τε τῶν Γαλατῶν τῶν τὴν Φρυγίαν ἐχόντων οὐκ ὀλίγην ἐλυμήνατο· ἀντὶ δὲ τῆς βλάβης ἐπράξαντο ζημίαν αὐτὸν τάλαντα τριακόσια Ῥωμαίοις ἐπιτρέψαντες τὴν κρίσιν. τὸ δ’ αὐτὸ συνέβη καὶ περὶ Ἧρπα· καὶ γὰρ ἐκεῖ τὸ τοῦ Καρμάλα ῥεῦμα ἐνέφραξεν, εἶτ’ ἐκραγέντος τοῦ στομίου καὶ τῶν Κιλίκων τινὰ χωρία τὰ περὶ Μαλλὸν διαφθείραντος τοῦ ὕδατος, δίκας ἔτισεν τοῖς ἀδικηθεῖσιν.", "st": "12.2.8"}, {"sp": "N", "t": "ἀφυὲς δ’ οὖν κατὰ πολλὰ τὸ τῶν Μαζακηνῶν χωρίον ὂν πρὸς κατοικίαν μάλιστα οἱ βασιλεῖς ἑλέσθαι δοκοῦσιν, ὅτι τῆς χώρας ἁπάσης τόπος ἦν μεσαίτατος οὗτος τῶν ξύλα ἐχόντων ἅμα καὶ λίθον πρὸς τὰς οἰκοδομίας καὶ χόρτον, οὗ πλεῖστον ἐδέοντο κτηνοτροφοῦντες· τρόπον γάρ τινα στρατόπεδον ἦν αὐτοῖς ἡ πόλις. τὴν δ’ ἄλλην ἀσφάλειαν τὴν αὐτῶν τε καὶ σωμάτων καὶ τῶν χρημάτων εἶχον ἐν τοῖς φρουρίοις, ἃ πολλὰ ὑπάρχει τὰ μὲν βασιλικὰ τὰ δὲ τῶν φίλων. ἀφέστηκε δὲ τὰ Μάζακα τοῦ μὲν Πόντου περὶ ὀκτακοσίους σταδίους πρὸς νότον, τοῦ δ’ Εὐφράτου μικρὸν ἐλάττους ἢ διπλασίους, τῶν Κιλικίων δὲ πυλῶν ὁδὸν ἡμερῶν ἓξ καὶ τοῦ Κύρου στρατοπέδου διὰ Τυάνων· κατὰ μέσην δὲ τὴν ὁδὸν κεῖται τὰ Τύανα, διέχει δὲ Κυβίστρων τριακοσίους σταδίους. χρῶνται δὲ οἱ Μαζακηνοὶ τοῖς Χαρώνδα νόμοις, αἱρούμενοι καὶ νομῳδόν, ὅς ἐστιν αὐτοῖς ἐξηγητὴς τῶν νόμων, καθάπερ οἱ παρὰ Ῥωμαίοις νομικοί. διέθηκε δὲ φαύλως αὐτοὺς Τιγράνης ὁ Ἀρμένιος, ἡνίκα τὴν Καππαδοκίαν κατέδραμεν· ἅπαντας γὰρ ἀναστάτους ἐποίησεν εἰς τὴν Μεσοποταμίαν, καὶ τὰ Τιγρανόκερτα ἐκ τούτων συνῴκισε τὸ πλέον· ὕστερον δ’ ἐπανῆλθον οἱ δυνάμενοι μετὰ τὴν τῶν Τιγρανοκέρτων ἅλωσιν.", "st": "12.2.9"}, {"sp": "N", "t": "μέγεθος δὲ τῆς χώρας κατὰ πλάτος μὲν τὸ ἀπὸ τοῦ Πόντου πρὸς τὸν Ταῦρον ὅσον χίλιοι καὶ ὀκτακόσιοι στάδιοι, μῆκος δὲ ἀπὸ τῆς Λυκαονίας καὶ Φρυγίας μέχρι Εὐφράτου πρὸς τὴν ἕω καὶ τὴν Ἀρμενίαν περὶ τρισχιλίους. ἀγαθὴ δὲ καρποῖς, μάλιστα δὲ σίτῳ καὶ βοσκήμασι παντοδαποῖς· νοτιωτέρα δ’ οὖσα τοῦ Πόντου ψυχροτέρα ἐστίν· ἡ δὲ Βαγαδανία καίπερ πεδιὰς οὖσα καὶ νοτιωτάτη πασῶν (ὑποπέπτωκε γὰρ τῷ Ταύρῳ) μόλις τῶν καρπίμων τι φέρει δένδρων, ὀναγροβότος δ’ ἐστὶ καὶ αὕτη καὶ ἡ πολλὴ τῆς ἄλλης, καὶ μάλιστα ἡ περὶ Γαρσαύιρα καὶ Λυκαονίαν καὶ Μοριμηνήν. ἐν δὲ τῇ Καππαδοκίᾳ γίνεται καὶ ἡ λεγομένη Σινωπικὴ μίλτος ἀρίστη τῶν πασῶν· ἐνάμιλλος δ’ ἐστὶν αὐτῇ καὶ ἡ Ἰβηρική· ὠνομάσθη δὲ Σινωπικὴ διότι κατάγειν ἐκεῖσε εἰώθεσαν οἱ ἔμποροι πρὶν ἢ τὸ τῶν Ἐφεσίων ἐμπόριον μέχρι τῶν ἐνθάδε ἀνθρώπων διῖχθαι. λέγεται δὲ καὶ κρυστάλλου πλάκας καὶ ὀνυχίτου λίθου πλησίον τῆς τῶν Γαλατῶν ὑπὸ τῶν Ἀρχελάου μεταλλευτῶν εὑρῆσθαι. ἦν δέ τις τόπος καὶ λίθου λευκοῦ τῷ ἐλέφαντι κατὰ τὴν χρόαν ἐμφεροῦς ὥσπερ ἀκόνας τινὰς οὐ μεγάλας ἐκφέρων, ἐξ ὧν τὰ λάβια τοῖς μαχαιρίοις κατεσκεύαζον· ἄλλος δὲ εἰς διόπτρας βώλους μεγάλας ἐκδιδούς, ὥστε καὶ ἔξω κομίζεσθαι. ὅριον δ’ ἐστὶ τοῦ Πόντου καὶ τῆς Καππαδοκίας ὀρεινή τις παράλληλος τῷ Ταύρῳ, τὴν ἀρχὴν ἔχουσα ἀπὸ τῶν ἑσπερίων ἄκρων τῆς Χαμμανηνῆς, ἐφ’ ἧς ἵδρυται φρούριον ἀπότομον Δασμένδα, μέχρι τῶν ἑωθινῶν τῆς Λαουιανσηνῆς. στρατηγίαι δ’ εἰσὶ τῆς Καππαδοκίας ἥ τε Χαμμανηνὴ καὶ ἡ Λαουιανσηνή.", "st": "12.2.10"}, {"sp": "N", "t": "συνέβη δέ, ἡνίκα πρῶτον Ῥωμαῖοι τὰ κατὰ τὴν Ἀσίαν διῴκουν νικήσαντες Ἀντίοχον, καὶ φιλίας καὶ συμμαχίας ἐποιοῦντο πρός τε τὰ ἔθνη καὶ τοὺς βασιλέας, τοῖς μὲν ἄλλοις βασιλεῦσιν αὐτοῖς καθ’ ἑαυτοὺς δοθῆναι τὴν τιμὴν ταύτην, τῷ δὲ Καππάδοκι καὶ αὐτῷ δὲ τῷ ἔθνει κοινῇ. ἐκλιπόντος δὲ τοῦ βασιλικοῦ γένους οἱ μὲν Ῥωμαῖοι συνεχώρουν αὐτοῖς αὐτονομεῖσθαι κατὰ τὴν συγκειμένην φιλίαν τε καὶ συμμαχίαν πρὸς τὸ ἔθνος, οἱ δὲ πρεσβευσάμενοι τὴν μὲν ἐλευθερίαν παρῃτοῦντο (οὐ γὰρ δύνασθαι φέρειν αὐτὴν ἔφασαν), βασιλέα δ’ ἠξίουν αὐτοῖς ἀποδειχθῆναι. οἱ δὲ θαυμάσαντες εἴ τινες οὕτως εἶεν ἀπειρηκότες πρὸς τὴν ἐλευθερίαν … ἐπέτρεψαν δ’ οὖν αὐτοῖς ἐξ ἑαυτῶν ἑλέσθαι κατὰ χειροτονίαν ὃν ἂν βούλωνται· καὶ εἵλοντο Ἀριοβαρζάνην· εἰς τριγονίαν δὲ προελθόντος τοῦ γένους ἐξέλιπε, κατεστάθη δ’ ὁ Ἀρχέλαος οὐδὲν προσήκων αὐτοῖς Ἀντωνίου καταστήσαντος. ταῦτα καὶ περὶ τῆς μεγάλης Καππαδοκίας· περὶ δὲ τῆς τραχείας Κιλικίας τῆς προστεθείσης αὐτῇ βέλτιόν ἐστιν ἐν τῷ περὶ τῆς ὅλης Κιλικίας λόγῳ διελθεῖν.", "st": "12.2.11"}, {"sp": "N", "t": "τοῦ δὲ Πόντου καθίστατο μὲν Μιθριδάτης ὁ Εὐπάτωρ βασιλεύς. εἶχε δὲ τὴν ἀφοριζομένην τῷ Ἅλυϊ μέχρι Τιβαρανῶν καὶ Ἀρμενίων καὶ τῆς ἐντὸς Ἅλυος τὰ μέχρι Ἀμάστρεως καὶ τινῶν τῆς Παφλαγονίας μερῶν. προσεκτήσατο δ’ οὗτος καὶ τὴν μέχρι Ἡρακλείας παραλίαν ἐπὶ τὰ δυσμικὰ μέρη, τῆς Ἡρακλείδου τοῦ Πλατωνικοῦ πατρίδος, ἐπὶ δὲ τἀναντία μέχρι Κολχίδος καὶ τῆς μικρᾶς Ἀρμενίας, ἃ δὴ καὶ προσέθηκε τῷ Πόντῳ. καὶ δὴ καὶ Πομπήιος καταλύσας ἐκεῖνον ἐν τούτοις τοῖς ὅροις οὖσαν τὴν χώραν ταύτην παρέλαβε· τὰ μὲν πρὸς Ἀρμενίαν καὶ τὰ περὶ τὴν Κολχίδα τοῖς συναγωνισαμένοις δυνάσταις κατένειμε, τὰ δὲ λοιπὰ εἰς ἕνδεκα πολιτείας διεῖλε καὶ τῇ Βιθυνίᾳ προσέθηκεν ὥστ’ ἐξ ἀμφοῖν ἐπαρχίαν γενέσθαι μίαν· μεταξὺ δὲ τῶν Παφλαγόνων τῶν μεσογαίων τινὰς βασιλεύεσθαι παρέδωκε τοῖς ἀπὸ Πυλαιμένους, καθάπερ καὶ τοὺς Γαλάτας τοῖς ἀπὸ γένους τετράρχαις. ὕστερον δ’ οἱ τῶν Ῥωμαίων ἡγεμόνες ἄλλους καὶ ἄλλους ἐποιήσαντο μερισμούς, βασιλέας τε καὶ δυνάστας καθιστάντες καὶ πόλεις τὰς μὲν ἐλευθεροῦντες τὰς δὲ ἐγχειρίζοντες τοῖς δυνάσταις τὰς δ’ ὑπὸ τῷ δήμῳ τῷ Ῥωμαίων ἐῶντες. ἡμῖν δ’ ἐπιοῦσι τὰ καθ’ ἕκαστα ὡς νῦν ἔχει λεγέσθω, μικρὰ καὶ τῶν προτέρων ἐφαπτομένοις ὅπου τοῦτο χρήσιμον. ἀρξόμεθα δὲ ἀπὸ Ἡρακλείας, ἥπερ δυσμικωτάτη ἐστὶ τούτων τῶν τόπων.", "st": "12.3.1"}, {"sp": "N", "t": "εἰς δὴ τὸν Εὔξεινον πόντον εἰσπλέουσιν ἐκ τῆς Προποντίδος ἐν ἀριστερᾷ μὲν τὰ προσεχῆ τῷ Βυζαντίῳ κεῖται· Θρᾳκῶν δ’ ἐστί, καλεῖται δὲ τὰ ἀριστερὰ τοῦ Πόντου· ἐν δεξιᾷ δὲ τὰ προσεχῆ Χαλκηδόνι· Βιθυνῶν δ’ ἐστὶ τὰ πρῶτα, εἶτα Μαριανδυνῶν (τινὲς δὲ καὶ Καυκώνων φασίν), εἶτα Παφλαγόνων μέχρι Ἅλυος, εἶτα Καππαδόκων τῶν πρὸς τῷ Πόντῳ καὶ τῶν ἑξῆς μέχρι Κολχίδος· ταῦτα δὲ πάντα καλεῖται τὰ δεξιὰ τοῦ Εὐξείνου πόντου. ταύτης δὲ τῆς παραλίας ἁπάσης ἐπῆρξεν Εὐπάτωρ ἀρξάμενος ἀπὸ τῆς Κολχίδος μέχρι Ἡρακλείας, τὰ δ’ ἐπέκεινα τὰ μέχρι τοῦ στόματος καὶ τῆς Χαλκηδόνος τῷ Βιθυνῶν βασιλεῖ συνέμενε. καταλυθέντων δὲ τῶν βασιλέων ἐφύλαξαν οἱ Ῥωμαῖοι τοὺς αὐτοὺς ὅρους, ὥστε τὴν Ἡράκλειαν προσκεῖσθαι τῷ Πόντῳ, τὰ δ’ ἐπέκειαν Βιθυνοῖς προσχωρεῖν.", "st": "12.3.2"}, {"sp": "N", "t": "οἱ μὲν οὖν Βιθυνοὶ διότι πρότερον Μυσοὶ ὄντες μετωνομάσθησαν οὕτως ἀπὸ τῶν Θρᾳκῶν τῶν ἐποικησάντων, Βιθυνῶν τε καὶ Θυνῶν, ὁμολογεῖται παρὰ τῶν πλείστων, καὶ σημεῖα τίθενται τοῦ μὲν τῶν Βιθυνῶν ἔθνους τὸ μέχρι νῦν ἐν τῇ Θρᾴκῃ λέγεσθαί τινας Βιθυνούς, τοῦ δὲ τῶν Θυνῶν τὴν Θυνιάδα ἀκτὴν τὴν πρὸς Ἀπολλωνίᾳ καὶ Σαλμυδησσῷ. καὶ οἱ Βέβρυκες δὲ οἱ τούτων προεποικήσαντες τὴν Μυσίαν Θρᾷκες, ὡς εἰκάζω ἐγώ. εἴρηται δ’ ὅτι καὶ αὐτοὶ οἱ Μυσοὶ Θρᾳκῶν ἄποικοί εἰσι τῶν νῦν λεγομένων Μοισῶν.", "st": "12.3.3"}, {"sp": "N", "t": "ταῦτα μὲν οὕτω λέγεται. τοὺς δὲ Μαριανδυνοὺς καὶ τοὺς Καύκωνας οὐχ ὁμοίως ἅπαντες λέγουσι· τὴν γὰρ δὴ Ἡράκλειαν ἐν τοῖς Μαριανδυνοῖς ἱδρῦσθαί φασι Μιλησίων κτίσμα· τίνες δὲ καὶ πόθεν οὐδενὶ εἴρηται· οὐδὲ διάλεκτος οὐδ’ ἄλλη διαφορὰ ἐθνικὴ περὶ τοὺς ἀνθρώπους φαίνεται, παραπλήσιοι δ’ εἰσὶ τοῖς Βιθυνοῖς· ἔοικεν οὖν καὶ τοῦτο Θρᾴκιον ὑπάρξαι τὸ φῦλον. Θεόπομπος δὲ Μαριανδυνόν φησι μέρους τῆς Παφλαγονίας ἄρξαντα ὑπὸ πολλῶν δυναστευομένης, ἐπελθόντα τὴν τῶν Βεβρύκων κατασχεῖν, ἣν δ’ ἐξέλιπεν ἐπώνυμον ἑαυτοῦ καταλιπεῖν. εἴρηται δὲ καὶ τοῦτο ὅτι πρῶτοι τὴν Ἡράκλειαν κτίσαντες Μιλήσιοι τοὺς Μαριανδυνοὺς εἱλωτεύειν ἠνάγκασαν τοὺς προκατέχοντας τὸν τόπον, ὥστε καὶ πιπράσκεσθαι ὑπ’ αὐτῶν, μὴ εἰς τὴν ὑπερορίαν δέ (συμβῆναι γὰρ ἐπὶ τούτοις), καθάπερ Κρησὶ μὲν ἐθήτευεν ἡ Μνῴα καλουμένη σύνοδος, Θετταλοῖς δὲ οἱ Πενέσται.", "st": "12.3.4"}, {"sp": "N", "t": "τοὺς δὲ Καύκωνας, οὓς ἱστοροῦσι τὴν ἐφεξῆς οἰκῆσαι παραλίαν τοῖς Μαριανδυνοῖς μέχρι τοῦ Παρθενίου ποταμοῦ πόλιν ἔχοντας τὸ Τίειον, οἱ μὲν Σκύθας φασὶν οἱ δὲ τῶν Μακεδόνων τινὰς οἱ δὲ τῶν Πελασγῶν· εἴρηται δέ που καὶ περὶ τούτων πρότερον. Καλλισθένης δὲ καὶ ἔγραφε τὰ ἔπη ταῦτα εἰς τὸν διάκοσμον, μετὰ τὸ<br>Κρῶμνάν τ’ Αἰγιαλόν τε καὶ ὑψηλοὺς Ἐρυθίνους<br>τιθείς<br>Καύκωνας δ’ αὖτ’ ἦγε Πολυκλέος υἱὸς ἀμύμων,<br>οἳ περὶ Παρθένιον ποταμὸν κλυτὰ δώματ’ ἔναιον.<br>παρήκειν γὰρ ἀφ’ Ἡρακλείας καὶ Μαριανδυνῶν μέχρι Λευκοσύρων, οὓς ἡμεῖς Καππάδοκας προσαγορεύομεν, τό τε τῶν Καυκώνων γένος τὸ περὶ τὸ Τίειον μέχρι Παρθενίου καὶ τὸ τῶν Ἐνετῶν τὸ συνεχὲς μετὰ τὸν Παρθένιον τῶν ἐχόντων τὸ Κύτωρον· καὶ νῦν δ’ ἔτι Καυκωνίτας εἶναί τινας περὶ τὸν Παρθένιον.", "st": "12.3.5"}, {"sp": "N", "t": "ἡ μὲν οὖν Ἡράκλεια πόλις ἐστὶν εὐλίμενος καὶ ἄλλως ἀξιόλογος, ἥ γε καὶ ἀποικίας ἔστελλεν· ἐκείνης γὰρ ἥ τε Χερρόνησος ἄποικος καὶ ἡ Κάλλατις· ἦν τε αὐτόνομος, εἶτ’ ἐτυραννήθη χρόνους τινάς, εἶτ’ ἠλευθέρωσεν ἑαυτὴν πάλιν· ὕστερον δ’ ἐβασιλεύθη γενομένη ὑπὸ τοῖς Ῥωμαίοις· ἐδέξατο δ’ ἀποικίαν Ῥωμαίων ἐπὶ μέρει τῆς πόλεως καὶ τῆς χώρας. λαβὼν δὲ παρ’ Ἀντωνίου τὸ μέρος τοῦτο τῆς πόλεως Ἀδιατόριξ ὁ Δομνεκλείου τετράρχου Γαλατῶν υἱός, ὃ κατεῖχον οἱ Ἡρακλειῶται, μικρὸν πρὸ τῶν Ἀκτιακῶν ἐπέθετο νύκτωρ τοῖς Ῥωμαίοις καὶ ἀπέσφαξεν αὐτούς, ἐπιτρέψαντος, ὡς ἔφασκεν ἐκεῖνος, Ἀντωνίου· θριαμβευθεὶς δὲ μετὰ τὴν ἐν Ἀκτίῳ νίκην ἐσφάγη μεθ’ υἱοῦ· ἡ δὲ πόλις ἐστὶ τῆς Ποντικῆς ἐπαρχίας τῆς συντεταγμένης τῇ Βιθυνίᾳ.", "st": "12.3.6"}, {"sp": "N", "t": "μεταξὺ δὲ Χαλκηδόνος καὶ Ἡρακλείας ῥέουσι ποταμοὶ πλείους, ὧν εἰσιν ὅ τε Ψίλλις καὶ ὁ Κάλπας καὶ ὁ Σαγγάριος οὗ μέμνηται καὶ ὁ ποιητής. ἔχει δὲ τὰς πηγὰς κατὰ Σαγγίαν κώμην ἀφ’ ἑκατὸν καὶ πεντήκοντά που σταδίων οὗτος Πεσσινοῦντος· διέξεισι δὲ τῆς ἐπικτήτου Φρυγίας τὴν πλείω, μέρος δέ τι καὶ τῆς Βιθυνίας ὥστε καὶ τῆς Νικομηδείας ἀπέχειν μικρὸν πλείους ἢ τριακοσίους σταδίους, καθ’ ὃ συμβάλλει ποταμὸς αὐτῷ Γάλλος ἐκ Μόδρων τὰς ἀρχὰς ἔχων τῆς ἐφ’ Ἑλλησπόντῳ Φρυγίας. αὕτη δ’ ἐστὶν ἡ αὐτὴ τῇ ἐπικτήτῳ, καὶ εἶχον αὐτὴν οἱ Βιθυνοὶ πρότερον. αὐξηθεὶς δὲ καὶ γενόμενος πλωτός, καίπερ πάλαι ἄπλωτος ὤν, τὴν Βιθυνίαν ὁρίζει πρὸς ταῖς ἐκβολαῖς. πρόκειται δὲ τῆς παραλίας ταύτης καὶ ἡ Θυνία νῆσος. ἐν δὲ τῇ Ἡρακλειώτιδι γίνεται τὸ ἀκόνιτον· διέχει δὲ ἡ πόλις αὕτη τοῦ ἱεροῦ τοῦ Χαλκηδονίου σταδίους χιλίους που καὶ πεντακοσίους, τοῦ δὲ Σαγγαρίου πεντακοσίους.", "st": "12.3.7"}, {"sp": "N", "t": "τὸ δὲ Τίειόν ἐστι πολίχνιον οὐδὲν ἔχον μνήμης ἄξιον πλὴν ὅτι Φιλέταιρος ἐντεῦθεν ἦν, ὁ ἀρχηγέτης τοῦ τῶν Ἀτταλικῶν βασιλέων γένους· εἶθ’ ὁ Παρθένιος ποταμὸς διὰ χωρίων ἀνθηρῶν φερόμενος καὶ διὰ τοῦτο τοῦ ὀνόματος τούτου τετυχηκώς, ἐν αὐτῇ τῇ Παφλαγονίᾳ τὰς πηγὰς ἔχων· ἔπειτα ἡ Παφλαγονία καὶ οἱ Ἐνετοί. ζητοῦσι δὲ τίνας λέγει τοὺς Ἐνετοὺς ὁ ποιητὴς ὅταν φῇ<br>Παφλαγόνων δ’ ἡγεῖτο Πυλαιμένεος λάσιον κῆρ<br>ἐξ Ἐνετῶν, ὅθεν ἡμιόνων γένος ἀγροτεράων.<br>οὐ γὰρ δείκνυσθαί φασι νῦν Ἐνετοὺς ἐν τῇ Παφλαγονίᾳ· οἱ δὲ κώμην ἐν τῷ Αἰγιαλῷ φασι δέκα σχοίνους ἀπὸ Ἀμάστρεως διέχουσαν. Ζηνόδοτος δὲ “ἐξ Ἐνετῆς” γράφει, καὶ φησὶ δηλοῦσθαι τὴν νῦν Ἀμισόν· ἄλλοι δὲ φῦλόν τι τοῖς Καππάδοξιν ὅμορον στρατεῦσαι μετὰ Κιμμερίων, εἶτ’ ἐκπεσεῖν εἰς τὸν Ἀδρίαν. τὸ δὲ μάλισθ’ ὁμολογούμενόν ἐστιν ὅτι ἀξιολογώτατον ἦν τῶν Παφλαγόνων φῦλον οἱ Ἐνετοί, ἐξ οὗ ὁ Πυλαιμένης ἦν· καὶ δὴ καὶ συνεστράτευσαν οὗτοι αὐτῷ πλεῖστοι, ἀποβαλόντες δὲ τὸν ἡγεμόνα διέβησαν εἰς τὴν Θρᾴκην μετὰ τὴν Τροίας ἅλωσιν, πλανώμενοι δ’ εἰς τὴν νῦν Ἐνετικὴν ἀφίκοντο. τινὲς δὲ καὶ Ἀντήνορα καὶ τοὺς παῖδας αὐτοῦ κοινωνῆσαι τοῦ στόλου τούτου φασὶ καὶ ἱδρυθῆναι κατὰ τὸν μυχὸν τοῦ Ἀδρίου, καθάπερ ἐμνήσθημεν ἐν τοῖς Ἰταλικοῖς. τοὺς μὲν οὖν Ἐνετοὺς διὰ τοῦτ’ ἐκλιπεῖν εἰκὸς καὶ μὴ δείκνυσθαι ἐν τῇ Παφλαγονίᾳ.", "st": "12.3.8"}, {"sp": "N", "t": "τοὺς δὲ Παφλαγόνας πρὸς ἕω μὲν ὁρίζει ὁ Ἅλυς ποταμός [ὃς] ῥέων ἀπὸ μεσημβρίης μεταξὺ Σύρων τε καὶ Παφλαγόνων ἐξίει κατὰ τὸν Ἡρόδοτον ἐς τὸν Εὔξεινον καλεόμενον πόντον, Σύρους λέγοντα τοὺς Καππάδοκας· καὶ γὰρ ἔτι καὶ νῦν Λευκόσυροι καλοῦνται, Σύρων καὶ τῶν ἔξω τοῦ Ταύρου λεγομένων· κατὰ δὲ τὴν πρὸς τοὺς ἐντὸς τοῦ Ταύρου σύγκρισιν, ἐκείνων ἐπικεκαυμένων τὴν χρόαν τούτων δὲ μή, τοιαύτην τὴν ἐπωνυμίαν γενέσθαι συνέβη· καὶ Πίνδαρός φησιν ὅτι αἱ Ἀμαζόνες<br>Σύριον εὐρυαίχμαν δίεπον στρατόν,<br>τὴν ἐν τῇ Θεμισκύρᾳ κατοικίαν οὕτω δηλῶν. ἡ δὲ Θεμίσκυρά ἐστιν τῶν Ἀμισηνῶν, αὕτη δὲ Λευκοσύρων τῶν μετὰ τὸν Ἅλυν. πρὸς ἕω μὲν τοίνυν ὁ Ἅλυς ὅριον τῶν Παφλαγόνων, πρὸς νότον δὲ Φρύγες καὶ οἱ ἐποικήσαντες Γαλάται, πρὸς δύσιν δὲ Βιθυνοὶ καὶ Μαριανδυνοί (τὸ γὰρ τῶν Καυκώνων γένος ἐξέφθαρται τελέως πάντοθεν), πρὸς ἄρκτον δὲ ὁ Εὔξεινος ἔστι. τῆς δὲ χώρας ταύτης διῃρημένης εἴς τε τὴν μεσόγαιαν καὶ τὴν ἐπὶ θαλάττῃ διατείνουσαν ἀπὸ τοῦ Ἅλυος μέχρι Βιθυνίας, ἑκατέραν τὴν μὲν παραλίαν ἕως τῆς Ἡρακλείας εἶχεν ὁ Εὐπάτωρ, τῆς δὲ μεσογαίας τὴν μὲν ἐγγυτάτω ἔσχεν, ἧς τινα καὶ πέραν τοῦ Ἅλυος διέτεινε (καὶ μέχρι δεῦρο τοῖς Ῥωμαίοις ἡ Ποντικὴ ἐπαρχία ἀφώρισται), τὰ λοιπὰ δ’ ἦν ὑπὸ δυνάσταις καὶ μετὰ τὴν Μιθριδάτου κατάλυσιν. περὶ μὲν δὴ τῶν ἐν τῇ μεσογαίᾳ Παφλαγόνων ἐροῦμεν ὕστερον τῶν μὴ ὑπὸ τῷ Μιθριδάτῃ, νῦν δὲ πρόκειται τὴν ὑπ’ ἐκείνῳ χώραν, κληθεῖσαν δὲ Πόντον, διελθεῖν.", "st": "12.3.9"}, {"sp": "N", "t": "μετὰ δὴ τὸν Παρθένιον ποταμὸν ἔστιν Ἄμαστρις ὁμώνυμος τῆς συνῳκικυίας πόλις· ἵδρυται δ’ ἐπὶ χερρονήσου λιμένας ἔχουσα τοῦ ἰσθμοῦ ἑκατέρωθεν· ἦν δ’ ἡ Ἄμαστρις γυνὴ μὲν Διονυσίου τοῦ Ἡρακλείας τυράννου, θυγάτηρ δὲ Ὀξυάθρου τοῦ Δαρείου ἀδελφοῦ τοῦ κατὰ Ἀλέξανδρον. ἐκείνη μὲν οὖν ἐκ τεττάρων κατοικιῶν συνῴκισε τὴν πόλιν, ἔκ τε Σησάμου καὶ Κυτώρου καὶ Κρώμνης (ὧν καὶ Ὅμηρος μέμνηται ἐν τῷ Παφλαγονικῷ διακόσμῳ), τετάρτης δὲ τῆς Τίου· ἀλλ’ αὕτη μὲν ταχὺ ἀπέστη τῆς κοινωνίας, αἱ δὲ ἄλλαι συνέμειναν, ὧν ἡ Σήσαμος ἀκρόπολις τῆς Ἀμάστρεως λέγεται. τὸ δὲ Κύτωρον ἐμπόριον ἦν ποτε Σινωπέων, ὠνόμασται δ’ ἀπὸ Κυτώρου τοῦ Φρίξου παιδός, ὡς Ἔφορός φησι. πλείστη δὲ καὶ ἀρίστη πύξος φύεται κατὰ τὴν Ἀμαστριανήν, καὶ μάλιστα περὶ τὸ Κύτωρον. ὁ δὲ Αἰγιαλὸς ἔστι μὲν ᾐὼν μακρὰ πλειόνων ἢ ἑκατὸν σταδίων, ἔχει δὲ καὶ κώμην ὁμώνυμον, ἧς μέμνηται ὁ ποιητὴς ὅταν φῇ<br>Κρῶμνάν τ’ Αἰγιαλόν τε καὶ ὑψηλοὺς Ἐρυθίνους.<br>γράφουσι δέ τινες<br>Κρῶμναν Κωβίαλόν τε.<br>Ἐρυθίνους δὲ λέγεσθαί φασι τοὺς νῦν Ἐρυθρίνους ἀπὸ τῆς χρόας· δύο δ’ εἰσὶ σκόπελοι. μετὰ δὲ Αἰγιαλὸν Κάραμβις, ἄκρα μεγάλη πρὸς τὰς ἄρκτους ἀνατεταμένη καὶ τὴν Σκυθικὴν χερρόνησον. ἐμνήσθημεν δ’ αὐτῆς πολλάκις καὶ τοῦ ἀντικειμένου αὐτῇ Κριοῦ μετώπου, διθάλαττον ποιοῦντος τὸν Εὔξεινον πόντον. μετὰ δὲ Κάραμβιν Κίνωλις καὶ Ἀντικίνωλις καὶ Ἀβώνου τεῖχος πολίχνιον, καὶ Ἀρμένη ἐφ’ ᾗ παροιμιάζονται<br>ὅστις ἔργον οὐδὲν εἶχεν Ἀρμένην ἐτείχισεν.<br>ἔστι δὲ κώμη τῶν Σινωπέων ἔχουσα λιμένα.", "st": "12.3.10"}, {"sp": "N", "t": "εἶτ’ αὐτὴ Σινώπη, σταδίους πεντήκοντα τῆς Ἀρμένης διέχουσα, ἀξιολογωτάτη τῶν ταύτῃ πόλεων. ἔκτισαν μὲν οὖν αὐτὴν Μιλήσιοι, κατασκευασαμένη δὲ ναυτικὸν ἐπῆρχε τῆς ἐντὸς Κυανέων θαλάττης, καὶ ἔξω δὲ πολλῶν ἀγώνων μετεῖχε τοῖς Ἕλλησιν· αὐτονομηθεῖσα δὲ πολὺν χρόνον οὐδὲ διὰ τέλους ἐφύλαξε τὴν ἐλευθερίαν, ἀλλ’ ἐκ πολιορκίας ἑάλω καὶ ἐδούλευσε Φαρνάκῃ πρῶτον, ἔπειτα τοῖς διαδεξαμένοις ἐκεῖνον μέχρι τοῦ Εὐπάτορος καὶ τῶν καταλυσάντων Ῥωμαίων ἐκεῖνον. ὁ δὲ Εὐπάτωρ καὶ ἐγεννήθη ἐκεῖ καὶ ἐτράφη· διαφερόντως δὲ ἐτίμησεν αὐτὴν μητρόπολίν τε τῆς βασιλείας ὑπέλαβεν. ἔστι δὲ καὶ φύσει καὶ προνοίᾳ κατεσκευασμένη καλῶς· ἵδρυται γὰρ ἐπὶ αὐχένι χερρονήσου τινός, ἑκατέρωθεν δὲ τοῦ ἰσθμοῦ λιμένες καὶ ναύσταθμα καὶ πηλαμυδεῖα θαυμαστά, περὶ ὧν εἰρήκαμεν ὅτι δευτέραν θήραν οἱ Σινωπεῖς ἔχουσι, τρίτην δὲ Βυζάντιοι· καὶ κύκλῳ δ’ ἡ χερρόνησος προβέβληται ῥαχιώδεις ἀκτὰς ἐχούσας καὶ κοιλάδας τινὰς ὡσανεὶ βόθρους πετρίνους, οὓς καλοῦσι χοινικίδας· πληροῦνται δὲ οὗτοι μετεωρισθείσης τῆς θαλάττης, ὡς καὶ διὰ τοῦτο οὐκ εὐπρόσιτον τὸ χωρίον καὶ διὰ τὸ πᾶσαν τὴν τῆς πέτρας ἐπιφάνειαν ἐχινώδη καὶ ἀνεπίβατον εἶναι γυμνῷ ποδί· ἄνωθεν μέντοι καὶ ὑπὲρ τῆς πόλεως εὔγεών ἐστι τὸ ἔδαφος καὶ ἀγροκηπίοις κεκόσμηται πυκνοῖς, πολὺ δὲ μᾶλλον τὰ προάστεια. αὐτὴ δ’ ἡ πόλις τετείχισται καλῶς, καὶ γυμνασίῳ δὲ καὶ ἀγορᾷ καὶ στοαῖς κεκόσμηται λαμπρῶς. τοιαύτη δὲ οὖσα δὶς ὅμως ἑάλω, πρότερον μὲν τοῦ Φαρνάκου παρὰ δόξαν αἰφνιδίως ἐπιπεσόντος, ὕστερον δὲ ὑπὸ Λευκόλλου καὶ τοῦ ἐγκαθημένου τυράννου καὶ ἐντὸς ἅμα καὶ ἐκτὸς πολιορκουμένη· ὁ γὰρ ἐγκατασταθεὶς ὑπὸ τοῦ βασιλέως φρούραρχος Βακχίδης ὑπονοῶν ἀεί τινα προδοσίαν ἐκ τῶν ἔνδοθεν καὶ πολλὰς αἰκίας καὶ σφαγὰς ποιῶν, ἀπαγορεῦσαι τοὺς ἀνθρώπους ἐποίησε πρὸς ἄμφω μήτ’ ἀμύνασθαι δυναμένους γενναίως μήτε προσθέσθαι κατὰ συμβάσεις. ἑάλωσαν δ’ οὖν· καὶ τὸν μὲν ἄλλον κόσμον τῆς πόλεως διεφύλαξεν ὁ Λεύκολλος, τὴν δὲ τοῦ Βιλλάρου σφαῖραν ἦρε καὶ τὸν Αὐτόλυκον, Σθένιδος ἔργον, ὃν ἐκεῖνοι οἰκιστὴν ἐνόμιζον καὶ ἐτίμων ὡς θεόν· ἦν δὲ καὶ μαντεῖον αὐτοῦ· δοκεῖ δὲ τῶν Ἰάσονι συμπλευσάντων εἶναι καὶ κατασχεῖν τοῦτον τὸν τόπον. εἶθ’ ὕστερον Μιλήσιοι τὴν εὐφυΐαν ἰδόντες καὶ τὴν ἀσθένειαν τῶν ἐνοικούντων ἐξιδιάσαντο καὶ ἐποίκους ἔστειλαν· νυνὶ δὲ καὶ Ῥωμαίων ἀποικίαν δέδεκται, καὶ μέρος τῆς πόλεως καὶ τῆς χώρας ἐκείνων ἐστί. διέχει δὲ τοῦ μὲν Ἱεροῦ τρισχιλίους καὶ πεντακοσίους, ἀφ’ Ἡρακλείας δὲ δισχιλίους, Καράμβεως δὲ ἑπτακοσίους σταδίους. ἄνδρας δὲ ἐξήνεγκεν ἀγαθούς, τῶν μὲν φιλοσόφων Διογένη τὸν κυνικὸν καὶ Τιμόθεον τὸν Πατρίωνα, τῶν δὲ ποιητῶν Δίφιλον τὸν κωμικόν, τῶν δὲ συγγραφέων Βάτωνα τὸν πραγματευθέντα τὰ Περσικά.", "st": "12.3.11"}, {"sp": "N", "t": "ἐντεῦθεν δ’ ἐφεξῆς ἡ τοῦ Ἅλυος ἐκβολὴ ποταμοῦ· ὠνόμασται δ’ ἀπὸ τῶν ἁλῶν ἃς παραρρεῖ· ἔχει δὲ τὰς πηγὰς ἐν τῇ μεγάλῃ Καππαδοκίᾳ τῆς Ποντικῆς πλησίον κατὰ τὴν Καμισηνήν, ἐνεχθεὶς δ’ ἐπὶ δύσιν πολύς, εἶτ’ ἐπιστρέψας πρὸς τὴν ἄρκτον διά τε Γαλατῶν καὶ Παφλαγόνων ὁρίζει τούτους τε καὶ τοὺς Λευκοσύρους. ἔχει δὲ καὶ ἡ Σινωπῖτις καὶ πᾶσα ἡ μέχρι Βιθυνίας ὀρεινὴ ἡ ὑπερκειμένη τῆς λεχθείσης παραλίας ναυπηγήσιμον ὕλην ἀγαθὴν καὶ εὐκατακόμιστον. ἡ δὲ Σινωπῖτις καὶ σφένδαμνον φύει καὶ ὀροκάρυον, ἐξ ὧν τὰς τραπέζας τέμνουσιν· ἅπασα δὲ καὶ ἐλαιόφυτός ἐστιν ἡ μικρὸν ὑπὲρ τῆς θαλάττης γεωργουμένη.", "st": "12.3.12"}, {"sp": "N", "t": "μετὰ δὲ τὴν ἐκβολὴν τοῦ Ἅλυος ἡ Γαζηλωνῖτίς ἐστι μέχρι τῆς Σαραμηνῆς, εὐδαίμων χώρα καὶ πεδιὰς πᾶσα καὶ πάμφορος· ἔχει δὲ καὶ προβατείαν ὑποδιφθέρου καὶ μαλακῆς ἐρέας, ἧς καθ’ ὅλην τὴν Καππαδοκίαν καὶ τὸν Πόντον σφόδρα πολλὴ σπάνις ἐστί· γίνονται δὲ καὶ ζορκές, ὧν ἀλλαχοῦ σπάνις ἐστί. ταύτης δὲ τῆς χώρας τὴν μὲν ἔχουσιν Ἀμισηνοί, τὴν δ’ ἔδωκε Δηιοτάρῳ Πομπήιος, καθάπερ καὶ τὰ περὶ Φαρνακίαν καὶ τὴν Τραπεζουσίαν μέχρι Κολχίδος καὶ τῆς μικρᾶς Ἀρμενίας· καὶ τούτων ἀπέδειξεν αὐτὸν βασιλέα, ἔχοντα καὶ τὴν πατρῴαν τετραρχίαν τῶν Γαλατῶν, τοὺς Τολιστοβωγίους. ἀποθανόντος δ’ ἐκείνου πολλαὶ διαδοχαὶ τῶν ἐκείνου γεγόνασι.", "st": "12.3.13"}, {"sp": "N", "t": "μετὰ δὲ τὴν Γαζηλῶνα ἡ Σαραμηνὴ καὶ Ἀμισὸς πόλις ἀξιόλογος, διέχουσα τῆς Σινώπης περὶ ἐνακοσίους σταδίους. φησὶ δ’ αὐτὴν Θεόπομπος πρώτους Μιλησίους κτίσαι … Καππαδόκων ἄρχοντα, τρίτον δ’ ὑπ’ Ἀθηνοκλέους καὶ Ἀθηναίων ἐποικισθεῖσαν Πειραιᾶ μετονομασθῆναι. καὶ ταύτην δὲ κατέσχον οἱ βασιλεῖς, ὁ δ’ Εὐπάτωρ ἐκόσμησεν ἱεροῖς καὶ προσέκτισε μέρος. Λεύκολλος δὲ καὶ ταύτην ἐπολιόρκησεν, εἶθ’ ὕστερον Φαρνάκης ἐκ Βοσπόρου διαβάς· ἐλευθερωθεῖσαν δ’ ὑπὸ Καίσαρος τοῦ θεοῦ παρέδωκεν Ἀντώνιος βασιλεῦσιν· εἶθ’ ὁ τύραννος Στράτων κακῶς αὐτὴν διέθηκεν· εἶτ’ ἠλευθερώθη πάλιν μετὰ τὰ Ἀκτιακὰ ὑπὸ Καίσαρος τοῦ Σεβαστοῦ, καὶ νῦν εὖ συνέστηκεν. ἔχει δὲ τήν τε ἄλλην χώραν καλὴν καὶ τὴν Θεμίσκυραν τὸ τῶν Ἀμαζόνων οἰκητήριον, καὶ τὴν Σιδήνην.", "st": "12.3.14"}, {"sp": "N", "t": "ἔστι δὲ ἡ Θεμίσκυρα πεδίον τῇ μὲν ὑπὸ τοῦ πελάγους κλυζόμενον, ὅσον ἑξήκοντα σταδίους τῆς πόλεως διέχον, τῇ δ’ ὑπὸ τῆς ὀρεινῆς εὐδένδρου καὶ διαρρύτου ποταμοῖς αὐτόθεν τὰς πηγὰς ἔχουσιν. ἐκ μὲν οὖν τούτων πληρούμενος ἁπάντων εἷς ποταμὸς διέξεισι τὸ πεδίον Θερμώδων καλούμενος· ἄλλος δὲ τούτῳ πάρισος ῥέων ἐκ τῆς καλουμένης Φαναροίας τὸ αὐτὸ διέξεισι πεδίον· καλεῖται δὲ Ἶρις. ἔχει δὲ τὰς πηγὰς ἐν αὐτῷ τῷ Πόντῳ, ῥυεὶς δὲ διὰ πόλεως μέσης Κομάνων τῶν Ποντικῶν καὶ διὰ τῆς Δαζιμωνίτιδος εὐδαίμονος πεδίου πρὸς δύσιν, εἶτ’ ἐπιστρέφει πρὸς τὰς ἄρκτους παρ’ αὐτὰ τὰ Γαζίουρα, παλαιὸν βασίλειον, νῦν δ’ ἔρημον· εἶτα ἀνακάμπτει πάλιν πρὸς ἕω παραλαβὼν τόν τε Σκύλακα καὶ ἄλλους ποταμούς, καὶ παρ’ αὐτὸ τὸ τῆς Ἀμασείας ἐνεχθεὶς τεῖχος, τῆς ἡμετέρας πατρίδος, πόλεως ἐρυμνοτάτης, εἰς τὴν Φανάροιαν πρόεισιν· ἐνταῦθα δὲ συμβαλὼν ὁ Λύκος αὐτῷ τὰς ἀρχὰς ἐξ Ἀρμενίας ἔχων γίνεται καὶ αὐτὸς Ἶρις· εἶθ’ ἡ Θεμίσκυρα ὑποδέχεται τὸ ῥεῦμα καὶ τὸ Ποντικὸν πέλαγος. διὰ δὲ τοῦτο ἔνδροσόν ἐστι καὶ ποάζον ἀεὶ τὸ πεδίον τοῦτο τρέφειν ἀγέλας βοῶν τε ὁμοίως καὶ ἵππων δυνάμενον, σπόρον δὲ πλεῖστον δέχεται τὸν ἐκ τῆς ἐλύμου καὶ κέγχρου, μᾶλλον δὲ ἀνέκλειπτον· αὐχμοῦ γάρ ἐστι κρείττων ἡ εὐυδρία παντός, ὥστ’ οὐδὲ λιμὸς καθικνεῖται τῶν ἀνθρώπων τούτων οὐδ’ ἅπαξ· τοσαύτην δ’ ὀπώραν ἐκδίδωσιν ἡ παρόρειος τὴν αὐτοφυῆ καὶ ἀγρίαν σταφυλῆς τε καὶ ὄχνης καὶ μήλου καὶ τῶν καρυωδῶν ὥστε κατὰ πᾶσαν τοῦ ἔτους ὥραν ἀφθόνως εὐπορεῖν τοὺς ἐξιόντας ἐπὶ τὴν ὕλην, τοτὲ μὲν ἔτι κρεμαμένων τῶν καρπῶν ἐν τοῖς δένδρεσι, τοτὲ δ’ ἐν τῇ πεπτωκυίᾳ φυλλάδι καὶ ὑπ’ αὐτῇ κειμένων βαθείᾳ καὶ πολλῇ κεχυμένῃ. συχναὶ δὲ καὶ θῆραι παντοίων ἀγρευμάτων διὰ τὴν εὐπορίαν τῆς τροφῆς.", "st": "12.3.15"}, {"sp": "N", "t": "μετὰ δὲ τὴν Θεμίσκυράν ἐστιν ἡ Σιδήνη, πεδίον εὔδαιμον, οὐχ ὁμοίως δὲ κατάρρυτον, ἔχον χωρία ἐρυμνὰ ἐπὶ τῇ παραλίᾳ, τήν τε Σίδην ἀφ’ ἧς ὠνομάσθη Σιδήνη, καὶ Χάβακα καὶ Φάβδα· μέχρι μὲν δὴ δεῦρο Ἀμισηνή. ἄνδρες δὲ γεγόνασιν ἄξιοι μνήμης κατὰ παιδείαν ἐνταῦθα μαθηματικοὶ μὲν Δημήτριος ὁ τοῦ Ῥαθηνοῦ καὶ Διονυσόδωρος ὁμώνυμος τῷ Μηλίῳ γεωμέτρῃ, γραμματικὸς δὲ Τυραννίων οὗ ἡμεῖς ἠκροασάμεθα.", "st": "12.3.16"}, {"sp": "N", "t": "μετὰ δὲ τὴν Σιδήνην ἡ Φαρνακία ἐστὶν ἐρυμνὸν πόλισμα, καὶ μετὰ ταῦτα ἡ Τραπεζοῦς πόλις Ἑλληνίς, εἰς ἣν ἀπὸ τῆς Ἀμισοῦ περὶ δισχιλίους καὶ διακοσίους σταδίους ἐστὶν ὁ πλοῦς· εἶτ’ ἔνθεν εἰς Φᾶσιν χίλιοί που καὶ τετρακόσιοι, ὥστε οἱ σύμπαντες ἀπὸ τοῦ Ἱεροῦ μέχρι Φάσιδος περὶ ὀκτακισχιλίους σταδίους εἰσὶν ἢ μικρῷ πλείους ἢ ἐλάττους. ἐν δὲ τῇ παραλίᾳ ταύτῃ ἀπὸ Ἀμισοῦ πλέουσιν ἡ Ἡράκλειος ἄκρα πρῶτον ἔστιν, εἶτ’ ἄλλη ἄκρα Ἰασόνιον καὶ ὁ Γενήτης, εἶτα Κοτύωρα πολίχνη ἐξ ἧς συνῳκίσθη ἡ Φαρνακία, εἶτ’ Ἰσχόπολις κατερηριμμένη, εἶτα κόλπος ἐν ᾧ Κερασοῦς τε καὶ Ἑρμώνασσα κατοικίαι μέτριαι, εἶτα τῆς Ἑρμωνάσσης πλησίον ἡ Τραπεζοῦς, εἶθ’ ἡ Κολχίς· ἐνταῦθα δέ που ἐστὶ καὶ Ζυγόπολίς τις λεγομένη κατοικία. περὶ μὲν οὖν τῆς Κολχίδος εἴρηται καὶ τῆς ὑπερκειμένης παραλίας.", "st": "12.3.17"}, {"sp": "N", "t": "τῆς δὲ Τραπεζοῦντος ὑπέρκεινται καὶ τῆς Φαρνακίας Τιβαρανοί τε καὶ Χαλδαῖοι καὶ Σάννοι, οὓς πρότερον ἐκάλουν Μάκρωνας, καὶ ἡ μικρὰ Ἀρμενία· καὶ οἱ Ἀππαῗται δέ πως πλησιάζουσι τοῖς χωρίοις τούτοις οἱ πρότερον Κερκῖται. διήκει δὲ διὰ τούτων ὅ τε Σκυδίσης ὄρος τραχύτατον συνάπτον τοῖς Μοσχικοῖς ὄρεσι τοῖς ὑπὲρ τῆς Κολχίδος, οὗ τὰ ἄκρα κατέχουσιν οἱ Ἑπτακωμῆται, καὶ ὁ Παρυάδρης ὁ μέχρι τῆς μικρᾶς Ἀρμενίας ἀπὸ τῶν κατὰ Σιδήνην καὶ Θεμίσκυραν τόπων διατείνων καὶ ποιῶν τὸ ἑωθινὸν τοῦ Πόντου πλευρόν. εἰσὶ δ’ ἅπαντες μὲν οἱ ὄρειοι τούτων ἄγριοι τελέως, ὑπερβέβληνται δὲ τοὺς ἄλλους οἱ Ἑπτακωμῆται· τινὲς δὲ καὶ ἐπὶ δένδρεσιν ἢ πυργίοις οἰκοῦσι, διὸ καὶ Μοσυνοίκους ἐκάλουν οἱ παλαιοί, τῶν πύργων μοσσύνων λεγομένων. ζῶσι δ’ ἀπὸ θηρείων σαρκῶν καὶ τῶν ἀκροδρύων, ἐπιτίθενται δὲ καὶ τοῖς ὁδοιποροῦσι καταπηδήσαντες ἀπὸ τῶν ἰκρίων. οἱ δὲ Ἑπτακωμῆται τρεῖς Πομπηίου σπείρας κατέκοψαν διεξιούσας τὴν ὀρεινήν, κεράσαντες κρατῆρας ἐν ταῖς ὁδοῖς τοῦ μαινομένου μέλιτος, ὃ φέρουσιν οἱ ἀκρεμόνες τῶν δένδρων· πιοῦσι γὰρ καὶ παρακόψασιν ἐπιθέμενοι ῥᾳδίως διεχειρίσαντο τοὺς ἀνθρώπους. ἐκαλοῦντο δὲ τούτων τινὲς τῶν βαρβάρων καὶ Βύζηρες.", "st": "12.3.18"}, {"sp": "N", "t": "οἱ δὲ νῦν Χαλδαῖοι Χάλυβες τὸ παλαιὸν ὠνομάζοντο, καθ’ οὓς μάλιστα ἡ Φαρνακία ἵδρυται, κατὰ θάλατταν μὲν ἔχουσα εὐφυΐαν τὴν ἐκ τῆς πηλαμυδείας (πρώτιστα γὰρ ἁλίσκεται ἐνταῦθα τὸ ὄψον τοῦτο), ἐκ δὲ τῆς γῆς τὰ μέταλλα νῦν μὲν σιδήρου πρότερον δὲ καὶ ἀργύρου. ὅλως δὲ κατὰ τοὺς τόπους τούτους ἡ παραλία στενὴ τελέως ἐστίν· ὑπέρκειται γὰρ εὐθὺς τὰ ὄρη μετάλλων πλήρη καὶ δρυμῶν, γεωργεῖται δ’ οὐ πολλά· λείπεται δὴ τοῖς μὲν μεταλλευταῖς ἐκ τῶν μετάλλων ὁ βίος, τοῖς δὲ θαλαττουργοῖς ἐκ τῆς ἁλιείας καὶ μάλιστα τῶν πηλαμύδων καὶ τῶν δελφίνων· ἐπακολουθοῦντες γὰρ ταῖς ἀγέλαις τῶν ἰχθύων, κορδύλης τε καὶ θύννης καὶ αὐτῆς τῆς πηλαμύδος, πιαίνονταί τε καὶ εὐάλωτοι γίνονται διὰ τὸ πλησιάζειν τῇ γῇ προαλέστερον· δελεαζομένους μόνοι οὗτοι κατακόπτουσι τοὺς δελφῖνας καὶ τῷ στέατι πολλῷ χρῶνται πρὸς ἅπαντα.", "st": "12.3.19"}, {"sp": "N", "t": "τούτους οὖν οἶμαι λέγειν τὸν ποιητὴν Ἁλιζώνους ἐν τῷ μετὰ τοὺς Παφλαγόνας καταλόγῳ<br>αὐτὰρ Ἁλιζώνων Ὀδίος καὶ Ἐπίστροφος ἦρχον<br>τηλόθεν ἐξ Ἀλύβης, ὅθεν ἀργύρου ἐστὶ γενέθλη.<br>ἤτοι τῆς γραφῆς μετατεθείσης ἀπὸ τοῦ “τηλόθεν ἐκ Χαλύβης,” ἢ τῶν ἀνθρώπων πρότερον Ἀλύβων λεγομένων ἀντὶ Χαλύβων· οὐ γὰρ νῦν μὲν δυνατὸν γέγονεν ἐκ Χαλύβων Χαλδαίους λεχθῆναι, πρότερον δ’ οὐκ ἐνῆν ἀντὶ Ἀλύβων Χάλυβας, καὶ ταῦτα τῶν ὀνομάτων μεταπτώσεις πολλὰς δεχομένων καὶ μάλιστα ἐν τοῖς βαρβάροις· Σίντιες γὰρ ἐκαλοῦντό τινες τῶν Θρᾳκῶν, εἶτα Σιντοί, εἶτα Σάιοι, παρ’ οἷς φησιν Ἀρχίλοχος τὴν ἀσπίδα ῥῖψαι<br>ἀσπίδα μὲν Σαΐων τις ἀνείλετο, τὴν παρὰ θάμνῳ<br>ἔντος ἀμώμητον κάλλιπον οὐκ ἐθέλων.<br>οἱ δ’ αὐτοὶ οὗτοι Σαπαῖοι νῦν ὀνομάζονται· πάντες γὰρ οὗτοι περὶ Ἄβδηρα τὴν οἴκησιν εἶχον καὶ τὰς περὶ Λῆμνον νήσους· ὁμοίως δὲ καὶ Βρῦγοι καὶ Βρύγες καὶ Φρύγες οἱ αὐτοί, καὶ Μυσοὶ καὶ Μαίονες καὶ Μῄονες· οὐ χρεία δὲ πλεονάζειν. ὑπονοεῖ δὲ καὶ ὁ Σκήψιος τὴν τοῦ ὀνόματος μετάπτωσιν ἐξ Ἀλύβων εἰς Χάλυβας, τὰ δ’ ἑξῆς καὶ τὰ συνῳδὰ οὐ νοῶν, καὶ μάλιστα ἐκ τίνος Ἁλιζώνους εἴρηκε τοὺς Χάλυβας, ἀποδοκιμάζει τὴν δόξαν· ἡμεῖς δ’ ἀντιπαραθέντες τῇ ἡμετέρᾳ τὴν ἐκείνου καὶ τὰς τῶν ἄλλων ὑπολήψεις σκοπῶμεν.", "st": "12.3.20"}, {"sp": "N", "t": "οἱ μὲν [οὖν] μεταγράφουσιν “Ἀλαζώνων” οἱ δ’ “Ἀμαζώνων” ποιοῦντες, τὸ δ’ “ἐξ Ἀλύβης” “ἐξ Ἀλόπης” ἢ “ἐξ Ἀλόβης,” τοὺς μὲν Σκύθας Ἀλαζῶνας φάσκοντες ὑπὲρ τὸν Βορυσθένη καὶ Καλλιπίδας καὶ ἄλλα ὀνόματα, ἅπερ Ἑλλάνικός τε καὶ Ἡρόδοτος καὶ Εὔδοξος κατεφλυάρησαν ἡμῶν, τοὺς δ’ Ἀμαζῶνας μεταξὺ Μυσίας καὶ Καρίας καὶ Λυδίας, καθάπερ Ἔφορος νομίζει, πλησίον Κύμης τῆς πατρίδος αὐτοῦ· καὶ τοῦτο μὲν ἔχεταί τινος λόγου τυχὸν ἴσως· εἴη γὰρ ἂν λέγων τὴν ὑπὸ τῶν Αἰολέων καὶ Ἰώνων οἰκισθεῖσαν ὕστερον, πρότερον δ’ ὑπὸ Ἀμαζόνων, [ὧν] καὶ ἐπωνύμους πόλεις τινὰς εἶναί φασι· καὶ γὰρ Ἔφεσον καὶ Σμύρναν καὶ Κύμην καὶ Μύριναν. ἡ δὲ Ἀλύβη ἢ ὥς τινες Ἀλόπη ἢ Ἀλόβη πῶς ἂν ἐν τοῖς τόποις τούτοις ἐξητάζετο; πῶς δὲ τηλόθεν; πῶς δ’ ἡ τοῦ ἀργύρου γενέθλη;", "st": "12.3.21"}, {"sp": "N", "t": "ταῦτα μὲν ἀπολύεται τῇ μεταγραφῇ· γράφει γὰρ οὕτως<br>αὐτὰρ Ἀμαζώνων Ὀδίος καὶ Ἐπίστροφος ἦρχον,<br>ἐλθόντ’ ἐξ Ἀλόπης, ὅ θ’ Ἀμαζονίδων γένος ἐστί.<br>ταῦτα δ’ ἀπολυσάμενος εἰς ἄλλο ἐμπέπτωκε πλάσμα· οὐδαμοῦ γὰρ ἐνθάδε εὑρίσκεται Ἀλόπη· καὶ ἡ μεταγραφὴ δὲ παρὰ τὴν τῶν ἀντιγράφων τῶν ἀρχαίων πίστιν καινοτομουμένη ἐπὶ τοσοῦτον σχεδιασμῷ ἔοικεν. ὁ δὲ Σκήψιος οὔτε τὴν τούτου δόξαν ἔοικεν ἀποδεξάμενος οὔτε τῶν περὶ τὴν Παλλήνην τοὺς Ἁλιζώνους ὑπολαβόντων, ὧν ἐμνήσθημεν ἐν τοῖς Μακεδονικοῖς. ὁμοίως διαπορεῖ καὶ πῶς ἐκ τῶν ὑπὲρ τὸν Βορυσθένην νομάδων ἀφῖχθαι συμμαχίαν τοῖς Τρωσί τις νομίσειεν, ἐπαινεῖ δὲ μάλιστα τὴν Ἑκαταίου τοῦ Μιλησίου καὶ Μενεκράτους τοῦ Ἐλαΐτου τῶν Ξενοκράτους γνωρίμων ἀνδρὸς δόξαν καὶ τὴν Παλαιφάτου, ὧν ὁ μὲν ἐν γῆς περιόδῳ φησίν ἐπὶ δ’ Ἀλαζίᾳ πόλι ποταμὸς Ὀδρύσης ῥέων διὰ Μυγδονίης πεδίου ἀπὸ δύσιος ἐκ τῆς λίμνης τῆς Δασκυλίτιδος ἐς Ῥύνδακον ἐσβάλλει. ἔρημον δὲ εἶναι νῦν τὴν Ἀλαζίαν λέγει, κώμας δὲ πολλὰς τῶν Ἀλαζώνων οἰκεῖσθαι, δι’ ὧν Ὀδρύσης ῥεῖ, ἐν δὲ ταύταις τὸν Ἀπόλλωνα τιμᾶσθαι διαφερόντως, καὶ μάλιστα κατὰ τὴν ἐφορίαν τῶν Κυζικηνῶν. ὁ δὲ Μενεκράτης ἐν τῇ Ἑλλησποντιακῇ περιόδῳ ὑπερκεῖσθαι λέγει τῶν περὶ τὴν Μύρλειαν τόπων ὀρεινὴν συνεχῆ, ἣν κατῴκει τὸ τῶν Ἁλιζώνων ἔθνος· δεῖ δέ, φησί, γράφειν ἐν τοῖς δύο λάβδα, τὸν δὲ ποιητὴν ἐν τῷ ἑνὶ γράφειν διὰ τὸ μέτρον. ὁ δὲ Παλαίφατός φησιν ἐξ Ἀλαζώνων τῶν ἐν τῇ Ἀλόπῃ οἰκούντων, νῦν δὲ Ζελείᾳ, τὸν Ὀδίον καὶ τὸν Ἐπίστροφον στρατεῦσαι. τί οὖν ἄξιον ἐπαινεῖν τὰς τούτων δόξας; χωρὶς γὰρ τοῦ τὴν ἀρχαίαν γραφὴν καὶ τούτους κινεῖν οὔτε τὰ ἀργυρεῖα δεικνύουσιν, οὔτε ποῦ τῆς Μυρλεάτιδος Ἀλόπη ἐστίν, οὔτε πῶς οἱ ἐνθένδε ἀφιγμένοι εἰς Ἴλιον τηλόθεν ἦσαν, εἰ καὶ δοθείη Ἀλόπην τινὰ γεγονέναι ἢ Ἀλαζίαν· πολὺ γὰρ δὴ ταῦτα ἐγγυτέρω ἐστὶ τῇ Τρῳάδι ἢ τὰ περὶ Ἔφεσον. ἀλλ’ ὅμως τοὺς περὶ Πύγελα λέγοντας τοὺς Ἀμαζῶνας μεταξὺ Ἐφέσου καὶ Μαγνησίας καὶ Πριήνης φλυαρεῖν φησὶν ὁ Δημήτριος· τὸ γὰρ “τηλόθεν” οὐκ ἐφαρμόττειν τῷ τόπῳ· πόσῳ οὖν μᾶλλον οὐκ ἐφαρμόττει τῷ περὶ Μυσίαν καὶ Τευθρανίαν;", "st": "12.3.22"}, {"sp": "N", "t": "νὴ Δία, ἀλλά φησι δεῖν ἔνια καὶ ἀκύρως προστιθέμενα δέχεσθαι, ὡς καὶ<br>τῆλ’ ἐξ Ἀσκανίης<br>καὶ<br>Ἀρναῖος δ’ ὄνομ’ ἔσκε, τὸ γὰρ θέτο πότνια μήτηρ,<br>καὶ<br>εἵλετο δὲ κληῖδ’ εὐκαμπέα χειρὶ παχείῃ Πηνελόπη.<br>δεδόσθω δὴ καὶ τοῦτο· ἀλλ’ ἐκεῖνα οὐ δοτέα, οἷς προσέχων ὁ Δημήτριος οὐδὲ τοῖς ὑπολαβοῦσι δεῖν ἀκούειν “τηλόθεν ἐκ Χαλύβης” πιθανῶς ἀντείρηκε. συγχωρήσας γὰρ ὅτι, εἰ καὶ μὴ ἔστι νῦν ἐν τοῖς Χάλυψι τὰ ἀργυρεῖα, ὑπάρξαι γε ἐνεδέχετο, ἐκεῖνό γε οὐ συγχωρεῖ ὅτι καὶ ἔνδοξα ἦν καὶ ἄξια μνήμης, καθάπερ τὰ σιδηρεῖα. τί δὲ κωλύει, φαίη τις ἄν, καὶ ἔνδοξα εἶναι, καθάπερ καὶ τὰ σιδηρεῖα; ἢ σιδήρου μὲν εὐπορία τόπον ἐπιφανῆ δύναται ποιεῖν, ἀργύρου δ’ οὔ; τί δ’ εἰ μὴ κατὰ τοὺς ἥρωας, ἀλλὰ καθ’ Ὅμηρον εἰς δόξαν ἀφῖκτο τὰ ἀργυρεῖα, ἆρα μέμψαιτό τις ἂν τὴν ἀπόφασιν τοῦ ποιητοῦ; πῶς οὖν εἰς τὸν ποιητὴν ἡ δόξα ἀφίκετο; πῶς δ’ ἡ τοῦ ἐν τῇ Τεμέσῃ χαλκοῦ τῇ Ἰταλιώτιδι; πῶς δ’ ἡ τοῦ Θηβαϊκοῦ πλούτου τοῦ κατ’ Αἴγυπτον; καίτοι διπλάσιον σχεδόν τι διέχοντα τῶν Αἰγυπτίων Θηβῶν ἢ τῶν Χαλδαίων. ἀλλ’ οὐδ’ οἷς συνηγορεῖ, τούτοις ὁμολογεῖ· τὰ γὰρ περὶ τὴν Σκῆψιν τοποθετῶν τὴν ἑαυτοῦ πατρίδα, πλησίον τῆς Σκήψεως καὶ τοῦ Αἰσήπου Νέαν κώμην καὶ Ἀργυρίαν λέγει καὶ Ἀλαζονίαν. ταῦτα μὲν οὖν εἰ καὶ ἔστι, πρὸς ταῖς πηγαῖς ἂν εἴη τοῦ Αἰσήπου. ὁ δὲ Ἑκαταῖος λέγει ἐπέκεινα τῶν ἐκβολῶν αὐτοῦ, ὅ τε Παλαίφατος πρότερον μὲν Ἀλόπην οἰκεῖν φήσας νῦν δὲ Ζέλειαν, οὐδὲν ὅμοιον λέγει τούτοις. εἰ δ’ ἄρα ὁ Μενεκράτης, καὶ οὐδ’ οὗτος τὴν Ἀλόπην ἢ Ἀλόβην ἢ ὅπως ποτὲ βούλονται γράφειν φράζει ἥτις ἐστίν, οὐδ’ αὐτὸς ὁ Δημήτριος.", "st": "12.3.23"}, {"sp": "N", "t": "πρὸς Ἀπολλόδωρον δὲ περὶ τῶν αὐτῶν ἐν τῷ Τρωικῷ διακόσμῳ διαλεγόμενον πολλὰ μὲν εἴρηται πρότερον, καὶ νῦν δὲ λεκτέον. οὐ γὰρ οἴεται δεῖν δέχεσθαι τοὺς Ἁλιζώνους ἐκτὸς τοῦ Ἅλυος· μηδεμίαν γὰρ συμμαχίαν ἀφῖχθαι τοῖς Τρωσὶν ἐκ τῆς περαίας τοῦ Ἅλυος. πρῶτον τοίνυν ἀπαιτήσομεν αὐτὸν τίνες εἰσὶν οἱ ἐντὸς τοῦ Ἅλυος Ἁλίζωνοι, οἱ καὶ<br>τηλόθεν ἐξ Ἀλύβης, ὅθεν ἀργύρου ἐστὶ γενέθλη·<br>οὐ γὰρ ἕξει λέγειν· ἔπειτα τὴν αἰτίαν δι’ ἣν οὐ συγχωρεῖ καὶ ἐκ τῆς περαίας ἀφῖχθαί τινα συμμαχίαν· καὶ γὰρ εἰ τὰς ἄλλας ἐντὸς εἶναι τοῦ ποταμοῦ πάσας συμβαίνει πλὴν τῶν Θρᾳκῶν, μίαν γε ταύτην οὐδὲν ἐκώλυε πέραθεν ἀφῖχθαι ἐκ τῆς ἐπέκεινα τῶν Λευκοσύρων. ἢ πολεμήσοντας μὲν ἦν δυνατὸν διαβαίνειν ἐκ τῶν τόπων τούτων καὶ τῶν ἐπέκεινα, καθάπερ τὰς Ἀμαζόνας καὶ Τρῆρας καὶ Κιμμερίους φασί, συμμαχήσοντας δ’ ἀδύνατον; αἱ μὲν οὖν Ἀμαζόνες οὐ συνεμάχουν διὰ τὸ τὸν Πρίαμον πολεμῆσαι πρὸς αὐτὰς συμμαχοῦντα τοῖς Φρυξὶν<br>ἤματι τῷ ὅτε τ’ ἦλθον Ἀμαζόνες ἀντιάνειραι<br>φησὶν ὁ Πρίαμος<br>καὶ γὰρ ἐγὼν ἐπίκουρος ἐὼν μετὰ τοῖσιν ἐλέγμην.<br>οἱ δ’ ὁμοροῦντες αὐταῖς, οὔθ’ οὕτως ἄπωθεν ὄντες ὥστε χαλεπὴν εἶναι τὴν ἐκεῖθεν μετάπεμψιν οὔτ’ ἔχθρας ὑποκειμένης, οὐδὲν ἐκωλύοντο οἶμαι συμμαχεῖν.", "st": "12.3.24"}, {"sp": "N", "t": "ἀλλ’ οὐδὲ δόξαν ἔχει τοιαύτην τῶν παλαιῶν εἰπεῖν ὡς συμφωνούντων ἁπάντων μηδένας ἐκ τῆς περαίας τοῦ Ἅλυος κοινωνῆσαι τοῦ Τρωικοῦ πολέμου. πρὸς τοὐναντίον δὲ μᾶλλον εὕροι τις ἂν μαρτυρίας· Μαιάνδριος γοῦν ἐκ τῶν Λευκοσύρων φησὶ τοὺς Ἐνετοὺς ὁρμηθέντας συμμαχῆσαι τοῖς Τρωσίν, ἐκεῖθεν δὲ μετὰ τῶν Θρᾳκῶν ἀπᾶραι καὶ οἰκῆσαι περὶ τὸν τοῦ Ἀδρίου μυχόν, τοὺς δὲ μὴ μετασχόντας τῆς στρατείας Ἐνετοὺς Καππάδοκας γενέσθαι. συνηγορεῖν δ’ ἂν δόξειε τῷ λόγῳ τούτῳ, διότι πᾶσα ἡ πλησίον τοῦ Ἅλυος Καππαδοκία ὅση παρατείνει τῇ Παφλαγονίᾳ ταῖς δυσὶ χρῆται διαλέκτοις καὶ τοῖς ὀνόμασι πλεονάζει τοῖς Παφλαγονικοῖς, Βάγας καὶ Βιάσας καὶ Αἰνιάτης καὶ Ῥατώτης καὶ Ζαρδώκης καὶ Τίβιος καὶ Γάσυς καὶ Ὀλίγασυς καὶ Μάνης· ταῦτα γὰρ ἔν τε τῇ Φαζημωνίτιδι καὶ τῇ Πιμωλισίτιδι καὶ τῇ Γαζηλωνίτιδι καὶ Γαζακηνῇ καὶ ἄλλαις πλείσταις χώραις ἐπιπολάζει τὰ ὀνόματα. αὐτὸς δὲ ὁ Ἀπολλόδωρος παρατίθησι τὸ τοῦ Ζηνοδότου ὅτι γράφει<br>ἐξ Ἐνετῆς, ὅθεν ἡμιόνων γένος ἀγροτεράων.<br>ταύτην δέ φησιν Ἑκαταῖον τὸν Μιλήσιον δέχεσθαι τὴν Ἀμισόν· ἡ δ’ Ἀμισὸς εἴρηται διότι τῶν Λευκοσύρων ἐστὶ καὶ ἐκτὸς τοῦ Ἅλυος.", "st": "12.3.25"}, {"sp": "N", "t": "εἴρηται δ’ αὐτῷ που καὶ διότι ὁ ποιητὴς ἱστορίαν εἶχε τῶν Παφλαγόνων τῶν ἐν τῇ μεσογαίᾳ παρὰ τῶν πεζῇ διελθόντων τὴν χώραν, τὴν παραλίαν δ’ ἠγνόει, καθάπερ καὶ τὴν ἄλλην τὴν Ποντικήν· ὠνόμαζε γὰρ [ἂν] αὐτήν. τοὐναντίον δ’ ἔστιν ἀναστρέψαντα εἰπεῖν ἐκ τῆς περιοδείας ὁρμηθέντα τῆς ἀποδοθείσης νυνί, ὡς τὴν μὲν παραλίαν πᾶσαν ἐπελήλυθε καὶ οὐδὲν τῶν ὄντων τότε ἀξίων μνήμης παραλέλοιπεν· εἰ δ’ Ἡράκλειαν καὶ Ἄμαστριν καὶ Σινώπην οὐ λέγει τὰς μήπω συνῳκισμένας οὐδὲν θαυμαστόν· τὴν δὲ μεσόγαιαν οὐδὲν ἄτοπον εἰ μὴ εἴρηκε. καὶ τὸ μὴ ὀνομάζειν δὲ πολλὰ τῶν γνωρίμων οὐκ ἀγνοίας ἐστὶ σημεῖον, ὅπερ καὶ ἐν τοῖς ἔμπροσθεν ἐπεσημηνάμεθα· ἀγνοεῖν γὰρ αὐτὸν πολλὰ τῶν ἐνδόξων ἔφη περὶ τὸν Πόντον, οἷον ποταμοὺς καὶ ἔθνη· ὀνομάσαι γὰρ ἄν. τοῦτο δ’ ἐπὶ μέν τινων σφόδρα σημειωδῶν δοίη τις ἄν, οἷον Σκύθας καὶ Μαιῶτιν καὶ Ἴστρον. οὐ γὰρ διὰ σημείων μὲν τοὺς νομάδας εἴρηκε γαλακτοφάγους ἀβίους τε, δικαιοτάτους ἀνθρώπους, καὶ ἔτι ἀγαυοὺς ἱππημολγούς, Σκύθας δὲ οὐκ ἂν εἶπεν ἢ Σαυρομάτας ἢ Σαρμάτας, εἰ δὴ οὕτως ὠνομάζοντο [τότε] ὑπὸ τῶν Ἑλλήνων· οὐδ’ ἂν Θρᾳκῶν τε καὶ Μυσῶν μνησθεὶς τῶν πρὸς τῷ Ἴστρῳ αὐτὸν παρεσίγησε μέγιστον τῶν ποταμῶν ὄντα, καὶ ἄλλως ἐπιφόρως ἔχων πρὸς τὸ τοῖς ποταμοῖς ἀφορίζεσθαι τοὺς τόπους, οὐδ’ ἂν Κιμμερίους λέγων παρῆκε τὸν Βόσπορον ἢ τὴν Μαιῶτιν.", "st": "12.3.26"}, {"sp": "N", "t": "ἐπὶ δὲ τῶν μὴ οὕτω σημειωδῶν ἢ μὴ τότε ἢ μὴ πρὸς τὴν ὑπόθεσιν τί ἄν τις μέμφοιτο; οἷον τὸν Τάναϊν δι’ οὐδὲν ἄλλο γνωριζόμενον ἢ διότι τῆς Ἀσίας καὶ τῆς Εὐρώπης ὅριόν ἐστιν· ἀλλ’ οὔτε τὴν Ἀσίαν οὔτε τὴν Εὐρώπην ὠνόμαζόν πω οἱ τότε, οὐδὲ διῄρητο οὕτως εἰς τρεῖς ἠπείρους ἡ οἰκουμένη· ὠνόμασε γὰρ ἄν που διὰ τὸ λίαν σημειῶδες, ὡς καὶ τὴν Λιβύην καὶ τὸν λίβα τὸν ἀπὸ τῶν ἑσπερίων τῆς Λιβύης πνέοντα· τῶν δ’ ἠπείρων μήπω διωρισμένων οὐδὲ τοῦ Τανάιδος ἔδει καὶ τῆς μνήμης αὐτοῦ. πολλὰ δὲ καὶ ἀξιομνημόνευτα μέν, οὐχ ὑπέδραμε δέ· πολὺ γὰρ δὴ καὶ τὸ ἐπελευστικὸν εἶδος ἔν τε τοῖς λόγοις καὶ ἐν ταῖς πράξεσίν ἐστιν. ἐκ πάντων δὲ [τούτων καὶ] τῶν τοιούτων δῆλόν ἐστιν ὅτι μοχθηρῷ σημείῳ χρῆται πᾶς ὁ ἐκ τοῦ μὴ λέγεσθαί τι ὑπὸ τοῦ ποιητοῦ τὸ ἀγνοεῖσθαι ἐκεῖνο ὑπ’ αὐτοῦ τεκμαιρόμενος. καὶ δεῖ διὰ πλειόνων παραδειγμάτων ἐξελέγχειν αὐτὸ μοχθηρὸν ὄν· πολλῷ γὰρ αὐτῷ κέχρηνται πολλοί. ἀνακρουστέον οὖν αὐτοὺς προφέροντας τὰ τοιαῦτα, εἰ καὶ ταυτολογήσομεν· οἷον ἐπὶ τῶν ποταμῶν εἴ τις λέγοι τῷ μὴ ὠνομάσθαι ἀγνοεῖσθαι εὐήθη φήσομεν τὸν λόγον· ὅπου γε οὐδὲ Μέλητα τὸν παρὰ τὴν Σμύρναν ῥέοντα ὠνόμακε ποταμόν, τὴν ὑπὸ τῶν πλείστων λεγομένην αὐτοῦ πατρίδα, Ἕρμον ποταμὸν καὶ Ὕλλον ὀνομάζων, οὐδὲ Πακτωλὸν τὸν εἰς ταὐτὸ τούτοις ῥεῖθρον ἐμβάλλοντα, τὴν δ’ ἀρχὴν ἀπὸ τοῦ Τμώλου ἔχοντα οὗ μέμνηται· οὐδ’ αὐτὴν Σμύρναν λέγει, οὐδὲ τὰς ἄλλας τῶν Ἰώνων πόλεις καὶ τῶν Αἰολέων τὰς πλείστας, Μίλητον λέγων καὶ Λέσβον καὶ Τένεδον, οὐδὲ Ληθαῖον τὸν παρὰ Μαγνησίαν ῥέοντα οὐδὲ δὴ Μαρσύαν τοὺς εἰς τὸν Μαίανδρον ἐκδιδόντας, ἐκεῖνον ὀνομάζων καὶ πρὸς τούτοις<br>Ῥῆσόν θ’ Ἑπτάπορόν τε Κάρησόν τε Ῥοδίον τε,<br>καὶ τοὺς ἄλλους, ὧν οἱ πλείους ὀχετῶν οὔκ εἰσι μείζους. πολλάς τε χώρας ὀνομάζων καὶ πόλεις τοτὲ μὲν καὶ τοὺς ποταμοὺς καὶ ὄρη συγκαταλέγει τοτὲ δ’ οὔ· τοὺς γοῦν κατὰ τὴν Αἰτωλίαν καὶ τὴν Ἀττικὴν οὐ λέγει οὐδ’ ἄλλους πλείους· ἔτι δὲ καὶ τῶν πόρρω μεμνημένος τῶν ἐγγὺς σφόδρα οὐ μέμνηται, οὐ δήπου ἀγνοῶν αὐτοὺς γνωρίμους τοῖς ἄλλοις ὄντας· οὐδὲ δὴ τοὺς ἐγγὺς ἐπίσης, ὧν τοὺς μὲν ὀνομάζει τοὺς δὲ οὔ, οἷον Λυκίους μὲν καὶ Σολύμους, Μιλύας δ’ οὔ, οὐδὲ Παμφύλους οὐδὲ Πισίδας· καὶ Παφλαγόνας μὲν καὶ Φρύγας καὶ Μυσούς, Μαριανδυνοὺς δ’ οὔ, οὐδὲ Θυνοὺς οὐδὲ Βιθυνοὺς οὐδὲ Βέβρυκας· Ἀμαζόνων τε μέμνηται, Λευκοσύρων δ’ οὔ, οὐδὲ Σύρων οὐδὲ Καππαδόκων οὐδὲ Λυκαόνων, Φοίνικας καὶ Αἰγυπτίους καὶ Αἰθίοπας θρυλῶν· καὶ Ἀλήιον μὲν πεδίον λέγει καὶ Ἀρίμους, τὸ δὲ ἔθνος ἐν ᾧ ταῦτα σιγᾷ. ὁ μὲν δὴ τοιοῦτος ἔλεγχος ψευδής ἐστιν, ὁ δ’ ἀληθής, ὅταν δείκνυται ψεῦδος λεγόμενόν τι. ἀλλ’ οὐδ’ ἐν τῷ τοιούτῳ κατορθῶν ἐδείχθη, ὅτε γε ἐθάρρησε πλάσματα λέγειν τοὺς ἀγαυοὺς ἱππημολγοὺς [καὶ] γαλακτοφάγους. τοσαῦτα καὶ πρὸς Ἀπολλόδωρον· ἐπάνειμι δὲ ἐπὶ τὴν ἑξῆς περιήγησιν.", "st": "12.3.27"}, {"sp": "N", "t": "ὑπὲρ μὲν δὴ τῶν περὶ Φαρνακίαν καὶ Τραπεζοῦντα τόπων οἱ Τιβαρηνοὶ καὶ Χαλδαῖοι μέχρι τῆς μικρᾶς Ἀρμενίας εἰσίν. αὕτη δ’ ἐστὶν εὐδαίμων ἱκανῶς χώρα· δυνάσται δ’ αὐτὴν κατεῖχον ἀεί, καθάπερ τὴν Σωφηνήν, τοτὲ μὲν φίλοι τοῖς ἄλλοις Ἀρμενίοις ὄντες τοτὲ δὲ ἰδιοπραγοῦντες· ὑπηκόους δ’ εἶχον καὶ τοὺς Χαλδαίους καὶ Τιβαρηνούς, ὥστε μέχρι Τραπεζοῦντος καὶ Φαρνακίας διατείνειν τὴν ἀρχὴν αὐτῶν. αὐξηθεὶς δὲ Μιθριδάτης ὁ Εὐπάτωρ καὶ τῆς Κολχίδος κατέστη κύριος καὶ τούτων ἁπάντων, Ἀντιπάτρου τοῦ Σίσιδος παραχωρήσαντος αὐτῷ. ἐπεμελήθη δὲ οὕτω τῶν τόπων τούτων ὥστε πέντε καὶ ἑβδομήκοντα φρούρια ἐν αὐτοῖς κατεσκευάσατο, οἷσπερ τὴν πλείστην γάζαν ἐνεχείρισε. τούτων δ’ ἦν ἀξιολογώτατα ταῦτα, Ὕδαρα καὶ Βασγοιδάριζα καὶ Σινορία, ἐπιπεφυκὸς τοῖς ὁρίοις τῆς μεγάλης Ἀρμενίας χωρίον, διόπερ Θεοφάνης Συνορίαν παρωνόμασεν. ἡ γὰρ τοῦ Παρυάδρου πᾶσα ὀρεινὴ τοιαύτας ἐπιτηδειότητας ἔχει πολλὰς εὔυδρός τε οὖσα καὶ ὑλώδης καὶ ἀποτόμοις φάραγξι καὶ κρημνοῖς διειλημμένη πολλαχόθεν· ἐτετείχιστο γοῦν ἐνταῦθα τὰ πλεῖστα τῶν γαζοφυλακίων, καὶ δὴ καὶ τὸ τελευταῖον εἰς ταύτας κατέφυγε τὰς ἐσχατιὰς τῆς Ποντικῆς βασιλείας ὁ Μιθριδάτης ἐπιόντος Πομπηίου, καὶ τῆς Ἀκιλισηνῆς κατὰ Δάστειρα εὔυδρον ὄρος καταλαβόμενος (πλησίον δ’ ἦν καὶ ὁ Εὐφράτης ὁ διορίζων τὴν Ἀκιλισηνὴν ἀπὸ τῆς μικρᾶς Ἀρμενίας) διέτριψε τέως ἕως πολιορκούμενος ἠναγκάσθη φυγεῖν διὰ τῶν ὀρῶν εἰς Κολχίδα κἀκεῖθεν εἰς Βόσπορον. Πομπήιος δὲ περὶ τὸν τόπον τοῦτον πόλιν ἔκτισεν ἐν τῇ μικρᾷ Ἀρμενίᾳ Νικόπολιν, ἣ καὶ νῦν συμμένει καὶ οἰκεῖται καλῶς.", "st": "12.3.28"}, {"sp": "N", "t": "τὴν μὲν οὖν μικρὰν Ἀρμενίαν ἄλλοτ’ ἄλλων ἐχόντων, ὡς ἐβούλοντο Ῥωμαῖοι, τὸ τελευταῖον εἶχεν ὁ Ἀρχέλαος. τοὺς δὲ Τιβαρηνοὺς καὶ Χαλδαίους μέχρι Κολχίδος καὶ Φαρνακίας καὶ Τραπεζοῦντος ἔχει Πυθοδωρίς, γυνὴ σώφρων καὶ δυνατὴ προΐστασθαι πραγμάτων. ἔστι δὲ θυγάτηρ Πυθοδώρου τοῦ Τραλλιανοῦ, γυνὴ δ’ ἐγένετο Πολέμωνος καὶ συνεβασίλευσεν ἐκείνῳ χρόνον τινά, εἶτα διεδέξατο τὴν ἀρχήν, τελευτήσαντος ἐν τοῖς Ἀσπουργιανοῖς καλουμένοις τῶν περὶ τὴν Σινδικὴν βαρβάρων· δυεῖν δ’ ἐκ τοῦ Πολέμωνος ὄντων υἱῶν καὶ θυγατρὸς ἡ μὲν ἐδόθη Κότυϊ τῷ Σαπαίῳ, δολοφονηθέντος δὲ ἐχήρευσε παῖδας ἔχουσα ἐξ αὐτοῦ· δυναστεύει δ’ ὁ πρεσβύτατος αὐτῶν· τῶν δὲ τῆς Πυθοδωρίδος υἱῶν ὁ μὲν ἰδιώτης συνδιῴκει τῇ μητρὶ τὴν ἀρχήν, ὁ δὲ νεωστὶ καθέσταται τῆς μεγάλης Ἀρμενίας βασιλεύς. αὐτὴ δὲ συνῴκησεν Ἀρχελάῳ καὶ συνέμεινεν ἐκείνῳ μέχρι τέλους, νῦν δὲ χηρεύει, τά τε λεχθέντα ἔχουσα χωρία καὶ ἄλλα ἐκείνων χαριέστερα, περὶ ὧν ἐφεξῆς ἐροῦμεν.", "st": "12.3.29"}, {"sp": "N", "t": "τῇ γὰρ Φαρνακίᾳ συνεχής ἐστιν ἡ Σιδήνη καὶ ἡ Θεμίσκυρα. τούτων δ’ ἡ Φανάροια ὑπέρκειται μέρος ἔχουσα τοῦ Πόντου τὸ κράτιστον· καὶ γὰρ ἐλαιόφυτός ἐστι καὶ εὔοινος καὶ τὰς ἄλλας ἔχει πάσας ἀρετάς, ἐκ μὲν τῶν ἑῴων μερῶν προβεβλημένη τὸν Παρυάδρην παράλληλον αὐτῇ κατὰ μῆκος, ἐκ δὲ τῶν πρὸς δύσιν τὸν Λίθρον καὶ τὸν Ὄφλιμον. ἔστι δ’ αὐλὼν καὶ μῆκος ἔχων ἀξιόλογον καὶ πλάτος· διαρρεῖ δ’ αὐτὴν ἐκ μὲν τῆς Ἀρμενίας ὁ Λύκος, ἐκ δὲ τῶν περὶ Ἀμάσειαν στενῶν ὁ Ἶρις· συμβάλλουσι δ’ ἀμφότεροι κατὰ μέσον που τὸν αὐλῶνα, ἐπὶ τῇ συμβολῇ δ’ ἵδρυται πόλις, ἣν ὁ μὲν πρῶτος ὑποβεβλημένος Εὐπατορίαν ἀφ’ αὑτοῦ προσηγόρευσε, Πομπήιος δ’ ἡμιτελῆ καταλαβών, προσθεὶς χώραν καὶ οἰκήτορας Μαγνόπολιν προσεῖπεν. αὕτη μὲν οὖν ἐν μέσῳ κεῖται τῷ πεδίῳ, πρὸς αὐτῇ δὲ τῇ παρωρείᾳ τοῦ Παρυάδρου Κάβειρα ἵδρυται, σταδίοις ἑκατὸν καὶ πεντήκοντά που νοτιωτέρα τῆς Μαγνοπόλεως, ὅσον καὶ Ἀμάσεια δυσμικωτέρα αὐτῆς ἐστιν· ἐν δὲ τοῖς Καβείροις τὰ βασίλεια Μιθριδάτου κατεσκεύαστο καὶ ὁ ὑδραλέτης καὶ τὰ ζωγρεῖα καὶ αἱ πλησίον θῆραι καὶ τὰ μέταλλα.", "st": "12.3.30"}, {"sp": "N", "t": "ἐνταῦθα δὲ καὶ τὸ Καινὸν χωρίον προσαγορευθέν, ἐρυμνὴ καὶ ἀπότομος πέτρα, διέχουσα τῶν Καβείρων ἔλαττον ἢ διακοσίους σταδίους· ἔχει δ’ ἐπὶ τῇ κορυφῇ πηγὴν ἀναβάλλουσαν πολὺ ὕδωρ, πρός τε τῇ ῥίζῃ ποταμὸν καὶ φάραγγα βαθεῖαν· τὸ δ’ ὕψος ἐξαίσιον τῆς πέτρας ἐστὶ ἄνω τοῦ αὐχένος, ὥστ’ ἀπολιόρκητός ἐστι· τετείχισται δὲ θαυμαστῶς πλὴν ὅσον οἱ Ῥωμαῖοι κατέσπασαν· οὕτω δ’ ἐστὶν ἅπασα ἡ κύκλῳ κατάδρυμος καὶ ὀρεινὴ καὶ ἄνυδρος, ὥστ’ ἐντὸς ἑκατὸν καὶ εἴκοσι σταδίων μὴ εἶναι δυνατὸν στρατοπεδεύσασθαι. ἐνταῦθα μὲν ἦν τῷ Μιθριδάτῃ τὰ τιμιώτατα τῶν κειμηλίων, ἃ νῦν ἐν τῷ Καπιτωλίῳ κεῖται Πομπηίου ἀναθέντος. ταύτην δὴ τὴν χώραν ἔχει πᾶσαν ἡ Πυθοδωρὶς προσεχῆ οὖσαν τῇ βαρβάρῳ τῇ ὑπ’ αὐτῆς κατεχομένῃ, καὶ τὴν Ζηλῖτιν καὶ Μεγαλοπολῖτιν. τὰ δὲ Κάβειρα Πομπηίου σκευάσαντος εἰς πόλιν καὶ καλέσαντος Διόσπολιν, ἐκείνη προσκατεσκεύασε καὶ Σεβαστὴν μετωνόμασε, βασιλείῳ τε τῇ πόλει χρῆται. ἔχει δὲ καὶ τὸ ἱερὸν Μηνὸς Φαρνάκου καλούμενον, τὴν Ἀμερίαν κωμόπολιν πολλοὺς ἱεροδούλους ἔχουσαν καὶ χώραν ἱεράν, ἣν ὁ ἱερώμενος ἀεὶ καρποῦται. ἐτίμησαν δ’ οἱ βασιλεῖς τὸ ἱερὸν τοῦτο οὕτως εἰς ὑπερβολὴν ὥστε τὸν βασιλικὸν καλούμενον ὅρκον τοῦτον ἀπέφηναν “τύχην βασιλέως” καὶ “μῆνα Φαρνάκου.” ἔστι δὲ καὶ τοῦτο τῆς σελήνης τὸ ἱερόν, καθάπερ τὸ ἐν Ἀλβανοῖς καὶ τὰ ἐν Φρυγίᾳ, τό τε τοῦ Μηνὸς ἐν τῷ ὁμωνύμῳ τόπῳ καὶ τὸ τοῦ Ἀσκαίου τὸ πρὸς Ἀντιοχείᾳ τῇ πρὸς Πισιδίᾳ καὶ τὸ ἐν τῇ χώρᾳ τῶν Ἀντιοχέων.", "st": "12.3.31"}, {"sp": "N", "t": "ὑπὲρ δὲ τῆς Φαναροίας ἐστὶ τὰ Κόμανα τὰ ἐν τῷ Πόντῳ, ὁμώνυμα τοῖς ἐν τῇ μεγάλῃ Καππαδοκίᾳ καὶ τῇ αὐτῇ θεῷ καθιερωμένα, ἀφιδρυθέντα ἐκεῖθεν, σχεδὸν δέ τι καὶ τῇ ἀγωγῇ παραπλησίᾳ κεχρημένα τῶν τε ἱερουργιῶν καὶ τῶν θεοφοριῶν καὶ τῆς περὶ τοὺς ἱερέας τιμῆς, καὶ μάλιστα ἐπὶ τῶν πρὸ τοῦ βασιλέων, ἡνίκα δὶς τοῦ ἔτους κατὰ τὰς ἐξόδους λεγομένας τῆς θεοῦ διάδημα φορῶν ἐτύγχανεν ὁ ἱερεύς, καὶ ἦν δεύτερος κατὰ τιμὴν μετὰ τὸν βασιλέα.", "st": "12.3.32"}, {"sp": "N", "t": "ἐμνήσθημεν δὲ πρότερον Δορυλάου τε τοῦ τακτικοῦ, ὃς ἦν πρόπαππος τῆς μητρὸς ἡμῶν, καὶ ἄλλου Δορυλάου, ὃς ἦν ἐκείνου ἀδελφιδοῦς υἱὸς δὲ Φιλεταίρου, καὶ διότι ἐκεῖνος τῶν ἄλλων τιμῶν παρὰ τοῦ Εὐπάτορος τῶν μεγίστων τυχὼν καὶ δὴ καὶ τῆς ἐν Κομάνοις ἱερωσύνης ἐφωράθη τὴν βασιλείαν ἀφιστὰς Ῥωμαίοις· καταλυθέντος δ’ ἐκείνου συνδιεβλήθη καὶ τὸ γένος. ὀψὲ δὲ Μοαφέρνης ὁ θεῖος τῆς μητρὸς ἡμῶν εἰς ἐπιφάνειαν ἦλθεν ἤδη πρὸς καταλύσει τῆς βασιλείας, καὶ πάλιν τῷ βασιλεῖ συνητύχησαν καὶ αὐτὸς καὶ οἱ ἐκείνου φίλοι, πλὴν εἴ τινες ἔφθησαν προαποστάντες αὐτοῦ, καθάπερ ὁ πάππος ἡμῶν ὁ πρὸς αὐτῆς, ὃς ἰδὼν τὰ τοῦ βασιλέως κακῶς φερόμενα ἐν τῷ πρὸς Λεύκολλον πολέμῳ, καὶ ἅμα ἠλλοτριωμένος αὐτοῦ δι’ ὀργήν, ὅτι ἀνεψιὸν αὐτοῦ Τίβιον καὶ υἱὸν ἐκείνου Θεόφιλον ἐτύγχανεν ἀπεκτονὼς νεωστί, ὥρμησε τιμωρεῖν ἐκείνοις τε καὶ ἑαυτῷ, καὶ λαβὼν παρὰ τοῦ Λευκόλλου πίστεις ἀφίστησιν αὐτῷ πεντεκαίδεκα φρούρια· καὶ ἐπαγγελίαι μὲν ἐγένοντο ἀντὶ τούτων μεγάλαι, ἐπελθὼν δὲ Πομπήιος ὁ διαδεξάμενος τὸν πόλεμον πάντας τοὺς ἐκείνῳ τι χαρισαμένους ἐχθροὺς ὑπέλαβε διὰ τὴν γενομένην αὐτῷ πρὸς ἐκεῖνον ἀπέχθειαν, διαπολεμήσας δὲ καὶ ἐπανελθὼν οἴκαδε ἐξενίκησεν ὥστε τὰς τιμάς, ἃς ὑπέσχετο ὁ Λεύκολλος τῶν Ποντικῶν τισι, μὴ κυρῶσαι τὴν σύγκλητον· ἄδικον γὰρ εἶναι κατορθώσαντος ἑτέρου τὸν πόλεμον τὰ βραβεῖα ἐπ’ ἄλλῳ γενέσθαι καὶ τὴν τῶν ἀριστείων διανομήν.", "st": "12.3.33"}, {"sp": "N", "t": "ἐπὶ μὲν οὖν τῶν βασιλέων οὕτω τὰ Κόμανα διῳκεῖτο ὡς εἴρηται, παραλαβὼν δὲ Πομπήιος τὴν ἐξουσίαν Ἀρχέλαον ἐπέστησεν ἱερέα καὶ προσώρισεν αὐτῷ χώραν δίσχοινον κύκλῳ (τοῦτο δ’ ἔστιν ἑξήκοντα στάδιοι) πρὸς τῇ ἱερᾷ, προστάξας τοῖς ἐνοικοῦσι πειθαρχεῖν αὐτῷ· τούτων μὲν οὖν ἡγεμὼν ἦν καὶ τῶν τὴν πόλιν οἰκούντων ἱεροδούλων κύριος πλὴν τοῦ πιπράσκειν· ἦσαν δὲ οὐκ ἐλάττους οὐδ’ ἐνταῦθα τῶν ἑξακισχιλίων. ἦν δ’ οὗτος Ἀρχέλαος υἱὸς μὲν τοῦ ὑπὸ Σύλλα καὶ τῆς συγκλήτου τιμηθέντος, φίλος δὲ Γαβινίου τῶν ὑπατικῶν τινος. ἐκείνου δὲ πεμφθέντος εἰς Συρίαν ἧκε καὶ αὐτὸς ἐπ’ ἐλπίδι τοῦ κοινωνήσειν αὐτῷ παρασκευαζομένῳ πρὸς τὸν Παρθικὸν πόλεμον, οὐκ ἐπιτρεπούσης δὲ τῆς συγκλήτου ταύτην ἀφεὶς τὴν ἐλπίδα ἄλλην εὕρατο μείζω. ἐτύγχανε γὰρ Πτολεμαῖος ὁ τῆς Κλεοπάτρας πατὴρ ὑπὸ τῶν Αἰγυπτίων ἐκβεβλημένος, θυγάτηρ δ’ αὐτοῦ κατεῖχε τὴν βασιλείαν, ἀδελφὴ πρεσβυτέρα τῆς Κλεοπάτρας· ταύτῃ ζητουμένου ἀνδρὸς βασιλικοῦ γένους ἐνεχείρισεν ἑαυτὸν τοῖς συμπράττουσι, προσποιησάμενος Μιθριδάτου τοῦ Εὐπάτορος υἱὸς [εἶναι], καὶ παραδεχθεὶς ἐβασίλευσεν ἓξ μῆνας. τοῦτον μὲν οὖν ὁ Γαβίνιος ἀνεῖλεν ἐν παρατάξει κατάγων τὸν Πτολεμαῖον.", "st": "12.3.34"}, {"sp": "N", "t": "υἱὸς δ’ αὐτοῦ τὴν ἱερωσύνην παρέλαβεν· εἶθ’ ὕστερον Λυκομήδης, ᾧ καὶ τετράσχοινος ἄλλη προσετέθη· καταλυθέντος δὲ καὶ τούτου νῦν ἔχει Δύτευτος υἱὸς Ἀδιατόριγος, ὃς δοκεῖ ταύτης τυγχάνειν τῆς τιμῆς παρὰ Καίσαρος τοῦ Σεβαστοῦ δι’ ἀρετήν. ὁ μὲν γὰρ Καῖσαρ θριαμβεύσας τὸν Ἀδιατόριγα μετὰ παίδων καὶ γυναικὸς ἔγνω ἀναιρεῖν μετὰ τοῦ πρεσβυτάτου τῶν παίδων (ἦν δὲ πρεσβύτατος οὗτος), τοῦ δὲ δευτέρου τῶν ἀδελφῶν αὐτοῦ φήσαντος εἶναι πρεσβυτάτου πρὸς τοὺς ἀπάγοντας στρατιώτας, ἔρις ἦν ἀμφοτέροις πολὺν χρόνον ἕως οἱ γονεῖς ἔπεισαν τὸν Δύτευτον παραχωρῆσαι τῷ νεωτέρῳ τῆς νίκης· αὐτὸν γὰρ ἐν ἡλικίᾳ μᾶλλον ὄντα ἐπιτηδειότερον κηδεμόνα τῇ μητρὶ ἔσεσθαι καὶ τῷ λειπομένῳ ἀδελφῷ· οὕτω δὲ τὸν μὲν συναποθανεῖν τῷ πατρί, τοῦτον δὲ σωθῆναι καὶ τυχεῖν τῆς τιμῆς ταύτης. αἰσθόμενος γάρ, ὡς ἔοικε, Καῖσαρ ἤδη τῶν ἀνθρώπων ἀνῃρημένων ἠχθέσθη, καὶ τούς γε σωζομένους εὐεργεσίας καὶ ἐπιμελείας ἀξίους ὑπέλαβε δοὺς αὐτοῖς ταύτην τὴν τιμήν.", "st": "12.3.35"}, {"sp": "N", "t": "τὰ μὲν οὖν Κόμανα εὐανδρεῖ καὶ ἔστιν ἐμπόριον τοῖς ἀπὸ τῆς Ἀρμενίας ἀξιόλογον· συνέρχονται δὲ κατὰ τὰς ἐξόδους τῆς θεοῦ πανταχόθεν ἔκ τε τῶν πόλεων καὶ τῆς χώρας ἄνδρες ὁμοῦ γυναιξὶν ἐπὶ τὴν ἑορτήν· καὶ ἄλλοι δὲ κατ’ εὐχὴν ἀεί τινες ἐπιδημοῦσι θυσίας ἐπιτελοῦντες τῇ θεῷ. καί εἰσιν ἁβροδίαιτοι οἱ ἐνοικοῦντες, καὶ οἰνόφυτα τὰ κτήματα αὐτῶν ἐστι πάντα, καὶ πλῆθος γυναικῶν τῶν ἐργαζομένων ἀπὸ τοῦ σώματος, ὧν αἱ πλείους εἰσὶν ἱεραί. τρόπον γὰρ δή τινα μικρὰ Κόρινθός ἐστιν ἡ πόλις· καὶ γὰρ ἐκεῖ διὰ τὸ πλῆθος τῶν ἑταιρῶν, αἳ τῆς Ἀφροδίτης ἦσαν ἱεραί, πολὺς ἦν ὁ ἐπιδημῶν καὶ ἐνεορτάζων τῷ τόπῳ· οἱ δ’ ἐμπορικοὶ καὶ στρατιωτικοὶ τελέως ἐξανηλίσκοντο, ὥστ’ ἐπ’ αὐτῶν καὶ παροιμίαν ἐκπεσεῖν τοιαύτην<br>οὐ παντὸς ἀνδρὸς εἰς Κόρινθόν ἐσθ’ ὁ πλοῦς.<br>τὰ μὲν δὴ Κόμανα τοιαῦτα.", "st": "12.3.36"}, {"sp": "N", "t": "τὴν δὲ κύκλῳ πᾶσαν ἔχει Πυθοδωρίς, ἧς ἥ τε Φανάροια ἔστι καὶ ἡ Ζηλῖτις καὶ ἡ Μεγαλοπολῖτις. περὶ μὲν Φαναροίας εἴρηται· ἡ δὲ Ζηλῖτις ἔχει πόλιν Ζῆλα ἐπὶ χώματι Σεμιράμιδος τετειχισμένην, ἔχουσαν τὸ ἱερὸν τῆς Ἀναΐτιδος, ἥνπερ καὶ οἱ Ἀρμένιοι σέβονται. αἱ μὲν οὖν ἱεροποιίαι μετὰ μείζονος ἁγιστείας ἐνταῦθα συντελοῦνται, καὶ τοὺς ὅρκους περὶ τῶν μεγίστων ἐνταῦθα Ποντικοὶ πάντες ποιοῦνται· τὸ δὲ πλῆθος τῶν ἱεροδούλων καὶ αἱ τῶν ἱερέων τιμαὶ παρὰ μὲν τοῖς βασιλεῦσι τὸν αὐτὸν εἶχον τύπον ὅνπερ προείπομεν, νυνὶ δὲ ἐπὶ τῇ Πυθοδωρίδι πάντ’ ἐστίν. ἐκάκωσαν δὲ πολλοὶ καὶ ἐμείωσαν τό τε πλῆθος τῶν ἱεροδούλων καὶ τὴν ἄλλην εὐπορίαν. ἐμειώθη δὲ καὶ ἡ παρακειμένη χώρα μερισθεῖσα εἰς πλείους δυναστείας. ἡ λεγομένη Ζηλῖτις. τὸ παλαιὸν μὲν γὰρ οἱ βασιλεῖς οὐχ ὡς πόλιν ἀλλ’ ὡς ἱερὸν διῴκουν τῶν Περσικῶν θεῶν τὰ Ζῆλα, καὶ ἦν ὁ ἱερεὺς κύριος τῶν πάντων· ᾠκεῖτο δ’ ὑπὸ τοῦ πλήθους τῶν ἱεροδούλων καὶ τοῦ ἱερέως ὄντος ἐν περιουσίᾳ μεγάλῃ, καὶ τοῖς περὶ αὐτὸν οὐκ ὀλίγοις χώρα τε ὑπέκειτο ἱερὰ καὶ ἦν τοῦ ἱερέως. Πομπήιος δὲ πολλὰς ἐπαρχίας προσώρισε τῷ τόπῳ καὶ πόλιν ὠνόμασε καὶ ταύτην καὶ τὴν Μεγαλόπολιν, συνθεὶς ταύτην τε εἰς ἓν τήν τε Κουλουπηνὴν καὶ τὴν Καμισηνήν, ὁμόρους οὔσας τῇ τε μικρᾷ Ἀρμενίᾳ καὶ τῇ Λαουιανσηνῇ, ἐχούσας ὀρυκτοὺς ἅλας καὶ ἔρυμα ἀρχαῖον τὰ Κάμισα νῦν κατεσπασμένον· οἱ δὲ μετὰ ταῦτα ἡγεμόνες τῶν Ῥωμαίων τῶν δυεῖν πολιτευμάτων τούτων τὰ μὲν τοῖς Κομάνων ἱερεῦσι προσένειμαν, τὰ δὲ τῷ Ζήλων ἱερεῖ, τὰ δ’ Ἀτεπόριγι, δυνάστῃ τινὶ τοῦ τετραρχικοῦ γένους τῶν Γαλατῶν ἀνδρί· τελευτήσαντος δ’ ἐκείνου ταύτην μὲν τὴν μερίδα οὐ πολλὴν οὖσαν ὑπὸ Ῥωμαίοις εἶναι συμβαίνει καλουμένην ἐπαρχίαν (καὶ ἔστι σύστημα καθ’ αὑτὸ τὸ πολίχνιον συνοικισάντων τὰ Κάρανα, ἀφ’ οὗ καὶ ἡ χώρα Καρανῖτις λέγεται), τὰ δὲ λοιπὰ ἔχει Πυθοδωρὶς καὶ ὁ Δύτευτος.", "st": "12.3.37"}, {"sp": "N", "t": "λείπεται δὲ τοῦ Πόντου [τὰ] μεταξὺ ταύτης τε τῆς χώρας καὶ τῆς Ἀμισηνῶν καὶ Σινωπέων, πρός τε τὴν Καππαδοκίαν συντείνοντα καὶ Γαλάτας καὶ Παφλαγόνας. μετὰ μὲν οὖν τὴν Ἀμισηνῶν μέχρι τοῦ Ἅλυος ἡ Φαζημωνῖτις ἔστιν, ἣν Πομπήιος Νεαπολῖτιν ὠνόμασε κατὰ Φαζημῶνα κώμην, [πόλιν] ἀποδείξας τὴν κατοικίαν καὶ προσαγορεύσας Νεάπολιν. ταύτης δὲ τῆς χώρας τὸ μὲν προσάρκτιον πλευρὸν ἡ Γαζηλωνῖτις συγκλείει καὶ ἡ τῶν Ἀμισηνῶν, τὸ δὲ ἑσπέριον ὁ Ἅλυς, τὸ δ’ ἑῷον ἡ Φανάροια, τὸ δὲ λοιπὸν ἡ ἡμετέρα χώρα ἡ τῶν Ἀμασέων, πολὺ πασῶν πλείστη καὶ ἀρίστη. τὸ μὲν οὖν πρὸς τῇ Φαναροίᾳ μέρος τῆς Φαζημωνίτιδος λίμνη κατέχει πελαγία τὸ μέγεθος ἡ Στιφάνη καλουμένη, πολύοψος καὶ κύκλῳ νομὰς ἀφθόνους ἔχουσα καὶ παντοδαπάς· ἐπίκειται δ’ αὐτῇ φρούριον ἐρυμνὸν ἔρημον νῦν Ἰκίζαρι, καὶ πλησίον βασίλειον κατεσκαμμένον· ἡ δὲ λοιπὴ ψιλὴ τὸ πλέον καὶ σιτοφόρος χώρα. ὑπέρκειται δὲ τῆς τῶν Ἀμασέων τά τε θερμὰ ὕδατα τῶν Φαζημωνιτῶν ὑγιεινὰ σφόδρα, καὶ τὸ Σαγύλιον ἐπὶ ὄρους ὀρθίου καὶ ὑψηλοῦ πρὸς ὀξεῖαν ἀνατείνοντος ἄκραν ἔρυμα ἱδρυμένον ἔχον καὶ ὑδρεῖον δαψιλές, ὃ νῦν ὠλιγώρηται, τοῖς δὲ βασιλεῦσιν ἦν χρήσιμον εἰς πολλά. ἐνταῦθα δὲ ἑάλω καὶ διεφθάρη ὑπὸ τῶν Φαρνάκου τοῦ βασιλέως παίδων Ἀρσάκης, δυναστεύων καὶ νεωτερίζων, ἐπιτρέψαντος οὐδενὸς τῶν ἡγεμόνων· ἑάλω δὲ οὐ βίᾳ τοῦ ἐρύματος ληφθέντος ὑπὸ Πολέμωνος καὶ Λυκομήδους, βασιλέων ἀμφοῖν, ἀλλὰ λιμῷ· ἀνέφυγε γὰρ εἰς τὸ ὄρος παρασκευῆς χωρὶς εἰργόμενος τῶν πεδίων, εὗρε δὲ καὶ τὰ ὑδρεῖα ἐμπεφραγμένα πέτραις ἠλιβάτοις· οὕτω γὰρ διετέτακτο Πομπήιος, κατασπᾶν κελεύσας τὰ φρούρια καὶ μὴ ἐᾶν χρήσιμα τοῖς ἀναφεύγειν εἰς αὐτὰ βουλομένοις λῃστηρίων χάριν. ἐκεῖνος μὲν οὖν οὕτω διέταξε τὴν Φαζημωνῖτιν, οἱ δ’ ὕστερον βασιλεῦσι καὶ ταύτην ἔνειμαν.", "st": "12.3.38"}, {"sp": "N", "t": "ἡ δ’ ἡμετέρα πόλις κεῖται μὲν ἐν φάραγγι βαθείᾳ καὶ μεγάλῃ, δι’ ἧς ὁ Ἶρις φέρεται ποταμός, κατεσκεύασται δὲ θαυμαστῶς προνοίᾳ τε καὶ φύσει, πόλεως τε ἅμα καὶ φρουρίου παρέχεσθαι χρείαν δυναμένη· πέτρα γὰρ ὑψηλὴ καὶ περίκρημνος κατερρωγυῖα ἐπὶ τὸν ποταμόν, τῇ μὲν ἔχουσα τὸ τεῖχος ἐπὶ τῷ χείλει τοῦ ποταμοῦ καθ’ ὃ ἡ πόλις συνῴκισται, τῇ δ’ ἀνατρέχον ἑκατέρωθεν ἐπὶ τὰς κορυφάς· δύο δ’ εἰσὶ συμφυεῖς ἀλλήλαις πεπυργωμέναι παγκάλως· ἐν δὲ τῷ περιβόλῳ τούτῳ βασίλειά τ’ ἐστὶ καὶ μνήματα βασιλέων· αἱ κορυφαὶ δ’ ἔχουσιν αὐχένα παντάπασι στενόν, πέντε ἢ ἓξ σταδίων ἑκατέρωθεν τὸ ὕψος ἀπὸ τῆς ποταμίας ἀναβαίνοντι καὶ τῶν προαστείων· ἀπὸ δὲ τοῦ αὐχένος ἐπὶ τὰς κορυφὰς ἄλλη σταδιαία λείπεται πρόσβασις ὀξεῖα καὶ πάσης βίας κρείττων· ἔχει δὲ καὶ ὑδρεῖα ἐντὸς ἀναφαίρετα, συρίγγων τετμημένων δυεῖν, τῆς μὲν ἐπὶ τὸν ποταμὸν τῆς δ’ ἐπὶ τὸν αὐχένα· ἐπέζευκται δὲ γέφυρα τῷ ποταμῷ μία μὲν ἀπὸ τῆς πόλεως ἐπὶ τὸ προάστειον, ἄλλη δ’ ἀπὸ τοῦ προαστείου πρὸς τὴν ἔξω χώραν· κατὰ γὰρ τὴν γέφυραν ταύτην ἀπολήγει τὸ ὄρος τὸ τῆς πέτρας ὑπερκείμενον. αὐλὼν δ’ ἐστὶν ἀπὸ τοῦ ποταμοῦ διήκων οὐ πλατὺς τὸ πρῶτον τελέως, ἔπειτα πλατύνεται καὶ ποιεῖ τὸ Χιλιόκωμον καλούμενον πεδίον· εἶθ’ ἡ Διακοπηνὴ καὶ ἡ Πιμωλισηνὴ χώρα πᾶσα εὐδαίμων μέχρι τοῦ Ἅλυος. ταῦτα μὲν τὰ ἀρκτικὰ μέρη τῆς τῶν Ἀμασέων χώρας, μῆκος ὅσον πεντακοσίων σταδίων· ἔπειθ’ ἑξῆς ἡ λοιπὴ πολὺ ταύτης ἐπιμηκεστέρα μέχρι τοῦ Βαβανόμου καὶ τῆς Ξιμήνης, ἥπερ καὶ αὐτὴ καθήκει μέχρι πρὸς τὸν Ἅλυν· τοῦτο μὲν δὴ τὸ μῆκος, πλάτος δὲ τὸ ἀπὸ τῶν ἄρκτων πρὸς νότον ἐπί τε τὴν Ζηλῖτιν καὶ τὴν μεγάλην Καππαδοκίαν μέχρι τῶν Τροκμῶν. εἰσὶ δ’ ἐν τῇ Ξιμήνῃ ἅλαι ὀρυκτῶν ἁλῶν, ἀφ’ ὧν εἰκάζουσιν εἰρῆσθαι Ἅλυν τὸν ποταμόν. ἔστι δὲ καὶ ἐρύματα πλείω κατεσκαμμένα ἐν τῇ ἡμετέρᾳ χώρᾳ καὶ ἔρημος γῆ πολλὴ διὰ τὸν Μιθριδατικὸν πόλεμον. ἔστι μέντοι πᾶσα μὲν εὔδενδρος, ἡ δ’ ἱππόβοτος καὶ τοῖς ἄλλοις θρέμμασι πρόσφορος· ἅπασα δ’ οἰκήσιμος καλῶς. ἐδόθη δὲ καὶ ἡ Ἀμάσεια βασιλεῦσι, νῦν δ’ ἐπαρχία ἐστί.", "st": "12.3.39"}, {"sp": "N", "t": "λοιπὴ δ’ ἐστὶν ἡ ἐκτὸς Ἅλυος χώρα τῆς Ποντικῆς ἐπαρχίας ἡ περὶ τὸν Ὄλγασσυν, συναφὴς τῇ Σινωπίδι. ἔστι δ’ ὁ Ὄλγασσυς ὄρος σφόδρα ὑψηλὸν καὶ δύσβατον· καὶ ἱερὰ τοῦ ὄρους τούτου πανταχοῦ καθιδρυμένα ἔχουσιν οἱ Παφλαγόνες. περίκειται δ’ ἱκανῶς χώρα ἀγαθὴ ἥ τε Βλαηνὴ καὶ ἡ Δομανῖτις, δι’ ἧς Ἀμνίας ῥεῖ ποταμός. ἐνταῦθα Μιθριδάτης ὁ Εὐπάτωρ τὰς Νικομήδους τοῦ Βιθυνοῦ δυνάμεις ἄρδην ἠφάνισεν, οὐκ αὐτὸς παρατυχὼν ἀλλὰ διὰ τῶν στρατηγῶν· καὶ ὁ μὲν φεύγων μετ’ ὀλίγων εἰς τὴν οἰκείαν ἐσώθη κἀκεῖθεν εἰς Ἰταλίαν ἔπλευσεν, ὁ δ’ ἠκολούθησε καὶ τήν τε Βιθυνίαν εἷλεν ἐξ ἐφόδου καὶ τὴν Ἀσίαν κατέσχε μέχρι Καρίας καὶ Λυκίας. κἀνταῦθα δ’ ἀπεδείχθη πόλις ἡ Πομπηιούπολις· ἐν δὲ τῇ πόλει ταύτῃ τὸ σανδαρακουργεῖον οὐ πολὺ ἄπωθεν Πιμωλίσων, φρουρίου βασιλικοῦ κατεσκαμμένου, ἀφ’ οὗ ἡ χώρα ἡ ἑκατέρωθεν τοῦ ποταμοῦ καλεῖται Πιμωλισηνή. τὸ δὲ σανδαρακουργεῖον ὄρος κοῖλόν ἐστιν ἐκ τῆς μεταλλείας, ὑπεληλυθότων αὐτὸ τῶν ἐργαζομένων διώρυξι μεγάλαις· εἰργάζοντο δὲ δημοσιῶναι μεταλλευταῖς χρώμενοι τοῖς ἀπὸ κακουργίας ἀγοραζομένοις ἀνδραπόδοις· πρὸς γὰρ τῷ ἐπιπόνῳ τοῦ ἔργου καὶ θανάσιμον καὶ δύσοιστον εἶναι τὸν ἀέρα φασὶ τὸν ἐν τοῖς μετάλλοις διὰ τὴν βαρύτητα τῆς τῶν βώλων ὀδμῆς, ὥστε ὠκύμορα εἶναι τὰ σώματα. καὶ δὴ καὶ ἐκλείπεσθαι συμβαίνει πολλάκις τὴν μεταλλείαν διὰ τὸ ἀλυσιτελές, πλειόνων μὲν ἢ διακοσίων ὄντων τῶν ἐργαζομένων, συνεχῶς δὲ νόσοις καὶ φθοραῖς δαπανωμένων. τοσαῦτα καὶ περὶ τοῦ Πόντου εἰρήσθω.", "st": "12.3.40"}, {"sp": "N", "t": "μετὰ δὲ τὴν Πομπηιούπολιν ἡ λοιπὴ τῆς Παφλαγονίας ἐστὶ τῆς μεσογαίας μέχρι Βιθυνίας ἰοῦσι πρὸς δύσιν. ταύτης δὲ καίπερ ὀλίγης οὔσης μικρὸν μὲν πρὸ ἡμῶν ἦρχον πλείους, νῦν δ’ ἔχουσι Ῥωμαῖοι τοῦ γένους τῶν βασιλέων ἐκλιπόντος. ὀνομάζουσι δ’ οὖν τὴν ὅμορον τῇ Βιθυνίᾳ Τιμωνῖτιν καὶ τὴν Γεζατόριγος καὶ Μαρμωλῖτίν τε καὶ Σανισηνὴν καὶ Ποταμίαν· ἦν δέ τις καὶ Κιμιατηνή, ἐν ᾗ τὰ Κιμίατα, φρούριον ἐρυμνόν, ὑποκείμενον τῇ τοῦ Ὀλγάσσυος ὀρεινῇ, ᾧ χρησάμενος ὁρμητηρίῳ Μιθριδάτης ὁ κτίστης προσαγορευθεὶς κατέστη τοῦ Πόντου κύριος, καὶ οἱ ἀπ’ αὐτοῦ τὴν διαδοχὴν ἐφύλαξαν μέχρι τοῦ Εὐπάτορος. ὕστατος δὲ τῆς Παφλαγονίας ἦρξε Δηιόταρος, Κάστορος υἱὸς ὁ προσαγορευθεὶς φιλάδελφος, τὸ Μορζέου βασίλειον ἔχων τὰ Γάγγρα πολισμάτιον ἅμα καὶ φρούριον.", "st": "12.3.41"}, {"sp": "N", "t": "Εὔδοξος δ’ ὀρυκτοὺς ἰχθῦς ἐν Παφλαγονίᾳ λέγων ἐν ξηροῖς τόποις οὐ διορίζει τὸν τόπον, ἐν ὑγροῖς δὲ περὶ τὴν Ἀσκανίαν λίμνην φησὶ τὴν ὑπὸ Κίῳ, λέγων οὐδὲν σαφές. ἐπεὶ δὲ καὶ τὴν ὅμορον τῷ Πόντῳ Παφλαγονίαν ἐκτιθέμεθα, τοῖς δὲ Παφλαγόσιν ὁμοροῦσιν οἱ Βιθυνοὶ πρὸς δύσιν, πειρασόμεθα καὶ τὰ τούτων ἐπελθεῖν· ἔπειτα λαβόντες ἀρχὴν ἄλλην ἔκ τε τούτων καὶ τῶν Παφλαγόνων τὰ ἑξῆς τούτων τὰ πρὸς νότον μέχρι τοῦ Ταύρου συνυφανοῦμεν τὰ παράλληλα τῷ Πόντῳ καὶ τῇ Καππαδοκίᾳ· τοιαύτην γάρ τινα ὑπογράφει τάξιν καὶ μερισμὸν ἡ τῶν τόπων φύσις.", "st": "12.3.42"}, {"sp": "N", "t": "τὴν δὲ Βιθυνίαν ἀπὸ μὲν τῆς ἀνατολῆς ὁρίζουσι Παφλαγόνες τε καὶ Μαριανδυνοὶ καὶ τῶν Ἐπικτήτων τινές, ἀπὸ δὲ τῶν ἄρκτων ἡ Ποντικὴ θάλαττα ἡ ἀπὸ τῶν ἐκβολῶν τοῦ Σαγγαρίου μέχρι τοῦ στόματος τοῦ κατὰ Βυζάντιον καὶ Χαλκηδόνα, ἀπὸ δὲ δύσεως ἡ Προποντίς, πρὸς νότον δ’ ἥ τε Μυσία καὶ ἡ ἐπίκτητος καλουμένη Φρυγία, ἡ δ’ αὐτὴ καὶ Ἑλλησποντιακὴ Φρυγία καλουμένη.", "st": "12.4.1"}, {"sp": "N", "t": "ταύτης δ’ ἐπὶ μὲν τῷ στόματι τοῦ Πόντου Χαλκηδὼν ἵδρυται, Μεγαρέων κτίσμα, καὶ κώμη Χρυσόπολις καὶ τὸ ἱερὸν τὸ Χαλκηδόνιον, ἔχει δ’ ἡ χώρα μικρὸν ὑπὲρ τῆς θαλάττης κρήνην Ἀζαριτίαν, τρέφουσαν κροκοδείλους μικρούς· ἔπειτ’ ἐκδέχεται τὴν τῶν Χαλκηδονίων ᾐόνα ὁ Ἀστακηνὸς καλούμενος κόλπος, μέρος ὢν τῆς Προποντίδος, ἐν ᾧ ἡ Νικομήδεια ἔκτισται ἐπώνυμος ἑνὸς τῶν Βιθυνικῶν βασιλέων τοῦ κτίσαντος αὐτήν· πολλοὶ δ’ ὁμωνύμως ὠνομάσθησαν, καθάπερ Πτολεμαῖοι διὰ τὴν τοῦ πρώτου δόξαν. ἦν δ’ ἐν αὐτῷ τῷ κόλπῳ καὶ Ἀστακὸς πόλις, Μεγαρέων κτίσμα καὶ Ἀθηναίων καὶ μετὰ ταῦτα Δοιδαλσοῦ, ἀφ’ ἧς καὶ ὁ κόλπος ὠνομάσθη· κατεσκάφη δ’ ὑπὸ Λυσιμάχου· τοὺς δ’ οἰκήτορας μετήγαγεν εἰς Νικομήδειαν ὁ κτίσας αὐτήν.", "st": "12.4.2"}, {"sp": "N", "t": "τῷ δ’ Ἀστακηνῷ κόλπος ἄλλος συνεχής ἐστιν, εἰσέχων μᾶλλον πρὸς ἀνίσχοντα ἥλιον, ἐν ᾧ Προυσιὰς ἔστιν ἡ Κίος πρότερον ὀνομασθεῖσα· κατέσκαψε δὲ τὴν Κίον Φίλιππος, ὁ Δημητρίου μὲν υἱὸς Περσέως δὲ πατήρ, ἔδωκε δὲ Προυσίᾳ τῷ Ζήλα, συγκατασκάψαντι καὶ ταύτην καὶ Μύρλειαν ἀστυγείτονα πόλιν, πλησίον δὲ καὶ Προύσης οὖσαν· ἀναλαβὼν δ’ ἐκεῖνος ἐκ τῶν ἐρειπίων αὐτὰς ἐπωνόμασεν ἀφ’ ἑαυτοῦ μὲν Προυσιάδα πόλιν τὴν Κίον, τὴν δὲ Μύρλειαν Ἀπάμειαν ἀπὸ τῆς γυναικός. οὗτος δ’ ἔστιν ὁ Προυσίας ὁ καὶ Ἀννίβαν δεξάμενος ἀναχωρήσαντα δεῦρο μετὰ τὴν Ἀντιόχου ἧτταν, καὶ τῆς ἐφ’ Ἑλλησπόντῳ Φρυγίας ἀναστὰς κατὰ συμβάσεις τοῖς Ἀτταλικοῖς, ἣν οἱ μὲν πρότερον ἐκάλουν μικρὰν Φρυγίαν, ἐκεῖνοι δ’ ἐπίκτητον ὠνόμασαν· ὑπέρκειται δὲ τῆς Προυσιάδος ὄρος ὃ καλοῦσιν Ἀργανθώνιον. ἐνταῦθα δὲ μυθεύουσι τὸν Ὕλαν ἕνα τῶν Ἡρακλέους ἑταίρων συμπλεύσαντα ἐπὶ τῆς Ἀργοῦς αὐτῷ ἐξιόντα δὲ ἐπὶ ὑδρείαν ὑπὸ νυμφῶν ἁρπαγῆναι· κίον δὲ καὶ τοῦτον Ἡρακλέους ἑταῖρον καὶ σύμπλουν ἐπανελθόντα ἐκ Κόλχων αὐτόθι καταμεῖναι καὶ κτίσαι τὴν πόλιν ἐπώνυμον αὐτοῦ. καὶ νῦν δ’ ἔτι ἑορτή τις ἄγεται παρὰ τοῖς Προυσιεῦσιν καὶ ὀρειβασία θιασευόντων καὶ καλούντων Ὕλαν, ὡς ἂν κατὰ ζήτησιν τὴν ἐκείνου πεποιημένων τὴν ἐπὶ τὰς ὕλας ἔξοδον. πολιτευσάμενοι δὲ πρὸς Ῥωμαίους οἱ Προυσιεῖς εὐνοϊκῶς ἐλευθερίας ἔτυχον. οἱ δ’ Ἀπαμεῖς ἀποικίαν ἐδέξαντο Ῥωμαίων. Προῦσα δὲ ἐπὶ τῷ Ὀλύμπῳ ἵδρυται τῷ Μυσίῳ, πόλις εὐνομουμένη, τοῖς τε Φρυξὶν ὅμορος καὶ τοῖς Μυσοῖς, κτίσμα Προυσίου τοῦ πρὸς Κροῖσον πολεμήσαντος.", "st": "12.4.3"}, {"sp": "N", "t": "διορίσαι δὲ τοὺς ὅρους χαλεπὸν τούς τε Βιθυνῶν καὶ Φρυγῶν καὶ Μυσῶν καὶ ἔτι Δολιόνων τῶν περὶ Κύζικον καὶ Μυγδόνων καὶ Τρώων· καὶ διότι μὲν εἶναι δεῖ ἕκαστον φῦλον χωρὶς ὁμολογεῖται (καὶ ἐπί γε τῶν Φρυγῶν καὶ τῶν Μυσῶν καὶ παροιμιάζονται<br>χωρὶς τὰ Μυσῶν καὶ Φρυγῶν ὁρίσματα),<br>διορίσαι δὲ χαλεπόν. αἴτιον δὲ τὸ τοὺς ἐπήλυδας βαρβάρους καὶ στρατιώτας ὄντας μὴ βεβαίως κατέχειν τὴν κρατηθεῖσαν, ἀλλὰ πλανήτας εἶναι τὸ πλέον ἐκβάλλοντας καὶ ἐκβαλλομένους. ἅπαντα δὲ τὰ ἔθνη ταῦτα Θρᾴκιά τις εἰκάζοι ἂν διὰ τὸ τὴν περαίαν νέμεσθαι τούτους καὶ διὰ τὸ μὴ πολὺ ἐξαλλάττειν ἀλλήλων ἑκατέρους.", "st": "12.4.4"}, {"sp": "N", "t": "ὅμως δ’ ἐφ’ ὅσον εἰκάζειν οἷόν τε, τῆς μὲν Βιθυνίας μέσην ἄν τις θείη καὶ τῆς ἐκβολῆς τοῦ Αἰσήπου τὴν Μυσίαν, ἁπτομένην τῆς θαλάττης καὶ διήκουσαν μέχρι τοῦ Ὀλύμπου σχεδόν [τι] παντός· κύκλῳ δὲ τὴν Ἐπίκτητον κειμένην ἐν τῇ μεσογαία, θαλάττης οὐδαμοῦ ἁπτομένην διατείνουσαν δὲ μέχρι τῶν ἑῴων μερῶν τῆς Ἀσκανίας λίμνης τε καὶ χώρας· ὁμωνύμως γὰρ τῇ λίμνῃ καὶ ἡ χώρα ἐλέγετο, καὶ ἦν αὐτῆς τὸ μὲν Φρύγιον τὸ δὲ Μύσιον ἀπωτέρω δὲ τῆς Τροίας τὸ Φρύγιον. καὶ δὴ καὶ οὕτω δεκτέον τὸ παρὰ τῷ ποιητῇ ὅταν φῇ<br>Φόρκυς δ’ αὖ Φρύγας ἦγε καὶ Ἀσκάνιος θεοειδής,<br>τῆλ’ ἐξ Ἀσκανίης,<br>τῆς Φρυγιακῆς, ὡς οὔσης ἐγγυτέρω ἄλλης Ἀσκανίας Μυσιακῆς τῆς πρὸς τῇ νῦν Νικαίᾳ, ἧς μέμνηται ὅταν φῇ<br>Πάλμυν τ’ Ἀσκάνιόν τε Μόρυν θ’, υἷ’ Ἱπποτίωνος,<br>Μυσῶν ἀγχεμάχων ἡγήτορα,<br>οἵ ῥ’ ἐξ Ἀσκανίης ἐριβώλακος ἦλθον ἀμοιβοί.<br>οὐ θαυμαστὸν δ’ εἰ τῶν Φρυγῶν εἰπών τινα ἡγεμόνα Ἀσκάνιον καὶ ἐξ Ἀσκανίας ἥκοντα, καὶ Μυσῶν τινα λέγει ἡγεμόνα Ἀσκάνιον καὶ ἐξ Ἀσκανίας ἥκοντα· πολλὴ γὰρ ἡ ὁμωνυμία παρ’ αὐτῷ καὶ ἡ ἀπὸ τῶν ποταμῶν καὶ λιμνῶν καὶ χωρίων ἐπίκλησις.", "st": "12.4.5"}, {"sp": "N", "t": "καὶ τὸν Αἴσηπον δὲ τῶν Μυσῶν ὅριον παραδίδωσιν αὐτὸς ὁ ποιητής· τὴν γὰρ ὑπὲρ τοῦ Ἰλίου παρώρειαν τῆς Τροίας καταλέξας τὴν ὑπ’ Αἰνείᾳ ἣν Δαρδανίαν ἐκάλεσε, τίθησιν ἐφεξῆς πρὸς ἄρκτον καὶ τὴν Λυκίαν τὴν ὑπὸ Πανδάρῳ ἐν ᾗ ἡ Ζέλεια· καὶ φησίν<br>οἳ δὲ Ζέλειαν ἔναιον ὑπαὶ πόδα νείατον Ἴδης,<br>ἀφνειοί, πίνοντες ὕδωρ μέλαν Αἰσήποιο<br>Τρῶες.<br>τῇ δὲ Ζελείᾳ ὑποπέπτωκε πρὸς θαλάττῃ ἐπίταδε τοῦ Αἰσήπου τὸ τῆς Ἀδραστείας πεδίον καὶ Τήρεια καὶ ἡ Πιτύα καὶ καθόλου ἡ νῦν Κυζικηνὴ ἡ πρὸς Πριάπῳ ἣν ἐφεξῆς καταλέγει, εἶτα ἀνακάμπτει πάλιν ἐπὶ τὰ πρὸς ἕω μέρη καὶ τὰ ἐπέκεινα, ὥστε ἐμφαίνει τὴν μέχρι Αἰσήπου πέρας ἡγούμενος τῆς Τρῳάδος τὸ ἀρκτικὸν καὶ ἑῷον. ἀλλὰ μὴν μετά γε τὴν Τρῳάδα ἡ Μυσία ἐστὶ καὶ ὁ Ὄλυμπος. ἡ μὲν οὖν παλαιὰ μνήμη τοιαύτην τινὰ ὑπαγορεύει τὴν τῶν ἐθνῶν θέσιν. αἱ δὲ νῦν μεταβολαὶ τὰ πολλὰ ἐξήλλαξαν, ἄλλοτ’ ἄλλων ἐπικρατούντων καὶ τὰ μὲν συγχεόντων τὰ δὲ διασπώντων. καὶ γὰρ Φρύγες ἐπεκράτησαν καὶ Μυσοὶ μετὰ τὴν Τροίας ἅλωσιν, εἶθ’ ὕστερον Λυδοὶ καὶ μετ’ ἐκείνων Αἰολεῖς καὶ Ἴωνες, ἔπειτα Πέρσαι καὶ Μακεδόνες, τελευταῖοι δὲ Ῥωμαῖοι, ἐφ’ ὧν ἤδη καὶ τὰς διαλέκτους καὶ τὰ ὀνόματα ἀποβεβλήκασιν οἱ πλεῖστοι, γεγονότος ἑτέρου τινὸς μερισμοῦ τῆς χώρας, οὗ μᾶλλον φροντίσαι δεῖ τὰ νῦν οἷ’ ἔστι λέγοντας, τῇ δὲ ἀρχαιολογίᾳ μετρίως προσέχοντας.", "st": "12.4.6"}, {"sp": "N", "t": "ἐν δὲ τῇ μεσογαίᾳ τῆς Βιθυνίας τό τε Βιθύνιον ἔστιν ὑπερκείμενον τοῦ Τιείου καὶ ἔχον τὴν περὶ Σάλωνα χώραν ἀρίστην βουβοσίοις, ὅθεν ἐστὶν ὁ Σαλωνίτης τυρός, καὶ Νίκαια ἡ μητρόπολις τῆς Βιθυνίας ἐπὶ τῇ Ἀσκανίᾳ λίμνῃ (περίκειται δὲ κύκλῳ πεδίον μέγα καὶ σφόδρα εὔδαιμον, οὐ πάνυ δὲ ὑγιεινὸν τοῦ θέρους), κτίσμα Ἀντιγόνου μὲν πρῶτον τοῦ Φιλίππου, ὃς αὐτὴν Ἀντιγόνειαν προσεῖπεν, εἶτα Λυσιμάχου, ὃς ἀπὸ τῆς γυναικὸς μετωνόμασε Νίκαιαν· ἦν δ’ αὕτη θυγάτηρ Ἀντιπάτρου. ἔστι δὲ τῆς πόλεως ἑκκαιδεκαστάδιος ὁ περίβολος ἐν τετραγώνῳ σχήματι· ἔστι δὲ καὶ τετράπυλος ἐν πεδίῳ κείμενος ἐρρυμοτομημένος πρὸς ὀρθὰς γωνίας, ὥστ’ ἀφ’ ἑνὸς λίθου κατὰ μέσον ἱδρυμένου τὸ γυμνάσιον τὰς τέτταρας ὁρᾶσθαι πύλας. μικρὸν δ’ ὑπὲρ τῆς Ἀσκανίας λίμνης Ὀτροία πολίχνη, πρὸς τοῖς ὅροις ἤδη τῆς Βιθυνίας τοῖς πρὸς ἕω· εἰκάζουσι δ’ ἀπὸ Ὀτρέως Ὀτροίαν καλεῖσθαι.", "st": "12.4.7"}, {"sp": "N", "t": "ὅτι δ’ ἦν κατοικία Μυσῶν ἡ Βιθυνία πρῶτον μαρτυρήσει Σκύλαξ ὁ Καρυανδεὺς φήσας περιοικεῖν τὴν Ἀσκανίαν λίμνην Φρύγας καὶ Μυσούς, ἔπειτα Διονύσιος ὁ τὰς κτίσεις συγγράψας, ὃς τὰ κατὰ Χαλκηδόνα καὶ Βυζάντιον στενά, ἃ νῦν Θρᾴκιος Βόσπορος καλεῖται, πρότερόν φησι Μύσιον Βόσπορον προσαγορεύεσθαι· τοῦτο δ’ ἄν τις καὶ τοῦ Θρᾷκας εἶναι τοὺς Μυσοὺς μαρτύριον θείη· ὅ τε Εὐφορίων<br>Μυσοῖο παρ’ ὕδασιν Ἀσκανίοιο<br>λέγων, καὶ ὁ Αἰτωλὸς Ἀλέξανδρος<br>οἳ καὶ ἐπ’ Ἀσκανίων δώματ’ ἔχουσι ῥοῶν<br>λίμνης Ἀσκανίης ἐπὶ χείλεσιν, ἔνθα Δολίων<br>υἱὸς Σιληνοῦ νάσσατο καὶ Μελίης<br>τὸ αὐτὸ ἐκμαρτυροῦσιν, οὐδαμοῦ τῆς Ἀσκανίας λίμνης εὑρισκομένης ἀλλ’ ἐνταῦθα μόνον.", "st": "12.4.8"}, {"sp": "N", "t": "ἄνδρες δ’ ἀξιόλογοι κατὰ παιδείαν γεγόνασιν ἐν τῇ Βιθυνίᾳ Ξενοκράτης τε ὁ φιλόσοφος καὶ Διονύσιος ὁ διαλεκτικὸς καὶ Ἵππαρχος καὶ Θεοδόσιος καὶ οἱ παῖδες αὐτοῦ μαθηματικοὶ Κλεοχάρης τε ῥήτωρ ὅ [τε] Μυρλεανὸς Ἀσκληπιάδης [γραμματικὸς] ἰατρός [τε] ὁ Προυσιεύς.", "st": "12.4.9"}, {"sp": "N", "t": "πρὸς νότον δ’ εἰσὶ τοῖς Βιθυνοῖς οἱ περὶ τὸν Ὄλυμπον Μυσοὶ (οὓς Ὀλυμπηνοὺς καλοῦσί τινες, οἱ δ’ Ἑλλησποντίους) καὶ ἡ ἐφ’ Ἑλλησπόντῳ Φρυγία, τοῖς δὲ Παφλαγόσι Γαλάται· ἀμφοτέρων τε τούτων ἔτι πρὸς νότον ἡ μεγάλη Φρυγία καὶ Λυκαονία μέχρι τοῦ Ταύρου τοῦ Κιλικίου καὶ τοῦ Πισιδικοῦ. ἐπεὶ δὲ τὰ τῇ Παφλαγονίᾳ συνεχῆ παράκειται τῷ Πόντῳ καὶ τῇ Καππαδοκίᾳ καὶ τοῖς ἤδη περιωδευμένοις ἔθνεσιν, οἰκεῖον ἂν εἴη τὰ τούτοις γειτονοῦντα μέρη προσαποδοῦναι πρῶτον, ἔπειτα τοὺς ἑξῆς τόπους παραδεῖξαι.", "st": "12.4.10"}, {"sp": "N", "t": "πρὸς νότον τοίνυν εἰσὶ τοῖς Παφλαγόσι Γαλάται· τούτων δ’ ἐστὶν ἔθνη τρία, δύο μὲν τῶν ἡγεμόνων ἐπώνυμα, Τροκμοὶ καὶ Τολιστοβώγιοι, τὸ τρίτον δ’ ἀπὸ τοῦ ἐν Κελτικῇ ἔθνους Τεκτόσαγες. κατέσχον δὲ τὴν χώραν ταύτην οἱ Γαλάται πλανηθέντες πολὺν χρόνον καὶ καταδραμόντες τὴν ὑπὸ τοῖς Ἀτταλικοῖς βασιλεῦσι χώραν καὶ τοῖς Βιθυνοῖς, ἕως παρ’ ἑκόντων ἔλαβον τὴν νῦν Γαλατίαν καὶ Γαλλογραικίαν λεγομένην. ἀρχηγὸς δὲ δοκεῖ μάλιστα τῆς περαιώσεως τῆς εἰς τὴν Ἀσίαν γενέσθαι Λεοννόριος. τριῶν δὲ ὄντων ἐθνῶν ὁμογλώττων καὶ κατ’ ἄλλο οὐδὲν ἐξηλλαγμένων, ἕκαστον διελόντες εἰς τέτταρας μερίδας τετραρχίαν ἑκάστην ἐκάλεσαν, τετράρχην ἔχουσαν ἴδιον καὶ δικαστὴν ἕνα καὶ στρατοφύλακα ἕνα ὑπὸ τῷ τετράρχῃ τεταγμένους, ὑποστρατοφύλακας δὲ δύο. ἡ δὲ τῶν δώδεκα τετραρχῶν βουλὴ ἄνδρες ἦσαν τριακόσιοι, συνήγοντο δὲ εἰς τὸν καλούμενον Δρυνέμετον. τὰ μὲν οὖν φονικὰ ἡ βουλὴ ἔκρινε, τὰ δὲ ἄλλα οἱ τετράρχαι καὶ οἱ δικασταί. πάλαι μὲν οὖν ἦν τοιαύτη τις ἡ διάταξις, καθ’ ἡμᾶς δὲ εἰς τρεῖς, εἶτ’ εἰς δύο ἡγεμόνας, εἶτα εἰς ἕνα ἧκεν ἡ δυναστεία, εἰς Δηιόταρον, εἶτα ἐκεῖνον διεδέξατο Ἀμύντας· νῦν δ’ ἔχουσι Ῥωμαῖοι καὶ ταύτην καὶ τὴν ὑπὸ τῷ Ἀμύντᾳ γενομένην πᾶσαν εἰς μίαν συναγαγόντες ἐπαρχίαν.", "st": "12.5.1"}, {"sp": "N", "t": "ἔχουσι δὲ οἱ μὲν Τροκμοὶ τὰ πρὸς τῷ Πόντῳ καὶ τῇ Καππαδοκίᾳ· ταῦτα δ’ ἐστὶ τὰ κράτιστα ὧν νέμονται Γαλάται· φρούρια δ’ αὐτοῖς τετείχισται τρία, Τάουιον, ἐμπόριον τῶν ταύτῃ, ὅπου ὁ τοῦ Διὸς κολοσσὸς χαλκοῦς καὶ τέμενος αὐτοῦ ἄσυλον, καὶ Μιθριδάτιον, ὃ ἔδωκε Πομπήιος Βογοδιατάρῳ τῆς Ποντικῆς βασιλείας ἀφορίσας, τρίτον δέ πω Δανάλα, ὅπου τὸν σύλλογον ἐποιήσαντο Πομπήιός τε καὶ Λεύκολλος, ὁ μὲν ἥκων ἐπὶ τὴν τοῦ πολέμου διαδοχὴν ὁ δὲ παραδιδοὺς τὴν ἐξουσίαν καὶ ἀπαίρων ἐπὶ τὸν θρίαμβον. Τροκμοὶ μὲν δὴ ταῦτ’ ἔχουσι τὰ μέρη, Τεκτόσαγες δὲ τὰ πρὸς τῇ μεγάλῃ Φρυγίᾳ τῇ κατὰ Πεσσινοῦντα καὶ Ὀρκαόρκους· τούτων δ’ ἦν φρούριον Ἄγκυρα ὁμώνυμος τῇ πρὸς Λυδίᾳ περὶ Βλαῦδον πολίχνῃ Φρυγιακῇ. Τολιστοβώγιοι δὲ ὅμοροι Βιθυνοῖς εἰσι καὶ τῇ Ἐπικτήτῳ καλουμένῃ Φρυγίᾳ· φρούρια δ’ αὐτῶν ἐστι τό τε Βλούκιον καὶ τὸ Πήιον, ὧν τὸ μὲν ἦν βασίλειον Δηιοτάρου, τὸ δὲ γαζοφυλάκιον.", "st": "12.5.2"}, {"sp": "N", "t": "Πεσσινοῦς δ’ ἐστὶν ἐμπόριον τῶν ταύτῃ μέγιστον, ἱερὸν ἔχον τῆς μητρὸς τῶν θεῶν σεβασμοῦ μεγάλου τυγχάνον· καλοῦσι δ’ αὐτὴν Ἄγδιστιν. οἱ δ’ ἱερεῖς τὸ παλαιὸν μὲν δυνάσται τινὲς ἦσαν, ἱερωσύνην καρπούμενοι μεγάλην, νυνὶ δὲ τούτων μὲν αἱ τιμαὶ πολὺ μεμείωνται, τὸ δὲ ἐμπόριον συμμένει· κατεσκεύασται δ’ ὑπὸ τῶν Ἀτταλικῶν βασιλέων ἱεροπρεπῶς τὸ τέμενος ναῷ τε καὶ στοαῖς λευκολίθοις· ἐπιφανὲς δ’ ἐποίησαν Ῥωμαῖοι τὸ ἱερόν, ἀφίδρυμα ἐνθένδε τῆς θεοῦ μεταπεμψάμενοι κατὰ τοὺς τῆς Σιβύλλης χρησμούς, καθάπερ καὶ τοῦ Ἀσκληπιοῦ τοῦ ἐν Ἐπιδαύρῳ. ἔστι δὲ καὶ ὄρος ὑπερκείμενον τῆς πόλεως τὸ Δίνδυμον, ἀφ’ οὗ ἡ Δινδυμηνή, καθάπερ ἀπὸ τῶν Κυβέλων ἡ Κυβέλη. πλησίον δὲ καὶ ὁ Σαγγάριος ποταμὸς ποιεῖται τὴν ῥύσιν· ἐπὶ δὲ τούτῳ τὰ παλαιὰ τῶν Φρυγῶν οἰκητήρια Μίδου καὶ ἔτι πρότερον Γορδίου καὶ ἄλλων τινῶν, οὐδ’ ἴχνη σώζοντα πόλεων, ἀλλὰ κῶμαι μικρῷ μείζους τῶν ἄλλων, οἷόν ἐστι τὸ Γόρδιον καὶ Γορβεοῦς, τὸ τοῦ Κάστορος βασίλειον τοῦ Σαωκονδάρου, ἐν ᾧ γαμβρὸν ὄντα τοῦτον ἀπέσφαξε Δηιόταρος καὶ τὴν θυγατέρα τὴν ἑαυτοῦ· τὸ δὲ φρούριον κατέσπασε καὶ διελυμήνατο τὸ πλεῖστον τῆς κατοικίας.", "st": "12.5.3"}, {"sp": "N", "t": "μετὰ δὲ τὴν Γαλατίαν πρὸς νότον ἥ τε λίμνη ἐστὶν ἡ Τάττα, παρακειμένη τῇ μεγάλῃ Καππαδοκίᾳ τῇ κατὰ τοὺς Μοριμηνούς, μέρος δ’ οὖσα τῆς μεγάλης Φρυγίας, καὶ ἡ συνεχὴς ταύτῃ μέχρι τοῦ Ταύρου, ἧς τὴν πλείστην Ἀμύντας εἶχεν. ἡ μὲν οὖν Τάττα ἁλοπήγιόν ἐστιν αὐτοφυές, οὕτω δὲ περιπήττεται ῥᾳδίως τὸ ὕδωρ παντὶ τῷ βαπτισθέντι εἰς αὐτὸ ὥστε στεφάνους ἁλῶν ἀνέλκουσιν, ἐπειδὰν καθῶσι κύκλον σχοίνινον, τά τε ὄρνεα ἁλίσκεται τὰ προσαψάμενα τῷ πτερώματι τοῦ ὕδατος παραχρῆμα πίπτοντα διὰ τὴν περίπηξιν τῶν ἁλῶν.", "st": "12.5.4"}, {"sp": "N", "t": "ἥ τε δὴ Τάττα [τοιαύτη] ἐστί, καὶ τὰ περὶ Ὀρκαόρκους καὶ Πιτνισσὸν καὶ τὰ τῶν Λυκαόνων ὀροπέδια ψυχρὰ καὶ ψιλὰ καὶ ὀναγρόβοτα, ὑδάτων δὲ σπάνις πολλή· ὅπου δὲ καὶ εὑρεῖν δυνατόν, βαθύτατα φρέατα τῶν πάντων, καθάπερ ἐν Σοάτροις, ὅπου καὶ πιπράσκεται τὸ ὕδωρ (ἔστι δὲ κωμόπολις Γαρσαούρων πλησίον)· ὅμως δὲ καίπερ ἄνυδρος οὖσα ἡ χώρα πρόβατα ἐκτρέφει θαυμαστῶς, τραχείας δὲ ἐρέας, καί τινες ἐξ αὐτῶν τούτων μεγίστους πλούτους ἐκτήσαντο· Ἀμύντας δ’ ὑπὲρ τριακοσίας ἔσχε ποίμνας ἐν τοῖς τόποις τούτοις. εἰσὶ δὲ καὶ λίμναι, Κάραλις μὲν ἡ μείζων ἡ δ’ ἐλάττων Τρωγῖτις. ἐνταῦθα δέ που καὶ τὸ Ἰκόνιον ἔστι, πολίχνιον εὖ συνῳκισμένον καὶ χώραν εὐτυχεστέραν ἔχον τῆς λεχθείσης ὀναγροβότου· τοῦτο δ’ εἶχε Πολέμων. πλησιάζει δ’ ἤδη τούτοις τοῖς τόποις ὁ Ταῦρος ὁ τὴν Καππαδοκίαν ὁρίζων καὶ τὴν Λυκαονίαν πρὸς τοὺς ὑπερκειμένους Κίλικας τοὺς Τραχειώτας. Λυκαόνων τε καὶ Καππαδόκων ὅριόν ἐστι τὸ μεταξὺ Κοροπασσοῦ κώμης Λυκαόνων, καὶ Γαρσαούρων πολιχνίου Καππαδόκων· ἔστι δὲ τὸ μεταξὺ διάστημα τῶν φρουρίων τούτων ἑκατὸν εἴκοσί που στάδιοι.", "st": "12.6.1"}, {"sp": "N", "t": "τῆς δὲ Λυκαονίας ἐστὶ καὶ ἡ Ἰσαυρικὴ πρὸς αὐτῷ τῷ Ταύρῳ ἡ τὰ Ἴσαυρα ἔχουσα κώμας δύο ὁμωνύμους, τὴν μὲν παλαιὰν καλουμένην, [τὴν δὲ νέαν,] εὐερκῆ· ὑπήκοοι δ’ ἦσαν ταύταις καὶ ἄλλαι κῶμαι συχναί, λῃστῶν δ’ ἅπασαι κατοικίαι. παρέσχον δὲ καὶ Ῥωμαίοις πράγματα καὶ τῷ Ἰσαυρικῷ προσαγορευθέντι Πουβλίῳ Σερβιλίῳ, ὃν ἡμεῖς εἴδομεν, ὃς καὶ ταῦτα ὑπέταξε Ῥωμαίοις καὶ τὰ πολλὰ τῶν πειρατῶν ἐρύματα ἐξεῖλε τὰ ἐπὶ τῇ θαλάττῃ.", "st": "12.6.2"}, {"sp": "N", "t": "τῆς δ’ Ἰσαυρικῆς ἔστιν ἐν πλευραῖς ἡ Δέρβη, μάλιστα τῇ Καππαδοκίᾳ ἐπιπεφυκὸς τοῦ Ἀντιπάτρου τυραννεῖον τοῦ Δερβήτου· τοῦ δ’ ἦν καὶ τὰ Λάρανδα· ἐφ’ ἡμῶν δὲ καὶ τὰ Ἴσαυρα καὶ τὴν Δέρβην Ἀμύντας εἶχεν, ἐπιθέμενος τῷ Δερβήτῃ καὶ ἀνελὼν αὐτόν, τὰ δ’ Ἴσαυρα παρὰ τῶν Ῥωμαίων λαβών· καὶ δὴ βασίλειον ἑαυτῷ κατεσκεύαζεν ἐνταῦθα, τὴν παλαιὰν Ἴσαυραν ἀνατρέψας. ἐν δὲ τῷ αὐτῷ χωρίῳ καινὸν τεῖχος οἰκοδομῶν οὐκ ἔφθη συντελέσας, ἀλλὰ διέφθειραν αὐτὸν οἱ Κίλικες ἐμβαλόντα εἰς τοὺς Ὁμοναδεῖς καὶ ἐξ ἐνέδρας ληφθέντα.", "st": "12.6.3"}, {"sp": "N", "t": "τὴν γὰρ Ἀντιόχειαν ἔχων τὴν πρὸς τῇ Πισιδίᾳ μέχρι Ἀπολλωνιάδος τῆς πρὸς Ἀπαμείᾳ τῇ Κιβωτῷ καὶ τῆς Παρωρείου τινὰ καὶ τὴν Λυκαονίαν ἐπειρᾶτο τοὺς ἐκ τοῦ Ταύρου κατατρέχοντας Κίλικας καὶ Πισίδας τὴν χώραν ταύτην Φρυγῶν οὖσαν ἐξαιρεῖν, καὶ πολλὰ χωρία ἐξεῖλεν ἀπόρθητα πρότερον ὄντα, ὧν καὶ Κρῆμνα· τὸ δὲ Σανδάλιον οὐδ’ ἐνεχείρησε βίᾳ προσάγεσθαι, μεταξὺ κείμενον τῆς τε Κρήμνης καὶ Σαγαλασσοῦ.", "st": "12.6.4"}, {"sp": "N", "t": "τὴν μὲν οὖν Κρῆμναν ἄποικοι Ῥωμαίων ἔχουσιν, ἡ Σαγαλασσὸς δ’ ἐστὶν ὑπὸ τῷ αὐτῷ ἡγεμόνι τῶν Ῥωμαίων ὑφ’ ᾧ καὶ ἡ Ἀμύντου βασιλεία πᾶσα· διέχει δ’ Ἀπαμείας ἡμέρας ὁδόν, κατάβασιν ἔχουσα σχεδόν τι καὶ τριάκοντα σταδίων ἀπὸ τοῦ ἐρύματος· καλοῦσι δ’ αὐτὴν καὶ Σελγησσόν· ταύτην δὲ τὴν πόλιν καὶ Ἀλέξανδρος εἷλεν. ὁ δ’ οὖν Ἀμύντας τὴν μὲν Κρῆμναν εἷλεν, εἰς δὲ τοὺς Ὁμοναδέας παρελθών, οἳ ἐνομίζοντο ἀληπτότατοι, καὶ καταστὰς ἤδη κύριος τῶν πλείστων χωρίων ἀνελὼν καὶ τὸν τύραννον αὐτῶν ἐξ ἀπάτης ἐλήφθη διὰ τῆς τοῦ τυράννου γυναικός. καὶ τοῦτον μὲν ἐκεῖνοι διέφθειραν, ἐκείνους δὲ Κυρίνιος ἐξεπόρθησε λιμῷ καὶ τετρακισχιλίους ἄνδρας ἐζώγρησε καὶ συνῴκισεν εἰς τὰς ἐγγὺς πόλεις, τὴν δὲ χώραν ἀπέλιπεν ἔρημον τῶν ἐν ἀκμῇ. ἔστι δὲ ἐν ὑψηλοῖς τοῦ Ταύρου μέρεσι, κρημνοῖς ἀποτόμοις σφόδρα καὶ τὸ πλέον ἀβάτοις, ἐν μέσῳ κοῖλον καὶ εὔγεων πεδίον εἰς αὐλῶνας πλείους διῃρημένον· τοῦτο δὲ γεωργοῦντες ᾤκουν ἐν ταῖς ὑπερκειμέναις ὀφρύσιν ἢ σπηλαίοις, τὰ πολλὰ δ’ ἔνοπλοι ἦσαν καὶ κατέτρεχον τὴν ἀλλοτρίαν ἔχοντες ὄρη τειχίζοντα τὴν χώραν αὐτῶν.", "st": "12.6.5"}, {"sp": "N", "t": "συναφεῖς δ’ εἰσὶ τούτοις οἵ τε ἄλλοι Πισίδαι καὶ οἱ Σελγεῖς, οἵπερ εἰσὶν ἀξιολογώτατοι τῶν Πισιδῶν. τὸ μὲν οὖν πλέον αὐτῶν μέρος τὰς ἀκρωρείας τοῦ Ταύρου κατέχει, τινὲς δὲ καὶ ὑπὲρ Σίδης καὶ Ἀσπένδου Παμφυλικῶν πόλεων κατέχουσι γεώλοφα χωρία ἐλαιόφυτα πάντα, τὰ δ’ ὑπὲρ τούτων ἤδη ὀρεινά, Κατεννεῖς ὅμοροι Σελγεῦσι καὶ Ὁμοναδεῦσι, Σαγαλασσεῖς δ’ ἐπὶ τὰ ἐντὸς τὰ πρὸς τῇ Μιλυάδι.", "st": "12.7.1"}, {"sp": "N", "t": "φησὶ δ’ Ἀρτεμίδωρος τῶν Πισιδῶν πόλεις εἶναι Σέλγην Σαγαλασσὸν Πετνηλισσὸν Ἄδαδα Τυμβριάδα Κρῆμναν Πιτυασσὸν Ἄμβλαδα Ἀνάβουρα Σίνδα Ἀαρασσὸν Ταρβασσὸν Τερμησσόν· τούτων δ’ οἱ μέν εἰσι τελέως ὀρεινοί, οἱ δὲ καὶ μέχρι τῶν ὑπωρειῶν καθήκοντες ἐφ’ ἑκάτερα, ἐπί τε τὴν Παμφυλίαν καὶ τὴν Μιλυάδα, Φρυξὶ καὶ Λυδοῖς καὶ Καρσὶν ὅμοροι, πᾶσιν εἰρηνικοῖς ἔθνεσι καίπερ προσβόρροις οὖσιν. οἱ δὲ Πάμφυλοι πολὺ τοῦ Κιλικίου φύλου μετέχοντες οὐ τελέως ἀφεῖνται τῶν λῃστρικῶν ἔργων, οὐδὲ τοὺς ὁμόρους ἐῶσι καθ’ ἡσυχίαν ζῆν καίπερ τὰ νότια μέρη τῆς ὑπωρείας τοῦ Ταύρου κατέχοντες. εἰσὶ δὲ τοῖς Φρυξὶν ὅμοροι καὶ τῇ Καρίᾳ Τάβαι καὶ Σίνδα καὶ Ἄμβλαδα, ὅθεν καὶ ὁ Ἀμβλαδεὺς οἶνος ἐκφέρεται πρὸς διαίτας ἰατρικὰς ἐπιτήδειος.", "st": "12.7.2"}, {"sp": "N", "t": "τῶν δ’ οὖν ὀρεινῶν οὓς εἶπον Πισιδῶν οἱ μὲν ἄλλοι κατὰ τυραννίδας μεμερισμένοι, καθάπερ οἱ Κίλικες, λῃστρικῶς ἤσκηνται· φασὶ δ’ αὐτοῖς τῶν Λελέγων συγκαταμιχθῆναι τινὰς τὸ παλαιόν, πλάνητας ἀνθρώπους, καὶ συμμεῖναι διὰ τὴν ὁμοιοτροπίαν αὐτόθι. Σέλγη δὲ ἐξ ἀρχῆς μὲν ὑπὸ Λακεδαιμονίων ἐκτίσθη πόλις, καὶ ἔτι πρότερον ὑπὸ Κάλχαντος· ὕστερον δὲ καθ’ αὑτὴν ἔμεινεν αὐξηθεῖσα ἐκ τοῦ πολιτεύεσθαι νομίμως, ὥστε καὶ δισμυρίανδρός ποτε εἶναι. θαυμαστὴ δ’ ἐστὶν ἡ φύσις τῶν τόπων· ἐν γὰρ ταῖς ἀκρωρείαις τοῦ Ταύρου χώρα μυριάδας τρέφειν δυναμένη σφόδρα εὔκαρπός ἐστιν, ὥστε καὶ ἐλαιόφυτα εἶναι πολλὰ χωρία καὶ εὐάμπελα, νομάς τε ἀφθόνους ἀνεῖσθαι παντοδαποῖς βοσκήμασι· κύκλῳ δ’ ὑπέρκεινται δρυμοὶ ποικίλης ὕλης. πλεῖστος δ’ ὁ στύραξ φύεται παρ’ αὐτοῖς, δένδρον οὐ μέγα ὀρθηλόν, ἀφ’ οὗ καὶ τὰ στυράκινα ἀκοντίσματα, ἐοικότα τοῖς κρανεΐνοις· ἐγγίνεται δ’ ἐν τοῖς στελέχεσι ξυλοφάγου τι σκώληκος εἶδος, ὃ μέχρι τῆς ἐπιφανείας διαφαγὸν τὸ ξύλον τὸ μὲν πρῶτον πιτύροις ἢ πρίσμασιν ἐοικός τι ψῆγμα προχεῖ, καὶ σωρὸς συνίσταται πρὸς τῇ ῥίζῃ, μετὰ δὲ ταῦτα ἀπολείβεταί τις ὑγρασία δεχομένη πῆξιν ῥᾳδίαν παραπλησίαν τῇ κόμμει· ταύτης δὲ τὸ μὲν ἐπὶ τὸ ψῆγμα πρὸς τῇ ῥίζῃ κατενεχθὲν ἀναμίγνυται τούτῳ τε καὶ τῇ γῇ, πλὴν ὅσον ἐπιπολῆς συστὰν διαμένει καθαρόν, τὸ δ’ ἐν τῇ ἐπιφανείᾳ τοῦ στελέχους καθ’ ἣν ῥεῖ πήττεται, καὶ τοῦτο καθαρόν· ποιοῦσι δὲ καὶ ἐκ τοῦ μὴ καθαροῦ μῖγμα ξυλομιγές τι καὶ γεωμιγές, εὐωδέστερον τοῦ καθαροῦ, τῇ δ’ ἄλλῃ δυνάμει λειπόμενον (λανθάνει δὲ τοὺς πολλούς), ᾧ πλείστῳ χρῶνται θυμιάματι οἱ δεισιδαίμονες. ἐπαινεῖται δὲ καὶ ἡ Σελγικὴ ἶρις καὶ τὸ ἀπ’ αὐτῆς ἄλειμμα. ἔχει δ’ ὀλίγας προσβάσεις [τὰ] περὶ τὴν πόλιν καὶ τὴν χώραν τὴν Σελγέων, ὀρεινὴν κρημνῶν καὶ χαραδρῶν οὖσαν πλήρη, ἃς ποιοῦσιν ἄλλοι τε ποταμοὶ καὶ ὁ Εὐρυμέδων καὶ ὁ Κέστρος ἀπὸ τῶν Σελγικῶν ὀρῶν εἰς τὴν Παμφυλίαν ἐκπίπτοντες θάλατταν· γέφυραι δ’ ἐπίκεινται ταῖς ὁδοῖς. διὰ δὲ τὴν ἐρυμνότητα οὔτε πρότερον οὔθ’ ὕστερον οὐδ’ ἅπαξ οἱ Σελγεῖς ἐπ’ ἄλλοις ἐγένοντο, ἀλλὰ τὴν μὲν ἄλλην χώραν ἀδεῶς ἐκαρποῦντο, ὑπὲρ δὲ τῆς κάτω τῆς τε ἐν τῇ Παμφυλίᾳ καὶ τῆς ἐντὸς τοῦ Ταύρου διεμάχοντο πρὸς τοὺς βασιλέας ἀεί· πρὸς δὲ τοὺς Ῥωμαίους ἐπὶ τακτοῖς τισι κατεῖχον τὴν χώραν· πρὸς Ἀλέξανδρον δὲ πρεσβευσάμενοι δέχεσθαι τὰ προστάγματα εἶπον κατὰ φιλίαν· νῦν δὲ ὑπήκοοι τελέως γεγόνασι, καί εἰσιν ἐν τῇ ὑπὸ Ἀμύντᾳ τεταγμένῃ πρότερον.", "st": "12.7.3"}, {"sp": "N", "t": "τοῖς δὲ Βιθυνοῖς ὁμοροῦσι πρὸς νότον, ὡς ἔφην, οἱ περὶ τὸν Ὄλυμπον τὸν Μύσιον προσαγορευόμενον Μυσοί τε καὶ Φρύγες· ἑκάτερον δὲ τὸ ἔθνος διττόν ἐστι. Φρυγία τε γὰρ ἡ μὲν καλεῖται μεγάλη, ἧς ὁ Μίδας ἐβασίλευσε καὶ ἧς μέρος οἱ Γαλάται κατέσχον, ἡ δὲ μικρὰ ἡ ἐφ’ Ἑλλησπόντῳ καὶ ἡ περὶ τὸν Ὄλυμπον ἡ καὶ Ἐπίκτητος λεγομένη. Μυσία τε ὁμοίως ἥ τε Ὀλυμπηνὴ συνεχὴς οὖσα τῇ Βιθυνίᾳ καὶ τῇ Ἐπικτήτῳ, ἣν ἔφη Ἀρτεμίδωρος ἀπὸ τῶν πέραν Ἴστρου Μυσῶν ἀπῳκίσθαι, καὶ ἡ περὶ τὸν Κάικον καὶ τὴν Περγαμηνὴν μέχρι Τευθρανίας καὶ τῶν ἐκβολῶν τοῦ ποταμοῦ.", "st": "12.8.1"}, {"sp": "N", "t": "οὕτω δ’ ἐνήλλακται ταῦτα ἐν ἀλλήλοις, ὡς πολλάκις λέγομεν, ὥστε καὶ τὴν περὶ Σίπυλον Φρυγίαν οἱ παλαιοὶ καλοῦσιν, ἄδηλον εἴτε τῆς μεγάλης εἴτε τῆς μικρᾶς μέρος οὖσαν, ᾗ καὶ τὸν Τάνταλον Φρύγα καὶ τὸν Πέλοπα καὶ τὴν Νιόβην· ὁποτέρως δ’ ἂν ἔχῃ, ἥ γε ἐπάλλαξις φανερά. ἡ γὰρ Περγαμηνὴ καὶ ἡ Ἐλαῗτις, καθ’ ἣν ὁ Κάικος ἐκπίπτει, καὶ ἡ μεταξὺ τούτων Τευθρανία, ἐν ᾗ Τεύθρας καὶ ἡ τοῦ Τηλέφου ἐκτροφή, ἀνὰ μέσον ἐστὶ τοῦ τε Ἑλλησπόντου καὶ τῆς περὶ Σίπυλον καὶ Μαγνησίαν τὴν ὑπ’ αὐτῷ χώρας· ὥσθ’ ὅπερ ἔφην ἔργον διορίσαι<br>χωρὶς τὰ Μυσῶν καὶ Φρυγῶν ὁρίσματα", "st": "12.8.2"}, {"sp": "N", "t": "καὶ οἱ Λυδοὶ καὶ οἱ Μαίονες, οὓς Ὅμηρος καλεῖ Μῄονας, ἐν συγχύσει πώς εἰσι καὶ πρὸς τούτους καὶ πρὸς ἀλλήλους, ὅτι οἱ μὲν τοὺς αὐτοὺς οἱ δ’ ἑτέρους φασί· πρὸς δὲ τούτους, ὅτι τοὺς Μυσοὺς οἱ μὲν Θρᾷκας οἱ δὲ Λυδοὺς εἰρήκασι, κατ’ αἰτίαν παλαιὰν ἱστοροῦντες, ἣν Ξάνθος ὁ Λυδὸς γράφει καὶ Μενεκράτης ὁ Ἐλαΐτης, ἐτυμολογοῦντες καὶ τὸ ὄνομα τὸ τῶν Μυσῶν ὅτι τὴν ὀξύην οὕτως ὀνομάζουσιν οἱ Λυδοί· πολλὴ δ’ ἡ ὀξύη κατὰ τὸν Ὄλυμπον, ὅπου ἐκτεθῆναί φασι τοὺς δεκατευθέντας, ἐκείνων δὲ ἀπογόνους εἶναι τοὺς ὕστερον Μυσούς, ἀπὸ τῆς ὀξύης οὕτω προσαγορευθέντας· μαρτυρεῖν δὲ καὶ τὴν διάλεκτον· μιξολύδιον γάρ πως εἶναι καὶ μιξοφρύγιον· τέως μὲν γὰρ οἰκεῖν αὐτοὺς περὶ τὸν Ὄλυμπον, τῶν δὲ Φρυγῶν ἐκ τῆς Θρᾴκης περαιωθέντων [ἀν]ελόντων τε τῆς Τροίας ἄρχοντα καὶ τῆς πλησίον γῆς, ἐκείνους μὲν ἐνταῦθα οἰκῆσαι τοὺς δὲ Μυσοὺς ὑπὲρ τὰς τοῦ Καΐκου πηγὰς πλησίον Λυδῶν.", "st": "12.8.3"}, {"sp": "N", "t": "συνεργεῖ δὲ πρὸς τὰς τοιαύτας μυθοποιίας ἥ τε σύγχυσις τῶν ἐνταῦθα ἐθνῶν καὶ ἡ εὐδαιμονία τῆς χώρας τῆς ἐντὸς Ἅλυος, μάλιστα δὲ τῆς παραλίας, δι’ ἣν ἐπιθέσεις ἐγένοντο αὐτῇ πολλαχόθεν καὶ διὰ παντὸς ἐκ τῆς περαίας, ἢ καὶ ἐπ’ ἀλλήλους ἰόντων τῶν ἐγγύς. μάλιστα μὲν οὖν κατὰ τὰ Τρωικὰ καὶ μετὰ ταῦτα τὰς ἐφόδους γενέσθαι καὶ τὰς μεταναστάσεις συνέβη, τῶν τε βαρβάρων ἅμα καὶ τῶν Ἑλλήνων ὁρμῇ τινι χρησαμένων πρὸς τὴν τῆς ἀλλοτρίας κατάκτησιν· ἀλλὰ καὶ πρὸ τῶν Τρωικῶν ἦν ταῦτα. τό τε γὰρ τῶν Πελασγῶν ἦν φῦλον καὶ τὸ τῶν Καυκώνων καὶ Λελέγων· εἴρηται δ’ ὅτι πολλαχοῦ τῆς Εὐρώπης τὸ παλαιὸν ἐτύγχανε πλανώμενα, ἅπερ ποιεῖ τοῖς Τρωσὶ συμμαχοῦντα ὁ ποιητής, οὐκ ἐκ τῆς περαίας. τά τε περὶ τῶν Φρυγῶν καὶ τῶν Μυσῶν λεγόμενα πρεσβύτερα τῶν Τρωικῶν ἐστιν· οἱ δὲ διττοὶ Λύκιοι τοῦ αὐτοῦ γένους ὑπόνοιαν παρέχουσιν, ἢ τῶν Τρωικῶν ἢ τῶν πρὸς Καρίᾳ τοὺς ἑτέρους ἀποικισάντων. τάχα δὲ καὶ ἐπὶ τῶν Κιλίκων τὸ αὐτὸ συνέβη· διττοὶ γὰρ καὶ οὗτοι· οὐ μὴν ἔχομέν γε τοιαύτην λαβεῖν μαρτυρίαν ὅτι καὶ πρὸ τῶν Τρωικῶν ἦσαν ἤδη οἱ νῦν Κίλικες· ὅ τε Τήλεφος ἐκ τῆς Ἀρκαδίας ἀφῖχθαι νομίζοιτ’ ἂν μετὰ τῆς μητρός, γάμῳ δὲ τῷ ταύτης ἐξοικειωσάμενος τὸν ὑποδεξάμενον αὐτὸν Τεύθραντα ἐνομίσθη τε ἐκείνου καὶ παρέλαβε τὴν Μυσῶν ἀρχήν.", "st": "12.8.4"}, {"sp": "N", "t": "καὶ οἱ Κᾶρες δὲ νησιῶται πρότερον ὄντες καὶ Λέλεγες, ὥς φασιν, ἠπειρῶται γεγόνασι, προσλαβόντων Κρητῶν, οἳ καὶ τὴν Μίλητον ἔκτισαν ἐκ τῆς Κρητικῆς Μιλήτου Σαρπηδόνα λαβόντες κτίστην· καὶ τοὺς Τερμίλας κατῴκισαν ἐν τῇ νῦν Λυκίᾳ· τούτους δ’ ἀγαγεῖν ἐκ Κρήτης ἀποίκους Σαρπηδόνα, Μίνω καὶ Ῥαδαμάνθυος ἀδελφὸν ὄντα, καὶ ὀνομάσαι Τερμίλας τοὺς πρότερον Μιλύας, ὥς φησιν Ἡρόδοτος, ἔτι δὲ πρότερον Σολύμους, ἐπελθόντα δὲ τὸν Πανδίονος Λύκον ἀφ’ ἑαυτοῦ προσαγορεῦσαι τοὺς αὐτοὺς Λυκίους. οὗτος μὲν οὖν ὁ λόγος ἀποφαίνει τοὺς αὐτοὺς Σολύμους τε καὶ Λυκίους, ὁ δὲ ποιητὴς χωρίζει· Βελλεροφόντης γοῦν ὡρμημένος ἐκ τῆς Λυκίας<br>Σολύμοισι μαχέσσατο κυδαλίμοισι.<br>Πείσανδρόν τε ὡσαύτως υἱὸν αὐτοῦ Ἄρης ὥς φησι<br>μαρνάμενον Σολύμοισι κατέκτανε.<br>καὶ τὸν Σαρπηδόνα δὲ ἐπιχώριόν τινα λέγει.", "st": "12.8.5"}, {"sp": "N", "t": "ἀλλὰ τό γε ἆθλον προκεῖσθαι κοινὸν τὴν ἀρετὴν τῆς χώρας ἧς λέγω τοῖς ἰσχύουσιν ἐκ πολλῶν βεβαιοῦται [καὶ πρὸ τῶν Τρωικῶν] καὶ μετὰ τὰ Τρωικά· ὅπου καὶ Ἀμαζόνες κατεθάρρησαν αὐτῆς, ἐφ’ ἃς ὅ τε Πρίαμος στρατεῦσαι λέγεται καὶ ὁ Βελλεροφόντης· πόλεις τε παλαιαὶ ὁμολογοῦνται ἐπώνυμοι αὐτῶν· ἐν δὲ τῷ Ἰλιακῷ πεδίῳ κολώνη τις ἔστιν<br>ἣν ἤτοι ἄνδρες Βατίειαν κικλήσκουσιν,<br>ἀθάνατοι δέ τε σῆμα πολυσκάρθμοιο Μυρίνης,<br>ἣν ἱστοροῦσι μίαν εἶναι τῶν Ἀμαζόνων ἐκ τοῦ ἐπιθέτου τεκμαιρόμενοι· εὐσκάρθμους γὰρ ἵππους λέγεσθαι διὰ τὸ τάχος· κἀκείνην οὖν πολύσκαρθμον διὰ τὸ ἀπὸ τῆς ἡνιοχείας τάχος· καὶ ἡ Μύρινα οὖν ἐπώνυμος ταύτης λέγεται. καὶ αἱ ἐγγὺς δὲ νῆσοι ταῦτ’ ἔπαθον διὰ τὴν ἀρετήν, ὧν Ῥόδος καὶ Κῶς ὅτι πρὸ τῶν Τρωικῶν ἤδη ὑφ’ Ἑλλήνων ᾠκοῦντο καὶ ὑφ’ Ὁμήρου σαφῶς ἐκμαρτυρεῖται.", "st": "12.8.6"}, {"sp": "N", "t": "μετὰ δὲ τὰ Τρωικὰ αἵ τε τῶν Ἑλλήνων ἀποικίαι καὶ αἱ Τρηρῶν καὶ αἱ Κιμμερίων ἔφοδοι καὶ Λυδῶν καὶ μετὰ ταῦτα Περσῶν καὶ Μακεδόνων τό [τε] τελευταῖον Γαλατῶν ἐτάραξαν πάντα καὶ συνέχεαν. γέγονε δὲ ἡ ἀσάφεια οὐ διὰ τὰς μεταβολὰς μόνον ἀλλὰ καὶ διὰ τὰς τῶν συγγραφέων ἀνομολογίας περὶ τῶν αὐτῶν οὐ τὰ αὐτὰ λεγόντων, τοὺς μὲν Τρῶας καλούντων Φρύγας καθάπερ οἱ τραγικοί, τοὺς δὲ Λυκίους Κᾶρας καὶ ἄλλους οὕτως. οἱ δὲ Τρῶες οὕτως ἐκ μικρῶν αὐξηθέντες ὥστε καὶ βασιλεῖς βασιλέων εἶναι, παρέσχον καὶ τῷ ποιητῇ λόγον τίνα χρὴ καλεῖν Τροίαν, καὶ τοῖς ἐξηγουμένοις ἐκεῖνον. λέγει μὲν γὰρ καὶ κοινῶς ἅπαντας Τρῶας τοὺς συμπολεμήσαντας αὐτοῖς, ὥσπερ καὶ Δαναοὺς καὶ Ἀχαιοὺς τοὺς ἐναντίους· ἀλλ’ οὐ δήπου Τροίαν καὶ τὴν Παφλαγονίαν ἐροῦμεν· νὴ Δία, οὐδὲ τὴν Καρίαν ἢ τὴν ὅμορον αὐτῇ Λυκίαν. λέγω δ’ ὅταν οὕτω φῇ<br>Τρῶες μὲν κλαγγῇ τ’ ἐνοπῇ τ’ ἴσαν,<br>ἐκ δὲ τῶν ἐναντίων<br>οἱ δ’ ἄρ’ ἴσαν σιγῇ μένεα πνείοντες Ἀχαιοί.<br>καὶ ἄλλως δὲ λέγει πολλαχῶς. ὅμως δὲ καίπερ τοιούτων ὄντων πειρατέον διαιτᾶν ἕκαστα εἰς δύναμιν· ὅ τι δ’ ἂν διαφύγῃ τῆς παλαιᾶς ἱστορίας, τοῦτο μὲν ἐατέον (οὐ γὰρ ἐνταῦθα τὸ τῆς γεωγραφίας ἔργον), τὰ δὲ νῦν ὄντα λεκτέον.", "st": "12.8.7"}, {"sp": "N", "t": "ἔστι τοίνυν ὄρη δύο ὑπερκείμενα τῆς Προποντίδος ὅ τε Ὄλυμπος ὁ Μύσιος καὶ ἡ Ἴδη. τῷ μὲν οὖν Ὀλύμπῳ τὰ τῶν Βιθυνῶν ὑποπέπτωκε, τῆς δὲ Ἴδης μεταξὺ καὶ τῆς θαλάττης ἡ Τροία κεῖται συνάπτουσα τῷ ὄρει· περὶ μὲν οὖν ταύτης ἐροῦμεν ὕστερον καὶ τῶν συνεχῶν αὐτῇ πρὸς νότον, νῦν δὲ περὶ τῶν Ὀλυμπηνῶν καὶ τῶν ἐφεξῆς μέχρι τοῦ Ταύρου παραλλήλων τοῖς προεφωδευμένοις λέγωμεν. ἔστι τοίνυν ὁ Ὄλυμπος κύκλῳ μὲν εὖ συνοικούμενος, ἐν δὲ τοῖς ὕψεσι δρυμοὺς ἐξαισίους ἔχων καὶ λῃστήρια δυναμένους ἐκτρέφειν τόπους εὐερκεῖς, ἐν οἷς καὶ τύραννοι συνίστανται πολλάκις δυνάμενοι συμμεῖναι πολὺν χρόνον, καθάπερ Κλέων ὁ καθ’ ἡμᾶς τῶν λῃστηρίων ἡγεμών.", "st": "12.8.8"}, {"sp": "N", "t": "οὗτος δ’ ἦν μὲν ἐκ Γορδίου κώμης, ἣν ὕστερον αὐξήσας ἐποίησε πόλιν καὶ προσηγόρευσεν Ἰουλιόπολιν· λῃστηρίῳ δ’ ἐχρῆτο καὶ ὁρμητηρίῳ κατ’ ἀρχὰς τῷ καρτερωτάτῳ τῶν χωρίων ὄνομα Καλλυδίῳ. ὑπῆρξε δ’ Ἀντωνίῳ μὲν χρήσιμος ἐπελθὼν ἐπὶ τοὺς ἀργυρολογοῦντας Λαβιηνῷ καθ’ ὃν χρόνον ἐκεῖνος τὴν Ἀσίαν κατέσχε, καὶ κωλύσας τὰς παρασκευάς· ἐν δὲ τοῖς Ἀκτιακοῖς ἀποστὰς Ἀντωνίου τοῖς Καίσαρος προσέθετο στρατηγοῖς, καὶ ἐτιμήθη πλέον ἢ κατ’ ἀξίαν προσλαβὼν τοῖς παρ’ Ἀντωνίου δοθεῖσι καὶ τὰ παρὰ τοῦ Καίσαρος, ὥστ’ ἀντὶ λῃστοῦ δυνάστου περιέκειτο σχῆμα, ἱερεὺς μὲν ὢν τοῦ Ἀβρεττηνοῦ Διός, Μυσίου θεοῦ, μέρος δ’ ἔχων ὑπήκοον τῆς Μωρηνῆς (Μυσία δέ ἐστι καὶ αὕτη, καθάπερ ἡ Ἀβρεττηνή), λαβὼν δὲ ὕστατα καὶ τὴν ἐν τῷ Πόντῳ τῶν Κομάνων ἱερωσύνην, εἰς ἣν κατελθὼν ἐντὸς μηνιαίου χρόνου κατέστρεψε τὸν βίον· νόσος δ’ ἐξήγαγεν αὐτὸν ὀξεῖα, εἴτ’ ἄλλως ἐπιπεσοῦσα ἐκ τῆς ἅδην πλησμονῆς εἴθ’, ὡς ἔφασαν οἱ περὶ τὸ ἱερόν, κατὰ μῆνιν τῆς θεοῦ· ἐν γὰρ τῷ περιβόλῳ τοῦ τεμένους ἡ οἴκησίς ἐστιν ἥ τε τοῦ ἱερέως καὶ τῆς ἱερείας, τὸ δὲ τέμενος χωρὶς τῆς ἄλλης ἁγιστείας διαφανέστατα τῆς τῶν ὑείων κρεῶν βρώσεως καθαρεύει, ὅπου γε καὶ ἡ ὅλη πόλις, οὐδ’ εἰσάγεται εἰς αὐτὴν ὗς· ὁ δ’ ἐν τοῖς πρώτοις τὸ λῃστρικὸν ἦθος ἐπεδείξατο εὐθὺς κατὰ τὴν πρώτην εἴσοδον τῇ παραβάσει τούτου τοῦ ἔθους ὥσπερ οὐχ ἱερεὺς εἰσεληλυθὼς ἀλλὰ διαφθορεὺς τῶν ἱερῶν.", "st": "12.8.9"}, {"sp": "N", "t": "ὁ μὲν δὴ Ὄλυμπος τοιόσδε, περιοικεῖται δὲ πρὸς ἄρκτον μὲν ὑπὸ τῶν Βιθυνῶν καὶ Μυγδόνων καὶ Δολιόνων, τὸ δὲ λοιπὸν ἔχουσι Μυσοὶ καὶ Ἐπίκτητοι. Δολίονας μὲν οὖν μάλιστα καλοῦσι τοὺς περὶ Κύζικον ἀπὸ Αἰσήπου ἕως Ῥυνδάκου καὶ τῆς Δασκυλίτιδος λίμνης, Μυγδόνας δὲ τοὺς ἐφεξῆς τούτοις μέχρι τῆς Μυρλειανῶν χώρας· ὑπέρκεινται δὲ τῆς Δασκυλίτιδος ἄλλαι δύο λίμναι μεγάλαι ἥ τε Ἀπολλωνιᾶτις ἥ τε Μιλητοπολῖτις· πρὸς μὲν οὖν τῇ Δασκυλίτιδι Δασκύλιον πόλις, πρὸς δὲ τῇ Μιλητοπολίτιδι Μιλητούπολις, πρὸς δὲ τῇ τρίτῃ Ἀπολλωνία ἡ ἐπὶ Ῥυνδάκῳ λεγομένη· τὰ πλεῖστα δὲ τούτων ἐστὶ Κυζικηνῶν νυνί.", "st": "12.8.10"}, {"sp": "N", "t": "ἔστι δὲ νῆσος ἐν τῇ Προποντίδι ἡ Κύζικος συναπτομένη γεφύραις δυσὶ πρὸς τὴν ἤπειρον, ἀρετῇ μὲν κρατίστη μεγέθει δὲ ὅσον πεντακοσίων σταδίων τὴν περίμετρον· ἔχει δὲ ὁμώνυμον πόλιν πρὸς αὐταῖς ταῖς γεφύραις καὶ λιμένας δύο κλειστοὺς καὶ νεωσοίκους πλείους τῶν διακοσίων· τῆς δὲ πόλεως τὸ μὲν ἔστιν ἐν ἐπιπέδῳ τὸ δὲ πρὸς ὄρει· καλεῖται δ’ Ἄρκτων ὄρος· ὑπέρκειται δ’ ἄλλο Δίνδυμον μονοφυές, ἱερὸν ἔχον τῆς Δινδυμήνης μητρὸς θεῶν, ἵδρυμα τῶν Ἀργοναυτῶν. ἔστι δ’ ἐνάμιλλος ταῖς πρώταις τῶν κατὰ τὴν Ἀσίαν ἡ πόλις μεγέθει τε καὶ κάλλει καὶ εὐνομίᾳ πρός τε εἰρήνην καὶ πόλεμον· ἔοικέ τε τῷ παραπλησίῳ τύπῳ κοσμεῖσθαι ὥσπερ ἡ τῶν Ῥοδίων καὶ Μασσαλιωτῶν καὶ Καρχηδονίων τῶν πάλαι. τὰ μὲν οὖν πολλὰ ἐῶ, τρεῖς δ’ ἀρχιτέκτονας τοὺς ἐπιμελουμένους οἰκοδομημάτων τε δημοσίων καὶ ὀργάνων, τρεῖς δὲ καὶ θησαυροὺς κέκτηται, τὸν μὲν ὅπλων τὸν δ’ ὀργάνων τὸν δὲ σίτου· ποιεῖ δὲ τὸν σῖτον ἄσηπτον ἡ Χαλκιδικὴ γῆ μιγνυμένη. ἐπεδείξαντο δὲ τὴν ἐκ τῆς παρασκευῆς ταύτης ὠφέλειαν ἐν τῷ Μιθριδατικῷ πολέμῳ. ἐπελθόντος γὰρ αὐτοῖς ἀδοκήτως τοῦ βασιλέως πεντεκαίδεκα μυριάσι καὶ ἵππῳ πολλῇ καὶ κατασχόντος τὸ ἀντικείμενον ὄρος ὃ καλοῦσιν Ἀδραστείας καὶ τὸ προάστειον, ἔπειτα καὶ διάραντος εἰς τὸν ὑπὲρ τῆς πόλεως αὐχένα καὶ προσμαχομένου πεζῇ τε καὶ κατὰ θάλατταν τετρακοσίαις ναυσίν, ἀντέσχον πρὸς ἅπαντα οἱ Κυζικηνοί, ὥστε καὶ ἐγγὺς ἦλθον τοῦ ζωγρίᾳ λαβεῖν τὸν βασιλέα ἐν τῇ διώρυγι ἀντιδιορύττοντες, ἀλλ’ ἔφθη φυλαξάμενος καὶ ἀναλαβὼν ἑαυτὸν ἔξω τοῦ ὀρύγματος· ὀψὲ δὲ ἴσχυσεν εἰσπέμψαι τινὰς νύκτωρ ἐπικούρους ὁ τῶν Ῥωμαίων στρατηγὸς Λεύκολλος· ὤνησε δὲ καὶ λιμὸς τῷ τοσούτῳ πλήθει τῆς στρατιᾶς ἐπιπεσών, ὃν οὐ προείδετο ὁ βασιλεύς, ὡς ἀπῆλθε πολλοὺς ἀποβαλών. Ῥωμαῖοι δ’ ἐτίμησαν τὴν πόλιν, καὶ ἔστιν ἐλευθέρα μέχρι νῦν καὶ χώραν ἔχει πολλὴν τὴν μὲν ἐκ παλαιοῦ τὴν δὲ τῶν Ῥωμαίων προσθέντων. καὶ γὰρ τῆς Τρῳάδος ἔχουσι τὰ πέραν τοῦ Αἰσήπου τὰ περὶ τὴν Ζέλειαν καὶ τὸ τῆς Ἀδραστείας πεδίον· καὶ τῆς Δασκυλίτιδος λίμνης τὰ μὲν ἔχουσιν ἐκεῖνοι τὰ δὲ Βυζάντιοι· πρὸς δὲ τῇ Δολιονίδι καὶ τῇ Μυγδονίδι νέμονται πολλὴν μέχρι τῆς Μιλητοπολίτιδος λίμνης καὶ τῆς Ἀπολλωνιάτιδος αὐτῆς, δι’ ὧν χωρίων καὶ ὁ Ῥύνδακος ῥεῖ ποταμὸς τὰς ἀρχὰς ἔχων ἐκ τῆς Ἀζανίτιδος, προσλαβὼν δὲ καὶ ἐκ τῆς Ἀβρεττηνῆς Μυσίας ἄλλους τε καὶ Μέκεστον ἀπ’ Ἀγκύρας τῆς Ἀβαείτιδος ἐκδίδωσιν εἰς τὴν Προποντίδα κατὰ Βέσβικον νῆσον. ἐν ταύτῃ δὲ τῇ νήσῳ τῶν Κυζικηνῶν ὄρος ἐστὶν εὔδενδρον Ἀρτάκη· καὶ νησίον ὁμώνυμον πρόκειται τούτου, καὶ πλησίον ἀκρωτήριον Μέλανος καλούμενον ἐν παράπλῳ τοῖς εἰς Πρίαπον κομιζομένοις ἐκ τῆς Κυζίκου.", "st": "12.8.11"}, {"sp": "N", "t": "τῆς δ’ ἐπικτήτου Φρυγίας Ἀζανοί τέ εἰσι καὶ Νακολία καὶ Κοτιάειον καὶ Μιδάειον καὶ Δορυλάειον πόλεις καὶ Κάδοι· τοὺς δὲ Κάδους ἔνιοι τῆς Μυσίας φασίν. ἡ δὲ Μυσία κατὰ τὴν μεσόγαιαν ἀπὸ τῆς Ὀλυμπηνῆς ἐπὶ τὴν Περγαμηνὴν καθήκει καὶ τὸ Καΐκου λεγόμενον πεδίον, ὥστε μεταξὺ κεῖσθαι τῆς τε Ἴδης καὶ τῆς Κατακεκαυμένης, ἣν οἱ μὲν Μυσίαν οἱ δὲ Μαιονίαν φασίν.", "st": "12.8.12"}, {"sp": "N", "t": "ὑπὲρ δὲ τῆς Ἐπικτήτου πρὸς νότον ἐστὶν ἡ μεγάλη Φρυγία, λείπουσα ἐν ἀριστερᾷ τὴν Πεσσινοῦντα καὶ τὰ περὶ Ὀρκαόρκους καὶ Λυκαονίαν, ἐν δεξιᾷ δὲ Μαίονας καὶ Λυδοὺς καὶ Κᾶρας· ἐν ᾗ ἔστιν ἥ τε Παρώρειος λεγομένη Φρυγία καὶ ἡ πρὸς Πισιδίᾳ καὶ τὰ περὶ Ἀμόριον καὶ Εὐμένειαν καὶ Σύνναδα, εἶτα Ἀπάμεια ἡ Κιβωτὸς λεγομένη καὶ Λαοδίκεια, αἵπερ εἰσὶ μέγισται τῶν κατὰ τὴν Φρυγίαν πόλεων· περίκειται δὲ ταύταις πολίσματα καὶ … Ἀφροδισιὰς Κολοσσαὶ Θεμισώνιον Σαναὸς Μητρόπολις Ἀπολλωνιάς, ἔτι δὲ ἀπωτέρω τούτων Πέλται Τάβαι Εὐκαρπία Λυσιάς.", "st": "12.8.13"}, {"sp": "N", "t": "ἡ μὲν οὖν παρώρεια ὀρεινήν τινα ἔχει ῥάχιν ἀπὸ τῆς ἀνατολῆς ἐκτεινομένην ἐπὶ δύσιν· ταύτῃ δ’ ἑκατέρωθεν ὑποπέπτωκέ τι πεδίον μέγα, καὶ πόλεις πλησίον αὐτῆς πρὸς ἄρκτον μὲν Φιλομήλιον, ἐκ θατέρου δὲ μέρους Ἀντιόχεια ἡ πρὸς Πισιδίᾳ καλουμένη, ἡ μὲν ἐν πεδίῳ κειμένη πᾶσα ἡ δ’ ἐπὶ λόφου ἔχουσα ἀποικίαν Ῥωμαίων· ταύτην δ’ ᾤκισαν Μάγνητες οἱ πρὸς Μαιάνδρῳ. Ῥωμαῖοι δ’ ἠλευθέρωσαν τῶν βασιλέων, ἡνίκα τὴν ἄλλην Ἀσίαν Εὐμένει παρέδοσαν τὴν ἐντὸς τοῦ Ταύρου· ἦν δὲ ἐνταῦθα καὶ ἱερωσύνη τις Μηνὸς Ἀρκαίου, πλῆθος ἔχουσα ἱεροδούλων καὶ χωρίων ἱερῶν· κατελύθη δὲ μετὰ τὴν Ἀμύντου τελευτὴν ὑπὸ τῶν πεμφθέντων ἐπὶ τὴν ἐκείνου κληρονομίαν. Σύνναδα δ’ ἐστὶν οὐ μεγάλη πόλις· πρόκειται δ’ αὐτῆς ἐλαιόφυτον πεδίον ὅσον ἑξήκοντα σταδίων· ἐπέκεινα δ’ ἐστὶ Δοκιμία κώμη, καὶ τὸ λατόμιον Συνναδικοῦ λίθου (οὕτω μὲν Ῥωμαῖοι καλοῦσιν, οἱ δ’ ἐπιχώριοι Δοκιμίτην καὶ Δοκιμαῖον), κατ’ ἀρχὰς μὲν μικροὺς βώλους ἐκδιδόντος τοῦ μετάλλου, διὰ δὲ τὴν νυνὶ πολυτέλειαν τῶν Ῥωμαίων κίονες ἐξαιροῦνται μονόλιθοι μεγάλοι, πλησιάζοντες τῷ ἀλαβαστρίτῃ λίθῳ κατὰ τὴν ποικιλίαν, ὥστε καίπερ πολλῆς οὔσης τῆς ἐπὶ θάλατταν ἀγωγῆς τῶν τηλικούτων φορτίων ὅμως καὶ κίονες καὶ πλάκες εἰς Ῥώμην κομίζονται θαυμασταὶ κατὰ τὸ μέγεθος καὶ κάλλος.", "st": "12.8.14"}, {"sp": "N", "t": "Ἀπάμεια δ’ ἐστὶν ἐμπόριον μέγα τῆς ἰδίως λεγομένης Ἀσίας, δευτερεῦον μετὰ τὴν Ἔφεσον· αὕτη γὰρ καὶ τῶν ἀπὸ τῆς Ἰταλίας καὶ τῆς Ἑλλάδος ὑποδοχεῖον κοινόν ἐστιν. ἵδρυται δὲ ἡ Ἀπάμεια ἐπὶ ταῖς ἐκβολαῖς τοῦ Μαρσύου ποταμοῦ, καὶ ῥεῖ διὰ μέσης τῆς πόλεως ὁ ποταμὸς τὰς ἀρχὰς ἀπὸ τῆς πόλεως ἔχων· κατενεχθεὶς δ’ ἐπὶ τὸ προάστειον σφοδρῷ καὶ καταφερεῖ τῷ ῥεύματι συμβάλλει πρὸς τὸν Μαίανδρον, προσειληφότα καὶ ἄλλον ποταμὸν Ὀργᾶν δι’ ὁμαλοῦ φερόμενον πρᾶον καὶ μαλακόν· ἐντεῦθεν δ’ ἤδη γενόμενος Μαίανδρος τέως μὲν διὰ τῆς Φρυγίας φέρεται, ἔπειτα διορίζει τὴν Καρίαν καὶ τὴν Λυδίαν κατὰ τὸ Μαιάνδρου καλούμενον πεδίον, σκολιὸς ὢν εἰς ὑπερβολὴν ὥστε ἐξ ἐκείνου τὰς σκολιότητας ἁπάσας μαιάνδρους καλεῖσθαι· τελευτῶν δὲ καὶ τὴν Καρίαν αὐτὴν διαρρεῖ τὴν ὑπὸ τῶν Ἰώνων νῦν κατεχομένην, καὶ μεταξὺ Μιλήτου καὶ Πριήνης ποιεῖται τὰς ἐκβολάς. ἄρχεται δὲ ἀπὸ Κελαινῶν, λόφου τινός, ἐν ᾧ πόλις ἦν ὁμώνυμος τῷ λόφῳ· ἐντεῦθεν δ’ ἀναστήσας τοὺς ἀνθρώπους ὁ Σωτὴρ Ἀντίοχος εἰς τὴν νῦν Ἀπάμειαν τῆς μητρὸς ἐπώνυμον τὴν πόλιν ἐπέδειξεν Ἀπάμας, ἣ θυγάτηρ μὲν ἦν Ἀρταβάζου δεδομένη δ’ ἐτύγχανε πρὸς γάμον Σελεύκῳ τῷ Νικάτορι. ἐνταῦθα δὲ μυθεύεται τὰ περὶ τὸν Ὄλυμπον καὶ τὸν Μαρσύαν καὶ τὴν ἔριν ἣν ἤρισεν ὁ Μαρσύας πρὸς Ἀπόλλωνα. ὑπέρκειται δὲ καὶ λίμνη φύουσα κάλαμον τὸν εἰς τὰς γλώττας τῶν αὐλῶν ἐπιτήδειον, ἐξ ἧς ἀπολείβεσθαί φασι τὰς πηγὰς ἀμφοτέρας τήν τε τοῦ Μαρσύου καὶ τὴν τοῦ Μαιάνδρου.", "st": "12.8.15"}, {"sp": "N", "t": "ἡ δὲ Λαοδίκεια μικρὰ πρότερον οὖσα αὔξησιν ἔλαβεν ἐφ’ ἡμῶν καὶ τῶν ἡμετέρων πατέρων, καίτοι κακωθεῖσα ἐκ πολιορκίας ἐπὶ Μιθριδάτου τοῦ Εὐπάτορος· ἀλλ’ ἡ τῆς χώρας ἀρετὴ καὶ τῶν πολιτῶν τινες εὐτυχήσαντες μεγάλην ἐποίησαν αὐτήν, Ἱέρων μὲν πρότερον, ὃς πλειόνων ἢ δισχιλίων ταλάντων κληρονομίαν κατέλιπε τῷ δήμῳ πολλοῖς τ’ ἀναθήμασιν ἐκόσμησε τὴν πόλιν, Ζήνων δὲ ὁ ῥήτωρ ὕστερον καὶ ὁ υἱὸς αὐτοῦ Πολέμων, ὃς καὶ βασιλείας ἠξιώθη διὰ τὰς ἀνδραγαθίας ὑπ’ Ἀντωνίου μὲν πρότερον ὑπὸ Καίσαρος δὲ τοῦ Σεβαστοῦ μετὰ ταῦτα. φέρει δ’ ὁ περὶ τὴν Λαοδίκειαν τόπος προβάτων ἀρετὰς οὐκ εἰς μαλακότητα μόνον τῶν ἐρίων, ᾗ καὶ τῶν Μιλησίων διαφέρει, ἀλλὰ καὶ εἰς τὴν κοραξὴν χρόαν, ὥστε καὶ προσοδεύονται λαμπρῶς ἀπ’ αὐτῶν, ὥσπερ καὶ οἱ Κολοσσηνοὶ ἀπὸ τοῦ ὁμωνύμου χρώματος πλησίον οἰκοῦντες. ἐνταῦθα δὲ καὶ ὁ Κάπρος καὶ ὁ Λύκος συμβάλλει τῷ Μαιάνδρῳ ποταμῷ, ποταμὸς εὐμεγέθης, ἀφ’ οὗ καὶ ἡ πρὸς τῷ Λύκῳ Λαοδίκεια λέγεται. ὑπέρκειται δὲ τῆς πόλεως ὄρος Κάδμος, ἐξ οὗ καὶ ὁ Λύκος ῥεῖ καὶ ἄλλος ὁμώνυμος τῷ ὄρει. τὸ πλέον δ’ οὗτος ὑπὸ γῆς ῥυεὶς εἶτ’ ἀνακύψας συνέπεσεν εἰς ταὐτὸ τοῖς ἄλλοις ποταμοῖς, ἐμφαίνων ἅμα καὶ τὸ πολύτρητον τῆς χώρας καὶ τὸ εὔσειστον· εἰ γάρ τις ἄλλη, καὶ ἡ Λαοδίκεια εὔσειστος, καὶ τῆς πλησιοχώρου δὲ Κάρουρα.", "st": "12.8.16"}, {"sp": "N", "t": "ὅριον δέ ἐστι τῆς Φρυγίας καὶ τῆς Καρίας τὰ Κάρουρα· κώμη δ’ ἐστὶν αὕτη πανδοχεῖα ἔχουσα καὶ ζεστῶν ὑδάτων ἐκβολάς, τὰς μὲν ἐν τῷ ποταμῷ Μαιάνδρῳ τὰς δ’ ὑπὲρ τοῦ χείλους. καὶ δή ποτέ φασι πορνοβοσκὸν αὐλισθέντα ἐν τοῖς πανδοχείοις σὺν πολλῷ πλήθει γυναικῶν νύκτωρ γενομένου σεισμοῦ συναφανισθῆναι πάσαις. σχεδὸν δέ τι καὶ πᾶσα εὔσειστός ἐστιν ἡ περὶ τὸν Μαίανδρον χώρα καὶ ὑπόνομος πυρί τε καὶ ὕδατι μέχρι τῆς μεσογαίας. διατέτακε γὰρ ἀπὸ τῶν πεδίων ἀρξαμένη πᾶσα ἡ τοιαύτη κατασκευὴ τῆς χώρας εἰς τὰ Χαρώνια, τό τε ἐν Ἱεραπόλει καὶ τὸ ἐν Ἀχαράκοις τῆς Νυσαΐδος καὶ τὸ περὶ Μαγνησίαν καὶ Μυοῦντα· εὔθρυπτός τε γάρ ἐστιν ἡ γῆ καὶ ψαθυρὰ πλήρης τε ἁλμυρίδων καὶ εὐεκπύρωτός ἐστι· τάχα δὲ καὶ ὁ Μαίανδρος διὰ τοῦτο σκολιὸς ὅτι πολλὰς μεταπτώσεις λαμβάνει τὸ ῥεῖθρον, καὶ πολλὴν χοῦν κατάγων ἄλλοτ’ ἄλλῳ μέρει τῶν αἰγιαλῶν προστίθησι· τὸ δὲ πρὸς τὸ πέλαγος βιασάμενος ἐξωθεῖ. καὶ δὴ καὶ τὴν Πριήνην ἐπὶ θαλάττῃ πρότερον οὖσαν μεσόγεων πεποίηκε τετταράκοντα σταδίων προσχώματι.", "st": "12.8.17"}, {"sp": "N", "t": "καὶ ἡ Κατακεκαυμένη δέ, ἥπερ ὑπὸ Λυδῶν καὶ Μυσῶν κατέχεται, διὰ τοιαῦτά τινα τῆς προσηγορίας τετύχηκε ταύτης· ἥ τε Φιλαδέλφεια, ἡ πρὸς αὐτῇ πόλις, οὐδὲ τοὺς τοίχους ἔχει πιστούς, ἀλλὰ καθ’ ἡμέραν τρόπον τινὰ σαλεύονται καὶ διίστανται διατελοῦσι δὲ προσέχοντες τοῖς πάθεσι τῆς γῆς καὶ ἀρχιτεκτονοῦντες πρὸς αὐτά. καὶ τῶν ἄλλων δὲ πόλεων Ἀπάμεια μὲν καὶ πρὸ τῆς Μιθριδάτου στρατείας ἐσείσθη πολλάκις, καὶ ἔδωκεν ἐπελθὼν ὁ βασιλεὺς ἑκατὸν τάλαντα εἰς ἐπανόρθωσιν, ὁρῶν ἀνατετραμμένην τὴν πόλιν. λέγεται δὲ καὶ ἐπ’ Ἀλεξάνδρου παραπλήσια συμβῆναι· διόπερ εἰκός ἐστι καὶ τὸν Ποσειδῶ τιμᾶσθαι παρ’ αὐτοῖς καίπερ μεσογαίοις οὖσι, καὶ ἀπὸ Κελαινοῦ τοῦ Ποσειδῶνος ἐκ Κελαινοῦς, μιᾶς τῶν Δαναΐδων, γενομένου κεκλῆσθαι τὴν πόλιν ἐπώνυμον, ἢ διὰ τῶν λίθων τὴν ἀπὸ τῶν ἐκπυρώσεων μελανίαν. καὶ τὰ περὶ Σίπυλον δὲ καὶ τὴν ἀνατροπὴν αὐτοῦ μῦθον οὐ δεῖ τίθεσθαι· καὶ γὰρ νῦν τὴν Μαγνησίαν τὴν ὑπ’ αὐτῷ κατέβαλον σεισμοί, ἡνίκα καὶ Σάρδεις καὶ τῶν ἄλλων τὰς ἐπιφανεστάτας κατὰ πολλὰ μέρη διελυμήναντο· ἐπηνώρθωσε δ’ ὁ ἡγεμὼν χρήματα ἐπιδούς, καθάπερ καὶ πρότερον ἐπὶ τῆς γενομένης συμφορᾶς Τραλλιανοῖς (ἡνίκα τὸ γυμνάσιον καὶ ἄλλα μέρη συνέπεσεν) ὁ πατὴρ αὐτοῦ καὶ τούτοις καὶ Λαοδικεῦσιν.", "st": "12.8.18"}, {"sp": "N", "t": "ἀκούειν δ’ ἔστι καὶ τῶν παλαιῶν συγγραφέων οἷά φησιν ὁ τὰ Λύδια συγγράψας Ξάνθος, διηγούμενος οἷαι μεταβολαὶ κατέσχον πολλάκις τὴν χώραν ταύτην, ὧν ἐμνήσθημέν που καὶ ἐν τοῖς πρόσθεν. καὶ δὴ καὶ τὰ περὶ τὸν Τυφῶνα πάθη ἐνταῦθα μυθεύουσι καὶ τοὺς Ἀρίμους, καὶ τὴν Κατακεκαυμένην ταύτην εἶναί φασιν· οὐκ ὀκνοῦσι δὲ καὶ τὰ μεταξὺ Μαιάνδρου καὶ Λυδῶν ἅπανθ’ ὑπονοεῖν τοιαῦτα καὶ διὰ τὸ πλῆθος τῶν λιμνῶν καὶ ποταμῶν καὶ τοὺς πολλαχοῦ κευθμῶνας τῆς γῆς. ἡ δὲ μεταξὺ Λαοδικείας καὶ Ἀπαμείας λίμνη καὶ βορβορώδη καὶ ὑπονόμου τὴν ἀποφορὰν ἔχει πελαγία οὖσα· φασὶ δὲ καὶ δίκας εἶναι τῷ Μαιάνδρῳ μεταφέροντι τὰς χώρας ὅταν περικρουσθῶσιν οἱ ἀγκῶνες, ἁλόντος δὲ τὰς ζημίας ἐκ τῶν πορθμικῶν διαλύεσθαι τελῶν.", "st": "12.8.19"}, {"sp": "N", "t": "μεταξὺ δὲ τῆς Λαοδικείας καὶ τῶν Καρούρων ἱερὸν ἔστι Μηνὸς Κάρου καλούμενον τιμώμενον ἀξιολόγως. συνέστη δὲ καθ’ ἡμᾶς διδασκαλεῖον Ἡροφιλείων ἰατρῶν μέγα ὑπὸ Ζεύξιδος, καὶ μετὰ ταῦτα Ἀλεξάνδρου τοῦ Φιλαλήθους, καθάπερ ἐπὶ τῶν πατέρων τῶν ἡμετέρων ἐν Σμύρνῃ τὸ τῶν Ἐρασιστρατείων ὑπὸ Ἱκεσίου· νῦν δὲ οὐχ ὁμοίως ἔτι συμμένει.", "st": "12.8.20"}, {"sp": "N", "t": "λέγεται δέ τινα φῦλα Φρύγια οὐδαμοῦ δεικνύμενα, ὥσπερ οἱ Βερέκυντες. καὶ Ἀλκμὰν λέγει<br>Φρύγιον ηὔλησε μέλος τὸ Κερβήσιον.<br>καὶ βόθυνός τις λέγεται Κερβήσιος ἔχων ὀλεθρίους ἀποφοράς· ἀλλ’ οὗτός γε δείκνυται, οἱ δ’ ἄνθρωποι οὐκέθ’ οὕτω λέγονται. Αἰσχύλος δὲ συγχεῖ ἐν τῇ Νιόβῃ· φησὶ γὰρ ἐκείνη μνησθήσεσθαι τῶν περὶ Τάνταλον<br>οἷς ἐν Ἰδαίῳ πάγῳ<br>Διὸς πατρῴου βωμός ἐστι<br>καὶ πάλιν<br>Σίπυλον Ἰδαίαν ἀνὰ χθόνα.<br>καὶ ὁ Τάνταλος λέγει<br>σπείρω δ’ ἄρουραν δώδεχ’ ἡμερῶν ὁδόν,<br>Βερέκυντα χῶρον, ἔνθ’ Ἀδραστείας ἕδος<br>Ἴδη τε μυκηθμοῖσι καὶ βρυχήμασι<br>βρέμουσι μήλων, πᾶν τ’ ἐρέχθειον πέδον.", "st": "12.8.21"}, {"sp": "HDR", "t": "Βιβλίον ΙΓʹ", "st": "13"}, {"sp": "N", "t": "μέχρι μὲν δεῦρο ἀφωρίσθω τὰ περὶ τῆς Φρυγίας ἐπανιόντες δὲ πάλιν ἐπὶ τὴν Προποντίδα καὶ τὴν ἐφεξῆς τῷ Αἰσήπῳ παραλίαν τὴν αὐτὴν τῆς περιοδείας τάξιν ἀποδώσομεν. ἔστι δὲ Τρῳὰς πρώτη τῆς παραλίας ταύτης, ἧς τὸ πολυθρύλητον καίπερ ἐν ἐρειπίοις καὶ ἐν ἐρημίᾳ λειπομένης ὅμως πολυλογίαν οὐ τὴν τυχοῦσαν παρέχει τῇ γραφῇ. πρὸς τοῦτο δὲ συγγνώμης δεῖ καὶ παρακλήσεως, ὅπως τὴν αἰτίαν τοῦ μήκους μὴ ἡμῖν μᾶλλον ἀνάπτωσιν οἱ ἐντυγχάνοντες ἢ τοῖς σφόδρα ποθοῦσι τὴν τῶν ἐνδόξων καὶ παλαιῶν γνῶσιν· προσλαμβάνει δὲ τῷ μήκει καὶ τὸ πλῆθος τῶν ἐποικησάντων τὴν χώραν Ἑλλήνων τε καὶ βαρβάρων, καὶ οἱ συγγραφεῖς οὐχὶ τὰ αὐτὰ γράφοντες περὶ τῶν αὐτῶν οὐδὲ σαφῶς πάντα· ὧν ἐν τοῖς πρώτοις ἐστὶν Ὅμηρος εἰκάζειν περὶ τῶν πλείστων παρέχων. δεῖ δὲ καὶ τὰ τούτου διαιτᾶν καὶ τὰ τῶν ἄλλων ὑπογράψαντας πρότερον ἐν κεφαλαίῳ τὴν τῶν τόπων φύσιν.", "st": "13.1.1"}, {"sp": "N", "t": "ἀπὸ δὴ τῆς Κυζικηνῆς καὶ τῶν περὶ Αἴσηπον τόπων καὶ Γράνικον μέχρι Ἀβύδου καὶ Σηστοῦ τὴν τῆς Προποντίδος παραλίαν εἶναι συμβαίνει, ἀπὸ δὲ Ἀβύδου μέχρι Λεκτοῦ τὰ περὶ Ἴλιον καὶ Τένεδον καὶ Ἀλεξάνδρειαν τὴν Τρῳάδα· πάντων δὴ τούτων ὑπέρκειται ἡ Ἴδη τὸ ὄρος μέχρι Λεκτοῦ καθήκουσα· ἀπὸ Λεκτοῦ δὲ μέχρι Καΐκου ποταμοῦ καὶ τῶν Κανῶν λεγομένων ἔστι τὰ περὶ Ἄσσον καὶ Ἀδραμύττιον καὶ Ἀταρνέα καὶ Πιτάνην καὶ τὸν Ἐλαϊτικὸν κόλπον· οἷς πᾶσιν ἀντιπαρήκει ἡ τῶν Λεσβίων νῆσος· εἶθ’ ἑξῆς τὰ περὶ Κύμην μέχρι Ἕρμου καὶ Φωκαίας, ἥπερ ἀρχὴ μὲν τῆς Ἰωνίας ἐστὶ πέρας δὲ τῆς Αἰολίδος. τοιούτων δὲ τῶν τόπων ὄντων ὁ μὲν ποιητὴς ἀπὸ τῶν περὶ Αἴσηπον τόπων καὶ τῶν περὶ τὴν νῦν Κυζικηνὴν χώραν ὑπαγορεύει μάλιστα τοὺς Τρῶας ἄρξαι μέχρι τοῦ Καΐκου ποταμοῦ διῃρημένους κατὰ δυναστείας εἰς ὀκτὼ μερίδας ἢ καὶ ἐννέα· τὸ δὲ τῶν ἄλλων ἐπικούρων πλῆθος ἐν τοῖς συμμάχοις διαριθμεῖται.", "st": "13.1.2"}, {"sp": "N", "t": "οἱ δ’ ὕστερον τοὺς ὅρους οὐ τοὺς αὐτοὺς λέγουσι καὶ τοῖς ὀνόμασι χρῶνται διηλλαγμένως, διαιρέσεις νέμοντες πλείους. μάλιστα δὲ αἱ τῶν Ἑλλήνων ἀποικίαι παρεσχήκασι λόγον· ἧττον μὲν ἡ Ἰωνική (πλείονι γὰρ διέστηκε τῆς Τρῳάδος), ἡ δὲ τῶν Αἰολέων παντάπασι· καθ’ ὅλην γὰρ ἐσκεδάσθη ἀπὸ τῆς Κυζικηνῆς μέχρι τοῦ Καΐκου καὶ ἐπέλαβεν ἔτι πλέον, τὴν μεταξὺ τοῦ Καΐκου καὶ τοῦ Ἕρμου ποταμοῦ. τέτταρσι γὰρ δὴ γενεαῖς πρεσβυτέραν φασὶ τὴν Αἰολικὴν ἀποικίαν τῆς Ἰωνικῆς, διατριβὰς δὲ λαβεῖν καὶ χρόνους μακροτέρους. Ὀρέστην μὲν γὰρ ἄρξαι τοῦ στόλου, τούτου δ’ ἐν Ἀρκαδίᾳ τελευτήσαντος τὸν βίον διαδέξασθαι τὸν υἱὸν αὐτοῦ Πενθίλον, καὶ προελθεῖν μέχρι Θρᾴκης ἑξήκοντα ἔτεσι τῶν Τρωικῶν ὕστερον, ὑπ’ αὐτὴν τὴν τῶν Ἡρακλειδῶν εἰς Πελοπόννησον κάθοδον· εἶτ’ Ἀρχέλαον υἱὸν ἐκείνου περαιῶσαι τὸν Αἰολικὸν στόλον εἰς τὴν νῦν Κυζικηνὴν τὴν περὶ τὸ Δασκύλιον· Γρᾶν δὲ τὸν υἱὸν τούτου τὸν νεώτατον προελθόντα μέχρι τοῦ Γρανίκου ποταμοῦ καὶ παρεσκευασμένον ἄμεινον περαιῶσαι τὸ πλέον τῆς στρατιᾶς εἰς Λέσβον καὶ κατασχεῖν αὐτήν· Κλεύην δὲ τὸν Δώρου καὶ Μαλαόν, καὶ αὐτοὺς ἀπογόνους ὄντας Ἀγαμέμνονος, συναγαγεῖν μὲν τὴν στρατιὰν κατὰ τὸν αὐτὸν χρόνον καθ’ ὃν καὶ Πενθίλος, ἀλλὰ τὸν μὲν τοῦ Πενθίλου στόλον φθῆναι περαιωθέντα ἐκ τῆς Θρᾴκης εἰς τὴν Ἀσίαν, τούτους δὲ περὶ τὴν Λοκρίδα καὶ τὸ Φρίκιον ὄρος διατρῖψαι πολὺν χρόνον, ὕστερον δὲ διαβάντας κτίσαι τὴν Κύμην τὴν Φρικωνίδα κληθεῖσαν ἀπὸ τοῦ Λοκρικοῦ ὄρους.", "st": "13.1.3"}, {"sp": "N", "t": "τῶν Αἰολέων τοίνυν καθ’ ὅλην σκεδασθέντων τὴν χώραν, ἣν ἔφαμεν ὑπὸ τοῦ ποιητοῦ λέγεσθαι Τρωικήν, οἱ ὕστερον οἱ μὲν πᾶσαν Αἰολίδα προσαγορεύουσιν οἱ δὲ μέρος, καὶ Τροίαν οἱ μὲν ὅλην οἱ δὲ μέρος αὐτῆς, οὐδὲν ὅλως ἀλλήλοις ὁμολογοῦντες. εὐθὺς γὰρ ἐπὶ τῶν κατὰ τὴν Προποντίδα τόπων ὁ μὲν Ὅμηρος ἀπὸ Αἰσήπου τὴν ἀρχὴν ποιεῖται τῆς Τρῳάδος, Εὔδοξος δὲ ἀπὸ Πριάπου καὶ Ἀρτάκης τοῦ ἐν τῇ Κυζικηνῶν νήσῳ χωρίου ἀνταίροντος τῷ Πριάπῳ, συστέλλων ἐπ’ ἔλαττον τοὺς ὅρους, Δαμάστης δ’ ἔτι μᾶλλον συστέλλει ἀπὸ Παρίου· καὶ γὰρ οὗτος μὲν ἕως Λεκτοῦ προάγει, ἄλλοι δ’ ἄλλως· Χάρων δ’ ὁ Λαμψακηνὸς τριακοσίους ἄλλους ἀφαιρεῖ σταδίους, ἀπὸ Πρακτίου ἀρχόμενος (τοσοῦτοι γάρ εἰσιν ἀπὸ Παρίου εἰς Πράκτιον), ἕως μέντοι Ἀτραμυττίου πρόεισι· Σκύλαξ δὲ ὁ Καρυανδεὺς ἀπὸ Ἀβύδου ἄρχεται· ὁμοίως δὲ τὴν Αἰολίδα Ἔφορος μὲν λέγει ἀπὸ Ἀβύδου μέχρι Κύμης, ἄλλοι δ’ ἄλλως.", "st": "13.1.4"}, {"sp": "N", "t": "τοπογραφεῖ δὲ κάλλιστα τὴν ὄντως λεγομένην Τροίαν ἡ τῆς Ἴδης θέσις, ὄρους ὑψηλοῦ βλέποντος πρὸς δύσιν καὶ τὴν ταύτῃ θάλατταν, μικρὰ δ’ ἐπιστρέφοντος καὶ πρὸς ἄρκτον καὶ τὴν ταύτῃ παραλίαν. ἔστι δὲ αὕτη μὲν τῆς Προποντίδος ἀπὸ τῶν περὶ Ἄβυδον στενῶν ἐπὶ τὸν Αἴσηπον καὶ τὴν Κυζικηνήν· ἡ δ’ ἑσπερία θάλαττα ὅ τε Ἑλλήσποντός ἐστιν ὁ ἔξω καὶ τὸ Αἰγαῖον πέλαγος. πολλοὺς δ’ ἔχουσα πρόποδας ἡ Ἴδη καὶ σκολοπενδρώδης οὖσα τὸ σχῆμα ἐσχάτοις ἀφορίζεται τούτοις, τῷ τε περὶ τὴν Ζέλειαν ἀκρωτηρίῳ καὶ τῷ καλουμένῳ Λεκτῷ, τῷ μὲν τελευτῶντι εἰς τὴν μεσόγαιαν μικρὸν ὑπὲρ τῆς Κυζικηνῆς (καὶ δὴ καὶ ἔστι νῦν ἡ Ζέλεια τῶν Κυζικηνῶν)· τὸ δὲ Λεκτὸν εἰς τὸ πέλαγος καθήκει τὸ Αἰγαῖον ἐν παράπλῳ κείμενον τοῖς ἐκ Τενέδου πλέουσιν εἰς Λέσβον.<br>Ἴδην δ’ ἵκανον πολυπίδακα μητέρα θηρῶν,<br>Λεκτὸν ὅθι πρῶτον λιπέτην ἅλα<br>ὕπνος καὶ Ἥρα, τοῖς οὖσιν οἰκείως τοῦ ποιητοῦ φράζοντος τὸ Λεκτόν· καὶ γὰρ ὅτι τῆς Ἴδης ἐστὶ τὸ Λεκτὸν καὶ διότι πρώτη ἀπόβασις ἐκ θαλάττης αὕτη τοῖς ἐπὶ τὴν Ἴδην ἀνιοῦσιν, εἴρηκεν ὀρθῶς. τοὺς δὴ πρόποδας τοὺς ἐσχάτους ἐφ’ ἑκάτερα φράζων οὕτως τὸ Λεκτὸν καὶ τὴν Ζέλειαν, οἰκείως τούτων ἀκρώρειαν ἀφορίζει Γάργαρον, ἄκρον λέγων· καὶ γὰρ καὶ νῦν Γάργαρον ἐν τοῖς ἄνω μέρεσι τῆς Ἴδης δείκνυται τόπος, ἀφ’ οὗ τὰ νῦν Γάργαρα πόλις Αἰολική. ἐντὸς μὲν οὖν τῆς Ζελείας καὶ τοῦ Λεκτοῦ πρῶτά ἐστιν ἀπὸ τῆς Προποντίδος ἀρξαμένοις [τὰ] μέχρι τῶν κατ’ Ἄβυδον στενῶν, εἶτ’ ἔξω τῆς Προποντίδος τὰ μέχρι Λεκτοῦ.", "st": "13.1.5"}, {"sp": "N", "t": "κάμψαντι δὲ τὸ Λεκτὸν ἀναχεῖται κόλπος μέγας, ὃν ἡ Ἴδη ποιεῖ πρὸς τὴν ἤπειρον ἀποχωροῦσα ἀπὸ τοῦ Λεκτοῦ, καὶ αἱ Κάναι, τὸ ἐκ θατέρου μέρους ἀντικείμενον ἀκρωτήριον τῷ Λεκτῷ· καλοῦσι δ’ οἱ μὲν Ἰδαῖον κόλπον, οἱ δ’ Ἀδραμυττηνόν. ἐν τούτῳ δὲ αἱ τῶν Αἰολέων πόλεις μέχρι τῶν ἐκβολῶν τοῦ Ἕρμου, καθάπερ εἰρήκαμεν. εἴρηται δὲ ἐν τοῖς ἔμπροσθεν, ὅτι τοῖς ἐκ Βυζαντίου πλέουσι πρὸς νότον ἐπ’ εὐθείας ἐστὶν ὁ πλοῦς, πρῶτον ἐπὶ Σηστὸν καὶ Ἄβυδον διὰ μέσης τῆς Προποντίδος, ἔπειτα τῆς παραλίας τῆς Ἀσίας μέχρι Καρίας. ταύτην δὴ φυλάττοντας χρὴ τὴν ὑπόθεσιν ἀκούειν τῶν ἑξῆς, κἂν λέγωμεν κόλπους τινὰς ἐν τῇ παραλίᾳ, τάς τε ἄκρας δεῖ νοεῖν τὰς ποιούσας αὐτοὺς ἐπὶ τῆς αὐτῆς γραμμῆς κειμένας ὥσπερ τινὸς μεσημβρινῆς.", "st": "13.1.6"}, {"sp": "N", "t": "ἐκ δὴ τῶν ὑπὸ τοῦ ποιητοῦ λεγομένων εἰκάζουσιν οἱ φροντίσαντες περὶ τούτων πλέον τι, πᾶσαν τὴν παραλίαν ταύτην ὑπὸ τοῖς Τρωσὶ γεγονέναι, διῃρημένην μὲν εἰς δυναστείας ἐννέα, ὑπὸ δὲ τῷ Πριάμῳ τεταγμένην κατὰ τὸν Ἰλιακὸν πόλεμον καὶ λεγομένην Τροίαν· δῆλον δὲ ἐκ τῶν κατὰ μέρος. οἱ γὰρ περὶ τὸν Ἀχιλλέα τειχήρεις ὁρῶντες τοὺς Ἰλιέας κατ’ ἀρχάς, ἔξω ποιεῖσθαι τὸν πόλεμον ἐπεχείρησαν καὶ περιιόντες ἀφαιρεῖσθαι τὰ κύκλῳ<br>δώδεκα δὴ σὺν νηυσὶ πόλεις ἀλάπαξ’ ἀνθρώπων,<br>πεζὸς δ’ ἕνδεκά φημι κατὰ Τροίην ἐρίβωλον.<br>Τροίαν γὰρ λέγει τὴν πεπορθημένην ἤπειρον· πεπόρθηται δὲ σὺν ἄλλοις τόποις καὶ τὰ ἀντικείμενα τῇ Λέσβῳ τὰ περὶ Θήβην καὶ Λυρνησσὸν καὶ Πήδασον τὴν τῶν Λελέγων καὶ ἔτι ἡ τοῦ Εὐρυπύλου τοῦ Τηλέφου παιδός<br>ἀλλ’ οἷον τὸν Τηλεφίδην κατενήρατο χαλκῷ<br>ὁ Νεοπτόλεμος ἥρω Εὐρύπυλον. ταῦτα δὴ πεπορθῆσθαι λέγει καὶ αὐτὴν τὴν Λέσβον<br>ὅτε Λέσβον ἐυκτιμένην ἕλεν αὐτός.<br>καὶ<br>πέρσε δὲ Λυρνησσὸν καὶ Πήδασον<br>καὶ<br>Λυρνησσὸν διαπορθήσας καὶ τείχεα Θήβης.<br>ἐκ μὲν Λυρνησσοῦ ἡ Βρισηὶς ἑάλω<br>τὴν ἐκ Λυρνησσοῦ ἐξείλετο.<br>ἧς ἐν τῇ ἁλώσει τὸν Μύνητα πεσεῖν φησιν, ὡς ἡ Βρισηὶς θρηνοῦσα τὸν Πάτροκλον δηλοῖ<br>οὐδὲ μὲν οὐδέ μ’ ἔασκες, ὅτ’ ἄνδρ’ ἐμὸν ὠκὺς Ἀχιλλεὺς<br>ἔκτεινεν, πέρσεν δὲ πόλιν θείοιο Μύνητος,<br>κλαίειν.<br>ἐμφαίνει γὰρ τὴν Λυρνησσὸν λέγων “πόλιν θείοιο Μύνητος,” ὡς ἂν δυναστευομένην ὑπ’ αὐτοῦ, καὶ ἐνταῦθα πεσεῖν αὐτὸν μαχόμενον. ἐκ δὲ τῆς Θήβης ἡ Χρυσηὶς ἐλήφθη<br>ᾠχόμεθ’ ἐς Θήβην ἱερὴν πόλιν Ἠετίωνος.<br>ἐκ δὲ τῶν ἀχθέντων ἐκεῖθεν φησὶν εἶναι τὴν Χρυσηίδα. ἐνθένδε δ’ ἦν καὶ ἡ Ἀνδρομάχη.<br>Ἀνδρομάχη θυγάτηρ μεγαλήτορος Ἠετίωνος,<br>Ἠετίων, ὃς ἔναιεν ὑπὸ Πλάκῳ ὑληέσσῃ,<br>Θήβῃ ὑποπλακίῃ, Κιλίκεσσ’ ἄνδρεσσιν ἀνάσσων.<br>δευτέρα οὖν αὕτη δυναστεία Τρωικὴ μετὰ τὴν ὑπὸ Μύνητι. οἰκείως δὲ τούτοις καὶ τὸ ὑπὸ τῆς Ἀνδρομάχης λεχθὲν οὕτως<br>Ἕκτορ, ἐγὼ δύστηνος· ἰῇ ἄρα γεινόμεθ’ αἴσῃ<br>ἀμφότεροι, σὺ μὲν ἐν Τροίῃ Πριάμου ἐνὶ οἴκῳ,<br>αὐτὰρ ἐγὼ Θήβῃσιν,<br>οὐκ οἴονται δεῖν ἐξ εὐθείας ἀκούειν, ἀλλὰ καθ’ ὑπερβατόν “ἀμφότεροι ἐν Τροίῃ, σὺ μὲν Πριάμου ἐνὶ οἴκῳ, αὐτὰρ ἐγὼ Θήβῃσι.” τρίτη δ’ ἐστὶν ἡ τῶν Λελέγων, καὶ αὕτη Τρωική,<br>Ἄλτεω, ὃς Λελέγεσσι φιλοπτολέμοισιν ἀνάσσει.<br>οὗ τῇ θυγατρὶ συνελθὼν Πρίαμος γεννᾷ τὸν Λυκάονα καὶ Πολύδωρον. καὶ μὴν οἵ γε ὑπὸ τῷ Ἕκτορι ἐν τῷ καταλόγῳ ταττόμενοι λέγονται Τρῶες<br>Τρωσὶ μὲν ἡγεμόνευε μέγας κορυθαίολος Ἕκτωρ.<br>εἶθ’ οἱ ὑπὸ τῷ Αἰνείᾳ<br>Δαρδανίων αὖτ’ ἦρχεν ἐὺς πάις Ἀγχίσαο<br>καὶ οὗτοι Τρῶες· φησὶ γοῦν<br>Αἰνεία, Τρώων βουληφόρε.<br>εἶθ’ οἱ ὑπὸ Πανδάρῳ Λύκιοι, οὓς καὶ αὐτοὺς καλεῖ Τρῶας·<br>οἳ δὲ Ζέλειαν ἔναιον ὑπαὶ πόδα νείατον Ἴδης,<br>ἀφνειοί, πίνοντες ὕδωρ μέλαν Αἰσήποιο,<br>Τρῶες· τῶν αὖτ’ ἦρχε Λυκάονος ἀγλαὸς υἱός,<br>Πάνδαρος.<br>ἕκτη δ’ αὕτη δυναστεία. καὶ μὴν οἵ γε μεταξὺ τοῦ Αἰσήπου καὶ Ἀβύδου Τρῶες· ὑπὸ μὲν γὰρ τῷ Ἀσίῳ ἐστὶ τὰ περὶ Ἄβυδον<br>οἳ δ’ ἄρα Περκώτην καὶ Πράκτιον ἀμφενέμοντο,<br>καὶ Σηστὸν καὶ Ἄβυδον ἔχον καὶ δῖαν Ἀρίσβην,<br>τῶν αὖθ’ Ὑρτακίδης ἦρχ’ Ἄσιος.<br>ἀλλ’ ἐν Ἀβύδῳ μὲν υἱὸς τοῦ Πριάμου διέτριβεν, ἵππους νέμων, πατρῴας δηλονότι<br>ἀλλ’ υἱὸν Πριάμοιο νόθον βάλε Δημοκόωντα,<br>ὅς οἱ Ἀβυδόθεν ἦλθε παρ’ ἵππων ὠκειάων.<br>ἐν δὲ Περκώτῃ υἱὸς Ἱκετάονος ἐβουνόμει οὐκ ἀλλοτρίας οὐδ’ οὗτος βοῦς<br>πρῶτον δ’ Ἱκεταονίδην ἐνένιπεν,<br>ἴφθιμον Μελάνιππον· ὁ δ’ ὄφρα μὲν εἰλίποδας βοῦς<br>βόσκ’ ἐν Περκώτῃ.<br>ὥστε καὶ αὕτη ἂν εἴη Τρῳὰς καὶ ἡ ἐφεξῆς ἕως Ἀδραστείας· ἦρχον γὰρ αὐτῆς<br>υἷε δύω Μέροπος Περκωσίου.<br>πάντες μὲν δὴ Τρῶες οἱ ἀπὸ Ἀβύδου μέχρι Ἀδραστείας, δίχα μέντοι διῃρημένοι, οἱ μὲν ὑπὸ τῷ Ἀσίῳ οἱ δ’ ὑπὸ τοῖς Μεροπίδαις· καθάπερ καὶ ἡ τῶν Κιλίκων διττή, ἡ μὲν Θηβαϊκὴ ἡ δὲ Λυρνησσίς· ἐν αὐτῇ δ’ ἂν λεχθείη ἡ ὑπὸ Εὐρυπύλῳ ἐφεξῆς οὖσα τῇ Λυρνησσίδι. ὅτι δὲ τούτων ἁπάντων ἦρχεν ὁ Πρίαμος οἱ τοῦ Ἀχιλλέως λόγοι πρὸς τὸν Πρίαμον σαφῶς ἐμφανίζουσι<br>καί σε, γέρον, τὸ πρὶν μὲν ἀκούομεν ὄλβιον εἶναι,<br>ὅσσον Λέσβος ἄνω Μάκαρος πόλις ἐντὸς ἐέργει,<br>καὶ Φρυγίη καθύπερθε καὶ Ἑλλήσποντος ἀπείρων.", "st": "13.1.7"}, {"sp": "N", "t": "τότε μὲν οὖν τοιαῦτα ὑπῆρχεν, ὕστερον δὲ ἠκολούθησαν μεταβολαὶ παντοῖαι. τὰ μὲν γὰρ περὶ Κύζικον Φρύγες ἐπῴκησαν ἕως Πρακτίου, τὰ δὲ περὶ Ἄβυδον Θρᾷκες· ἔτι δὲ πρότερον τούτων ἀμφοῖν Βέβρυκες καὶ Δρύοπες· τὰ δ’ ἑξῆς Τρῆρες, καὶ οὗτοι Θρᾷκες· τὸ δὲ Θήβης πεδίον Λυδοί, οἱ τότε Μῄονες, καὶ Μυσῶν οἱ περιγενόμενοι τῶν ὑπὸ Τηλέφῳ πρότερον καὶ Τεύθραντι. οὕτω δὴ τοῦ ποιητοῦ τὴν Αἰολίδα καὶ τὴν Τροίαν εἰς ἓν συντιθέντος, καὶ τῶν Αἰολέων τὴν ἀπὸ τοῦ Ἕρμου πᾶσαν μέχρι τῆς κατὰ Κύζικον παραλίας κατασχόντων καὶ πόλεις κτισάντων, οὐδ’ ἂν ἡμεῖς ἀτόπως περιοδεύσαιμεν, εἰς ταὐτὸ συντιθέντες τήν τε Αἰολίδα νῦν ἰδίως λεγομένην τὴν ἀπὸ τοῦ Ἕρμου μέχρι Λεκτοῦ καὶ τὴν ἐφεξῆς μέχρι τοῦ Αἰσήπου. ἐν γὰρ τοῖς καθ’ ἕκαστα διακρινοῦμεν πάλιν, παρατιθέντες ἅμα τοῖς νῦν οὖσι τὰ ὑπὸ τοῦ ποιητοῦ καὶ τῶν ἄλλων λεγόμενα.", "st": "13.1.8"}, {"sp": "N", "t": "ἔστιν οὖν μετὰ τὴν τῶν Κυζικηνῶν πόλιν καὶ τὸν Αἴσηπον ἀρχὴ τῆς Τρῳάδος καθ’ Ὅμηρον. λέγει δ’ ἐκεῖνος μὲν οὕτω περὶ αὐτῆς<br>οἳ δὲ Ζέλειαν ἔναιον ὑπαὶ πόδα νείατον Ἴδης<br>ἀφνειοί, πίνοντες ὕδωρ μέλαν Αἰσήποιο,<br>Τρῶες· τῶν αὖθ’ ἦρχε Λυκάονος ἀγλαὸς υἱός,<br>Πάνδαρος.<br>τούτους δὲ ἐκάλει καὶ Λυκίους· Ἀφνειοὺς δὲ ἀπὸ τῆς Ἀφνίτιδος νομίζουσι λίμνης· καὶ γὰρ οὕτω καλεῖται ἡ Δασκυλῖτις.", "st": "13.1.9"}, {"sp": "N", "t": "ἡ μὲν δὴ Ζέλεια ἐν τῇ παρωρείᾳ τῇ ὑστάτῃ τῆς Ἴδης ἔστιν, ἀπέχουσα Κυζίκου μὲν σταδίους ἐνενήκοντα καὶ ἑκατόν, τῆς δ’ ἐγγυτάτω θαλάττης καθ’ ἣν ἐκδίδωσιν Αἴσηπος ὅσον ὀγδοήκοντα. ἐπιμερίζει δὲ συνεχῶς τὰ κατὰ τὴν μετὰ τὸν Αἴσηπον<br>οἳ δ’ Ἀδρήστειάν τ’ εἶχον καὶ δῆμον Ἀπαισοῦ,<br>καὶ Πιτύαν εἶχον καὶ Τηρείης ὄρος αἰπύ,<br>τῶν ἦρχ’ Ἄδρηστός τε καὶ Ἄμφιος λινοθώρηξ,<br>υἷε δύω Μέροπος Περκωσίου.<br>ταῦτα δὲ τὰ χωρία τῇ Ζελείᾳ μὲν ὑποπέπτωκεν, ἔχουσι δὲ Κυζικηνοί τε καὶ Πριαπηνοὶ μέχρι καὶ τῆς παραλίας. περὶ μὲν οὖν τὴν Ζέλειαν ὁ Τάρσιος ἔστι ποταμός, εἴκοσιν ἔχων διαβάσεις τῇ αὐτῇ ὁδῷ, καθάπερ ὁ Ἑπτάπορος, ὅν φησιν ὁ ποιητής.", "st": "13.1.10"}, {"sp": "N", "t": "ὑπὲρ δὲ τῆς ἐκβολῆς τοῦ Αἰσήπου σχεδόν τι … σταδίοις κολωνὸς ἔστιν, ἐφ’ ᾧ τάφος δείκνυται Μέμνονος τοῦ Τιθωνοῦ· πλησίον δ’ ἔστι καὶ ἡ Μέμνονος κώμη. τοῦ δὲ Αἰσήπου καὶ τοῦ Πριάπου μεταξὺ ὁ Γράνικος ῥεῖ τὰ πολλὰ δι’ Ἀδραστείας πεδίου, ἐφ’ ᾧ Ἀλέξανδρος τοὺς Δαρείου σατράπας ἀνὰ κράτος ἐνίκησε συμβαλών, καὶ πᾶσαν τὴν ἐντὸς τοῦ Ταύρου καὶ τοῦ Εὐφράτου παρέλαβεν. ἐπὶ δὲ Γρανίκῳ πόλις ἦν Σιδήνη χώραν ἔχουσα πολλὴν ὁμώνυμον, κατέσπασται δὲ νῦν. ἐν δὲ τῇ μεθορίᾳ τῆς Κυζικηνῆς καὶ τῆς Πριαπηνῆς ἔστι τὰ Ἁρπάγια τόπος, ἐξ οὗ τὸν Γανυμήδην μυθεύουσιν ἡρπάχθαι· ἄλλοι δὲ περὶ Δαρδάνιον ἄκραν πλησίον Δαρδάνου.", "st": "13.1.11"}, {"sp": "N", "t": "Πρίαπος δ’ ἔστι πόλις ἐπὶ θαλάττῃ καὶ λιμήν· κτίσμα δ’ οἱ μὲν Μιλησίων φασίν, οἵπερ καὶ Ἄβυδον καὶ Προκόννησον συνῴκισαν κατὰ τὸν αὐτὸν καιρόν, οἱ δὲ Κυζικηνῶν· ἐπώνυμος δ’ ἐστὶ τοῦ Πριάπου τιμωμένου παρ’ αὐτοῖς, εἴτ’ ἐξ Ὀρνεῶν τῶν περὶ Κόρινθον μετενηνεγμένου τοῦ ἱεροῦ, εἴτε τῷ λέγεσθαι Διονύσου καὶ νύμφης τὸν θεὸν ὁρμησάντων ἐπὶ τὸ τιμᾶν αὐτὸν τῶν ἀνθρώπων, ἐπειδὴ σφόδρα εὐάμπελός ἐστιν ἡ χώρα καὶ αὕτη καὶ [ἡ] ἐφεξῆς ὅμορος, ἥ τε τῶν Παριανῶν καὶ ἡ τῶν Λαμψακηνῶν· ὁ γοῦν Ξέρξης τῷ Θεμιστοκλεῖ εἰς οἶνον ἔδωκε τὴν Λάμψακον. ἀπεδείχθη δὲ θεὸς οὗτος ὑπὸ τῶν νεωτέρων· οὐδὲ γὰρ Ἡσίοδος οἶδε Πρίαπον, ἀλλ’ ἔοικε τοῖς Ἀττικοῖς Ὀρθάνῃ καὶ Κονισάλῳ καὶ Τύχωνι καὶ τοῖς τοιούτοις.", "st": "13.1.12"}, {"sp": "N", "t": "ἐκαλεῖτο δ’ ἡ χώρα αὕτη Ἀδράστεια καὶ Ἀδραστείας πεδίον, κατὰ ἔθος τι οὕτω λεγόντων τὸ αὐτὸ χωρίον διττῶς, ὡς καὶ Θήβην καὶ Θήβης πεδίον, καὶ Μυγδονίαν καὶ Μυγδονίας πεδίον. φησὶ δὲ Καλλισθένης ἀπὸ Ἀδράστου βασιλέως, ὃς πρῶτος Νεμέσεως ἱερὸν ἱδρύσατο, καλεῖσθαι Ἀδράστειαν. ἡ μὲν οὖν πόλις μεταξὺ Πριάπου καὶ Παρίου, ἔχουσα ὑποκείμενον πεδίον ὁμώνυμον, ἐν ᾧ καὶ μαντεῖον ἦν Ἀπόλλωνος Ἀκταίου καὶ Ἀρτέμιδος κατὰ τὴν … εἰς δὲ Πάριον μετηνέχθη πᾶσα ἡ κατασκευὴ καὶ λιθεία κατασπασθέντος τοῦ ἱεροῦ, καὶ ᾠκοδομήθη ἐν τῷ Παρίῳ βωμὸς, Ἑρμοκρέοντος ἔργον, πολλῆς μνήμης ἄξιον κατά τε μέγεθος καὶ κάλλος· τὸ δὲ μαντεῖον ἐξελείφθη, καθάπερ καὶ τὸ ἐν Ζελείᾳ. ἐνταῦθα μὲν οὖν οὐδὲν ἱερὸν Ἀδραστείας δείκνυται, οὐδὲ δὴ Νεμέσεως, περὶ δὲ Κύζικον ἔστιν Ἀδραστείας ἱερόν. Ἀντίμαχος δ’ οὕτω φησίν<br>ἔστι δέ τις Νέμεσις μεγάλη θεὸς, ἣ τάδε πάντα<br>πρὸς μακάρων ἔλαχεν· βωμὸν δέ οἱ εἵσατο πρῶτος<br>Ἄδρηστος, ποταμοῖο παρὰ ῥόον Αἰσήποιο,<br>ἔνθα τετίμηταί τε καὶ Ἀδρήστεια καλεῖται.", "st": "13.1.13"}, {"sp": "N", "t": "ἔστι δὲ καὶ τὸ Πάριον πόλις ἐπὶ θαλάττῃ, λιμένα ἔχουσα μείζω τῆς Πριάπου καὶ ηὐξημένη γε ἐκ ταύτης· θεραπεύοντες γὰρ οἱ Παριανοὶ τοὺς Ἀτταλικοὺς ὑφ’ οἷς ἐτέτακτο ἡ Πριαπηνή, πολλὴν αὐτῆς ἀπετέμοντο ἐπιτρεπόντων ἐκείνων. ἐνταῦθα μυθεύουσι τοὺς Ὀφιογενεῖς συγγένειάν τινα ἔχειν πρὸς τοὺς ὄφεις· φασὶ δ’ αὐτῶν τοὺς ἄρρενας τοῖς ἐχεοδήκτοις ἄκος εἶναι συνεχῶς ἐφαπτομένους ὥσπερ τοὺς ἐπῳδούς, πρῶτον μὲν τὸ πελίωμα εἰς ἑαυτοὺς μεταφέροντας, εἶτα καὶ τὴν φλεγμονὴν παύοντας καὶ τὸν πόνον. μυθεύουσι δὲ τὸν ἀρχηγέτην τοῦ γένους ἥρωά τινα ἐξ ὄφεως μεταβαλεῖν· τάχα δὲ τῶν Ψύλλων τις ἦν τῶν Λιβυκῶν, εἰς δὲ τὸ γένος διέτεινεν ἡ δύναμις μέχρι ποσοῦ. κτίσμα δ’ ἐστὶ τὸ Πάριον Μιλησίων καὶ Ἐρυθραίων καὶ Παρίων.", "st": "13.1.14"}, {"sp": "N", "t": "Πιτύα δ’ ἐστὶν ἐν Πιτυοῦντι τῆς Παριανῆς ὑπερκείμενον ἔχουσα πιτυῶδες ὄρος· μεταξὺ δὲ κεῖται Παρίου καὶ Πριάπου κατὰ Λίνον χωρίον ἐπὶ θαλάττῃ, ὅπου οἱ Λινούσιοι κοχλίαι ἄριστοι τῶν πάντων ἁλίσκονται.", "st": "13.1.15"}, {"sp": "N", "t": "ἐν δὲ τῷ παράπλῳ τῷ ἀπὸ Παρίου εἰς Πρίαπον ἥ τε παλαιὰ Προκόννησός ἐστι καὶ ἡ νῦν Προκόννησος, πόλιν ἔχουσα καὶ μέταλλον μέγα λευκοῦ λίθου σφόδρα ἐπαινούμενον· τὰ γοῦν κάλλιστα τῶν ταύτῃ πόλεων ἔργα, ἐν δὲ τοῖς πρῶτα τὰ ἐν Κυζίκῳ ταύτης ἐστὶ τῆς λίθου. ἐντεῦθέν ἐστιν Ἀριστέας ὁ ποιητὴς τῶν Ἀριμασπείων καλουμένων ἐπῶν, ἀνὴρ γόης εἴ τις ἄλλος.", "st": "13.1.16"}, {"sp": "N", "t": "τὸ δὲ Τηρείης ὄρος οἱ μὲν τὰ ἐν Πειρωσσῷ ὄρη φασὶν ἃ ἔχουσιν οἱ Κυζικηνοὶ τῇ Ζελείᾳ προσεχῆ, ἐν οἷς βασιλικὴ θήρα κατεσκεύαστο τοῖς Λυδοῖς, καὶ Πέρσαις ὕστερον· οἱ δ’ ἀπὸ τετταράκοντα σταδίων Λαμψάκου δεικνύουσι λόφον, ἐφ’ ᾧ μητρὸς θεῶν ἱερόν ἐστιν ἅγιον Τηρείης ἐπικαλούμενον.", "st": "13.1.17"}, {"sp": "N", "t": "καὶ ἡ Λάμψακος δ’ ἐπὶ θαλάττῃ πόλις ἐστὶν εὐλίμενος καὶ ἀξιόλογος, συμμένουσα καλῶς, ὥσπερ καὶ ἡ Ἄβυδος· διέχει δ’ αὐτῆς ὅσον ἑβδομήκοντα καὶ ἑκατὸν σταδίους· ἐκαλεῖτο δὲ πρότερον Πιτυοῦσσα, καθάπερ καὶ τὴν Χίον φασίν· ἐν δὲ τῇ περαίᾳ τῆς Χερρονήσου πολίχνιόν ἐστι Καλλίπολις· κεῖται δ’ ἐπ’ ἀκτῆς ἐκκειμένη πολὺ πρὸς τὴν Ἀσίαν κατὰ τὴν Λαμψακηνῶν πόλιν, ὥστε τὸ δίαρμα μὴ πλέον εἶναι τετταράκοντα σταδίων.", "st": "13.1.18"}, {"sp": "N", "t": "ἐν δὲ τῷ μεταξὺ Λαμψάκου καὶ Παρίου Παισὸς ἦν πόλις καὶ ποταμός· κατέσπασται δ’ ἡ πόλις, οἱ δὲ Παισηνοὶ μετῴκησαν εἰς Λάμψακον, Μιλησίων ὄντες ἄποικοι καὶ αὐτοί, καθάπερ καὶ οἱ Λαμψακηνοί. ὁ δὲ ποιητὴς εἴρηκεν ἀμφοτέρως, καὶ προσθεὶς τὴν πρώτην συλλαβήν<br>καὶ δῆμον Ἀπαισοῦ,<br>καὶ ἀφελών<br>ὅς ῥ’ ἐνὶ Παισῷ<br>ναῖε πολυκτήμων<br>καὶ ὁ ποταμὸς νῦν οὕτω καλεῖται. Μιλησίων δ’ εἰσὶ καὶ αἱ Κολωναὶ αἱ ὑπὲρ Λαμψάκου ἐν τῇ μεσογαίᾳ τῆς Λαμψακηνῆς· ἄλλαι δ’ εἰσὶν ἐπὶ τῇ ἐκτὸς Ἑλλησποντίᾳ θαλάττῃ, Ἰλίου διέχουσαι σταδίους τετταράκοντα πρὸς τοῖς ἑκατόν· ἐξ ὧν τὸν Κύκνον φασίν. Ἀναξιμένης δὲ καὶ ἐν τῇ Ἐρυθραίᾳ φησὶ λέγεσθαι Κολωνὰς καὶ ἐν τῇ Φωκίδι καὶ ἐν Θετταλίᾳ· ἐν δὲ τῇ Παριανῇ ἔστιν Ἰλιοκολώνη. ἐν δὲ τῇ Λαμψακηνῇ τόπος εὐάμπελος Γεργίθιον· ἦν δὲ καὶ πόλις Γέργιθα ἐκ τῶν ἐν τῇ Κυμαίᾳ Γεργίθων· ἦν γὰρ κἀκεῖ πόλις πληθυντικῶς καὶ θηλυκῶς λεγομένη αἱ Γέργιθες, ὅθενπερ ὁ Γεργίθιος ἦν Κεφάλων· καὶ νῦν ἔτι δείκνυται τόπος ἐν τῇ Κυμαίᾳ Γεργίθιον πρὸς Λαρίσῃ. ἐκ Παρίου μὲν οὖν ὁ γλωσσογράφος κληθεὶς ἦν Νεοπτόλεμος μνήμης ἄξιος, ἐκ Λαμψάκου δὲ Χάρων τε ὁ συγγραφεὺς καὶ Ἀδείμαντος καὶ Ἀναξιμένης ὁ ῥήτωρ καὶ Μητρόδωρος ὁ τοῦ Ἐπικούρου ἑταῖρος· καὶ αὐτὸς δ’ Ἐπίκουρος τρόπον τινὰ Λαμψακηνὸς ὑπῆρξε, διατρίψας ἐν Λαμψάκῳ καὶ φίλοις χρησάμενος τοῖς ἀρίστοις τῶν ἐν τῇ πόλει ταύτῃ, τοῖς περὶ Ἰδομενέα καὶ Λεοντέα. ἐντεῦθεν δὲ μετήνεγκεν Ἀγρίππας τὸν πεπτωκότα λέοντα, Λυσίππου ἔργον· ἀνέθηκε δὲ ἐν τῷ ἄλσει τῷ μεταξὺ τῆς λίμνης καὶ τοῦ εὐρίπου.", "st": "13.1.19"}, {"sp": "N", "t": "μετὰ δὲ Λάμψακον ἔστιν Ἄβυδος καὶ τὰ μεταξὺ χωρία, περὶ ὧν οὕτως εἴρηκε συλλαβὼν ὁ ποιητὴς καὶ τὴν Λαμψακηνὴν καὶ τῆς Παριανῆς τινα (οὔπω γὰρ ἦσαν αὗται αἱ πόλεις κατὰ τὰ Τρωικά)<br>οἳ δ’ ἄρα Περκώτην καὶ Πράκτιον ἀμφενέμοντο,<br>καὶ Σηστὸν καὶ Ἄβυδον ἔχον καὶ δῖαν Ἀρίσβην·<br>τῶν αὖθ’ Ὑρτακίδης ἦρχ’ Ἄσιος<br>φησίν<br>ὃν Ἀρίσβηθεν φέρον ἵπποι<br>αἴθωνες μεγάλοι ποταμοῦ ἄπο Σελλήεντος.<br>οὕτω δ’ εἰπὼν ἔοικε τὸ βασίλειον ἀποφαίνειν τοῦ Ἀσίου τὴν Ἀρίσβην, ὅθεν ἥκειν αὐτόν φησιν<br>ὃν Ἀρίσβηθεν φέρον ἵπποι ποταμοῦ<br>ἄπο Σελλήεντος.<br>οὕτω δ’ ἀφανῆ τὰ χωρία ταῦτά ἐστιν ὥστε οὐδ’ ὁμολογοῦσι περὶ αὐτῶν οἱ ἱστοροῦντες, πλὴν ὅτι περὶ Ἄβυδον καὶ Λάμψακόν ἐστι καὶ Πάριον, καὶ ὅτι ἡ πάλαι Περκώτη μετωνομάσθη ὁ τόπος.", "st": "13.1.20"}, {"sp": "N", "t": "τῶν δὲ ποταμῶν τὸν μὲν Σελλήεντά φησιν ὁ ποιητὴς πρὸς τῇ Ἀρίσβῃ ῥεῖν, εἴπερ ὁ Ἄσιος Ἀρίσβηθέν τε ἧκε καὶ ποταμοῦ ἄπο Σελλήεντος· ὁ δὲ Πράκτιος ποταμὸς μὲν ἔστι, πόλις δ’ οὐχ εὑρίσκεται, ὥς τινες ἐνόμισαν· ῥεῖ δὲ καὶ οὗτος μεταξὺ Ἀβύδου καὶ Λαμψάκου· τὸ οὖν<br>καὶ Πράκτιον ἀμφενέμοντο<br>οὕτω δεκτέον ὡς περὶ ποταμοῦ, καθάπερ κἀκεῖνα<br>οἵ τ’ ἄρα πὰρ ποταμὸν Κηφισὸν δῖον ἔναιον,<br>καὶ<br>ἀμφί τε Παρθένιον ποταμὸν κλυτὰ ἔργ’ ἐνέμοντο.<br>ἦν δὲ καὶ ἐν Λέσβῳ πόλις Ἀρίσβα, ἧς τὴν χώραν ἔχουσι Μηθυμναῖοι· ἔστι δὲ καὶ ποταμὸς Ἄρισβος ἐν Θρᾴκῃ, ὥσπερ εἴρηται, καὶ τούτου πλησίον οἱ Κεβρήνιοι Θρᾷκες. πολλαὶ δ’ ὁμωνυμίαι Θρᾳξὶ καὶ Τρωσίν, οἷον Σκαιοὶ Θρᾷκές τινες καὶ Σκαιὸς ποταμὸς καὶ Σκαιὸν τεῖχος καὶ ἐν Τροίᾳ Σκαιαὶ πύλαι· Ξάνθιοι Θρᾷκες, Ξάνθος ποταμὸς ἐν Τροίᾳ· Ἄρισβος ὁ ἐμβάλλων εἰς τὸν Ἕβρον, Ἀρίσβη ἐν Τροίᾳ· Ῥῆσος ποταμὸς ἐν Τροίᾳ, Ῥῆσος δὲ καὶ ὁ βασιλεὺς τῶν Θρᾳκῶν. ἔστι δὲ καὶ τῷ Ἀσίῳ ὁμώνυμος ἕτερος παρὰ τῷ ποιητῇ Ἄσιος<br>ὃς μήτρως ἦν Ἕκτορος ἱπποδάμοιο,<br>αὐτοκασίγνητος Ἑκάβης, υἱὸς δὲ Δύμαντος,<br>ὃς Φρυγίην ναίεσκε ῥοῇς ἐπὶ Σαγγαρίοιο.", "st": "13.1.21"}, {"sp": "N", "t": "Ἄβυδος δὲ Μιλησίων ἐστὶ κτίσμα ἐπιτρέψαντος Γύγου τοῦ Λυδῶν βασιλέως· ἦν γὰρ ἐπ’ ἐκείνῳ τὰ χωρία καὶ ἡ Τρῳὰς ἅπασα, ὀνομάζεται δὲ καὶ ἀκρωτήριόν τι πρὸς Δαρδάνῳ Γύγας· ἐπίκειται δὲ τῷ στόματι τῆς Προποντίδος καὶ τοῦ Ἑλλησπόντου, διέχει δὲ τὸ ἴσον Λαμψάκου καὶ Ἰλίου, σταδίους περὶ ἑβδομήκοντα καὶ ἑκατόν. ἐνταῦθα δ’ ἔστι τὸ ἑπταστάδιον ὅπερ ἔζευξε Ξέρξης, τὸ διορίζον τὴν Εὐρώπην καὶ τὴν Ἀσίαν. καλεῖται δ’ ἡ ἄκρα τῆς Εὐρώπης Χερρόνησος διὰ τὸ σχῆμα, ἡ ποιοῦσα τὰ στενὰ τὰ κατὰ τὸ ζεῦγμα· ἀντίκειται δὲ τὸ ζεῦγμα τῇ Ἀβύδῳ. Σηστὸς δὲ ἀρίστη τῶν ἐν Χερρονήσῳ πόλεων· διὰ δὲ τὴν γειτοσύνην ὑπὸ τῷ αὐτῷ ἡγεμόνι καὶ αὕτη ἐτέτακτο, οὔπω ταῖς ἠπείροις διοριζόντων τῶν τότε τὰς ἡγεμονίας. ἡ μὲν οὖν Ἄβυδος καὶ ἡ Σηστὸς διέχουσιν ἀλλήλων τριάκοντά που σταδίους ἐκ λιμένος εἰς λιμένα, τὸ δὲ ζεῦγμά ἐστι μικρὸν ἀπὸ τῶν πόλεων παραλλάξαντι ἐξ Ἀβύδου μὲν ὡς ἐπὶ τὴν Προποντίδα, ἐκ δὲ Σηστοῦ εἰς τοὐναντίον· ὀνομάζεται δὲ πρὸς τῇ Σηστῷ τόπος Ἀποβάθρα, καθ’ ὃν ἐζεύγνυτο ἡ σχεδία. ἔστι δὲ ἡ Σηστὸς ἐνδοτέρω κατὰ τὴν Προποντίδα ὑπερδέξιος τοῦ ῥοῦ τοῦ ἐξ αὐτῆς· διὸ καὶ εὐπετέστερον ἐκ τῆς Σηστοῦ διαίρουσι παραλεξάμενοι μικρὸν ἐπὶ τὸν τῆς Ἡροῦς πύργον, κἀκεῖθεν ἀφιέντες τὰ πλοῖα συμπράττοντος τοῦ ῥοῦ πρὸς τὴν περαίωσιν· τοῖς δ’ ἐξ Ἀβύδου περαιουμένοις παραλεκτέον ἐστὶν εἰς τἀναντία ὀκτώ που σταδίους ἐπὶ πύργον τινὰ κατ’ ἀντικρὺ τῆς Σηστοῦ, ἔπειτα διαίρειν πλάγιον καὶ μὴ τελέως ἐναντίον ἔχουσι τὸν ῥοῦν. ᾤκουν δὲ τὴν Ἄβυδον μετὰ τὰ Τρωικὰ Θρᾷκες, εἶτα Μιλήσιοι. τῶν δὲ πόλεων ἐμπρησθεισῶν ὑπὸ Δαρείου τοῦ Ξέρξου πατρὸς τῶν κατὰ τὴν Προποντίδα, ἐκοινώνησε καὶ ἡ Ἄβυδος τῆς αὐτῆς συμφορᾶς· ἐνέπρησε δὲ πυθόμενος μετὰ τὴν ἀπὸ τῶν Σκυθῶν ἐπάνοδον τοὺς νομάδας παρασκευάζεσθαι διαβαίνειν ἐπ’ αὐτὸν κατὰ τιμωρίαν ὧν ἔπαθον, δεδιὼς μὴ αἱ πόλεις πορθμεῖα παράσχοιεν τῇ στρατιᾷ. συνέβη δὲ πρὸς ταῖς ἄλλαις μεταβολαῖς καὶ τῷ χρόνῳ καὶ τοῦτο αἴτιον τῆς συγχύσεως τῶν τόπων. περὶ δὲ Σηστοῦ καὶ τῆς ὅλης Χερρονήσου προείπομεν ἐν τοῖς περὶ τῆς Θρᾴκης τόποις. φησὶ δὲ τὴν Σηστὸν Θεόπομπος βραχεῖαν μὲν εὐερκῆ δέ, καὶ σκέλει διπλέθρῳ συνάπτειν πρὸς τὸν λιμένα, καὶ διὰ ταῦτ’ οὖν καὶ διὰ τὸν ῥοῦν κυρίαν εἶναι τῶν παρόδων.", "st": "13.1.22"}, {"sp": "N", "t": "ὑπέρκειται δὲ τῆς τῶν Ἀβυδηνῶν χώρας ἐν τῇ Τρῳάδι τὰ Ἄστυρα, ἃ νῦν μὲν Ἀβυδηνῶν ἔστι, κατεσκαμμένη πόλις, πρότερον δὲ ἦν καθ’ αὑτά, χρυσεῖα ἔχοντα ἃ νῦν σπάνιά ἐστιν, ἐξαναλωμένα, καθάπερ τὰ ἐν τῷ Τμώλῳ τὰ περὶ τὸν Πακτωλόν. ἀπὸ Ἀβύδου δ’ ἐπὶ Αἴσηπον περὶ ἑπτακοσίους φασὶ σταδίους, εὐθυπλοίᾳ δὲ ἐλάττους.", "st": "13.1.23"}, {"sp": "N", "t": "ἔξω δὲ Ἀβύδου τὰ περὶ τὸ Ἴλιον ἔστι, τά τε παράλια ἕως Λεκτοῦ καὶ τὰ ἐν τῷ Τρωικῷ πεδίῳ καὶ τὰ παρώρεια τῆς Ἴδης τὰ ὑπὸ τῷ Αἰνείᾳ. διττῶς δὲ ταῦτ’ ὀνομάζει ὁ ποιητής, τοτὲ μὲν οὕτω λέγων<br>Δαρδανίων αὖτ’ ἦρχεν ἐὺς πάις Ἀγχίσαο,<br>Δαρδανίους καλῶν, τοτὲ δὲ Δαρδάνους<br>Τρῶες καὶ Λύκιοι καὶ Δάρδανοι ἀγχιμαχηταί.<br>εἰκὸς δ’ ἐνταῦθα ἱδρῦσθαι τὸ παλαιὸν τὴν λεγομένην ὑπὸ τοῦ ποιητοῦ Δαρδανίαν<br>Δάρδανον αὖ πρῶτον τέκετο νεφεληγερέτα Ζεύς,<br>κτίσσε δὲ Δαρδανίην.<br>νῦν μὲν γὰρ οὐδ’ ἴχνος πόλεως σώζεται αὐτόθι.", "st": "13.1.24"}, {"sp": "N", "t": "εἰκάζει δὲ Πλάτων μετὰ τοὺς κατακλυσμοὺς τρία πολιτείας εἴδη συνίστασθαι· πρῶτον μὲν τὸ ἐπὶ τὰς ἀκρωρείας ἁπλοῦν τι καὶ ἄγριον, δεδιότων τὰ ὕδατα ἐπιπολάζοντα ἀκμὴν ἐν τοῖς πεδίοις· δεύτερον δὲ τὸ ἐν ταῖς ὑπωρείαις, θαρρούντων ἤδη κατὰ μικρόν, ἅτε δὴ καὶ τῶν πεδίων ἀρχομένων ἀναψύχεσθαι· τρίτον δὲ τὸ ἐν τοῖς πεδίοις. λέγοι δ’ ἄν τις καὶ τέταρτον καὶ πέμπτον ἴσως καὶ πλείω, ὕστατον δὲ τὸ ἐν τῇ παραλίᾳ καὶ ἐν ταῖς νήσοις, λελυμένου παντὸς τοῦ τοιούτου φόβου. τὸ γὰρ μᾶλλον καὶ ἧττον θαρρεῖν πλησιάζειν τῇ θαλάττῃ πλείους ἂν ὑπογράφοι διαφορὰς πολιτειῶν καὶ ἠθῶν, καθάπερ τῶν ἀγαθῶν τε καὶ τῶν ἀγρίων ἔτι πως ἐπὶ τὸ ἥμερον τῶν δευτέρων ὑποβεβηκότων. ἔστι δέ τις διαφορὰ καὶ παρὰ τούτοις τῶν ἀγροίκων καὶ μεσαγροίκων καὶ πολιτικῶν· ἀφ’ ὧν ἤδη καὶ ἐπὶ τὸ ἀστεῖον καὶ ἄριστον ἦθος ἐτελεύτησεν ἡ τῶν ὀνομάτων κατ’ ὀλίγον μετάληψις, κατὰ τὴν τῶν ἠθῶν ἐπὶ τὸ κρεῖττον μετάστασιν, παρὰ τὰς τῶν τόπων καὶ τῶν βίων μεταβολάς. ταύτας δὴ τὰς διαφορὰς ὑπογράφειν φησὶ τὸν ποιητὴν ὁ Πλάτων, τῆς μὲν πρώτης πολιτείας παράδειγμα τιθέντα τὸν τῶν Κυκλώπων βίον, αὐτοφυεῖς νεμομένων καρποὺς καὶ τὰς ἀκρωρείας κατεχόντων ἐν σπηλαίοις τισίν·<br>ἀλλὰ τά γ’ ἄσπαρτα καὶ ἀνήροτα πάντα φύονται,<br>φησίν, αὐτοῖς·<br>τοῖσιν δ’ οὐκ ἀγοραὶ βουληφόροι, οὔτε θέμιστες·<br>ἀλλ’ οἵ γ’ ὑψηλῶν ὀρέων ναίουσι κάρηνα<br>ἐν σπέσσι γλαφυροῖσι, θεμιστεύει δὲ ἕκαστος<br>παίδων ἠδ’ ἀλόχων.<br>τοῦ δὲ δευτέρου τὸν ἐπὶ τοῦ Δαρδάνου<br>κτίσσε δὲ Δαρδανίην, ἐπεὶ οὔπω Ἴλιος ἱρὴ<br>ἐν πεδίῳ πεπόλιστο, πόλις μερόπων ἀνθρώπων,<br>ἀλλ’ ἔθ’ ὑπωρείας ᾤκεον πολυπιδάκου Ἴδης<br>τοῦ δὲ τρίτου ἐπὶ τοῦ Ἴλου τὸν ἐν τοῖς πεδίοις. τοῦτον γὰρ παραδιδόασι τοῦ Ἰλίου κτίστην, ἀφ’ οὗ καὶ τὴν ἐπωνυμίαν λαβεῖν τὴν πόλιν· εἰκὸς δὲ καὶ διὰ τοῦτο ἐν μέσῳ τῷ πεδίῳ τεθάφθαι αὐτόν, ὅτι πρῶτος ἐθάρρησεν ἐν τοῖς πεδίοις θέσθαι τὴν κατοικίαν<br>οἱ δὲ παρ’ Ἴλου σῆμα παλαιοῦ Δαρδανίδαο<br>μέσσον κὰπ πεδίον παρ’ ἐρινεὸν ἐσσεύοντο.<br>οὐδ’ οὗτος δὲ τελέως ἐθάρρησεν· οὐ γὰρ ἐνταῦθα ἵδρυσε τὴν πόλιν ὅπου νῦν ἔστιν, ἀλλὰ σχεδόν τι τριάκοντα σταδίοις ἀνωτέρω πρὸς ἕω καὶ πρὸς τὴν Ἴδην καὶ τὴν Δαρδανίαν κατὰ τὴν νῦν καλουμένην Ἰλιέων κώμην. οἱ δὲ νῦν Ἰλιεῖς φιλοδοξοῦντες καὶ θέλοντες εἶναι ταύτην τὴν παλαιὰν παρεσχήκασι λόγον τοῖς ἐκ τῆς Ὁμήρου ποιήσεως τεκμαιρομένοις· οὐ γὰρ ἔοικεν αὕτη εἶναι ἡ καθ’ Ὅμηρον. καὶ ἄλλοι δὲ ἱστοροῦσι πλείους μεταβεβληκέναι τόπους τὴν πόλιν, ὕστατα δ’ ἐνταῦθα συμμεῖναι κατὰ Κροῖσον μάλιστα. τὰς δὴ τοιαύτας μεταβάσεις εἰς τὰ κάτω μέρη τὰς τότε συμβαινούσας ὑπολαμβάνω καὶ βίων καὶ πολιτειῶν ὑπογράφειν διαφοράς. ἀλλὰ ταῦτα μὲν καὶ ἄλλοτε ἐπισκεπτέον.", "st": "13.1.25"}, {"sp": "N", "t": "τὴν δὲ τῶν Ἰλιέων πόλιν τῶν νῦν τέως μὲν κώμην εἶναί φασι τὸ ἱερὸν ἔχουσαν τῆς Ἀθηνᾶς μικρὸν καὶ εὐτελές, Ἀλέξανδρον δὲ ἀναβάντα μετὰ τὴν ἐπὶ Γρανίκῳ νίκην ἀναθήμασί τε κοσμῆσαι τὸ ἱερὸν καὶ προσαγορεῦσαι πόλιν καὶ οἰκοδομίαις ἀναλαβεῖν προστάξαι τοῖς ἐπιμεληταῖς ἐλευθέραν τε κρῖναι καὶ ἄφορον· ὕστερον δὲ μετὰ τὴν κατάλυσιν τῶν Περσῶν ἐπιστολὴν καταπέμψαι φιλάνθρωπον, ὑπισχνούμενον πόλιν τε ποιῆσαι μεγάλην καὶ ἱερὸν ἐπισημότατον καὶ ἀγῶνα ἀποδείξειν ἱερόν. μετὰ δὲ τὴν ἐκείνου τελευτὴν Λυσίμαχος μάλιστα τῆς πόλεως ἐπεμελήθη καὶ νεὼν κατεσκεύασε καὶ τεῖχος περιεβάλετο ὅσον τετταράκοντα σταδίων, συνῴκισέ τε εἰς αὐτὴν τὰς κύκλῳ πόλεις ἀρχαίας ἤδη κεκακωμένας, ὅτε καὶ Ἀλεξανδρείας ἤδη ἐπεμελήθη, συνῳκισμένης μὲν ἤδη ὑπ’ Ἀντιγόνου καὶ προσηγορευμένης Ἀντιγονείας, μεταβαλούσης δὲ τοὔνομα· ἔδοξε γὰρ εὐσεβὲς εἶναι τοὺς Ἀλέξανδρον διαδεξαμένους ἐκείνου πρότερον κτίζειν ἐπωνύμους πόλεις, εἶθ’ ἑαυτῶν· καὶ δὴ καὶ συνέμεινε καὶ αὔξησιν ἔσχε, νῦν δὲ καὶ Ῥωμαίων ἀποικίαν δέδεκται καὶ ἔστι τῶν ἐλλογίμων πόλεων.", "st": "13.1.26"}, {"sp": "N", "t": "καὶ τὸ Ἴλιον δ’ ὃ νῦν ἔστι κωμόπολίς τις ἦν, ὅτε πρῶτον Ῥωμαῖοι τῆς Ἀσίας ἐπέβησαν καὶ ἐξέβαλον Ἀντίοχον τὸν μέγαν ἐκ τῆς ἐντὸς τοῦ Ταύρου. φησὶ γοῦν Δημήτριος ὁ Σκήψιος, μειράκιον ἐπιδημήσας εἰς τὴν πόλιν κατ’ ἐκείνους τοὺς καιρούς, οὕτως ὠλιγωρημένην ἰδεῖν τὴν κατοικίαν ὥστε μηδὲ κεραμωτὰς ἔχειν τὰς στέγας· Ἡγησιάναξ δὲ τοὺς Γαλάτας περαιωθέντας ἐκ τῆς Εὐρώπης ἀναβῆναι μὲν εἰς τὴν πόλιν δεομένους ἐρύματος, παρὰ χρῆμα δ’ ἐκλιπεῖν διὰ τὸ ἀτείχιστον· ὕστερον δ’ ἐπανόρθωσιν ἔσχε πολλήν. εἶτ’ ἐκάκωσαν αὐτὴν πάλιν οἱ μετὰ Φιμβρίου Ῥωμαῖοι λαβόντες ἐκ πολιορκίας ἐν τῷ Μιθριδατικῷ πολέμῳ. συνεπέμφθη δὲ ὁ Φιμβρίας ὑπάτῳ Ὀυαλερίῳ Φλάκκῳ ταμίας προχειρισθέντι ἐπὶ τὸν Μιθριδάτην· καταστασιάσας δὲ καὶ ἀνελὼν τὸν ὕπατον κατὰ Βιθυνίαν αὐτὸς κατεστάθη κύριος τῆς στρατιᾶς, καὶ προελθὼν εἰς Ἴλιον, οὐ δεχομένων αὐτὸν τῶν Ἰλιέων ὡς λῃστήν, βίαν τε προσφέρει καὶ δεκαταίους αἱρεῖ· καυχωμένου δ’ ὅτι ἣν Ἀγαμέμνων πόλιν δεκάτῳ ἔτει μόλις εἷλε τὸν χιλιόναυν στόλον ἔχων καὶ τὴν σύμπασαν Ἑλλάδα συστρατεύουσαν, ταύτην αὐτὸς δεκάτῃ ἡμέρᾳ χειρώσαιτο, εἶπέ τις τῶν Ἰλιέων “οὐ γὰρ ἦν Ἕκτωρ ὁ ὑπερμαχῶν τῆς πόλεως.” τοῦτον μὲν οὖν ἐπελθὼν Σύλλας κατέλυσε, καὶ τὸν Μιθριδάτην κατὰ συμβάσεις εἰς τὴν οἰκείαν ἀπέπεμψε, τοὺς δ’ Ἰλιέας παρεμυθήσατο πολλοῖς ἐπανορθώμασι. καθ’ ἡμᾶς μέντοι Καῖσαρ ὁ θεὸς πολὺ πλέον αὐτῶν προὐνόησε ζηλώσας ἅμα καὶ Ἀλέξανδρον· ἐκεῖνος γὰρ κατὰ συγγενείας ἀνανέωσιν ὥρμησε προνοεῖν αὐτῶν, ἅμα καὶ φιλόμηρος ὤν· φέρεται γοῦν τις διόρθωσις τῆς Ὁμήρου ποιήσεως, ἡ ἐκ τοῦ νάρθηκος λεγομένη, τοῦ Ἀλεξάνδρου μετὰ τῶν περὶ Καλλισθένη καὶ Ἀνάξαρχον ἐπελθόντος καὶ σημειωσαμένου τινά, ἔπειτα καταθέντος εἰς νάρθηκα ὃν ηὗρεν ἐν τῇ Περσικῇ γάζῃ πολυτελῶς κατεσκευασμένον. κατά τε δὴ τὸν τοῦ ποιητοῦ ζῆλον καὶ κατὰ τὴν συγγένειαν τὴν ἀπὸ τῶν Αἰακιδῶν τῶν ἐν Μολοττοῖς βασιλευσάντων, παρ’ οἷς καὶ τὴν Ἀνδρομάχην ἱστοροῦσι βασιλεῦσαι τὴν Ἕκτορος γενομένην γυναῖκα, ἐφιλοφρονεῖτο πρὸς τοὺς Ἰλιέας ὁ Ἀλέξανδρος· ὁ δὲ Καῖσαρ καὶ φιλαλέξανδρος ὢν καὶ τῆς πρὸς τοὺς Ἰλιέας συγγενείας γνωριμώτερα ἔχων τεκμήρια, ἐπερρώσθη πρὸς τὴν εὐεργεσίαν νεανικῶς· γνωριμώτερα δέ, πρῶτον μὲν ὅτι Ῥωμαῖος, οἱ δὲ Ῥωμαῖοι τὸν Αἰνείαν ἀρχηγέτην ἡγοῦνται, ἔπειτα ὅτι Ἰούλιος ἀπὸ Ἰούλου τινὸς τῶν προγόνων· ἐκεῖνος δ’ ἀπὸ Ἰούλου τὴν προσωνυμίαν ἔσχε ταύτην, τῶν ἀπογόνων εἷς ὢν τῶν ἀπὸ Αἰνείου. χώραν τε δὴ προσένειμεν αὐτοῖς καὶ τὴν ἐλευθερίαν καὶ τὴν ἀλειτουργησίαν αὐτοῖς συνεφύλαξε καὶ μέχρι νῦν συμμένουσιν ἐν τούτοις. ὅτι δ’ οὐκ ἐνταῦθα ἵδρυται τὸ παλαιὸν Ἴλιον καθ’ Ὅμηρον σκοποῦσιν, ἐκ τῶν τοιῶνδε τεκμαίρονται. πρότερον δὲ ὑπογραπτέον τοὺς τόπους ἀπὸ τῆς παραλίας ἀρξαμένους ἀφ’ ἧσπερ ἐλίπομεν.", "st": "13.1.27"}, {"sp": "N", "t": "ἔστι τοίνυν μετ’ Ἄβυδον ἥ τε Δαρδανὶς ἄκρα, ἧς μικρὸν πρότερον ἐμνήσθημεν, καὶ ἡ πόλις ἡ Δάρδανος, διέχουσα τῆς Ἀβύδου ἑβδομήκοντα σταδίους. μεταξύ τε ὁ Ῥοδίος ἐκπίπτει ποταμός, καθ’ ὃν ἐν τῇ Χερρονήσῳ τὸ Κυνὸς σῆμά ἐστιν, ὅ φασιν Ἑκάβης εἶναι τάφον· οἱ δὲ τὸν Ῥοδίον εἰς τὸν Αἴσηπον ἐμβάλλειν φασίν· εἷς δ’ ἐστὶ τῶν ὑπὸ τοῦ ποιητοῦ λεγομένων καὶ οὗτος<br>Ῥῆσός θ’ Ἑπτάπορός τε Κάρησός τε Ῥοδίος τε.<br>ἡ δὲ Δάρδανος κτίσμα ἀρχαῖον, οὕτω δ’ εὐκαταφρόνητον ὥστε πολλάκις οἱ βασιλεῖς οἱ μὲν μετῴκιζον αὐτὴν εἰς Ἄβυδον οἱ δὲ ἀνῴκιζον πάλιν εἰς τὸ ἀρχαῖον κτίσμα. ἐνταῦθα δὲ συνῆλθον Σύλλας τε Κορνήλιος ὁ τῶν Ῥωμαίων ἡγεμὼν καὶ Μιθριδάτης ὁ κληθεὶς Εὐπάτωρ, καὶ συνέβησαν πρὸς ἀλλήλους ἐπὶ καταλύσει τοῦ πολέμου.", "st": "13.1.28"}, {"sp": "N", "t": "πλησίον δ’ ἐστὶ τὸ Ὀφρύνιον, ἐφ’ ᾧ τὸ τοῦ Ἕκτορος ἄλσος ἐν περιφανεῖ τόπῳ· καὶ ἐφεξῆς λίμνη Πτελεώς.", "st": "13.1.29"}, {"sp": "N", "t": "εἶτα Ῥοίτειον πόλις ἐπὶ λόφῳ κειμένη καὶ τῷ Ῥοιτείῳ συνεχὴς ᾐὼν ἁλιτενής, ἐφ’ ᾗ μνῆμα καὶ ἱερὸν Αἴαντος καὶ ἀνδριάς, ὃν ἄραντος Ἀντωνίου κομισθέντα εἰς Αἴγυπτον ἀπέδωκε τοῖς Ῥοιτειεῦσι πάλιν, καθάπερ καὶ ἄλλοις [ἄλλους], ὁ Σεβαστὸς Καῖσαρ. τὰ γὰρ κάλλιστα ἀναθήματα ἐκ τῶν ἐπιφανεστάτων ἱερῶν ὁ μὲν ἦρε τῇ Αἰγυπτίᾳ χαριζόμενος, ὁ δὲ θεοῖς ἀπέδωκε.", "st": "13.1.30"}, {"sp": "N", "t": "μετὰ δὲ τὸ Ῥοίτειον ἔστι τὸ Σίγειον, κατεσπασμένη πόλις, καὶ τὸ ναύσταθμον καὶ ὁ Ἀχαιῶν λιμὴν καὶ τὸ Ἀχαϊκὸν στρατόπεδον καὶ ἡ στομαλίμνη καλουμένη καὶ αἱ τοῦ Σκαμάνδρου ἐκβολαί. συμπεσόντες γὰρ ὅ τε Σιμόεις καὶ ὁ Σκάμανδρος ἐν τῷ πεδίῳ πολλὴν καταφέροντες ἰλὺν προσχοῦσι τὴν παραλίαν καὶ τυφλὸν στόμα τε καὶ λιμνοθαλάττας καὶ ἕλη ποιοῦσι. κατὰ δὲ τὴν Σιγειάδα ἄκραν ἐστὶν ἐν τῇ Χερρονήσῳ τὸ Πρωτεσιλάειον καὶ ἡ Ἐλαιοῦσσα, περὶ ὧν εἰρήκαμεν ἐν τοῖς Θρᾳκίοις.", "st": "13.1.31"}, {"sp": "N", "t": "ἔστι δὲ τὸ μῆκος τῆς παραλίας ταύτης ἀπὸ τοῦ Ῥοιτείου μέχρι Σιγείου καὶ τοῦ Ἀχιλλέως μνήματος εὐθυπλοούντων ἑξήκοντα σταδίων· ὑποπέπτωκε δὲ τῷ Ἰλίῳ πᾶσα, τῷ μὲν νῦν κατὰ τὸν Ἀχαιῶν λιμένα ὅσον δώδεκα σταδίους διέχουσα, τῷ δὲ προτέρῳ τριάκοντα ἄλλοις σταδίοις ἀνωτέρῳ κατὰ τὸ πρὸς τὴν Ἴδην μέρος. τοῦ μὲν οὖν Ἀχιλλέως καὶ ἱερόν ἐστι καὶ μνῆμα πρὸς τῷ Σιγείῳ, Πατρόκλου δὲ καὶ Ἀντιλόχου μνήματα, καὶ ἐναγίζουσιν οἱ Ἰλιεῖς πᾶσι καὶ τούτοις καὶ τῷ Αἴαντι. Ἡρακλέα δ’ οὐ τιμῶσιν αἰτιώμενοι τὴν ὑπ’ αὐτοῦ πόρθησιν. ἀλλ’ ἐκεῖνος μέν, φαίη τις ἄν, οὕτως ἐπόρθησεν ὥστ’ ἀπολιπεῖν τοῖς ὕστερον ἐκπορθήσουσι κεκακωμένην μέν, πόλιν δέ· διὸ καὶ οὕτως εἴρηκεν ὁ ποιητής<br>Ἰλίου ἐξαλάπαξε πόλιν, χήρωσε δ’ ἀγυιάς.<br>ἡ γὰρ χηρεία λιπανδρία τίς ἐστιν, οὐκ ἀφανισμὸς τέλειος· οὗτοι δ’ ἠφάνισαν τελέως, οἷς ἐναγίζειν ἀξιοῦσι καὶ τιμᾶν ὡς θεούς· εἰ μὴ τοῦτ’ αἰτιάσαιντο διότι οὗτοι μὲν δίκαιον πόλεμον ἐξήνεγκαν, ἐκεῖνος δὲ ἄδικον “ἕνεχ’ ἵππων Λαομέδοντος.” πρὸς τοῦτο δὲ πάλιν ἀντιτίθεται μῦθος· οὐ γὰρ ἕνεκα ἵππων, ἀλλὰ μισθοῦ ὑπὲρ τῆς Ἡσιόνης καὶ τοῦ κήτους. ἀλλ’ ἐάσωμεν ταῦτα· εἰς γὰρ μύθων ἀνασκευὰς ἐκπίπτει· τάχα δὲ λανθάνουσί τινες ἡμᾶς αἰτίαι πιστότεραι δι’ ἃς τοῖς Ἰλιεῦσιν ἐπῆλθε τοὺς μὲν τιμᾶν τοὺς δὲ μή. ἔοικε δὲ ὁ ποιητὴς μικρὰν ἀποφαίνειν τὴν πόλιν ἐν τῷ περὶ Ἡρακλέους λόγῳ, εἴπερ<br>ἓξ οἴῃς σὺν νηυσὶ καὶ ἀνδράσι παυροτέροισιν<br>Ἰλίου ἐξαλάπαξε πόλιν.<br>καὶ φαίνεται ὁ Πρίαμος τῷ τοιούτῳ λόγῳ μέγας ἐκ μικροῦ γεγονὼς καὶ βασιλεὺς βασιλέων, ὡς ἔφαμεν. μικρὸν δὲ προελθοῦσιν ἀπὸ τῆς παραλίας ταύτης ἐστὶ τὸ Ἀχαίιον ἤδη τῆς Τενεδίων περαίας ὑπάρχον.", "st": "13.1.32"}, {"sp": "N", "t": "τοιούτων δὲ τῶν ἐπὶ τῇ θαλάττῃ τόπων ὄντων ὑπέρκειται τούτων τὸ Τρωικὸν πεδίον μέχρι τῆς Ἴδης ἀνῆκον ἐπὶ πολλοὺς σταδίους κατὰ τὸ πρὸς ἕω μέρος. τούτου δ’ ἡ μὲν παρώρειός ἐστι στενή, τῇ μὲν ἐπὶ τὴν μεσημβρίαν τεταμένη μέχρι τῶν κατὰ Σκῆψιν τόπων, τῇ δ’ ἐπὶ τὰς ἄρκτους μέχρι τῶν κατὰ Ζέλειαν Λυκίων. ταύτην δ’ ὁ ποιητὴς ὑπ’ Αἰνείᾳ τάττει καὶ τοῖς Ἀντηνορίδαις, καλεῖ δὲ Δαρδανίαν. ὑπὸ δὲ ταύτῃ Κεβρηνία, πεδιὰς ἡ πλείστη, παράλληλός πως τῇ Δαρδανίᾳ· ἦν δὲ καὶ πόλις ποτὲ Κεβρήνη. ὑπονοεῖ δ’ ὁ Δημήτριος μέχρι δεῦρο διατείνειν τὴν περὶ τὸ Ἴλιον χώραν τὴν ὑπὸ τῷ Ἕκτορι, ἀνήκουσαν ἀπὸ τοῦ ναυστάθμου μέχρι Κεβρηνίας· τάφον τε γὰρ Ἀλεξάνδρου δείκνυσθαί φησιν αὐτόθι καὶ Οἰνώνης, ἣν ἱστοροῦσι γυναῖκα γεγονέναι τοῦ Ἀλεξάνδρου πρὶν Ἑλένην ἁρπάσαι· λέγειν τε τὸν ποιητήν<br>Κεβριόνην νόθον υἱὸν ἀγακλῆος Πριάμοιο,<br>ὃν εἰκὸς εἶναι ἐπώνυμον τῆς χώρας ἢ καὶ πόλεως, ὅπερ πιθανώτερον· τὴν δὲ Κεβρηνίαν διήκειν μέχρι τῆς Σκηψίας, ὅριον δ’ εἶναι τὸν Σκάμανδρον μέσον αὐτῶν ῥέοντα· ἔχθραν δ’ ἀεὶ καὶ πόλεμον εἶναι τοῖς τε Κεβρηνοῖς καὶ τοῖς Σκηψίοις, ἕως Ἀντίγονος αὐτοὺς συνῴκισεν εἰς τὴν τότε μὲν Ἀντιγόνειαν νῦν δὲ Ἀλεξάνδρειαν· τοὺς μὲν οὖν Κεβρηνιέας συμμεῖναι τοῖς ἄλλοις ἐν τῇ Ἀλεξανδρείᾳ, τοὺς δὲ Σκηψίους ἐπανελθεῖν εἰς τὴν οἰκείαν ἐπιτρέψαντος Λυσιμάχου.", "st": "13.1.33"}, {"sp": "N", "t": "ἀπὸ δὲ τῆς κατὰ [τούτους] τοὺς τόπους Ἰδαίας ὀρεινῆς δύο φησὶν ἀγκῶνας ἐκτείνεσθαι πρὸς θάλατταν, τὸν μὲν εὐθὺ Ῥοιτείου τὸν δὲ Σιγείου, ποιοῦντας ἐξ ἀμφοῖν γραμμὴν ἡμικυκλιώδη· τελευτᾶν δ’ ἐν τῷ πεδίῳ, τοσοῦτον ἀπέχοντας τῆς θαλάττης ὅσον τὸ νῦν Ἴλιον. τοῦτο μὲν δὴ μεταξὺ τῆς τελευτῆς τῶν λεχθέντων ἀγκώνων εἶναι, τὸ δὲ παλαιὸν κτίσμα μεταξὺ τῆς ἀρχῆς· ἀπολαμβάνεσθαι δ’ ἐντὸς τό τε Σιμοείσιον πεδίον δι’ οὗ ὁ Σιμόεις φέρεται, καὶ τὸ Σκαμάνδριον δι’ οὗ Σκάμανδρος ῥεῖ. τοῦτο δὲ καὶ ἰδίως Τρωικὸν λέγεται, καὶ τοὺς πλείστους ἀγῶνας ὁ ποιητὴς ἐνταῦθα ἀποδίδωσι· πλατύτερον γάρ ἐστι, καὶ τοὺς ὀνομαζομένους τόπους ἐνταῦθα δεικνυμένους ὁρῶμεν, τὸν ἐρινεόν, τὸν τοῦ Αἰσυήτου τάφον, τὴν Βατίειαν, τὸ τοῦ Ἴλου σῆμα. οἱ δὲ ποταμοὶ ὅ τε Σκάμανδρος καὶ ὁ Σιμόεις, ὁ μὲν τῷ Σιγείῳ πλησιάσας ὁ δὲ τῷ Ῥοιτείῳ, μικρὸν ἔμπροσθεν τοῦ νῦν Ἰλίου συμβάλλουσιν, εἶτ’ ἐπὶ τὸ Σίγειον ἐκδιδόασι καὶ ποιοῦσι τὴν στομαλίμνην καλουμένην. διείργει δ’ ἑκάτερον τῶν λεχθέντων πεδίων ἀπὸ θατέρου μέγας τις αὐχὴν τῶν εἰρημένων ἀγκώνων ἐπ’ εὐθείας, ἀπὸ τοῦ νῦν Ἰλίου τὴν ἀρχὴν ἔχων συμφυὴς αὐτῷ, τεινόμενος δ’ ἕως τῆς Κεβρηνίας καὶ ἀποτελῶν τὸ Ε γράμμα πρὸς τοὺς ἑκατέρωθεν ἀγκῶνας.", "st": "13.1.34"}, {"sp": "N", "t": "ὑπὲρ δὲ τούτου μικρὸν ἡ τῶν Ἰλιέων κώμη ἐστίν, ἐν ᾗ νομίζεται τὸ παλαιὸν Ἴλιον ἱδρῦσθαι πρότερον, τριάκοντα σταδίους διέχον ἀπὸ τῆς νῦν πόλεως. ὑπὲρ δὲ τῆς Ἰλιέων κώμης δέκα σταδίοις ἐστὶν ἡ Καλλικολώνη, λόφος τις, παρ’ ὃν ὁ Σιμόεις ῥεῖ πενταστάδιον διέχων· γίνεται οὖν εὔλογον πρῶτον μὲν τὸ ἐπὶ τοῦ Ἄρεος<br>ὦρτο δ’ Ἄρης ἑτέρωθεν ἐρεμνῇ λαίλαπι ἶσος,<br>ὀξὺ κατ’ ἀκροτάτης πόλιος Τρώεσσι κελεύων,<br>ἄλλοτε πὰρ Σιμόεντι θέων ἐπὶ Καλλικολώνῃ.<br>τῆς γὰρ μάχης ἐπὶ τῷ Σκαμανδρίῳ πεδίῳ συντελουμένης πιθανῶς ἂν ὁ Ἄρης ἄλλοτε μὲν τὴν ἐγκέλευσιν ἀπὸ τῆς ἀκροπόλεως ποιοῖτο, ἄλλοτε δ’ ἐκ τῶν πλησίον τόπων τοῦ τε Σιμόεντος καὶ τῆς Καλλικολώνης, μέχρι οὗ εἰκὸς καὶ τὴν μάχην παρατετάσθαι· τετταράκοντα δὲ σταδίους διεχούσης τῆς Καλλικολώνης ἀπὸ τοῦ νῦν Ἰλίου, τί χρήσιμον ἐπὶ τοσοῦτον μεταλαμβάνεσθαι τοὺς τόπους ἐφ’ ὅσον ἡ διάταξις οὐ διέτεινε; τό τε<br>πρὸς Θύμβρης δ’ ἔλαχον Λύκιοι<br>οἰκειότερόν ἐστι τῷ παλαιῷ κτίσματι· πλησίον γάρ ἐστι τὸ πεδίον ἡ Θύμβρα καὶ ὁ δι’ αὐτοῦ ῥέων ποταμὸς Θύμβριος, ἐμβάλλων εἰς τὸν Σκάμανδρον κατὰ τὸ Θυμβραίου Ἀπόλλωνος ἱερόν, τοῦ δὲ νῦν Ἰλίου καὶ πεντήκοντα σταδίους διέχει. ὅ τε ἐρινεός, τραχύς τις τόπος καὶ ἐρινεώδης, τῷ μὲν ἀρχαίῳ κτίσματι ὑποπέπτωκεν, ὥστε τὸ<br>λαὸν δὲ στῆσον παρ’ ἐρινεόν, ἔνθα μάλιστα<br>ἀμβατός ἐστι πόλις καὶ ἐπίδρομον ἔπλετο τεῖχος<br>οἰκείως ἂν λέγοι ἡ Ἀνδρομάχη· τῆς δὲ νῦν πόλεως πάμπολυ ἀφέστηκε· καὶ ὁ φηγὸς δὲ μικρὸν κατωτέρω ἐστὶ τοῦ ἐρινεοῦ, ἐφ’ οὗ φησιν ὁ Ἀχιλλεύς<br>ὄφρα δ’ ἐγὼ μετ’ Ἀχαιοῖσιν πολέμιζον,<br>οὐκ ἐθέλεσκε μάχην ἀπὸ τείχεος ὀρνύμεν Ἕκτωρ,<br>ἀλλ’ ὅσον ἐς Σκαιάς τε πύλας καὶ φηγὸν ἵκανεν.", "st": "13.1.35"}, {"sp": "N", "t": "καὶ μὴν τό γε ναύσταθμον τὸ νῦν ἔτι λεγόμενον πλησίον οὕτως ἐστὶ τῆς νῦν πόλεως, ὥστε θαυμάζειν εἰκότως ἄν τινα τῶν μὲν τῆς ἀπονοίας τῶν δὲ τοὐναντίον τῆς ἀψυχίας· ἀπονοίας μέν, εἰ τοσοῦτον χρόνον ἀτείχιστον αὐτὸ εἶχον, πλησίον οὔσης τῆς πόλεως καὶ τοσούτου πλήθους τοῦ τ’ ἐν αὐτῇ καὶ τοῦ ἐπικουρικοῦ· νεωστὶ γὰρ γεγονέναι φησὶ τὸ τεῖχος (ἢ οὐδ’ ἐγένετο, ὁ δὲ πλάσας ποιητὴς ἠφάνισεν, ὡς Ἀριστοτέλης φησίν)· ἀψυχίας δέ, εἰ γενομένου τοῦ τείχους ἐτειχομάχουν καὶ εἰσέπεσον εἰς αὐτὸ τὸ ναύσταθμον καὶ προσεμάχοντο ταῖς ναυσίν, ἀτείχιστον δὲ ἔχοντες οὐκ ἐθάρρουν προσιόντες πολιορκεῖν μικροῦ τοῦ διαστήματος ὄντος· ἔστι γὰρ τὸ ναύσταθμον πρὸς Σιγείῳ, πλησίον δὲ καὶ ὁ Σκάμανδρος ἐκδίδωσι διέχων τοῦ Ἰλίου σταδίους εἴκοσιν. εἰ δὲ φήσει τις τὸν νῦν λεγόμενον Ἀχαιῶν λιμένα εἶναι τὸ ναύσταθμον, ἐγγυτέρω τινὰ λέξει τόπον ὅσον δώδεκα σταδίους διεστῶτα τῆς πόλεως, [τὸ] ἐπὶ θαλάττῃ πεδίον συμπροστιθείς … διότι τοῦτο πᾶν πρόχωμα τῶν ποταμῶν ἐστι τὸ πρὸ τῆς πόλεως ἐπὶ θαλάττῃ πεδίον, ὥστε εἰ δωδεκαστάδιόν ἐστι νῦν τὸ μεταξύ, τότε καὶ τῷ ἡμίσει ἔλαττον ὑπῆρχε. καὶ ἡ διήγησις δ’ ἡ πρὸς τὸν Εὔμαιον ὑπὸ τοῦ Ὀδυσσέως διασκευασθεῖσα μέγα ἐμφαίνει τὸ διάστημα τὸ μέχρι τῆς πόλεως ἀπὸ τοῦ ναυστάθμου<br>ὡς ὅθ’ ὑπὸ Τροίῃ λόχον ἤγομεν.<br>φησὶ γὰρ ὑποβάς<br>λίην γὰρ νηῶν ἑκὰς ἤλθομεν.<br>ἐπί τε τὴν κατασκοπὴν πέμπονται γνωσόμενοι, πότερον μενοῦσι παρὰ νηυσὶν ἀπόπροθεν πολὺ ἀπεσπασμένοι τοῦ οἰκείου τείχους<br>ἠὲ πόλινδε<br>ἂψ ἀναχωρήσουσι.<br>καὶ ὁ Πολυδάμας<br>ἀμφὶ μάλα φράζεσθε, φίλοι· κέλομαι γὰρ ἔγωγε ἄστυδε νῦν ἰέναι<br>φησίν<br>ἑκὰς δ’ ἀπὸ τείχεός εἰμεν.<br>παρατίθησι δ’ ὁ Δημήτριος καὶ τὴν Ἀλεξανδρίνην Ἑστίαιαν μάρτυρα, τὴν συγγράψασαν περὶ τῆς Ὁμήρου Ἰλιάδος, πυνθανομένην εἰ περὶ τὴν νῦν πόλιν ὁ πόλεμος συνέστη, καὶ … τὸ Τρωικὸν πεδίον, ὃ μεταξὺ τῆς πόλεως καὶ τῆς θαλάττης ὁ ποιητὴς φράζει· τὸ μὲν γὰρ πρὸ τῆς νῦν πόλεως ὁρώμενον πρόχωμα εἶναι τῶν ποταμῶν ὕστερον γεγονός.", "st": "13.1.36"}, {"sp": "N", "t": "ὅ τε Πολίτης<br>ὃς Τρώων σκοπὸς ἷζε ποδωκείῃσι πεποιθώς,<br>τύμβῳ ἐπ’ ἀκροτάτῳ Αἰσυήταο γέροντος,<br>μάταιος ἦν. καὶ γὰρ εἰ ἐπ’ ἀκροτάτῳ, ὅμως [ἀπὸ] πολὺ ἂν μείζονος ὕψους τῆς ἀκροπόλεως ἐσκόπευεν ἐξ ἴσου σχεδόν τι διαστήματος, μὴ δεόμενος μηδὲν τῆς ποδωκείας τοῦ ἀσφαλοῦς χάριν· πέντε γὰρ διέχει σταδίους ὁ νῦν δεικνύμενος τοῦ Αἰσυήτου τάφος κατὰ τὴν εἰς Ἀλεξάνδρειαν ὁδόν. οὐδ’ ἡ τοῦ Ἕκτορος δὲ περιδρομὴ ἡ περὶ τὴν πόλιν ἔχει τι εὔλογον· οὐ γάρ ἐστι περίδρομος ἡ νῦν διὰ τὴν συνεχῆ ῥάχιν· ἡ δὲ παλαιὰ ἔχει περιδρομήν.", "st": "13.1.37"}, {"sp": "N", "t": "οὐδὲν δ’ ἴχνος σώζεται τῆς ἀρχαίας πόλεως. εἰκότως· ἅτε γὰρ ἐκπεπορθημένων τῶν κύκλῳ πόλεων, οὐ τελέως δὲ κατεσπασμένων, ταύτης δ’ ἐκ βάθρων ἀνατετραμμένης, οἱ λίθοι πάντες εἰς τὴν ἐκείνων ἀνάληψιν μετηνέχθησαν. Ἀρχαιάνακτα γοῦν φασι τὸν Μιτυληναῖον ἐκ τῶν ἐκεῖθεν λίθων τὸ Σίγειον τειχίσαι. τοῦτο δὲ κατέσχον μὲν Ἀθηναῖοι Φρύνωνα τὸν ὀλυμπιονίκην πέμψαντες, Λεσβίων ἐπιδικαζομένων σχεδόν τι τῆς συμπάσης Τρῳάδος· ὧν δὴ καὶ κτίσματά εἰσιν αἱ πλεῖσται τῶν κατοικιῶν, αἱ μὲν συμμένουσαι καὶ νῦν αἱ δ’ ἠφανισμέναι. Πιττακὸς δ’ ὁ Μιτυληναῖος, εἷς τῶν ἑπτὰ σοφῶν λεγομένων, πλεύσας ἐπὶ τὸν Φρύνωνα στρατηγὸν διεπολέμει τέως διατιθεὶς καὶ πάσχων κακῶς, ὕστερον δ’ ἐκ μονομαχίας, προκαλεσαμένου τοῦ Φρύνωνος, ἁλιευτικὴν ἀναλαβὼν σκευὴν συνέδραμε, καὶ τῷ μὲν ἀμφιβλήστρῳ περιέβαλε τῇ τριαίνῃ δὲ καὶ τῷ ξιφιδίῳ ἔπειρε καὶ ἀνεῖλε. μένοντος δ’ ἔτι τοῦ πολέμου Περίανδρος διαιτητὴς αἱρεθεὶς ὑπὸ ἀμφοῖν ἔλυσε τὸν πόλεμον.", "st": "13.1.38"}, {"sp": "N", "t": "Τίμαιον δὲ ψεύσασθαί φησιν ὁ Δημήτριος ἱστοροῦντα ἐκ τῶν λίθων τῶν ἐξ Ἰλίου Περίανδρον ἐπιτειχίσαι τὸ Ἀχίλλειον τοῖς Ἀθηναίοις, βοηθοῦντα τοῖς περὶ Πιττακόν· ἐπιτειχισθῆναι μὲν γὰρ ὑπὸ τῶν Μιτυληναίων τὸν τόπον τοῦτον τῷ Σιγείῳ, οὐ μὴν ἐκ λίθων τοιούτων οὐδ’ ὑπὸ τοῦ Περιάνδρου. πῶς γὰρ ἂν αἱρεθῆναι διαιτητὴν τὸν προσπολεμοῦντα; Ἀχίλλειον δ’ ἔστιν ὁ τόπος ἐν ᾧ τὸ Ἀχιλλέως μνῆμα, κατοικία μικρά. κατέσκαπται δὲ καὶ τὸ Σίγειον ὑπὸ τῶν Ἰλιέων ἀπειθοῦν· ὑπ’ ἐκείνοις γὰρ ἦν ὕστερον ἡ παραλία πᾶσα ἡ μέχρι Δαρδάνου, καὶ νῦν ὑπ’ ἐκείνοις ἐστί. τὸ δὲ παλαιὸν ὑπὸ τοῖς Αἰολεῦσιν ἦν τὰ πλεῖστα, ὥστε Ἔφορος οὐκ ὀκνεῖ πᾶσαν τὴν ἀπὸ Ἀβύδου μέχρι Κύμης καλεῖν Αἰολίδα. Θουκυδίδης δέ φησιν ἀφαιρεθῆναι τὴν Τροίαν ὑπὸ Ἀθηναίων τοὺς Μιτυληναίους ἐν τῷ Πελοποννησιακῷ πολέμῳ τῷ Παχητείῳ.", "st": "13.1.39"}, {"sp": "N", "t": "λέγουσι δ’ οἱ νῦν Ἰλιεῖς καὶ τοῦτο ὡς οὐδὲ τελέως ἠφανίσθαι συνέβαινεν τὴν πόλιν κατὰ τὴν ἅλωσιν ὑπὸ τῶν Ἀχαιῶν, οὐδ’ ἐξελείφθη οὐδέποτε. αἱ γοῦν Λοκρίδες παρθένοι μικρὸν ὕστερον ἀρξάμεναι ἐπέμποντο κατ’ ἔτος· καὶ ταῦτα δ’ οὐχ Ὁμηρικά· οὐδὲ γὰρ τῆς Κασάνδρας φθορὰν οἶδεν Ὅμηρος, ἀλλ’ ὅτι μὲν παρθένος ἦν ὑπ’ ἐκεῖνον τὸν χρόνον λέγει<br>πέφνε γὰρ Ὀθρυονῆα, Καβησόθεν ἔνδον ἐόντα,<br>ὅς ῥα νέον πτολέμοιο μετὰ κλέος εἰληλούθει.<br>ᾔτεε δὲ Πριάμοιο θυγατρῶν εἶδος ἀρίστην,<br>Κασσάνδρην, ἀνάεδνον.<br>βίας δὲ οὐδὲ μέμνηται, οὐδ’ ὅτι ἡ φθορὰ τοῦ Αἴαντος ἐν τῇ ναυαγίᾳ κατὰ μῆνιν Ἀθηνᾶς συνέβη ἢ κατὰ τοιαύτην αἰτίαν, ἀλλ’ ἀπεχθανόμενον μὲν τῇ Ἀθηνᾷ κατὰ τὸ κοινὸν εἴρηκεν (ἁπάντων γὰρ εἰς τὸ ἱερὸν ἀσεβησάντων ἅπασιν ἐμήνιεν), ἀπολέσθαι δὲ ὑπὸ Ποσειδῶνος μεγαλορρημονήσαντα· τὰς δὲ Λοκρίδας πεμφθῆναι Περσῶν ἤδη κρατούντων συνέβη.", "st": "13.1.40"}, {"sp": "N", "t": "οὕτω μὲν δὴ λέγουσιν οἱ Ἰλιεῖς, Ὅμηρος δὲ ῥητῶς τὸν ἀφανισμὸν τῆς πόλεως εἴρηκεν<br>ἔσσεται ἦμαρ ὅταν ποτ’ ὀλώλῃ Ἴλιος ἱρή.<br>ἦ γὰρ καὶ Πριάμοιο πόλιν διεπέρσαμεν αἰπήν.<br>βουλῇ καὶ μύθοισι.<br>πέρθετο δὲ Πριάμοιο πόλις δεκάτῳ ἐνιαυτῷ<br>καὶ τὰ τοιαῦτα δὲ τοῦ αὐτοῦ τίθενται τεκμήρια, οἷον ὅτι τῆς Ἀθηνᾶς τὸ ξόανον νῦν μὲν ἑστηκὸς ὁρᾶται, Ὅμηρος δὲ καθήμενον ἐμφαίνει· πέπλον γὰρ κελεύει<br>θεῖναι Ἀθηναίης ἐπὶ γούνασιν.<br>, ὡς καί,<br>μή ποτε γούνασιν οἷσιν ἐφέζεσθαι φίλον υἱόν.<br>βέλτιον γὰρ οὕτως ἢ ὡς τινὲς δέχονται ἀντὶ τοῦ “παρὰ τοῖς γόνασι θεῖναι” παρατιθέντες τὸ<br>ἡ δ’ ἧσται ἐπ’ ἐσχάρῃ ἐν πυρὸς αὐγῇ<br>ἀντὶ τοῦ “παρ’ ἐσχάρῃ.” τίς γὰρ ἂν νοηθείη πέπλου ἀνάθεσις παρὰ τοῖς γόνασι; καὶ οἱ τὴν προσῳδίαν δὲ διαστρέφοντες, “γουνάσιν” ὡς θυιάσιν, ὁποτέρως ἂν δέξωνται, ἀπεραντολογοῦσιν, εἴθ’ ἱκετ[είας ἑρμην]εύοντες [εἴ]τε φρένας. πολλὰ δὲ τῶν ἀρχαίων τῆς Ἀθηνᾶς ξοάνων καθήμενα δείκνυται, καθάπερ ἐν Φωκαίᾳ Μασσαλίᾳ Ῥώμῃ Χίῳ ἄλλαις πλείοσιν. ὁμολογοῦσι δὲ καὶ οἱ νεώτεροι τὸν ἀφανισμὸν τῆς πόλεως, ὧν ἔστι καὶ Λυκοῦργος ὁ ῥήτωρ· μνησθεὶς γὰρ τῆς Ἰλιέων πόλεως φησί τίς οὐκ ἀκήκοεν, ὡς ἅπαξ ὑπὸ τῶν Ἑλλήνων κατεσκάφθη, ἀοίκητον οὖσαν;", "st": "13.1.41"}, {"sp": "N", "t": "εἰκάζουσι δὲ τοὺς ὕστερον ἀνακτίσαι διανοουμένους οἰωνίσασθαι τὸν τόπον ἐκεῖνον, εἴτε διὰ τὰς συμφορὰς εἴτε καὶ καταρασαμένου τοῦ Ἀγαμέμνονος κατὰ παλαιὸν ἔθος, καθάπερ καὶ ὁ Κροῖσος ἐξελὼν τὴν Σιδήνην, εἰς ἣν ὁ τύραννος κατέφυγε Γλαυκίας, ἀρὰς ἔθετο κατὰ τῶν τειχιούντων πάλιν τὸν τόπον. ἐκείνου μὲν οὖν ἀποστῆναι τοῦ χωρίου, ἕτερον δὲ τειχίσαι. πρῶτοι μὲν οὖν Ἀστυπαλαιεῖς οἱ τὸ Ῥοίτειον κατασχόντες συνῴκισαν πρὸς τῷ Σιμόεντι Πόλιον, ὃ νῦν καλεῖται Πόλισμα, οὐκ ἐν εὐερκεῖ τόπῳ· διὸ κατεσπάσθη ταχέως. ἐπὶ δὲ τῶν Λυδῶν ἡ νῦν ἐκτίσθη κατοικία καὶ τὸ ἱερόν· οὐ μὴν πόλις γε ἦν, ἀλλὰ πολλοῖς χρόνοις ὕστερον καὶ κατ’ ὀλίγον, ὡς εἴρηται, τὴν αὔξησιν ἔσχεν. Ἑλλάνικος δὲ χαριζόμενος τοῖς Ἰλιεῦσιν, οἷος ἐκείνου θυμός, συνηγορεῖ τὸ τὴν αὐτὴν εἶναι πόλιν τὴν νῦν τῇ τότε. τὴν δὲ χώραν ἀφανισθείσης τῆς πόλεως οἱ τὸ Σίγειον καὶ τὸ Ῥοίτειον ἔχοντες διενείμαντο καὶ τῶν ἄλλων ὡς ἕκαστοι τῶν πλησιοχώρων, ἀπέδοσαν δ’ ἀνοικισθείσης.", "st": "13.1.42"}, {"sp": "N", "t": "πολυπίδακον δὲ τὴν Ἴδην ἰδίως οἴονται λέγεσθαι διὰ τὸ πλῆθος τῶν ἐξ αὐτῆς ῥεόντων ποταμῶν καθ’ ἃ μάλιστα ἡ Δαρδανικὴ ὑποπέπτωκεν αὐτῇ καὶ μέχρι Σκήψεως καὶ τὰ περὶ Ἴλιον. ἔμπειρος δ’ ὢν τῶν τόπων ὡς ἂν ἐπιχώριος ἀνὴρ ὁ Δημήτριος τοτὲ μὲν οὕτως λέγει περὶ αὐτῶν· ἔστι γὰρ λόφος τις τῆς Ἴδης Κότυλος· ὑπέρκειται δ’ οὗτος ἑκατόν που καὶ εἴκοσι σταδίοις Σκήψεως, ἐξ οὗ ὅ τε Σκάμανδρος ῥεῖ καὶ ὁ Γράνικος καὶ Αἴσηπος, οἱ μὲν πρὸς ἄρκτον καὶ τὴν Προποντίδα ἐκ πλειόνων πηγῶν συλλειβόμενοι, ὁ δὲ Σκάμανδρος ἐπὶ δύσιν ἐκ μιᾶς πηγῆς· πᾶσαι δ’ ἀλλήλαις πλησιάζουσιν ἐν εἴκοσι σταδίων περιεχόμεναι διαστήματι· πλεῖστον δ’ ἀφέστηκεν ἀπὸ τῆς ἀρχῆς τὸ τοῦ Αἰσήπου τέλος, σχεδόν τι καὶ πεντακοσίους σταδίους. παρέχει δὲ λόγον πῶς φησὶν ὁ ποιητής<br>κρουνὼ δ’ ἵκανον καλλιρρόω, ἔνθα δὲ πηγαὶ<br>δοιαὶ ἀναΐσσουσι Σκαμάνδρου δινήεντος·<br>ἡ μὲν γάρ θ’ ὕδατι λιαρῷ ῥέει,<br>ὅ ἐστι θερμῷ· ἐπιφέρει δέ<br>ἀμφὶ δὲ καπνὸς<br>γίγνεται ἐξ αὐτῆς ὡσεὶ πυρός.<br>ἡ δ’ ἑτέρη θέρεϊ προρέει εἰκυῖα χαλάζῃ<br>ἢ χιόνι ψυχρῇ.<br>οὔτε γὰρ θερμὰ νῦν ἐν τῷ τόπῳ εὑρίσκεται, οὔθ’ ἡ τοῦ Σκαμάνδρου πηγὴ ἐνταῦθα ἀλλ’ ἐν τῷ ὄρει, καὶ μία, ἀλλ’ οὐ δύο. τὰ μὲν οὖν θερμὰ ἐκλελεῖφθαι εἰκός, τὸ δὲ ψυχρὸν κατὰ διάδυσιν ὑπεκρέον ἐκ τοῦ Σκαμάνδρου κατὰ τοῦτ’ ἀνατέλλειν τὸ χωρίον, ἢ καὶ διὰ τὸ πλησίον εἶναι τοῦ Σκαμάνδρου καὶ τοῦτο τὸ ὕδωρ λέγεσθαι τοῦ Σκαμάνδρου πηγήν· οὕτω γὰρ λέγονται πλείους πηγαὶ τοῦ αὐτοῦ ποταμοῦ.", "st": "13.1.43"}, {"sp": "N", "t": "συμπίπτει δ’ εἰς αὐτὸν ὁ Ἄνδιρος ἀπὸ τῆς Καρησηνῆς, ὀρεινῆς τινος πολλαῖς κώμαις συνοικουμένης καὶ γεωργουμένης καλῶς, παρακειμένης τῇ Δαρδανικῇ μέχρι τῶν περὶ Ζέλειαν καὶ Πιτύειαν τόπων· ὠνομάσθαι δὲ τὴν χώραν φασὶν ἀπὸ τοῦ Καρήσου ποταμοῦ, ὃν ὠνόμακεν ὁ ποιητής<br>Ῥῆσός θ’ Ἑπτάπορός τε Κάρησός τε Ῥοδίος τε·<br>τὴν δὲ πόλιν κατεσπάσθαι τὴν ὁμώνυμον τῷ ποταμῷ. πάλιν δ’ οὕτως φησίν “ὁ μὲν Ῥῆσος ποταμὸς νῦν καλεῖται Ῥοείτης, εἰ μὴ ἄρα ὁ εἰς τὸν Γράνικον ἐμβάλλων Ῥῆσός ἐστιν. Ἑπτάπορος δέ, ὃν καὶ Πολύπορον λέγουσιν, ἑπτάκις διαβαινόμενος ἐκ τῶν περὶ τὴν καλὴν πεύκην χωρίων ἐπὶ Μελαινὰς κώμην ἰοῦσι καὶ τὸ Ἀσκληπίειον, ἵδρυμα Λυσιμάχου. περὶ δὲ τῆς καλῆς πεύκης Ἄτταλος ὁ πρῶτος βασιλεύσας οὕτως γράφει· τὴν μὲν περίμετρον εἶναί φησι ποδῶν τεττάρων καὶ εἴκοσι, τὸ δὲ ὕψος ἀπὸ μὲν ῥίζης ἀνιέναι ἐπὶ ἑξήκοντα καὶ ἑπτὰ πόδας, εἶτ’ εἰς τρία σχιζομένην ἴσον ἀλλήλων διέχοντα, εἶτα πάλιν συναγομένην εἰς μίαν κορυφήν, ἀποτελοῦσαν τὸ πᾶν ὕψος δυεῖν πλέθρων καὶ πεντεκαίδεκα πηχῶν· Ἀδραμυττίου δὲ διέχει πρὸς ἄρκτον ἑκατὸν καὶ ὀγδοήκοντα σταδίους. Κάρησος δ’ ἀπὸ Μαλοῦντος ῥεῖ, τόπου τινὸς κειμένου μεταξὺ Παλαισκήψεως καὶ Ἀχαιίου τῆς Τενεδίων περαίας· ἐμβάλλει δὲ εἰς τὸν Αἴσηπον. Ῥοδίος δὲ ἀπὸ Κλεανδρίας καὶ Γόρδου, ἃ διέχει τῆς καλῆς πεύκης ἑξήκοντα σταδίους· ἐμβάλλει δ’ εἰς τὸν Αἴνιον.”", "st": "13.1.44"}, {"sp": "N", "t": "“τοῦ δ’ αὐλῶνος τοῦ περὶ τὸν Αἴσηπον ἐν ἀριστερᾷ τῆς ῥύσεως αὐτοῦ πρῶτον ἔστι Πολίχνα τειχῆρες χωρίον, εἶθ’ ἡ Παλαίσκηψις, εἶτ’ Ἀλαζόνιον. τοῦτ’ ἤδη πεπλασμένον πρὸς τὴν τῶν Ἁλιζώνων ὑπόθεσιν, περὶ ὧν εἰρήκαμεν. εἶτα Κάρησος ἐρήμη καὶ ἡ Καρησηνὴ καὶ ὁμώνυμος ποταμός, ποιῶν καὶ αὐτὸς αὐλῶνα ἀξιόλογον, ἐλάττω δὲ τοῦ περὶ τὸν Αἴσηπον. τὰ δ’ ἑξῆς ἤδη τὰ τῆς Ζελείας ἐστὶ πεδία καὶ ὀροπέδια καλῶς γεωργούμενα· ἐν δεξιᾷ δὲ τοῦ Αἰσήπου μεταξὺ Πολίχνας τε καὶ Παλαισκήψεως ἡ Νέα κώμη καὶ Ἀργυρία.” καὶ τοῦτο πάλιν πλάσμα πρὸς τὴν αὐτὴν ὑπόθεσιν, ὅπως σωθείη τὸ<br>ὅθεν ἀργύρου ἐστὶ γενέθλη.<br>ἡ οὖν Ἀλύβη ποῦ ἢ Ἀλόπη ἢ ὅπως βούλονται παρονομάζειν; ἐχρῆν γὰρ καὶ τοῦτο πλάσαι παρατριψαμένους τὸ μέτωπον, καὶ μὴ χωλὸν ἐᾶν καὶ ἕτοιμον πρὸς ἔλεγχον ἅπαξ ἤδη ἀποτετολμηκότας. ταῦτα μὲν οὖν ἔνστασιν ἔχει τοιαύτην, τἆλλα δὲ ὑπολαμβάνομεν, ἢ τά γε πλεῖστα, δεῖν προσέχειν ὡς ἀνδρὶ ἐμπείρῳ καὶ ἐντοπίῳ, φροντίσαντί τε τοσοῦτον περὶ τούτων ὥστε τριάκοντα βίβλους συγγράψαι στίχων ἐξήγησιν μικρῷ πλειόνων ἑξήκοντα, τοῦ καταλόγου τῶν Τρώων. φησὶ δ’ οὖν τὴν Παλαίσκηψιν τῆς μὲν Νέας διέχειν πεντήκοντα σταδίους, τοῦ δὲ ποταμοῦ τοῦ Αἰσήπου τριάκοντα· ἀπὸ δὲ τῆς Παλαισκήψεως ταύτης διατεῖναι τὴν ὁμωνυμίαν καὶ εἰς ἄλλους πλείους τόπους. ἐπάνιμεν δὲ ἐπὶ τὴν παραλίαν ὅθενπερ ἀπελίπομεν.", "st": "13.1.45"}, {"sp": "N", "t": "ἔστι δὴ μετὰ τὴν Σιγειάδα ἄκραν καὶ τὸ Ἀχίλλειον ἡ Τενεδίων περαία τὸ Ἀχαίιον καὶ αὐτὴ ἡ Τένεδος, οὐ πλείους τῶν τετταράκοντα σταδίων διέχουσα τῆς ἠπείρου· ἔχει δὲ τὴν περίμετρον ὅσον ὀγδοήκοντα σταδίων καὶ πόλιν Αἰολίδα καὶ λιμένας δύο καὶ ἱερὸν τοῦ Σμινθέως Ἀπόλλωνος, καθάπερ καὶ ὁ ποιητὴς μαρτυρεῖ<br>Τενέδοιό τε ἶφι ἀνάσσεις,<br>Σμινθεῦ.<br>περίκειται δ’ αὐτῇ νησία πλείω, καὶ δὴ καὶ δύο ἃ καλοῦσι Καλύδνας, κειμένας κατὰ τὸν ἐπὶ Λεκτὸν πλοῦν· καὶ αὐτὴν δὲ τὴν Τένεδον Κάλυδναν τινὲς εἶπον, ἄλλοι δὲ Λεύκοφρυν. μυθεύουσι δ’ ἐν αὐτῇ τὰ περὶ τὸν Τέννη ἀφ’ οὗ καὶ τοὔνομα τῇ νήσῳ, καὶ τὰ περὶ τὸν Κύκνον, Θρᾷκα τὸ γένος, πατέρα δ’, ὥς τινες, τοῦ Τέννου, βασιλέα δὲ Κολωνῶν.", "st": "13.1.46"}, {"sp": "N", "t": "ἦν δὲ τῷ Ἀχαιίῳ συνεχὴς ἥ τε Λάρισα καὶ Κολωναί, τῆς [Τενεδίων περ]αίας οὖσαι πρότερον, καὶ ἡ νῦν Χρῦσα, ἐφ’ ὕψους τινὸς πετρώδους ὑπὲρ τῆς θαλάττης ἱδρυμένη, καὶ ἡ Ἁμαξιτὸς ἡ τῷ Λεκτῷ ὑποκειμένη συνεχής· νῦν δ’ ἡ Ἀλεξάνδρεια συνεχής ἐστι τῷ Ἀχαιίῳ· τὰ δὲ πολίσματα ἐκεῖνα συνῳκισμένα τυγχάνει, καθάπερ καὶ ἄλλα πλείω τῶν φρουρίων, εἰς τὴν Ἀλεξάνδρειαν, ὧν καὶ Κεβρήνη καὶ Νεανδρία ἐστὶ καὶ τὴν χώραν ἔχουσιν ἐκεῖνοι· ὁ δὲ τόπος ἐν ᾧ νῦν κεῖται ἡ Ἀλεξάνδρεια Σιγία ἐκαλεῖτο.", "st": "13.1.47"}, {"sp": "N", "t": "ἐν δὲ τῇ Χρύσῃ ταύτῃ καὶ τὸ τοῦ Σμινθέως Ἀπόλλωνός ἐστιν ἱερόν, καὶ τὸ σύμβολον τὸ τὴν ἐτυμότητα τοῦ ὀνόματος σῶζον, ὁ μῦς, ὑπόκειται τῷ ποδὶ τοῦ ξοάνου· Σκόπα δ’ ἐστὶν ἔργα τοῦ Παρίου· συνοικειοῦσι δὲ καὶ τὴν ἱστορίαν εἴτε μῦθον τούτῳ τῷ τόπῳ τὴν περὶ τῶν μυῶν. τοῖς γὰρ ἐκ τῆς Κρήτης ἀφιγμένοις Τεύκροις (οὓς πρῶτος παρέδωκε Καλλῖνος ὁ τῆς ἐλεγείας ποιητής, ἠκολούθησαν δὲ πολλοί) χρησμὸς ἦν, αὐτόθι ποιήσασθαι τὴν μονὴν ὅπου ἂν οἱ γηγενεῖς αὐτοῖς ἐπιθῶνται· συμβῆναι δὲ τοῦτ’ αὐτοῖς φασι περὶ Ἁμαξιτόν· νύκτωρ γὰρ πολὺ πλῆθος ἀρουραίων μυῶν ἐξανθῆσαν διαφαγεῖν ὅσα σκύτινα τῶν τε ὅπλων καὶ τῶν χρηστηρίων· τοὺς δὲ αὐτόθι μεῖναι· τούτους δὲ καὶ τὴν Ἴδην ἀπὸ τῆς ἐν Κρήτῃ προσονομάσαι. Ἡρακλείδης δ’ ὁ Ποντικὸς πληθύοντάς φησι τοὺς μύας περὶ τὸ ἱερὸν νομισθῆναί τε ἱεροὺς καὶ τὸ ξόανον οὕτω κατασκευασθῆναι βεβηκὸς ἐπὶ τῷ μυΐ. ἄλλοι δ’ ἐκ τῆς Ἀττικῆς ἀφῖχθαί τινα Τεῦκρόν φασιν ἐκ δήμου Τρώων, ὃς νῦν οἱ Ξυπετεῶνες λέγεται, Τεύκρους δὲ μηδένας ἐλθεῖν ἐκ τῆς Κρήτης. τῆς δὲ πρὸς τοὺς Ἀττικοὺς ἐπιπλοκῆς τῶν Τρώων τιθέασι σημεῖον καὶ τὸ παρ’ ἀμφοτέροις Ἐριχθόνιόν τινα γενέσθαι τῶν ἀρχηγετῶν. λέγουσι μὲν οὖν οὕτως οἱ νεώτεροι, τοῖς δ’ Ὁμήρου μᾶλλον ἔπεσι συμφωνεῖ τὰ ἐν τῷ Θήβης πεδίῳ καὶ τῇ αὐτόθι Χρύσῃ ἱδρυμένῃ ποτὲ δεικνύμενα ἴχνη, περὶ ὧν αὐτίκα ἐροῦμεν. πολλαχοῦ δ’ ἐστὶ τὸ τοῦ Σμινθέως ὄνομα· καὶ γὰρ περὶ αὐτὴν τὴν Ἁμαξιτὸν χωρὶς τοῦ κατὰ τὸ ἱερὸν Σμινθίου δύο τόποι καλοῦνται Σμίνθια· καὶ ἄλλοι δ’ ἐν τῇ πλησίον Λαρισαίᾳ· καὶ ἐν τῇ Παριανῇ δ’ ἔστι χωρίον τὰ Σμίνθια καλούμενον, καὶ ἐν Ῥόδῳ καὶ ἐν Λίνδῳ, καὶ ἄλλοθι δὲ πολλαχοῦ· καλοῦσι δὲ νῦν τὸ ἱερὸν Σμίνθιον. χωρὶς γοῦν καὶ τὸ Ἁλήσιον πεδίον οὐ μέγα ἐντὸς τοῦ Λεκτοῦ καὶ τὸ Τραγασαῖον ἁλοπήγιον αὐτόματον τοῖς ἐτησίαις πηγνύμενον πρὸς Ἁμαξιτῷ. ἐπὶ δὲ τῷ Λεκτῷ βωμὸς τῶν δώδεκα θεῶν δείκνυται, καλοῦσι δ’ Ἀγαμέμνονος ἵδρυμα· ἐν ἐπόψει δὲ τῷ Ἰλίῳ ἐστὶ τὰ χωρία ταῦτα, ὡς ἐν διακοσίοις σταδίοις ἢ μικρῷ πλείοσιν· ὡς δ’ αὕτως καὶ τὰ περὶ Ἄβυδον ἐκ θατέρου μέρους, μικρὸν δ’ ὅμως ἐγγυτέρω ἡ Ἄβυδος.", "st": "13.1.48"}, {"sp": "N", "t": "κάμψαντι δὲ τὸ Λεκτὸν ἐλλογιμώταται πόλεις τῶν Αἰολέων καὶ ὁ Ἀδραμυττηνὸς κόλπος ἐκδέχεται, ἐν ᾧ τοὺς πλείους τῶν Λελέγων κατοικίζων ὁ ποιητὴς φαίνεται καὶ τοὺς Κίλικας διττοὺς ὄντας. ἐνταῦθα δὲ καὶ ὁ τῶν Μιτυληναίων ἐστὶν αἰγιαλός, κώμας τινὰς ἔχων τῶν κατὰ τὴν ἤπειρον τῶν Μιτυληναίων. τὸν δὲ αὐτὸν κόλπον καὶ Ἰδαῖον λέγουσιν· ἡ γὰρ ἀπὸ τοῦ Λεκτοῦ ῥάχις ἀνατείνουσα πρὸς τὴν Ἴδην ὑπέρκειται τῶν πρώτων τοῦ κόλπου μερῶν, ἐν οἷς πρῶτον τοὺς Λέλεγας ἱδρυμένους ὁ ποιητὴς πεποίηκεν.", "st": "13.1.49"}, {"sp": "N", "t": "εἴρηται δὲ περὶ αὐτῶν καὶ πρότερον· καὶ νῦν δὲ προσληπτέον ὅτι Πήδασόν τινα λέγει πόλιν αὐτῶν ὑπὸ Ἄλτῃ τεταγμένην<br>Ἄλτεω, ὃς Λελέγεσσι φιλοπτολέμοισιν ἀνάσσει,<br>Πήδασον αἰπήεσσαν ἔχων ἐπὶ Σατνιόεντι.<br>καὶ νῦν ὁ τόπος δείκνυται τῆς πόλεως ἔρημος. γράφουσι δέ τινες οὐκ εὖ “ὑπὸ Σατνιόεντι,” ὡς ὑπὸ ὄρει Σατνιόεντι κειμένης τῆς πόλεως· οὐδὲν δ’ ἐστὶν ὄρος ἐνταῦθα Σατνιόεις προσαγορευόμενον, ἀλλὰ ποταμὸς ἐφ’ ᾧ ἵδρυται ἡ πόλις· νῦν δ’ ἐστὶν ἐρήμη. ὀνομάζει δὲ τὸν ποταμὸν ὁ ποιητής·<br>Σάτνιον οὔτασε δουρὶ<br>Οἰνοπίδην, ὃν ἄρα νύμφη τέκε Νηὶς ἀμύμων<br>οἴνοπι βουκολέοντι παρ’ ὄχθαις Σατνιόεντος<br>καὶ πάλιν<br>ναῖε δὲ Σατνιόεντος ἐυρρείταο παρ’ ὄχθαις<br>Πήδασον αἰπεινήν.<br>Σατνιόεντα δ’ ὕστερον εἶπον, οἱ δὲ Σαφνιόεντα· ἔστι δὲ χείμαρρος μέγας· ἄξιον δὲ μνήμης πεποίηκεν ὀνομάζων ὁ ποιητὴς αὐτόν. οὗτοι δ’ οἱ τόποι συνεχεῖς εἰσι τῇ Δαρδανίᾳ καὶ τῇ Σκηψίᾳ, ὥσπερ ἄλλη τις Δαρδανία, ταπεινοτέρα δέ.", "st": "13.1.50"}, {"sp": "N", "t": "Ἀσσίων δ’ ἐστὶ νῦν καὶ Γαργαρέων ἕως τῆς κατὰ Λέσβον θαλάττης περιεχόμενα τῇ τε Ἀντανδρίᾳ καὶ τῇ Κεβρηνίων καὶ Νεανδριέων καὶ Ἁμαξιτέων. τῆς μὲν γὰρ Ἁμαξιτοῦ Νεανδριεῖς ὑπέρκεινται, καὶ αὐτοὶ ὄντες ἐντὸς Λεκτοῦ, μεσογειότεροι δὲ καὶ πλησιαίτεροι τῷ Ἰλίῳ· διέχουσι γὰρ ἑκατὸν καὶ τριάκοντα σταδίους. τούτων δὲ καθύπερθε Κεβρήνιοι, τούτων δὲ Δαρδάνιοι μέχρι Παλαισκήψεως καὶ αὐτῆς τῆς Σκήψεως. τὴν δὲ Ἄντανδρον Ἀλκαῖος μὲν καλεῖ Λελέγων πόλιν<br>πρῶτα μὲν Ἄντανδρος Λελέγων πόλις.<br>ὁ δὲ Σκήψιος ἐν ταῖς παρακειμέναις τίθησιν, ὥστ’ ἐκπίπτοι ἂν εἰς τὴν τῶν Κιλίκων· οὗτοι γάρ εἰσι συνεχεῖς τοῖς Λέλεξι μᾶλλόν πως τὸ νότιον πλευρὸν τῆς Ἴδης ἀφορίζοντες· ταπεινοὶ δ’ ὅμως καὶ οὗτοι καὶ τῇ παραλίᾳ συνάπτοντες μᾶλλον τῇ κατὰ Ἀδραμύττιον. μετὰ γὰρ τὸ Λεκτὸν τὸ Πολυμήδειον ἔστι χωρίον τι ἐν τετταράκοντα σταδίοις, εἶτ’ ἐν ὀγδοήκοντα Ἄσσος μικρὸν ὑπὲρ τῆς θαλάττης, εἶτ’ ἐν ἑκατὸν καὶ τετταράκοντα Γάργαρα· κεῖται δὲ τὰ Γάργαρα ἐπ’ ἄκρας ποιούσης τὸν ἰδίως Ἀδραμυττηνὸν καλούμενον κόλπον. λέγεται γὰρ καὶ πᾶσα ἡ ἀπὸ Λεκτοῦ μέχρι Κανῶν παραλία τῷ αὐτῷ τούτῳ ὀνόματι, ἐν ᾧ καὶ ὁ Ἐλαϊτικὸς περιλαμβάνεται· ἰδίως μέντοι τοῦτον φασὶν Ἀδραμυττηνόν, τὸν κλειόμενον ὑπὸ ταύτης τε τῆς ἄκρας ἐφ’ ᾗ τὰ Γάργαρα, καὶ τῆς Πυρρᾶς ἄκρας προσαγορευομένης ἐφ’ ᾗ καὶ ἀφροδίσιον ἵδρυται. πλάτος δὲ τοῦ στόματός ἐστιν ἀπὸ τῆς ἄκρας ἐπὶ τὴν ἄκραν δίαρμα ἑκατὸν καὶ εἴκοσι σταδίων. ἐντὸς δὲ ἥ τε Ἄντανδρός ἐστιν ὑπερκείμενον ἔχουσα ὄρος ὃ καλοῦσιν Ἀλεξάνδρειαν, ὅπου τὰς θεὰς κριθῆναί φασιν ὑπὸ τοῦ Πάριδος, καὶ ὁ Ἀσπανεὺς τὸ ὑλοτόμιον τῆς Ἰδαίας ὕλης· ἐνταῦθα γὰρ διατίθενται κατάγοντες τοῖς δεομένοις. εἶτ’ Ἄστυρα, κώμη καὶ ἄλσος τῆς Ἀστυρηνῆς Ἀρτέμιδος ἅγιον. πλησίον δ’ εὐθὺς τὸ Ἀδραμύττιον, Ἀθηναίων ἄποικος πόλις ἔχουσα καὶ λιμένα καὶ ναύσταθμον· ἔξω δὲ τοῦ κόλπου καὶ τῆς Πυρρᾶς ἄκρας ἥ τε Κισθήνη ἐστὶ πόλις ἔρημος ἔχουσα λιμένα. ὑπὲρ αὐτῆς δ’ ἐν τῇ μεσογαίᾳ τό τε τοῦ χαλκοῦ μέταλλον καὶ Περπερηνὴ καὶ Τράριον καὶ ἄλλαι τοιαῦται κατοικίαι. ἐν δὲ τῇ παραλίᾳ τῇ ἐφεξῆς αἱ τῶν Μιτυληναίων κῶμαι Κορυφαντίς τε καὶ Ἡράκλεια, καὶ μετὰ ταῦτα Ἄττεα, εἶτ’ Ἀταρνεὺς καὶ Πιτάνη καὶ αἱ τοῦ Καΐκου ἐκβολαί· ταῦτα δ’ ἤδη τοῦ Ἐλαϊτῶν κόλπου· καὶ ἔστιν ἐν τῇ περαίᾳ ἡ Ἐλαία καὶ ὁ λοιπὸς μέχρι Κανῶν κόλπος. λέγωμεν δὲ ἀναλαβόντες περὶ τῶν καθ’ ἕκαστα πάλιν, εἴ τι παραλέλειπται μνήμης ἄξιον, καὶ πρῶτον περὶ τῆς Σκήψεως.", "st": "13.1.51"}, {"sp": "N", "t": "ἔστι δ’ ἡ μὲν Παλαίσκηψις ἐπάνω Κεβρῆνος κατὰ τὸ μετεωρότατον τῆς Ἴδης ἐγγὺς Πολίχνας· ἐκαλεῖτο δὲ τότε Σκῆψις, εἴτ’ ἄλλως εἴτ’ ἀπὸ τοῦ περίσκεπτον εἶναι τὸν τόπον, εἰ δεῖ τὰ παρὰ τοῖς βαρβάροις ἐν τῷ τότε ὀνόματα ταῖς Ἑλληνικαῖς ἐτυμολογεῖσθαι φωναῖς· ὕστερον δὲ κατωτέρω σταδίοις ἑξήκοντα εἰς τὴν νῦν Σκῆψιν μετῳκίσθησαν ὑπὸ Σκαμανδρίου τε τοῦ Ἕκτορος καὶ Ἀσκανίου τοῦ Αἰνείου παιδός· καὶ δύο γένη ταῦτα βασιλεῦσαι πολὺν χρόνον ἐν τῇ Σκήψει λέγεται· μετὰ ταῦτα δ’ εἰς ὀλιγαρχίαν μετέστησαν, εἶτα Μιλήσιοι συνεπολιτεύθησαν αὐτοῖς καὶ δημοκρατικῶς ᾤκουν· οἱ δ’ ἀπὸ τοῦ γένους οὐδὲν ἧττον ἐκαλοῦντο βασιλεῖς, ἔχοντές τινας τιμάς· εἶτ’ εἰς τὴν Ἀλεξάνδρειαν συνεπόλισε τοὺς Σκηψίους Ἀντίγονος, εἶτ’ ἀπέλυσε Λυσίμαχος, καὶ ἐπανῆλθον εἰς τὴν οἰκείαν.", "st": "13.1.52"}, {"sp": "N", "t": "οἴεται δ’ ὁ Σκήψιος καὶ βασίλειον τοῦ Αἰνείου γεγονέναι τὴν Σκῆψιν, μέσην οὖσαν τῆς τε ὑπὸ τῷ Αἰνείᾳ καὶ Λυρνησσοῦ, εἰς ἣν φυγεῖν εἴρηται διωκόμενος ὑπὸ τοῦ Ἀχιλλέως· φησὶ γοῦν ὁ Ἀχιλλεύς<br>ἢ οὐ μέμνῃ, ὅτε πέρ σε βοῶν ἄπο μοῦνον ἐόντα<br>σεῦα κατ’ Ἰδαίων ὀρέων ταχέεσσι πόδεσσι,<br>κεῖθεν δ’ ἐς Λυρνησσὸν ὑπέκφυγες· αὐτὰρ ἐγὼ τὴν<br>πέρσα, μεθορμηθείς.<br>οὐχ ὁμολογεῖ δὲ τῷ περὶ τῶν ἀρχηγετῶν τῆς Σκήψεως λόγῳ τῷ λεχθέντι νῦν τὰ περὶ τοῦ Αἰνείου θρυλούμενα. περιγενέσθαι γὰρ δὴ τοῦτόν φασιν ἐκ τοῦ πολέμου διὰ τὴν πρὸς Πρίαμον δυσμένειαν·<br>ἀεὶ γὰρ Πριάμῳ ἐπεμήνιε δίῳ,<br>οὕνεκ’ ἄρ’ ἐσθλὸν ἐόντα μετ’ ἀνδράσιν οὔ τι τίεσκε,<br>τοὺς δὲ συνάρχοντας Ἀντηνορίδας καὶ αὐτὸν τὸν Ἀντήνορα διὰ τὴν Μενελάου παρ’ αὐτῷ ξενίαν. Σοφοκλῆς γοῦν ἐν τῇ ἁλώσει τοῦ Ἰλίου παρδαλέαν φησὶ πρὸ τῆς θύρας τοῦ Ἀντήνορος προτεθῆναι σύμβολον τοῦ ἀπόρθητον ἐαθῆναι τὴν οἰκίαν. τὸν μὲν οὖν Ἀντήνορα καὶ τοὺς παῖδας μετὰ τῶν περιγενομένων Ἑνετῶν εἰς τὴν Θρᾴκην περισωθῆναι κἀκεῖθεν διαπεσεῖν εἰς τὴν λεγομένην κατὰ τὸν Ἀδρίαν Ἑνετικήν, τὸν δὲ Αἰνείαν μετ’ Ἀγχίσου τοῦ πατρὸς καὶ τοῦ παιδὸς Ἀσκανίου λαὸν ἀθροίσαντα πλεῦσαι· καὶ οἱ μὲν οἰκῆσαι περὶ τὸν Μακεδονικὸν Ὄλυμπον φασίν, οἱ δὲ περὶ Μαντίνειαν τῆς Ἀρκαδίας κτίσαι Καπύας, ἀπὸ Κάπυος θέμενον τοὔνομα τῷ πολίσματι, οἱ δ’ εἰς Αἴγεσταν κατᾶραι τῆς Σικελίας σὺν Ἐλύμῳ Τρωὶ καὶ Ἔρυκα καὶ Λιλύβαιον κατασχεῖν, καὶ ποταμοὺς περὶ Αἴγεσταν προσαγορεῦσαι Σκάμανδρον καὶ Σιμόεντα· ἔνθεν δ’ εἰς τὴν Λατίνην ἐλθόντα μεῖναι κατά τι λόγιον τὸ κελεῦον μένειν ὅπου ἂν τὴν τράπεζαν καταφάγῃ· συμβῆναι δὲ τῆς Λατίνης περὶ τὸ Λαουίνιον τοῦτο, ἄρτου μεγάλου τεθέντος ἀντὶ τραπέζης κατὰ ἀπορίαν καὶ ἅμα ἀναλωθέντος τοῖς ἐπ’ αὐτῷ κρέασιν. Ὅμηρος μέντοι συνηγορεῖν οὐδετέροις ἔοικεν, οὐδὲ τοῖς περὶ τῶν ἀρχηγετῶν τῆς Σκήψεως λεχθεῖσιν· ἐμφαίνει γὰρ μεμενηκότα τὸν Αἰνείαν ἐν τῇ Τροίᾳ καὶ διαδεδεγμένον τὴν ἀρχὴν καὶ παραδεδωκότα παισὶ παίδων τὴν διαδοχὴν αὐτῆς, ἠφανισμένου τοῦ τῶν Πριαμιδῶν γένους·<br>ἤδη γὰρ Πριάμου γενεὴν ἤχθηρε Κρονίων.<br>νῦν δὲ δὴ Αἰνείαο βίη Τρώεσσιν ἀνάξει<br>καὶ παίδων παῖδες, τοί κεν μετόπισθε γένωνται.<br>οὕτω δ’ οὐδ’ ἡ τοῦ Σκαμανδρίου διαδοχὴ σώζοιτ’ ἄν. πολὺ δὲ μᾶλλον τοῖς ἑτέροις διαφωνεῖ τοῖς μέχρι καὶ Ἰταλίας αὐτοῦ τὴν πλάνην λέγουσι καὶ αὐτόθι ποιοῦσι τὴν καταστροφὴν τοῦ βίου. τινὲς δὲ γράφουσιν<br>Αἰνείαο γένος πάντεσσιν ἀνάξει,<br>καὶ παῖδες παίδων,<br>τοὺς Ῥωμαίους λέγοντες.", "st": "13.1.53"}, {"sp": "N", "t": "ἐκ δὲ τῆς Σκήψεως οἵ τε Σωκρατικοὶ γεγόνασιν Ἔραστος καὶ Κορίσκος καὶ ὁ τοῦ Κορίσκου υἱὸς Νηλεύς, ἀνὴρ καὶ Ἀριστοτέλους ἠκροαμένος καὶ Θεοφράστου, διαδεδεγμένος δὲ τὴν βιβλιοθήκην τοῦ Θεοφράστου, ἐν ᾗ ἦν καὶ ἡ τοῦ Ἀριστοτέλους· ὁ γοῦν Ἀριστοτέλης τὴν ἑαυτοῦ Θεοφράστῳ παρέδωκεν, ᾧπερ καὶ τὴν σχολὴν ἀπέλιπε, πρῶτος ὧν ἴσμεν συναγαγὼν βιβλία καὶ διδάξας τοὺς ἐν Αἰγύπτῳ βασιλέας βιβλιοθήκης σύνταξιν. Θεόφραστος δὲ Νηλεῖ παρέδωκεν· ὁ δ’ εἰς Σκῆψιν κομίσας τοῖς μετ’ αὐτὸν παρέδωκεν, ἰδιώταις ἀνθρώποις, οἳ κατάκλειστα εἶχον τὰ βιβλία οὐδ’ ἐπιμελῶς κείμενα· ἐπειδὴ δὲ ᾔσθοντο τὴν σπουδὴν τῶν Ἀτταλικῶν βασιλέων ὑφ’ οἷς ἦν ἡ πόλις, ζητούντων βιβλία εἰς τὴν κατασκευὴν τῆς ἐν Περγάμῳ βιβλιοθήκης, κατὰ γῆς ἔκρυψαν ἐν διώρυγί τινι· ὑπὸ δὲ νοτίας καὶ σητῶν κακωθέντα ὀψέ ποτε ἀπέδοντο οἱ ἀπὸ τοῦ γένους Ἀπελλικῶντι τῷ Τηίῳ πολλῶν ἀργυρίων τά τε Ἀριστοτέλους καὶ τὰ τοῦ Θεοφράστου βιβλία· ἦν δὲ ὁ Ἀπελλικῶν φιλόβιβλος μᾶλλον ἢ φιλόσοφος· διὸ καὶ ζητῶν ἐπανόρθωσιν τῶν διαβρωμάτων εἰς ἀντίγραφα καινὰ μετήνεγκε τὴν γραφὴν ἀναπληρῶν οὐκ εὖ, καὶ ἐξέδωκεν ἁμαρτάδων πλήρη τὰ βιβλία. συνέβη δὲ τοῖς ἐκ τῶν περιπάτων τοῖς μὲν πάλαι τοῖς μετὰ Θεόφραστον οὐκ ἔχουσιν ὅλως τὰ βιβλία πλὴν ὀλίγων, καὶ μάλιστα τῶν ἐξωτερικῶν, μηδὲν ἔχειν φιλοσοφεῖν πραγματικῶς, ἀλλὰ θέσεις ληκυθίζειν· τοῖς δ’ ὕστερον, ἀφ’ οὗ τὰ βιβλία ταῦτα προῆλθεν, ἄμεινον μὲν ἐκείνων φιλοσοφεῖν καὶ ἀριστοτελίζειν, ἀναγκάζεσθαι μέντοι τὰ πολλὰ εἰκότα λέγειν διὰ τὸ πλῆθος τῶν ἁμαρτιῶν. πολὺ δὲ εἰς τοῦτο καὶ ἡ Ῥώμη προσελάβετο· εὐθὺς γὰρ μετὰ τὴν Ἀπελλικῶντος τελευτὴν Σύλλας ἦρε τὴν Ἀπελλικῶντος βιβλιοθήκην ὁ τὰς Ἀθήνας ἑλών, δεῦρο δὲ κομισθεῖσαν Τυραννίων τε ὁ γραμματικὸς διεχειρίσατο φιλαριστοτέλης ὤν, θεραπεύσας τὸν ἐπὶ τῆς βιβλιοθήκης, καὶ βιβλιοπῶλαί τινες γραφεῦσι φαύλοις χρώμενοι καὶ οὐκ ἀντιβάλλοντες, ὅπερ καὶ ἐπὶ τῶν ἄλλων συμβαίνει τῶν εἰς πρᾶσιν γραφομένων βιβλίων καὶ ἐνθάδε καὶ ἐν Ἀλεξανδρείᾳ. περὶ μὲν οὖν τούτων ἀπόχρη.", "st": "13.1.54"}, {"sp": "N", "t": "ἐκ δὲ τῆς Σκήψεως καὶ ὁ Δημήτριος ἔστιν οὗ μεμνήμεθα πολλάκις, ὁ τὸν Τρωικὸν διάκοσμον ἐξηγησάμενος γραμματικός, κατὰ τὸν αὐτὸν χρόνον γεγονὼς Κράτητι καὶ Ἀριστάρχῳ· καὶ μετὰ τοῦτον Μητρόδωρος, ἀνὴρ ἐκ τοῦ φιλοσόφου μεταβεβληκὼς ἐπὶ τὸν πολιτικὸν βίον καὶ ῥητορεύων τὸ πλέον ἐν τοῖς συγγράμμασιν· ἐχρήσατο δὲ φράσεώς τινι χαρακτῆρι καινῷ καὶ κατεπλήξατο πολλούς· διὰ δὲ τὴν δόξαν ἐν Χαλκηδόνι γάμου λαμπροῦ πένης ὢν ἔτυχε καὶ ἐχρημάτιζε Χαλκηδόνιος· Μιθριδάτην δὲ θεραπεύσας τὸν Εὐπάτορα συναπῆρεν εἰς τὸν Πόντον ἐκείνῳ μετὰ τῆς γυναικὸς καὶ ἐτιμήθη διαφερόντως, ταχθεὶς ἐπὶ τῆς δικαιοδοσίας, ἀφ’ ἧς οὐκ ἦν τῷ κριθέντι ἀναβολὴ τῆς δίκης ἐπὶ τὸν βασιλέα. οὐ μέντοι διηυτύχησεν, ἀλλ’ ἐμπεσὼν εἰς ἔχθραν ἀδικωτέρων ἀνθρώπων ἀπέστη τοῦ βασιλέως κατὰ τὴν πρὸς Τιγράνην τὸν Ἀρμένιον πρεσβείαν· ὁ δ’ ἄκοντα ἀνέπεμψεν αὐτὸν τῷ Εὐπάτορι, φεύγοντι ἤδη τὴν προγονικήν, κατὰ δὲ τὴν ὁδὸν κατέστρεψε τὸν βίον εἴθ’ ὑπὸ τοῦ βασιλέως εἴθ’ ὑπὸ νόσου· λέγεται γὰρ ἀμφότερα. περὶ μὲν τῶν Σκηψίων ταῦτα.", "st": "13.1.55"}, {"sp": "N", "t": "μετὰ δὲ Σκῆψιν Ἄνδειρα καὶ Πιονίαι καὶ ἡ Γαργαρίς. ἔστι δὲ λίθος περὶ τὰ Ἄνδειρα, ὃς καιόμενος σίδηρος γίνεται· εἶτα μετὰ γῆς τινος καμινευθεὶς ἀποστάζει ψευδάργυρον, ἣ προσλαβοῦσα χαλκὸν τὸ καλούμενον γίνεται κρᾶμα, ὅ τινες ὀρείχαλκον καλοῦσι· γίνεται δὲ ψευδάργυρος καὶ περὶ τὸν Τμῶλον. ταῦτα δ’ ἐστὶ τὰ χωρία, ἃ οἱ Λέλεγες κατεῖχον· ὡς δ’ αὕτως καὶ τὰ περὶ Ἄσσον.", "st": "13.1.56"}, {"sp": "N", "t": "ἔστι δὲ ἡ Ἄσσος ἐρυμνὴ καὶ εὐτειχής, ἀπὸ θαλάττης καὶ τοῦ λιμένος ὀρθίαν καὶ μακρὰν ἀνάβασιν ἔχουσα, ὥστ’ ἐπ’ αὐτῆς οἰκείως εἰρῆσθαι δοκεῖ τὸ τοῦ Στρατονίκου τοῦ κιθαριστοῦ<br>Ἄσσον ἴθ’, ὥς κεν θᾶσσον ὀλέθρου πείραθ’ ἵκηαι.<br>ὁ δὲ λιμὴν χώματι κατεσκεύασται μεγάλῳ. ἐντεῦθεν ἦν Κλεάνθης, ὁ στωικὸς φιλόσοφος, ὁ διαδεξάμενος τὴν Ζήνωνος τοῦ Κιτιέως σχολήν, καταλιπὼν δὲ Χρυσίππῳ τῷ Σολεῖ· ἐνταῦθα δὲ καὶ Ἀριστοτέλης διέτριψε διὰ τὴν πρὸς Ἑρμείαν τὸν τύραννον κηδείαν. ἦν δὲ Ἑρμείας εὐνοῦχος, τραπεζίτου τινὸς οἰκέτης· γενόμενος δ’ Ἀθήνησιν ἠκροάσατο καὶ Πλάτωνος καὶ Ἀριστοτέλους· ἐπανελθὼν δὲ τῷ δεσπότῃ συνετυράννησε, πρῶτον ἐπιθεμένῳ τοῖς περὶ Ἀταρνέα καὶ Ἄσσον χωρίοις· ἔπειτα διεδέξατο ἐκεῖνον καὶ μετεπέμψατο τόν τε Ἀριστοτέλην καὶ Ξενοκράτην καὶ ἐπεμελήθη αὐτῶν, τῷ δ’ Ἀριστοτέλει καὶ θυγατέρα ἀδελφοῦ συνῴκισε. Μέμνων δ’ ὁ Ῥόδιος ὑπηρετῶν τότε τοῖς Πέρσαις καὶ στρατηγῶν, προσποιησάμενος φιλίαν καλεῖ πρὸς ἑαυτὸν ξενίας τε ἅμα καὶ πραγμάτων προσποιητῶν χάριν, συλλαβὼν δ’ ἀνέπεμψεν ὡς τὸν βασιλέα, κἀκεῖ κρεμασθεὶς ἀπώλετο· οἱ φιλόσοφοι δ’ ἐσώθησαν φεύγοντες τὰ χωρία ἃ οἱ Πέρσαι κατέσχον.", "st": "13.1.57"}, {"sp": "N", "t": "φησὶ δὲ Μυρσίλος Μηθυμναίων κτίσμα εἶναι τὴν Ἄσσον, Ἑλλάνικός τε καὶ Αἰολίδα φησίν, ὥσπερ καὶ τὰ Γάργαρα καὶ ἡ Λαμπωνία Αἰολέων. Ἀσσίων γάρ ἐστι κτίσμα τὰ Γάργαρα, οὐκ εὖ συνοικούμενα· ἐποίκους γὰρ οἱ βασιλεῖς εἰσήγαγον ἐκ Μιλητουπόλεως ἐρημώσαντες ἐκείνην, ὥστε ἡμιβαρβάρους γενέσθαι φησὶ Δημήτριος αὐτοὺς ὁ Σκήψιος ἀντὶ Αἰολέων. καθ’ Ὅμηρον μέντοι ταῦτα πάντα ἦν Λελέγων, οὓς τινὲς μὲν Κᾶρας ἀποφαίνουσιν, Ὅμηρος δὲ χωρίζει<br>πρὸς μὲν ἁλὸς Κᾶρες καὶ Παίονες ἀγκυλότοξοι<br>καὶ Λέλεγες καὶ Καύκωνες.<br>ἕτεροι μὲν τοίνυν τῶν Καρῶν ὑπῆρξαν, ᾤκουν δὲ μεταξὺ τῶν ὑπὸ τῷ Αἰνείᾳ καὶ τῶν καλουμένων ὑπὸ τοῦ ποιητοῦ Κιλίκων· ἐκπορθηθέντες δὲ ὑπὸ τοῦ Ἀχιλλέως μετέστησαν εἰς τὴν Καρίαν, καὶ κατέσχον τὰ περὶ τὴν νῦν Ἁλικαρνασὸν χωρία.", "st": "13.1.58"}, {"sp": "N", "t": "ἡ μὲν τοίνυν ἐκλειφθεῖσα ὑπ’ αὐτῶν πόλις Πήδασος οὐκέτ’ ἐστίν, ἐν δὲ τῇ μεσογαίᾳ τῶν Ἁλικαρνασέων τὰ Πήδασα ὑπ’ αὐτῶν ὀνομασθέντα ἦν πόλις, καὶ νῦν ἡ χώρα Πηδασὶς λέγεται. φασὶ δ’ ἐν αὐτῇ καὶ ὀκτὼ πόλεις ᾠκίσθαι ὑπὸ τῶν Λελέγων πρότερον εὐανδρησάντων, ὥστε καὶ τῆς Καρίας κατασχεῖν τῆς μέχρι Μύνδου καὶ Βαργυλίων, καὶ τῆς Πισιδίας ἀποτεμέσθαι πολλήν. ὕστερον δ’ ἅμα τοῖς Καρσὶ στρατευόμενοι κατεμερίσθησαν εἰς ὅλην τὴν Ἑλλάδα καὶ ἠφανίσθη τὸ γένος, τῶν δ’ ὀκτὼ πόλεων τὰς ἓξ Μαύσωλος εἰς μίαν τὴν Ἁλικαρνασὸν συνήγαγεν, ὡς Καλλισθένης ἱστορεῖ· Συάγγελα δὲ καὶ Μύνδον διεφύλαξε. τοῖς δὲ Πηδασεῦσι τούτοις φησὶν Ἡρόδοτος ὅτε μέλλοι τι ἀνεπιτήδειον ἔσεσθαι καὶ τοῖς περιοίκοις, τὴν ἱέρειαν τῆς Ἀθηνᾶς πώγωνα ἴσχειν· τρὶς δὲ συμβῆναι τοῦτο αὐτοῖς. Πήδασον δὲ καὶ ἐν τῇ νῦν Στρατονικέων πολίχνιόν ἐστιν. ἐν ὅλῃ δὲ Καρίᾳ καὶ ἐν Μιλήτῳ Λελέγων τάφοι καὶ ἐρύματα καὶ ἴχνη κατοικιῶν δείκνυται.", "st": "13.1.59"}, {"sp": "N", "t": "μετὰ δὲ τοὺς Λέλεγας τὴν ἑξῆς παραλίαν ᾤκουν Κίλικες καθ’ Ὅμηρον, ἣν νῦν ἔχουσιν Ἀδραμυττηνοί τε καὶ Ἀταρνεῖται καὶ Πιταναῖοι μέχρι τῆς ἐκβολῆς τοῦ Καΐκου. διῄρηντο δ’ εἰς δύο δυναστείας οἱ Κίλικες, καθάπερ εἴπομεν, τήν τε ὑπὸ τῷ Ἠετίωνι καὶ τὴν ὑπὸ Μύνητι.", "st": "13.1.60"}, {"sp": "N", "t": "τοῦ μὲν οὖν Ἠετίωνος λέγει πόλιν Θήβην<br>ᾠχόμεθ’ ἐς Θήβην ἱερὴν πόλιν Ἠετίωνος<br>τούτου δὲ καὶ τὴν Χρῦσαν [τὴν ἔχουσαν] τὸ ἱερὸν τοῦ Σμινθέως Ἀπόλλωνος ἐμφαίνει, εἴπερ ἡ Χρυσηὶς ἐκ τῆς Θήβης ἑάλω· “ᾠχόμεθα” γάρ, φησίν,<br>ἐς Θήβην·<br>τὴν δὲ διεπράθομέν τε καὶ ἤγομεν ἐνθάδε πάντα.<br>καὶ τὰ μὲν εὖ δάσσαντο μετὰ σφίσιν [υἷες Ἀχαιῶν],<br>ἐκ δ’ ἕλον Ἀτρείδῃ Χρυσηίδα.<br>τοῦ δὲ Μύνητος τὴν Λυρνησσόν· ἐπειδὴ<br>Λυρνησσὸν διαπορθήσας καὶ τείχεα Θήβης<br>τόν τε Μύνητα καὶ τὸν Ἐπίστροφον ἀνεῖλεν Ἀχιλλεύς, ὥστε ὅταν φῇ ἡ Βρισηίς<br>οὐδέ μ’ ἔασκες, ὅτ’ ἄνδρ’ ἐμὸν ὠκὺς Ἀχιλλεὺς<br>ἔκτεινεν, πέρσεν δὲ πόλιν θείοιο Μύνητος,<br>οὐ τὴν Θήβην λέγοι ἄν (αὕτη γὰρ Ἠετίωνος) ἀλλὰ τὴν Λυρνησσόν· ἀμφότεραι δ’ ἦσαν ἐν τῷ κληθέντι μετὰ ταῦτα Θήβης πεδίῳ, ὃ διὰ τὴν ἀρετὴν περιμάχητον γενέσθαι φασὶ Μυσοῖς μὲν καὶ Λυδοῖς τὸ πρότερον, τοῖς δ’ Ἕλλησιν ὕστερον τοῖς ἐποικήσασιν ἐκ τῆς Αἰολίδος καὶ τῆς Λέσβου. ἔχουσι δὲ νῦν Ἀδραμυττηνοὶ τὸ πλέον· ἐνταῦθα γὰρ καὶ ἡ Θήβη καὶ ἡ Λυρνησσός, ἐρυμνὸν χωρίον· ἔρημοι δ’ ἀμφότεραι· διέχουσι δὲ Ἀδραμυττίου σταδίους ἡ μὲν ἑξήκοντα ἡ δὲ ὀγδοήκοντα καὶ ὀκτὼ ἐπὶ θάτερα.", "st": "13.1.61"}, {"sp": "N", "t": "ἐν δὲ τῇ Ἀδραμυττηνῇ ἔστι καὶ ἡ Χρῦσα καὶ ἡ Κίλλα· πλησίον οὖν τῆς Θήβης ἔτι νῦν Κίλλα τις τόπος λέγεται, ἐν ᾧ Κιλλαίου Ἀπόλλωνος ἔστιν ἱερόν· παραρρεῖ δ’ αὐτῷ ἐξ Ἴδης φερόμενος ὁ Κίλλαιος ποταμός· ταῦτα δ’ ἐστὶ κατὰ τὴν Ἀντανδρίαν· καὶ τὸ ἐν Λέσβῳ δὲ Κίλλαιον ἀπὸ ταύτης τῆς Κίλλης ὠνόμασται· ἔστι δὲ καὶ Κίλλαιον ὄρος μεταξὺ Γαργάρων καὶ Ἀντάνδρου. φησὶ δὲ Δάης ὁ Κολωναεὺς ἐν Κολωναῖς ἱδρυθῆναι πρῶτον ὑπὸ τῶν ἐκ τῆς Ἑλλάδος πλευσάντων Αἰολέων τὸ τοῦ Κιλλαίου Ἀπόλλωνος ἱερόν· καὶ ἐν Χρύσῃ δὲ λέγουσι Κίλλαιον Ἀπόλλωνα ἱδρῦσθαι, ἄδηλον εἴτε τὸν αὐτὸν τῷ Σμινθεῖ εἴθ’ ἕτερον.", "st": "13.1.62"}, {"sp": "N", "t": "ἡ δὲ Χρῦσα ἐπὶ θαλάττῃ πολίχνιον ἦν ἔχον λιμένα, πλησίον δὲ ὑπέρκειται ἡ Θήβη· ἐνταῦθα δ’ ἦν καὶ τὸ ἱερὸν τοῦ Σμινθέως Ἀπόλλωνος καὶ ἡ Χρυσηίς· ἠρήμωται δὲ νῦν τὸ χωρίον τελέως· εἰς δὲ τὴν νῦν Χρῦσαν τὴν κατὰ Ἁμαξιτὸν μεθίδρυται τὸ ἱερόν, τῶν Κιλίκων τῶν μὲν εἰς τὴν Παμφυλίαν ἐκπεσόντων τῶν δὲ εἰς Ἁμαξιτόν. οἱ δ’ ἀπειρότεροι τῶν παλαιῶν ἱστοριῶν ἐνταῦθα τὸν Χρύσην καὶ τὴν Χρυσηίδα γεγονέναι φασὶ καὶ τὸν Ὅμηρον τούτου τοῦ τόπου μεμνῆσθαι. ἀλλ’ οὔτε λιμήν ἐστιν ἐνταῦθα, ἐκεῖνος δέ φησιν<br>οἱ δ’ ὅτε δὴ λιμένος πολυβενθέος ἐντὸς ἵκοντο,<br>οὔτ’ ἐπὶ θαλάττῃ τὸ ἱερόν ἐστιν, ἐκεῖνος δ’ ἐπὶ θαλάττῃ ποιεῖ τὸ ἱερόν<br>ἐκ δὲ Χρυσηὶς νηὸς βῆ ποντοπόροιο·<br>τὴν μὲν ἔπειτ’ ἐπὶ βωμὸν ἄγων πολύμητις Ὀδυσσεὺς<br>πατρὶ φίλῳ ἐν χερσὶ τίθει<br>οὔτε Θήβης πλησίον, ἐκεῖνος δὲ πλησίον· ἐκεῖθεν γοῦν ἁλοῦσαν λέγει τὴν Χρυσηίδα. ἀλλ’ οὐδὲ Κίλλα τόπος οὐδεὶς ἐν τῇ Ἀλεξανδρέων χώρᾳ δείκνυται, οὐδὲ Κιλλαίου Ἀπόλλωνος ἱερόν· ὁ ποιητὴς δὲ συζεύγνυσιν<br>ὃς Χρύσην ἀμφιβέβηκας<br>Κίλλαν τε ζαθέην<br>ἐν δὲ τῷ Θήβης πεδίῳ δείκνυται πλησίον· ὅ τε πλοῦς ἀπὸ μὲν τῆς Κιλικίου Χρύσης ἐπὶ τὸ ναύσταθμον ἑπτακοσίων που σταδίων ἐστὶν ἡμερήσιός πως, ὅσον φαίνεται πλεύσας ὁ Ὀδυσσεύς. ἐκβὰς γὰρ εὐθὺς παρίστησι τὴν θυσίαν τῷ θεῷ καὶ τῆς ἑσπέρας ἐπιλαβούσης μένει αὐτόθι, πρωὶ δὲ ἀποπλεῖ· ἀπὸ δὲ Ἁμαξιτοῦ τὸ τρίτον μόλις τοῦ λεχθέντος διαστήματός ἐστιν, ὥστε παρῆν τῷ Ὀδυσσεῖ αὐθημερὸν ἀναπλεῖν ἐπὶ τὸ ναύσταθμον τελέσαντι τὴν θυσίαν. ἔστι δὲ καὶ Κίλλου μνῆμα περὶ τὸ ἱερὸν τοῦ Κιλλαίου Ἀπόλλωνος, χῶμα μέγα· ἡνίοχον δὲ τοῦτον Πέλοπός φασιν ἡγησάμενον τῶν τόπων, ἀφ’ οὗ ἴσως ἡ Κιλικία ἢ ἔμπαλιν.", "st": "13.1.63"}, {"sp": "N", "t": "τὰ οὖν περὶ τοὺς Τεύκρους καὶ τοὺς μύας, ἀφ’ ὧν ὁ Σμινθεύς, ἐπειδὴ σμίνθοι οἱ μύες, δεῦρο μετενεκτέον. παραμυθοῦνται δὲ τὴν ἀπὸ μικρῶν ἐπίκλησιν τοιούτοις τισί· καὶ γὰρ ἀπὸ τῶν παρνόπων, οὓς οἱ Οἰταῖοι κόρνοπας λέγουσι, Κορνοπίωνα τιμᾶσθαι παρ’ ἐκείνοις Ἡρακλέα ἀπαλλαγῆς ἀκρίδων χάριν· ἰποκτόνον δὲ παρ’ Ἐρυθραίοις τοῖς τὸν Μίμαντα οἰκοῦσιν, ὅτι φθαρτικὸς τῶν ἀμπελοφάγων ἰπῶν· καὶ δὴ παρ’ ἐκείνοις μόνοις τῶν Ἐρυθραίων τὸ θηρίον τοῦτο μὴ γίνεσθαι. Ῥόδιοι δὲ ἐρυθιβίου Ἀπόλλωνος ἔχουσιν ἐν τῇ χώρᾳ ἱερόν, τὴν ἐρυσίβην καλοῦντες ἐρυθίβην· παρ’ Αἰολεῦσι δὲ τοῖς ἐν Ἀσίᾳ μείς τις καλεῖται Πορνοπίων, οὕτω τοὺς πάρνοπας καλούντων Βοιωτῶν, καὶ θυσία συντελεῖται Πορνοπίωνι Ἀπόλλωνι.", "st": "13.1.64"}, {"sp": "N", "t": "Μυσία μὲν οὖν ἔστιν ἡ περὶ τὸ Ἀδραμύττιον· ἦν δέ ποτε ὑπὸ Λυδοῖς, καὶ νῦν πύλαι Λύδιαι καλοῦνται ἐν Ἀδραμυττίῳ, Λυδῶν (ὥς φασι) τὴν πόλιν ἐκτικότων. Μυσίας δὲ [καὶ] Ἄστυρα τὴν πλησίον κώμην φασίν. ἦν δὲ πολίχνη ποτέ, ἐν ᾗ τὸ τῆς Ἀστυρηνῆς Ἀρτέμιδος ἱερὸν ἐν ἄλσει, προστατούμενον μετὰ ἁγιστείας ὑπ’ Ἀντανδρίων, οἷς μᾶλλον γειτνιᾷ· διέχει δὲ τῆς παλαιᾶς Χρύσης εἴκοσι σταδίους, καὶ αὐτῆς ἐν ἄλσει τὸ ἱερὸν ἐχούσης. αὐτοῦ δὲ καὶ ὁ Ἀχίλλειος χάραξ· ἐν δὲ τῇ μεσογαίᾳ ἀπὸ πεντήκοντα σταδίων ἐστὶν ἡ Θήβη ἔρημος, ἥν φησιν ὁ ποιητής “ὑπὸ Πλάκῳ ὑληέσσῃ.” οὔτε δὲ Πλάκος ἢ Πλὰξ ἐκεῖ τι λέγεται, οὔθ’ ὕλη ὑπέρκειται καίτοι πρὸς τῇ Ἴδῃ. Ἀστύρων δ’ ἡ Θήβη διέχει εἰς ἑβδομήκοντα σταδίους, Ἀνδείρων δὲ ἑξήκοντα. πάντα δὲ ταῦτά ἐστι τὰ ὀνόματα τόπων ἐρήμων ἢ φαύλως οἰκουμένων ἢ ποταμῶν χειμάρρων· τεθρύληται δὲ διὰ τὰς παλαιὰς ἱστορίας.", "st": "13.1.65"}, {"sp": "N", "t": "πόλεις δ’ εἰσὶν ἀξιόλογοι Ἄσσος τε καὶ Ἀδραμύττιον. ἠτύχησε δὲ τὸ Ἀδραμύττιον ἐν τῷ Μιθριδατικῷ πολέμῳ· τὴν γὰρ βουλὴν ἀπέσφαξε τῶν πολιτῶν Διόδωρος στρατηγὸς χαριζόμενος τῷ βασιλεῖ, προσποιούμενος δ’ ἅμα τῶν τε ἐξ Ἀκαδημίας φιλοσόφων εἶναι καὶ δίκας λέγειν καὶ σοφιστεύειν τὰ ῥητορικά· καὶ δὴ καὶ συναπῆρεν εἰς τὸν Πόντον τῷ βασιλεῖ· καταλυθέντος δὲ τοῦ βασιλέως ἔτισε δίκας τοῖς ἀδικηθεῖσιν· ἐγκλημάτων γὰρ ἐπενεχθέντων ἅμα πολλῶν, ἀπεκαρτέρησεν αἰσχρῶς οὐ φέρων τὴν δυσφημίαν ἐν τῇ ἡμετέρᾳ πόλει. ἀνὴρ δὲ Ἀδραμυττηνὸς ῥήτωρ ἐπιφανὴς γεγένηται Ξενοκλῆς, τοῦ μὲν Ἀσιανοῦ χαρακτῆρος, ἀγωνιστὴς δὲ εἴ τις ἄλλος καὶ εἰρηκὼς ὑπὲρ τῆς Ἀσίας ἐπὶ τῆς συγκλήτου καθ’ ὃν καιρὸν αἰτίαν εἶχε Μιθριδατισμοῦ.", "st": "13.1.66"}, {"sp": "N", "t": "πρὸς δὲ τοῖς Ἀστύροις λίμνη καλεῖται Σάπρα βαραθρώδης εἰς ῥαχιώδη τῆς θαλάττης αἰγιαλὸν τὸ ἔκρηγμα ἔχουσα. ὑπὸ δὲ τοῖς Ἀνδείροις ἱερόν ἐστι μητρὸς θεῶν Ἀνδειρηνῆς ἅγιον καὶ ἄντρον ὑπόνομον μέχρι Παλαιᾶς. ἔστι δ’ ἡ Παλαιὰ κατοικία τις οὕτω καλουμένη, διέχουσα τῶν Ἀνδείρων ἑκατὸν καὶ τριάκοντα σταδίους· ἔδειξε δὲ τὴν ὑπονομὴν χίμαρος ἐμπεσὼν εἰς τὸ στόμα καὶ ἀνευρεθεὶς τῇ ὑστεραίᾳ κατὰ Ἄνδειρα ὑπὸ τοῦ ποιμένος κατὰ τύχην ἐπὶ θυσίαν ἥκοντος. Ἀταρνεὺς δ’ ἐστὶ τὸ τοῦ Ἑρμείου τυραννεῖον, εἶτα Πιτάνη πόλις Αἰολική, δύο ἔχουσα λιμένας, καὶ ὁ παραρρέων αὐτὴν ποταμὸς Εὔηνος, ἐξ οὗ τὸ ὑδραγωγεῖον πεποίηται τοῖς Ἀδραμυττηνοῖς. ἐκ δὲ τῆς Πιτάνης ἐστὶν Ἀρκεσίλαος ὁ ἐκ τῆς Ἀκαδημίας, Ζήνωνος τοῦ Κιτιέως συσχολαστὴς παρὰ Πολέμωνι. καλεῖται δὲ καὶ ἐν τῇ Πιτάνῃ τις τόπος ἐπὶ θαλάττῃ Ἀταρνεὺς ὑπὸ τῇ Πιτάνῃ κατὰ τὴν καλουμένην νῆσον Ἐλαιοῦσσαν. φασὶ δ’ ἐν τῇ Πιτάνῃ τὰς πλίνθους ἐπιπολάζειν ἐν τοῖς ὕδασι, καθάπερ καὶ ἐν τῇ Τυρρηνίᾳ νησὶς πέπονθε· κουφοτέρα γὰρ ἡ γῆ τοῦ ἐπισόγκου ὕδατός ἐστιν ὥστ’ ἐποχεῖσθαι. ἐν Ἰβηρίᾳ δέ φησιν ἰδεῖν Ποσειδώνιος ἐκ τινος γῆς ἀργιλώδους, ᾗ τὰ ἀργυρώματα ἐκμάττεται, πλίνθους πηγνυμένας καὶ ἐπιπλεούσας. μετὰ δὲ τὴν Πιτάνην ὁ Κάικος εἰς τὸν Ἐλαΐτην καλούμενον κόλπον ἐν τριάκοντα σταδίοις ἐκδίδωσιν. ἐν δὲ τῷ πέραν τοῦ Καΐκου δώδεκα διέχουσα τοῦ ποταμοῦ σταδίους Ἐλαία πόλις Αἰολικὴ καὶ αὕτη, Περγαμηνῶν ἐπίνειον, ἑκατὸν καὶ εἴκοσι σταδίους διέχουσα τοῦ Περγάμου.", "st": "13.1.67"}, {"sp": "N", "t": "εἶτ’ ἐν ἑκατὸν σταδίοις ἡ Κάνη, τὸ ἀνταῖρον ἀκρωτήριον τῷ Λεκτῷ καὶ ποιοῦν τὸν Ἀδραμυττηνὸν κόλπον, οὗ μέρος καὶ ὁ Ἐλαϊτικός ἐστι. Κάναι δὲ πολίχνιον Λοκρῶν τῶν ἐκ Κύνου κατὰ τὰ ἄκρα τῆς Λέσβου τὰ νοτιώτατα κείμενον ἐν τῇ Καναίᾳ· αὕτη δὲ μέχρι τῶν Ἀργινουσσῶν διήκει καὶ τῆς ὑπερκειμένης ἄκρας, ἣν Αἶγά τινες ὀνομάζουσιν ὁμωνύμως τῷ ζῴῳ. δεῖ δὲ μακρῶς τὴν δευτέραν συλλαβὴν ἐκφέρειν Αἰγάν, ὡς ἀκτὰν καὶ ἀρχάν· οὕτω γὰρ καὶ τὸ ὄρος ὅλον ὠνομάζετο, ὃ νῦν Κάνην καὶ Κάνας λέγουσι. κύκλῳ δὲ περὶ τὸ ὄρος πρὸς νότον μὲν καὶ δύσιν ἡ θάλαττα, πρὸς ἕω δὲ τὸ Καΐκου πεδίον ὑπόκειται, πρὸς ἄρκτον δὲ ἡ Ἐλαῗτις· αὐτὸ δὲ καθ’ αὑτὸ ἱκανῶς συνέσταλται, προσνεύει δὲ ἐπὶ τὸ Αἰγαῖον πέλαγος, ὅθεν αὐτῷ καὶ τοὔνομα· ὕστερον δὲ αὐτὸ τὸ ἀκρωτήριον Αἰγὰ κεκλῆσθαι, τὸ δὲ λοιπὸν Κάνη καὶ Κάναι.", "st": "13.1.68"}, {"sp": "N", "t": "μεταξὺ δὲ Ἐλαίας τε καὶ Πιτάνης καὶ Ἀταρνέως καὶ Περγάμου Τευθρανία ἐστί, διέχουσα οὐδεμιᾶς αὐτῶν ὑπὲρ ἑβδομήκοντα σταδίους ἐντὸς τοῦ Καΐκου, καὶ ὁ Τεύθρας Κιλίκων καὶ Μυσῶν ἱστόρηται βασιλεύς. Εὐριπίδης δ’ ὑπὸ Ἀλέου φησὶ τοῦ τῆς Αὔγης πατρὸς εἰς λάρνακα τὴν Αὔγην κατατεθεῖσαν ἅμα τῷ παιδὶ Τηλέφῳ καταποντωθῆναι, φωράσαντος τὴν ἐξ Ἡρακλέους φθοράν· Ἀθηνᾶς δὲ προνοίᾳ τὴν λάρνακα περαιωθεῖσαν ἐκπεσεῖν εἰς τὸ στόμα τοῦ Καΐκου, τὸν δὲ Τεύθραντα ἀναλαβόντα τὰ σώματα τῇ μὲν ὡς γαμετῇ χρήσασθαι τῷ δ’ ὡς ἑαυτοῦ παιδί. τοῦτο μὲν οὖν μῦθος, ἄλλην δέ τινα δεῖ γεγονέναι συντυχίαν, δι’ ἣν ἡ τοῦ Ἀρκάδος θυγάτηρ τῷ Μυσῶν βασιλεῖ συνῆλθε καὶ ὁ ἐξ αὐτῆς διεδέξατο τὴν ἐκείνου βασιλείαν. πεπίστευται δ’ οὖν ὅτι καὶ ὁ Τεύθρας καὶ ὁ Τήλεφος ἐβασίλευσαν τῆς χώρας τῆς περὶ τὴν Τευθρανίαν καὶ τὸν Κάικον, ὁ δὲ ποιητὴς ἐπὶ τοσοῦτον μέμνηται μόνον τῆς ἱστορίας ταύτης<br>ἀλλ’ οἷον τὸν Τηλεφίδην κατενήρατο χαλκῷ<br>ἥρω Εὐρύπυλον, πολλοὶ δ’ ἀμφ’ αὐτὸν ἑταῖροι<br>Κήτειοι κτείνοντο γυναίων εἵνεκα δώρων,<br>αἴνιγμα τιθεὶς ἡμῖν μᾶλλον ἢ λέγων τι σαφές. οὔτε γὰρ τοὺς Κητείους ἴσμεν οὕστινας δέξασθαι δεῖ, οὔτε τὸ “γυναίων εἵνεκα δώρων.” ἀλλὰ καὶ οἱ γραμματικοὶ μυθάρια παραβάλλοντες εὑρεσιλογοῦσι μᾶλλον ἢ λύουσι τὰ ζητούμενα.", "st": "13.1.69"}, {"sp": "N", "t": "ἐάσθω δὴ ταῦτα, ἐκεῖνο δ’ ὅπερ ἐστὶ μᾶλλον ἐν φανερῷ λαβόντες λέγωμεν, ὅτι ἐν τοῖς περὶ τὸν Κάικον τόποις φαίνεται βεβασιλευκὼς καθ’ Ὅμηρον ὁ Εὐρύπυλος, ὥστ’ ἴσως καὶ τῶν Κιλίκων τι μέρος ἦν ὑπ’ αὐτῷ, καὶ οὐ δύο δυναστεῖαι μόνον ἀλλὰ καὶ τρεῖς ὑπῆρξαν ἐν αὐτοῖς. τῷ δὲ λόγῳ τούτῳ συνηγορεῖ τὸ ἐν τῇ Ἐλαΐτιδι χειμαρρῶδες ποτάμιον δείκνυσθαι Κήτειον· ἐμπίπτει δ’ οὗτος εἰς ἄλλον ὅμοιον, εἶτ’ ἄλλον, καταστρέφουσι δὲ εἰς τὸν Κάικον· ὁ δὲ Κάικος οὐκ ἀπὸ τῆς Ἴδης ῥεῖ, καθάπερ εἴρηκε Βακχυλίδης, οὐδ’ ὀρθῶς Εὐριπίδης τὸν Μαρσύαν φησί<br>τὰς διωνομασμένας<br>ναίειν Κελαινὰς ἐσχάτοις Ἴδης τόποις.<br>πολὺ γὰρ τῆς Ἴδης ἄπωθεν αἱ Κελαιναί, πολὺ δὲ καὶ αἱ τοῦ Καΐκου πηγαί· δείκνυνται γὰρ ἐν πεδίῳ. Τῆμνον δ’ ἔστιν ὄρος ὃ διορίζει τοῦτό τε καὶ τὸ καλούμενον Ἀπίας πεδίον, ὃ ὑπέρκειται ἐν τῇ μεσογαίᾳ τοῦ Θήβης πεδίου· ῥεῖ δ’ ἐκ τοῦ Τήμνου ποταμὸς Μύσιος ἐμβάλλων εἰς τὸν Κάικον ὑπὸ ταῖς πηγαῖς αὐτοῦ, ἀφ’ οὗ δέχονταί τινες εἰπεῖν Αἰσχύλον κατὰ τὴν εἰσβολὴν τοῦ ἐν Μυρμιδόσι προλόγου<br>ἰὼ Κάικε Μύσιαί τ’ ἐπιρροαί.<br>ἐγγὺς δὲ τῶν πηγῶν κώμη Γέργιθα ἔστιν, εἰς ἣν μετῴκισεν Ἄτταλος τοὺς ἐν τῇ Τρῳάδι τὸ χωρίον ἐξελών.", "st": "13.1.70"}, {"sp": "N", "t": "ἐπεὶ δὲ τῇ παραλίᾳ τῇ ἀπὸ Λεκτοῦ μέχρι Κανῶν ἀντιπαρατέταται νῆσος ἡ Λέσβος λόγου ἀξία πλείστου, περίκειται δὲ αὐτῇ καὶ νησία τὰ μὲν ἔξωθεν τὰ δὲ καὶ ἐντὸς μεταξὺ αὐτῆς τε καὶ τῆς ἠπείρου, καιρὸς ἤδη περὶ τούτων εἰπεῖν· καὶ γὰρ ταῦτά ἐστιν Αἰολικά, σχεδὸν δέ τι καὶ μητρόπολις ἡ Λέσβος ὑπάρχει τῶν Αἰολικῶν πόλεων. ἀρκτέον δ’ ἀφ’ ὧνπερ καὶ τὴν παραλίαν ἐπήλθομεν τὴν κατ’ αὐτήν.", "st": "13.2.1"}, {"sp": "N", "t": "ἀπὸ Λεκτοῦ τοίνυν ἐπὶ Ἄσσον πλέουσιν ἀρχὴ τῆς Λεσβίας ἐστὶ κατὰ Σίγριον τὸ πρὸς ἄρκτον αὐτῆς ἄκρον. ἐνταῦθα δέ που καὶ Μήθυμνα πόλις Λεσβίων ἐστὶν ἀπὸ ἑξήκοντα σταδίων τῆς ἐκ Πολυμηδείου πρὸς τὴν Ἄσσον παραλίας. οὔσης δὲ τῆς περιμέτρου σταδίων χιλίων ἑκατὸν ἣν ἡ σύμπασα ἐκπληροῖ νῆσος, τὰ καθ’ ἕκαστα οὕτως ἔχει· ἀπὸ Μηθύμνης εἰς Μαλίαν τὸ νοτιώτατον ἄκρον ἐν δεξιᾷ ἔχουσι τὴν νῆσον, καθ’ ὃ αἱ Κάναι μάλιστα ἀντίκεινται τῇ νήσῳ καὶ συναπαρτίζουσι, στάδιοί εἰσι τριακόσιοι τετταράκοντα· ἐντεῦθεν δ’ ἐπὶ Σίγριον, ὅπερ ἐστὶ τῆς νήσου τὸ μῆκος, πεντακόσιοι ἑξήκοντα· εἶτ’ ἐπὶ τὴν Μήθυμναν διακόσιοι δέκα. Μιτυλήνη δὲ κεῖται μεταξὺ Μηθύμνης καὶ τῆς Μαλίας ἡ μεγίστη πόλις, διέχουσα τῆς Μαλίας ἑβδομήκοντα σταδίους, τῶν δὲ Κανῶν ἑκατὸν εἴκοσιν, ὅσους καὶ τῶν Ἀργινουσσῶν, αἳ τρεῖς μέν εἰσιν οὐ μεγάλαι νῆσοι, πλησιάζουσι δὲ τῇ ἠπείρῳ, παρακείμεναι ταῖς Κάναις. ἐν δὲ τῷ μεταξὺ Μιτυλήνης καὶ τῆς Μηθύμνης κατὰ κώμην τῆς Μηθυμναίας καλουμένην Αἴγειρον στενωτάτη ἐστὶν ἡ νῆσος, ὑπέρβασιν ἔχουσα εἰς τὸν Πυρραίων εὔριπον σταδίων εἴκοσιν. ἵδρυται δ’ ἡ Πύρρα ἐν τῷ ἑσπερίῳ πλευρῷ τῆς Λέσβου, διέχουσα τῆς Μαλίας ἑκατόν. ἔχει δ’ ἡ Μιτυλήνη λιμένας δύο, ὧν ὁ νότιος κλειστὸς τριηρικὸς ναυσὶ πεντήκοντα, ὁ δὲ βόρειος μέγας καὶ βαθύς, χώματι σκεπαζόμενος· πρόκειται δ’ ἀμφοῖν νησίον μέρος τῆς πόλεως ἔχον αὐτόθι συνοικούμενον· κατεσκεύασται δὲ τοῖς πᾶσι καλῶς.", "st": "13.2.2"}, {"sp": "N", "t": "ἄνδρας δ’ ἔσχεν ἐνδόξους τὸ παλαιὸν μὲν Πιττακόν, ἕνα τῶν ἑπτὰ σοφῶν, καὶ τὸν ποιητὴν Ἀλκαῖον καὶ τὸν ἀδελφὸν Ἀντιμενίδαν, ὅν φησιν Ἀλκαῖος Βαβυλωνίοις συμμαχοῦντα τελέσαι μέγαν ἆθλον καὶ ἐκ πόνων αὐτοὺς ῥύσασθαι κτείναντα<br>ἄνδρα μαχαίταν βασιληίων<br>παλαστὰν (ὥς φησιν) ἀπολείποντα μόνον μίαν<br>παχέων ἀπὺ πέμπων.<br>συνήκμασε δὲ τούτοις καὶ ἡ Σαπφώ, θαυμαστόν τι χρῆμα· οὐ γὰρ ἴσμεν ἐν τῷ τοσούτῳ χρόνῳ τῷ μνημονευομένῳ φανεῖσάν τινα γυναῖκα ἐνάμιλλον οὐδὲ κατὰ μικρὸν ἐκείνῃ ποιήσεως χάριν. ἐτυραννήθη δὲ ἡ πόλις κατὰ τοὺς χρόνους τούτους ὑπὸ πλειόνων διὰ τὰς διχοστασίας, καὶ τὰ στασιωτικὰ καλούμενα τοῦ Ἀλκαίου ποιήματα περὶ τούτων ἐστίν· ἐν δὲ τοῖς τυράννοις καὶ ὁ Πιττακὸς ἐγένετο. Ἀλκαῖος μὲν οὖν ὁμοίως ἐλοιδορεῖτο καὶ τούτῳ καὶ τοῖς ἄλλοις, Μυρσίλῳ καὶ Μελάγχρῳ καὶ τοῖς Κλεανακτίδαις καὶ ἄλλοις τισίν, οὐδ’ αὐτὸς καθαρεύων τῶν τοιούτων νεωτερισμῶν. Πιττακὸς δ’ εἰς μὲν τὴν τῶν δυναστειῶν κατάλυσιν ἐχρήσατο τῇ μοναρχίᾳ καὶ αὐτός, καταλύσας δὲ ἀπέδωκε τὴν αὐτονομίαν τῇ πόλει. ὕστερον δ’ ἐγένετο χρόνοις πολλοῖς Διοφάνης ὁ ῥήτωρ, καθ’ ἡμᾶς δὲ Ποτάμων καὶ Λεσβοκλῆς καὶ Κριναγόρας καὶ ὁ συγγραφεὺς Θεοφάνης. οὗτος δὲ καὶ πολιτικὸς ἀνὴρ ὑπῆρξε καὶ Πομπηίῳ τῷ Μάγνῳ κατέστη φίλος μάλιστα διὰ τὴν ἀρετὴν ταύτην, καὶ πάσας συγκατώρθωσεν αὐτῷ τὰς πράξεις, ἀφ’ ὧν τήν τε πατρίδα ἐκόσμησε τὰ μὲν δι’ ἐκείνου τὰ δὲ δι’ ἑαυτοῦ, καὶ ἑαυτὸν πάντων τῶν Ἑλλήνων ἐπιφανέστατον ἀνέδειξεν· υἱόν τε ἀπέλιπε Μάρκον Πομπήιον, ὃν τῆς Ἀσίας ἐπίτροπον κατέστησέ ποτε Καῖσαρ ὁ Σεβαστός, καὶ νῦν ἐν τοῖς πρώτοις ἐξετάζεται τῶν Τιβερίου φίλων. Ἀθηναῖοι δ’ ἐκινδύνευσαν μὲν ἀνηκέστῳ ψόγῳ περιπεσεῖν ψηφισάμενοι Μιτυληναίους ἡβηδὸν ἀποσφαγῆναι, μετέγνωσαν δὲ καὶ ἔφθη μιᾷ θᾶττον ἡμέρᾳ τὸ ψήφισμα ἀφιγμένον ὡς τοὺς στρατηγοὺς πρὶν ἢ πρᾶξαι τὸ προσταχθέν.", "st": "13.2.3"}, {"sp": "N", "t": "ἡ δὲ Πύρρα κατέστραπται, τὸ δὲ προάστειον οἰκεῖται καὶ ἔχει λιμένα, ὅθεν εἰς Μιτυλήνην ὑπέρβασις σταδίων ὀγδοήκοντα. εἶτ’ Ἔρεσος ἔστι μετὰ τὴν Πύρραν· ἵδρυται δ’ ἐπὶ λόφου καθήκει τε ἐπὶ θάλατταν· εἶτ’ ἐπὶ τὸ Σίγριον ἐντεῦθεν στάδιοι εἰκοσιοκτώ· ἐξ Ἐρέσου δ’ ἦσαν Θεόφραστός τε καὶ Φανίας οἱ ἐκ τῶν περιπάτων φιλόσοφοι, Ἀριστοτέλους γνώριμοι. Τύρταμος δ’ ἐκαλεῖτο ἔμπροσθεν ὁ Θεόφραστος, μετωνόμασε δ’ αὐτὸν Ἀριστοτέλης Θεόφραστον, ἅμα μὲν φεύγων τὴν τοῦ προτέρου ὀνόματος κακοφωνίαν, ἅμα δὲ τὸν τῆς φράσεως αὐτοῦ ζῆλον ἐπισημαινόμενος· ἅπαντας μὲν γὰρ λογίους ἐποίησε τοὺς μαθητὰς Ἀριστοτέλης, λογιώτατον δὲ Θεόφραστον. Ἄντισσα δ’ ἐφεξῆς ἐστι τῷ Σιγρίῳ πόλις ἔχουσα λιμένα, ἔπειτα Μήθυμνα· ἐντεῦθεν δ’ ἦν Ἀρίων ὁ ἐπὶ τῷ δελφῖνι μυθευόμενος ὑπὸ τῶν περὶ Ἡρόδοτον εἰς Ταίναρον σωθῆναι, καταποντωθεὶς ὑπὸ τῶν λῃστῶν· οὗτος μὲν οὖν κιθαρῳδός. καὶ Τέρπανδρον δὲ τῆς αὐτῆς μουσικῆς τεχνίτην γεγονέναι φασὶ καὶ τῆς αὐτῆς νήσου, τὸν πρῶτον ἀντὶ τῆς τετραχόρδου λύρας ἑπταχόρδῳ χρησάμενον, καθάπερ καὶ ἐν τοῖς ἀναφερομένοις ἔπεσιν εἰς αὐτὸν λέγεται<br>σοὶ δ’ ἡμεῖς τετράγηρυν ἀποστρέψαντες ἀοιδὴν,<br>ἑπτατόνῳ φόρμιγγι νέους κελαδήσομεν ὕμνους.<br>καὶ Ἑλλάνικος δὲ Λέσβιος ὁ συγγραφεὺς καὶ Καλλίας ὁ τὴν Σαπφὼ καὶ τὸν Ἀλκαῖον ἐξηγησάμενος.", "st": "13.2.4"}, {"sp": "N", "t": "κατὰ δὲ τὸν πορθμὸν τὸν μεταξὺ τῆς Ἀσίας καὶ τῆς Λέσβου νησία ἐστὶ περὶ εἴκοσιν, ὡς δὲ Τιμοσθένης φησί, τετταράκοντα· καλοῦνται δ’ Ἑκατόννησοι συνθέτως, ὡς Πελοπόννησος, κατὰ ἔθος τι τοῦ ⟨ν⟩ γράμματος πλεονάζοντος ἐν τοῖς τοιούτοις, ὡς Μυόννησος καὶ Προκόννησος λέγεται καὶ Ἁλόννησος, ὥστε Ἑκατόννησοί εἰσιν, οἷον Ἀπολλωνόννησοι· Ἕκατος γὰρ ὁ Ἀπόλλων· παρὰ πᾶσαν γὰρ δὴ τὴν παραλίαν ταύτην ὁ Ἀπόλλων ἐκτετίμηται μέχρι Τενέδου, Σμινθεὺς ἢ Κιλλαῖος καλούμενος ἢ Γρυνεὺς ἤ τινα ἄλλην ἐπωνυμίαν ἔχων. πλησίον δὲ τούτων ἐστὶ καὶ ἡ Πορδοσελήνη, πόλιν ὁμώνυμον ἔχουσα ἐν αὐτῇ· καὶ πρὸ τῆς πόλεως ταύτης ἄλλη νῆσος μείζων αὐτῆς, καὶ πόλις ὁμώνυμος ἔρημος, ἱερὸν ἅγιον ἔχουσα Ἀπόλλωνος.", "st": "13.2.5"}, {"sp": "N", "t": "τὰς δὲ δυσφημίας τῶν ὀνομάτων φεύγοντές τινες ἐνταῦθα μὲν Ποροσελήνην δεῖν λέγειν φασί, τὸ δ’ Ἀσπορδηνὸν ὄρος τὸ περὶ Πέργαμον, τραχὺ καὶ λυπρὸν ὄν, Ἀσπορηνόν, καὶ τὸ ἱερὸν τὸ ἐνταῦθα τῆς μητρὸς τῶν θεῶν Ἀσπορηνῆς. τί οὖν φήσομεν τὴν πόρδαλιν καὶ τὸν σαπέρδην καὶ τὸν Περδίκκαν καὶ τὸ Σιμωνίδου<br>σὺν πορδακοῖσιν ἐκπεσόντες εἵμασιν<br>ἀντὶ τοῦ διαβρόχοις, καὶ ἐν τῇ ἀρχαίᾳ που κωμῳδίᾳ<br>πορδακὸν τὸ χωρίον<br>τὸ λιμνάζον; διέχει δ’ ἡ Λέσβος τὸ ἴσον ἀπὸ τῆς Τενέδου καὶ Λήμνου καὶ Χίου σχεδόν τι τῶν πεντακοσίων ἐνδοτέρω σταδίων.", "st": "13.2.6"}, {"sp": "N", "t": "τοιαύτης δὲ τῆς πρὸς τοὺς Τρῶας οἰκειότητος ὑπαρχούσης τοῖς τε Λέλεξι καὶ τοῖς Κίλιξι, ζητοῦσιν αἰτίαν δι’ ἣν οὐ συγκαταλέγονται καὶ οὗτοι ἐν τῷ καταλόγῳ. εἰκὸς δὲ διὰ τὴν τῶν ἡγεμόνων διαφθορὰν καὶ τὴν τῶν πόλεων ἐκπόρθησιν ὀλίγους ὑπολειφθέντας τοὺς Κίλικας ὑπὸ τῷ Ἕκτορι τάττεσθαι· ὅ τε γὰρ Ἠετίων καὶ οἱ παῖδες αὐτοῦ λέγονται πρὸ τοῦ καταλόγου διαφθαρῆναι<br>ἤτοι μὲν πατέρ’ ἀμὸν ἀπέκτανε δῖος Ἀχιλλεύς,<br>ἐκ δὲ πόλιν πέρσεν Κιλίκων,<br>Θήβην ὑψίπυλον.<br>οἳ δέ μοι ἑπτὰ κασίγνητοι ἔσαν ἐν μεγάροισιν,<br>οἱ μὲν πάντες ἰῷ κίον ἤματι Ἄιδος εἴσω·<br>πάντας γὰρ κατέπεφνε ποδάρκης δῖος Ἀχιλλεύς.<br>ὡς δ’ αὕτως καὶ οἱ ὑπὸ Μύνητι τούς τε ἡγεμόνας ἀποβεβλήκασι καὶ τὴν πόλιν<br>κὰδ δὲ Μύνητ’ ἔβαλεν καὶ Ἐπίστροφον,<br>πέρσεν δὲ πόλιν θείοιο Μύνητος.<br>, τοὺς δὲ Λέλεγας τοῖς μὲν ἀγῶσι παρόντας ποιεῖ, ὅταν οὕτω λέγῃ<br>πρὸς μὲν ἁλὸς Κᾶρες καὶ Παίονες ἀγκυλότοξοι<br>καὶ Λέλεγες καὶ Καύκωνες,<br>καὶ πάλιν<br>Σάτνιον οὔτασε δουρὶ<br>Οἰνοπίδην, ὃν ἄρα νύμφη τέκε Νηὶς ἀμύμων<br>Οἴνοπι βουκολέοντι παρ’ ὄχθας Σατνιόεντος.<br>οὐ γὰρ οὕτως ἐξελελοίπεσαν τελέως ὥστε μὴ καὶ καθ’ αὑτοὺς ἔχειν τι σύστημα, ἅτε τοῦ βασιλέως αὐτῶν ἔτι περιόντος<br>Ἄλτεω, ὃς Λελέγεσσι φιλοπτολέμοισιν ἀνάσσει,<br>καὶ τῆς πόλεως οὐ τελέως ἠφανισμένης· ἐπιφέρει γὰρ<br>Πήδασον αἰπήεσσαν ἔχων ἐπὶ Σατνιόεντι.<br>ἐν μέντοι τῷ καταλόγῳ παραλέλοιπεν αὐτούς, οὐχ ἱκανὸν ἡγούμενος τὸ σύστημα ὥστ’ ἐν καταλόγῳ τάττεσθαι, ἢ καὶ ὑπὸ τῷ Ἕκτορι καὶ τούτους συγκαταλέγων οὕτως ὄντας οἰκείους. ὁ γὰρ Λυκάων φησὶν ἀδελφὸς ὢν Ἕκτορος<br>μινυνθάδιον δέ με μήτηρ<br>γείνατο Λαοθόη, θυγάτηρ Ἄλταο γέροντος,<br>Ἄλτεω, ὃς Λελέγεσσι φιλοπτολέμοισιν ἀνάσσει.<br>ταῦτα μὲν οὖν τοιαύτην τινὰ ἔχει τὴν εἰκοτολογίαν.", "st": "13.3.1"}, {"sp": "N", "t": "εἰκοτολογεῖν δ’ ἔστι κἂν εἴ τις τὸν ἀκριβῆ ζητεῖ κατὰ τὸν ποιητὴν ὅρον μέχρι τίνος οἱ Κίλικες διέτεινον καὶ οἱ Πελασγοὶ καὶ ἔτι οἱ μεταξὺ τούτων Κήτειοι λεγόμενοι οἱ ὑπὸ τῷ Εὐρυπύλῳ. περὶ μὲν οὖν τῶν Κιλίκων καὶ τῶν ὑπ’ Εὐρυπύλῳ τὰ ἐνόντα εἴρηται, καὶ διότι [ἐπὶ] τὰ περὶ τὸν Κάικον μάλιστα περατοῦνται. τοὺς δὲ Πελασγοὺς εὔλογον τούτοις ἐφεξῆς τιθέναι ἔκ τε τῶν ὑφ’ Ὁμήρου λεγομένων καὶ ἐκ τῆς ἄλλης ἱστορίας. ὁ μὲν γὰρ οὕτω φησίν<br>Ἱππόθοος δ’ ἄγε φῦλα Πελασγῶν ἐγχεσιμώρων,<br>τῶν οἳ Λάρισαν ἐριβώλακα ναιετάασκον·<br>τῶν ἦρχ’ Ἱππόθοός τε Πύλαιός τ’ ὄζος Ἄρηος,<br>υἷε δύω Λήθοιο Πελασγοῦ Τευταμίδαο.<br>ἐξ ὧν πλῆθός τε ἐμφαίνει ἀξιόλογον τὸ τῶν Πελασγῶν (οὐ γὰρ φῦλον, ἀλλὰ φῦλα ἔφη) καὶ τὴν οἴκησιν ἐν Λαρίσῃ φράζει. πολλαὶ μὲν οὖν αἱ Λάρισαι, δεῖ δὲ τῶν ἐγγύς τινα δέξασθαι, μάλιστα δ’ ἂν τὴν περὶ Κύμην ὑπολάβοι τις ὀρθῶς· τριῶν γὰρ οὐσῶν ἡ μὲν καθ’ Ἁμαξιτὸν ἐν ὄψει τελέως ἐστὶ τῷ Ἰλίῳ, καὶ ἐγγὺς σφόδρα ἐν διακοσίοις που σταδίοις, ὥστ’ οὐκ ἂν λέγοιτο πιθανῶς ὁ Ἱππόθοος πεσεῖν ἐν τῷ ὑπὲρ Πατρόκλου ἀγῶνι “τῆλ’ ἀπὸ Λαρίσης,” ταύτης γε, ἀλλὰ μᾶλλον τῆς περὶ Κύμην· χίλιοι γάρ που στάδιοι μεταξύ· τρίτη δ’ ἐστὶ Λάρισα κώμη τῆς Ἐφεσίας ἐν τῷ Καϋστρίῳ πεδίῳ, ἥν φασι πόλιν ὑπάρξαι πρότερον, ἔχουσαν καὶ ἱερὸν Ἀπόλλωνος Λαρισηνοῦ, πλησιάζουσαν τῷ Τμώλῳ μᾶλλον ἢ τῇ Ἐφέσῳ· ταύτης γὰρ ἑκατὸν καὶ ὀγδοήκοντα διέχει σταδίους, ὥστε ὑπὸ τοῖς Μῄοσιν ἄν τις τάττοι ταύτην. Ἐφέσιοι δ’ αὐξηθέντες ὕστερον πολλὴν τῆς τῶν Μῃόνων, οὓς νῦν Λυδοὺς φαμέν, ἀπετέμοντο, ὥστ’ οὐδ’ αὕτη ἂν ἡ τῶν Πελασγῶν Λάρισα εἴη, ἀλλ’ ἐκείνη μᾶλλον. καὶ γὰρ τῆς μὲν ἐν τῇ Καϋστριανῇ Λαρίσης οὐδὲν ἔχομεν τεκμήριον ἰσχυρὸν ὡς ἦν ἤδη τότε· οὐδὲ γὰρ τῆς Ἐφέσου. τῆς δὲ περὶ τὴν Κύμην μαρτύριόν ἐστι πᾶσα ἡ Αἰολικὴ ἱστορία μικρὸν ὕστερον τῶν Τρωικῶν γενομένη.", "st": "13.3.2"}, {"sp": "N", "t": "φασὶ γὰρ τοὺς ἐκ τοῦ Φρικίου τοῦ ὑπὲρ Θερμοπυλῶν Λοκρικοῦ ὄρους ὁρμηθέντας κατᾶραι μὲν εἰς τὸν τόπον ὅπου νῦν ἡ Κύμη ἐστί, καταλαβόντας δὲ τοὺς Πελασγοὺς κεκακωμένους ὑπὸ τοῦ Τρωικοῦ πολέμου, κατέχοντας δ’ ὅμως ἔτι τὴν Λάρισαν διέχουσαν τῆς Κύμης ὅσον ἑβδομήκοντα σταδίους, ἐπιτειχίσαι αὐτοῖς τὸ νῦν ἔτι λεγόμενον Νέον τεῖχος ἀπὸ τριάκοντα σταδίων τῆς Λαρίσης, ἑλόντας δὲ κτίσαι τὴν Κύμην καὶ τοὺς περιγενομένους ἀνθρώπους ἐκεῖσε ἀνοικίσαι· ἀπὸ δὲ τοῦ Λοκρικοῦ ὄρους τήν τε Κύμην Φρικωνίδα καλοῦσιν, ὁμοίως δὲ καὶ τὴν Λάρισαν· ἐρήμη δ’ ἐστὶ νῦν. ὅτι δ’ οἱ Πελασγοὶ μέγα ἦν ἔθνος, καὶ ἐκ τῆς ἄλλης ἱστορίας οὕτως ἐκμαρτυρεῖσθαί φασι· Μενεκράτης γοῦν ὁ Ἐλαΐτης ἐν τοῖς περὶ κτίσεων φησὶ τὴν παραλίαν τὴν νῦν Ἰωνικὴν πᾶσαν ἀπὸ Μυκάλης ἀρξαμένην ὑπὸ Πελασγῶν οἰκεῖσθαι πρότερον καὶ τὰς πλησίον νήσους. Λέσβιοι δ’ ὑπὸ Πυλαίῳ τετάχθαι λέγουσι σφᾶς τῷ ὑπὸ τοῦ ποιητοῦ λεγομένῳ τῶν Πελασγῶν ἄρχοντι, ἀφ’ οὗ καὶ τὸ παρ’ αὐτοῖς ὄρος ἔτι Πύλαιον καλεῖσθαι. καὶ Χῖοι δὲ οἰκιστὰς ἑαυτῶν Πελασγούς φασι τοὺς ἐκ τῆς Θετταλίας. πολύπλανον δὲ καὶ ταχὺ τὸ ἔθνος πρὸς ἀπαναστάσεις, ηὐξήθη τε ἐπὶ πολὺ καὶ ἀθρόαν ἔλαβε τὴν ἔκλειψιν καὶ μάλιστα κατὰ τὴν τῶν Αἰολέων καὶ τῶν Ἰώνων περαίωσιν εἰς τὴν Ἀσίαν.", "st": "13.3.3"}, {"sp": "N", "t": "ἴδιον δέ τι τοῖς Λαρισαίοις συνέβη τοῖς τε Καϋστριανοῖς καὶ τοῖς Φρικωνεῦσι καὶ τρίτοις τοῖς ἐν Θετταλίᾳ· ἅπαντες γὰρ ποταμόχωστον τὴν χώραν ἔσχον οἱ μὲν ὑπὸ τοῦ Καΰστρου, οἱ δ’ ὑπὸ τοῦ Ἕρμου, οἱ δ’ ὑπὸ τοῦ Πηνειοῦ. ἐν δὲ τῇ Φρικωνίδι Λαρίσῃ τετιμῆσθαι λέγεται Πίασος, ὅν φασιν ἄρχοντα Πελασγῶν ἐρασθῆναι τῆς θυγατρὸς Λαρίσης, βιασάμενον δ’ αὐτὴν τῖσαι τῆς ὕβρεως δίκην· ἐγκύψαντα γὰρ εἰς πίθον οἴνου καταμαθοῦσαν τῶν σκελῶν λαβομένην ἐξᾶραι καὶ καθεῖναι αὐτὸν εἰς τὸν πίθον. τὰ μὲν οὖν ἀρχαῖα τοιαῦτα.", "st": "13.3.4"}, {"sp": "N", "t": "ταῖς δὲ νῦν Αἰολικαῖς πόλεσιν ἔτι καὶ τὰς Αἰγὰς προσληπτέον καὶ τὴν Τῆμνον, ὅθεν ἦν Ἑρμαγόρας ὁ τὰς ῥητορικὰς τέχνας συγγράψας· ἵδρυνται δ’ αἱ πόλεις αὗται κατὰ τὴν ὀρεινὴν τὴν ὑπερκειμένην τῆς τε Κυμαίας καὶ τῆς Φωκαέων καὶ Σμυρναίων γῆς, παρ’ ἣν ὁ Ἕρμος ῥεῖ. οὐκ ἄπωθεν δὲ τούτων τῶν πόλεων οὐδ’ ἡ Μαγνησία ἐστὶν ἡ ὑπὸ Σιπύλῳ, ἐλευθέρα πόλις ὑπὸ Ῥωμαίων κεκριμένη. καὶ ταύτην δ’ ἐκάκωσαν οἱ νεωστὶ γενόμενοι σεισμοί. εἰς δὲ τἀναντία τὰ ἐπὶ τὸν Κάικον νεύοντα ἀπὸ Λαρίσης μὲν διαβάντι τὸν Ἕρμον εἰς Κύμην ἑβδομήκοντα στάδιοι, ἐντεῦθεν δ’ εἰς Μύριναν τετταράκοντα στάδιοι, τὸ δ’ ἴσον ἐντεῦθεν εἰς Γρύνιον κἀκεῖθεν εἰς Ἐλαίαν· ὡς δ’ Ἀρτεμίδωρος, ἀπὸ τῆς Κύμης εἰσὶν Ἄδαι, εἶτ’ ἄκρα μετὰ τετταράκοντα σταδίους ἣν καλοῦσιν Ὕδραν, ἡ ποιοῦσα τὸν κόλπον τὸν Ἐλαϊτικὸν πρὸς τὴν ἀπεναντίον ἄκραν Ἁρματοῦντα. τοῦ μὲν οὖν στόματος τὸ πλάτος περὶ ὀγδοήκοντα σταδίους ἐστίν, ἐγκολπίζοντι δὲ Μύρινα ἐν ἑξήκοντα σταδίοις, Αἰολὶς πόλις ἔχουσα λιμένα, εἶτ’ Ἀχαιῶν λιμήν, ὅπου οἱ βωμοὶ τῶν δώδεκα θεῶν, εἶτα πολίχνιον Μυριναίων Γρύνιον καὶ ἱερὸν Ἀπόλλωνος καὶ μαντεῖον ἀρχαῖον καὶ νεὼς πολυτελὴς λίθου λευκοῦ, στάδιοι δ’ ἐπ’ αὐτὴν τετταράκοντα· εἶθ’ ἑβδομήκοντα εἰς Ἐλαίαν, λιμένα ἔχουσαν καὶ ναύσταθμον τῶν Ἀτταλικῶν βασιλέων, Μενεσθέως κτίσμα καὶ τῶν σὺν αὐτῷ Ἀθηναίων τῶν συστρατευσάντων ἐπὶ Ἴλιον. τὰ δ’ ἑξῆς εἴρηται τὰ περὶ Πιτάνην καὶ Ἀταρνέα καὶ τἆλλα τὰ ταύτῃ.", "st": "13.3.5"}, {"sp": "N", "t": "μεγίστη δέ ἐστι τῶν Αἰολικῶν καὶ ἀρίστη Κύμη καὶ σχεδὸν μητρόπολις αὕτη τε καὶ ἡ Λέσβος τῶν ἄλλων πόλεων περὶ τριάκοντά που τὸν ἀριθμόν, ὧν ἐκλελοίπασιν οὐκ ὀλίγαι. σκώπτεται δ’ εἰς ἀναισθησίαν ἡ Κύμη κατὰ τοιαύτην τινά, ὥς φασιν ἔνιοι, δόξαν, ὅτι τριακοσίοις ἔτεσιν ὕστερον τῆς κτίσεως ἀπέδοντο τοῦ λιμένος τὰ τέλη, πρότερον δ’ οὐκ ἐκαρποῦτο τὴν πρόσοδον ταύτην ὁ δῆμος· κατέσχεν οὖν δόξα ὡς ὀψὲ ᾐσθημένων ὅτι ἐπὶ θαλάττῃ πόλιν οἰκοῖεν. ἔστι δὲ καὶ ἄλλος λόγος, ὅτι δανεισάμενοι χρήματα δημοσίᾳ τὰς στοὰς ὑπέθεντο, εἶτ’ οὐκ ἀποδιδόντες κατὰ τὴν ὡρισμένην ἡμέραν εἴργοντο τῶν περιπάτων· ὅτε μέντοι ὄμβρος εἴη, κατ’ αἰδῶ τινα κηρύττοιεν οἱ δανεισταί, κελεύοντες ὑπὸ τὰς στοὰς ὑπέρχεσθαι· τοῦ δὴ κήρυκος οὕτω φθεγγομένου “ὑπὸ τὰς στοὰς ὑπέλθετε,” ἐκπεσεῖν λόγον ὡς Κυμαίων οὐκ αἰσθανομένων ὡς ἐν τοῖς ὄμβροις ὑπὸ τὰς στοὰς ὑπελθετέον, ἂν μὴ σημάνῃ τις αὐτοῖς διὰ κηρύγματος. ἀνὴρ δ’ ἄξιος μνήμης ἐκ τῆσδε τῆς πόλεως ἀναντιλέκτως μέν ἐστιν Ἔφορος, τῶν Ἰσοκράτους γνωρίμων τοῦ ῥήτορος, ὁ τὴν ἱστορίαν συγγράψας καὶ τὰ περὶ τῶν εὑρημάτων· καὶ ἔτι πρότερος τούτου Ἡσίοδος ὁ ποιητής· αὐτὸς γὰρ εἴρηκεν ὅτι ὁ πατὴρ αὐτοῦ Δῖος μετῴκησεν εἰς Βοιωτοὺς Κύμην Αἰολίδα προλιπών<br>νάσσατο δ’ ἄγχ’ Ἑλικῶνος ὀιζυρῇ ἐνὶ κώμῃ<br>Ἄσκρῃ, χεῖμα κακῇ, θέρει ἀργαλέῃ, οὐδέ ποτ’ ἐσθλῇ.<br>Ὅμηρος δ’ οὐχ ὁμολογουμένως· πολλοὶ γὰρ ἀμφισβητοῦσιν αὐτοῦ. τὸ δ’ ὄνομα ἀπὸ Ἀμαζόνος τῇ πόλει τεθεῖσθαι, καθάπερ καὶ τῇ Μυρίνῃ ἀπὸ τῆς ἐν τῷ Τρωικῷ πεδίῳ κειμένης ὑπὸ τῇ Βατιείᾳ<br>τὴν ἤτοι ἄνδρες Βατίειαν κικλήσκουσιν,<br>ἀθάνατοι δέ τε σῆμα πολυσκάρθμοιο Μυρίνης<br>σκώπτεται δὲ καὶ ὁ Ἔφορος, διότι τῆς πατρίδος ἔργα οὐκ ἔχων φράζειν ἐν τῇ διαριθμήσει τῶν ἄλλων πράξεων, οὐ μὴν οὐδ’ ἀμνημόνευτον αὐτὴν εἶναι θέλων, οὕτως ἐπιφωνεῖ κατὰ δὲ τὸν αὐτὸν καιρὸν Κυμαῖοι τὰς ἡσυχίας ἦγον. Ἐπεὶ δὲ διεληλύθαμεν τὴν Τρωικὴν ἅμα καὶ τὴν Αἰολικὴν παραλίαν, ἐφεξῆς ἂν εἴη τὴν μεσόγαιαν ἐπιδραμεῖν μέχρι τοῦ Ταύρου, φυλάττοντας τὴν αὐτὴν τῆς ἐφόδου τάξιν.", "st": "13.3.6"}, {"sp": "N", "t": "ἔχει δέ τινα ἡγεμονίαν πρὸς τοὺς τόπους τούτους τὸ Πέργαμον, ἐπιφανὴς πόλις καὶ πολὺν συνευτυχήσασα χρόνον τοῖς Ἀτταλικοῖς βασιλεῦσι· καὶ δὴ καὶ ἐντεῦθεν ἀρκτέον τῆς ἑξῆς περιοδείας, καὶ πρῶτον περὶ τῶν βασιλέων ὁπόθεν ὡρμήθησαν καὶ εἰς ἃ κατέστρεψαν ἐν βραχέσι δηλωτέον. ἦν μὲν δὴ τὸ Πέργαμον Λυσιμάχου γαζοφυλάκιον τοῦ Ἀγαθοκλέους, ἑνὸς τῶν Ἀλεξάνδρου διαδόχων, αὐτὴν τὴν ἄκραν τοῦ ὄρους συνοικουμένην ἔχον· ἔστι δὲ στροβιλοειδὲς τὸ ὄρος εἰς ὀξεῖαν κορυφὴν ἀπολῆγον. ἐπεπίστευτο δὲ τὴν φυλακὴν τοῦ ἐρύματος τούτου καὶ τῶν χρημάτων (ἦν δὲ τάλαντα ἐνακισχίλια) φιλέταιρος, ἀνὴρ Τιανός, θλιβίας ἐκ παιδός· συνέβη γὰρ ἔν τινι ταφῇ θέας οὔσης καὶ πολλῶν παρόντων ἀποληφθεῖσαν ἐν τῷ ὄχλῳ τὴν κομίζουσαν τροφὸν τὸν Φιλέταιρον ἔτι νήπιον συνθλιβῆναι μέχρι τοσοῦδε ὥστε πηρωθῆναι τὸν παῖδα. ἦν μὲν δὴ εὐνοῦχος, τραφεὶς δὲ καλῶς ἐφάνη τῆς πίστεως ταύτης ἄξιος. τέως μὲν οὖν εὔνους διέμεινε τῷ Λυσιμάχῳ, διενεχθεὶς δὲ πρὸς Ἀρσινόην τὴν γυναῖκα αὐτοῦ διαβάλλουσαν αὐτὸν ἀπέστησε τὸ χωρίον καὶ πρὸς τοὺς καιροὺς ἐπολιτεύετο ὁρῶν ἐπιτηδείους πρὸς νεωτερισμόν· ὅ τε γὰρ Λυσίμαχος κακοῖς οἰκείοις περιπεσὼν ἠναγκάσθη τὸν υἱὸν ἀνελεῖν Ἀγαθοκλέα, Σέλευκός τε ἐπελθὼν ὁ Νικάτωρ ἐκεῖνόν τε κατέλυσε καὶ αὐτὸς κατελύθη δολοφονηθεὶς ὑπὸ Πτολεμαίου τοῦ Κεραυνοῦ. τοιούτων δὲ θορύβων ὄντων διεγένετο μένων ἐπὶ τοῦ ἐρύματος ὁ εὐνοῦχος, καὶ πολιτευόμενος δι’ ὑποσχέσεων καὶ τῆς ἄλλης θεραπείας ἀεὶ πρὸς τὸν ἰσχύοντα καὶ ἐγγὺς παρόντα· διετέλεσε γοῦν ἔτη εἴκοσι κύριος ὢν τοῦ φρουρίου καὶ τῶν χρημάτων.", "st": "13.4.1"}, {"sp": "N", "t": "ἦσαν δ’ αὐτῷ δύο ἀδελφοί, πρεσβύτερος μὲν Εὐμένης νεώτερος δ’ Ἄτταλος· ἐκ μὲν οὖν τοῦ Εὐμένους ἐγένετο ὁμώνυμος τῷ πατρὶ Εὐμένης, ὅσπερ καὶ διεδέξατο τὸ Πέργαμον, καὶ ἦν ἤδη δυνάστης τῶν κύκλῳ χωρίων ὥστε καὶ περὶ Σάρδεις ἐνίκησε μάχῃ συμβαλὼν Ἀντίοχον τὸν Σελεύκου· δύο δὲ καὶ εἴκοσιν ἄρξας ἔτη τελευτᾷ τὸν βίον. ἐκ δὲ Ἀττάλου καὶ Ἀντιοχίδος τῆς Ἀχαιοῦ γεγονὼς Ἄτταλος διεδέξατο τὴν ἀρχήν, καὶ ἀνηγορεύθη βασιλεὺς πρῶτος νικήσας Γαλάτας μάχῃ μεγάλῃ. οὗτος δὲ καὶ Ῥωμαίοις κατέστη φίλος καὶ συνεπολέμησε πρὸς Φίλιππον μετὰ τοῦ Ῥοδίων ναυτικοῦ· γηραιὸς δὲ ἐτελεύτα βασιλεύσας ἔτη τρία καὶ τετταράκοντα, κατέλιπε δὲ τέτταρας υἱοὺς ἐξ Ἀπολλωνίδος Κυζικηνῆς γυναικός, Εὐμένη Ἄτταλον Φιλέταιρον Ἀθήναιον. οἱ μὲν οὖν νεώτεροι διετέλεσαν ἰδιῶται, τῶν δ’ ἄλλων ὁ πρεσβύτερος Εὐμένης ἐβασίλευσε· συνεπολέμησε δὲ οὗτος Ῥωμαίοις πρός τε Ἀντίοχον τὸν μέγαν καὶ πρὸς Περσέα, καὶ ἔλαβε παρὰ τῶν Ῥωμαίων ἅπασαν τὴν ὑπ’ Ἀντιόχῳ τὴν ἐντὸς τοῦ Ταύρου. πρότερον δ’ ἦν τὰ περὶ Πέργαμον οὐ πολλὰ χωρία μέχρι τῆς θαλάττης τῆς κατὰ τὸν Ἐλαΐτην κόλπον καὶ τὸν Ἀδραμυττηνόν. κατεσκεύασε δ’ οὗτος τὴν πόλιν καὶ τὸ Νικηφόριον ἄλσει κατεφύτευσε, καὶ ἀναθήματα καὶ βιβλιοθήκας καὶ τὴν ἐπὶ τοσόνδε κατοικίαν τοῦ Περγάμου τὴν νῦν οὖσαν ἐκεῖνος προσεφιλοκάλησε· βασιλεύσας [δὲ] ἔτη τετταράκοντα καὶ ἐννέα ἀπέλιπεν υἱῷ τὴν ἀρχὴν Ἀττάλῳ, γεγονότι ἐκ Στρατονίκης τῆς Ἀριαράθου θυγατρὸς τοῦ Καππαδόκων βασιλέως. ἐπίτροπον δὲ κατέστησε καὶ τοῦ παιδὸς νέου τελέως ὄντος καὶ τῆς ἀρχῆς τὸν ἀδελφὸν Ἄτταλον. ἓν δὲ καὶ εἴκοσιν ἔτη βασιλεύσας γέρων οὗτος τελευτᾷ κατορθώσας πολλά· καὶ γὰρ Δημήτριον τὸν Σελεύκου συγκατεπολέμησεν Ἀλεξάνδρῳ τῷ Ἀντιόχου καὶ συνεμάχησε Ῥωμαίοις ἐπὶ τὸν Ψευδοφίλιππον, ἐχειρώσατο δὲ καὶ Διήγυλιν τὸν Καινῶν βασιλέα στρατεύσας εἰς τὴν Θρᾴκην, ἀνεῖλε δὲ καὶ Προυσίαν ἐπισυστήσας αὐτῷ Νικομήδη τὸν υἱόν, κατέλιπε δὲ τὴν ἀρχὴν τῷ ἐπιτροπευθέντι Ἀττάλῳ· βασιλεύσας δὲ οὗτος ἔτη πέντε καὶ κληθεὶς Φιλομήτωρ ἐτελεύτα νόσῳ τὸν βίον, κατέλιπε δὲ κληρονόμους Ῥωμαίους· οἱ δ’ ἐπαρχίαν ἀπέδειξαν τὴν χώραν Ἀσίαν προσαγορεύσαντες ὁμώνυμον τῇ ἠπείρῳ. παραρρεῖ δ’ ὁ Κάικος τὸ Πέργαμον, διὰ τοῦ Καΐκου πεδίου προσαγορευομένου σφόδρα εὐδαίμονα γῆν διεξιὼν σχεδὸν δέ τι καὶ τὴν ἀρίστην τῆς Μυσίας.", "st": "13.4.2"}, {"sp": "N", "t": "ἄνδρες δ’ ἐγένοντο ἐλλόγιμοι καθ’ ἡμᾶς Περγαμηνοὶ Μιθριδάτης τε Μηνοδότου υἱὸς καὶ Ἀδοβογιωνίδος τοῦ τετραρχικοῦ τῶν Γαλατῶν γένους, ἣν καὶ παλλακεῦσαι τῷ βασιλεῖ Μιθριδάτῃ φασίν· ὅθεν καὶ τοὔνομα τῷ παιδὶ θέσθαι τοὺς ἐπιτηδείους προσποιησαμένους ἐκ τοῦ βασιλέως αὐτὸν γεγονέναι. οὗτος γοῦν Καίσαρι τῷ θεῷ γενόμενος φίλος εἰς τοσόνδε προῆλθε τιμῆς ὥστε καὶ τετράρχης ἀπεδείχθη [ἀπὸ] τοῦ μητρῴου γένους καὶ βασιλεὺς ἄλλων τε καὶ τοῦ Βοσπόρου· κατελύθη δ’ ὑπὸ Ἀσάνδρου τοῦ καὶ Φαρνάκην ἀνελόντος τὸν βασιλέα καὶ κατασχόντος τὸν Βόσπορον. οὗτός τε δὴ ὀνόματος ἠξίωται μεγάλου, καὶ Ἀπολλόδωρος ὁ ῥήτωρ ὁ τὰς τέχνας συγγράψας καὶ τὴν Ἀπολλοδώρειον αἵρεσιν παραγαγών, ἥτις ποτ’ ἐστί· πολλὰ γὰρ ἐπεκράτει, μείζονα δὲ ἢ καθ’ ἡμᾶς ἔχοντα τὴν κρίσιν, ὧν ἔστι καὶ ἡ Ἀπολλοδώρειος αἵρεσις καὶ ἡ Θεοδώρειος. μάλιστα δὲ ἐξῆρε τὸν Ἀπολλόδωρον ἡ τοῦ Καίσαρος φιλία τοῦ Σεβαστοῦ, διδάσκαλον τῶν λόγων γενόμενον· μαθητὴν δ’ ἔσχεν ἀξιόλογον Διονύσιον τὸν ἐπικληθέντα Ἀττικόν, πολίτην αὐτοῦ· καὶ γὰρ σοφιστὴς ἦν ἱκανὸς καὶ συγγραφεὺς καὶ λογογράφος.", "st": "13.4.3"}, {"sp": "N", "t": "προϊόντι δ’ ἀπὸ τοῦ πεδίου καὶ τῆς πόλεως ἐπὶ μὲν τὰ πρὸς ἕω μέρη πόλις ἐστὶν Ἀπολλωνία, μετεώροις ἐπικειμένη τόποις· ἐπὶ δὲ τὸν νότον ὀρεινὴ ῥάχις ἐστίν, ἣν ὑπερβᾶσι καὶ βαδίζουσιν ἐπὶ Σάρδεων πόλις ἐστὶν ἐν ἀριστερᾷ Θυάτειρα, κατοικία Μακεδόνων, ἣν Μυσῶν ἐσχάτην τινὲς φασίν. ἐν δεξιᾷ δ’ Ἀπολλωνίς, διέχουσα Περγάμου τριακοσίους σταδίους, τοὺς δὲ ἴσους καὶ τῶν Σάρδεων· ἐπώνυμος δ’ ἐστὶ τῆς Κυζικηνῆς Ἀπολλωνίδος· εἶτ’ ἐκδέχεται τὸ Ἕρμου πεδίον καὶ Σάρδεις· τὰ δὲ προσάρκτια τῷ Περγάμῳ τὰ πλεῖστα ὑπὸ Μυσῶν ἔχεται τὰ ἐν δεξιᾷ τῶν Ἀβαειτῶν λεγομένων, οἷς συνάπτει ἡ Ἐπίκτητος μέχρι Βιθυνίας.", "st": "13.4.4"}, {"sp": "N", "t": "αἱ δὲ Σάρδεις πόλις ἐστὶ μεγάλη, νεωτέρα μὲν τῶν Τρωικῶν ἀρχαία δ’ ὅμως, ἄκραν ἔχουσα εὐερκῆ· βασίλειον δ’ ὑπῆρξε τῶν Λυδῶν, οὓς ὁ ποιητὴς καλεῖ Μῄονας οἱ δ’ ὕστερον Μαίονας, οἱ μὲν τοὺς αὐτοὺς τοῖς Λυδοῖς οἱ δ’ ἑτέρους ἀποφαίνοντες· τοὺς δ’ αὐτοὺς ἄμεινόν ἐστι λέγειν. ὑπέρκειται δὲ τῶν Σάρδεων ὁ Τμῶλος, εὔδαιμον ὄρος, ἐν τῇ ἀκρωρείᾳ σκοπὴν ἔχον, ἐξέδραν λευκοῦ λίθου, Περσῶν ἔργον, ἀφ’ οὗ κατοπτεύεται τὰ κύκλῳ πεδία καὶ μάλιστα τὸ Καϋστριανόν· περιοικοῦσι δὲ Λυδοὶ καὶ Μυσοὶ καὶ Μακεδόνες. ῥεῖ δ’ ὁ Πακτωλὸς ἀπὸ τοῦ Τμώλου, καταφέρων τὸ παλαιὸν ψῆγμα χρυσοῦ πολύ, ἀφ’ οὗ τὸν Κροίσου λεγόμενον πλοῦτον καὶ τῶν προγόνων αὐτοῦ διονομασθῆναί φασι· νῦν δ’ ἐκλέλοιπε τὸ ψῆγμα, ὡς εἴρηται. καταφέρεται δ’ ὁ Πακτωλὸς εἰς τὸν Ἕρμον, εἰς ὃν καὶ ὁ Ὕλλος ἐμβάλλει, Φρύγιος νυνὶ καλούμενος· συμπεσόντες δ’ οἱ τρεῖς καὶ ἄλλοι ἀσημότεροι σὺν αὐτοῖς εἰς τὴν κατὰ Φώκαιαν ἐκδιδόασι θάλατταν, ὡς Ἡρόδοτός φησιν. ἄρχεται δ’ ἐκ Μυσίας ὁ Ἕρμος, ἐξ ὄρους ἱεροῦ τῆς Δινδυμήνης, καὶ διὰ τῆς Κατακεκαυμένης εἰς τὴν Σαρδιανὴν φέρεται καὶ τὰ συνεχῆ πεδία μέχρι τῆς θαλάττης. ὑπόκειται δὲ τῇ πόλει τό τε Σαρδιανὸν πεδίον καὶ τὸ τοῦ Κύρου καὶ τὸ τοῦ Ἕρμου καὶ τὸ Καϋστριανόν, συνεχῆ τε ὄντα καὶ πάντων ἄριστα πεδίων. ἐν δὲ σταδίοις τετταράκοντα ἀπὸ τῆς πόλεως ἔστιν ἡ Γυγαία μὲν ὑπὸ τοῦ ποιητοῦ λεγομένη [λίμνη], Κολόη δ’ ὕστερον μετονομασθεῖσα, ὅπου τὸ ἱερὸν τῆς Κολοηνῆς Ἀρτέμιδος μεγάλην ἁγιστείαν ἔχον. φασὶ δ’ ἐνταῦθα χορεύειν τοὺς καλάθους κατὰ τὰς ἑορτάς, οὐκ οἶδ’ ὅπως ποτὲ παραδοξολογοῦντες μᾶλλον ἢ ἀληθεύοντες.", "st": "13.4.5"}, {"sp": "N", "t": "κειμένων δ’ οὕτω πως τῶν ἐπῶν παρ’ Ὁμήρῳ<br>Μῄοσιν αὖ Μέσθλης τε καὶ Ἄντιφος ἡγησάσθην,<br>υἷε Ταλαιμένεος, τὼ Γυγαίη τέκε λίμνη,<br>οἳ καὶ Μῄονας ἦγον ὑπὸ Τμώλῳ γεγαῶτας,<br>προσγράφουσί τινες τοῦτο τέταρτον ἔπος<br>Τμώλῳ ὑπὸ νιφόεντι, Ὕδης ἐν πίονι δήμῳ.<br>οὐδεμία δ’ εὑρίσκεται Ὕδη ἐν τοῖς Λυδοῖς. οἱ δὲ καὶ τὸν Τυχίον ἐνθένδε ποιοῦσιν ὅν φησιν ὁ ποιητής<br>σκυτοτόμων ὄχ’ ἄριστος Ὕδῃ ἔνι.<br>προστιθέασι δὲ καὶ διότι δρυμώδης ὁ τόπος καὶ κεραυνόβολος, καὶ ὅτι ἐνταῦθα οἱ Ἄριμοι· καὶ γὰρ τῷ<br>εἰν Ἀρίμοις, ὅθι φασὶ Τυφωέος ἔμμεναι εὐνάς<br>ἐπεισφέρουσι<br>χώρῳ ἐνὶ δρυόεντι, Ὕδης ἐν πίονι δήμῳ.<br>ἄλλοι δ’ ἐν Κιλικίᾳ, τινὲς δ’ ἐν Συρία πλάττουσι τὸν μῦθον τοῦτον, οἱ δ’ ἐν Πιθηκούσσαις, οἳ καὶ τοὺς πιθήκους φασὶ παρὰ τοῖς Τυρρηνοῖς ἀρίμους καλεῖσθαι· οἱ δὲ τὰς Σάρδεις Ὕδην ὀνομάζουσιν, οἱ δὲ τὴν ἀκρόπολιν αὐτῆς. πιθανωτάτους δ’ ὁ Σκήψιος ἡγεῖται τοὺς ἐν τῇ Κατακεκαυμένῃ τῆς Μυσίας τοὺς Ἀρίμους τιθέντας. Πίνδαρος δὲ συνοικειοῖ τοῖς ἐν τῇ Κιλικίᾳ τὰ ἐν Πιθηκούσσαις, ἅπερ ἐστὶ πρὸ τῆς Κυμαίας, καὶ τὰ ἐν Σικελίᾳ· καὶ γὰρ τῇ Αἴτνῃ φησὶν ὑποκεῖσθαι τὸν Τυφῶνα<br>τόν ποτε<br>Κιλίκιον θρέψεν πολυώνυμον ἄντρον· νῦν γε μὰν<br>ταί θ’ ὑπὲρ Κύμας ἁλιερκέες ὄχθαι<br>Σικελία τ’ αὐτοῦ πιέζει στέρνα λαχνάεντα.<br>καὶ πάλιν<br>κείνῳ μὲν Αἴτνα δεσμὸς ὑπερφίαλος<br>ἀμφίκειται.<br>καὶ πάλιν<br>ἀλλ’ οἶος ἄπλατον κεράιζε θεῶν<br>Τυφῶνα πεντηκοντακάρανον ἀνάγκᾳ Ζεὺς πατὴρ<br>ἐν Ἀρίμοις ποτέ.<br>οἱ δὲ τοὺς Σύρους Ἀρίμους δέχονται, οὓς νῦν Ἀραμαίους λέγουσι, τοὺς δὲ Κίλικας τοὺς ἐν Τροίᾳ μεταναστάντας εἰς Συρίαν ἀνῳκισμένους ἀποτεμέσθαι παρὰ τῶν Σύρων τὴν νῦν λεγομένην Κιλικίαν. Καλλισθένης δ’ ἐγγὺς τοῦ Καλυκάδνου καὶ τῆς Σαρπηδόνος ἄκρας παρ’ αὐτὸ τὸ Κωρύκιον ἄντρον εἶναι τοὺς Ἀρίμους, ἀφ’ ὧν τὰ ἐγγὺς ὄρη λέγεσθαι Ἄριμα.", "st": "13.4.6"}, {"sp": "N", "t": "περίκειται δὲ τῇ λίμνῃ τῇ Κολόῃ τὰ μνήματα τῶν βασιλέων· πρὸς δὲ ταῖς Σάρδεσιν ἔστι τὸ τοῦ Ἀλυάττου ἐπὶ κρηπῖδος ὑψηλῆς χῶμα μέγα, ἐργασθέν, ὥς φησιν Ἡρόδοτος, ὑπὸ τοῦ πλήθους τῆς πόλεως, οὗ τὸ πλεῖστον ἔργον αἱ παιδίσκαι συνετέλεσαν· λέγει δ’ ἐκεῖνος καὶ πορνεύεσθαι πάσας· τινὲς δὲ καὶ πόρνης μνῆμα λέγουσι τὸν τάφον. χειροποίητον δὲ τὴν λίμνην ἔνιοι ἱστοροῦσι τὴν Κολόην πρὸς τὰς ἐκδοχὰς τῶν πλημμυρίδων, αἳ συμβαίνουσι τῶν ποταμῶν πληρουμένων. Ὕπαιπα δὲ πόλις ἐστὶ καταβαίνουσιν ἀπὸ τοῦ Τμώλου πρὸς τὸ τοῦ Καΰστρου πεδίον.", "st": "13.4.7"}, {"sp": "N", "t": "φησὶ δὲ Καλλισθένης ἁλῶναι τὰς Σάρδεις ὑπὸ Κιμμερίων πρῶτον, εἶθ’ ὑπὸ Τρηρῶν καὶ Λυκίων, ὅπερ καὶ Καλλῖνον δηλοῦν τὸν τῆς ἐλεγείας ποιητήν, ὕστατα δὲ τὴν ἐπὶ Κύρου καὶ Κροίσου γενέσθαι ἅλωσιν. λέγοντος δὲ τοῦ Καλλίνου τὴν ἔφοδον τῶν Κιμμερίων ἐπὶ τοὺς Ἠσιονῆας γεγονέναι καθ’ ἣν αἱ Σάρδεις ἑάλωσαν, εἰκάζουσιν οἱ περὶ τὸν Σκήψιον ἰαστὶ λέγεσθαι Ἠσιονεῖς τοὺς Ἀσιονεῖς· “τάχα γὰρ ἡ Μῃονία” φησίν “Ἀσία ἐλέγετο, καθ’ ὃ καὶ Ὅμηρος εἴρηκεν<br>Ἀσίῳ ἐν λειμῶνι Καϋστρίου ἀμφὶ ῥέεθρα.” ἀναληφθεῖσα δ’ ἀξιολόγως ὕστερον διὰ τὴν ἀρετὴν τῆς χώρας ἡ πόλις καὶ οὐδεμιᾶς λειπομένη τῶν ἀστυγειτόνων, νεωστὶ ὑπὸ σεισμῶν ἀπέβαλε πολλὴν τῆς κατοικίας. ἡ δὲ τοῦ Τιβερίου πρόνοια τοῦ καθ’ ἡμᾶς ἡγεμόνος καὶ ταύτην καὶ τῶν ἄλλων συχνὰς ἀνέλαβε ταῖς εὐεργεσίαις, ὅσαι περὶ τὸν αὐτὸν καιρὸν ἐκοινώνησαν τοῦ αὐτοῦ πάθους.", "st": "13.4.8"}, {"sp": "N", "t": "ἄνδρες δ’ ἀξιόλογοι γεγόνασι τοῦ αὐτοῦ γένους Διόδωροι δύο οἱ ῥήτορες, ὧν ὁ πρεσβύτερος ἐκαλεῖτο Ζωνᾶς, ἀνὴρ πολλοὺς ἀγῶνας ἠγωνισμένος ὑπὲρ τῆς Ἀσίας, κατὰ δὲ τὴν Μιθριδάτου τοῦ βασιλέως ἔφοδον αἰτίαν ἐσχηκὼς ὡς ἀφιστὰς παρ’ αὐτοῦ τὰς πόλεις ἀπελύσατο τὰς διαβολὰς ἀπολογησάμενος· τοῦ δὲ νεωτέρου φίλου ἡμῖν γενομένου καὶ ἱστορικὰ συγγράμματα ἔστι καὶ μέλη καὶ ἄλλα ποιήματα τὴν ἀρχαίαν γραφὴν ἐπιφαίνοντα ἱκανῶς. Ξάνθος δὲ ὁ παλαιὸς συγγραφεὺς Λυδὸς μὲν λέγεται, εἰ δὲ ἐκ Σάρδεων οὐκ ἴσμεν.", "st": "13.4.9"}, {"sp": "N", "t": "μετὰ δὲ Λυδούς εἰσιν οἱ Μυσοὶ καὶ πόλις Φιλαδέλφεια σεισμῶν πλήρης. οὐ γὰρ διαλείπουσιν οἱ τοῖχοι διιστάμενοι καὶ ἄλλοτ’ ἄλλο μέρος τῆς πόλεως κακοπαθοῦν· οἰκοῦσιν οὖν ὀλίγοι διὰ τοῦτο τὴν πόλιν, οἱ δὲ πολλοὶ καταβιοῦσιν ἐν τῇ χώρᾳ γεωργοῦντες, ἔχοντες εὐδαίμονα γῆν· ἀλλὰ καὶ τῶν ὀλίγων θαυμάζειν ἔστιν ὅτι οὕτω φιλοχωροῦσιν, ἐπισφαλεῖς τὰς οἰκήσεις ἔχοντες· ἔτι δ’ ἄν τις μᾶλλον θαυμάσειε τῶν κτισάντων αὐτήν.", "st": "13.4.10"}, {"sp": "N", "t": "μετὰ δὲ ταῦτ’ ἔστιν ἡ Κατακεκαυμένη λεγομένη χώρα μῆκος μὲν καὶ πεντακοσίων σταδίων πλάτος δὲ τετρακοσίων, εἴτε Μυσίαν χρὴ καλεῖν εἴτε Μῃονίαν (λέγεται γὰρ ἀμφοτέρως), ἅπασα ἄδενδρος πλὴν ἀμπέλου τῆς τὸν Κατακεκαυμενίτην φερούσης οἶνον οὐδενὸς τῶν ἐλλογίμων ἀρετῇ λειπόμενον. ἔστι δὲ ἡ ἐπιφάνεια τεφρώδης τῶν πεδίων, ἡ δ’ ὀρεινὴ καὶ πετρώδης μέλαινα ὡς ἂν ἐξ ἐπικαύσεως. εἰκάζουσι μὲν οὖν τινες ἐκ κεραυνοβολιῶν καὶ πρηστήρων συμβῆναι τοῦτο, καὶ οὐκ ὀκνοῦσι τὰ περὶ τὸν Τυφῶνα ἐνταῦθα μυθολογεῖν. Ξάνθος δὲ καὶ Ἀριμοῦν τινα λέγει τῶν τόπων τούτων βασιλέα. οὐκ εὔλογον δὲ ὑπὸ τοιούτων παθῶν τὴν τοσαύτην χώραν ἐμπρησθῆναι ἀθρόως, ἀλλὰ μᾶλλον ὑπὸ γηγενοῦς πυρός, ἐκλιπεῖν δὲ νῦν τὰς πηγάς· δείκνυνται δὲ καὶ βόθροι τρεῖς, οὓς φύσας καλοῦσιν, ὅσον τετταράκοντα ἀλλήλων διεστῶτες σταδίους· ὑπέρκεινται δὲ λόφοι τραχεῖς, οὓς εἰκὸς ἐκ τῶν ἀναφυσηθέντων σεσωρεῦσθαι μύδρων. τὸ δ’ εὐάμπελον τὴν τοιαύτην ὑπάρχειν γῆν, λάβοι τις ἂν καὶ ἐκ τῆς Καταναίας τῆς χωσθείσης τῇ σποδῷ καὶ νῦν ἀποδιδούσης οἶνον δαψιλῆ καὶ καλόν. ἀστεϊζόμενοι δέ τινες εἰκότως πυριγενῆ τὸν Διόνυσον λέγεσθαί φασιν, ἐκ τῶν τοιούτων χωρίων τεκμαιρόμενοι.", "st": "13.4.11"}, {"sp": "N", "t": "τὰ δ’ ἑξῆς ἐπὶ τὰ νότια μέρη τοῖς τόποις τούτοις ἐμπλοκὰς ἔχει μέχρι πρὸς τὸν Ταῦρον, ὥστε καὶ τὰ Φρύγια καὶ τὰ Καρικὰ καὶ τὰ Λύδια καὶ ἔτι τὰ τῶν Μυσῶν δυσδιάκριτα εἶναι παραπίπτοντα εἰς ἄλληλα· εἰς δὲ τὴν σύγχυσιν ταύτην οὐ μικρὰ συλλαμβάνει τὸ τοὺς Ῥωμαίους μὴ κατὰ φῦλα διελεῖν αὐτούς, ἀλλὰ ἕτερον τρόπον διατάξαι τὰς διοικήσεις, ἐν αἷς τὰς ἀγοραίους ποιοῦνται καὶ τὰς δικαιοδοσίας. ὁ μέν γε Τμῶλος ἱκανῶς συνῆκται καὶ περιγραφὴν ἔχει μετρίαν ἐν αὐτοῖς ἀφοριζόμενος τοῖς Λυδίοις μέρεσιν, ἡ δὲ Μεσωγὶς εἰς τὸ ἀντικείμενον μέρος διατείνει μέχρι Μυκάλης ἀπὸ Κελαινῶν ἀρξάμενον, ὥς φησι Θεόπομπος, ὥστε τὰ μὲν αὐτοῦ Φρύγες κατέχουσι τὰ πρὸς ταῖς Κελαιναῖς καὶ τῇ Ἀπαμείᾳ, τὰ δὲ Μυσοὶ καὶ Λυδοί, τὰ δὲ Κᾶρες καὶ Ἴωνες. οὕτω δὲ καὶ οἱ ποταμοὶ καὶ μάλιστα ὁ Μαίανδρος τὰ μὲν διορίζοντες τῶν ἐθνῶν, δι’ ὧν δὲ μέσοι φερόμενοι δύσληπτον ποιοῦσι τἀκριβές· καὶ περὶ τῶν πεδίων δὲ τῶν ἐφ’ ἑκάτερα τῆς τε ὀρεινῆς καὶ τῆς ποταμίας ὁ αὐτὸς λόγος. οὐδ’ ἡμῖν ἴσως ἐπὶ τοσοῦτον φροντιστέον ὡς ἀναγκαῖον χωρομετροῦσιν, ἀλλὰ τοσοῦτον μόνον ὑπογραπτέον ὅσον καὶ οἱ πρὸ ἡμῶν παραδεδώκασι.", "st": "13.4.12"}, {"sp": "N", "t": "τῷ δὴ Καϋστριανῷ πεδίῳ μεταξὺ πίπτοντι τῆς τε Μεσωγίδος καὶ τοῦ Τμώλου συνεχές ἐστι πρὸς ἕω τὸ Κιλβιανὸν πεδίον πολύ τε καὶ συνοικούμενον εὖ καὶ χώραν ἔχον σπουδαίαν· εἶτα τὸ Ὑρκάνιον πεδίον, Περσῶν ἐπονομασάντων καὶ ἐποίκους ἀγαγόντων ἐκεῖθεν (ὁμοίως δὲ καὶ τὸ Κύρου πεδίον Πέρσαι κατωνόμασαν)· εἶτα τὸ Πελτηνὸν πεδίον, ἤδη Φρύγιον, καὶ τὸ Κιλλάνιον καὶ τὸ Ταβηνόν, ἔχοντα πολίχνας μιξοφρυγίους ἐχούσας τι καὶ Πισιδικόν, ἀφ’ ὧν αὐτὰ κατωνομάσθη.", "st": "13.4.13"}, {"sp": "N", "t": "ὑπερβαλοῦσι δὲ τὴν Μεσωγίδα τὴν μεταξὺ Καρῶν τε καὶ τῆς Νυσαΐδος, ἥ ἐστι χώρα κατὰ τὰ τοῦ Μαιάνδρου πέραν μέχρι τῆς Κιβυράτιδος καὶ τῆς Καβαλίδος, πόλεις εἰσὶ πρὸς μὲν τῇ Μεσωγίδι καταντικρὺ Λαοδικείας Ἱερὰ πόλις, ὅπου τὰ θερμὰ ὕδατα καὶ τὸ Πλουτώνιον, ἄμφω παραδοξολογίαν τινὰ ἔχοντα· τὸ μὲν γὰρ ὕδωρ οὕτω ῥᾳδίως εἰς πῶρον μεταβάλλει πηττόμενον ὥστ’ ὀχετοὺς ἐπάγοντες φραγμοὺς ἀπεργάζονται μονολίθους, τὸ δὲ Πλουτώνιον ὑπ’ ὀφρύι μικρᾷ τῆς ὑπερκειμένης ὀρεινῆς στόμιόν ἐστι σύμμετρον ὅσον ἄνθρωπον δέξασθαι δυνάμενον, βεβάθυνται δ’ ἐπὶ πολύ· πρόκειται δὲ τούτου δρυφάκτωμα τετράγωνον ὅσον ἡμιπλέθρου τὴν περίμετρον· τοῦτο δὲ πλῆρές ἐστιν ὁμιχλώδους παχείας ἀχλύος ὥστε μόγις τοὔδαφος καθορᾶν. τοῖς μὲν οὖν κύκλῳ πλησιάζουσι πρὸς τὸν δρύφακτον ἄλυπός ἐστιν ὁ ἀήρ, καθαρεύων ἐκείνης τῆς ἀχλύος ἐν ταῖς νηνεμίαις· συμμένει γὰρ ἐντὸς τοῦ περιβόλου· τῷ δ’ εἴσω παριόντι ζῴῳ θάνατος παραχρῆμα ἀπαντᾷ· ταῦροι γοῦν εἰσαχθέντες πίπτουσι καὶ ἐξέλκονται νεκροί, ἡμεῖς δὲ στρουθία ἐπέμψαμεν καὶ ἔπεσεν εὐθὺς ἐκπνεύσαντα· οἱ δ’ ἀπόκοποι Γάλλοι παρίασιν ἀπαθεῖς, ὥστε καὶ μέχρι τοῦ στομίου πλησιάζειν καὶ ἐγκύπτειν καὶ καταδύνειν μέχρι ποσοῦ συνέχοντας ὡς ἐπὶ τὸ πολὺ τὸ πνεῦμα· ἑωρῶμεν γὰρ ἐκ τῆς ὄψεως ὡς ἂν πνιγώδους τινὸς πάθους ἔμφασιν, εἴτ’ ἐπὶ πάντων [τῶν] οὕτω πεπηρωμένων τοῦτο εἴτε μόνων τῶν περὶ τὸ ἱερόν, καὶ εἴτε θείᾳ προνοίᾳ, καθάπερ ἐπὶ τῶν ἐνθουσιασμῶν εἰκός, εἴτε ἀντιδότοις τισὶ δυνάμεσι τούτου συμβαίνοντος. τὸ δὲ τῆς ἀπολιθώσεως καὶ ἐπὶ τῶν ἐν Λαοδικείᾳ ποταμῶν φασι συμβαίνειν καίπερ ὄντων ποτίμων. ἔστι δὲ καὶ πρὸς βαφὴν ἐρίων θαυμαστῶς σύμμετρον τὸ κατὰ τὴν Ἱερὰν πόλιν ὕδωρ, ὥστε τὰ ἐκ τῶν ῥιζῶν βαπτόμενα ἐνάμιλλα εἶναι τοῖς ἐκ τῆς κόκκου καὶ τοῖς ἁλουργέσιν· οὕτω δ’ ἐστὶν ἄφθονον τὸ πλῆθος τοῦ ὕδατος ὥστε ἡ πόλις μεστὴ τῶν αὐτομάτων βαλανείων ἐστί.", "st": "13.4.14"}, {"sp": "N", "t": "μετὰ δὲ τὴν Ἱερὰν πόλιν τὰ πέραν τοῦ Μαιάνδρου. τὰ μὲν οὖν περὶ Λαοδίκειαν καὶ Ἀφροδισιάδα καὶ τὰ μέχρι Καρούρων εἴρηται· τὰ δ’ ἑξῆς ἐστι τὰ μὲν πρὸς δύσιν ἡ τῶν Ἀντιοχέων πόλις τῶν ἐπὶ Μαιάνδρῳ, τῆς Καρίας ἤδη· τὰ δὲ πρὸς νότον ἡ Κιβύρα ἐστὶν ἡ μεγάλη καὶ ἡ Σίνδα καὶ ἡ Καβαλὶς μέχρι τοῦ Ταύρου καὶ τῆς Λυκίας. ἡ μὲν οὖν Ἀντιόχεια μετρία πόλις ἐστὶν ἐπ’ αὐτῷ κειμένη τῷ Μαιάνδρῳ κατὰ τὸ πρὸς τῇ Φρυγίᾳ μέρος, ἐπέζευκται δὲ γέφυρα· χώραν δ’ ἔχει πολλὴν ἐφ’ ἑκάτερα τοῦ ποταμοῦ πᾶσαν εὐδαίμονα, πλείστην δὲ φέρει τὴν καλουμένην Ἀντιοχικὴν ἰσχάδα· τὴν δὲ αὐτὴν καὶ τρίφυλλον ὀνομάζουσιν· εὔσειστος δὲ καὶ οὗτός ἐστιν ὁ τόπος. σοφιστὴς δὲ παρὰ τούτοις ἔνδοξος γεγένηται Διοτρέφης, οὗ διήκουσεν Ὑβρέας ὁ καθ’ ἡμᾶς γενόμενος μέγιστος ῥήτωρ.", "st": "13.4.15"}, {"sp": "N", "t": "Σολύμους δ’ εἶναί φασι τοὺς Καβαλεῖς· τῆς γοῦν Τερμησσέων ἄκρας ὁ ὑπερκείμενος λόφος καλεῖται Σόλυμος, καὶ αὐτοὶ δὲ οἱ Τερμησσεῖς Σόλυμοι καλοῦνται. πλησίον δ’ ἐστὶ καὶ ὁ Βελλεροφόντου χάραξ καὶ ὁ Πεισάνδρου τάφος τοῦ υἱοῦ [αὐτοῦ] πεσόντος ἐν τῇ πρὸς Σολύμους μάχῃ. ταῦτα δὲ καὶ τοῖς ὑπὸ τοῦ ποιητοῦ λεγομένοις ὁμολογεῖται· περὶ μὲν γὰρ τοῦ Βελλεροφόντου φησὶν οὕτως<br>δεύτερον αὖ Σολύμοισι μαχέσσατο κυδαλίμοισι.<br>περὶ δὲ τοῦ παιδὸς αὐτοῦ<br>Πείσανδρον δέ οἱ υἱὸν Ἄρης ἆτος πολέμοιο<br>μαρνάμενον Σολύμοισι κατέκτανεν.<br>ἡ δὲ Τερμησσός ἐστι Πισιδικὴ πόλις ἡ μάλιστα καὶ ἔγγιστα ὑπερκειμένη τῆς Κιβύρας.", "st": "13.4.16"}, {"sp": "N", "t": "λέγονται δὲ ἀπόγονοι Λυδῶν οἱ Κιβυρᾶται τῶν κατασχόντων τὴν Καβαλίδα· ὕστερον δὲ Πισιδῶν τῶν ὁμόρων ἐποικησάντων καὶ μετακτισάντων εἰς ἕτερον τόπον εὐερκέστατον ἐν κύκλῳ σταδίων περὶ ἑκατόν. ηὐξήθη δὲ διὰ τὴν εὐνομίαν, καὶ αἱ κῶμαι παρεξέτειναν ἀπὸ Πισιδίας καὶ τῆς ὁμόρου Μιλυάδος ἕως Λυκίας καὶ τῆς Ῥοδίων περαίας· προσγενομένων δὲ τριῶν πόλεων ὁμόρων, Βουβῶνος Βαλβούρων Οἰνοάνδων, τετράπολις τὸ σύστημα ἐκλήθη, μίαν ἑκάστης ψῆφον ἐχούσης, δύο δὲ τῆς Κιβύρας· ἔστελλε γὰρ αὕτη πεζῶν μὲν τρεῖς μυριάδας ἱππέας δὲ δισχιλίους· ἐτυραννεῖτο δ’ ἀεί, σωφρόνως δ’ ὅμως· ἐπὶ Μοαγέτου δ’ ἡ τυραννὶς τέλος ἔσχε, καταλύσαντος αὐτὴν Μουρηνᾶ καὶ Λυκίοις προσορίσαντος τὰ Βάλβουρα καὶ τὴν Βουβῶνα· οὐδὲν δ’ ἧττον ἐν ταῖς μεγίσταις ἐξετάζεται διοικήσεσι τῆς Ἀσίας ἡ Κιβυρατική. τέτταρσι δὲ γλώτταις ἐχρῶντο οἱ Κιβυρᾶται, τῇ Πισιδικῇ τῇ Σολύμων τῇ Ἑλληνίδι τῇ Λυδῶν· … δὲ οὐδ’ ἴχνος ἐστὶν ἐν Λυδίᾳ. ἴδιον δ’ ἐστὶν ἐν Κιβύρᾳ τὸ τὸν σίδηρον τορεύεσθαι ῥᾳδίως. Μιλύα δ’ ἐστὶν ἡ ἀπὸ τῶν κατὰ Τερμησσὸν στενῶν καὶ τῆς εἰς τὸ ἐντὸς τοῦ Ταύρου ὑπερθέσεως δι’ αὐτῶν ἐπὶ Ἴσινδα παρατείνουσα ὀρεινὴ μέχρι Σαγαλασσοῦ καὶ τῆς Ἀπαμέων χώρας.", "st": "13.4.17"}, {"sp": "HDR", "t": "Βιβλίον ΙΔʹ", "st": "14"}, {"sp": "N", "t": "λοιπὸν δ’ ἐστὶν εἰπεῖν περὶ Ἰώνων καὶ Καρῶν καὶ τῆς ἔξω τοῦ Ταύρου παραλίας, ἣν ἔχουσι Λύκιοί τε καὶ Πάμφυλοι καὶ Κίλικες· οὕτω γὰρ ἂν ἔχοι τέλος ἡ πᾶσα τῆς χερρονήσου περιήγησις, ἧς ἰσθμὸν ἔφαμεν τὴν ὑπέρβασιν τὴν ἐκ τῆς Ποντικῆς θαλάττης ἐπὶ τὴν Ἰσσικήν.", "st": "14.1.1"}, {"sp": "N", "t": "ἔστι δὲ τῆς Ἰωνίας ὁ μὲν περίπλους ὁ παρὰ γῆν σταδίων που τρισχιλίων τετρακοσίων τριάκοντα διὰ τοὺς κόλπους καὶ διὰ τὸ χερρονησίζειν ἐπὶ πλεῖον τὴν χώραν, τὸ δ’ ἐπ’ εὐθείας μῆκος οὐ πολύ. αὐτὸ οὖν τὸ ἐξ Ἐφέσου μέχρι Σμύρνης ὁδὸς μέν ἐστιν ἐπ’ εὐθείας τριακόσιοι εἴκοσι στάδιοι· εἰς γὰρ Μητρόπολιν ἑκατὸν καὶ εἴκοσι στάδιοι, οἱ λοιποὶ δὲ εἰς Σμύρναν· περίπλους δὲ μικρὸν ἀπολείπων τῶν δισχιλίων καὶ διακοσίων. ἔστι δ’ οὖν ἀπὸ τοῦ Ποσειδίου τοῦ Μιλησίων καὶ τῶν Καρικῶν ὅρων μέχρι Φωκαίας καὶ τοῦ Ἕρμου τὸ πέρας τῆς Ἰωνικῆς παραλίας.", "st": "14.1.2"}, {"sp": "N", "t": "ταύτης δέ φησι Φερεκύδης Μίλητον μὲν καὶ Μυοῦντα καὶ τὰ περὶ Μυκάλην καὶ Ἔφεσον Κᾶρας ἔχειν πρότερον, τὴν δ’ ἑξῆς παραλίαν μέχρι Φωκαίας καὶ Χίον καὶ Σάμον, ἧς Ἀγκαῖος ἦρχε, Λέλεγας· ἐκβληθῆναι δ’ ἀμφοτέρους ὑπὸ τῶν Ἰώνων καὶ εἰς τὰ λοιπὰ μέρη τῆς Καρίας ἐκπεσεῖν. ἄρξαι δέ φησιν Ἄνδροκλον τῆς τῶν Ἰώνων ἀποικίας, ὕστερον τῆς Αἰολικῆς, υἱὸν γνήσιον Κόδρου τοῦ Ἀθηνῶν βασιλέως, γενέσθαι δὲ τοῦτον Ἐφέσου κτίστην. διόπερ τὸ βασίλειον τῶν Ἰώνων ἐκεῖ συστῆναί φασι, καὶ ἔτι νῦν οἱ ἐκ τοῦ γένους ὀνομάζονται βασιλεῖς ἔχοντές τινας τιμάς, προεδρίαν τε ἐν ἀγῶσι καὶ πορφύραν ἐπίσημον τοῦ βασιλικοῦ γένους, σκίπωνα ἀντὶ σκήπτρου, καὶ τὰ ἱερὰ τῆς Ἐλευσινίας Δήμητρος. καὶ Μίλητον δ’ ἔκτισεν Νηλεὺς ἐκ Πύλου τὸ γένος ὤν· οἵ τε Μεσσήνιοι καὶ οἱ Πύλιοι συγγένειάν τινα προσποιοῦνται, καθ’ ἣν καὶ Μεσσήνιον τὸν Νέστορα οἱ νεώτεροί φασι ποιηταί, καὶ τοῖς περὶ Μέλανθον τὸν Κόδρου πατέρα πολλοὺς καὶ τῶν Πυλίων συνεξᾶραί φασιν εἰς τὰς Ἀθήνας· τοῦτον δὴ πάντα τὸν λαὸν μετὰ τῶν Ἰώνων κοινῇ στεῖλαι τὴν ἀποικίαν· τοῦ δὲ Νηλέως ἐπὶ τῷ Ποσειδίῳ βωμὸς ἵδρυμα δείκνυται. Κυδρῆλος δὲ νόθος υἱὸς Κόδρου Μυοῦντα κτίζει· Ἀνδρόπομπος δὲ Λέβεδον καταλαβόμενος τόπον τινὰ Ἄρτιν· Κολοφῶνα δ’ Ἀνδραίμων Πύλιος, ὥς φησι καὶ Μίμνερμος ἐν Ναννοῖ· Πριήνην δ’ Αἴπυτος ὁ Νηλέως, εἶθ’ ὕστερον Φιλωτᾶς ἐκ Θηβῶν λαὸν ἀγαγών· Τέω δὲ Ἀθάμας μὲν πρότερον, διόπερ Ἀθαμαντίδα καλεῖ αὐτὴν Ἀνακρέων, κατὰ δὲ τὴν Ἰωνικὴν ἀποικίαν Ναῦκλος υἱὸς Κόδρου νόθος, καὶ μετὰ τοῦτον Ἄποικος καὶ Δάμασος Ἀθηναῖοι καὶ Γέρης ἐκ Βοιωτῶν· Ἐρυθρὰς δὲ Κνῶπος, καὶ οὗτος υἱὸς Κόδρου νόθος· Φώκαιαν δ’ οἱ μετὰ Φιλογένους Ἀθηναῖοι· Κλαζομενὰς δὲ Πάραλος· Χίον δὲ Ἐγέρτιος, σύμμικτον ἐπαγαγόμενος πλῆθος· Σάμον δὲ Τεμβρίων, εἶθ’ ὕστερον Προκλῆς.", "st": "14.1.3"}, {"sp": "N", "t": "αὗται μὲν δώδεκα Ἰωνικαὶ πόλεις, προσελήφθη δὲ χρόνοις ὕστερον καὶ Σμύρνα εἰς τὸ Ἰωνικὸν ἐναγαγόντων Ἐφεσίων· ἦσαν γὰρ αὐτοῖς σύνοικοι τὸ παλαιόν, ἡνίκα καὶ Σμύρνα ἐκαλεῖτο ἡ Ἔφεσος· καὶ Καλλῖνός που οὕτως ὠνόμακεν αὐτήν, Σμυρναίους τοὺς Ἐφεσίους καλῶν ἐν τῷ πρὸς τὸν Δία λόγῳ<br>Σμυρναίους δ’ ἐλέησον<br>καὶ πάλιν<br>μνῆσαι δ’ εἴκοτέ τοι μηρία καλὰ βοῶν<br>[Σμυρναῖοι κατέκηαν].<br>Σμύρνα δ’ ἦν Ἀμαζὼν ἡ κατασχοῦσα τὴν Ἔφεσον, ἀφ’ ἧς τοὔνομα καὶ τοῖς ἀνθρώποις καὶ τῇ πόλει, ὡς καὶ ἀπὸ Σισύρβης Σισυρβῖται τινὲς τῶν Ἐφεσίων ἐλέγοντο· καὶ τόπος δέ τις τῆς Ἐφέσου Σμύρνα ἐκαλεῖτο, ὡς δηλοῖ Ἱππῶναξ<br>ᾤκει δ’ ὄπισθε τῆς πόλιος ἐνὶ Σμύρνῃ<br>μεταξὺ Τρηχείης τε καὶ Λεπρῆς ἀκτῆς.<br>ἐκαλεῖτο γὰρ Λεπρὴ μὲν ἀκτὴ ὁ πρηὼν ὁ ὑπερκείμενος τῆς νῦν πόλεως, ἔχων μέρος τοῦ τείχους αὐτῆς· τὰ γοῦν ὄπισθεν τοῦ πρηῶνος κτήματα ἔτι νυνὶ λέγεται ἐν τῇ Ὀπισθολεπρίᾳ· τραχεῖα δ’ ἐκαλεῖτο ἡ περὶ τὸν Κορησσὸν Παρώρειος. ἡ δὲ πόλις ἦν τὸ παλαιὸν περὶ τὸ Ἀθήναιον τὸ νῦν ἔξω τῆς πόλεως ὂν κατὰ τὴν καλουμένην Ὑπέλαιον, ὥστε ἡ Σμύρνα ἦν κατὰ τὸ νῦν γυμνάσιον ὄπισθεν μὲν τῆς τότε πόλεως, μεταξὺ δὲ Τρηχείης τε καὶ Λεπρῆς ἀκτῆς. ἀπελθόντες δὲ παρὰ τῶν Ἐφεσίων οἱ Σμυρναῖοι στρατεύουσιν ἐπὶ τὸν τόπον, ἐν ᾧ νῦν ἔστιν ἡ Σμύρνα, Λελέγων κατεχόντων· ἐκβαλόντες δ’ αὐτοὺς ἔκτισαν τὴν παλαιὰν Σμύρναν διέχουσαν τῆς νῦν περὶ εἴκοσι σταδίους. ὕστερον δὲ ὑπὸ Αἰολέων ἐκπεσόντες κατέφυγον εἰς Κολοφῶνα, καὶ μετὰ τῶν ἐνθένδε ἐπιόντες τὴν σφετέραν ἀπέλαβον· καθάπερ καὶ Μίμνερμος ἐν τῇ Ναννοῖ φράζει μνησθεὶς τῆς Σμύρνης ὅτι περιμάχητος ἀεί<br>ἡμεῖς δηὖτε Πύλον Νηλήιον ἄστυ λιπόντες<br>ἱμερτὴν Ἀσίην νηυσὶν ἀφικόμεθα·<br>ἐς δ’ ἐρατὴν Κολοφῶνα βίην ὑπέροπλον ἔχοντες<br>ἑζόμεθ’ ἀργαλέης ὕβριος ἡγεμόνες.<br>κεῖθεν δ’ ἀστήεντος ἀπορνύμενοι ποταμοῖο<br>θεῶν βουλῇ Σμύρνην εἵλομεν Αἰολίδα.<br>ταῦτα μὲν περὶ τούτων· ἐφοδευτέον δὲ πάλιν τὰ καθ’ ἕκαστα, τὴν ἀρχὴν ἀπὸ τῶν ἡγεμονικωτέρων τόπων ποιησαμένους, ἐφ’ ὧνπερ καὶ πρῶτον αἱ κτίσεις ἐγένοντο, λέγω δὲ τῶν περὶ Μίλητον καὶ Ἔφεσον· αὗται γὰρ ἄρισται πόλεις καὶ ἐνδοξόταται.", "st": "14.1.4"}, {"sp": "N", "t": "μετὰ δὲ τὸ Ποσείδιον τὸ Μιλησίων ἑξῆς ἐστι τὸ μαντεῖον τοῦ Διδυμέως Ἀπόλλωνος τὸ ἐν Βραγχίδαις ἀναβάντι ὅσον ὀκτωκαίδεκα σταδίους· ἐνεπρήσθη δ’ ὑπὸ Ξέρξου, καθάπερ καὶ τὰ ἄλλα ἱερὰ πλὴν τοῦ ἐν Ἐφέσῳ· οἱ δὲ Βραγχίδαι τοὺς θησαυροὺς τοῦ θεοῦ παραδόντες τῷ Πέρσῃ φεύγοντι συναπῆραν τοῦ μὴ τῖσαι δίκας τῆς ἱεροσυλίας καὶ τῆς προδοσίας. ὕστερον δ’ οἱ Μιλήσιοι μέγιστον νεὼν τῶν πάντων κατεσκεύασαν, διέμεινε δὲ χωρὶς ὀροφῆς διὰ τὸ μέγεθος· κώμης γοῦν κατοικίαν ὁ τοῦ σηκοῦ περίβολος δέδεκται καὶ ἄλσος ἐντός τε καὶ ἐκτὸς πολυτελές· ἄλλοι δὲ σηκοὶ τὸ μαντεῖον καὶ τὰ ἱερὰ συνέχουσιν· ἐνταῦθα δὲ μυθεύεται τὰ περὶ τὸν Βράγχον καὶ τὸν ἔρωτα τοῦ Ἀπόλλωνος· κεκόσμηται δ’ ἀναθήμασι τῶν ἀρχαίων τεχνῶν πολυτελέστατα· ἐντεῦθεν δ’ ἐπὶ τὴν πόλιν οὐ πολλὴ ὁδός ἐστιν οὐδὲ πλοῦς.", "st": "14.1.5"}, {"sp": "N", "t": "φησὶ δ’ Ἔφορος τὸ πρῶτον κτίσμα εἶναι Κρητικόν, ὑπὲρ τῆς θαλάττης τετειχισμένον, ὅπου νῦν ἡ πάλαι Μίλητος ἔστι, Σαρπηδόνος ἐκ Μιλήτου τῆς Κρητικῆς ἀγαγόντος οἰκήτορας καὶ θεμένου τοὔνομα τῇ πόλει τῆς ἐκεῖ πόλεως ἐπώνυμον, κατεχόντων πρότερον Λελέγων τὸν τόπον· τοὺς δὲ περὶ Νηλέα ὕστερον τὴν νῦν τειχίσαι πόλιν. ἔχει δὲ τέτταρας λιμένας ἡ νῦν, ὧν ἕνα καὶ στόλῳ ἱκανόν. πολλὰ δὲ τῆς πόλεως ἔργα ταύτης, μέγιστον δὲ τὸ πλῆθος τῶν ἀποικιῶν· ὅ τε γὰρ Εὔξεινος πόντος ὑπὸ τούτων συνῴκισται πᾶς καὶ ἡ Προποντὶς καὶ ἄλλοι πλείους τόποι. Ἀναξιμένης γοῦν ὁ Λαμψακηνὸς οὕτω φησὶν ὅτι καὶ Ἴκαρον τὴν νῆσον καὶ Λέρον Μιλήσιοι συνῴκισαν καὶ περὶ Ἑλλήσποντον ἐν μὲν τῇ Χερρονήσῳ Λίμνας, ἐν δὲ τῇ Ἀσίᾳ Ἄβυδον Ἄρισβαν Παισόν, ἐν δὲ τῇ Κυζικηνῶν νήσῳ Ἀρτάκην Κύζικον, ἐν δὲ τῇ μεσογαίᾳ τῆς Τρῳάδος Σκῆψιν· ἡμεῖς δ’ ἐν τοῖς καθ’ ἕκαστα λέγομεν καὶ τὰς ἄλλας τὰς ὑπὸ τούτου παραλελειμμένας. οὔλιον δ’ Ἀπόλλωνα καλοῦσί τινα καὶ Μιλήσιοι καὶ Δήλιοι, οἷον ὑγιαστικὸν καὶ παιωνικόν· τὸ γὰρ οὔλειν ὑγιαίνειν, ἀφ’ οὗ καὶ τὸ οὐλὴ καὶ τό “οὖλέ τε καὶ μέγα χαῖρε.” ἰατικὸς γὰρ ὁ Ἀπόλλων· καὶ ἡ Ἄρτεμις ἀπὸ τοῦ ἀρτεμέας ποιεῖν· καὶ ὁ Ἥλιος δὲ καὶ ἡ Σελήνη συνοικειοῦνται τούτοις, ὅτι τῆς περὶ τοὺς ἀέρας εὐκρασίας αἴτιοι· καὶ τὰ λοιμικὰ δὲ πάθη καὶ τοὺς αὐτομάτους θανάτους τούτοις ἀνάπτουσι τοῖς θεοῖς.", "st": "14.1.6"}, {"sp": "N", "t": "ἄνδρες δ’ ἄξιοι μνήμης ἐγένοντο ἐν τῇ Μιλήτῳ Θαλῆς τε εἷς τῶν ἑπτὰ σοφῶν, ὁ πρῶτος φυσιολογίας ἄρξας ἐν τοῖς Ἕλλησι καὶ μαθηματικῆς, καὶ ὁ τούτου μαθητὴς Ἀναξίμανδρος καὶ ὁ τούτου πάλιν Ἀναξιμένης, ἔτι δ’ Ἑκαταῖος ὁ τὴν ἱστορίαν συντάξας, καθ’ ἡμᾶς δὲ Αἰσχίνης ὁ ῥήτωρ, ὃς ἐν φυγῇ διετέλεσε, παρρησιασάμενος πέρα τοῦ μετρίου πρὸς Πομπήιον Μάγνον. ἠτύχησε δ’ ἡ πόλις ἀποκλείσασα Ἀλέξανδρον καὶ βίᾳ ληφθεῖσα, καθάπερ καὶ Ἁλικαρνασός· ἔτι δὲ πρότερον ὑπὸ Περσῶν· καί φησί γε Καλλισθένης ὑπ’ Ἀθηναίων χιλίαις δραχμαῖς ζημιωθῆναι Φρύνιχον τὸν τραγικόν, διότι δρᾶμα ἐποίησε Μιλήτου ἅλωσιν ὑπὸ Δαρείου. πρόκειται δ’ ἡ Λάδη νῆσος πλησίον καὶ τὰ περὶ τὰς Τραγαίας νησία ὑφόρμους ἔχοντα λῃσταῖς.", "st": "14.1.7"}, {"sp": "N", "t": "ἑξῆς δ’ ἐστὶν ὁ Λατμικὸς κόλπος, ἐν ᾧ Ἡράκλεια ἡ ὑπὸ Λάτμῳ λεγομένη, πολίχνιον ὕφορμον ἔχον· ἐκαλεῖτο δὲ πρότερον Λάτμος ὁμωνύμως τῷ ὑπερκειμένῳ ὄρει, ὅπερ Ἑκαταῖος μὲν ἐμφαίνει τὸ αὐτὸ εἶναι νομίζων τῷ ὑπὸ τοῦ ποιητοῦ Φθειρῶν ὄρει λεγομένῳ (ὑπὲρ γὰρ τῆς Λάτμου φησὶ τὸ Φθειρῶν ὄρος κεῖσθαι), τινὲς δὲ τὸ Γρίον φασίν, ὡς ἂν παράλληλον τῷ Λάτμῳ ἀνῆκον ἀπὸ τῆς Μιλησίας πρὸς ἕω διὰ τῆς Καρίας μέχρι Εὐρώμου καὶ Χαλκητόρων· ὑπέρκειται δὲ ταύτης ἐν ὄψει. μικρὸν δ’ ἄπωθεν διαβάντι ποταμίσκον πρὸς τῷ Λάτμῳ δείκνυται τάφος Ἐνδυμίωνος ἔν τινι σπηλαίῳ· εἶτα ἀφ’ Ἡρακλείας ἐπὶ Πύρραν πολίχνην πλοῦς ἑκατόν που σταδίων.", "st": "14.1.8"}, {"sp": "N", "t": "μικρὸν δὲ πλέον τὸ ἀπὸ Μιλήτου εἰς Ἡράκλειαν ἐγκολπίζοντι, εὐθυπλοίᾳ δ’ εἰς Πύρραν ἐκ Μιλήτου τριάκοντα· τοσαύτην ἔχει μακροπορίαν ὁ παρὰ γῆν πλοῦς. ἀνάγκη δ’ ἐπὶ τῶν ἐνδόξων τόπων ὑπομένειν τὸ περισκελὲς τῆς τοιαύτης γεωγραφίας.", "st": "14.1.9"}, {"sp": "N", "t": "ἐκ δὲ Πύρρας ἐπὶ τὴν ἐκβολὴν τοῦ Μαιάνδρου πεντήκοντα· τεναγώδης δ’ ὁ τόπος καὶ ἑλώδης· ἀναπλεύσαντι δ’ ὑπηρετικοῖς σκάφεσι τριάκοντα σταδίους πόλις Μυοῦς, μία τῶν Ἰάδων τῶν δώδεκα, ἣ νῦν δι’ ὀλιγανδρίαν Μιλησίοις συμπεπόλισται. ταύτην ὄψον λέγεται Θεμιστοκλεῖ δοῦναι Ξέρξης, ἄρτον δὲ Μαγνησίαν, οἶνον δὲ Λάμψακον.", "st": "14.1.10"}, {"sp": "N", "t": "ἔνθεν ἐν σταδίοις τέτταρσι κώμη Καρικὴ Θυμβρία, παρ’ ἣν ἄορνόν ἐστι σπήλαιον ἱερόν, Χαρώνιον λεγόμενον, ὀλεθρίους ἔχον ἀποφοράς. ὑπέρκειται δὲ Μαγνησία ἡ πρὸς Μαιάνδρῳ, Μαγνήτων ἀποικία τῶν ἐν Θετταλίᾳ καὶ Κρητῶν, περὶ ἧς αὐτίκα ἐροῦμεν.", "st": "14.1.11"}, {"sp": "N", "t": "μετὰ δὲ τὰς ἐκβολὰς τοῦ Μαιάνδρου ὁ κατὰ Πριήνην ἐστὶν αἰγιαλός· ὑπὲρ αὐτοῦ δ’ ἡ Πριήνη καὶ Μυκάλη τὸ ὄρος εὔθηρον καὶ εὔδενδρον. ἐπίκειται δὲ τῇ Σαμίᾳ καὶ ποιεῖ πρὸς αὐτὴν ἐπέκεινα τῆς Τρωγιλίου καλουμένης ἄκρας ὅσον ἑπταστάδιον πορθμόν. λέγεται δ’ ὑπό τινων ἡ Πριήνη Κάδμη, ἐπειδὴ Φιλωτᾶς ὁ ἐπικτίσας αὐτὴν Βοιώτιος ὑπῆρχεν· ἐκ Πριήνης δ’ ἦν Βίας εἷς τῶν ἑπτὰ σοφῶν, περὶ οὗ φησιν οὕτως Ἱππῶναξ<br>καὶ δικάσσασθαι Βίαντος τοῦ Πριηνέως κρέσσον.", "st": "14.1.12"}, {"sp": "N", "t": "τῆς δὲ Τρωγιλίου πρόκειται νησίον ὁμώνυμον· ἐντεῦθεν δὲ τὸ ἐγγυτάτω δίαρμά ἐστιν ἐπὶ Σούνιον σταδίων χιλίων ἑξακοσίων, κατ’ ἀρχὰς μὲν Σάμον ἐν δεξιᾷ ἔχοντι καὶ Ἰκαρίαν καὶ Κορσίας, τοὺς δὲ Μελαντίους σκοπέλους ἐξ εὐωνύμων, τὸ λοιπὸν δὲ διὰ μέσων τῶν Κυκλάδων νήσων. καὶ αὐτὴ δ’ ἡ Τρωγίλιος ἄκρα πρόπους τις τῆς Μυκάλης ἐστί. τῇ Μυκάλῃ δ’ ὄρος ἄλλο πρόσκειται τῆς Ἐφεσίας Πακτύης· καὶ ἡ Μεσωγὶς δὲ εἰς αὐτὴν καταστρέφει.", "st": "14.1.13"}, {"sp": "N", "t": "ἀπὸ δὲ τῆς Τρωγιλίου στάδιοι τετταράκοντα εἰς τὴν Σάμον· βλέπει δὲ πρὸς νότον καὶ αὐτὴ καὶ ὁ λιμὴν ἔχων ναύσταθμον. ἔστι δ’ αὐτῆς ἐν ἐπιπέδῳ τὸ πλέον ὑπὸ τῆς θαλάττης κλυζόμενον, μέρος δέ τι καὶ εἰς τὸ ὄρος ἀνέχει τὸ ὑπερκείμενον. ἐν δεξιᾷ μὲν οὖν προσπλέουσι πρὸς τὴν πόλιν ἔστι τὸ Ποσείδιον ἄκρα ἡ ποιοῦσα πρὸς τὴν Μυκάλην τὸν ἑπταστάδιον πορθμόν, ἔχει δὲ νεὼν Ποσειδῶνος· πρόκειται δ’ αὐτοῦ νησίδιον ἡ Ναρθηκίς· ἐπ’ ἀριστερᾷ δὲ τὸ προάστειον τὸ πρὸς τῷ Ἡραίῳ καὶ ὁ Ἴμβρασος ποταμὸς καὶ τὸ Ἡραῖον, ἀρχαῖον ἱερὸν καὶ νεὼς μέγας, ὃς νῦν πινακοθήκη ἐστί· χωρὶς δὲ τοῦ πλήθους τῶν ἐνταῦθα κειμένων πινάκων ἄλλαι πινακοθῆκαι καὶ ναΐσκοι τινές εἰσι πλήρεις τῶν ἀρχαίων τεχνῶν· τό τε ὕπαιθρον ὁμοίως μεστὸν ἀνδριάντων ἐστὶ τῶν ἀρίστων· ὧν τρία Μύρωνος ἔργα κολοσσικὰ ἱδρυμένα ἐπὶ μιᾶς βάσεως, ἃ ἦρε μὲν Ἀντώνιος ἀνέθηκε δὲ πάλιν ὁ Σεβαστὸς Καῖσαρ εἰς τὴν αὐτὴν βάσιν τὰ δύο, τὴν Ἀθηνᾶν καὶ τὸν Ἡρακλέα, τὸν δὲ Δία εἰς τὸ Καπετώλιον μετήνεγκε κατασκευάσας αὐτῷ ναΐσκον.", "st": "14.1.14"}, {"sp": "N", "t": "περίπλους δ’ ἐστὶ τῆς Σαμίων νήσου σταδίων ἑξακοσίων. ἐκαλεῖτο δὲ Παρθενία πρότερον οἰκούντων Καρῶν, εἶτα Ἀνθεμοῦς, εἶτα Μελάμφυλλος, εἶτα Σάμος, εἴτ’ ἀπό τινος ἐπιχωρίου ἥρωος εἴτ’ ἐξ Ἰθάκης καὶ Κεφαλληνίας ἀποικήσαντος. καλεῖται μὲν οὖν καὶ ἄκρα τις Ἄμπελος βλέπουσά πως πρὸς τὸ τῆς Ἰκαρίας Δρέπανον, ἀλλὰ καὶ τὸ ὄρος ἅπαν ὃ ποιεῖ τὴν ὅλην νῆσον ὀρεινὴν ὁμωνύμως λέγεται· ἔστι δ’ οὐκ εὔοινος, καίπερ εὐοινουσῶν τῶν κύκλῳ νήσων, καὶ τῆς ἠπείρου σχεδόν τι τῆς προσεχοῦς πάσης τοὺς ἀρίστους ἐκφερούσης οἴνους· οἷον Χίου καὶ Λέσβου καὶ Κῶ· καὶ μὴν καὶ ὁ Ἐφέσιος καὶ Μητροπολίτης ἀγαθοί, ἥ τε Μεσωγὶς καὶ ὁ Τμῶλος καὶ ἡ Κατακεκαυμένη καὶ Κνίδος καὶ Σμύρνα καὶ ἄλλοι ἀσημότεροι τόποι διαφόρως χρηστοινοῦσιν ἢ πρὸς ἀπόλαυσιν ἢ πρὸς διαίτας ἰατρικάς. περὶ μὲν [οὖν] οἴνους οὐ πάνυ εὐτυχεῖ Σάμος, τὰ δ’ ἄλλα εὐδαίμων, ὡς δῆλον ἔκ τε τοῦ περιμάχητον γενέσθαι καὶ ἐκ τοῦ τοὺς ἐπαινοῦντας μὴ ὀκνεῖν ἐφαρμόττειν αὐτῇ τὴν λέγουσαν παροιμίαν ὅτι φέρει καὶ ὀρνίθων γάλα. τοῦτο δὲ καὶ τῶν τυραννίδων αἴτιον αὐτῇ κατέστη καὶ τῆς πρὸς Ἀθηναίους ἔχθρας.", "st": "14.1.15"}, {"sp": "N", "t": "αἱ μὲν οὖν τυραννίδες ἤκμασαν κατὰ Πολυκράτη μάλιστα καὶ τὸν ἀδελφὸν αὐτοῦ Συλοσῶντα· ἦν δ’ ὁ μὲν καὶ τύχῃ καὶ δυνάμει λαμπρὸς ὥστε καὶ θαλαττοκρατῆσαι· τῆς δ’ εὐτυχίας αὐτοῦ σημεῖον τιθέασιν ὅτι ῥίψαντος εἰς τὴν θάλατταν ἐπίτηδες τὸν δακτύλιον λίθου καὶ γλύμματος πολυτελοῦς, ἀνήνεγκε μικρὸν ὕστερον τῶν ἁλιέων τις τὸν καταπιόντα ἰχθὺν αὐτόν· ἀνατμηθέντος δ’ εὑρέθη ὁ δακτύλιος· πυθόμενον δὲ τοῦτο τὸν Αἰγυπτίων βασιλέα φασὶ μαντικῶς πως ἀποφθέγξασθαι ὡς ἐν βραχεῖ καταστρέψει τὸν βίον εἰς οὐκ εὐτυχὲς τέλος ὁ τοσοῦτον ἐξηρμένος ταῖς εὐπραγίαις· καὶ δὴ καὶ συμβῆναι τοῦτο· ληφθέντα γὰρ ἐξ ἀπάτης ὑπὸ τοῦ σατράπου τῶν Περσῶν κρεμασθῆναι. τούτῳ συνεβίωσεν Ἀνακρέων ὁ μελοποιός· καὶ δὴ καὶ πᾶσα ἡ ποίησις πλήρης ἐστὶ τῆς περὶ αὐτοῦ μνήμης. ἐπὶ τούτου δὲ καὶ Πυθαγόραν ἱστοροῦσιν ἰδόντα φυομένην τὴν τυραννίδα ἐκλιπεῖν τὴν πόλιν καὶ ἀπελθεῖν εἰς Αἴγυπτον καὶ Βαβυλῶνα φιλομαθείας χάριν· ἐπανιόντα δ’ ἐκεῖθεν, ὁρῶντα ἔτι συμμένουσαν τὴν τυραννίδα, πλεύσαντα εἰς Ἰταλίαν ἐκεῖ διατελέσαι τὸν βίον. περὶ Πολυκράτους μὲν ταῦτα.", "st": "14.1.16"}, {"sp": "N", "t": "Συλοσῶν δ’ ἀπελείφθη μὲν ἰδιώτης ὑπὸ τοῦ ἀδελφοῦ, Δαρείῳ δὲ τῷ Ὑστάσπεω χαρισάμενος ἐσθῆτα, ἧς ἐπεθύμησεν ἐκεῖνος φοροῦντα ἰδών, οὔπω δ’ ἐβασίλευε τότε, βασιλεύσαντος ἀντέλαβε δῶρον τὴν τυραννίδα. πικρῶς δ’ ἦρξεν, ὥστε καὶ ἐλειπάνδρησεν ἡ πόλις· κἀκεῖθεν ἐκπεσεῖν συνέβη τὴν παροιμίαν<br>ἕκητι Συλοσῶντος εὐρυχωρίη.", "st": "14.1.17"}, {"sp": "N", "t": "Ἀθηναῖοι δὲ πρότερον μὲν πέμψαντες στρατηγὸν Περικλέα καὶ σὺν αὐτῷ Σοφοκλέα τὸν ποιητὴν πολιορκίᾳ κακῶς διέθηκαν ἀπειθοῦντας τοὺς Σαμίους, ὕστερον δὲ καὶ κληρούχους ἔπεμψαν δισχιλίους ἐξ ἑαυτῶν, ὧν ἦν καὶ Νεοκλῆς ὁ Ἐπικούρου τοῦ φιλοσόφου πατήρ, γραμματοδιδάσκαλος, ὥς φασι· καὶ δὴ καὶ τραφῆναί φασιν ἐνθάδε καὶ ἐν Τέῳ καὶ ἐφηβεῦσαι Ἀθήνησι· γενέσθαι δ’ αὐτῷ συνέφηβον Μένανδρον τὸν κωμικόν· Σάμιος δ’ ἦν καὶ Κρεώφυλος, ὅν φασι δεξάμενον ξενίᾳ ποτὲ Ὅμηρον λαβεῖν δῶρον τὴν ἐπιγραφὴν τοῦ ποιήματος ὃ καλοῦσιν Οἰχαλίας ἅλωσιν. Καλλίμαχος δὲ τοὐναντίον ἐμφαίνει δι’ ἐπιγράμματός τινος, ὡς ἐκείνου μὲν ποιήσαντος λεγομένου δ’ Ὁμήρου διὰ τὴν λεγομένην ξενίαν<br>τοῦ Σαμίου πόνος εἰμί, δόμῳ ποτὲ θεῖον Ὅμηρον<br>δεξαμένου· κλείω δ’ Εὔρυτον ὅσσ’ ἔπαθεν,<br>καὶ ξανθὴν Ἰόλειαν· Ὁμήρειον δὲ καλεῦμαι<br>γράμμα· Κρεωφύλῳ, Ζεῦ φίλε, τοῦτο μέγα.<br>τινὲς δὲ διδάσκαλον Ὁμήρου τοῦτόν φασιν, οἱ δ’ οὐ τοῦτον ἀλλ’ Ἀριστέαν τὸν Προκοννήσιον.", "st": "14.1.18"}, {"sp": "N", "t": "παράκειται δὲ τῇ Σάμῳ νῆσος Ἰκαρία ἀφ’ ἧς τὸ Ἰκάριον πέλαγος. αὕτη δ’ ἐπώνυμός ἐστιν Ἰκάρου παιδὸς τοῦ Δαιδάλου, ὅν φασι τῷ πατρὶ κοινωνήσαντα τῆς φυγῆς, ἡνίκα ἀμφότεροι πτερωθέντες ἀπῆραν ἐκ Κρήτης, πεσεῖν ἐνθάδε μὴ κρατήσαντα τοῦ δρόμου· μετεωρισθέντι γὰρ πρὸς τὸν ἥλιον ἐπὶ πλέον περιρρυῆναι τὰ πτερὰ τακέντος τοῦ κηροῦ. τριακοσίων δ’ ἐστὶ τὴν περίμετρον σταδίων ἡ νῆσος ἅπασα καὶ ἀλίμενος πλὴν ὑφόρμων, ὧν ὁ κάλλιστος Ἱστοὶ λέγονται· ἄκρα δ’ ἐστὶν ἀνατείνουσα πρὸς ζέφυρον. ἔστι δὲ καὶ Ἀρτέμιδος ἱερὸν καλούμενον Ταυροπόλιον ἐν τῇ νήσῳ καὶ πολισμάτιον Οἰνόη, καὶ ἄλλο Δράκανον ὁμώνυμον τῇ ἄκρᾳ ἐφ’ ᾗ ἵδρυται, πρόσορμον ἔχον· ἡ δὲ ἄκρα διέχει τῆς Σαμίων ἄκρας τῆς Κανθαρίου καλουμένης ὀγδοήκοντα σταδίους, ὅπερ ἐστὶν ἐλάχιστον δίαρμα τὸ μεταξύ. νυνὶ μέντοι λιπανδροῦσαν Σάμιοι νέμονται τὰ πολλὰ βοσκημάτων χάριν.", "st": "14.1.19"}, {"sp": "N", "t": "μετὰ δὲ τὸν Σάμιον πορθμὸν τὸν πρὸς Μυκάλῃ πλέουσιν εἰς Ἔφεσον ἐν δεξιᾷ ἐστιν ἡ Ἐφεσίων παραλία· μέρος δέ τι ἔχουσιν αὐτῆς καὶ οἱ Σάμιοι. πρῶτον δ’ ἐστὶν ἐν τῇ παραλίᾳ τὸ Πανιώνιον τρισὶ σταδίοις ὑπερκείμενον τῆς θαλάττης, ὅπου τὰ Πανιώνια, κοινὴ πανήγυρις τῶν Ἰώνων, συντελεῖται τῷ Ἑλικωνίῳ Ποσειδῶνι καὶ θυσία· ἱερῶνται δὲ Πριηνεῖς· εἴρηται δὲ περὶ αὐτῶν ἐν τοῖς Πελοποννησιακοῖς. εἶτα Νεάπολις, ἣ πρότερον μὲν ἦν Ἐφεσίων νῦν δὲ Σαμίων διαλλαξαμένων πρὸς τὸ Μαραθήσιον, τὸ ἐγγυτέρω πρὸς τὸ ἀπωτέρω· εἶτα Πύγελα πολίχνιον, ἱερὸν ἔχον Ἀρτέμιδος Μουνυχίας, ἵδρυμα Ἀγαμέμνονος, οἰκούμενον ὑπὸ μέρους τῶν ἐκείνου λαῶν· πυγαλγίας γάρ τινας καὶ γενέσθαι καὶ κληθῆναι, κάμνοντας δ’ ὑπὸ τοῦ πάθους καταμεῖναι, καὶ τυχεῖν οἰκείου τοῦδε τοῦ ὀνόματος τὸν τόπον. εἶτα λιμὴν Πάνορμος καλούμενος ἔχων ἱερὸν τῆς Ἐφεσίας Ἀρτέμιδος· εἶθ’ ἡ πόλις. ἐν δὲ τῇ αὐτῇ παραλίᾳ μικρὸν ὑπὲρ τῆς θαλάττης ἐστὶ καὶ ἡ Ὀρτυγία, διαπρεπὲς ἄλσος παντοδαπῆς ὕλης, κυπαρίττου δὲ τῆς πλείστης. διαρρεῖ δὲ ὁ Κέγχριος ποταμός, οὗ φασι νίψασθαι τὴν Λητὼ μετὰ τὰς ὠδῖνας. ἐνταῦθα γὰρ μυθεύουσι τὴν λοχείαν καὶ τὴν τροφὸν τὴν Ὀρτυγίαν καὶ τὸ ἄδυτον ἐν ᾧ ἡ λοχεία, καὶ τὴν πλησίον ἐλαίαν, ᾗ πρῶτον ἐπαναπαύσασθαί φασι τὴν θεὸν ἀπολυθεῖσαν τῶν ὠδίνων. ὑπέρκειται δὲ τοῦ ἄλσους ὄρος ὁ Σολμισσός, ὅπου στάντας φασὶ τοὺς Κουρῆτας τῷ ψόφῳ τῶν ὅπλων ἐκπλῆξαι τὴν Ἥραν ζηλοτύπως ἐφεδρεύουσαν, καὶ λαθεῖν συμπράξαντας τὴν λοχείαν τῇ Λητοῖ. ὄντων δ’ ἐν τῷ τόπῳ πλειόνων ναῶν, τῶν μὲν ἀρχαίων τῶν δ’ ὕστερον γενομένων, ἐν μὲν τοῖς ἀρχαίοις ἀρχαῖά ἐστι ξόανα, ἐν δὲ τοῖς ὕστερον Σκόπα ἔργα· ἡ μὲν Λητὼ σκῆπτρον ἔχουσα, ἡ δ’ Ὀρτυγία παρέστηκεν ἑκατέρᾳ τῇ χειρὶ παιδίον ἔχουσα. πανήγυρις δ’ ἐνταῦθα συντελεῖται κατ’ ἔτος, ἔθει δέ τινι οἱ νέοι φιλοκαλοῦσι μάλιστα περὶ τὰς ἐνταῦθα εὐωχίας λαμπρυνόμενοι· τότε δὲ καὶ τῶν Κουρήτων ἀρχεῖον συνάγει συμπόσια καί τινας μυστικὰς θυσίας ἐπιτελεῖ.", "st": "14.1.20"}, {"sp": "N", "t": "τὴν δὲ πόλιν ᾤκουν μὲν Κᾶρές τε καὶ Λέλεγες, ἐκβαλὼν δ’ ὁ Ἄνδροκλος τοὺς πλείστους ᾤκισεν ἐκ τῶν συνελθόντων αὐτῷ περὶ τὸ Ἀθήναιον καὶ τὴν Ὑπέλαιον, προσπεριλαβὼν καὶ τῆς περὶ τὸν Κορησσὸν παρωρείας. μέχρι μὲν δὴ τῶν κατὰ Κροῖσον οὕτως ᾠκεῖτο, ὕστερον δ’ ἀπὸ τῆς Παρωρείου καταβάντες περὶ τὸ νῦν ἱερὸν ᾤκησαν μέχρι Ἀλεξάνδρου. Λυσίμαχος δὲ τὴν νῦν πόλιν τειχίσας, ἀηδῶς τῶν ἀνθρώπων μεθισταμένων, τηρήσας καταρράκτην ὄμβρον συνήργησε καὶ αὐτὸς καὶ τοὺς ῥινούχους ἐνέφραξεν ὥστε κατακλύσαι τὴν πόλιν· οἱ δὲ μετέστησαν ἄσμενοι. ἐκάλεσε δ’ Ἀρσινόην ἀπὸ τῆς γυναικὸς τὴν πόλιν, ἐπεκράτησε μέντοι τὸ ἀρχαῖον ὄνομα. ἦν δὲ γερουσία καταγραφομένη, τούτοις δὲ συνῄεσαν οἱ ἐπίκλητοι καλούμενοι καὶ διῴκουν πάντα.", "st": "14.1.21"}, {"sp": "N", "t": "τὸν δὲ νεὼν τῆς Ἀρτέμιδος πρῶτος μὲν Χερσίφρων ἠρχιτεκτόνησεν, εἶτ’ ἄλλος ἐποίησε μείζω· ὡς δὲ τοῦτον Ἡρόστρατός τις ἐνέπρησεν, ἄλλον ἀμείνω κατεσκεύασαν συνενέγκαντες τὸν τῶν γυναικῶν κόσμον καὶ τὰς ἰδίας οὐσίας, διαθέμενοι δὲ καὶ τοὺς προτέρους κίονας· τούτων δὲ μαρτύριά ἐστι τὰ γενηθέντα τότε ψηφίσματα, ἅπερ ἀγνοοῦντά φησιν ὁ Ἀρτεμίδωρος τὸν Ταυρομενίτην Τίμαιον καὶ ἄλλως βάσκανον ὄντα καὶ συκοφάντην (διὸ καὶ Ἐπιτίμαιον κληθῆναι) λέγειν ὡς ἐκ τῶν Περσικῶν παρακαταθηκῶν ἐποιήσαντο τοῦ ἱεροῦ τὴν ἐπισκευήν· οὔτε δὲ ὑπάρξαι παρακαταθήκας τότε, εἴ τε ὑπῆρξαν, συνεμπεπρῆσθαι τῷ ναῷ· μετὰ δὲ τὴν ἔμπρησιν τῆς ὀροφῆς ἠφανισμένης, ἐν ὑπαίθρῳ τῷ σηκῷ τίνα ἂν ἐθελῆσαι παρακαταθήκην κειμένην ἔχειν; Ἀλέξανδρον δὴ τοῖς Ἐφεσίοις ὑποσχέσθαι τὰ γεγονότα καὶ τὰ μέλλοντα ἀναλώματα, ἐφ’ ᾧ τε τὴν ἐπιγραφὴν αὐτὸν ἔχειν, τοὺς δὲ μὴ ἐθελῆσαι, πολὺ μᾶλλον οὐκ ἂν ἐθελήσαντας ἐξ ἱεροσυλίας καὶ ἀποστερήσεως φιλοδοξεῖν· ἐπαινεῖ τε τὸν εἰπόντα τῶν Ἐφεσίων πρὸς τὸν βασιλέα, ὡς οὐ πρέποι θεῷ θεοῖς ἀναθήματα κατασκευάζειν.", "st": "14.1.22"}, {"sp": "N", "t": "μετὰ δὲ τὴν τοῦ νεὼ συντέλειαν, ὅν φησιν εἶναι Δεινοκράτους ἔργον (τοῦ δ’ αὐτοῦ καὶ τὴν Ἀλεξανδρείας κτίσιν· τὸν δ’ αὐτὸν ὑποσχέσθαι Ἀλεξάνδρῳ τὸν Ἄθω διασκευάσειν εἰς αὐτόν, ὡσανεὶ ἐκ πρόχου τινὸς εἰς φιάλην καταχέοντα σπονδήν, ποιήσοντα πόλεις δύο, τὴν μὲν ἐκ δεξιῶν τοῦ ὄρους τὴν δ’ ἐν ἀριστερᾷ, ἀπὸ δὲ τῆς ἑτέρας εἰς τὴν ἑτέραν ῥέοντα ποταμόν), μετὰ δ’ οὖν τὸν νεὼν τὸ τῶν ἄλλων ἀναθημάτων πλῆθος εὑρέσθαι τῇ ἐκτιμήσει τῶν δημιουργῶν, τὸν δὲ δὴ βωμὸν εἶναι τῶν Πραξιτέλους ἔργων ἅπαντα σχεδόν τι πλήρη. ἡμῖν δ’ ἐδείκνυτο καὶ τῶν Θράσωνός τινα, οὗπερ καὶ τὸ Ἑκατήσιόν ἐστι καὶ ἡ κηρίνη Πηνελόπη καὶ ἡ πρεσβῦτις ἡ Εὐρύκλεια. ἱερέας δ’ εὐνούχους εἶχον οὓς ἐκάλουν Μεγαβύζους, καὶ ἀλλαχόθεν μετιόντες ἀεί τινας ἀξίους τῆς τοιαύτης προστασίας, καὶ ἦγον ἐν τιμῇ μεγάλῃ· συνιερᾶσθαι δὲ τούτοις ἐχρῆν παρθένους. νυνὶ δὲ τὰ μὲν φυλάττεται τῶν νομίμων τὰ δ’ ἧττον, ἄσυλον δὲ μένει τὸ ἱερὸν καὶ νῦν καὶ πρότερον· τῆς δ’ ἀσυλίας τοὺς ὅρους ἀλλαγῆναι συνέβη πολλάκις, Ἀλεξάνδρου μὲν ἐπὶ στάδιον ἐκτείναντος, Μιθριδάτου δὲ τόξευμα ἀφέντος ἀπὸ τῆς γωνίας τοῦ κεράμου καὶ δόξαντος ὑπερβαλέσθαι μικρὰ τὸ στάδιον, Ἀντωνίου δὲ διπλασιάσαντος τοῦτο καὶ συμπεριλαβόντος τῇ ἀσυλίᾳ μέρος τι τῆς πόλεως· ἐφάνη δὲ τοῦτο βλαβερὸν καὶ ἐπὶ τοῖς κακούργοις ποιοῦν τὴν πόλιν, ὥστ’ ἠκύρωσεν ὁ Σεβαστὸς Καῖσαρ.", "st": "14.1.23"}, {"sp": "N", "t": "ἔχει δ’ ἡ πόλις καὶ νεώρια καὶ λιμένα· βραχύστομον δ’ ἐποίησαν οἱ ἀρχιτέκτονες, συνεξαπατηθέντες τῷ κελεύσαντι βασιλεῖ. οὗτος δ’ ἦν Ἄτταλος ὁ φιλάδελφος· οἰηθεὶς γὰρ οὗτος βαθὺν τὸν εἴσπλουν ὁλκάσι μεγάλαις ἔσεσθαι καὶ αὐτὸν τὸν λιμένα τεναγώδη ὄντα πρότερον διὰ τὰς ἐκ τοῦ Καΰστρου προχώσεις, ἐὰν παραβληθῇ χῶμα τῷ στόματι πλατεῖ τελέως ὄντι, ἐκέλευσε γενέσθαι τὸ χῶμα. συνέβη δὲ τοὐναντίον· ἐντὸς γὰρ ἡ χοῦς εἰργομένη τεναγίζειν μᾶλλον ἐποίησε τὸν λιμένα σύμπαντα μέχρι τοῦ στόματος· πρότερον δ’ ἱκανῶς αἱ πλημμυρίδες καὶ ἡ παλίρροια τοῦ πελάγους ἀφῄρει τὴν χοῦν καὶ ἀνέσπα πρὸς τὸ ἐκτός. ὁ μὲν οὖν λιμὴν τοιοῦτος· ἡ δὲ πόλις τῇ πρὸς τὰ ἄλλα εὐκαιρίᾳ τῶν τόπων αὔξεται καθ’ ἑκάστην ἡμέραν, ἐμπόριον οὖσα μέγιστον τῶν κατὰ τὴν Ἀσίαν τὴν ἐντὸς τοῦ Ταύρου.", "st": "14.1.24"}, {"sp": "N", "t": "ἄνδρες δ’ ἀξιόλογοι γεγόνασιν ἐν αὐτῇ τῶν μὲν παλαιῶν Ἡράκλειτός τε ὁ σκοτεινὸς καλούμενος καὶ Ἑρμόδωρος, περὶ οὗ ὁ αὐτὸς οὗτός φησιν ἄξιον Ἐφεσίοις ἡβηδὸν ἀπάγξασθαι, οἵτινες Ἑρμόδωρον ἄνδρα ἑωυτῶν ὀνήιστον ἐξέβαλον, φάντες ἡμέων μηδὲ εἷς ὀνήιστος ἔστω, εἰ δὲ μή, ἄλλῃ τε καὶ μετ’ ἄλλων. δοκεῖ δ’ οὗτος ὁ ἀνὴρ νόμους τινὰς Ῥωμαίοις συγγράψαι. καὶ Ἱππῶναξ δ’ ἐστὶν ὁ ποιητὴς ἐξ Ἐφέσου καὶ Παρράσιος ὁ ζωγράφος καὶ Ἀπελλῆς, τῶν δὲ νεωτέρων [Ἀρτεμίδωρος καὶ] Ἀλέξανδρος ῥήτωρ ὁ Λύχνος προσαγορευθείς, ὃς καὶ ἐπολιτεύσατο καὶ συνέγραψεν ἱστορίαν καὶ ἔπη κατέλιπεν, ἐν οἷς τά τε οὐράνια διατίθεται καὶ τὰς ἠπείρους γεωγραφεῖ, καθ’ ἑκάστην ἐκδοὺς ποίημα.", "st": "14.1.25"}, {"sp": "N", "t": "μετὰ δὲ τὴν ἐκβολὴν τοῦ Καΰστρου λίμνη ἐστὶν ἐκ τοῦ πελάγους ἀναχεομένη (καλεῖται δὲ Σελινουσία) καὶ ἐφεξῆς ἄλλη σύρρους αὐτῇ μεγάλας ἔχουσαι προσόδους, ἃς οἱ βασιλεῖς μὲν ἱερὰς οὔσας ἀφείλοντο τὴν θεόν, Ῥωμαῖοι δ’ ἀπέδοσαν· πάλιν δ’ οἱ δημοσιῶναι βιασάμενοι περιέστησαν εἰς ἑαυτοὺς τὰ τέλη, πρεσβεύσας δὲ ὁ Ἀρτεμίδωρος, ὥς φησι, τάς τε λίμνας ἀπέλαβε τῇ θεῷ καὶ τὴν Ἡρακλεῶτιν ἀφισταμένην ἐξενίκησε κριθεὶς ἐν Ῥώμῃ· ἀντὶ δὲ τούτων εἰκόνα χρυσῆν ἀνέστησεν ἡ πόλις ἐν τῷ ἱερῷ. τῆς δὲ λίμνης ἐν τῷ κοιλοτάτῳ βασιλέως ἐστὶν ἱερόν· φασὶ δ’ Ἀγαμέμνονος ἵδρυμα.", "st": "14.1.26"}, {"sp": "N", "t": "εἶτα τὸ Γαλλήσιον ὄρος καὶ ἡ Κολοφὼν πόλις Ἰωνικὴ καὶ τὸ πρὸ αὐτῆς ἄλσος τοῦ Κλαρίου Ἀπόλλωνος, ἐν ᾧ καὶ μαντεῖόν ἐστι παλαιόν. λέγεται δὲ Κάλχας ὁ μάντις μετ’ Ἀμφιλόχου τοῦ Ἀμφιαράου κατὰ τὴν ἐκ Τροίας ἐπάνοδον πεζῇ δεῦρο ἀφικέσθαι, περιτυχὼν δ’ ἑαυτοῦ κρείττονι μάντει κατὰ τὴν Κλάρον, Μόψῳ τῷ Μαντοῦς τῆς Τειρεσίου θυγατρός, διὰ λύπην ἀποθανεῖν. Ἡσίοδος μὲν οὖν οὕτω πως διασκευάζει τὸν μῦθον· προτεῖναι γάρ τι τοιοῦτο τῷ Μόψῳ τὸν Κάλχαντα<br>θαῦμά μ’ ἔχει κατὰ θυμόν, ὅσους ἐρινειὸς ὀλύνθους<br>οὗτος ἔχει μικρός περ ἐών· εἴποις ἂν ἀριθμόν;<br>τὸν δ’ ἀποκρίνασθαι<br>μύριοί εἰσιν ἀριθμόν, ἀτὰρ μέτρον γε μέδιμνος·<br>εἷς δὲ περισσεύει, τὸν ἐπενθέμεν οὔ κε δύναιο.<br>ὣς φάτο· καί σφιν ἀριθμὸς ἐτήτυμος εἴδετο μέτρου.<br>καὶ τότε δὴ Κάλχανθ’ ὕπνος θανάτοιο κάλυψε.<br>Φερεκύδης δέ φησιν ὗν προβαλεῖν ἔγκυον τὸν Κάλχαντα πόσους ἔχει χοίρους, τὸν δ’ εἰπεῖν ὅτι τρεῖς, ὧν ἕνα θῆλυν· ἀληθεύσαντος δ’ ἀποθανεῖν ὑπὸ λύπης. οἱ δὲ τὸν μὲν Κάλχαντα προβαλεῖν τὴν ὗν φασι τὸν δὲ ἐρινεόν, καὶ τὸν μὲν εἰπεῖν τἀληθὲς τὸν δὲ μή, ἀποθανεῖν δὲ ὑπὸ λύπης καὶ κατά τι λόγιον. λέγει δ’ αὐτὸ Σοφοκλῆς ἐν Ἑλένης ἀπαιτήσει ὡς εἱμαρμένον εἴη ἀποθανεῖν, ὅταν κρείττονι ἑαυτοῦ μάντει περιτύχῃ· οὗτος δὲ καὶ εἰς Κιλικίαν μεταφέρει τὴν ἔριν καὶ τὸν θάνατον τοῦ Κάλχαντος. τὰ μὲν παλαιὰ τοιαῦτα.", "st": "14.1.27"}, {"sp": "N", "t": "ἐκτήσαντο δέ ποτε καὶ ναυτικὴν ἀξιόλογον δύναμιν Κολοφώνιοι καὶ ἱππικήν, ἐν ᾗ τοσοῦτον διέφερον τῶν ἄλλων ὥσθ’, ὅπου ποτὲ ἐν τοῖς δυσκαταλύτοις πολέμοις τὸ ἱππικὸν τῶν Κολοφωνίων ἐπικουρήσειε, λύεσθαι τὸν πόλεμον· ἀφ’ οὗ καὶ τὴν παροιμίαν ἐκδοθῆναι τὴν λέγουσαν “τὸν Κολοφῶνα ἐπέθηκεν” ὅταν τέλος ἐπιτεθῇ βέβαιον τῷ πράγματι. ἄνδρες δ’ ἐγένοντο Κολοφώνιοι τῶν μνημονευομένων Μίμνερμος αὐλητὴς ἅμα καὶ ποιητὴς ἐλεγείας, καὶ Ξενοφάνης ὁ φυσικός, ὁ τοὺς σίλλους ποιήσας διὰ ποιημάτων· λέγει δὲ Πίνδαρος καὶ Πολύμναστόν τινα τῶν περὶ τὴν μουσικὴν ἐλλογίμων<br>φθέγμα μὲν πάγκοινον ἔγνωκας;Πολυμνάστου Κολοφωνίου ἀνδρός.<br>καὶ Ὅμηρον δέ τινες ἐντεῦθεν εἶναί φασιν. Εὐθυπλοίᾳ μὲν οὖν ἑβδομήκοντα στάδιοί εἰσιν ἐξ Ἐφέσου, ἐγκολπίζοντι δὲ ἑκατὸν καὶ εἴκοσι.", "st": "14.1.28"}, {"sp": "N", "t": "μετὰ δὲ Κολοφῶνα ὄρος Κοράκιον καὶ νησίον ἱερὸν Ἀρτέμιδος, εἰς ὃ διανηχομένας τίκτειν τὰς ἐλάφους πεπιστεύκασιν. εἶτα Λέβεδος διέχουσα Κολοφῶνος ἑκατὸν καὶ εἴκοσιν· ἐνταῦθα τῶν περὶ τὸν Διόνυσον τεχνιτῶν ἡ σύνοδος καὶ κατοικία τῶν ἐν Ἰωνίᾳ μέχρι Ἑλλησπόντου, ἐν ᾗ πανήγυρίς τε καὶ ἀγῶνες κατ’ ἔτος συντελοῦνται τῷ Διονύσῳ. ἐν Τέῳ δὲ ᾤκουν πρότερον τῇ ἐφεξῆς πόλει τῶν Ἰώνων, ἐμπεσούσης δὲ στάσεως εἰς Ἔφεσον κατέφυγον· Ἀττάλου δ’ εἰς Μυόννησον αὐτοὺς καταστήσαντος μεταξὺ Τέω καὶ Λεβέδου, πρεσβεύονται Τήιοι δεόμενοι Ῥωμαίων μὴ περιιδεῖν ἐπιτειχιζομένην σφίσι τὴν Μυόννησον, οἱ δὲ μετέστησαν εἰς Λέβεδον δεξαμένων τῶν Λεβεδίων ἀσμένως διὰ τὴν κατέχουσαν αὐτοὺς ὀλιγανδρίαν. καὶ Τέως δὲ Λεβέδου διέχει ἑκατὸν εἴκοσι, μεταξὺ δὲ νῆσος Ἀσπίς, οἱ δ’ Ἀρκόνησον καλοῦσι· καὶ ἡ Μυόννησος δὲ ἐφ’ ὕψους χερρονησίζοντος κατοικεῖται.", "st": "14.1.29"}, {"sp": "N", "t": "καὶ ἡ Τέως δὲ ἐπὶ χερρονήσῳ ἵδρυται λιμένα ἔχουσα· ἐνθένδ’ ἐστὶν Ἀνακρέων ὁ μελοποιός, ἐφ’ οὗ Τήιοι τὴν πόλιν ἐκλιπόντες εἰς Ἄβδηρα ἀπῴκησαν Θρᾳκίαν πόλιν, οὐ φέροντες τὴν τῶν Περσῶν ὕβριν, ἀφ’ οὗ καὶ τοῦτ’ εἴρηται<br>Ἄβδηρα καλὴ Τηίων ἀποικίη.<br>πάλιν δ’ ἐπανῆλθόν τινες αὐτῶν χρόνῳ ὕστερον· εἴρηται δὲ καὶ περὶ Ἀπελλικῶντος ὅτι Τήιος ἦν κἀκεῖνος· γέγονε δὲ καὶ συγγραφεὺς Ἑκαταῖος ἐκ τῆς αὐτῆς πόλεως. ἔστι καὶ ἄλλος λιμὴν ὁ πρόσβορρος ἀπὸ τριάκοντα σταδίων τῆς πόλεως Γερραιίδαι.", "st": "14.1.30"}, {"sp": "N", "t": "εἶτα Χαλκιδεῖς [καὶ] ὁ τῆς χερρονήσου ἰσθμὸς τῆς Τηίων καὶ Ἐρυθραίων· ἐντὸς μὲν οὖν τοῦ ἰσθμοῦ οἰκοῦσιν οὗτοι, ἐπ’ αὐτῷ δὲ τῷ ἰσθμῷ Τήιοι καὶ Κλαζομένιοι· τὸ μὲν γὰρ νότιον τοῦ ἰσθμοῦ πλευρὸν ἔχουσι Τήιοι τοὺς Χαλκιδέας, τὸ δὲ πρόσβορρον Κλαζομένιοι, καθ’ ὃ συνάπτουσι τῇ Ἐρυθραίᾳ. κεῖται δ’ Ὑπόκρημνος ὁ τόπος ἐπὶ τῇ ἀρχῇ τοῦ ἰσθμοῦ, ἐντὸς μὲν ἀπολαμβάνων τὴν Ἐρυθραίαν ἐκτὸς δὲ τὴν τῶν Κλαζομενίων. ὑπέρκειται δὲ τῶν Χαλκιδέων ἄλσος καθιερωμένον Ἀλεξάνδρῳ τῷ Φιλίππου, καὶ ἀγὼν ὑπὸ τοῦ κοινοῦ τῶν Ἰώνων Ἀλεξάνδρεια καταγγέλλεται, συντελούμενος ἐνταῦθα. ἡ δ’ ὑπέρβασις τοῦ ἰσθμοῦ τοῦ ἀπὸ τοῦ Ἀλεξανδρείου καὶ τῶν Χαλκιδέων μέχρι τοῦ Ὑποκρήμνου πεντήκοντά εἰσι στάδιοι, ὁ δὲ περίπλους πλείους ἢ χίλιοι. κατὰ μέσον δέ που τὸν περίπλουν αἱ Ἐρυθραί, πόλις Ἰωνικὴ λιμένα ἔχουσα καὶ νησῖδας προκειμένας τέτταρας Ἵππους καλουμένας.", "st": "14.1.31"}, {"sp": "N", "t": "πρὶν δ’ ἐλθεῖν ἐπὶ τὰς Ἐρυθράς, πρῶτον μὲν Ἔραι πολίχνιόν ἐστι Τηίων· εἶτα Κώρυκος ὄρος ὑψηλὸν καὶ λιμὴν ὑπ’ αὐτῷ Κασύστης καὶ ἄλλος Ἐρυθρᾶς λιμὴν καλούμενος καὶ ἐφεξῆς πλείους ἕτεροι. φασὶ δὲ τὸν παράπλουν τοῦ Κωρύκου πάντα λῃστήριον ὑπάρξαι τῶν Κωρυκαίων καλουμένων, εὑρομένων τρόπον καινὸν τῆς ἐπιβουλῆς τῶν πλοϊζομένων· κατεσπαρμένους γὰρ ἐν τοῖς λιμέσι τοῖς καθορμιζομένοις ἐμπόροις προσφοιτᾶν καὶ ὠτακουστεῖν τί φέροιεν καὶ ποῦ πλέοιεν, εἶτα συνελθόντας ἀναχθεῖσι τοῖς ἀνθρώποις ἐπιτίθεσθαι καὶ καθαρπάζειν· ἀφ’ οὗ δὴ πάντα τὸν πολυπράγμονα καὶ κατακούειν ἐπιχειροῦντα τῶν λάθρα καὶ ἐν ἀπορρήτῳ διαλεγομένων Κωρυκαῖον καλοῦμεν, καὶ ἐν παροιμίᾳ φαμέν<br>τοῦ δ’ ἆρ’ ὁ Κωρυκαῖος ἠκροάζετο,<br>ὅταν δοκῇ τις πράττειν δι’ ἀπορρήτων ἢ λαλεῖν, μὴ λανθάνῃ δὲ διὰ τοὺς κατασκοποῦντας καὶ φιλοπευστοῦντας τὰ μὴ προσήκοντα.", "st": "14.1.32"}, {"sp": "N", "t": "μετὰ δὲ Κώρυκον Ἁλόννησος νησίον· εἶτα τὸ Ἄργεννον, ἄκρα τῆς Ἐρυθραίας πλησιάζουσα μάλιστα τῷ Χίων Ποσειδίῳ ποιοῦντι πορθμὸν ὅσον ἑξήκοντα σταδίων. μεταξὺ δὲ τῶν Ἐρυθρῶν καὶ τοῦ Ὑποκρήμνου Μίμας ἐστὶν ὄρος ὑψηλὸν εὔθηρον πολύδενδρον· εἶτα κώμη Κυβέλεια καὶ ἄκρα Μέλαινα καλουμένη μύλων ἔχουσα λατόμιον.", "st": "14.1.33"}, {"sp": "N", "t": "ἐκ δ’ Ἐρυθρῶν Σίβυλλά ἐστιν, ἔνθους καὶ μαντικὴ γυνὴ τῶν ἀρχαίων τις· κατ’ Ἀλέξανδρον δὲ ἄλλη ἦν τὸν αὐτὸν τρόπον μαντική, καλουμένη Ἀθηναΐς, ἐκ τῆς αὐτῆς πόλεως· καὶ καθ’ ἡμᾶς Ἡρακλείδης Ἡροφίλειος ἰατρὸς συσχολαστὴς Ἀπολλωνίου τοῦ Μυός.", "st": "14.1.34"}, {"sp": "N", "t": "ἡ δὲ Χίος τὸν μὲν περίπλουν ἐστὶ σταδίων ἐνακοσίων παρὰ γῆν φερομένῳ, πόλιν δ’ ἔχει εὐλίμενον καὶ ναύσταθμον ναυσὶν ὀγδοήκοντα. ἐν δὲ τῷ περίπλῳ δεξιὰν τὴν νῆσον ἔχοντι ἀπὸ τῆς πόλεως πρῶτον μέν ἐστι τὸ Ποσείδιον, εἶτα Φάναι λιμὴν βαθύς, καὶ νεὼς Ἀπόλλωνος καὶ ἄλσος φοινίκων· εἶτα Νότιον ὕφορμος αἰγιαλός· εἶτα Λαΐους, καὶ οὗτος ὕφορμος αἰγιαλός, ὅθεν εἰς τὴν πόλιν ἑξήκοντα σταδίων ἰσθμός· περίπλους δὲ τριακοσίων ἑξήκοντα ὃν ἐπήλθομεν. εἶτα Μέλαινα ἄκρα, καθ’ ἣν τὰ Ψύρα νῆσος ἀπὸ πεντήκοντα σταδίων τῆς ἄκρας, ὑψηλή, πόλιν ὁμώνυμον ἔχουσα· κύκλος δὲ τῆς νήσου τετταράκοντα στάδιοι. εἶθ’ ἡ Ἀριουσία χώρα τραχεῖα καὶ ἀλίμενος σταδίων ὅσον τριάκοντα, οἶνον ἄριστον φέρουσα τῶν Ἑλληνικῶν. εἶτα τὸ Πελιναῖον ὄρος ὑψηλότατον τῶν ἐν τῇ νήσῳ. ἔχει δ’ ἡ νῆσος καὶ λατόμιον μαρμάρου λίθου. ἄνδρες δὲ Χῖοι γεγόνασιν ἐλλόγιμοι Ἴων τε ὁ τραγικὸς καὶ Θεόπομπος ὁ συγγραφεὺς καὶ Θεόκριτος ὁ σοφιστής· οὗτοι δὲ καὶ ἀντεπολιτεύσαντο ἀλλήλοις. ἀμφισβητοῦσι δὲ καὶ Ὁμήρου Χῖοι, μαρτύριον μέγα τοὺς Ὁμηρίδας καλουμένους ἀπὸ τοῦ ἐκείνου γένους προχειριζόμενοι, ὧν καὶ Πίνδαρος μέμνηται<br>ὅθεν περ καὶ Ὁμηρίδαι<br>ῥαπτῶν ἐπέων τὰ πόλλ’ ἀοιδοί<br>ἐκέκτηντο δὲ καὶ ναυτικόν ποτε Χῖοι, καὶ ἀνθήπτοντο τῆς κατὰ θάλατταν ἀρχῆς καὶ ἐλευθερίας. ἐκ Χίου δ’ εἰς Λέσβον νότῳ τετρακόσιοί που στάδιοι.", "st": "14.1.35"}, {"sp": "N", "t": "ἐκ δὲ τοῦ Ὑποκρήμνου Χύτριόν ἐστι τόπος, ὅπου πρότερον ἵδρυντο Κλαζομεναί· εἶθ’ ἡ νῦν πόλις νησία ἔχουσα προκείμενα ὀκτὼ γεωργούμενα· Κλαζομένιος δ’ ἦν ἀνὴρ ἐπιφανὴς Ἀναξαγόρας ὁ φυσικός, Ἀναξιμένους ὁμιλητὴς τοῦ Μιλησίου· διήκουσαν δὲ τούτου Ἀρχέλαος ὁ φυσικὸς καὶ Εὐριπίδης ὁ ποιητής. εἶθ’ ἱερὸν Ἀπόλλωνος καὶ θερμὰ ὕδατα καὶ ὁ Σμυρναίων κόλπος καὶ ἡ πόλις.", "st": "14.1.36"}, {"sp": "N", "t": "ἑξῆς δὲ ἄλλος κόλπος, ἐν ᾧ ἡ παλαιὰ Σμύρνα ἀπὸ εἴκοσι σταδίων τῆς νῦν. Λυδῶν δὲ κατασπασάντων τὴν Σμύρναν περὶ τετρακόσια ἔτη διετέλεσεν οἰκουμένη κωμηδόν· εἶτα ἀνήγειρεν αὐτὴν Ἀντίγονος, καὶ μετὰ ταῦτα Λυσίμαχος, καὶ νῦν ἐστι καλλίστη τῶν πασῶν, μέρος μέν τι ἔχουσα ἐπ’ ὄρει τετειχισμένον, τὸ δὲ πλέον ἐν πεδίῳ πρὸς τῷ λιμένι καὶ πρὸς τῷ μητρῴῳ καὶ πρὸς γυμνασίῳ. ἔστι δ’ ἡ ῥυμοτομία διάφορος ἐπ’ εὐθειῶν εἰς δύναμιν καὶ αἱ ὁδοὶ λιθόστρωτοι στοαί τε μεγάλαι τετράγωνοι, ἐπίπεδοί τε καὶ ὑπερῷοι· ἔστι δὲ καὶ βιβλιοθήκη καὶ τὸ Ὁμήρειον, στοὰ τετράγωνος, ἔχουσα νεὼν Ὁμήρου καὶ ξόανον· μεταποιοῦνται γὰρ καὶ οὗτοι διαφερόντως τοῦ ποιητοῦ, καὶ δὴ καὶ νόμισμά τι χαλκοῦν παρ’ αὐτοῖς Ὁμήρειον λέγεται. ῥεῖ δὲ πλησίον τοῦ τείχους ὁ Μέλης ποταμός. ἔστι δὲ πρὸς τῇ ἄλλῃ κατασκευῇ τῆς πόλεως καὶ λιμὴν κλειστός. ἓν δ’ ἐλάττωμα τῶν ἀρχιτεκτόνων οὐ μικρόν, ὅτι τὰς ὁδοὺς στορνύντες ὑπορρύσεις οὐκ ἔδωκαν αὐταῖς, ἀλλ’ ἐπιπολάζει τὰ σκύβαλα καὶ μάλιστα ἐν τοῖς ὄμβροις ἐπαφιεμένων τῶν ἀποσκευῶν. ἐνταῦθα Δολοβέλλας Τρεβώνιον ἐκπολιορκήσας ἀνεῖλεν, ἕνα τῶν δολοφονησάντων Καίσαρα τὸν θεόν, καὶ τῆς πόλεως παρέλυσε πολλὰ μέρη.", "st": "14.1.37"}, {"sp": "N", "t": "μετὰ δὲ Σμύρναν αἱ Λεῦκαι πολίχνιον, ὃ ἀπέστησεν Ἀριστόνικος μετὰ τὴν Ἀττάλου τοῦ φιλομήτορος τελευτήν, δοκῶν τοῦ γένους εἶναι τοῦ τῶν βασιλέων καὶ διανοούμενος εἰς ἑαυτὸν ποιεῖσθαι τὴν ἀρχήν· ἐντεῦθεν μὲν οὖν ἐξέπεσεν ἡττηθεὶς ναυμαχίᾳ περὶ τὴν Κυμαίαν ὑπὸ Ἐφεσίων, εἰς δὲ τὴν μεσόγαιαν ἀνιὼν ἤθροισε διὰ ταχέων πλῆθος ἀπόρων τε ἀνθρώπων καὶ δούλων ἐπ’ ἐλευθερίᾳ κατακεκλημένων, οὓς Ἡλιοπολίτας ἐκάλεσε. πρῶτον μὲν οὖν παρεισέπεσεν εἰς Θυάτειρα, εἶτ’ Ἀπολλωνίδα ἔσχεν, εἶτ’ ἄλλων ἐφίετο φρουρίων· οὐ πολὺν δὲ διεγένετο χρόνον, ἀλλ’ εὐθὺς αἵ τε πόλεις ἔπεμψαν πλῆθος, καὶ Νικομήδης ὁ Βιθυνὸς ἐπεκούρησε καὶ οἱ τῶν Καππαδόκων βασιλεῖς. ἔπειτα πρέσβεις Ῥωμαίων πέντε ἧκον, καὶ μετὰ ταῦτα στρατιὰ καὶ ὕπατος Πόπλιος Κράσσος, καὶ μετὰ ταῦτα Μάρκος Περπέρνας, ὃς καὶ κατέλυσε τὸν πόλεμον ζωγρίᾳ λαβὼν τὸν Ἀριστόνικον καὶ ἀναπέμψας εἰς Ῥώμην. ἐκεῖνος μὲν οὖν ἐν τῷ δεσμωτηρίῳ κατέστρεψε τὸν βίον, Περπέρναν δὲ νόσος διέφθειρε, Κράσσος δὲ περὶ Λεύκας ἐπιθεμένων τινῶν ἔπεσεν ἐν μάχῃ. Μάνιος δ’ Ἀκύλλιος ἐπελθὼν ὕπατος μετὰ δέκα πρεσβευτῶν διέταξε τὴν ἐπαρχίαν εἰς τὸ νῦν ἔτι συμμένον τῆς πολιτείας σχῆμα. μετὰ δὲ Λεύκας Φώκαια ἐν κόλπῳ· περὶ δὲ ταύτης εἰρήκαμεν ἐν τῷ περὶ Μασσαλίας λόγῳ. εἶθ’ οἱ ὅροι τῶν Ἰώνων καὶ τῶν Αἰολέων· εἴρηται δὲ καὶ περὶ τούτων. ἐν δὲ τῇ μεσογαίᾳ τῆς Ἰωνικῆς παραλίας λοιπά ἐστι τὰ περὶ τὴν ὁδὸν τὴν ἐξ Ἐφέσου μέχρι Ἀντιοχείας καὶ τοῦ Μαιάνδρου. ἔστι δὲ καὶ τὰ χωρία ταῦτα Λυδοῖς καὶ Καρσὶν ἐπίμικτα καὶ τοῖς Ἕλλησι.", "st": "14.1.38"}, {"sp": "N", "t": "πρώτη δ’ ἐστὶν ἐξ Ἐφέσου Μαγνησία πόλις Αἰολίς, λεγομένη δὲ ἐπὶ Μαιάνδρῳ· πλησίον γὰρ αὐτοῦ ἵδρυται· πολὺ δὲ πλησιαίτερον ὁ Ληθαῖος ἐμβάλλων εἰς τὸν Μαίανδρον, τὴν δ’ ἀρχὴν ἔχων ἀπὸ Πακτύου τοῦ τῶν Ἐφεσίων ὄρους· ἕτερος δ’ ἐστὶ Ληθαῖος ὁ ἐν Γορτύνῃ καὶ ὁ περὶ Τρίκκην, ἐφ’ ᾧ ὁ Ἀσκληπιὸς γεννηθῆναι λέγεται, καὶ ἔτι ἐν τοῖς Ἑσπερίταις Λίβυσι. κεῖται δ’ ἐν πεδίῳ πρὸς ὄρει καλουμένῳ Θώρακι ἡ πόλις, ἐφ’ ᾧ σταυρωθῆναί φασι Δαφίταν τὸν γραμματικὸν λοιδορήσαντα τοὺς βασιλέας διὰ διστίχου<br>πορφύρεοι μώλωπες, ἀπορρινήματα γάζης<br>Λυσιμάχου, Λυδῶν ἄρχετε καὶ Φρυγίης.<br>καὶ λόγιον δ’ ἐκπεσεῖν αὐτῷ λέγεται φυλάττεσθαι τὸν Θώρακα.", "st": "14.1.39"}, {"sp": "N", "t": "δοκοῦσι δ’ εἶναι Μάγνητες Δελφῶν ἀπόγονοι τῶν ἐποικησάντων τὰ Δίδυμα ὄρη ἐν Θετταλίᾳ, περὶ ὧν φησιν Ἡσίοδος<br>ἢ οἵη Διδύμους ἱεροὺς ναίουσα κολωνούς,<br>Δωτίῳ ἐν πεδίῳ πολυβότρυος ἄντ’ Ἀμύροιο,<br>νίψατο Βοιβιάδος λίμνης πόδα παρθένος ἀδμής.<br>ἐνταῦθα δ’ ἦν καὶ τὸ τῆς Δινδυμήνης ἱερὸν μητρὸς θεῶν· ἱεράσασθαι δ’ αὐτοῦ τὴν Θεμιστοκλέους γυναῖκα, οἱ δὲ θυγατέρα παραδιδόασι· νῦν δ’ οὐκ ἔστι τὸ ἱερὸν διὰ τὸ τὴν πόλιν εἰς ἄλλον μετῳκίσθαι τόπον· ἐν δὲ τῇ νῦν πόλει τὸ τῆς Λευκοφρυήνης ἱερὸν ἔστιν Ἀρτέμιδος, ὃ τῷ μὲν μεγέθει τοῦ ναοῦ καὶ τῷ πλήθει τῶν ἀναθημάτων λείπεται τοῦ ἐν Ἐφέσῳ, τῇ δ’ εὐρυθμίᾳ καὶ τῇ τέχνῃ τῇ περὶ τὴν κατασκευὴν τοῦ σηκοῦ πολὺ διαφέρει· καὶ τῷ μεγέθει ὑπεραίρει πάντας τοὺς ἐν Ἀσίᾳ πλὴν δυεῖν, τοῦ ἐν Ἐφέσῳ καὶ τοῦ ἐν Διδύμοις. καὶ τὸ παλαιὸν δὲ συνέβη τοῖς Μάγνησιν ὑπὸ Τρηρῶν ἄρδην ἀναιρεθῆναι, Κιμμερικοῦ ἔθνους, εὐτυχήσαντας πολὺν χρόνον, τὸ δ’ ἑξῆς τοὺς Ἐφεσίους κατασχεῖν τὸν τόπον. Καλλῖνος μὲν οὖν ὡς εὐτυχούντων ἔτι τῶν Μαγνήτων μέμνηται καὶ κατορθούντων ἐν τῷ πρὸς τοὺς Ἐφεσίους πολέμῳ, Ἀρχίλοχος δὲ ἤδη φαίνεται γνωρίζων τὴν γενομένην αὐτοῖς συμφοράν<br>κλαίειν τὰ Θασίων, οὗ τὰ Μαγνήτων κακά.<br>ἐξ οὗ καὶ [αὐ]τὸν νεώτερον εἶναι τοῦ Καλλίνου τεκμαίρεσθαι πάρεστιν. ἄλλης δέ τινος ἐφόδου τῶν Κιμμερίων μέμνηται πρεσβυτέρας ὁ Καλλῖνος ἐπὰν φῇ<br>νῦν δ’ ἐπὶ Κιμμερίων στρατὸς ἔρχεται ὀβριμοεργῶν,<br>ἐν ᾗ τὴν Σάρδεων ἅλωσιν δηλοῖ.", "st": "14.1.40"}, {"sp": "N", "t": "ἄνδρες δ’ ἐγένοντο γνώριμοι Μάγνητες Ἡγησίας τε ὁ ῥήτωρ, ὃς ἦρξε μάλιστα τοῦ Ἀσιανοῦ λεγομένου ζήλου παραφθείρας τὸ καθεστὼς ἔθος τὸ Ἀττικόν, καὶ Σῖμος ὁ μελοποιὸς παραφθείρας καὶ αὐτὸς τὴν τῶν προτέρων μελοποιῶν ἀγωγὴν καὶ τὴν σιμῳδίαν εἰσαγαγών (καθάπερ ἔτι μᾶλλον λυσιῳδοὶ καὶ μαγῳδοί), καὶ Κλεόμαχος ὁ πύκτης, ὃς εἰς ἔρωτα ἐμπεσὼν κιναίδου τινὸς καὶ παιδίσκης ὑπὸ [τῷ] κιναίδῳ τρεφομένης ἀπεμιμήσατο τὴν ἀγωγὴν τῶν παρὰ τοῖς κιναίδοις διαλέκτων καὶ τῆς ἠθοποιίας· ἦρξε δὲ Σωτάδης μὲν πρῶτος τοῦ κιναιδολογεῖν, ἔπειτα Ἀλέξανδρος ὁ Αἰτωλός· ἀλλ’ οὗτοι μὲν ἐν ψιλῷ λόγῳ, μετὰ μέλους δὲ Λῦσις, καὶ ἔτι πρότερος τούτου ὁ Σῖμος. Ἀναξήνορα δὲ τὸν κιθαρῳδὸν ἐξῆρε μὲν καὶ τὰ θέατρα, ἀλλ’ ὅτι μάλιστα Ἀντώνιος, ὅς γε καὶ τεττάρων πόλεων ἀπέδειξε φορολόγον στρατιώτας αὐτῷ συστήσας. καὶ ἡ πατρὶς δ’ ἱκανῶς αὐτὸν ηὔξησε πορφύραν ἐνδύσασα ἱερωμένον τοῦ σωσιπόλιδος Διός, καθάπερ καὶ ἡ γραπτὴ εἰκὼν ἐμφανίζει ἡ ἐν τῇ ἀγορᾷ. ἔστι δὲ καὶ χαλκῆ εἰκὼν ἐν τῷ θεάτρῳ ἐπιγραφὴν ἔχουσα<br>ἤτοι μὲν τόδε καλὸν ἀκουέμεν ἐστὶν ἀοιδοῦ τοιοῦδ’, οἷος ὅδ’ ἐστί, θεοῖς ἐναλίγκιος αὐδῇ.<br>οὐ στοχασάμενος δὲ ὁ ἐπιγράψας τὸ τελευταῖον γράμμα τοῦ δευτέρου ἔπους παρέλιπε τοῦ πλάτους τῆς βάσεως μὴ συνεξαρκοῦντος, ὥστε τῆς πόλεως ἀμαθίαν καταγινώσκειν παρέσχε διὰ τὴν ἀμφιβολίαν τὴν περὶ τὴν γραφήν, εἴτε τὴν ὀνομαστικὴν δέχοιτο πτῶσιν τῆς ἐσχάτης προσηγορίας εἴτε τὴν δοτικήν· πολλοὶ γὰρ χωρὶς τοῦ ι γράφουσι τὰς δοτικάς, καὶ ἐκβάλλουσι δὲ τὸ ἔθος φυσικὴν αἰτίαν οὐκ ἔχον.", "st": "14.1.41"}, {"sp": "N", "t": "μετὰ δὲ Μαγνησίαν ἡ ἐπὶ Τράλλεις ἐστὶν ὁδὸς ἐν ἀριστερᾷ μὲν τὴν Μεσωγίδα ἔχουσιν, ἐν αὐτῇ δὲ τῇ ὁδῷ καὶ ἐν δεξιᾷ τὸ Μαιάνδρου πεδίον, Λυδῶν ἅμα καὶ Καρῶν νεμομένων καὶ Ἰώνων Μιλησίων τε καὶ Μυησίων, ἔτι δὲ Αἰολέων τῶν ἐν Μαγνησίᾳ· ὁ δ’ αὐτὸς τρόπος τῆς τοποθεσίας καὶ μέχρι Νύσης καὶ Ἀντιοχείας. ἵδρυται δ’ ἡ μὲν τῶν Τραλλιανῶν πόλις ἐπὶ τραπεζίου τινὸς ἄκραν ἔχοντος ἐρυμνήν· καὶ τὰ κύκλῳ δ’ ἱκανῶς εὐερκῆ· συνοικεῖται δὲ καλῶς εἴ τις ἄλλη τῶν κατὰ τὴν Ἀσίαν ὑπὸ εὐπόρων ἀνθρώπων, καὶ ἀεί τινες ἐξ αὐτῆς εἰσιν οἱ πρωτεύοντες κατὰ τὴν ἐπαρχίαν, οὓς Ἀσιάρχας καλοῦσιν· ὧν Πυθόδωρός τε ἦν, ἀνὴρ Νυσαεὺς τὸ ἐξ ἀρχῆς, ἐκεῖσε δὲ μεταβεβηκὼς διὰ τὴν ἐπιφάνειαν καὶ ἐν τῇ πρὸς Πομπήιον φιλίᾳ διαπρέπων μετ’ ὀλίγων· περιεβέβλητο δὲ καὶ οὐσίαν βασιλικὴν πλειόνων ἢ δισχιλίων ταλάντων, ἣν ὑπὸ Καίσαρος τοῦ θεοῦ πραθεῖσαν διὰ τὴν πρὸς Πομπήιον φιλίαν ἐξωνησάμενος οὐχ ἥττω τοῖς παισὶ κατέλιπε· τούτου δ’ ἐστὶ θυγάτηρ Πυθοδωρὶς ἡ νῦν βασιλεύουσα ἐν τῷ Πόντῳ, περὶ ἧς εἰρήκαμεν. οὗτός [τε] δὴ καθ’ ἡμᾶς ἤκμασε καὶ Μηνόδωρος, ἀνὴρ λόγιος καὶ ἄλλως σεμνὸς καὶ βαρύς, ἔχων τὴν ἱερωσύνην τοῦ Διὸς τοῦ Λαρισαίου· κατεστασιάσθη δ’ ὑπὸ τῶν Δομετίου τοῦ Ἀηνοβάρβου φίλων, καὶ ἀνεῖλεν αὐτὸν ἐκεῖνος ὡς ἀφιστάντα τὸ ναυτικόν, πιστεύσας τοῖς ἐνδειξαμένοις. ἐγένοντο δὲ καὶ ῥήτορες ἐπιφανεῖς Διονυσοκλῆς τε καὶ μετὰ ταῦτα Δάμασος ὁ σκόμβρος. κτίσμα δέ φασιν εἶναι τὰς Τράλλεις Ἀργείων καί τινων Θρᾳκῶν Τραλλίων, ἀφ’ ὧν τοὔνομα. τυραννηθῆναι δ’ ὀλίγον συνέπεσε χρόνον τὴν πόλιν ὑπὸ τῶν Κρατίππου παίδων κατὰ τὰ Μιθριδατικά.", "st": "14.1.42"}, {"sp": "N", "t": "Νῦσα δ’ ἵδρυται πρὸς τῇ Μεσωγίδι τὸ πλέον τῷ ὄρει προσανακεκλιμένη, ἔστι δ’ ὥσπερ δίπολις· διαιρεῖ γὰρ αὐτὴν χαράδρα τις ποιοῦσα φάραγγα, ἧς τὸ μὲν γέφυραν ἐπικειμένην ἔχει συνάπτουσαν τὰς δύο πόλεις, τὸ δ’ ἀμφιθεάτρῳ κεκόσμηται κρυπτὴν ἔχοντι τὴν ὑπόρρυσιν τῶν χαραδρωδῶν ὑδάτων· τῷ δὲ θεάτρῳ δύο ἄκραι, ὧν τῇ μὲν ὑπόκειται τὸ γυμνάσιον τῶν νέων, τῇ δ’ ἀγορὰ καὶ τὸ γεροντικόν· πρὸς δὲ νότον ὑποπέπτωκε τῇ πόλει τὸ πεδίον, καθάπερ καὶ ταῖς Τράλλεσιν.", "st": "14.1.43"}, {"sp": "N", "t": "ἐν δὲ τῇ ὁδῷ τῇ μεταξὺ τῶν Τράλλεων καὶ τῆς Νύσης κώμη τῶν Νυσαέων ἐστὶν οὐκ ἄπωθεν τῆς πόλεως Ἀχάρακα, ἐν ᾗ τὸ Πλουτώνιον ἔχον καὶ ἄλσος πολυτελὲς καὶ νεὼν Πλούτωνός τε καὶ Κόρης, καὶ τὸ Χαρώνιον ἄντρον ὑπερκείμενον τοῦ ἄλσους θαυμαστὸν τῇ φύσει· λέγουσι γὰρ δὴ τοὺς νοσώδεις καὶ προσέχοντας ταῖς τῶν θεῶν τούτων θεραπείαις φοιτᾶν ἐκεῖσε καὶ διαιτᾶσθαι ἐν τῇ κώμῃ πλησίον τοῦ ἄντρου παρὰ τοῖς ἐμπείροις τῶν ἱερέων, οἳ ἐγκοιμῶνταί τε ὑπὲρ αὐτῶν καὶ διατάττουσιν ἐκ τῶν ὀνείρων τὰς θεραπείας. οὗτοι δ’ εἰσὶ καὶ οἱ ἐπικαλοῦντες τὴν τῶν θεῶν ἰατρείαν· ἄγουσι δὲ πολλάκις εἰς τὸ ἄντρον καὶ ἱδρύουσι μένοντας καθ’ ἡσυχίαν ἐκεῖ καθάπερ ἐν φωλεῷ σιτίων χωρὶς ἐπὶ πλείους ἡμέρας. ἔστι δ’ ὅτε καὶ ἰδίοις ἐνυπνίοις οἱ νοσηλευόμενοι προσέχουσι, μυσταγωγοῖς δ’ ὅμως καὶ συμβούλοις ἐκείνοις χρῶνται ὡς ἂν ἱερεῦσι· τοῖς δ’ ἄλλοις ἄδυτός ἐστιν ὁ τόπος καὶ ὀλέθριος. πανήγυρις δ’ ἐν τοῖς Ἀχαράκοις συντελεῖται κατ’ ἔτος, καὶ τότε μάλιστα ὁρᾶν ἔστι καὶ ἀκούειν περὶ τῶν νοσούντων τοὺς πανηγυρίζοντας· τότε δὲ καὶ περὶ τὴν μεσημβρίαν ὑπολαβόντες ταῦρον οἱ ἐκ τοῦ γυμνασίου νέοι καὶ ἔφηβοι γυμνοὶ λίπ’ ἀληλιμμένοι μετὰ σπουδῆς ἀνακομίζουσιν εἰς τὸ ἄντρον· ἀφεθεὶς δὲ μικρὸν προελθὼν πίπτει καὶ ἔκπνους γίνεται.", "st": "14.1.44"}, {"sp": "N", "t": "ἀπὸ δὲ τριάκοντα σταδίων τῆς Νύσης ὑπερβᾶσι Τμῶλον καὶ τὸ ὄρος τὴν Μεσωγίδα ἐπὶ τὰ πρὸς νότον μέρη καλεῖται τόπος Λειμών, εἰς ὃν ἐξοδεύουσι πανηγυριοῦντες Νυσαεῖς τε καὶ οἱ κύκλῳ πάντες· οὐ πόρρω δὲ τούτου στόμιόν ἐστιν ἱερὸν τῶν αὐτῶν θεῶν, ὅ φασι καθήκειν μέχρι τῶν Ἀχαράκων. τοῦτον δὲ τὸν λειμῶνα ὀνομάζειν τὸν ποιητήν φασιν ὅταν φῇ “Ἀσίω ἐν λειμῶνι,” δεικνύντες Καϋστρίου καὶ Ἀσίου τινὸς ἡρῷον καὶ τὸν Κάυστρον πλησίον ἀπορρέοντα.", "st": "14.1.45"}, {"sp": "N", "t": "ἱστοροῦσι δὲ τρεῖς ἀδελφούς, Ἄθυμβρόν τε καὶ Ἀθύμβραδον καὶ Ὕδρηλον, ἐλθόντας ἐκ Λακεδαίμονος τὰς ἐπωνύμους ἑαυτῶν κτίσαι πόλεις, λιπανδρῆσαι δ’ ὕστερον, ἐξ ἐκείνων δὲ συνοικισθῆναι τὴν Νῦσαν· καὶ νῦν Ἄθυμβρον ἀρχηγέτην νομίζουσιν οἱ Νυσαεῖς.", "st": "14.1.46"}, {"sp": "N", "t": "περίκεινται δὲ ἀξιόλογοι κατοικίαι πέραν τοῦ Μαιάνδρου, Κοσκίνια καὶ Ὀρθωσία· ἐντὸς δὲ Βρίουλα Μάσταυρα Ἀχάρακα καὶ ὑπὲρ τῆς πόλεως ἐν τῷ ὄρει τὰ Ἄρομα, ὅθεν ἄριστος Μεσωγίτης οἶνος ὁ Ἀρομεύς.", "st": "14.1.47"}, {"sp": "N", "t": "ἄνδρες δὲ γεγόνασιν ἔνδοξοι Νυσαεῖς Ἀπολλώνιός τε ὁ στωικὸς φιλόσοφος τῶν Παναιτίου γνωρίμων ἄριστος, καὶ Μενεκράτης Ἀριστάρχου μαθητής, καὶ Ἀριστόδημος ἐκείνου υἱός, οὗ διηκούσαμεν ἡμεῖς ἐσχατόγηρω νέοι παντελῶς ἐν τῇ Νύσῃ· καὶ Σώστρατος δὲ ὁ ἀδελφὸς τοῦ Ἀριστοδήμου καὶ ἄλλος Ἀριστόδημος ἀνεψιὸς αὐτοῦ ὁ παιδεύσας Μάγνον Πομπήιον ἀξιόλογοι γεγόνασι γραμματικοί· ὁ δ’ ἡμέτερος καὶ ἐρρητόρευε καὶ ἐν τῇ Ῥόδῳ καὶ ἐν τῇ πατρίδι δύο σχολὰς συνεῖχε, πρωὶ μὲν τὴν ῥητορικὴν δείλης δὲ τὴν γραμματικὴν σχολήν· ἐν δὲ τῇ Ῥώμῃ τῶν Μάγνου παίδων ἐπιστατῶν ἠρκεῖτο τῇ γραμματικῇ σχολῇ.", "st": "14.1.48"}, {"sp": "N", "t": "τὰ δὲ πέραν ἤδη τοῦ Μαιάνδρου τὰ λειπόμενα τῆς περιοδείας πάντ’ ἐστὶ Καρικά, οὐκέτι τοῖς Λυδοῖς ἐπιμεμιγμένων ἐνταῦθα τῶν Καρῶν ἀλλ’ ἤδη καθ’ αὑτοὺς ὄντων, πλὴν εἴ τι Μιλήσιοι καὶ Μυούσιοι τῆς παραλίας ἀποτέτμηνται. ἀρχὴ μὲν οὖν τῆς Καρίας ἐστὶν ἡ τῶν Ῥοδίων περαία πρὸς θαλάττης, τέλος δὲ τὸ Ποσείδιον τῶν Μιλησίων, ἐν δὲ τῇ μεσογαίᾳ τὰ ἄκρα τοῦ Ταύρου μέχρι Μαιάνδρου. λέγουσι γὰρ ἀρχὴν εἶναι τοῦ Ταύρου τὰ ὑπερκείμενα ὄρη τῶν Χελιδονίων καλουμένων νήσων, αἵπερ ἐν μεθορίῳ τῆς Παμφυλίας καὶ τῆς Λυκίας πρόκεινται· ἐντεῦθεν γὰρ ἐξαίρεται πρὸς ὕψος ὁ Ταῦρος· τὸ δ’ ἀληθὲς καὶ τὴν Λυκίαν ἅπασαν ὀρεινὴ ῥάχις τοῦ Ταύρου διείργει πρὸς τὰ ἐκτὸς καὶ τὸ νότιον μέρος ἀπὸ τῶν Κιβυρατικῶν μέχρι τῆς περαίας τῶν Ῥοδίων. κἀνταῦθα δ’ ἐστὶ συνεχὴς ὀρεινή, πολὺ μέντοι ταπεινοτέρα καὶ οὐκέτι τοῦ Ταύρου νομίζεται, οὐδὲ τὰ μὲν ἐκτὸς αὐτοῦ τὰ δ’ ἐντός, διὰ τὸ σποράδας εἶναι τὰς ἐξοχὰς καὶ τὰς εἰσοχὰς ἐπίσης εἴς τε πλάτος καὶ μῆκος τῆς χώρας ἁπάσης καὶ μηδὲν ἔχειν ὅμοιον διατειχίσματι. ἔστι δ’ ἅπας μὲν ὁ περίπλους κατακολπίζοντι σταδίων τετρακισχιλίων ἐνακοσίων, αὐτὸς δὲ ὁ τῆς περαίας τῶν Ῥοδίων ἐγγὺς χιλίων καὶ πεντακοσίων.", "st": "14.2.1"}, {"sp": "N", "t": "ἀρχὴ δὲ τὰ Δαίδαλα τῆς Ῥοδίας χωρίον, πέρας δὲ τὸ καλούμενον ὄρος Φοίνιξ, καὶ τοῦτο τῆς Ῥοδίας. πρόκειται δ’ Ἐλαιοῦσσα νῆσος διέχουσα τῆς Ῥόδου σταδίους ἑκατὸν εἴκοσι. μεταξὺ δὲ πρῶτον μὲν ἀπὸ Δαιδάλων πλέουσιν ἐπὶ τὴν δύσιν ἐπ’ εὐθείας τῇ ἐκ Κιλικίας καὶ Παμφυλίας καὶ Λυκίας παραλίᾳ κόλπος ἐστὶν εὐλίμενος Γλαῦκος καλούμενος, εἶτα τὸ Ἀρτεμίσιον ἄκρα καὶ ἱερόν, εἶτα τὸ Λητῷον ἄλσος· ὑπὲρ αὐτοῦ δὲ καὶ τῆς θαλάττης ἐν ἑξήκοντα σταδίοις Κάλυνδα πόλις· εἶτα Καῦνος καὶ ποταμὸς πλησίον Κάλβις βαθὺς ἔχων εἰσαγωγήν, καὶ μεταξὺ Πίσιλις.", "st": "14.2.2"}, {"sp": "N", "t": "ἔχει δ’ ἡ πόλις νεώρια καὶ λιμένα κλειστόν· ὑπέρκειται δὲ τῆς πόλεως ἐν ὕψει φρούριον Ἴμβρος. τῆς δὲ χώρας εὐδαίμονος οὔσης ἡ πόλις τοῦ θέρους ὁμολογεῖται παρὰ πάντων εἶναι δυσάερος καὶ τοῦ μετοπώρου … διὰ τὰ καύματα καὶ τὴν ἀφθονίαν τῶν ὡραίων· καὶ δὴ καὶ τὰ τοιαῦτα διηγημάτια θρυλεῖται, ὅτι Στρατόνικος ὁ κιθαριστὴς ἰδὼν ἐπιμελῶς χλωροὺς τοὺς Καυνίους, τοῦτ’ εἶναι ἔφη τὸ τοῦ ποιητοῦ<br>οἵη περ φύλλων γενεή, τοιήδε καὶ ἀνδρῶν.<br>μεμφομένων δὲ ὡς σκώπτοιτο αὐτῷ ἡ πόλις ὡς νοσερά “ἐγώ” ἔφη “ταύτην θαρρήσαιμ’ ἂν λέγειν νοσεράν, ὅπου καὶ οἱ νεκροὶ περιπατοῦσιν;” ἀπέστησαν δέ ποτε Καύνιοι τῶν Ῥοδίων· κριθέντες δ’ ἐπὶ τῶν Ῥωμαίων ἀπελήφθησαν πάλιν· καὶ ἔστι λόγος Μόλωνος κατὰ Καυνίων. φασὶ δ’ αὐτοὺς ὁμογλώττους μὲν εἶναι τοῖς Καρσίν, ἀφῖχθαι δ’ ἐκ Κρήτης καὶ χρῆσθαι νόμοις ἰδίοις.", "st": "14.2.3"}, {"sp": "N", "t": "ἑξῆς δὲ Φύσκος πολίχνη λιμένα ἔχουσα καὶ ἄλσος Λητῷον· εἶτα Λώρυμα παραλία τραχεῖα, καὶ ὄρος ὑψηλότατον τῶν ταύτῃ (ἐπ’ ἄκρῳ δὲ φρούριον ὁμώνυμον τῷ ὄρει) Φοῖνιξ· πρόκειται δ’ ἡ Ἐλαιοῦσσα νῆσος ἐν τέτταρσι σταδίοις κύκλον ἔχουσα ὅσον ὀκτωστάδιον.", "st": "14.2.4"}, {"sp": "N", "t": "ἡ δὲ τῶν Ῥοδίων πόλις κεῖται μὲν ἐπὶ τοῦ ἑωθινοῦ ἀκρωτηρίου, λιμέσι δὲ καὶ ὁδοῖς καὶ τείχεσι καὶ τῇ ἄλλῃ κατασκευῇ τοσοῦτον διαφέρει τῶν ἄλλων ὥστ’ οὐκ ἔχομεν εἰπεῖν ἑτέραν ἀλλ’ οὐδὲ πάρισον, μή τί γε κρείττω ταύτης τῆς πόλεως. θαυμαστὴ δὲ καὶ ἡ εὐνομία καὶ ἡ ἐπιμέλεια πρός τε τὴν ἄλλην πολιτείαν καὶ τὴν περὶ τὰ ναυτικά, ἀφ’ ἧς ἐθαλαττοκράτησε πολὺν χρόνον καὶ τὰ λῃστήρια καθεῖλε καὶ Ῥωμαίοις ἐγένετο φίλη καὶ τῶν βασιλέων τοῖς φιλορωμαίοις τε καὶ φιλέλλησιν· ἀφ’ ὧν αὐτόνομός τε διετέλεσε καὶ πολλοῖς ἀναθήμασιν ἐκοσμήθη, ἃ κεῖται τὰ μὲν πλεῖστα ἐν τῷ Διονυσίῳ καὶ τῷ γυμνασίῳ, ἄλλα δ’ ἐν ἄλλοις τόποις. ἄριστα δὲ ὅ τε τοῦ Ἡλίου κολοσσός, ὅν φησιν ὁ ποιήσας τὸ ἰαμβεῖον ὅτι<br>ἑπτάκις δέκα<br>Χάρης ἐποίει πηχέων ὁ Λίνδιος.<br>κεῖται δὲ νῦν ὑπὸ σεισμοῦ πεσὼν περικλασθεὶς ἀπὸ τῶν γονάτων· οὐκ ἀνέστησαν δ’ αὐτὸν κατά τι λόγιον. τοῦτό τε δὴ τῶν ἀναθημάτων κράτιστον (τῶν γοῦν ἑπτὰ θεαμάτων ὁμολογεῖται) καὶ αἱ τοῦ Πρωτογένους γραφαί, ὅ τε Ἰάλυσος καὶ ὁ Σάτυρος παρεστὼς στύλῳ, ἐπὶ δὲ τῷ στύλῳ πέρδιξ ἐφειστήκει, πρὸς ὃν οὕτως ἐκεχήνεσαν ὡς ἔοικεν οἱ ἄνθρωποι νεωστὶ ἀνακειμένου τοῦ πίνακος, ὥστ’ ἐκεῖνον ἐθαύμαζον, ὁ δὲ Σάτυρος παρεωρᾶτο καίτοι σφόδρα κατωρθωμένος· ἐξέπληττον δ’ ἔτι μᾶλλον οἱ περδικοτρόφοι κομίζοντες τοὺς τιθασοὺς καὶ τιθέντες καταντικρύ· ἐφθέγγοντο γὰρ πρὸς τὴν γραφὴν οἱ πέρδικες καὶ ὠχλαγώγουν. ὁρῶν δὲ ὁ Πρωτογένης τὸ ἔργον πάρεργον γεγονὸς ἐδεήθη τῶν τοῦ τεμένους προεστώτων ἐπιτρέψαι παρελθόντα ἐξαλεῖψαι τὸν ὄρνιν καὶ ἐποίησε. δημοκηδεῖς δ’ εἰσὶν οἱ Ῥόδιοι καίπερ οὐ δημοκρατούμενοι, συνέχειν δ’ ὅμως βουλόμενοι τὸ τῶν πενήτων πλῆθος. σιταρχεῖται δὴ ὁ δῆμος καὶ οἱ εὔποροι τοὺς ἐνδεεῖς ὑπολαμβάνουσιν ἔθει τινὶ πατρίῳ, λειτουργίαι τέ τινές εἰσιν ὀψωνιζόμεναι, ὥσθ’ ἅμα τόν τε πένητα ἔχειν τὴν διατροφὴν καὶ τὴν πόλιν τῶν χρειῶν μὴ καθυστερεῖν καὶ μάλιστα πρὸς τὰς ναυστολίας. τῶν δὲ ναυστάθμων τινὰ καὶ κρυπτὰ ἦν καὶ ἀπόρρητα τοῖς πολλοῖς, τῷ δὲ κατοπτεύσαντι ἢ παρελθόντι εἴσω θάνατος ὥριστο ἡ ζημία. κἀνταῦθα δὲ ὥσπερ ἐν Μασσαλίᾳ καὶ Κυζίκῳ τὰ περὶ τοὺς ἀρχιτέκτονας καὶ τὰς ὀργανοποιίας καὶ θησαυροὺς ὅπλων τε καὶ τῶν ἄλλων ἐσπούδασται διαφερόντως, καὶ ἔτι γε τῶν παρ’ ἄλλοις μᾶλλον.", "st": "14.2.5"}, {"sp": "N", "t": "Δωριεῖς δ’ εἰσὶν ὥσπερ καὶ Ἁλικαρνασεῖς καὶ Κνίδιοι καὶ Κῷοι. οἱ γὰρ Δωριεῖς οἱ τὰ Μέγαρα κτίσαντες μετὰ τὴν Κόδρου τελευτὴν οἱ μὲν ἔμειναν αὐτόθι, οἱ δὲ σὺν Ἀλθαιμένει τῷ Ἀργείῳ τῆς εἰς Κρήτην ἀποικίας ἐκοινώνησαν, οἱ δ’ εἰς τὴν Ῥόδον καὶ τὰς λεχθείσας ἀρτίως πόλεις ἐμερίσθησαν. ταῦτα δὲ νεώτερα τῶν ὑφ’ Ὁμήρου λεγομένων ἐστί· Κνίδος μὲν γὰρ καὶ Ἁλικαρνασὸς οὐδ’ ἦν πω, Ῥόδος δ’ ἦν καὶ Κῶς, ἀλλ’ ᾠκεῖτο ὑφ’ Ἡρακλειδῶν. Τληπόλεμος μὲν οὖν ἀνδρωθεὶς<br>αὐτίκα πατρὸς ἑοῖο φίλον μήτρωα κατέκτα<br>ἤδη γηράσκοντα, Λικύμνιον.<br>αἶψα δὲ νῆας ἔπηξε, πολὺν δ’ ὅγε λαὸν ἀγείρας<br>βῆ φεύγων.<br>εἶτά φησιν<br>εἰς Ῥόδον ἷξεν ἀλώμενος,<br>τριχθὰ δὲ ᾤκηθεν καταφυλαδόν.<br>καὶ τὰς πόλεις ὀνομάζει τὰς τότε<br>Λίνδον Ἰηλυσόν τε καὶ ἀργινόεντα Κάμειρον,<br>τῆς Ῥοδίων πόλεως οὔπω συνῳκισμένης. οὐδαμοῦ δὴ ἐνταῦθα Δωριέας ὀνομάζει, ἀλλ’ εἰ ἄρα Αἰολέας ἐμφαίνει καὶ Βοιωτούς, εἴπερ ἐκεῖ ἡ κατοικία τοῦ Ἡρακλέους καὶ τοῦ Λικυμνίου· εἰ δ’ ὥσπερ καὶ ἄλλοι φασίν, ἐξ Ἄργους καὶ Τίρυνθος ἀπῆρεν ὁ Τληπόλεμος, οὐδ’ οὕτω Δωρικὴ γίνεται ἡ ἐκεῖθεν ἀποικία· πρὸ γὰρ τῆς Ἡρακλειδῶν καθόδου γεγένηται. καὶ τῶν Κῴων δὲ<br>Φείδιππός τε καὶ Ἄντιφος ἡγησάσθην,<br>Θεσσαλοῦ υἷε δύω Ἡρακλείδαο ἄνακτος,<br>καὶ οὗτοι τὸ Αἰολικὸν μᾶλλον ἢ τὸ Δωρικὸν γένος ἐμφαίνοντες.", "st": "14.2.6"}, {"sp": "N", "t": "ἐκαλεῖτο δ’ ἡ Ῥόδος πρότερον Ὀφιοῦσσα καὶ Σταδία, εἶτα Τελχινὶς ἀπὸ τῶν οἰκησάντων Τελχίνων τὴν νῆσον, οὓς οἱ μὲν βασκάνους φασὶ καὶ γόητας θείῳ καταρραίνοντας τὸ τῆς Στυγὸς ὕδωρ ζώων τε καὶ φυτῶν ὀλέθρου χάριν, οἱ δὲ τέχναις διαφέροντας τοὐναντίον ὑπὸ τῶν ἀντιτέχνων βασκανθῆναι καὶ τῆς δυσφημίας τυχεῖν ταύτης, ἐλθεῖν δ’ ἐκ Κρήτης εἰς Κύπρον πρῶτον, εἶτ’ εἰς Ῥόδον, πρώτους δ’ ἐργάσασθαι σίδηρόν τε καὶ χαλκόν, καὶ δὴ καὶ τὴν ἅρπην τῷ Κρόνῳ δημιουργῆσαι. εἴρηται μὲν οὖν καὶ πρότερον περὶ αὐτῶν, ἀλλὰ ποιεῖ τὸ πολύμυθον ἀναλαμβάνειν πάλιν ἀναπληροῦντας εἴ τι παρελίπομεν.", "st": "14.2.7"}, {"sp": "N", "t": "μετὰ δὲ τοὺς Τελχῖνας οἱ Ἡλιάδαι μυθεύονται κατασχεῖν τὴν νῆσον, ὧν ἑνὸς Κερκάφου καὶ Κυδίππης γενέσθαι παῖδας τοὺς τὰς πόλεις κτίσαντας ἐπωνύμους αὑτῶν<br>Λίνδον Ἰηλυσόν τε καὶ ἀργινόεντα Κάμειρον.<br>ἔνιοι δὲ τὸν Τληπόλεμον κτίσαι φασί, θέσθαι δὲ τὰ ὀνόματα ὁμωνύμως τῶν Δαναοῦ θυγατέρων τισίν.", "st": "14.2.8"}, {"sp": "N", "t": "ἡ δὲ νῦν πόλις ἐκτίσθη κατὰ τὰ Πελοποννησιακὰ ὑπὸ τοῦ αὐτοῦ ἀρχιτέκτονος, ὥς φασιν, ὑφ’ οὗ καὶ ὁ Πειραιεύς· οὐ συμμένει δ’ ὁ Πειραιεύς, κακωθεὶς ὑπό τε Λακεδαιμονίων πρότερον τῶν τὰ σκέλη καθελόντων καὶ ὑπὸ Σύλλα τοῦ Ῥωμαίων ἡγεμόνος.", "st": "14.2.9"}, {"sp": "N", "t": "ἱστοροῦσι δὲ καὶ ταῦτα περὶ τῶν Ῥοδίων, ὅτι οὐ μόνον ἀφ’ οὗ χρόνου συνῴκισαν τὴν νῦν πόλιν εὐτύχουν κατὰ θάλατταν, ἀλλὰ καὶ πρὸ τῆς Ὀλυμπικῆς θέσεως συχνοῖς ἔτεσιν ἔπλεον πόρρω τῆς οἰκείας ἐπὶ σωτηρίᾳ τῶν ἀνθρώπων· ἀφ’ οὗ καὶ μέχρι Ἰβηρίας ἔπλευσαν, κἀκεῖ μὲν τὴν Ῥόδην ἔκτισαν ἣν ὕστερον Μασσαλιῶται κατέσχον, ἐν δὲ τοῖς Ὀπικοῖς τὴν Παρθενόπην, ἐν δὲ Δαυνίοις μετὰ Κῴων Ἐλπίας. τινὲς δὲ μετὰ τὴν ἐκ Τροίας ἄφοδον τὰς Γυμνησίας νήσους ὑπ’ αὐτῶν κτισθῆναι λέγουσιν, ὧν τὴν μείζω φησὶ Τίμαιος μεγίστην εἶναι μετὰ τὰς ἑπτά, Σαρδὼ Σικελίαν Κύπρον Κρήτην Εὔβοιαν Κύρνον Λέσβον, οὐ τἀληθῆ λέγων· πολὺ γὰρ ἄλλαι μείζους. φασὶ δὲ τοὺς γυμνήτας ὑπὸ Φοινίκων βαλεαρίδας λέγεσθαι, διότι τὰς Γυμνησίας Βαλεαρίδας λεχθῆναι. τινὲς δὲ τῶν Ῥοδίων καὶ περὶ Σύβαριν ᾤκησαν κατὰ τὴν Χωνίαν. ἔοικε δὲ καὶ ὁ ποιητὴς μαρτυρεῖν τὴν ἐκ παλαιοῦ παροῦσαν τοῖς Ῥοδίοις εὐδαιμονίαν εὐθὺς ἀπὸ τῆς πρώτης κτίσεως τῶν τριῶν πόλεων<br>τριχθὰ δὲ ᾤκηθεν καταφυλαδόν, ἠδ’ ἐφίληθεν<br>ἐκ Διός, ὅστε θεοῖσι καὶ ἀνθρώποισιν ἀνάσσει,<br>καί σφιν θεσπέσιον πλοῦτον κατέχευε Κρονίων.<br>οἱ δ’ εἰς μῦθον ἀνήγαγον τὸ ἔπος καὶ χρυσὸν ὑσθῆναί φασιν ἐν τῇ νήσῳ κατὰ τὴν Ἀθηνᾶς γένεσιν ἐκ τῆς κεφαλῆς τοῦ Διός, ὡς εἴρηκε Πίνδαρος. ἡ δὲ νῆσος κύκλον ἔχει σταδίων ἐνακοσίων εἴκοσιν.", "st": "14.2.10"}, {"sp": "N", "t": "ἔστι δὲ πρώτη μὲν Λίνδος ἀπὸ τῆς πόλεως πλέουσιν ἐν δεξιᾷ ἔχουσι τὴν νῆσον, πόλις ἐπὶ ὄρους ἱδρυμένη, πολὺ πρὸς μεσημβρίαν ἀνατείνουσα καὶ πρὸς Ἀλεξάνδρειαν μάλιστα· ἱερὸν δέ ἐστιν Ἀθηνᾶς Λινδίας αὐτόθι ἐπιφανὲς τῶν Δαναΐδων ἵδρυμα. πρότερον μὲν οὖν καθ’ αὑτοὺς ἐπολιτεύοντο οἱ Λίνδιοι, καθάπερ καὶ Καμειρεῖς καὶ Ἰαλύσιοι, μετὰ ταῦτα δὲ συνῆλθον ἅπαντες εἰς τὴν Ῥόδον. ἐντεῦθεν δ’ ἐστὶν εἷς τῶν ἑπτὰ σοφῶν Κλεόβουλος.", "st": "14.2.11"}, {"sp": "N", "t": "μετὰ δὲ Λίνδον Ἰξία χωρίον καὶ Μνασύριον· εἶθ’ ὁ Ἀτάβυρις, ὄρος τῶν ἐνταῦθα ὑψηλότατον, ἱερὸν Διὸς Ἀταβυρίου· εἶτα Κάμειρος· εἶτ’ Ἰαλυσὸς κώμη, καὶ ὑπὲρ αὐτὴν ἀκρόπολίς ἐστιν Ὀχύρωμα καλουμένη· εἶθ’ ἡ τῶν Ῥοδίων πόλις ἐν ὀγδοήκοντά που σταδίοις. μεταξὺ δ’ ἐστὶ τὸ Θοάντειον ἀκτή τις, ἧς μάλιστα πρόκεινται αἱ Σποράδες αἱ περὶ τὴν Χαλκίαν, ὧν ἐμνήσθημεν πρότερον.", "st": "14.2.12"}, {"sp": "N", "t": "ἄνδρες δ’ ἐγένοντο μνήμης ἄξιοι πολλοὶ στρατηλάται τε καὶ ἀθληταί, ὧν εἰσι καὶ οἱ Παναιτίου τοῦ φιλοσόφου πρόγονοι· τῶν δὲ πολιτικῶν καὶ τῶν περὶ λόγους καὶ φιλοσοφίαν ὅ τε Παναίτιος αὐτὸς καὶ Στρατοκλῆς καὶ Ἀνδρόνικος ὁ ἐκ τῶν περιπάτων καὶ Λεωνίδης ὁ στωικός, ἔτι δὲ πρότερον Πραξιφάνης καὶ Ἱερώνυμος καὶ Εὔδημος. Ποσειδώνιος δ’ ἐπολιτεύσατο μὲν ἐν Ῥόδῳ καὶ ἐσοφίστευσεν, ἦν δ’ Ἀπαμεὺς ἐκ τῆς Συρίας, καθάπερ καὶ Ἀπολλώνιος ὁ μαλακὸς καὶ Μόλων, ἦσαν δὲ Ἀλαβανδεῖς, Μενεκλέους μαθηταὶ τοῦ ῥήτορος. ἐπεδήμησε δὲ πρότερον Ἀπολλώνιος, ὀψὲ δ’ ἧκεν ὁ Μόλων, καὶ ἔφη πρὸς αὐτὸν ἐκεῖνος “ὀψὲ μολών” ἀντὶ τοῦ ἐλθών· καὶ Πείσανδρος δ’ ὁ τὴν Ἡράκλειαν γράψας ποιητὴς Ῥόδιος, καὶ Σιμμίας ὁ γραμματικὸς καὶ Ἀριστοκλῆς ὁ καθ’ ἡμᾶς· Διονύσιος δὲ ὁ Θρᾷξ καὶ Ἀπολλώνιος ὁ τοὺς Ἀργοναύτας ποιήσας Ἀλεξανδρεῖς μέν, ἐκαλοῦντο δὲ Ῥόδιοι. περὶ μὲν Ῥόδου ἀποχρώντως εἴρηται.", "st": "14.2.13"}, {"sp": "N", "t": "πάλιν δὲ τῆς Καρικῆς παραλίας τῆς μετὰ τὴν Ῥόδον ἀπὸ Ἐλαιοῦντος καὶ τῶν Λωρύμων καμπτήρ τις ἐπὶ τὰς ἄρκτους ἐστί, καὶ λοιπὸν ἐπ’ εὐθείας ὁ πλοῦς μέχρι τῆς Προποντίδος, ὡς ἂν μεσημβρινήν τινα ποιῶν γραμμὴν ὅσον πεντακισχιλίων σταδίων ἢ μικρὸν ἀπολείπουσαν. ἐνταῦθα δ’ ἐστὶν ἡ λοιπὴ τῆς Καρίας καὶ Ἴωνες καὶ Αἰολεῖς καὶ Τροία καὶ τὰ περὶ Κύζικον καὶ Βυζάντιον. μετὰ δ’ οὖν τὰ Λώρυμα τὸ Κυνὸς σῆμα ἔστι καὶ Σύμη νῆσος.", "st": "14.2.14"}, {"sp": "N", "t": "εἶτα Κνίδος δύο λιμένας ἔχουσα, ὧν τὸν ἕτερον κλειστὸν τριηρικὸν καὶ ναύσταθμον ναυσὶν εἴκοσι. πρόκειται δὲ νῆσος ἑπταστάδιός πως τὴν περίμετρον ὑψηλὴ θεατροειδὴς συναπτομένη χώμασι πρὸς τὴν ἤπειρον καὶ ποιοῦσα δίπολιν τρόπον τινὰ τὴν Κνίδον· πολὺ γὰρ αὐτῆς μέρος οἰκεῖ τὴν νῆσον σκεπάζουσαν ἀμφοτέρους τοὺς λιμένας. κατ’ αὐτὴν δ’ ἔστιν ἡ Νίσυρος πελαγία. ἄνδρες δ’ ἀξιόλογοι Κνίδιοι πρῶτον μὲν Εὔδοξος ὁ μαθηματικὸς τῶν Πλάτωνος ἑταίρων, εἶτ’ Ἀγαθαρχίδης ὁ ἐκ τῶν περιπάτων, ἀνὴρ συγγραφεύς, καθ’ ἡμᾶς δὲ Θεόπομπος, ὁ Καίσαρος τοῦ θεοῦ φίλος τῶν μέγα δυναμένων, καὶ υἱὸς Ἀρτεμίδωρος. ἐντεῦθεν δὲ καὶ Κτησίας ὁ ἰατρεύσας μὲν Ἀρταξέρξην, συγγράψας δὲ τὰ Ἀσσυρικὰ καὶ τὰ Περσικά. εἶτα μετὰ Κνίδον Κέραμος καὶ Βάργασα πολίχνια ὑπὲρ θαλάττης.", "st": "14.2.15"}, {"sp": "N", "t": "εἶθ’ Ἁλικαρνασός, τὸ βασίλειον τῶν τῆς Καρίας δυναστῶν, Ζεφυρία καλουμένη πρότερον. ἐνταῦθα δ’ ἐστὶν ὅ τε τοῦ Μαυσώλου τάφος, [ἓν] τῶν ἑπτὰ θεαμάτων, … ἔργον, ὅπερ Ἀρτεμισία τῷ ἀνδρὶ κατεσκεύασε, καὶ ἡ Σαλμακὶς κρήνη, διαβεβλημένη οὐκ οἶδ’ ὁπόθεν ὡς μαλακίζουσα τοὺς πιόντας ἀπ’ αὐτῆς. ἔοικε δ’ ἡ τρυφὴ τῶν ἀνθρώπων αἰτιᾶσθαι τοὺς ἀέρας ἢ τὰ ὕδατα· τρυφῆς δ’ αἴτια οὐ ταῦτα, ἀλλὰ πλοῦτος καὶ ἡ περὶ τὰς διαίτας ἀκολασία. ἔχει δ’ ἀκρόπολιν ἡ Ἁλικαρνασός· πρόκειται δ’ αὐτῆς ἡ Ἀρκόνησος. οἰκισταὶ δ’ αὐτῆς ἐγένοντο ἄλλοι τε καὶ Ἄνθης μετὰ Τροιζηνίων. ἄνδρες δὲ γεγόνασιν ἐξ αὐτῆς Ἡρόδοτός τε ὁ συγγραφεύς, ὃν ὕστερον Θούριον ἐκάλεσαν διὰ τὸ κοινωνῆσαι τῆς εἰς Θουρίους ἀποικίας, καὶ Ἡράκλειτος ὁ ποιητὴς ὁ Καλλιμάχου ἑταῖρος, καὶ καθ’ ἡμᾶς Διονύσιος ὁ συγγραφεύς.", "st": "14.2.16"}, {"sp": "N", "t": "ἔπταισε δὲ καὶ αὕτη ἡ πόλις βίᾳ ληφθεῖσα ὑπὸ Ἀλεξάνδρου. Ἑκατόμνω γὰρ τοῦ Καρῶν βασιλέως ἦσαν υἱοὶ τρεῖς, Μαύσωλος καὶ Ἱδριεὺς καὶ Πιξώδαρος, καὶ θυγατέρες δύο, ὧν τῇ πρεσβυτέρᾳ Ἀρτεμισίᾳ Μαύσωλος συνῴκησεν ὁ πρεσβύτατος τῶν ἀδελφῶν, ὁ δὲ δεύτερος Ἱδριεὺς Ἄδᾳ τῇ ἑτέρᾳ ἀδελφῇ· ἐβασίλευσε δὲ Μαύσωλος· τελευτῶν δ’ ἄτεκνος τὴν ἀρχὴν κατέλιπε τῇ γυναικί, ὑφ’ ἧς αὐτῷ κατεσκευάσθη ὁ λεχθεὶς τάφος· φθίσει δ’ ἀποθανούσης διὰ πένθος τοῦ ἀνδρὸς Ἱδριεὺς ἦρξε· καὶ τοῦτον ἡ γυνὴ Ἄδα διεδέξατο νόσῳ τελευτήσαντα· ἐξέβαλε δὲ ταύτην Πιξώδαρος, ὁ λοιπὸς τῶν Ἑκατόμνω παίδων· περσίσας δὲ μεταπέμπεται σατράπην ἐπὶ κοινωνίᾳ τῆς ἀρχῆς· ἀπελθόντος δ’ ἐκ τοῦ ζῆν καὶ τούτου κατεῖχεν ὁ σατράπης τὴν Ἁλικαρνασὸν ἔχων Ἄδαν γυναῖκα, ἥτις θυγάτηρ ἦν Πιξωδάρου ἐξ Ἀφνηίδος Καππαδοκίσσης γυναικός. ἐπελθόντος δὲ Ἀλεξάνδρου πολιορκίαν ὑπέμεινεν, ἡ δὲ τοῦ Ἑκατόμνω θυγάτηρ Ἄδα, ἣν ὁ Πιξώδαρος ἐξέβαλεν, ἱκετεύει τὸν Ἀλέξανδρον καὶ πείθει κατάγειν αὐτὴν εἰς τὴν ἀφαιρεθεῖσαν βασιλείαν ὑποσχομένη ἐπὶ τὰ ἀφεστῶτα συμπράξειν αὐτῷ· τοὺς γὰρ ἔχοντας οἰκείους ὑπάρχειν αὐτῇ· παρεδίδου δὲ καὶ τὰ Ἄλινδα, ἐν ᾧ διέτριβεν αὐτή· ἐπαινέσας δὲ καὶ βασίλισσαν ἀναδείξας, ἁλούσης τῆς πόλεως πλὴν τῆς ἄκρας (διττὴ δ’ ἦν), ἐκείνῃ πολιορκεῖν ἔδωκεν· ἑάλω δὲ ὀλίγῳ ὕστερον καὶ ἡ ἄκρα, πρὸς ὀργὴν ἤδη καὶ ἀπέχθειαν τῆς πολιορκίας γενομένης.", "st": "14.2.17"}, {"sp": "N", "t": "ἑξῆς δ’ ἐστὶν ἄκρα Τερμέριον Μυνδίων, καθ’ ἣν ἀντίκειται τῆς Κῴας ἄκρα Σκανδαρία διέχουσα τῆς ἠπείρου σταδίους τετταράκοντα· ἔστι δὲ καὶ χωρίον Τέρμερον ὑπὲρ τῆς ἄκρας.", "st": "14.2.18"}, {"sp": "N", "t": "ἡ δὲ τῶν Κῴων πόλις ἐκαλεῖτο τὸ παλαιὸν Ἀστυπάλαια, καὶ ᾠκεῖτο ἐν ἄλλῳ τόπῳ ὁμοίως ἐπὶ θαλάττῃ· ἔπειτα διὰ στάσιν μετῴκησαν εἰς τὴν νῦν πόλιν περὶ τὸ Σκανδάριον, καὶ μετωνόμασαν Κῶν ὁμωνύμως τῇ νήσῳ. ἡ μὲν οὖν πόλις οὐ μεγάλη, κάλλιστα δὲ πασῶν συνῳκισμένη καὶ ἰδέσθαι τοῖς καταπλέουσιν ἡδίστη. τῆς δὲ νήσου τὸ μέγεθος ὅσον πεντακοσίων σταδίων καὶ πεντήκοντα· εὔκαρπος δὲ πᾶσα, οἴνῳ δὲ καὶ ἀρίστη, καθάπερ Χίος καὶ Λέσβος· ἔχει δὲ πρὸς νότον μὲν ἄκραν τὸν Λακητῆρα (ἀφ’ οὗ ἑξήκοντα εἰς Νίσυρον), πρὸς δὲ τῷ Λακητῆρι χωρίον Ἁλίσαρνα, ἀπὸ δύσεως δὲ τὸ Δρέκανον καὶ κώμην καλουμένην Στομαλίμνην· τοῦτο μὲν οὖν ὅσον διακοσίους τῆς πόλεως διέχει σταδίους· ὁ δὲ Λακητὴρ προσλαμβάνει πέντε καὶ τριάκοντα τῷ μήκει τοῦ πλοῦ. ἐν δὲ τῷ προαστείῳ τὸ Ἀσκληπιεῖον ἔστι, σφόδρα ἔνδοξον καὶ πολλῶν ἀναθημάτων μεστόν, ἐν οἷς ἐστι καὶ ὁ Ἀπελλοῦ Ἀντίγονος. ἦν δὲ καὶ ἡ ἀναδυομένη Ἀφροδίτη, ἣ νῦν ἀνάκειται τῷ θεῷ Καίσαρι ἐν Ῥώμῃ, τοῦ Σεβαστοῦ ἀναθέντος τῷ πατρὶ τὴν ἀρχηγέτιν τοῦ γένους αὐτοῦ· φασὶ δὲ τοῖς Κῴοις ἀντὶ τῆς γραφῆς ἑκατὸν ταλάντων ἄφεσιν γενέσθαι τοῦ προσταχθέντος φόρου. φασὶ δ’ Ἱπποκράτην μάλιστα ἐκ τῶν ἐνταῦθα ἀνακειμένων θεραπειῶν γυμνάσασθαι τὰ περὶ τὰς διαίτας· οὗτός τε δή ἐστι τῶν ἐνδόξων Κῷος ἀνὴρ καὶ Σῖμος ὁ ἰατρός, Φιλητᾶς τε ποιητὴς ἅμα καὶ κριτικός, καὶ καθ’ ἡμᾶς Νικίας ὁ καὶ τυραννήσας Κῴων, καὶ Ἀρίστων ὁ ἀκροασάμενος τοῦ περιπατητικοῦ καὶ κληρονομήσας ἐκεῖνον· ἦν δὲ καὶ Θεόμνηστος ὁ ψάλτης ἐν ὀνόματι, ὃς καὶ ἀντεπολιτεύσατο τῷ Νικίᾳ.", "st": "14.2.19"}, {"sp": "N", "t": "ἐν δὲ τῇ παραλίᾳ τῆς ἠπείρου κατὰ τὴν Μυνδίαν Ἀστυπάλαιά ἐστιν ἄκρα καὶ Ζεφύριον· εἶτ’ εὐθὺς ἡ Μύνδος λιμένα ἔχουσα, καὶ μετὰ ταύτην Βαργύλια, καὶ αὕτη πόλις· ἐν δὲ τῷ μεταξὺ Καρύανδα λιμὴν καὶ νῆσος ὁμώνυμος, ἣν ᾤκουν Καρυανδεῖς. ἐντεῦθεν δ’ ἦν καὶ Σκύλαξ ὁ παλαιὸς συγγραφεύς. πλησίον δ’ ἐστὶ τῶν Βαργυλίων τὸ τῆς Ἀρτέμιδος ἱερὸν τῆς Κινδυάδος, ὃ πεπιστεύκασι περιύεσθαι· ἦν δέ ποτε καὶ χωρίον Κινδύη. ἐκ δὲ τῶν Βαργυλίων ἀνὴρ ἐλλόγιμος ἦν ὁ Ἐπικούρειος Πρώταρχος, ὁ Δημητρίου καθηγησάμενος τοῦ Λάκωνος προσαγορευθέντος.", "st": "14.2.20"}, {"sp": "N", "t": "εἶτ’ Ἰασὸς ἐπὶ νήσῳ κεῖται προσκειμένη τῇ ἠπείρῳ· ἔχει δὲ λιμένα, καὶ τὸ πλεῖστον τοῦ βίου τοῖς ἐνθάδε ἐκ θαλάττης· εὐοψεῖ γὰρ χώραν τ’ ἔχει παράλυπρον. καὶ δὴ καὶ διηγήματα τοιαῦτα πλάττουσιν εἰς αὐτήν· κιθαρῳδοῦ γὰρ ἐπιδεικνυμένου τέως μὲν ἀκροᾶσθαι πάντας· ὡς δ’ ὁ κώδων ὁ κατὰ τὴν ὀψοπωλίαν ἐψόφησε, καταλιπόντας ἀπελθεῖν ἐπὶ τὸ ὄψον πλὴν ἑνὸς δυσκώφου· τὸν οὖν κιθαρῳδὸν προσιόντα εἰπεῖν ὅτι “ὦ ἄνθρωπε πολλήν σοι χάριν οἶδα τῆς πρός με τιμῆς καὶ φιλομουσίας· οἱ μὲν γὰρ ἄλλοι ἅμα τῷ κώδωνος ἀκοῦσαι ἀπιόντες οἴχονται.” ὁ δέ “τί λέγεις;” ἔφη “ἤδη γὰρ ὁ κώδων ἐψόφηκεν;” εἰπόντος δέ “εὖ σοι εἴη” ἔφη καὶ ἀναστὰς ἀπῆλθε καὶ αὐτός. ἐντεῦθεν δ’ ἦν ὁ διαλεκτικὸς Διόδωρος ὁ Κρόνος προσαγορευθείς, κατ’ ἀρχὰς μὲν ψευδῶς· Ἀπολλώνιος γὰρ ἐκαλεῖτο ὁ Κρόνος, ὁ ἐπιστατήσας ἐκείνου· μετήνεγκαν δ’ ἐπ’ αὐτὸν διὰ τὴν ἀδοξίαν τοῦ κατ’ ἀλήθειαν Κρόνου.", "st": "14.2.21"}, {"sp": "N", "t": "μετὰ δ’ Ἰασὸν τὸ τῶν Μιλησίων Ποσείδιον ἔστιν. ἐν δὲ τῇ μεσογαίᾳ τρεῖς εἰσι πόλεις ἀξιόλογοι, Μύλασα Στρατονίκεια Ἀλάβανδα· αἱ δὲ ἄλλαι περιπόλιοι τούτων ἢ τῶν παραλίων, ὧν εἰσιν Ἀμυζὼν Ἡράκλεια Εὔρωμος Χαλκήτορες· τούτων μὲν οὖν ἐλάττων λόγος.", "st": "14.2.22"}, {"sp": "N", "t": "τὰ δὲ Μύλασα ἵδρυται ἐν πεδίῳ σφόδρα εὐδαίμονι· ὑπέρκειται δὲ κατὰ κορυφὴν ὄρος αὐτοῦ, λατόμιον λευκοῦ λίθου κάλλιστον ἔχον· τοῦτο μὲν οὖν ὄφελός ἐστιν οὐ μικρόν, τὴν λιθείαν πρὸς τὰς οἰκοδομίας ἄφθονον καὶ ἐγγύθεν ἔχον καὶ μάλιστα πρὸς τὰς τῶν ἱερῶν καὶ τῶν ἄλλων δημοσίων ἔργων κατασκευάς· τοιγάρτοι στοαῖς τε καὶ ναοῖς εἴ τις ἄλλη κεκόσμηται παγκάλως. θαυμάζειν δ’ ἔστι τῶν ὑποβαλόντων οὕτως ἀλόγως τὸ κτίσμα ὀρθίῳ καὶ ὑπερδεξίῳ κρημνῷ· καὶ δὴ τῶν ἡγεμόνων τις εἰπεῖν λέγεται θαυμάσας τὸ πρᾶγμα “ταύτην γάρ” ἔφη “τὴν πόλιν ὁ κτίσας, εἰ μὴ ἐφοβεῖτο, ἆρ’ οὐδ’ ᾐσχύνετο;” ἔχουσι δ’ οἱ Μυλασεῖς ἱερὰ δύο τοῦ Διός, τοῦ τε Ὀσογῶα καλουμένου καὶ Λαβραυνδηνοῦ, τὸ μὲν ἐν τῇ πόλει, τὰ δὲ Λάβραυνδα κώμη ἐστὶν ἐν τῷ ὄρει κατὰ τὴν ὑπέρθεσιν τὴν ἐξ Ἀλαβάνδων εἰς τὰ Μύλασα ἄπωθεν τῆς πόλεως· ἐνταῦθα νεώς ἐστιν ἀρχαῖος καὶ ξόανον Διὸς Στρατίου· τιμᾶται δὲ ὑπὸ τῶν κύκλῳ καὶ ὑπὸ τῶν Μυλασέων, ὁδός τε ἔστρωται σχεδόν τι καὶ ἑξήκοντα σταδίων μέχρι τῆς πόλεως ἱερὰ καλουμένη, δι’ ἧς πομποστολεῖται τὰ ἱερά· ἱερῶνται δ’ οἱ ἐπιφανέστατοι τῶν πολιτῶν ἀεὶ διὰ βίου. ταῦτα μὲν οὖν ἴδια τῆς πόλεως. τρίτον δ’ ἐστὶν ἱερὸν τοῦ Καρίου Διὸς κοινὸν ἁπάντων Καρῶν, οὗ μέτεστι καὶ Λυδοῖς καὶ Μυσοῖς ὡς ἀδελφοῖς. ἱστορεῖται δὲ κώμη ὑπάρξαι τὸ παλαιόν, πατρὶς δὲ καὶ βασίλειον τῶν Καρῶν τῶν περὶ τὸν Ἑκατόμνω· πλησιάζει δὲ μάλιστα τῇ κατὰ Φύσκον θαλάττῃ ἡ πόλις, καὶ τοῦτ’ ἐστὶν αὐτοῖς ἐπίνειον.", "st": "14.2.23"}, {"sp": "N", "t": "ἀξιολόγους δ’ ἔσχεν ἄνδρας καθ’ ἡμᾶς τὰ Μύλασα, ῥήτοράς τε ἅμα καὶ δημαγωγοὺς τῆς πόλεως, Εὐθύδημόν τε καὶ Ὑβρέαν. ὁ μὲν οὖν Εὐθύδημος ἐκ προγόνων παραλαβὼν οὐσίαν τε μεγάλην καὶ δόξαν, προσθεὶς καὶ τὴν δεινότητα, οὐκ ἐν τῇ πατρίδι μόνον μέγας ἦν ἀλλὰ καὶ ἐν τῇ Ἀσίᾳ τῆς πρώτης ἠξιοῦτο τιμῆς· Ὑβρέᾳ δ’ ὁ πατήρ, ὡς αὐτὸς διηγεῖτο ἐν τῇ σχολῇ καὶ παρὰ τῶν πολιτῶν ὡμολόγητο, ἡμίονον κατέλιπε ξυλοφοροῦντα καὶ ἡμιονηγόν· διοικούμενος δ’ ὑπὸ τούτων ὀλίγον χρόνον, Διοτρέφους τοῦ Ἀντιοχέως ἀκροασάμενος ἐπανῆλθε καὶ τῷ ἀγορανομίῳ παρέδωκεν αὑτόν· ἐνταῦθα δὲ κυλινδηθεὶς καὶ χρηματισάμενος μικρὰ ὥρμησεν ἐπὶ τὸ πολιτεύεσθαι καὶ τοῖς ἀγοραίοις συνακολουθεῖν, ταχὺ δὲ αὔξησιν ἔσχε καὶ ἐθαυμάσθη ἔτι μὲν καὶ Εὐθυδήμου ζῶντος, ἀλλὰ τελευτήσαντος μάλιστα, κύριος γενόμενος τῆς πόλεως. ζῶν δ’ ἐπεκράτει πολὺ ἐκεῖνος, δυνατὸς ὢν ἅμα καὶ χρήσιμος τῇ πόλει, ὥστ’ εἰ καί τι τυραννικὸν προσῆν, τοῦτ’ ἀπελύετο τῷ παρακολουθεῖν τὸ χρήσιμον. ἐπαινοῦσι γοῦν τοῦτο τοῦ Ὑβρέου ὅπερ δημηγορῶν ἐπὶ τελευτῆς εἶπεν “Εὐθύδημε, κακὸν εἶ τῆς πόλεως ἀναγκαῖον· οὔτε γὰρ μετὰ σοῦ δυνάμεθα ζῆν οὔτ’ ἄνευ σοῦ.” αὐξηθεὶς οὖν ἐπὶ πολὺ καὶ δόξας καὶ πολίτης ἀγαθὸς εἶναι καὶ ῥήτωρ ἔπταισεν ἐν τῇ πρὸς Λαβιηνὸν ἀντιπολιτείᾳ. οἱ μὲν γὰρ ἄλλοι μεθ’ ὅπλων ἐπιόντι καὶ Παρθικῆς συμμαχίας, ἤδη τῶν Παρθυαίων τὴν Ἀσίαν ἐχόντων, εἶξαν ἅτε ἄοπλοι καὶ εἰρηνικοί· Ζήνων δ’ ὁ Λαοδικεὺς καὶ Ὑβρέας οὐκ εἶξαν, ἀμφότεροι ῥήτορες, ἀλλὰ ἀπέστησαν τὰς ἑαυτῶν πόλεις· ὁ δ’ Ὑβρέας καὶ προσπαρώξυνε φωνῇ τινι μειράκιον εὐερέθιστον καὶ ἀνοίας πλῆρες. ἐκείνου γὰρ ἀνειπόντος ἑαυτὸν Παρθικὸν αὐτοκράτορα “οὐκοῦν” ἔφη “κἀγὼ λέγω ἐμαυτὸν Καρικὸν αὐτοκράτορα.” ἐκ τούτου δὲ ἐπὶ τὴν πόλιν ὥρμησε τάγματα ἔχων ἤδη συντεταγμένα Ῥωμαίων τῶν ἐν τῇ Ἀσίᾳ· αὐτὸν μὲν οὖν οὐ κατέλαβε παραχωρήσαντα εἰς Ῥόδον, τὴν δ’ οἰκίαν αὐτοῦ διελυμήνατο πολυτελεῖς ἔχουσαν κατασκευὰς καὶ διήρπασεν· ὡς δ’ αὕτως καὶ τὴν πόλιν ὅλην ἐκάκωσεν. ἐκλιπόντος δ’ ἐκείνου τὴν Ἀσίαν ἐπανῆλθε καὶ ἀνέλαβεν ἑαυτόν τε καὶ τὴν πόλιν. περὶ μὲν οὖν Μυλάσων ταῦτα.", "st": "14.2.24"}, {"sp": "N", "t": "Στρατονίκεια δ’ ἐστὶ κατοικία Μακεδόνων· ἐκοσμήθη δὲ καὶ αὕτη κατασκευαῖς πολυτελέσιν ὑπὸ τῶν βασιλέων. ἔστι δ’ ἐν τῇ χώρᾳ τῶν Στρατονικέων δύο ἱερά, ἐν μὲν Λαγίνοις τὸ τῆς Ἑκάτης ἐπιφανέστατον πανηγύρεις μεγάλας συνάγον κατ’ ἐνιαυτόν, ἐγγὺς δὲ τῆς πόλεως τὸ τοῦ Χρυσαορέως Διὸς κοινὸν ἁπάντων Καρῶν, εἰς ὃ συνίασι θύσοντές τε καὶ βουλευσόμενοι περὶ τῶν κοινῶν· καλεῖται δὲ τὸ σύστημα αὐτῶν Χρυσαορέων, συνεστηκὸς ἐκ κωμῶν· οἱ δὲ πλείστας παρεχόμενοι κώμας προέχουσι τῇ ψήφῳ, καθάπερ Κεραμιῆται· καὶ Στρατονικεῖς δὲ τοῦ συστήματος μετέχουσιν οὐκ ὄντες τοῦ Καρικοῦ γένους, ἀλλ’ ὅτι κώμας ἔχουσι τοῦ Χρυσαορικοῦ συστήματος. κἀνταῦθα δ’ ἀνὴρ ἀξιόλογος γεγένηται ῥήτωρ Μένιππος κατὰ τοὺς πατέρας ἡμῶν Κοτοκᾶς ἐπικαλούμενος, ὃν μάλιστα ἐπαινεῖ τῶν κατὰ τὴν Ἀσίαν ῥητόρων ὧν ἠκροάσατο Κικέρων, ὥς φησιν ἔν τινι γραφῇ αὐτὸς συγκρίνων Ξενοκλεῖ καὶ τοῖς κατ’ ἐκεῖνον ἀκμάζουσιν. ἔστι δὲ καὶ ἄλλη Στρατονίκεια ἡ πρὸς τῷ Ταύρῳ καλουμένη, πολίχνιον προσκείμενον τῷ ὄρει.", "st": "14.2.25"}, {"sp": "N", "t": "Ἀλάβανδα δὲ καὶ αὐτὴ μὲν ὑπόκειται λόφοις δυσὶ συγκειμένοις οὕτως ὥστ’ ὄψιν παρέχεσθαι κανθηλίου κατεστρωμένου. καὶ δὴ καὶ ὁ μαλακὸς Ἀπολλώνιος σκώπτων τὴν πόλιν εἴς τε ταῦτα καὶ εἰς τὸ τῶν σκορπίων πλῆθος, ἔφη αὐτὴν εἶναι σκορπίων κανθήλιον κατεστρωμένον· μεστὴ δ’ ἐστὶ καὶ αὕτη καὶ ἡ τῶν Μυλασέων πόλις τῶν θηρίων τούτων καὶ ἡ μεταξὺ πᾶσα ὀρεινή. τρυφητῶν δ’ ἐστὶν ἀνθρώπων καὶ καπυριστῶν ἔχουσα ψαλτρίας πολλάς. ἄνδρες δ’ ἐγένοντο λόγου ἄξιοι δύο ῥήτορες ἀδελφοὶ Ἀλαβανδεῖς, Μενεκλῆς τε οὗ ἐμνήσθημεν μικρὸν ἐπάνω καὶ Ἱεροκλῆς, καὶ οἱ μετοικήσαντες εἰς τὴν Ῥόδον ὅ τε Ἀπολλώνιος καὶ ὁ Μόλων.", "st": "14.2.26"}, {"sp": "N", "t": "πολλῶν δὲ λόγων εἰρημένων περὶ Καρῶν ὁ μάλισθ’ ὁμολογούμενός ἐστιν οὗτος ὅτι οἱ Κᾶρες ὑπὸ Μίνω ἐτάττοντο, τότε Λέλεγες καλούμενοι, καὶ τὰς νήσους ᾤκουν· εἶτ’ ἠπειρῶται γενόμενοι πολλὴν τῆς παραλίας καὶ τῆς μεσογαίας κατέσχον τοὺς προκατέχοντας ἀφελόμενοι· καὶ οὗτοι δ’ ἦσαν οἱ πλείους Λέλεγες καὶ Πελασγοί· πάλιν δὲ τούτους ἀφείλοντο μέρος οἱ Ἕλληνες, Ἴωνές τε καὶ Δωριεῖς. τοῦ δὲ περὶ τὰ στρατιωτικὰ ζήλου τά τε ὄχανα ποιοῦνται τεκμήρια καὶ τὰ ἐπίσημα καὶ τοὺς λόφους· ἅπαντα γὰρ λέγεται Καρικά· Ἀνακρέων μέν γε φησίν<br>διὰ δηὖτε καρικοεργέος<br>ὀχάνου χεῖρα τιθέμεναι<br>ὁ δ’ Ἀλκαῖος<br>λόφον τε σείων Καρικόν.", "st": "14.2.27"}, {"sp": "N", "t": "τοῦ ποιητοῦ δ’ εἰρηκότος οὑτωσί<br>μάσθλης αὖ Καρῶν ἡγήσατο βαρβαροφώνων,<br>οὐκ ἔχει λόγον πῶς τοσαῦτα εἰδὼς ἔθνη βάρβαρα μόνους εἴρηκε βαρβαροφώνους τοὺς Κᾶρας, βαρβάρους δ’ οὐδένας· οὔτ’ οὖν Θουκυδίδης ὀρθῶς· οὐδὲ γὰρ λέγεσθαί φησι βαρβάρους διὰ τὸ μηδὲ Ἕλληνάς πω ἀντίπαλον εἰς ἓν ὄνομα ἀποκεκρίσθαι· τό τε γὰρ μηδὲ Ἕλληνάς πω ψεῦδος αὐτὸς ὁ ποιητὴς ἀπελέγχει<br>ἀνδρός, τοῦ κλέος εὐρὺ καθ’ Ἑλλάδα καὶ μέσον Ἄργος.<br>καὶ πάλιν<br>εἴτ’ ἐθέλεις τραφθῆναι ἀν’ Ἑλλάδα καὶ μέσον Ἄργος.<br>μὴ λεγομένων τε βαρβάρων πῶς ἔμελλεν εὖ λεχθήσεσθαι τὸ βαρβαροφώνων; οὔτε δὴ οὗτος εὖ οὔτ’ Ἀπολλόδωρος ὁ γραμματικός, ὅτι τῷ κοινῷ ὀνόματι ἰδίως καὶ λοιδόρως ἐχρῶντο οἱ Ἕλληνες κατὰ τῶν Καρῶν, καὶ μάλιστα οἱ Ἴωνες μισοῦντες αὐτοὺς διὰ τὴν ἔχθραν καὶ τὰς συνεχεῖς στρατείας· ἐχρῆν γὰρ οὕτως βαρβάρους ὀνομάζειν. ἡμεῖς δὲ ζητοῦμεν διὰ τί βαρβαροφώνους καλεῖ, βαρβάρους δ’ οὐδ’ ἅπαξ. “ὅτι” φησί “τὸ πληθυντικὸν εἰς τὸ μέτρον οὐκ ἐμπίπτει, διὰ τοῦτ’ οὐκ εἴρηκε βαρβάρους.” ἀλλ’ αὕτη μὲν ἡ πτῶσις οὐκ ἐμπίπτει, ἡ δ’ ὀρθὴ οὐ διαφέρει τῆς Δάρδανοι<br>Τρῶες καὶ Λύκιοι καὶ Δάρδανοι.<br>τοιοῦτον δὲ καὶ τό<br>οἷοι Τρώιοι ἵπποι.<br>οὐδέ γε ὅτι τραχυτάτη ἡ γλῶττα τῶν Καρῶν· οὐ γάρ ἐστιν ἀλλὰ καὶ πλεῖστα Ἑλληνικὰ ὀνόματα ἔχει καταμεμιγμένα, ὥς φησι Φίλιππος ὁ τὰ Καρικὰ γράψας. οἶμαι δὲ τὸ βάρβαρον κατ’ ἀρχὰς ἐκπεφωνῆσθαι οὕτως κατ’ ὀνοματοποιίαν ἐπὶ τῶν δυσεκφόρως καὶ σκληρῶς καὶ τραχέως λαλούντων, ὡς τὸ βατταρίζειν καὶ τραυλίζειν καὶ ψελλίζειν. εὐφυέστατοι γάρ ἐσμεν τὰς φωνὰς ταῖς ὁμοίαις φωναῖς κατονομάζειν διὰ τὸ ὁμογενές· ᾗ δὴ καὶ πλεονάζουσιν ἐνταῦθα αἱ ὀνοματοποιίαι, οἷον τὸ κελαρύζειν καὶ κλαγγὴ δὲ καὶ ψόφος καὶ βοὴ καὶ κρότος, ὧν τὰ πλεῖστα ἤδη καὶ κυρίως ἐκφέρεται· πάντων δὴ τῶν παχυστομούντων οὕτως βαρβάρων λεγομένων, ἐφάνη τὰ τῶν ἀλλοεθνῶν στόματα τοιαῦτα, λέγω δὲ τὰ τῶν μὴ Ἑλλήνων. ἐκείνους οὖν ἰδίως ἐκάλεσαν βαρβάρους, ἐν ἀρχαῖς μὲν κατὰ τὸ λοίδορον, ὡς ἂν παχυστόμους ἢ τραχυστόμους, εἶτα κατεχρησάμεθα ὡς ἐθνικῷ κοινῷ ὀνόματι ἀντιδιαιροῦντες πρὸς τοὺς Ἕλληνας. καὶ γὰρ δὴ τῇ πολλῇ συνηθείᾳ καὶ ἐπιπλοκῇ τῶν βαρβάρων οὐκέτι ἐφαίνετο κατὰ παχυστομίαν καὶ ἀφυΐαν τινὰ τῶν φωνητηρίων ὀργάνων τοῦτο συμβαῖνον, ἀλλὰ κατὰ τὰς τῶν διαλέκτων ἰδιότητας. ἄλλη δέ τις ἐν τῇ ἡμετέρᾳ διαλέκτῳ ἀνεφάνη κακοστομία καὶ οἷον βαρβαροστομία, εἴ τις ἑλληνίζων μὴ κατορθοίη, ἀλλ’ οὕτω λέγοι τὰ ὀνόματα ὡς οἱ βάρβαροι οἱ εἰσαγόμενοι εἰς τὸν ἑλληνισμὸν οὐκ ἰσχύοντες ἀρτιστομεῖν, ὡς οὐδ’ ἡμεῖς ἐν ταῖς ἐκείνων διαλέκτοις. τοῦτο δὲ μάλιστα συνέβη τοῖς Καρσί· τῶν γὰρ ἄλλων οὔτ’ ἐπιπλεκομένων πω σφόδρα τοῖς Ἕλλησιν, οὔτ’ ἐπιχειρούντων ἑλληνικῶς ζῆν ἢ μανθάνειν τὴν ἡμετέραν διάλεκτον, πλὴν εἴ τινες σπάνιοι καὶ κατὰ τύχην ἐπεμίχθησαν καὶ κατ’ ἄνδρα ὀλίγοις τῶν Ἑλλήνων τισίν· οὗτοι δὲ καθ’ ὅλην ἐπλανήθησαν τὴν Ἑλλάδα μισθοῦ στρατεύοντες. ἤδη οὖν τὸ βαρβαρόφωνον ἐπ’ ἐκείνων πυκνὸν ἦν ἀπὸ τῆς εἰς τὴν Ἑλλάδα αὐτῶν στρατείας· καὶ μετὰ ταῦτα ἐπεπόλασε πολὺ μᾶλλον, ἀφ’ οὗ τάς τε νήσους μετὰ τῶν Ἑλλήνων ᾤκησαν, κἀκεῖθεν εἰς τὴν Ἀσίαν ἐκπεσόντες οὐδ’ ἐνταῦθα χωρὶς Ἑλλήνων οἰκεῖν ἠδύναντο, ἐπιδιαβάντων τῶν Ἰώνων καὶ τῶν Δωριέων. ἀπὸ δὲ τῆς αὐτῆς αἰτίας καὶ τὸ βαρβαρίζειν λέγεται· καὶ γὰρ τοῦτο ἐπὶ τῶν κακῶς ἑλληνιζόντων εἰώθαμεν λέγειν, οὐκ ἐπὶ τῶν καριστὶ λαλούντων. οὕτως οὖν καὶ τὸ βαρβαροφωνεῖν καὶ τοὺς βαρβαροφώνους δεκτέον τοὺς κακῶς ἑλληνίζοντας· ἀπὸ δὲ τοῦ καρίζειν καὶ τὸ βαρβαρίζειν μετήνεγκαν εἰς τὰς περὶ ἑλληνισμοῦ τέχνας καὶ τὸ σολοικίζειν, εἴτ’ ἀπὸ Σόλων εἴτ’ ἄλλως τοῦ ὀνόματος τούτου πεπλασμένου.", "st": "14.2.28"}, {"sp": "N", "t": "φησὶ δὲ Ἀρτεμίδωρος ἀπὸ Φύσκου τῆς Ῥοδίων περαίας ἰοῦσιν εἰς Ἔφεσον μέχρι μὲν Λαγίνων ὀκτακοσίους εἶναι καὶ πεντήκοντα σταδίους, ἐντεῦθεν δ’ εἰς Ἀλάβανδα πεντήκοντα ἄλλους καὶ διακοσίους, εἰς δὲ Τράλλεις ἑκατὸν ἑξήκοντα· ἀλλ’ ἡ εἰς Τράλλεις ἐστὶ διαβάντι τὸν Μαίανδρον κατὰ μέσην που τὴν ὁδὸν ὅπου τῆς Καρίας οἱ ὅροι· γίνονται δ’ οἱ πάντες ἀπὸ Φύσκου ἐπὶ τὸν Μαίανδρον κατὰ τὴν εἰς Ἔφεσον ὁδὸν χίλιοι ἑκατὸν ὀγδοήκοντα. πάλιν ἀπὸ τοῦ Μαιάνδρου τῆς Ἰωνίας ἐφεξῆς μῆκος ἐπιόντι κατὰ τὴν αὐτὴν ὁδὸν ἀπὸ μὲν τοῦ ποταμοῦ εἰς Τράλλεις ὀγδοήκοντα, εἶτ’ εἰς Μαγνησίαν ἑκατὸν τετταράκοντα, εἰς Ἔφεσον δ’ ἑκατὸν εἴκοσιν, εἰς δὲ Σμύρναν τριακόσιοι εἴκοσιν, εἰς δὲ Φώκαιαν καὶ τοὺς ὅρους τῆς Ἰωνίας ἐλάττους τῶν διακοσίων, ὥστε τὸ ἐπ’ εὐθείας μῆκος τῆς Ἰωνίας εἴη ἂν κατ’ αὐτὸν μικρῷ πλέον τῶν ὀκτακοσίων. ἐπεὶ δὲ κοινή τις ὁδὸς τέτριπται ἅπασι τοῖς ἐπὶ τὰς ἀνατολὰς ὁδοιποροῦσιν ἐξ Ἐφέσου, καὶ ταύτην ἔπεισιν. ἐπὶ μὲν τὰ Κάρουρα τῆς Καρίας ὅριον πρὸς τὴν Φρυγίαν διὰ Μαγνησίας καὶ Τραλλέων Νύσης Ἀντιοχείας ὁδὸς ἑπτακοσίων καὶ τετταράκοντα σταδίων· ἐντεῦθεν δὲ ἡ Φρυγία διὰ Λαοδικείας καὶ Ἀπαμείας καὶ Μητροπόλεως καὶ Χελιδονίων· ἐπὶ μὲν οὖν τὴν ἀρχὴν τῆς Παρωρείου, τοὺς Ὅλμους, στάδιοι περὶ ἐνακοσίους καὶ εἴκοσιν ἐκ τῶν Καρούρων· ἐπὶ δὲ τὸ πρὸς τῇ Λυκαονίᾳ πέρας τῆς Παρωρείου τὸ Τυριαῖον διὰ Φιλομηλίου μικρῷ πλείους τῶν πεντακοσίων, εἶθ’ ἡ Λυκαονία μέχρι Κοροπασσοῦ διὰ Λαοδικείας τῆς κατακεκαυμένης ὀκτακόσιοι τετταράκοντα, ἐκ δὲ Κοροπασσοῦ τῆς Λυκαονίας εἰς Γαρσάουρα, πολίχνιον τῆς Καππαδοκίας ἐπὶ τῶν ὅρων αὐτῆς ἱδρυμένον, ἑκατὸν εἴκοσιν· ἐντεῦθεν δ’ εἰς Μάζακα τὴν μητρόπολιν τῶν Καππαδόκων διὰ Σοάνδου καὶ Σαδακόρων ἑξακόσιοι ὀγδοήκοντα· ἐντεῦθεν δ’ ἐπὶ τὸν Εὐφράτην μέχρι Τομίσων χωρίου τῆς Σωφηνῆς διὰ Ἡρφῶν πολίχνης χίλιοι τετρακόσιοι τετταράκοντα. τὰ δ’ ἐπ’ εὐθείας τούτοις μέχρι τῆς Ἰνδικῆς τὰ αὐτὰ κεῖται καὶ παρὰ τῷ Ἀρτεμιδώρῳ ἅπερ καὶ παρὰ τῷ Ἐρατοσθένει. λέγει δὲ καὶ Πολύβιος περὶ τῶν ἐκεῖ μάλιστα δεῖν πιστεύειν ἐκείνῳ. ἄρχεται δὲ ἀπὸ Σαμοσάτων τῆς Κομμαγηνῆς, ἣ πρὸς τῇ διαβάσει καὶ τῷ Ζεύγματι κεῖται· εἰς δὲ Σαμόσατα ἀπὸ τῶν ὅρων τῆς Καππαδοκίας τῶν περὶ Τόμισα ὑπερθέντι τὸν Ταῦρον σταδίους εἴρηκε τετρακοσίους καὶ πεντήκοντα.", "st": "14.2.29"}, {"sp": "N", "t": "μετὰ δὲ τὴν Ῥοδίων περαίαν ἧς ὅριον τὰ Δαίδαλα ἐφεξῆς πλέουσι πρὸς ἀνίσχοντα ἥλιον ἡ Λυκία κεῖται μέχρι Παμφυλίας, εἶθ’ ἡ Παμφυλία μέχρι Κιλίκων τῶν τραχέων, εἶθ’ ἡ τούτων μέχρι τῶν ἄλλων Κιλίκων τῶν περὶ τὸν Ἰσσικὸν κόλπον· ταῦτα δ’ ἐστὶ μέρη μὲν τῆς χερρονήσου, ἧς τὸν ἰσθμὸν ἔφαμεν τὴν ἀπὸ Ἰσσοῦ ὁδὸν μέχρι Ἀμισοῦ ἢ Σινώπης, ὥς τινες, ἐκτὸς δὲ τοῦ Ταύρου ἐν στενῇ παραλίᾳ τῇ ἀπὸ Λυκίας μέχρι τῶν περὶ Σόλους τόπων, τὴν νῦν Πομπηιόπολιν· ἔπειτα ἤδη εἰς πεδία ἀναπέπταται ἡ κατὰ τὸν Ἰσσικὸν κόλπον παραλία ἀπὸ Σόλων καὶ Ταρσοῦ ἀρξαμένη. ταύτην οὖν ἐπελθοῦσιν ὁ πᾶς περὶ τῆς χερρονήσου λόγος ἔσται περιωδευμένος· εἶτα μεταβησόμεθα ἐπὶ τὰ ἄλλα μέρη τῆς Ἀσίας τὰ ἐκτὸς τοῦ Ταύρου. τελευταῖα δ’ ἐκθήσομεν τὰ περὶ τὴν Λιβύην.", "st": "14.3.1"}, {"sp": "N", "t": "μετὰ τοίνυν Δαίδαλα τὰ τῶν Ῥοδίων ὄρος ἐστὶ τῆς Λυκίας ὁμώνυμον αὐτοῖς Δαίδαλα, ἀφ’ οὗ λαμβάνει τὴν ἀρχὴν ὁ παράπλους ἅπας ὁ Λυκιακός, σταδίων μὲν ὢν χιλίων ἑπτακοσίων εἴκοσι, τραχὺς δὲ καὶ χαλεπός, ἀλλ’ εὐλίμενος σφόδρα καὶ ὑπὸ ἀνθρώπων συνοικούμενος σωφρόνων· ἐπεὶ ἥ γε τῆς χώρας φύσις παραπλησία καὶ τοῖς Παμφύλοις ἐστὶ καὶ τοῖς Τραχειώταις Κίλιξιν· ἀλλ’ ἐκεῖνοι μὲν ὁρμητηρίοις ἐχρήσαντο τοῖς τόποις πρὸς τὰ λῃστήρια, αὐτοὶ πειρατεύοντες ἢ τοῖς πειραταῖς λαφυροπώλια καὶ ναύσταθμα παρέχοντες· ἐν Σίδῃ γοῦν πόλει τῆς Παμφυλίας τὰ ναυπήγια συνίστατο τοῖς Κίλιξιν, ὑπὸ κήρυκά τε ἐπώλουν ἐκεῖ τοὺς ἁλόντας ἐλευθέρους ὁμολογοῦντες· Λύκιοι δ’ οὕτω πολιτικῶς καὶ σωφρόνως ζῶντες διετέλεσαν ὥστ’ ἐκείνων διὰ τὰς εὐτυχίας θαλαττοκρατησάντων μέχρι τῆς Ἰταλίας ὅμως ὑπ’ οὐδενὸς ἐξήρθησαν αἰσχροῦ κέρδους, ἀλλ’ ἔμειναν ἐν τῇ πατρίῳ διοικήσει τοῦ Λυκιακοῦ συστήματος.", "st": "14.3.2"}, {"sp": "N", "t": "εἰσὶ δὲ τρεῖς καὶ εἴκοσι πόλεις αἱ τῆς ψήφου μετέχουσαι· συνέρχονται δὲ ἐξ ἑκάστης πόλεως εἰς κοινὸν συνέδριον, ἣν ἂν δοκιμάσωσι πόλιν ἑλόμενοι· τῶν δὲ πόλεων αἱ μέγισται μὲν τριῶν ψήφων ἐστὶν ἑκάστη κυρία, αἱ δὲ μέσαι δυεῖν, αἱ δ’ ἄλλαι μιᾶς· ἀνὰ λόγον δὲ καὶ τὰς εἰσφορὰς εἰσφέρουσι καὶ τὰς ἄλλας λειτουργίας. ἓξ δὲ τὰς μεγίστας ἔφη ὁ Ἀρτεμίδωρος, Ξάνθον Πάταρα Πίναρα Ὄλυμπον Μύρα Τλῶν κατὰ τὴν [ὑπέρ]θεσιν τὴν εἰς Κιβύραν κειμένην. ἐν δὲ τῷ συνεδρίῳ πρῶτον μὲν Λυκιάρχης αἱρεῖται, εἶτ’ ἄλλαι ἀρχαὶ αἱ τοῦ συστήματος· δικαστήριά τε ἀποδείκνυται κοινῇ· καὶ περὶ πολέμου δὲ καὶ εἰρήνης καὶ συμμαχίας ἐβουλεύοντο πρότερον, νῦν δ’ οὐκ εἰκός, ἀλλ’ ἐπὶ τοῖς Ῥωμαίοις ταῦτ’ ἀνάγκη κεῖσθαι, πλὴν εἰ ἐκείνων ἐπιτρεψάντων, ἢ ὑπὲρ αὐτῶν εἴη χρήσιμον· ὁμοίως δὲ καὶ δικασταὶ καὶ ἄρχοντες ἀνὰ λόγον ταῖς ψήφοις ἐξ ἑκάστης προχειρίζονται πόλεως. οὕτω δ’ εὐνομουμένοις αὐτοῖς συνέβη παρὰ Ῥωμαίοις ἐλευθέροις διατελέσαι τὰ πάτρια νέμουσι, τοὺς δὲ λῃστὰς ἐπιδεῖν ἄρδην ἠφανισμένους, πρότερον μὲν ὑπὸ Σερουιλίου τοῦ Ἰσαυρικοῦ, καθ’ ὃν χρόνον καὶ τὰ Ἴσαυρα ἐκεῖνος καθεῖλεν, ὕστερον δὲ Πομπηίου τοῦ Μάγνου, πλείω τῶν χιλίων καὶ τριακοσίων σκαφῶν ἐμπρήσαντος τὰς δὲ κατοικίας ἐκκόψαντος, τῶν δὲ περιγενομένων ἀνθρώπων ἐν ταῖς μάχαις τοὺς μὲν καταγαγόντος εἰς Σόλους, ἣν ἐκεῖνος Πομπηιόπολιν ὠνόμασε, τοὺς δ’ εἰς Δύμην λιπανδρήσασαν, ἣν νυνὶ Ῥωμαίων ἀποικία νέμεται. οἱ ποιηταὶ δὲ μάλιστα οἱ τραγικοὶ συγχέοντες τὰ ἔθνη, καθάπερ τοὺς Τρῶας καὶ τοὺς Μυσοὺς καὶ τοὺς Λυδοὺς Φρύγας προσαγορεύουσιν, οὕτω καὶ τοὺς Λυκίους Κᾶρας.", "st": "14.3.3"}, {"sp": "N", "t": "μετὰ δ’ οὖν τὰ Δαίδαλα τὸ τῶν Λυκίων ὄρος πλησίον ἐστὶ Τελεμησσὸς πολίχνη Λυκίων, καὶ Τελεμησσὶς ἄκρα λιμένα ἔχουσα. ἔλαβε δὲ τὸ χωρίον τοῦτο παρὰ Ῥωμαίων Εὐμένης ἐν τῷ Ἀντιοχικῷ πολέμῳ, καταλυθείσης δὲ τῆς βασιλείας ἀπέλαβον πάλιν οἱ Λύκιοι.", "st": "14.3.4"}, {"sp": "N", "t": "εἶθ’ ἑξῆς ὁ Ἀντίκραγος, ὄρθιον ὄρος, ἐφ’ ᾧ Καρμυλησσὸς χωρίον ἐν φάραγγι ᾠκημένον, καὶ μετὰ τοῦτον ὁ Κράγος, ἔχων ἄκρας ὀκτὼ καὶ πόλιν ὁμώνυμον. περὶ ταῦτα μυθεύεται τὰ ὄρη τὰ περὶ τῆς Χιμαίρας· ἔστι δ’ οὐκ ἄπωθεν καὶ ἡ Χίμαιρα φάραγξ τις ἀπὸ τοῦ αἰγιαλοῦ ἀνατείνουσα. ὑπόκειται δὲ τῷ Κράγῳ Πίναρα ἐν μεσογαίᾳ, τῶν μεγίστων οὖσα πόλεων ἐν τῇ Λυκίᾳ. ἐνταῦθα δὲ Πάνδαρος τιμᾶται, τυχὸν ἴσως ὁμώνυμος τῷ Τρωικῷ· καὶ γὰρ τοῦτον ἐκ Λυκίας φασίν.", "st": "14.3.5"}, {"sp": "N", "t": "εἶθ’ ὁ Ξάνθος ποταμός, ὃν Σίρβιν ἐκάλουν τὸ πρότερον· ἀναπλεύσαντι δ’ ὑπηρετικοῖς δέκα σταδίους τὸ Λητῷον ἔστιν· ὑπὲρ δὲ τοῦ ἱεροῦ προελθόντι ἑξήκοντα ἡ πόλις ἡ τῶν Ξανθίων ἐστὶ μεγίστη τῶν ἐν Λυκίᾳ. μετὰ δὲ τὴν Ξάνθον Πάταρα, καὶ αὕτη μεγάλη πόλις λιμένα ἔχουσα καὶ ἱερὰ Ἀπόλλωνος, κτίσμα Πατάρου. Πτολεμαῖος δ’ ὁ φιλάδελφος ἐπισκευάσας Ἀρσινόην ἐκάλεσε τὴν ἐν Λυκίᾳ, ἐπεκράτησε δὲ τὸ ἐξ ἀρχῆς ὄνομα.", "st": "14.3.6"}, {"sp": "N", "t": "εἶτα Μύρα ἐν εἴκοσι σταδίοις ὑπὲρ τῆς θαλάττης ἐπὶ μετεώρου λόφου. εἶθ’ ἡ ἐκβολὴ τοῦ Λιμύρου ποταμοῦ καὶ ἀνιόντι πεζῇ σταδίους εἴκοσι τὰ Λίμυρα πολίχνη. μεταξὺ δ’ ἐν τῷ λεχθέντι παράπλῳ νησία πολλὰ καὶ λιμένες, ὧν καὶ Μεγίστη νῆσος καὶ πόλις ὁμώνυμος, καὶ ἡ Κισθήνη. ἐν δὲ τῇ μεσογαίᾳ χωρία Φελλὸς καὶ Ἀντίφελλος καὶ ἡ Χίμαιρα, ἧς ἐμνήσθημεν ἐπάνω.", "st": "14.3.7"}, {"sp": "N", "t": "εἶθ’ Ἱερὰ ἄκρα καὶ αἱ Χελιδόνιαι τρεῖς νῆσοι τραχεῖαι, πάρισοι τὸ μέγεθος, ὅσον πέντε σταδίοις ἀλλήλων διέχουσαι· τῆς δὲ γῆς ἀφεστᾶσιν ἑξαστάδιον· μία δ’ αὐτῶν καὶ πρόσορμον ἔχει. ἐντεῦθεν νομίζουσιν οἱ πολλοὶ τὴν ἀρχὴν λαμβάνειν τὸν Ταῦρον διά τε τὴν ἄκραν ὑψηλὴν οὖσαν καὶ καθήκουσαν ἀπὸ τῶν Πισιδικῶν ὀρῶν τῶν ὑπερκειμένων τῆς Παμφυλίας καὶ διὰ τὰς προκειμένας νήσους ἐχούσας ἐπιφανές τι σημεῖον ἐν τῇ θαλάττῃ κρασπέδου δίκην. τὸ δ’ ἀληθὲς ἀπὸ τῆς Ῥοδίων περαίας ἐπὶ τὰ πρὸς Πισιδίαν μέρη συνεχής ἐστιν ἡ ὀρεινή, καλεῖται δὲ καὶ αὕτη Ταῦρος. δοκοῦσι δὲ αἱ Χελιδόνιαι κατὰ Κάνωβόν πως πίπτειν· τὸ δὲ δίαρμα λέγεται τετρακισχιλίων σταδίων. ἀπὸ δὲ τῆς Ἱερᾶς ἄκρας ἐπὶ τὴν Ὀλβίαν λείπονται στάδιοι τριακόσιοι ἑξήκοντα ἑπτά· ἐν τούτοις δ’ ἐστὶν ἥ τε Κράμβουσα καὶ Ὄλυμπος πόλις μεγάλη καὶ ὄρος ὁμώνυμον, ὃ καὶ Φοινικοῦς καλεῖται· εἶτα Κώρυκος ὁ αἰγιαλός.", "st": "14.3.8"}, {"sp": "N", "t": "εἶτα Φάσηλις τρεῖς ἔχουσα λιμένας, πόλις ἀξιόλογος καὶ λίμνη. ὑπέρκειται δ’ αὐτῆς τὰ Σόλυμα ὄρος καὶ Τερμησσὸς Πισιδικὴ πόλις, ἐπικειμένη τοῖς στενοῖς δι’ ὧν ὑπέρβασίς ἐστιν εἰς τὴν Μιλυάδα. καὶ ὁ Ἀλέξανδρος διὰ τοῦτο ἐξεῖλεν αὐτὴν ἀνοῖξαι βουλόμενος τὰ στενά. περὶ Φασήλιδα δ’ ἐστὶ τὰ κατὰ θάλατταν στενά, δι’ ὧν Ἀλέξανδρος παρήγαγε τὴν στρατιάν. ἔστι δ’ ὄρος Κλῖμαξ καλούμενον, ἐπίκειται δὲ τῷ Παμφυλίῳ πελάγει, στενὴν ἀπολεῖπον πάροδον ἐπὶ τῷ αἰγιαλῷ ταῖς μὲν νηνεμίαις γυμνουμένην ὥστε εἶναι βάσιμον τοῖς ὁδεύουσι, πλημμύροντος δὲ τοῦ πελάγους ὑπὸ τῶν κυμάτων καλυπτομένην ἐπὶ πολύ· ἡ μὲν οὖν διὰ τοῦ ὄρους ὑπέρβασις περίοδον ἔχει καὶ προσάντης ἐστί, τῷ δ’ αἰγιαλῷ χρῶνται κατὰ τὰς εὐδίας. ὁ δὲ Ἀλέξανδρος εἰς χειμέριον ἐμπεσὼν καιρὸν καὶ τὸ πλέον ἐπιτρέπων τῇ τύχῃ πρὶν ἀνεῖναι τὸ κῦμα ὥρμησε, καὶ ὅλην τὴν ἡμέραν ἐν ὕδατι γενέσθαι τὴν πορείαν συνέβη μέχρι ὀμφαλοῦ βαπτιζομένων. ἔστι μὲν οὖν καὶ αὕτη ἡ πόλις Λυκιακὴ ἐπὶ τῶν ὅρων ἱδρυμένη τῶν πρὸς Παμφυλίαν, τοῦ δὲ κοινοῦ τῶν Λυκίων οὐ μετέχει, καθ’ αὑτὴν δὲ συνέστηκεν.", "st": "14.3.9"}, {"sp": "N", "t": "ὁ μὲν οὖν ποιητὴς ἑτέρους τῶν Λυκίων ποιεῖ τοὺς Σολύμους· ὑπὸ γὰρ τοῦ τῶν Λυκίων βασιλέως πεμφθεὶς ὁ Βελλεροφόντης ἐπὶ δεύτερον τοῦτον ἆθλον<br>Σολύμοισι μαχέσσατο κυδαλίμοισιν.<br>οἱ δὲ τοὺς Λυκίους πρότερον καλεῖσθαι Σολύμους φάσκοντες, ὕστερον δὲ Τερμίλας ἀπὸ τῶν ἐκ Κρήτης συγκατελθόντων τῷ Σαρπηδόνι, μετὰ δὲ ταῦτα Λυκίους ἀπὸ Λύκου τοῦ Πανδίονος, ὃν ἐκπεσόντα τῆς οἰκείας ἐδέξατο Σαρπηδὼν ἐπὶ μέρει τῆς ἀρχῆς, οὐχ ὁμολογούμενα λέγουσιν Ὁμήρῳ· βελτίους δ’ οἱ φάσκοντες λέγεσθαι Σολύμους ὑπὸ τοῦ ποιητοῦ τοὺς νῦν Μιλύας προσαγορευομένους, περὶ ὧν εἰρήκαμεν.", "st": "14.3.10"}, {"sp": "N", "t": "μετὰ Φασήλιδα δ’ ἔστιν ἡ Ὁλβία, τῆς Παμφυλίας ἀρχή, μέγα ἔρυμα, καὶ μετὰ ταύτην ὁ Καταράκτης λεγόμενος ἀφ’ ὑψηλῆς πέτρας καταράττων ποταμὸς πολὺς καὶ χειμαρρώδης ὥστε πόρρωθεν ἀκούεσθαι τὸν ψόφον. εἶτα πόλις Ἀττάλεια, ἐπώνυμος τοῦ κτίσαντος Φιλαδέλφου καὶ οἰκίσαντος εἰς Κώρυκον, πολίχνιον ὅμορον, ἄλλην κατοικίαν καὶ μείζω περίβολον περιθέντος. φασὶ δ’ ἐν τῷ μεταξὺ Φασήλιδος καὶ Ἀτταλείας δείκνυσθαι Θήβην τε καὶ Λυρνησσόν, ἐκπεσόντων ἐκ τοῦ Θήβης πεδίου τῶν Τρωικῶν Κιλίκων εἰς τὴν Παμφυλίαν ἐκ μέρους, ὡς εἴρηκε Καλλισθένης.", "st": "14.4.1"}, {"sp": "N", "t": "εἶθ’ ὁ Κέστρος ποταμός, ὃν ἀναπλεύσαντι σταδίους ἑξήκοντα Πέργη πόλις καὶ πλησίον ἐπὶ μετεώρου τόπου τὸ τῆς Περγαίας Ἀρτέμιδος ἱερόν, ἐν ᾧ πανήγυρις κατ’ ἔτος συντελεῖται. εἶθ’ ὑπὲρ τῆς θαλάττης ὅσον τετταράκοντα Σύλλιον πόλις ἐστὶν ὑψηλὴ τοῖς ἐκ Πέργης ἔποπτος· εἶτα λίμνη εὐμεγέθης Καπρία καὶ μετὰ ταῦτα ὁ Εὐρυμέδων ποταμός, ὃν ἀναπλεύσαντι ἑξήκοντα σταδίους Ἄσπενδος πόλις εὐανδροῦσα ἱκανῶς, Ἀργείων κτίσμα· ὑπέρκειται δὲ ταύτης Πετνηλισσός· εἶτ’ ἄλλος ποταμὸς καὶ νησία προκείμενα πολλά· εἶτα Σίδη Κυμαίων ἄποικος· ἔχει δ’ Ἀθηνᾶς ἱερόν. πλησίον δ’ ἐστὶ καὶ ἡ Κιβυρατῶν παραλία τῶν μικρῶν· εἶθ’ ὁ Μέλας ποταμὸς καὶ ὕφορμος· εἶτα Πτολεμαῒς πόλις· καὶ μετὰ ταῦθ’ οἱ ὅροι τῆς Παμφυλίας καὶ τὸ Κορακήσιον, ἀρχὴ τῆς τραχείας Κιλικίας. ὁ δὲ παράπλους ἅπας ὁ Παμφύλιος στάδιοί εἰσιν ἑξακόσιοι τεσσαράκοντα.", "st": "14.4.2"}, {"sp": "N", "t": "φησὶ δ’ Ἡρόδοτος τοὺς Παμφύλους τῶν μετὰ Ἀμφιλόχου καὶ Κάλχαντος εἶναι λαῶν μιγάδων τινῶν ἐκ Τροίας συνακολουθησάντων· τοὺς μὲν δὴ πολλοὺς ἐνθάδε καταμεῖναι, τινὰς δὲ σκεδασθῆναι πολλαχοῦ τῆς γῆς. Καλλῖνος δὲ τὸν μὲν Κάλχαντα ἐν Κλάρῳ τελευτῆσαι τὸν βίον φησί, τοὺς δὲ λαοὺς μετὰ Μόψου τὸν Ταῦρον ὑπερθέντας τοὺς μὲν ἐν Παμφυλίᾳ μεῖναι τοὺς δ’ ἐν Κιλικίᾳ μερισθῆναι καὶ Συρίᾳ μέχρι καὶ Φοινίκης.", "st": "14.4.3"}, {"sp": "N", "t": "τῆς Κιλικίας δὲ τῆς ἔξω τοῦ Ταύρου ἡ μὲν λέγεται τραχεῖα ἡ δὲ πεδιάς· τραχεῖα μέν, ἧς ἡ παραλία στενή ἐστι καὶ οὐδὲν ἢ σπανίως ἔχει τι χωρίον ἐπίπεδον, καὶ ἔτι ἧς ὑπέρκειται ὁ Ταῦρος οἰκούμενος κακῶς μέχρι καὶ τῶν προσβόρρων πλευρῶν τῶν περὶ Ἴσαυρα καὶ τοὺς Ὁμοναδέας μέχρι τῆς Πισιδίας· καλεῖται δ’ ἡ αὐτὴ καὶ Τραχειῶτις καὶ οἱ ἐνοικοῦντες Τραχειῶται· πεδιὰς δ’ ἡ ἀπὸ Σόλων καὶ Ταρσοῦ μέχρι Ἰσσοῦ, καὶ ἔτι ἧς ὑπέρκεινται κατὰ τὸ πρόσβορρον τοῦ Ταύρου πλευρὸν Καππάδοκες· αὕτη γὰρ ἡ χώρα τὸ πλέον πεδίων εὐπορεῖ καὶ χώρας ἀγαθῆς. ἐπεὶ δὲ τούτων τὰ μέν ἐστιν ἐντὸς τοῦ Ταύρου τὰ δ’ ἐκτός, περὶ μὲν τῶν ἐντὸς εἴρηται, περὶ δὲ τῶν ἐκτὸς λέγωμεν ἀπὸ τῶν Τραχειωτῶν ἀρξάμενοι.", "st": "14.5.1"}, {"sp": "N", "t": "πρῶτον τοίνυν ἐστὶ τῶν Κιλίκων φρούριον τὸ Κορακήσιον ἱδρυμένον ἐπὶ πέτρας ἀπορρῶγος, ᾧ ἐχρήσατο Διόδοτος ὁ Τρύφων προσαγορευθεὶς ὁρμητηρίῳ καθ’ ὃν καιρὸν ἀπέστησε τὴν Συρίαν τῶν βασιλέων καὶ διεπολέμει πρὸς ἐκείνους, τοτὲ μὲν κατορθῶν τοτὲ δὲ πταίων. τοῦτον μὲν οὖν Ἀντίοχος ὁ Δημητρίου κατακλείσας εἴς τι χωρίον ἠνάγκασε διεργάσασθαι τὸ σῶμα· τοῖς δὲ Κίλιξιν ἀρχὴν τοῦ τὰ πειρατικὰ συνίστασθαι Τρύφων αἴτιος κατέστη καὶ ἡ τῶν βασιλέων οὐδένεια τῶν τότε ἐκ διαδοχῆς ἐπιστατούντων τῆς Συρίας ἅμα καὶ τῆς Κιλικίας· τῷ γὰρ ἐκείνου νεωτερισμῷ συνενεωτέρισαν καὶ ἄλλοι, διχοστατοῦντές τε ἀδελφοὶ πρὸς ἀλλήλους ὑποχείριον ἐποίουν τὴν χώραν τοῖς ἐπιτιθεμένοις. ἡ δὲ τῶν ἀνδραπόδων ἐξαγωγὴ προὐκαλεῖτο μάλιστα εἰς τὰς κακουργίας ἐπικερδεστάτη γενομένη· καὶ γὰρ ἡλίσκοντο ῥᾳδίως, καὶ τὸ ἐμπόριον οὐ παντελῶς ἄπωθεν ἦν μέγα καὶ πολυχρήματον, ἡ Δῆλος, δυναμένη μυριάδας ἀνδραπόδων αὐθημερὸν καὶ δέξασθαι καὶ ἀποπέμψαι, ὥστε καὶ παροιμίαν γενέσθαι διὰ τοῦτο “ἔμπορε, κατάπλευσον, ἐξελοῦ, πάντα πέπραται.” αἴτιον δ’ ὅτι πλούσιοι γενόμενοι Ῥωμαῖοι μετὰ τὴν Καρχηδόνος καὶ Κορίνθου κατασκαφὴν οἰκετείαις ἐχρῶντο πολλαῖς· ὁρῶντες δὲ τὴν εὐπέτειαν οἱ λῃσταὶ ταύτην ἐξήνθησαν ἀθρόως, αὐτοὶ καὶ λῃζόμενοι καὶ σωματεμποροῦντες. συνήργουν δ’ εἰς ταῦτα καὶ οἱ τῆς Κύπρου καὶ οἱ τῆς Αἰγύπτου βασιλεῖς ἐχθροὶ τοῖς Σύροις ὄντες· οὐδ’ οἱ Ῥόδιοι δὲ φίλοι ἦσαν αὐτοῖς ὥστ’ οὐδὲν ἐβοήθουν· ἅμα δὲ καὶ οἱ λῃσταὶ προσποιούμενοι σωματεμπορεῖν ἄλυτον τὴν κακουργίαν εἶχον. ἀλλ’ οὐδὲ Ῥωμαῖοί πω τοσοῦτον ἐφρόντιζον τῶν ἔξω τοῦ Ταύρου, ἀλλ’ ἔπεμψαν μὲν καὶ Σκιπίωνα τὸν Αἰμιλιανὸν ἐπισκεψόμενον τὰ ἔθνη καὶ τὰς πόλεις καὶ πάλιν ἄλλους τινάς, ἔγνωσαν δὲ κακίᾳ τῶν ἀρχόντων συμβαῖνον τοῦτο, εἰ καὶ τὴν κατὰ γένος διαδοχὴν τὴν ἀπὸ Σελεύκου τοῦ Νικάτορος αὐτοὶ κεκυρωκότες ᾐδοῦντο ἀφαιρεῖσθαι. τοῦτο δὲ συμβὰν τῆς μὲν χώρας ἐποίησε κυρίους Παρθυαίους, οἳ τὰ πέραν τοῦ Εὐφράτου κατέσχον, τὸ τελευταῖον δὲ καὶ Ἀρμενίους, οἳ καὶ τὴν ἐκτὸς τοῦ Ταύρου προσέλαβον μέχρι καὶ Φοινίκης, καὶ τοὺς βασιλέας κατέλυσαν εἰς δύναμιν καὶ τὸ γένος αὐτῶν σύμπαν, τὴν δὲ θάλατταν τοῖς Κίλιξι παρέδωκαν. εἶτ’ αὐξηθέντας ἠναγκάσθησαν καταλύειν Ῥωμαῖοι πολέμῳ καὶ μετὰ στρατιᾶς οὓς αὐξομένους οὐκ ἐκώλυσαν. ὀλιγωρίαν μὲν οὖν αὐτῶν χαλεπὸν καταγνῶναι· πρὸς ἑτέροις δὲ ὄντες τοῖς ἐγγυτέρω καὶ κατὰ χεῖρα μᾶλλον οὐχ οἷοί τε ἦσαν τὰ ἀπωτέρω σκοπεῖν. ταῦτα μὲν οὖν ἔδοξεν ἡμῖν ἐν παρεκβάσει διὰ βραχέων εἰπεῖν.", "st": "14.5.2"}, {"sp": "N", "t": "μετὰ δὲ τὸ Κορακήσιον Ἀρσινόη πόλις, εἶθ’ Ἁμαξία ἐπὶ βουνοῦ κατοικία τις ὕφορμον ἔχουσα, ὅπου κατάγεται ἡ ναυπηγήσιμος ὕλη. κέδρος δ’ ἐστὶν ἡ πλείστη, καὶ δοκεῖ ταῦτα τὰ μέρη πλεονεκτεῖν τῇ τοιαύτῃ ξυλείᾳ· καὶ διὰ τοῦτ’ Ἀντώνιος Κλεοπάτρᾳ τὰ χωρία ταῦτα προσένειμεν ἐπιτήδεια ὄντα πρὸς τὰς τῶν στόλων κατασκευάς. εἶτα Λαέρτης φρούριον ἐπὶ λόφου μαστοειδοῦς ὕφορμον ἔχον· εἶτα Σελινοῦς πόλις· εἶτα Κράγος πέτρα περίκρημνος πρὸς θαλάττῃ· εἶτα Χαραδροῦς ἔρυμα καὶ αὐτὸ ὕφορμον ἔχον (ὑπέρκειται δ’ ὄρος Ἄνδρικλος) καὶ παράπλους τραχὺς Πλατανιστῆς καλούμενος· εἶτ’ Ἀνεμούριον ἄκρα καθ’ ἣν ἡ ἤπειρος ἐγγυτάτω τῆς Κυπρίας ἐστὶν ἐπὶ Κρομμύου ἄκραν ἐν διάρματι σταδίων τριακοσίων πεντήκοντα. εἰς μὲν οὖν τὸ Ἀνεμούριον ἀπὸ τῶν ὅρων τῆς Παμφυλίας ὁ Κιλίκιος παράπλους σταδίων ἐστὶν ὀκτακοσίων εἴκοσι, λοιπὸς δ’ ἐστὶ μέχρι Σόλων ὅσον πεντακοσίων παράπλους σταδίων. τούτου δ’ ἐστὶ Νάγιδος πρώτη μετὰ τὸ Ἀνεμούριον πόλις· εἶτ’ Ἀρσινόη πρόσορμον ἔχουσα· εἶτα τόπος Μελανία καὶ Κελένδερις πόλις λιμένα ἔχουσα. τινὲς δὲ ταύτην ἀρχὴν τίθενται τῆς Κιλικίας, οὐ τὸ Κορακήσιον, ὧν ἐστι καὶ ὁ Ἀρτεμίδωρος· καί φησιν ἀπὸ μὲν τοῦ Πηλουσιακοῦ στόματος εἶναι τρισχιλίους ἑξακοσίους σταδίους εἰς Ὀρθωσίαν, ἐπὶ δὲ τὸν Ὀρόντην ποταμὸν χίλια ἑκατὸν τριάκοντα, ἐπὶ δὲ τὰς πύλας ἑξῆς πεντακόσια εἰκοσιπέντε, ἐπὶ δὲ τοὺς ὅρους τῶν Κιλίκων χίλια ἐνακόσια εἴκοσιν.", "st": "14.5.3"}, {"sp": "N", "t": "εἶθ’ Ὅλμοι, ὅπου πρότερον ᾤκουν οἱ νῦν Σελευκεῖς, κτισθείσης δ’ ἐπὶ τῷ Καλυκάδνῳ τῆς Σελευκείας ἐκεῖ μετῳκίσθησαν. εὐθὺς γάρ ἐστιν ἡ τοῦ Καλυκάδνου ἐκβολὴ κάμψαντι ᾐόνα ποιοῦσαν ἄκραν ἣ καλεῖται Σαρπηδών. πλησίον δ’ ἐστὶ τοῦ Καλυκάδνου καὶ τὸ Ζεφύριον καὶ αὕτη ἄκρα· ἔχει δὲ ὁ ποταμὸς ἀνάπλουν εἰς τὴν Σελεύκειαν πόλιν εὖ συνοικουμένην καὶ πολὺ ἀφεστῶσαν τοῦ Κιλικίου καὶ Παμφυλίου τρόπου. ἐνταῦθα ἐγένοντο καθ’ ἡμᾶς ἄνδρες ἀξιόλογοι τῶν ἐκ τοῦ περιπάτου φιλοσόφων Ἀθήναιός τε καὶ Ξέναρχος, ὧν ὁ μὲν Ἀθήναιος καὶ ἐπολιτεύσατο καὶ ἐδημαγώγησε χρόνον τινὰ ἐν τῇ πατρίδι, εἶτ’ ἐμπεσὼν εἰς τὴν Μουρήνα φιλίαν ἐκείνῳ συνεάλω φεύγων φωραθείσης τῆς κατὰ Καίσαρος τοῦ Σεβαστοῦ συσταθείσης ἐπιβουλῆς· ἀναίτιος δὲ φανεὶς ἀφείθη ὑπὸ Καίσαρος. ὡς δ’ ἐπανιόντα εἰς Ῥώμην ἠσπάζοντο καὶ ἐπυνθάνοντο οἱ πρῶτοι ἐντυγχάνοντες, τὸ Εὐριπίδου ἔφη<br>ἥκω νεκρῶν κευθμῶνα καὶ σκότου πύλας λιπών.<br>ὀλίγον δ’ ἐπιβιοὺς χρόνον ἐν συμπτώσει τῆς οἰκίας ἐν ᾗ ᾤκει διεφθάρη νύκτωρ γενομένῃ, Ξέναρχος δέ, οὗ ἠκροασάμεθα ἡμεῖς, ἐν οἴκῳ μὲν οὐ πολὺ διέτριψεν, ἐν Ἀλεξανδρείᾳ δὲ καὶ Ἀθήνησι καὶ τὸ τελευταῖον ἐν Ῥώμῃ, τὸν παιδευτικὸν βίον ἑλόμενος· χρησάμενος δὲ καὶ τῇ Ἀρείου φιλίᾳ καὶ μετὰ ταῦτα τῇ Καίσαρος τοῦ Σεβαστοῦ διετέλεσε μέχρι γήρως ἐν τιμῇ ἀγόμενος· μικρὸν δὲ πρὸ τῆς τελευτῆς πηρωθεὶς τὴν ὄψιν κατέστρεψε νόσῳ τὸν βίον.", "st": "14.5.4"}, {"sp": "N", "t": "μετὰ δὲ τὸν Καλύκαδνον ἡ Ποικίλη λεγομένη πέτρα κλίμακα ἔχουσα λατομητὴν ἐπὶ Σελεύκειαν ἄγουσαν. εἶτ’ Ἀνεμούριον ἄκρα ὁμώνυμος τῇ προτέρᾳ, καὶ Κράμβουσα νῆσος καὶ Κώρυκος ἄκρα, ὑπὲρ ἧς ἐν εἴκοσι σταδίοις ἐστὶ τὸ Κωρύκιον ἄντρον, ἐν ᾧ ἡ ἀρίστη κρόκος φύεται. ἔστι δὲ κοιλὰς μεγάλη κυκλοτερὴς ἔχουσα περικειμένην ὀφρὺν πετρώδη πανταχόθεν ἱκανῶς ὑψηλήν· καταβάντι δ’ εἰς αὐτὴν ἀνώμαλόν ἐστιν ἔδαφος καὶ τὸ πολὺ πετρῶδες, μεστὸν δὲ τῆς θαμνώδους ὕλης ἀειθαλοῦς τε καὶ ἡμέρου· παρέσπαρται δὲ καὶ τὰ ἐδάφη τὰ φέροντα τὴν κρόκον. ἔστι δὲ καὶ ἄντρον αὐτόθι ἔχον πηγὴν μεγάλην ποταμὸν ἐξιεῖσαν καθαροῦ τε καὶ διαφανοῦς ὕδατος, εὐθὺς καταπίπτοντα ὑπὸ γῆς· ἐνεχθεὶς δ’ ἀφανὴς ἔξεισιν εἰς τὴν θάλατταν· καλοῦσι δὲ πικρὸν ὕδωρ.", "st": "14.5.5"}, {"sp": "N", "t": "εἶθ’ ἡ Ἐλαιοῦσσα νῆσος μετὰ τὴν Κώρυκον, προσκειμένη τῇ ἠπείρῳ, ἣν συνῴκισεν Ἀρχέλαος καὶ κατεσκευάσατο βασίλειον λαβὼν τὴν Τραχειῶτιν Κιλικίαν ὅλην πλὴν Σελευκείας, καθ’ ὃν τρόπον καὶ Ἀμύντας πρότερον εἶχε καὶ ἔτι πρότερον Κλεοπάτρα. εὐφυοῦς γὰρ ὄντος τοῦ τόπου πρὸς τὰ λῃστήρια καὶ κατὰ γῆν καὶ κατὰ θάλατταν (κατὰ γῆν μὲν διὰ τὸ μέγεθος τῶν ὀρῶν καὶ τῶν ὑπερκειμένων ἐθνῶν, πεδία καὶ γεώργια ἐχόντων μεγάλα καὶ εὐκατατρόχαστα, κατὰ θάλατταν δὲ διὰ τὴν εὐπορίαν τῆς τε ναυπηγησίμου ὕλης καὶ τῶν λιμένων καὶ ἐρυμάτων καὶ ὑποδυτηρίων), ἐδόκει πρὸς ἅπαν τὸ τοιοῦτο βασιλεύεσθαι μᾶλλον τοὺς τόπους ἢ ὑπὸ τοῖς Ῥωμαίοις ἡγεμόσιν εἶναι τοῖς ἐπὶ τὰς κρίσεις πεμπομένοις, οἳ μήτ’ ἀεὶ παρεῖναι ἔμελλον μήτε μεθ’ ὅπλων. οὕτω μὲν Ἀρχέλαος ἔλαβε πρὸς τῇ Καππαδοκίᾳ τὴν τραχεῖαν Κιλικίαν. εἰσὶ δ’ ὅροι ταύτης μεταξὺ Σόλων τε καὶ Ἐλαιούσσης ὁ Λάμος ποταμὸς καὶ κώμη ὁμώνυμος.", "st": "14.5.6"}, {"sp": "N", "t": "κατὰ δὲ τὰς ἀκρωρείας τοῦ Ταύρου τὸ Ζηνικέτου πειρατήριόν ἐστιν ὁ Ὄλυμπος ὄρος τε καὶ φρούριον ὁμώνυμον, ἀφ’ οὗ κατοπτεύεται πᾶσα Λυκία καὶ Παμφυλία καὶ Πισιδία καὶ Μιλυάς· ἁλόντος δὲ τοῦ ὄρους [ὑπὸ] τοῦ Ἰσαυρικοῦ, ἐνέπρησεν ἑαυτὸν πανοίκιον. τούτου δ’ ἦν καὶ ὁ Κώρυκος καὶ ἡ Φάσηλις καὶ πολλὰ τῶν Παμφύλων χωρία· πάντα δ’ εἷλεν ὁ Ἰσαυρικός.", "st": "14.5.7"}, {"sp": "N", "t": "μετὰ δὲ Λάμον Σόλοι πόλις ἀξιόλογος, τῆς ἄλλης Κιλικίας ἀρχὴ τῆς περὶ τὸν Ἰσσόν, Ἀχαιῶν καὶ Ῥοδίων κτίσμα τῶν ἐκ Λίνδου· εἰς ταύτην λιπανδρήσασαν Πομπήιος Μάγνος κατῴκισε τοὺς περιγενομένους τῶν πειρατῶν, οὓς μάλιστα ἔγνω σωτηρίας καὶ προνοίας τινὸς ἀξίους, καὶ μετωνόμασε Πομπηιόπολιν. γεγόνασι δ’ ἄνδρες ἐνθένδε τῶν ὀνομαστῶν Χρύσιππός τε ὁ στωικὸς φιλόσοφος πατρὸς ὢν Ταρσέως ἐκεῖθεν μετοικήσαντος, καὶ Φιλήμων ὁ κωμικὸς ποιητής, καὶ Ἄρατος ὁ τὰ φαινόμενα συγγράψας ἐν ἔπεσιν.", "st": "14.5.8"}, {"sp": "N", "t": "εἶτα Ζεφύριον ὁμώνυμον τῷ πρὸς Καλύδνῳ· εἶτ’ Ἀγχιάλη μικρὸν ὑπὲρ τῆς θαλάττης, κτίσμα Σαρδαναπάλλου, φησὶν Ἀριστόβουλος· ἐνταῦθα δ’ εἶναι μνῆμα τοῦ Σαρδαναπάλλου καὶ τύπον λίθινον συμβάλλοντα τοὺς τῆς δεξιᾶς χειρὸς δακτύλους ὡς ἂν ἀποκροτοῦντα, καὶ ἐπιγραφὴν εἶναι Ἀσσυρίοις γράμμασι τοιάνδε “Σαρδανάπαλλος ὁ Ἀνακυνδαράξεω παῖς Ἀγχιάλην καὶ Ταρσὸν ἔδειμεν ἡμέρῃ μιῇ. ἔσθιε πῖνε παῖζε, ὡς τἆλλα τούτου οὐκ ἄξια,” τοῦ ἀποκροτήματος. μέμνηται δὲ καὶ Χοιρίλος τούτων· καὶ δὴ καὶ περιφέρεται τὰ ἔπη ταυτί<br>ταῦτ’ ἔχω, ὅσσ’ ἔφαγον καὶ ἀφύβρισα, καὶ μετ’ ἔρωτος<br>τέρπν’ ἔπαθον, τὰ δὲ πολλὰ καὶ ὄλβια κεῖνα λέλειπται.", "st": "14.5.9"}, {"sp": "N", "t": "ὑπέρκειται δὲ τὰ Κύινδα τῆς Ἀγχιάλης ἔρυμα, ᾧ ἐχρήσαντό ποτε οἱ Μακεδόνες γαζοφυλακίῳ· ἦρε δὲ τὰ χρήματα Εὐμένης ἀποστὰς Ἀντιγόνου. ἔτι δ’ ὕπερθεν τούτου τε καὶ τῶν Σόλων ὀρεινή ἐστιν, ἐν ᾗ Ὄλβη πόλις Διὸς ἱερὸν ἔχουσα, Αἴαντος ἵδρυμα τοῦ Τεύκρου· καὶ ὁ ἱερεὺς δυνάστης ἐγίνετο τῆς Τραχειώτιδος· εἶτ’ ἐπέθεντο τῇ χώρᾳ τύραννοι πολλοί, καὶ συνέστη τὰ λῃστήρια. μετὰ δὲ τὴν τούτων κατάλυσιν ἐφ’ ἡμῶν ἤδη τὴν τοῦ Τεύκρου δυναστείαν ταύτην ἐκάλουν, τὴν δ’ αὐτὴν καὶ ἱερωσύνην· καὶ οἱ πλεῖστοί γε τῶν ἱερασαμένων ὠνομάζοντο Τεῦκροι ἢ Αἴαντες. εἰσιοῦσα δὲ Ἄβα κατ’ ἐπιγαμίαν εἰς τὸν οἶκον τοῦτον, ἡ Ζηνοφάνους θυγάτηρ ἑνὸς τῶν τυράννων, αὐτὴ κατέσχε τὴν ἀρχὴν προλαβόντος τοῦ πατρὸς ἐν ἐπιτρόπου σχήματι· ὕστερον δὲ καὶ Ἀντώνιος καὶ Κλεοπάτρα κατεχαρίσαντο ἐκείνῃ θεραπείαις ἐκλιπαρηθέντες· ἔπειθ’ ἡ μὲν κατελύθη τοῖς δ’ ἀπὸ τοῦ γένους διέμεινεν ἡ ἀρχή. μετὰ δὲ τὴν Ἀγχιάλην αἱ τοῦ Κύδνου ἐκβολαὶ κατὰ τὸ Ῥῆγμα καλούμενον. ἔστι δὲ λιμνάζων τόπος ἔχων καὶ παλαιὰ νεώρια, εἰς ὃν ἐκπίπτει ὁ Κύδνος ὁ διαρρέων μέσην τὴν Ταρσὸν τὰς ἀρχὰς ἔχων ἀπὸ τοῦ ὑπερκειμένου τῆς πόλεως Ταύρου· καὶ ἔστιν ἐπίνειον ἡ λίμνη τῆς Ταρσοῦ.", "st": "14.5.10"}, {"sp": "N", "t": "μέχρι μὲν δὴ δεῦρο ἡ παραλία πᾶσα ἀπὸ τῆς Ῥοδίων περαίας ἀρξαμένη πρὸς ἰσημερινὰς ἀνατολὰς ἀπὸ τῶν ὁμωνύμων ἐκτείνεται δύσεων, εἶτ’ ἐπὶ τὴν χειμερινὴν ἀνατολὴν ἐπιστρέφει μέχρι Ἰσσοῦ, κἀντεῦθεν ἤδη καμπὴν λαμβάνει πρὸς νότον μέχρι Φοινίκης, τὸ δὲ λοιπὸν πρὸς δύσιν μέχρι στηλῶν τελευτᾷ. τὸ μὲν οὖν ἀληθὲς ὁ ἰσθμὸς τῆς περιωδευμένης χερρονήσου οὗτός ἐστιν ὁ ἀπὸ Ταρσοῦ καὶ τῆς ἐκβολῆς τοῦ Κύδνου μέχρι Ἀμισοῦ· τὸ γὰρ ἐλάχιστον ἐξ Ἀμισοῦ διάστημα ἐπὶ τοὺς Κιλίκων ὅρους τοῦτ’ ἔστιν· ἐντεῦθεν δὲ ἑκατὸν εἴκοσίν εἰσιν εἰς Ταρσὸν στάδιοι, κἀκεῖθεν οὐ πλείους ἐπὶ τὴν ἐκβολὴν τοῦ Κύδνου. καὶ μὴν ἐπί γε Ἰσσὸν καὶ τὴν κατ’ αὐτὴν θάλατταν οὔτ’ ἄλλη ὁδὸς συντομωτέρα ἐστὶν ἐξ Ἀμισοῦ τῆς διὰ Ταρσοῦ, οὔτ’ ἐκ Ταρσοῦ ἐπὶ Ἰσσὸν ἐγγυτέρω ἐστὶν ἢ ἐπὶ Κύδνον, ὥστε δῆλον ὅτι ταῖς μὲν ἀληθείαις οὗτος ἂν εἴη ὁ ἰσθμός, λέγεται δ’ ὅμως ὁ μέχρι τοῦ Ἰσσικοῦ κόλπου, παρακλεπτόντων διὰ τὸ σημειῶδες. διὰ δὲ τοῦτ’ αὐτὸ καὶ τὴν ἐκ τῆς Ῥοδίας γραμμήν, ἣν μέχρι τοῦ Κύδνου κατηγάγομεν, τὴν αὐτὴν ἀποφαίνομεν τῇ μέχρι Ἰσσοῦ, οὐδὲν παρὰ τοῦτο ποιούμενοι, καὶ τὸν Ταῦρόν φαμεν διήκειν ἐπ’ εὐθείας τῇδε τῇ γραμμῇ μέχρι τῆς Ἰνδικῆς.", "st": "14.5.11"}, {"sp": "N", "t": "ἡ δὲ Ταρσὸς κεῖται μὲν ἐν πεδίῳ κτίσμα δ’ ἐστὶ τῶν μετὰ Τριπτολέμου πλανηθέντων Ἀργείων κατὰ ζήτησιν Ἰοῦς· διαρρεῖ δ’ αὐτὴν μέσην ὁ Κύδνος παρ’ αὐτὸ τὸ γυμνάσιον τῶν νέων· ἅτε δὲ τῆς πηγῆς οὐ πολὺ ἄπωθεν οὔσης, καὶ τοῦ ῥείθρου διὰ φάραγγος βαθείας ἰόντος, εἶτ’ εὐθὺς εἰς τὴν πόλιν ἐκπίπτοντος, ψυχρόν τε καὶ τραχὺ τὸ ῥεῦμά ἐστιν, ὅθεν καὶ τοῖς παχυνευροῦσι ῥοϊζομένοις καὶ κτήνεσι καὶ ἀνθρώποις ἐπικουρεῖ.", "st": "14.5.12"}, {"sp": "N", "t": "τοσαύτη δὲ τοῖς ἐνθάδε ἀνθρώποις σπουδὴ πρός τε φιλοσοφίαν καὶ τὴν ἄλλην παιδείαν ἐγκύκλιον ἅπασαν γέγονεν ὥσθ’ ὑπερβέβληνται καὶ Ἀθήνας καὶ Ἀλεξάνδρειαν καὶ εἴ τινα ἄλλον τόπον δυνατὸν εἰπεῖν, ἐν ᾧ σχολαὶ καὶ διατριβαὶ φιλοσόφων γεγόνασι. διαφέρει δὲ τοσοῦτον ὅτι ἐνταῦθα μὲν οἱ φιλομαθοῦντες ἐπιχώριοι πάντες εἰσί, ξένοι δ’ οὐκ ἐπιδημοῦσι ῥᾳδίως· οὐδ’ αὐτοὶ οὗτοι μένουσιν αὐτόθι, ἀλλὰ καὶ τελειοῦνται ἐκδημήσαντες καὶ τελειωθέντες ξενιτεύουσιν ἡδέως, κατέρχονται δ’ ὀλίγοι. ταῖς δ’ ἄλλαις πόλεσιν ἃς ἀρτίως εἶπον πλὴν Ἀλεξανδρείας συμβαίνει τἀναντία· φοιτῶσι γὰρ εἰς αὐτὰς πολλοὶ καὶ διατρίβουσιν αὐτόθι ἄσμενοι, τῶν δ’ ἐπιχωρίων οὐ πολλοὺς οὔτ’ ἂν ἔξω φοιτῶντας ἴδοις κατὰ φιλομάθειαν, οὔτ’ αὐτόθι περὶ τοῦτο σπουδάζοντας· Ἀλεξανδρεῦσι δ’ ἀμφότερα συμβαίνει· καὶ γὰρ δέχονται πολλοὺς τῶν ξένων καὶ ἐκπέμπουσι τῶν ἰδίων οὐκ ὀλίγους … καὶ εἰσὶ σχολαὶ παρ’ αὐτοῖς παντοδαπαὶ τῶν περὶ λόγους τεχνῶν, καὶ τἆλλα δ’ εὐανδρεῖ καὶ πλεῖστον δύναται τὸν τῆς μητροπόλεως ἐπέχουσα λόγον.", "st": "14.5.13"}, {"sp": "N", "t": "ἄνδρες δ’ ἐξ αὐτῆς γεγόνασι τῶν μὲν στωικῶν Ἀντίπατρός τε καὶ Ἀρχέδημος καὶ Νέστωρ, ἔτι δ’ Ἀθηνόδωροι δύο, ὧν ὁ μὲν Κορδυλίων καλούμενος συνεβίωσε Μάρκῳ Κάτωνι καὶ ἐτελεύτα παρ’ ἐκείνῳ, ὁ δὲ τοῦ Σάνδωνος, ὃν καὶ Κανανίτην φασὶν ἀπὸ κώμης τινός, Καίσαρος καθηγήσατο καὶ τιμῆς ἔτυχε μεγάλης, κατιών τε εἰς τὴν πατρίδα ἤδη γηραιὸς κατέλυσε τὴν καθεστῶσαν πολιτείαν κακῶς φερομένην ὑπό τε ἄλλων καὶ Βοήθου, κακοῦ μὲν ποιητοῦ κακοῦ δὲ πολίτου, δημοκοπίαις ἰσχύσαντος τὸ πλέον. ἐπῆρε δ’ αὐτὸν καὶ Ἀντώνιος κατ’ ἀρχὰς ἀποδεξάμενος τὸ γραφὲν εἰς τὴν ἐν Φιλίπποις νίκην ἔπος, καὶ ἔτι μᾶλλον ἡ εὐχέρεια ἡ ἐπιπολάζουσα παρὰ τοῖς Ταρσεῦσιν ὥστ’ ἀπαύστως σχεδιάζειν παρὰ χρῆμα πρὸς τὴν δεδομένην ὑπόθεσιν· καὶ δὴ καὶ γυμνασιαρχίαν ὑποσχόμενος Ταρσεῦσι τοῦτον ἀντὶ γυμνασιάρχου κατέστησε, καὶ τὰ ἀναλώματα ἐπίστευσεν αὐτῷ. ἐφωράθη δὲ νοσφισάμενος τά τε ἄλλα καὶ τοὔλαιον· ἐλεγχόμενος δ’ ὑπὸ τῶν κατηγόρων ἐπὶ τοῦ Ἀντωνίου παρῃτεῖτο τὴν ὀργήν, σὺν ἄλλοις καὶ ταῦτα λέγων ὅτι “ὥσπερ Ὅμηρος ἐξύμνησεν Ἀχιλλέα καὶ Ἀγαμέμνονα καὶ Ὀδυσσέα, οὕτως ἐγὼ σέ· οὐ δίκαιος οὖν εἰμι εἰς τοιαύτας ἄγεσθαι διαβολὰς ἐπὶ σοῦ.” παραλαβὼν οὖν ὁ κατήγορος τὸν λόγον “ἀλλ’ Ὅμηρος μέν” ἔφη “ἔλαιον Ἀγαμέμνονος οὐκ ἔκλεψεν, ἀλλ’ οὐδὲ Ἀχιλλέως, σὺ δέ· ὥστε δώσεις δίκην.” διακρουσάμενος δ’ οὖν θεραπείαις τισὶ τὴν ὀργὴν οὐδὲν ἧττον διετέλεσεν ἄγων καὶ φέρων τὴν πόλιν μέχρι τῆς καταστροφῆς τοῦ Ἀντωνίου. τοιαύτην δὲ τὴν πόλιν καταλαβὼν ὁ Ἀθηνόδωρος τέως μὲν ἐπεχείρει λόγῳ μετάγειν κἀκεῖνον καὶ τοὺς συστασιώτας· ὡς δ’ οὐκ ἀπείχοντο ὕβρεως οὐδεμιᾶς, ἐχρήσατο τῇ δοθείσῃ ὑπὸ τοῦ Καίσαρος ἐξουσίᾳ καὶ ἐξέβαλεν αὐτοὺς καταγνοὺς φυγήν. οἱ δὲ πρῶτον μὲν κατετοιχογράφησαν αὐτοῦ τοιαῦτα<br>ἔργα νέων, βουλαὶ δὲ μέσων, πορδαὶ δὲ γερόντων.<br>ἐπεὶ δ’ ἐκεῖνος ἐν παιδιᾶς μέρει δεξάμενος ἐκέλευσε παρεπιγράψαι “βρονταὶ δὲ γερόντων,” καταφρονήσας τις τοῦ ἐπιεικοῦς εὔλυτον τὸ κοιλίδιον ἔχων προσέρρανε πολὺ τῇ θύρᾳ καὶ τῷ τοίχῳ νύκτωρ παριὼν τὴν οἰκίαν· ὁ δὲ τῆς στάσεως κατηγορῶν ἐν ἐκκλησίᾳ “τὴν νόσον τῆς πόλεως” ἔφη “καὶ τὴν καχεξίαν πολλαχόθεν σκοπεῖν ἔξεστι, καὶ δὴ καὶ ἐκ τῶν διαχωρημάτων.” οὗτοι μὲν στωικοὶ ἄνδρες· ἀκαδημαϊκὸς δὲ Νέστωρ ὁ καθ’ ἡμᾶς, ὁ Μαρκέλλου καθηγησάμενος τοῦ Ὀκταουίας παιδός, τῆς Καίσαρος ἀδελφῆς. καὶ οὗτος δὲ προέστη τῆς πολιτείας διαδεξάμενος τὸν Ἀθηνόδωρον, καὶ διετέλεσε τιμώμενος παρά τε τοῖς ἡγεμόσι καὶ ἐν τῇ πόλει.", "st": "14.5.14"}, {"sp": "N", "t": "τῶν δ’ ἄλλων φιλοσόφων<br>οὕς κεν ἐὺ γνοίην καί τ’ οὔνομα μυθησαίμην,<br>Πλουτιάδης τε ἐγένετο καὶ Διογένης τῶν περιπολιζόντων καὶ σχολὰς διατιθεμένων εὐφυῶς· ὁ δὲ Διογένης καὶ ποιήματα ὥσπερ ἀπεφοίβαζε τεθείσης ὑποθέσεως, τραγικὰ ὡς ἐπὶ πολύ· γραμματικοὶ δὲ ὧν καὶ συγγράμματα ἔστιν, Ἀρτεμίδωρός τε καὶ Διόδωρος· ποιητὴς δὲ τραγῳδίας ἄριστος τῶν τῆς Πλειάδος καταριθμουμένων Διονυσίδης. μάλιστα δ’ ἡ Ῥώμη δύναται διδάσκειν τὸ πλῆθος τῶν ἐκ τῆσδε τῆς πόλεως φιλολόγων· Ταρσέων γὰρ καὶ Ἀλεξανδρέων ἐστὶ μεστή. τοιαύτη μὲν ἡ Ταρσός.", "st": "14.5.15"}, {"sp": "N", "t": "μετὰ δὲ τὸν Κύδνον ὁ Πύραμος ἐκ τῆς Καταονίας ῥέων, οὗπερ καὶ πρότερον ἐμνήσθημεν· φησὶ δ’ Ἀρτεμίδωρος ἐντεῦθεν εἰς Σόλους εὐθυπλοίᾳ σταδίους εἶναι πεντακοσίους. πλησίον δὲ καὶ Μαλλὸς ἐφ’ ὕψους κειμένη, κτίσμα Ἀμφιλόχου καὶ Μόψου τοῦ Ἀπόλλωνος καὶ Μαντοῦς, περὶ ὧν πολλὰ μυθολογεῖται· καὶ δὴ καὶ ἡμεῖς ἐμνήσθημεν αὐτῶν ἐν τοῖς περὶ Κάλχαντος λόγοις καὶ τῆς ἔριδος ἣν ἤρισαν περὶ τῆς μαντικῆς ὅ τε Κάλχας καὶ ὁ Μόψος· ταύτην τε γὰρ τὴν ἔριν μεταφέρουσιν ἔνιοι, καθάπερ καὶ Σοφοκλῆς, εἰς τὴν Κιλικίαν, καλέσας ἐκεῖνος αὐτὴν Παμφυλίαν τραγικῶς, καθάπερ καὶ τὴν Λυκίαν Καρίαν καὶ τὴν Τροίαν καὶ Λυδίαν Φρυγίαν· καὶ τὸν θάνατον δὲ τοῦ Κάλχαντος ἐνταῦθα παραδιδόασιν ἄλλοι τε καὶ Σοφοκλῆς. οὐ μόνον δὲ τὴν περὶ τῆς μαντικῆς ἔριν μεμυθεύκασιν ἀλλὰ καὶ τῆς ἀρχῆς. τὸν γὰρ Μόψον φασὶ καὶ τὸν Ἀμφίλοχον ἐκ Τροίας ἐλθόντας κτίσαι Μαλλόν· εἶτ’ Ἀμφίλοχον εἰς Ἄργος ἀπελθεῖν, δυσαρεστήσαντα δὲ τοῖς ἐκεῖ πάλιν ἀναστρέψαι δεῦρο, ἀποκλειόμενον δὲ τῆς κοινωνίας συμβαλεῖν εἰς μονομαχίαν πρὸς τὸν Μόψον, πεσόντας δ’ ἀμφοτέρους ταφῆναι μὴ ἐν ἐπόψει ἀλλήλοις· καὶ νῦν οἱ τάφοι δείκνυνται περὶ Μάγαρσα τοῦ Πυράμου πλησίον. ἐντεῦθεν δ’ ἦν Κράτης ὁ γραμματικός, οὗ φησι γενέσθαι μαθητὴς Παναίτιος.", "st": "14.5.16"}, {"sp": "N", "t": "ὑπέρκειται δὲ τῆς παραλίας ταύτης Ἀλήιον πεδίον, δι’ οὗ Φιλωτᾶς διήγαγεν Ἀλεξάνδρῳ τὴν ἵππον, ἐκείνου τὴν φάλαγγα ἀγαγόντος ἐκ τῶν Σόλων διὰ τῆς παραλίας καὶ τῆς Μαλλώτιδος ἐπί τε Ἰσσὸν καὶ τὰς Δαρείου δυνάμεις. φασὶ δὲ καὶ ἐναγίσαι τῷ Ἀμφιλόχῳ τὸν Ἀλέξανδρον διὰ τὴν ἐξ Ἄργους συγγένειαν. Ἡσίοδος δ’ ἐν Σόλοις ὑπὸ Ἀπόλλωνος ἀναιρεθῆναι τὸν Ἀμφίλοχόν φησιν, οἱ δὲ περὶ τὸ Ἀλήιον πεδίον, οἱ δ’ ἐν Συρίᾳ, ἀπὸ τοῦ Ἀληίου ἀπιόντα διὰ τὴν ἔριν.", "st": "14.5.17"}, {"sp": "N", "t": "μετὰ δὲ Μαλλὸν Αἰγαῖαι πολίχνιον ὕφορμον ἔχον· εἶτ’ Ἀμανίδες πύλαι ὕφορμον ἔχουσαι, εἰς ἃς τελευτᾷ τὸ Ἀμανὸν ὄρος ἀπὸ τοῦ Ταύρου καθῆκον, ὃ τῆς Κιλικίας ὑπέρκειται κατὰ τὸ πρὸς ἕω μέρος, ἀεὶ μὲν ὑπὸ πλειόνων δυναστευόμενον τυράννων ἐχόντων ἐρύματα· καθ’ ἡμᾶς δὲ κατέστη κύριος πάντων ἀνὴρ ἀξιόλογος καὶ βασιλεὺς ὑπὸ Ῥωμαίων ὠνομάσθη διὰ τὰς ἀνδραγαθίας Ταρκονδίμοτος, καὶ τὴν διαδοχὴν τοῖς μετ’ αὐτὸν παρέδωκε.", "st": "14.5.18"}, {"sp": "N", "t": "μετὰ δὲ Αἰγαίας Ἰσσὸς πολίχνιον ὕφορμον ἔχον καὶ ποταμὸς Πίναρος. ἐνταῦθα ὁ ἀγὼν συνέπεσεν Ἀλεξάνδρῳ καὶ Δαρείῳ· καὶ ὁ κόλπος εἴρηται Ἰσσικός· ἐν αὐτῷ δὲ πόλις Ῥωσὸς καὶ Μυρίανδρος πόλις καὶ Ἀλεξάνδρεια καὶ Νικόπολις καὶ Μοψουεστία καὶ [αἱ] πύλαι λεγόμεναι, ὅριον Κιλίκων τε καὶ Σύρων. ἐν δὲ τῇ Κιλικίᾳ ἐστὶ καὶ τὸ τῆς Σαρπηδονίας Ἀρτέμιδος ἱερὸν καὶ μαντεῖον, τοὺς δὲ χρησμοὺς ἔνθεοι προθεσπίζουσιν.", "st": "14.5.19"}, {"sp": "N", "t": "μετὰ δὲ τὴν Κιλικίαν πρώτη πόλις ἐστὶ τῶν Σύρων Σελεύκεια ἡ ἐν Πιερίᾳ, καὶ πλησίον Ὀρόντης ἐκδίδωσι ποταμός. ἔστι δ’ ἀπὸ Σελευκείας εἰς Σόλους ἐπ’ εὐθείας πλοῦς ὀλίγον ἀπολείπων τῶν χιλίων σταδίων.", "st": "14.5.20"}, {"sp": "N", "t": "τῶν δ’ ἐν Τροίᾳ Κιλίκων ὧν Ὅμηρος μέμνηται πολὺ διεστώτων ἀπὸ τῶν ἔξω τοῦ Ταύρου Κιλίκων, οἱ μὲν ἀποφαίνουσιν ἀρχηγέτας τοὺς ἐν τῇ Τροίᾳ τούτων καὶ δεικνύουσί τινας τόπους κἀνταῦθα, ὥσπερ ἐν τῇ Παμφυλίᾳ Θήβην καὶ Λυρνησσόν, οἱ δ’ ἔμπαλιν καὶ Ἀλήιόν τι πεδίον κἀκεῖ δεικνύουσι. περιωδευμένων δὲ καὶ τῶν ἔξω τοῦ Ταύρου μερῶν τῆς προειρημένης χερρονήσου, προσθετέον ἐστὶ καὶ ταῦτα.", "st": "14.5.21"}, {"sp": "N", "t": "ὁ γὰρ Ἀπολλόδωρος ἐν τοῖς περὶ νεῶν ἔτι καὶ τοιαῦτα λέγει· τοὺς γὰρ ἐκ τῆς Ἀσίας ἐπικούρους τῶν Τρώων ἅπαντας καταριθμεῖσθαί φησιν ὑπὸ τοῦ ποιητοῦ τῆς χερρονήσου κατοίκους ὄντας, ἧς ὁ στενώτατος ἰσθμός ἐστι τὸ μεταξὺ τοῦ κατὰ Σινώπην μυχοῦ καὶ Ἰσσοῦ· αἱ δ’ ἐκτὸς πλευραί φησί τριγωνοειδοῦς οὔσης, εἰσὶ μὲν ἄνισοι, παρήκουσι δὲ ἡ μὲν ἀπὸ Κιλικίας ἐπὶ Χελιδονίας, ἡ δ’ ἐνθένδε ἐπὶ τὸ στόμα τοῦ Εὐξείνου, ἡ δ’ ἐπὶ Σινώπην πάλιν ἐνθένδε. τὸ μὲν οὖν μόνους τοὺς ἐν τῇ χερρονήσῳ διὰ τῶν αὐτῶν ἐλέγχοιτ’ ἂν ψεῦδος ὂν δι’ ὧν ἠλέγξαμεν πρότερον μὴ μόνους τοὺς ἐντὸς Ἅλυος. οἱ γὰρ περὶ Φαρνακίαν τόποι ἐν οἷς τοὺς Ἁλιζώνους ἔφαμεν, ὥσπερ ἔξω τοῦ Ἅλυός εἰσιν, οὕτω καὶ ἔξω τοῦ ἰσθμοῦ, εἴπερ καὶ τῶν στενῶν τῶν μεταξὺ Σινώπης καὶ Ἰσσοῦ, καὶ οὐ τούτων γε μόνων ἀλλὰ καὶ τῶν κατ’ ἀλήθειαν στενῶν τῶν μεταξὺ Ἀμισοῦ τε καὶ Ἰσσοῦ· οὐδὲ γὰρ ἐκεῖνος ὀρθῶς ἀφώρισται τὸν ἰσθμὸν καὶ τὰ κατ’ αὐτὸν στενά, ἐκεῖνα ἀντὶ τούτων τιθείς. πάντων δ’ εὐηθέστατον τὸ τὴν χερρόνησον τριγωνοειδῆ φήσαντα τρεῖς ἀποφήνασθαι τὰς ἔξω πλευράς· ὁ γὰρ τὰς ἔξω λέγων πλευρὰς ἔοικεν ὑπεξαιρουμένῳ τὴν κατὰ τὰ στενά, ὡς καὶ ταύτην οὖσαν πλευράν, οὐκ ἔξω δὲ οὐδ’ ἐπὶ θαλάττῃ. εἰ μὲν τοίνυν τὰ στενὰ ταῦτα οὕτως ἦν συνηγμένα ὥστε μικρὸν ἀπολείπειν τοῦ συνάπτειν ἐπ’ ἀλλήλαις τήν τε ἐπὶ Ἰσσὸν καὶ τὴν ἐπὶ Σινώπην πίπτουσαν πλευράν, συνεχώρει ἂν τριγωνοειδῆ λέγεσθαι τὴν χερρόνησον· νῦν δέ γε τρισχιλίους σταδίους ἀπολειπόντων μεταξὺ τῶν ὑπ’ αὐτοῦ λεγομένων στενῶν, ἀμαθία τὸ λέγειν τριγωνοειδὲς τὸ τοιοῦτον τετράπλευρον, οὐδὲ χωρογραφικόν. ὁ δὲ καὶ χωρογραφίαν ἐξέδωκεν ἐν κωμικῷ μέτρῳ γῆς περίοδον ἐπιγράψας. μένει δ’ ἡ αὐτὴ ἀμαθία κἂν εἰς τοὐλάχιστον καταγάγῃ διάστημά τις τὸν ἰσθμόν, ὅσον εἰρήκασιν οἱ πλεῖστον ψευσάμενοι τὸ ἥμισυ τοῦ παντός, ὅσον εἴρηκε καὶ Ἀρτεμίδωρος, χιλίους καὶ πεντακοσίους σταδίους· οὐδὲ γὰρ τοῦτο συναγωγήν πω τριγωνοειδοῦς ποιεῖ σχήματος. ἀλλ’ οὐδὲ τὰς πλευρὰς ὀρθῶς διῄρηται τὰς ἔξω τὴν ἀπὸ Ἰσσοῦ μέχρι Χελιδονίων εἰπών· λοιπὴ γάρ ἐστιν ὅλη ἐπ’ εὐθείας ἡ Λυκιακὴ παραλία ταύτῃ, καὶ ἡ τῶν Ῥοδίων περαία μέχρι Φύσκου· ἐντεῦθεν δὲ καμπὴν λαβοῦσα ἡ ἤπειρος ἄρχεται τὴν δευτέραν καὶ δυσμικὴν ποιεῖν πλευρὰν ἄχρι Προποντίδος καὶ Βυζαντίου.", "st": "14.5.22"}, {"sp": "N", "t": "φήσαντος δὲ τοῦ Ἐφόρου διότι τὴν χερρόνησον κατοικεῖ ταύτην ἑκκαίδεκα γένη, τρία μὲν Ἑλληνικὰ τὰ δὲ λοιπὰ βάρβαρα χωρὶς τῶν μιγάδων, ἐπὶ θαλάττῃ μὲν Κίλικες καὶ Πάμφυλοι καὶ Λύκιοι καὶ Βιθυνοὶ καὶ Παφλαγόνες καὶ Μαριανδυνοὶ καὶ Τρῶες καὶ Κᾶρες, Πισίδαι δὲ καὶ Μυσοὶ καὶ Χάλυβες καὶ Φρύγες καὶ Μιλύαι ἐν τῇ μεσογαίᾳ, διαιτῶν ταῦτα ὁ Ἀπολλόδωρος ἑπτακαιδέκατόν φησιν εἶναι τὸ τῶν Γαλατῶν, ὃ νεώτερόν ἐστι τοῦ Ἐφόρου, τῶν δ’ εἰρημένων τὰ μὲν Ἑλληνικὰ μήπω κατὰ τὰ Τρωικὰ κατῳκίσθαι, τὰ δὲ βάρβαρα πολλὴν ἔχειν σύγχυσιν διὰ τὸν χρόνον· καταλέγεσθαι δ’ ὑπὸ τοῦ ποιητοῦ τό τε τῶν Τρώων καὶ τῶν νῦν ὀνομαζομένων Παφλαγόνων καὶ Μυσῶν καὶ Φρυγῶν καὶ Καρῶν καὶ Λυκίων, Μῄονάς [τε] ἀντὶ Λυδῶν καὶ ἄλλους ἀγνῶτας, οἷον Ἁλιζῶνας καὶ Καύκωνας· ἐκτὸς δὲ τοῦ καταλόγου Κητείους τε καὶ Σολύμους καὶ Κίλικας τοὺς ἐκ Θήβης πεδίου καὶ Λέλεγας· Παμφύλους δὲ καὶ Βιθυνοὺς καὶ Μαριανδυνοὺς καὶ Πισίδας καὶ Χάλυβας καὶ Μιλύας καὶ Καππάδοκας μηδ’ ὠνομάσθαι, τοὺς μὲν διὰ τὸ μηδέπω τοὺς τόπους κατῳκηκέναι τούτους, τοὺς δὲ διὰ τὸ ἑτέροις γένεσι περιέχεσθαι, ὡς Ἰδριεῖς μὲν καὶ Τερμίλαι Καρσί, Δολίονες δὲ καὶ Βέβρυκες Φρυξί.", "st": "14.5.23"}, {"sp": "N", "t": "φαίνεται δ’ οὔτε τοῦ Ἐφόρου τὴν ἀπόφασιν διαιτῶν ἱκανῶς τά τε τοῦ ποιητοῦ ταράττων καὶ καταψευδόμενος. Ἐφόρου τε γὰρ τοῦτο πρῶτον ἀπαιτεῖν ἐχρῆν, τί δὴ τοὺς Χάλυβας τίθησιν ἐντὸς τῆς χερρονήσου τοσοῦτον ἀφεστῶτας καὶ Σινώπης καὶ Ἀμισοῦ πρὸς ἕω; οἱ γὰρ λέγοντες τὸν ἰσθμὸν τῆς χερρονήσου ταύτης τὴν ἀπὸ Ἰσσοῦ γραμμὴν ἐπὶ τὸν Εὔξεινον, ὡς ἂν μεσημβρινήν τινα τιθέασι ταύτην, [ἣν] οἱ μὲν εἶναι νομίζουσι τὴν ἐπὶ Σινώπης οἱ δὲ τὴν ἐπ’ Ἀμισοῦ, ἐπὶ δὲ τῶν Χαλύβων οὐδείς· λοξὴ γάρ ἐστι τελέως. ὁ γὰρ δὴ διὰ Χαλύβων μεσημβρινὸς διὰ τῆς μικρᾶς Ἀρμενίας γράφοιτ’ ἂν καὶ τοῦ Εὐφράτου τὴν Καππαδοκίαν ὅλην ἐντὸς ἀπολαμβάνων καὶ τὴν Κομμαγηνὴν καὶ τὸν Ἀμανὸν καὶ τὸν Ἰσσικὸν κόλπον. εἰ δ’ οὖν καὶ τὴν λοξὴν γραμμὴν ὁρίζειν τὸν ἰσθμὸν συγχωρήσαιμεν, τὰ πλεῖστά γε τούτων καὶ μάλιστα ἡ Καππαδοκία ἐντὸς ἀπολαμβάνοιτ’ ἂν καὶ ὁ νῦν ἰδίως λεγόμενος Πόντος τῆς Καππαδοκίας μέρος ὢν τὸ πρὸς τῷ Εὐξείνῳ, ὥστ’ εἰ τοὺς Χάλυβας τῆς χερρονήσου θετέον μέρος, πολὺ μᾶλλον τοὺς Κατάονας καὶ Καππάδοκας ἀμφοτέρους καὶ Λυκάονας δέ, οὓς καὶ αὐτοὺς παρῆκε. διὰ τί δ’ ἐν τοῖς μεσογαίοις ἔταξε τοὺς Χάλυβας, οὓς ὁ ποιητὴς Ἁλιζῶνας ἐκάλεσεν, ὥσπερ καὶ ἡμεῖς ἀπεδείξαμεν; ἄμεινον γὰρ ἦν διελεῖν καὶ τοὺς μὲν ἐπὶ τῇ θαλάττῃ φάναι τοὺς δὲ ἐν τῇ μεσογαίᾳ· ὅπερ καὶ ἐπὶ τῆς Καππαδοκίας ποιητέον καὶ τῆς Κιλικίας. ὁ δὲ τὴν μὲν οὐδ’ ὠνόμακε, τοὺς Κίλικας δὲ τοὺς ἐπὶ τῇ θαλάττῃ μόνον εἴρηκεν. οἱ οὖν ἐπ’ Ἀντιπάτρῳ τῷ Δερβήτῃ καὶ οἱ Ὁμοναδεῖς καὶ ἄλλοι πλείους οἱ συνάπτοντες τοῖς Πισίδαις,<br>οἳ οὐκ ἴσασι θάλατταν<br>ἀνέρες, οὐδέ θ’ ἅλεσσι μεμιγμένον εἶδαρ ἔδουσι<br>τίνα λάβωσι τάξιν; ἀλλ’ οὐδὲ Λυδοὺς οὐδὲ Μῄονας εἴρηκεν, εἴτε δύο εἴθ’ οἱ αὐτοί εἰσι, καὶ εἴτε καθ’ ἑαυτοὺς εἴτ’ ἐν ἑτέρῳ γένει περιεχομένους. οὕτω γὰρ ἐπίσημον ἔθνος οὐκ ἀποκρύψαι δυνατόν, ὅ τε μὴ λέγων περὶ αὐτοῦ μηδὲν οὐκ ἂν δόξειε παραλιπεῖν τι τῶν κυριωτάτων;", "st": "14.5.24"}, {"sp": "N", "t": "τίνες δ’ εἰσὶν οἱ μιγάδες; οὐ γὰρ ἂν ἔχοιμεν εἰπεῖν παρὰ τοὺς λεχθέντας τόπους ἢ ὠνομάσθαι ὑπ’ αὐτοῦ ἢ παραλελεῖφθαι ἄλλους οὓς ἀποδώσομεν τοῖς μιγάσιν, οὐδέ γε αὐτῶν τινας τούτων ὧν ἢ εἶπεν ἢ παρέλιπε. καὶ γὰρ εἰ κατεμίχθησαν, ἀλλ’ ἡ ἐπικράτεια πεποίηκεν ἢ Ἕλληνας ἢ βαρβάρους· τρίτον δὲ γένος οὐδὲν ἴσμεν τὸ μικτόν.", "st": "14.5.25"}, {"sp": "N", "t": "πῶς δὲ τρία γένη τῶν Ἑλλήνων ἐστὶ τὰ τὴν χερρόνησον οἰκοῦντα; εἰ γάρ, ὅτι τὸ παλαιὸν οἱ αὐτοὶ ἦσαν Ἴωνες καὶ Ἀθηναῖοι. λεγέσθωσαν καὶ οἱ Δωριεῖς καὶ οἱ Αἰολεῖς οἱ αὐτοί, ὥστε δύο ἔθνη γίνοιτ’ ἄν· εἰ δὲ διαιρετέον κατὰ τὰ ὕστερα ἔθη, καθάπερ καὶ τὰς διαλέκτους, τέτταρα ἂν εἴη καὶ τὰ ἔθνη, καθάπερ καὶ αἱ διάλεκτοι. οἰκοῦσι δὲ τὴν χερρόνησον ταύτην, καὶ μάλιστα κατὰ τὸν τοῦ Ἐφόρου διορισμόν, οὐκ Ἴωνες μόνον ἀλλὰ καὶ Ἀθηναῖοι, καθάπερ ἐν τοῖς καθ’ ἕκαστα δεδήλωται. τοιαῦτα μὲν δὴ πρὸς τὸν Ἔφορον διαπορεῖν ἄξιον· Ἀπολλόδωρος δὲ τούτων μὲν ἐφρόντισεν οὐδέν, τοῖς δὲ ἑκκαίδεκα ἔθνεσι προστίθησιν ἑπτακαιδέκατον, τὸ τῶν Γαλατῶν, ἄλλως μὲν χρήσιμον λεχθῆναι, πρὸς δὲ τὴν δίαιταν τῶν ὑπὸ τοῦ Ἐφόρου λεγομένων ἢ παραλειπομένων οὐ δέον· εἴρηκε δὲ τὴν αἰτίαν αὐτός, ὅτι ταῦτα πάντα νεώτερα τῆς ἐκείνου ἡλικίας.", "st": "14.5.26"}, {"sp": "N", "t": "μεταβὰς δ’ ἐπὶ τὸν ποιητὴν τοῦτο μὲν ὀρθῶς λέγει, διότι πολλὴ σύγχυσις γεγένηται τῶν βαρβάρων ἐθνῶν ἀπὸ τῶν Τρωικῶν εἰς τὰ νῦν διὰ τὰς μεταπτώσεις· καὶ γὰρ προσγέγονέ τινα καὶ ἐλλέλοιπε καὶ διέσπασται καὶ συνῆκται εἰς ἕν. οὐκ εὖ δὲ τὴν αἰτίαν διττὴν ἀποφαίνει δι’ ἣν οὐ μέμνηταί τινων ὁ ποιητής· ἢ τῷ μήπω τότ’ οἰκεῖσθαι ὑπὸ τοῦ ἔθνους τούτου, ἢ τῷ ἐν ἑτέρῳ γένει περιέχεσθαι. τὴν γὰρ Καππαδοκίαν οὐκ εἴρηκεν, οὐδὲ τὴν Καταονίαν, ὡς δ’ αὕτως τὴν Λυκαονίαν, δι’ οὐδέτερον τούτων· οὐ γὰρ ἔχομεν τοιαύτην ἱστορίαν ἐπ’ αὐτῶν οὐδεμίαν. γελοῖόν τε τὸ τοὺς Καππάδοκας καὶ Λυκάονας διὰ τί μὲν Ὅμηρος παρέλιπε φροντίσαι καὶ ἀπολογήσασθαι, διὰ τί δ’ Ἔφορος παρῆλθε παρελθεῖν καὶ αὐτόν, καὶ ταῦτα παραθέμενον πρὸς αὐτὸ τοῦτο τὴν ἀπόφασιν τἀνδρός, πρὸς τὸ ἐξετάσαι καὶ διαιτῆσαι· καὶ διότι μὲν Μῄονας ἀντὶ Λυδῶν Ὅμηρος εἶπε διδάξαι, ὅτι δ’ οὔτε Λυδοὺς οὔτε Μῄονας εἴρηκεν Ἔφορος μὴ ἐπισημήνασθαι.", "st": "14.5.27"}, {"sp": "N", "t": "φήσας δὲ ἀγνώτων τινῶν μεμνῆσθαι τὸν ποιητήν, Καύκωνας μὲν ὀρθῶς λέγει καὶ Σολύμους καὶ Κητείους καὶ Λέλεγας καὶ Κίλικας τοὺς ἐκ Θήβης πεδίου, τοὺς δ’ Ἁλιζῶνας αὐτὸς πλάττει, μᾶλλον δ’ οἱ πρῶτοι τοὺς Ἁλιζῶνας ἀγνοήσαντες τίνες εἰσί, καὶ μεταγράφοντες πλεοναχῶς καὶ πλάττοντες τὴν τοῦ ἀργύρου γενέθλην καὶ ἄλλα πολλὰ μέταλλα, ἐκλελειμμένα ἅπαντα. πρὸς ταύτην δὲ τὴν φιλοτιμίαν κἀκείνας συνήγαγον τὰς ἱστορίας, ἃς ὁ Σκήψιος τίθησι παρὰ Καλλισθένους λαβὼν καὶ ἄλλων τινῶν, οὐ καθαρευόντων τῆς περὶ τῶν Ἁλιζώνων ψευδοδοξίας· ὡς ὁ μὲν Ταντάλου πλοῦτος καὶ τῶν Πελοπιδῶν ἀπὸ τῶν περὶ Φρυγίαν καὶ Σίπυλον μετάλλων ἐγένετο· ὁ δὲ Κάδμου [ἐκ τῶν] περὶ Θρᾴκην καὶ τὸ Παγγαῖον ὄρος· ὁ δὲ Πριάμου ἐκ τῶν ἐν Ἀστύροις περὶ Ἄβυδον χρυσείων, ὧν καὶ νῦν ἔτι μικρὰ λείπεται· πολλὴ δ’ ἡ ἐκβολὴ καὶ τὰ ὀρύγματα σημεῖα τῆς πάλαι μεταλλείας· ὁ δὲ Μίδου ἐκ τῶν περὶ τὸ Βέρμιον ὄρος· ὁ δὲ Γύγου καὶ Ἀλυάττου καὶ Κροίσου ἀπὸ τῶν ἐν Λυδίᾳ καὶ τῆς μεταξὺ Ἀταρνέως τε καὶ Περγάμου πολίχνη ἐρήμη ἐκμεμεταλλευμένα ἔχουσα τὰ χωρία.", "st": "14.5.28"}, {"sp": "N", "t": "ἔτι καὶ ταῦτα μέμψαιτο ἄν τις τοῦ Ἀπολλοδώρου, ὅτι τῶν νεωτέρων καινοτομούντων πολλὰ παρὰ τὰς Ὁμηρικὰς ἀποφάσεις, εἰωθὼς ταῦτ’ ἐλέγχειν ἐπὶ πλέον, ἐνταῦθα οὐκ ὠλιγώρηκε μόνον, ἀλλὰ καὶ τἀναντία εἰς ἓν συνάγει τὰ μὴ ὡσαύτως λεγόμενα. ὁ μὲν γὰρ Ξάνθος ὁ Λυδὸς μετὰ τὰ Τρωικά φησιν ἐλθεῖν τοὺς Φρύγας ἐκ τῆς Εὐρώπης καὶ τῶν ἀριστερῶν τοῦ Πόντου, ἀγαγεῖν δ’ αὐτοὺς Σκαμάνδριον ἐκ Βερεκύντων καὶ Ἀσκανίας. ἐπιλέγει δὲ τούτοις ὁ Ἀπολλόδωρος, ὅτι τῆς Ἀσκανίας ταύτης μνημονεύει καὶ Ὅμηρος ἧς ὁ Ξάνθος<br>Φόρκυς δὲ Φρύγας ἦγε καὶ Ἀσκάνιος θεοειδὴς<br>τῆλ’ ἐξ Ἀσκανίης.<br>ἀλλ’ εἰ οὕτως ἔχει, ἡ μὲν μετανάστασις ὕστερον ἂν εἴη τῶν Τρωικῶν γεγονυῖα, ἐν δὲ τοῖς Τρωικοῖς τὸ λεγόμενον ὑπὸ τοῦ ποιητοῦ ἐπικουρικὸν ἧκεν ἐκ τῆς περαίας ἐκ τῶν Βερεκύντων καὶ τῆς Ἀσκανίας. τίνες οὖν Φρύγες ἦσαν<br>οἵ ῥα τότ’ ἐστρατόωντο παρ’ ὄχθας Σαγγαρίοιο,<br>ὅτε ὁ Πρίαμος<br>ἐπίκουρος ἐὼν μετὰ τοῖσιν ἐλέγμην<br>φησί; πῶς δὲ ἐκ μὲν Βερεκύντων μετεπέμπετο Φρύγας ὁ Πρίαμος, πρὸς οὓς οὐδὲν ἦν αὐτῷ συμβόλαιον, τοὺς δ’ ὁμόρους καὶ οἷς αὐτὸς πρότερον ἐπεκούρησε παρέλιπεν; οὕτω δὲ περὶ τῶν Φρυγῶν εἰπὼν ἐπιφέρει καὶ τὰ περὶ τῶν Μυσῶν οὐχ ὁμολογούμενα τούτοις· λέγεσθαι γάρ φησι καὶ τῆς Μυσίας κώμην Ἀσκανίαν περὶ λίμνην ὁμώνυμον, ἐξ ἧς καὶ τὸν Ἀσκάνιον ποταμὸν ῥεῖν, οὗ μνημονεύει καὶ Εὐφορίων<br>Μυσοῖος παρ’ ὕδασιν Ἀσκανίοιο.<br>καὶ ὁ Αἰτωλὸς Ἀλέξανδρος<br>οἳ καὶ ἐπ’ Ἀσκανίῳ δώματ’ ἔχουσι ῥόῳ,<br>λίμνης Ἀσκανίης ἐπὶ χείλεσιν· ἔνθα Δολίων<br>υἱὸς Σιληνοῦ νάσσατο καὶ Μελίης.<br>καλοῦσι δέ, φησί, Δολιονίδα καὶ Μυσίαν τὴν περὶ Κύζικον ἰόντι εἰς Μιλητούπολιν. εἰ οὖν οὕτως ἔχει ταῦτα, καὶ ἐκμαρτυρεῖται ὑπὸ τῶν δεικνυμένων νῦν καὶ ὑπὸ τῶν ποιητῶν, τί ἐκώλυε τὸν Ὅμηρον ταύτης μεμνῆσθαι τῆς Ἀσκανίας, ἀλλὰ μὴ τῆς ὑπὸ Ξάνθου λεγομένης; εἴρηται δὲ καὶ πρότερον περὶ τούτων ἐν τῷ περὶ Μυσῶν καὶ Φρυγῶν λόγῳ, ὥστε ἐχέτω πέρας.", "st": "14.5.29"}, {"sp": "N", "t": "λοιπὸν δὲ τὴν πρὸς νότου παρακειμένην τῇ χερρονήσῳ ταύτῃ περιοδεῦσαι νῆσον τὴν Κύπρον. εἴρηται δ’ ὅτι ἡ περιεχομένη θάλαττα ὑπὸ τῆς Αἰγύπτου καὶ Φοινίκης καὶ Συρίας καὶ τῆς λοιπῆς παραλίας μέχρι τῆς Ῥοδίας σύνθετός πώς ἐστιν ἔκ τε τοῦ Αἰγυπτίου πελάγους καὶ τοῦ Παμφυλίου καὶ τοῦ κατὰ τὸν Ἰσσικὸν κόλπον. ἐν δὲ ταύτῃ ἐστὶν ἡ Κύπρος, τὰ μὲν προσάρκτια μέρη συνάπτοντα ἔχουσα τῇ Τραχείᾳ Κιλικίᾳ, καθ’ ἃ δὴ καὶ προσεχεστάτη τῇ ἠπείρῳ ἐστί, τὰ δὲ ἑῷα τῷ Ἰσσικῷ κόλπῳ, τὰ δ’ ἑσπέρια τῷ Παμφυλίῳ κλυζόμενα πελάγει, τὰ δὲ νότια τῷ Αἰγυπτίῳ. τοῦτο μὲν οὖν σύρρουν ἐστὶν ἀπὸ τῆς ἑσπέρας τῷ Λιβυκῷ καὶ τῷ Καρπαθίῳ πελάγει, ἀπὸ δὲ τῶν νοτίων καὶ τῶν ἑῴων μερῶν ἥ τε Αἴγυπτός ἐστι καὶ ἡ ἐφεξῆς παραλία μέχρι Σελευκείας τε καὶ Ἰσσοῦ, πρὸς ἄρκτον δ’ ἥ τε Κύπρος καὶ τὸ Παμφύλιον πέλαγος. τοῦτο δὲ ἀπὸ μὲν τῶν ἄρκτων περιέχεται τοῖς τε ἄκρος τῆς Τραχείας Κιλικίας καὶ τῆς Παμφυλίας καὶ Λυκίας μέχρι τῆς Ῥοδίας, ἀπὸ δὲ τῆς δύσεως τῇ Ῥοδίων νήσῳ, ἀπὸ δὲ τῆς ἀνατολῆς τῇ Κύπρῳ τῇ κατὰ Πάφον καὶ τὸν Ἀκάμαντα, ἀπὸ δὲ τῆς μεσημβρίας σύρρουν ἐστὶ τῷ Αἰγυπτίῳ πελάγει.", "st": "14.6.1"}, {"sp": "N", "t": "ἔστι δ’ ὁ μὲν κύκλος τῆς Κύπρου σταδίων τρισχιλίων καὶ τετρακοσίων εἴκοσι κατακολπίζοντι· μῆκος δὲ ἀπὸ Κλειδῶν ἐπὶ τὸν Ἀκάμαντα πεζῇ σταδίων χιλίων τετρακοσίων ὁδεύοντι ἀπ’ ἀνατολῆς ἐπὶ δύσιν. εἰσὶ δὲ αἱ μὲν Κλεῖδες νησία δύο προσκείμενα τῇ Κύπρῳ κατὰ τὰ ἑωθινὰ μέρη τῆς νήσου, τὰ διέχοντα τοῦ Πυράμου σταδίους ἑπτακοσίους· ὁ δ’ Ἀκάμας ἐστὶν ἄκρα δύο μαστοὺς ἔχουσα καὶ ὕλην πολλήν, κείμενος μὲν ἐπὶ τῶν ἑσπερίων τῆς νήσου μερῶν, ἀνατείνων δὲ πρὸς ἄρκτους, ἐγγυτάτω μὲν πρὸς Σελινοῦντα τῆς Τραχείας Κιλικίας ἐν διάρματι χιλίων σταδίων, πρὸς Σίδην δὲ τῆς Παμφυλίας χιλίων καὶ ἑξακοσίων, πρὸς δὲ Χελιδονίας χιλίων ἐνακοσίων. ἔστι δὲ ἑτερόμηκες τὸ ὅλον τῆς νήσου σχῆμα, καί που καὶ ἰσθμοὺς ποιεῖ κατὰ τὰς τὸ πλάτος διοριζούσας πλευράς· ἔχει δὲ καὶ τὰ καθ’ ἕκαστα ὡς ἐν βραχέσιν εἰπεῖν οὕτως, ἀρξαμένοις ἀπὸ τοῦ προσεχεστάτου σημείου τῇ ἠπείρῳ.", "st": "14.6.2"}, {"sp": "N", "t": "ἔφαμεν δέ που κατὰ τὸ Ἀνεμούριον ἄκραν τῆς Τραχείας Κιλικίας ἀντικεῖσθαι τὸ τῶν Κυπρίων ἀκρωτήριον τὴν Κρομμύου ἄκραν ἐν τριακοσίοις καὶ πεντήκοντα σταδίοις· ἐντεῦθεν δ’ ἤδη δεξιὰν τὴν νῆσον ἔχουσιν, ἐν ἀριστερᾷ δὲ τὴν ἤπειρον, πρὸς ἄρκτον ὁ πλοῦς ἐστι καὶ πρὸς ἕω καὶ πρὸς τὰς Κλεῖδας εὐθυπλοίᾳ σταδίων ἑπτακοσίων. ἐν δὲ τῷ μεταξὺ Λάπαθός τέ ἐστι πόλις ὕφορμον ἔχουσα καὶ νεώρια, Λακώνων κτίσμα καὶ Πραξάνδρου, καθ’ ἣν ἡ Νάγιδος· εἶτ’ Ἀφροδίσιον, καθ’ ὃ στενὴ ἡ νῆσος· εἰς γὰρ Σαλαμῖνα ὑπέρβασις σταδίων ἑβδομήκοντα· εἶτ’ Ἀχαιῶν ἀκτή, ὅπου Τεῦκρος προσωρμίσθη πρῶτον ὁ κτίσας Σαλαμῖνα τὴν ἐν Κύπρῳ, ἐκβληθείς, ὥς φασιν, ὑπὸ τοῦ πατρὸς Τελαμῶνος· εἶτα Καρπασία πόλις λιμένα ἔχουσα, κεῖται δὲ κατὰ τὴν ἄκραν τὴν Σαρπηδόνα· ἐκ δὲ τῆς Καρπασίας ὑπέρβασίς ἐστιν ἰσθμοῦ τριάκοντα σταδίων πρὸς τὰς νήσους τὰς Καρπασίας καὶ τὸ νότιον πέλαγος· εἶτ’ ἄκρα καὶ ὄρος· ἡ δ’ ἀκρώρεια καλεῖται Ὄλυμπος, ἔχουσα Ἀφροδίτης Ἀκραίας ναόν, ἄδυτον γυναιξὶ καὶ ἀόρατον. πρόκεινται δὲ πλησίον αἱ Κλεῖδες καὶ ἄλλαι δὲ πλείους, εἶθ’ αἱ Καρπασίαι νῆσοι, καὶ μετὰ ταῦτα ἡ Σαλαμίς, ὅθεν ἦν Ἄριστος ὁ συγγραφεύς· εἶτ’ Ἀρσινόη πόλις καὶ λιμήν· εἶτ’ ἄλλος λιμὴν Λεύκολλα· εἶτ’ ἄκρα Πηδάλιον, ἧς ὑπέρκειται λόφος τραχὺς ὑψηλὸς τραπεζοειδής, ἱερὸς Ἀφροδίτης, εἰς ὃν ἀπὸ Κλειδῶν στάδιοι ἑξακόσιοι ὀγδοήκοντα· εἶτα κολπώδης καὶ τραχὺς παράπλους ὁ πλείων εἰς Κίτιον … ἔχει δὲ λιμένα κλειστόν· ἐντεῦθέν ἐστι Ζήνων τε ὁ τῆς στωικῆς αἱρέσεως ἀρχηγέτης καὶ Ἀπολλώνιος ἰατρός· ἐντεῦθεν εἰς Βηρυτὸν στάδιοι χίλιοι πεντακόσιοι. εἶτ’ Ἀμαθοῦς πόλις καὶ μεταξὺ πολίχνη Παλαιὰ καλουμένη, καὶ ὄρος μαστοειδὲς Ὄλυμπος· εἶτα Κουριὰς [ἄκρα] χερρονησώδης, εἰς ἣν ἀπὸ Θρόνων στάδιοι ἑπτακόσιοι. εἶτα πόλις Κούριον ὅρμον ἔχουσα, Ἀργείων κτίσμα. ἤδη οὖν πάρεστι σκοπεῖν τὴν ῥᾳθυμίαν τοῦ ποιήσαντος τὸ ἐλεγεῖον τοῦτο οὗ ἡ ἀρχή<br>ἱραὶ τῷ Φοίβῳ, πολλὸν διὰ κῦμα θέουσαι,<br>ἤλθομεν αἱ ταχιναὶ τόξα φυγεῖν ἔλαφοι,<br>εἴθ’ Ἡδύλος ἐστὶν εἴθ’ ὁστισοῦν· φησὶ μὲν γὰρ ὁρμηθῆναι τὰς ἐλάφους Κωρυκίης ἀπὸ δειράδος, ἐκ δὲ Κιλίσσης ᾐόνος εἰς ἀκτὰς διανήξασθαι Κουριάδας, καὶ ἐπιφθέγγεται διότι<br>μυρίον ἀνδράσι θαῦμα νοεῖν πάρα, πῶς ἀνόδευτον<br>χεῦμα δί’ εἰαρινῷ ἐδράμομεν ζεφύρῳ<br>ἀπὸ γὰρ Κωρύκου περίπλους μέν ἐστιν εἰς Κουριάδα ἀκτήν, οὐ ζεφύρῳ δὲ οὔτε ἐν δεξιᾷ ἔχοντι τὴν νῆσον οὔτ’ ἐν ἀριστερᾷ, δίαρμα δ’ οὐδέν. ἀρχὴ δ’ οὖν τοῦ δυσμικοῦ παράπλου τὸ Κούριον τοῦ βλέποντος πρὸς Ῥόδον, καὶ εὐθύς ἐστιν ἄκρα ἀφ’ ἧς ῥίπτουσι τοὺς ἁψαμένους τοῦ βωμοῦ τοῦ Ἀπόλλωνος· εἶτα Τρήτα καὶ Βοόσουρα καὶ Παλαίπαφος, ὅσον ἐν δέκα σταδίοις ὑπὲρ τῆς θαλάττης ἱδρυμένη, ὕφορμον ἔχουσα καὶ ἱερὸν ἀρχαῖον τῆς Παφίας Ἀφροδίτης· εἶτ’ ἄκρα Ζεφυρία πρόσορμον ἔχουσα, καὶ ἄλλη Ἀρσινόη ὁμοίως πρόσορμον ἔχουσα καὶ ἱερὸν καὶ ἄλσος· μικρὸν δ’ ἀπὸ τῆς θαλάττης καὶ ἡ Ἱεροκηπία. εἶθ’ ἡ Πάφος, κτίσμα Ἀγαπήνορος καὶ λιμένα ἔχουσα καὶ ἱερὰ εὖ κατεσκευασμένα· διέχει δὲ πεζῇ σταδίους ἑξήκοντα τῆς Παλαιπάφου, καὶ πανηγυρίζουσι διὰ τῆς ὁδοῦ ταύτης κατ’ ἔτος ἐπὶ τὴν Παλαίπαφον ἄνδρες ὁμοῦ γυναιξὶν συνιόντες καὶ ἐκ τῶν ἄλλων πόλεων. φασὶ δ’ εἰς Ἀλεξάνδρειάν τινες ἐκ Πάφου σταδίους εἶναι τρισχιλίους ἑξακοσίους. εἶθ’ ὁ Ἀκάμας ἐστὶ μετὰ Πάφον· εἶτα πρὸς ἕω μετὰ τὸν Ἀκάμαντα πλοῦς εἰς Ἀρσινόην πόλιν καὶ τὸ τοῦ Διὸς ἄλσος· εἶτα Σόλοι πόλις λιμένα ἔχουσα καὶ ποταμὸν καὶ ἱερὸν Ἀφροδίτης καὶ Ἴσιδος· κτίσμα δ’ ἐστὶ Φαλήρου καὶ Ἀκάμαντος Ἀθηναίων· οἱ δ’ ἐνοικοῦντες Σόλιοι καλοῦνται. ἐντεῦθεν ἦν Στασάνωρ τῶν Ἀλεξάνδρου ἑταίρων, ἀνὴρ ἡγεμονίας ἠξιωμένος· ὑπέρκειται δ’ ἐν μεσογαίᾳ Λιμενία πόλις· εἶθ’ ἡ Κρομμύου ἄκρα.", "st": "14.6.3"}, {"sp": "N", "t": "τί δὲ δεῖ τῶν ποιητῶν θαυμάζειν, καὶ μάλιστα τῶν τοιούτων οἷς ἡ πᾶσα περὶ τὴν φράσιν ἐστὶ σπουδή, τὰ τοῦ Δαμάστου συγκρίνοντας, ὅστις τῆς νήσου τὸ μῆκος ἀπὸ τῶν ἄρκτων πρὸς μεσημβρίαν ἀποδίδωσιν, ἀπὸ Ἱεροκηπίας, ὥς φησιν, εἰς Κλεῖδας; οὐδὲ ὁ Ἐρατοσθένης εὖ· αἰτιώμενος γὰρ τοῦτον οὐκ ἀπ’ ἄρκτων φησὶν εἶναι τὴν Ἱεροκηπίαν, ἀλλ’ ἀπὸ νότου· οὐδὲ γὰρ ἀπὸ νότου, ἀλλ’ ἀπὸ δύσεως, εἴπερ ἐν τῇ δυσμικῇ πλευρᾷ κεῖται, ἐν ᾗ καὶ ἡ Πάφος καὶ ὁ Ἀκάμας.", "st": "14.6.4"}, {"sp": "N", "t": "διάκειται μὲν οὕτως ἡ Κύπρος τῇ θέσει. κατ’ ἀρετὴν δ’ οὐδεμιᾶς τῶν νήσων λείπεται· καὶ γὰρ εὔοινός ἐστι καὶ εὐέλαιος σίτῳ τε αὐτάρκει χρῆται· μέταλλά τε χαλκοῦ ἐστιν ἄφθονα τὰ ἐν Ταμασσῷ, ἐν οἷς τὸ χαλκανθὲς γίνεται καὶ ὁ ἰὸς τοῦ χαλκοῦ, πρὸς τὰς ἰατρικὰς δυνάμεις χρήσιμα. φησὶ δ’ Ἐρατοσθένης τὸ παλαιὸν ὑλομανούντων τῶν πεδίων ὥστε κατέχεσθαι δρυμοῖς καὶ μὴ γεωργεῖσθαι, μικρὰ μὲν ἐπωφελεῖν πρὸς τοῦτο τὰ μέταλλα δενδροτομούντων πρὸς τὴν καῦσιν τοῦ χαλκοῦ καὶ τοῦ ἀργύρου, προσγενέσθαι δὲ καὶ τὴν ναυπηγίαν τῶν στόλων ἤδη πλεομένης ἀδεῶς τῆς θαλάττης καὶ μετὰ δυνάμεων· ὡς δ’ οὐκ ἐξενίκων, ἐπιτρέψαι τοῖς βουλομένοις καὶ δυναμένοις ἐκκόπτειν καὶ ἔχειν ἰδιόκτητον καὶ ἀτελῆ τὴν διακαθαρθεῖσαν γῆν.", "st": "14.6.5"}, {"sp": "N", "t": "πρότερον μὲν οὖν κατὰ πόλεις ἐτυραννοῦντο οἱ Κύπριοι, ἀφ’ οὗ δ’ οἱ Πτολεμαϊκοὶ βασιλεῖς κύριοι τῆς Αἰγύπτου κατέστησαν, εἰς ἐκείνους καὶ ἡ Κύπρος περιέστη συμπραττόντων πολλάκις καὶ τῶν Ῥωμαίων. ἐπεὶ δ’ ὁ τελευταῖος ἄρξας Πτολεμαῖος, ἀδελφὸς τοῦ Κλεοπάτρας πατρὸς τῆς καθ’ ἡμᾶς βασιλίσσης, ἔδοξε πλημμελής τε εἶναι καὶ ἀχάριστος εἰς τοὺς εὐεργέτας, ἐκεῖνος μὲν κατελύθη, Ῥωμαῖοι δὲ κατέσχον τὴν νῆσον, καὶ γέγονε στρατηγικὴ ἐπαρχία καθ’ αὑτήν. μάλιστα δ’ αἴτιος τοῦ ὀλέθρου κατέστη τῷ βασιλεῖ Πόπλιος Κλαύδιος Ποῦλχερ· ἐμπεσὼν γὰρ εἰς τὰ λῃστήρια, τῶν Κιλίκων ἀκμαζόντων τότε, λύτρον αἰτούμενος ἐπέστειλε τῷ βασιλεῖ δεόμενος πέμψαι καὶ ῥύσασθαι αὐτόν· ὁ δ’ ἔπεμψε μὲν μικρὸν δὲ τελέως ὥστε καὶ τοὺς λῃστὰς αἰδεσθῆναι λαβεῖν ἀλλὰ ἀναπέμψαι πάλιν, τὸν δ’ ἄνευ λύτρων ἀπολῦσαι. σωθεὶς δ’ ἐκεῖνος ἀπεμνημόνευσεν ἀμφοτέροις τὴν χάριν, καὶ γενόμενος δήμαρχος ἴσχυσε τοσοῦτον ὥστε ἐπέμφθη Μάρκος Κάτων ἀφαιρησόμενος τὴν Κύπρον τὸν κατέχοντα. ἐκεῖνος μὲν οὖν ἔφθη διαχειρισάμενος αὑτόν, Κάτων δ’ ἐπελθὼν παρέλαβε τὴν Κύπρον καὶ τὴν βασιλικὴν οὐσίαν διέθετο καὶ τὰ χρήματα εἰς τὸ δημόσιον ταμιεῖον τῶν Ῥωμαίων ἐκόμισεν· ἐξ ἐκείνου δ’ ἐγένετο ἐπαρχία ἡ νῆσος καθάπερ καὶ νῦν ἐστι στρατηγική· ὀλίγον δὲ χρόνον τὸν μεταξὺ Ἀντώνιος Κλεοπάτρᾳ καὶ τῇ ἀδελφῇ αὐτῆς Ἀρσινόῃ παρέδωκε, καταλυθέντος δὲ ἐκείνου συγκατελύθησαν καὶ αἱ διατάξεις αὐτοῦ πᾶσαι.", "st": "14.6.6"}], []);})();
